window.CURRICULUM = {"meta":{"name":"供水学习平台 · 课程体系","version":"2.0","generatedAt":"2026-11-19","source":"data/课程采集包.xlsx","taxonomySource":"课程重设计方案 · 四大板块 × 16 子类知识坐标","audit":"全部内容待公司技术部门审核；未审定不得对外宣称正式课程","note":"本板块由课程采集包驱动生成：课程正文、知识框架、随堂题与材料锚点均从采集包读取；更新采集包后重新发布即可同步，无需改动代码。","design":"一门课＝子类(1) × 一类知识 × 精加工层 × 认知档；知识本体优先、场景后置；材料清单是锚点不是边界"},"boards":[{"id":"XG","name":"新手入门","tagline":"扫盲与底线","attr":"纯库内知识普及 + 行业常识","band":"D1–D2 为主，防呆 / 底线类到 D3–D4","rel":"知识主要来自材料库本身与行业常识，场景在库内 / 库房，条件少","subs":[{"id":"XG-01","name":"供水系统与材料图谱认知","band":"D1–D2","k":"了解供水管网的基本构成；知晓材料库「7 大类 108 项」的分类逻辑；清楚「公司现用（95 项）」与「非现用」的区别。","s":"能够独立打开平台，通过「搜索名称、点选分类、查看实物图片」3 步内找到任意一项指定材料；能准确读出材料卡上的型号与规格。","a":"建立「按图索骥、不凭感觉瞎猜」的数据意识。","first":"","courseIds":["C34","C33","C01","C02","C04","C07","C10","C11","C13","C14","C18","C19","C20","C24","C30","C31","C25","C26","C27","C29","C03","C05","C06","C08","C09","C12","C15","C16","C17","C21","C22","C23","C32","C28"],"quizCount":93},{"id":"XG-02","name":"常用材料快速辨识与防呆","band":"D1–D4，以防呆辨识为主线","k":"掌握同型异规、同物异名材料（如：法兰 vs 承插、明杆 vs 暗杆、双盘 vs 双承）的核心视觉差异。","s":"在库房或现场，仅通过「看端头、看阀杆、看标识」，能 100% 准确分辨易混淆管件；能识别出报废、老化或非现用的材料。","a":"养成「拿不准就查手机、绝不让疑似错件进入施工环节」的防呆习惯。","first":"法兰 vs 承插：看端头怎么一眼分","courseIds":["C35","C36","C37","C38","C39","C40","C41","C42","C43","C44","C45","C46","C47","C48","C49","C50","C51","C52"],"quizCount":54},{"id":"XG-03","name":"安全生产与作业底线","band":"D4","k":"知道阀门井、水表井属于有限空间；明白「先通风、再检测、后作业」的铁律。","s":"能正确穿戴 PPE（安全帽、反光衣）；能识别出井盖缺失、路面塌陷等明显材料与环境风险。","a":"树立「生命至上，绝不盲目施救、绝不违规下井」的敬畏心。","first":"井盖打开后，第一步不是下井","courseIds":["C53","C54","C55","C56"],"quizCount":12}],"courseCount":56},{"id":"CL","name":"材料管理","tagline":"守门与家当","attr":"库内核心字段（标准、材质、现用标签）的应用与延伸","band":"D2–D4，验收 / 盘点类带条件判断到 D4","rel":"知识来自材料卡的字段值，场景在验收 / 库房 / 台账，需逐项比对真字段","subs":[{"id":"CL-01","name":"材料验收入库与标准核对","band":"D1–D3","k":"熟知常用现用材料的执行标准（如 GB/T 13295、GB/T 8464）；了解合格证与卫生批件的查验要点。","s":"熟练运用「比对法」，将到货实物与材料卡上的标准 / 型号 / 图片逐一核对；能当场识破供应商「以次充好、非现用冒充现用」的行为并执行拒收。","a":"坚持「不验明正身不入库」的底线思维。","first":"","courseIds":["C57","C58","C61","C59","C60","C62","C63","C64","C65","C66","C67","C68","C69","C70","C71","C72","C73"],"quizCount":51},{"id":"CL-02","name":"仓储日常管理与材质养护","band":"D2","k":"清楚橡胶（避光防老化）、金属（防潮防锈）、电子（防静电）的物理化学特性。","s":"能按材质正确规划库位；能对现用件进行针对性防护（如胶圈覆盖遮光布、不锈钢与碳钢隔离存放）；能独立建立并标识「呆滞隔离区」。","a":"把库房当自己的「厨房」一样打理，重视物资的保全。","first":"","courseIds":["C74","C75","C76","C77","C78","C79","C80","C81","C82","C83"],"quizCount":30},{"id":"CL-03","name":"领退料管控与抢修供给","band":"D1–D3","k":"掌握常用抢修组合包（哈夫节 + 螺栓 + 胶垫）的配置清单；明白退库物资的「可复用 / 降级 / 报废」判定标准。","s":"能在 2 分钟内完成一次标准抢修包的核对与发放；面对一线索要非现用件时，能熟练使用平台查找替代品或要求出具特批单。","a":"树立「服务一线但坚守制度」的协同意识。","first":"一次标准抢修包该有哪几件","courseIds":["C84","C85","C86","C87","C88","C89"],"quizCount":18},{"id":"CL-04","name":"盘点技巧与账实核对","band":"D4","k":"了解盲盘、交叉盘的操作逻辑；明白同型异规件（如各种大小的补芯）的易错点。","s":"能熟练使用平台筛选「公司现用」，进行数据对比；能通过实物外观与管径识别，纠正系统里的录入错误；能规范填报盘点差异表。","a":"追求「账物相符」的严谨作风，不弄虚作假。","first":"","courseIds":["C90","C91","C92","C93","C94"],"quizCount":15}],"courseCount":38},{"id":"GW","name":"管网运维","tagline":"巡检与应急","attr":"库内知识在户外复杂工况和故障场景下的综合运用","band":"D2–D5，抢修 / 处置类带多条件判断到 D4–D5","rel":"知识要搬到户外工况与故障现场，条件多、需迁移","subs":[{"id":"GW-01","name":"日常巡检与材料缺陷识别","band":"D3","k":"了解管网常见漏损、腐蚀的早期表现；知道不同材质管道的寿命周期特征。","s":"能通过地面环境异样发现隐患；能肉眼判断阀门井内阀体生锈、胶圈渗漏、防腐层脱落等缺陷，并准确在系统中对应到具体材料卡片上报。","a":"保持「防微杜渐」的责任心。","first":"井里这处锈，该报哪张卡","courseIds":["C95","C96","C97","C100","C101","C98","C102","C99","C103"],"quizCount":27},{"id":"GW-02","name":"阀门操作与管网调度","band":"D2–D4","k":"理解各类现用阀门（软密封闸阀、偏心蝶阀、加密阀）的内部结构和启闭原理。","s":"能识别并操作不同手轮及加密锁；能严格遵循「慢开慢关」原则防范水锤；能准确判断阀门是否开关到位。","a":"遵守调度指令，保持对水锤破坏力的敬畏。","first":"关阀为什么要慢","courseIds":["C104","C105","C106","C107","C108","C109","C110","C111"],"quizCount":24},{"id":"GW-03","name":"管网抢修与快速处置","band":"D4–D5","k":"掌握 PE 管、球铁管断裂后的物理受力特点；熟知多功能法兰连接器、抢修节等常用抢修材料的适用边界与承压极限。","s":"能快速判断管材并选出正确的抢修件（是热熔还是打哈夫节）；能按照工艺顺序，在带水 / 带压状态下完成快速封堵与连接。","a":"急而不乱，安全优先。","first":"这根管断了：热熔还是哈夫节","courseIds":["C112","C113","C114","C115","C116","C117","C118","C119","C120","C121","C122","C123","C124","C125","C126","C127","C128","C129","C130","C131","C132","C133","C134","C135","C136","C137","C138","C139","C140","C141","C142","C143","C144","C145"],"quizCount":102},{"id":"GW-04","name":"入户故障与表前处理","band":"D3","k":"明确表前（供水企业责任）与表后（用户责任）的产权界碑；了解黄铜球阀、止回阀、活接的内部构造。","s":"能独立排查并修复表前阀门关不严、活接头漏水、水表接头渗水等典型小故障；能用平台里的材料图片向用户通俗解释故障原因。","a":"文明施工，处理好对客沟通，树立公司形象。","first":"表前还是表后：界碑在哪","courseIds":[],"quizCount":0}],"courseCount":51},{"id":"AZ","name":"工程建设","tagline":"选型与安装","attr":"库内知识与设计图纸、施工规范的深度融合","band":"D2–D5，选型 / 变更 / 验收类以 D4 情形判断为主","rel":"同一材料要同时满足压力、口径、材质、工艺多个条件","subs":[{"id":"AZ-01","name":"图纸交底与因地制宜选型","band":"D3–D4","k":"理解不同材料在承压、防腐、造价上的优劣势（如 PE 柔韧性好、球铁抗震、钢管承压高）。","s":"能看懂施工图，并根据现场地勘 / 路面情况（过河、过路、软地基），在现用库中合理替换或推荐管材、管件。","a":"坚持「不盲目照搬图纸，结合实际科学选材」的工程思维。","first":"过路段为什么换管材","courseIds":[],"quizCount":0},{"id":"AZ-02","name":"标准化安装工艺与规范","band":"D2–D3","k":"深刻理解材料卡片上连接方式字段背后的力学原理（如承插胶圈的自密封原理、法兰的挤压密封原理）。","s":"能严格按照规范完成球墨铸铁管的承插对接、PE 管的热熔、法兰的对称紧固；能正确把控水表组、伸缩器的安装间距与顺序。","a":"精益求精，对隐蔽工程的质量负责。","first":"承插胶圈为什么能自己密封","courseIds":[],"quizCount":0},{"id":"AZ-03","name":"现场材料变更与替代管理","band":"D4","k":"了解工程材料变更的审批红线；熟悉平台内同类材料的技术参数（压力、口径、材质）。","s":"当现场发生缺料时，能通过平台检索出参数等同或更优的「现用替代件」，并规范填报变更手续。","a":"杜绝「私自凑合」和「擅自降级」。","first":"缺料了，怎么找参数等同的替代件","courseIds":[],"quizCount":0},{"id":"AZ-04","name":"试压验收与常见通病防治","band":"D4","k":"了解水压试验时盲板、堵头的受力危险；熟悉法兰渗漏、井室积水等常见通病的成因。","s":"能安全设置试压盲板防飞脱区域；能准确发现并处理法兰垫片偏心、螺栓未拧紧、防腐层破坏等施工瑕疵。","a":"树立「工完料净场地清、试压合格才算完」的验收标准。","first":"试压前，盲板对面为什么不能站人","courseIds":[],"quizCount":0}],"courseCount":0}],"courses":[{"id":"C34","sub":"XG-01","topic":"PE给水管及管件：基础外观与口径换算","level":"D1 / L1","d":"D1","l":"L1","positioning":"这一课只解决新手拿到一根6m直管和黑管件时，怎么认外观、怎么从管身喷码读出正确口径，避免量错和拿错。","framework":"外观特征｜黑色6m直管与蓝色标识线。材质分级｜PE100与PE80的字符含义。口径天坑｜图纸DN与实物De外径的转换。管件基础｜平口热熔件与铜丝嵌件。施工底线｜严禁暴晒与明火。\nPE 基础逐块讲透：为什么只认外径 De｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\nPE 口径符号 对照表（先把字母认全）｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：承接前一板块知识；向下接 C33《衬塑管基础与口径换算》。**\n\n**现场情境：图纸标 DN100，材料架上摆着 De110 的 PE 管和外径 114 的钢管。** 领哪一根、量哪个尺寸？带着这个问题读本课。\n\n【外观特征：黑管带蓝线】\n你在库房看到一根根6m长的黑色直管，管身印着一条蓝色的线条，这就是PE给水管。黑管防紫外线，蓝线代表给水专用，与排污用的黑管区分开。\n\n【口径天坑：DN与De】\n新手最容易在口径上栽跟头。图纸常写DN100，但PE管身上印的是De110。记住：DN是公称直径，De才是PE管的实际外径。\n同样标DN100，钢管的外径是Φ114，而PE管的外径是De110，两个管子的外径是不一样大的！千万别拿卡尺量内径去对单子，PE管只认外径。\n\n【管件基础：平口与丝口】\n库房里的PE管件都是黑色的。端头光秃秃、两头平的是热熔件（PE弯头、PE直接、PE三通）；端头带一圈铜色螺纹的，是内丝或PE外丝直接，用来接水龙头或铁阀门。\n\n【施工底线】\nPE管极度怕晒，露天暴晒会变脆；严禁用明火烘烤弯曲，必须用热熔机。\n【PE 基础逐块讲透：为什么只认外径 De】\n**你拿到一根6m直管，先看有没有蓝色标识线：黑管防紫外线，蓝线代表给水专用。** 落回卡上：看「PE给水管」卡的外观栏，和排污黑管就靠这条线区分。\n**图纸写 DN100，PE 管身印的是 De110，DN 是名义尺寸、De 才是实际外径。** 千万别拿卡尺量内径去对单子，管壁有厚度，量出来的数不等于口径。\n**同样标 DN100，钢管外径是 Φ114、PE 管是 De110，两根管并不一样粗。** 这个「同 DN 不同外径」的坑，是跨材质领料最容易错的地方。\n**管身喷码还写着 PE100 / PE80、De、PN 和执行标准号。** 喷码就是这根管的身份证，模糊或没国标号就先待检。\n**PE 管件端头光平口是热熔件、带铜色螺纹的是内丝/外丝直接。** 平口件只能热熔，带铜牙的才接水龙头或铁阀门。\n**PE 极度怕晒、严禁用明火烘烤弯曲，只能用热熔机。** 紫外线让分子链断、明火会把管烤变形，露天存放必须遮阳。\n【PE 口径符号 对照表（先把字母认全）】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\nDN｜图纸上的公称直径｜名义值，不是实测内径｜别拿卡尺量内径去对。\nDe｜PE 管实际外径｜管身喷码上的毫米数｜PE 只认外径 De。\nΦ｜钢管 / 衬塑基体钢管外径｜与 De 不是同一套数值｜同 DN 下两者不相等。\nPE100 / PE80｜材质分级｜同级压力下 PE100 可更薄｜别把材质等级当壁厚等级。\nPN｜公称压力｜数值越大越扛压｜与 SDR 一起核，逐档值以现行标准与技术部门核定为准。\n**【红线】PE 只认外径 De；图纸 DN100 对 De110、对不上钢管 Φ114；严禁明火烘烤、严禁暴晒。**\n落回卡上：「PE给水管」卡的 DN20–DN630、PN、SDR 与执行标准栏，一张卡上就写着口径、压力、壁厚三组符号；逐档外径数值以核定为准，本课不代填。\n\n**自测：图纸写 DN100，能不能直接拿卡尺量 PE 管内径去对？** 回本课【口径天坑：DN与De】对照。\n\n**自测：露天堆放的 PE 管不遮阳，直接暴晒会怎样？** 回本课【存放禁忌】对照。","structure":"外观：黑管蓝线，6m直管。读口径：图纸DN100，PE管实物外径是De110（钢管是Φ114）。认管件：黑色平口是热熔件，带铜牙是丝接件。守底线：严禁暴晒，严禁明火烘烤。\n引导：本课已按符号字典把 DN、De、Φ 认清；现场常卡在「同 DN 就以为同外径」；下一步看 C01 把 SDR、PN 与壁厚三组坐标对全。","anchors":[{"name":"PE给水管","ref":"PE给水管"},{"name":"PE弯头","ref":"PE弯头"},{"name":"PE三通","ref":"PE三通"},{"name":"PE内丝直接","ref":"PE内丝直接"},{"name":"PE外丝直接","ref":"PE外丝直接"}],"pitfall":"【PE只认外径De】图纸DN100，PE管看De110，别和钢管外径114搞混；严禁明火烘烤，露天存放必须遮阳。","remark":"—","seq":1,"family":"PE 管材·管件·连接","lessonNo":1},{"id":"C33","sub":"XG-01","topic":"衬塑管基础与口径换算：图纸DN与管身Φ怎么看","level":"D1 / L1","d":"D1","l":"L1","positioning":"这一课只解决新手的三个最基础问题：衬塑管长什么样、管身上的喷码怎么看、图纸标DN50到底该拿多粗的管子。","framework":"外观特征｜外钢内塑。身份标识｜管身喷码的解读。口径换算｜DN与Φ的对应关系。施工底线｜为什么严禁高温破坏。口径符号字典｜DN、De、Φ、PN、SDR、S 系列、G 螺纹各管什么。DN 与分管寸螺纹｜现场俗称逐档对应。衬塑常用口径逐档完整对应表｜从 DN15 到 DN150 逐档怎么对。","lecture":"**相邻关系：向上接 C34《PE给水管及管件》；向下接 C01《PE给水管》。**\n\n**现场情境：一张图纸写 DN50，库房同时有 Φ60 的实物和标着 4 分的旧台账。** 三者怎么对上？本课讲清换算口径。\n\n【压力等级决定连接方式】\n**衬塑管怎么接不是随便选，要看压力和口径。** 螺纹连接一般用于 1.0MPa 以下，1.0-1.6MPa 宜用法兰或沟槽，水泵房强制用法兰；口径 100 以下宜丝接、100 以上用法兰或沟槽。领管件前先看清图纸压力等级和口径，选错连接方式现场装不上或承压不够。\n\n【外观与喷码：认出它是谁】\n外表是镀锌钢管，内壁有一层白或绿色的塑料，这就是衬塑管。管身上通常喷印着“衬塑管 DN50”字样，这是它的身份证。\n\n【口径换算：图纸DN与实物Φ】\n新手最容易在口径上栽跟头。图纸上写DN50（公称直径），这是名义尺寸。你拿卡尺去量衬塑管的实物，千万别去量内壁的塑料层，要量最外层的钢管外径。\nDN50的衬塑管，对应的钢管外径（符号是Φ）通常是60毫米。\n\n【为什么不能量内径】\n钢管有壁厚，如果你量内径，可能只有50毫米出头，但这并不代表管子不对。在工程标准里，钢管类的口径全部以外径为准。常见的DN15对应Φ21，DN100对应Φ114。\n\n【施工底线：严禁火烧】\n绝对不能对衬塑管用电焊或气割。高温不仅会烧化塑料，还会破坏钢与塑的粘合面导致内衬脱落。切断它只能用低速割管机或手锯。\n【口径符号字典：先把字母认全】\n**你在图纸、管身喷码、材料卡上会撞见一串字母，先认清各管什么，后面才不会串。** DN 是公称直径，名义尺寸，既不是内径也不是外径；De 是塑料管的实际外径；Φ 是钢管与衬塑基体钢管的外径符号；\nPN 是公称压力；SDR 是 PE 管的壁厚比；S 系列是 PPR 的壁厚系列；G、R、RC 是管螺纹代号。\n**这七个符号分属「口径、压力、壁厚、螺纹」四组坐标，别混成一组。** 落回卡上：看「衬塑复合管」卡的型号栏 DN15–DN300、PN10/16，一张卡上就同时写着口径与压力两组符号。\n\n【DN 与分管、寸、管螺纹：现场俗称对照】\n**师傅说「拿个 4 分补芯」「来根 6 分管」，你要能立刻对回图纸上的 DN。** 下面是现场俗称与公称口径的对照，逐档认：\n表头顺序：DN｜现场俗称｜英制螺纹｜识别要点\nDN15｜4 分｜1/2″｜最小档，户内支管与水表前后常见。\nDN20｜6 分｜3/4″｜常见小支管，与 DN15 靠丝扣尺寸区分。\nDN25｜1 寸｜1″｜「1 寸」是俗称，不是 25 毫米实测值。\nDN32｜1 寸 2｜1¼″｜变径起点常见档。\nDN40｜1 寸半｜1½″｜补芯变径高频档。\nDN50｜2 寸｜2″｜丝接与沟槽的交界档。\nDN65｜2 寸半｜2½″｜沟槽卡箍（刚性/柔性）的下限档。\nDN80｜3 寸｜3″｜沟槽管件常用档。\nDN100｜4 寸｜4″｜沟槽或法兰档。\n**【红线】分管、寸是行业通用俗称，螺纹规格与逐档外径一律以现行标准、管身喷码和材料卡核定，本课不代填数值。** 落回卡上：「衬塑双内丝直接」卡标着内丝 G1/2–G2，正是这套螺纹代号在卡面上的样子。\n\n【衬塑常用口径逐档完整对应表】\n**把「图纸 DN → 现场怎么叫 → 该领哪种件」一次对全，领料前照表核一遍。** 表头顺序：DN｜俗称｜连接方式｜配套管件｜识别要点；\n逐档外径数值须由技术部门按现行标准核定后填入，本课只给对照结构，不代填标准数值。\nDN15｜4 分｜丝接｜补芯、衬塑活接头、衬塑丝接弯头、丝接三通｜最小档，靠丝扣尺寸区分，别只看管子粗细。\nDN20｜6 分｜丝接｜补芯、衬塑活接头、衬塑丝接弯头｜与 DN15 靠丝扣尺寸区分。\nDN25｜1 寸｜丝接｜丝接异径管、补芯｜「1 寸」是俗称不是实测值。\nDN32｜1 寸 2｜丝接｜丝接异径管、补芯｜变径起点常见档。\nDN40｜1 寸半｜丝接｜丝接异径管、补芯｜补芯「外丝朝大径、内丝朝小径」在此档高频。\nDN50｜2 寸｜丝接 / 沟槽交界｜丝接件或沟槽卡箍（刚性/柔性）｜按设计定接法，两种件不能混发。\nDN65｜2 寸半｜沟槽｜沟槽卡箍（刚性/柔性）｜沟槽卡箍（刚性/柔性）下限档，丝接件到此为止。\nDN80｜3 寸｜沟槽｜沟槽三通、沟槽弯头、沟槽异径管（大小头）｜立管用刚性卡箍、需抗震用柔性卡箍。\nDN100｜4 寸｜沟槽 / 法兰｜沟槽管件、法兰、法兰盲板｜设备接口与主干管常见档。\nDN150 及以上｜6 寸起｜沟槽 / 法兰｜沟槽管件、法兰｜主干管与设备接口，按设计选，不在本课展开计算。\n**【红线】连接方式分界（丝接 / 沟槽）与逐档外径数值，须与企业现行设计口径和现行标准核定一致；本课现有示例为便于记忆的近似值，不作标准数值使用。**\n落回卡上：把「衬塑复合管」「衬塑内外丝补芯（变径补芯）」「衬塑活接头」「沟槽卡箍（刚性/柔性）」四张卡的口径范围并排看，范围值怎么落到逐档由技术部门核定。\n**自测：图纸写 DN50 的衬塑管，现场该按哪套件领、该量哪个尺寸？** 回本课【衬塑常用口径逐档完整对应表】找这一行，再看 C46 怎么跨材质对。\n\n**自测：图纸 DN50 的衬塑管，现场该按哪套件领、量哪个尺寸？** 回本课【口径换算：图纸DN与实物Φ】对照。","structure":"认外观：外镀锌钢，内有塑料衬层。读喷码：管身印有规格和国标。懂换算：图纸看DN，实物量外径Φ（如DN50对应Φ60）。守底线：严禁电焊气割，必须冷切割。\n认符号：DN 名义、De/Φ 外径、PN 压力、SDR/S 壁厚、G 螺纹。\n对俗称：4 分是 DN15、6 分是 DN20、1 寸是 DN25、2 寸是 DN50。\n查全表：按 DN 逐档对俗称、连接方式、配套件，外径数值以核定为准。\n引导：本课已能按档查表；现场常卡在「师傅报分管、单子写 DN」对不上；下一步看 C46 同口径假象。","anchors":[{"name":"衬塑复合管","ref":"衬塑复合管"},{"name":"衬塑内外丝补芯（变径补芯）","ref":"衬塑内外丝补芯（变径补芯）"},{"name":"衬塑活接头","ref":"衬塑活接头"},{"name":"沟槽卡箍（刚性/柔性）","ref":"沟槽卡箍（刚性/柔性）"},{"name":"衬塑丝接弯头","ref":"衬塑丝接弯头"}],"pitfall":"【量外径，别量内径】图纸DN50，实物外径是Φ60；严禁用普通砂轮或电焊切割。 【4 分=DN15、6 分=DN20、1 寸=DN25】逐档外径与连接方式以现行标准、卡面和技术部门核定为准，本课示例不作标准数值。","remark":"—","seq":2,"family":"衬塑复合及丝扣/沟槽","lessonNo":2},{"id":"C35","sub":"XG-02","topic":"管材大类外观初筛：PE、PPR、衬塑、球铁与钢管","level":"D1 / L1","d":"D1","l":"L1","positioning":"本课只讲管材大类的外观初筛，不展开口径换算、承压计算和安装工艺。目标是一眼把PE、PPR、衬塑、球铁、钢管分到正确大类。在XG-02中承担认得出的第一层。","framework":"外观总览｜黑色6m直管、绿白直管、外钢内塑、沥青黑粗重、带焊缝防腐层。PE识别｜黑管蓝线，6m直管。PPR识别｜绿白直管，红蓝冷热水线。衬塑识别｜外镀锌钢，内白或浅绿塑料。球铁识别｜沥青黑粗重，内水泥衬。钢管识别｜焊缝、3PE或环氧防腐。管材颜色标线与材质代号速查表｜五大类逐行对。","lecture":"**相邻关系：承接前一板块知识；向下接 C36《阀门大类外观与启闭件速记》。**\n\n**现场情境：库房一排管材，有黑管带蓝线、绿白管、外钢内塑管和沥青黑管。** 怎么先按外观分大类？本课讲初筛。\n\n【五大类管材一起辨：颜色、端面、掂重、磁铁四步走】\n**管材分大类别只靠磁铁，先看颜色标线、再看端面内衬、然后掂重量，磁铁只当辅助。** 黑管带蓝线、掂着轻的是 PE；绿白带红蓝线的是 PPR；像镀锌钢管、切口有一圈白或浅绿塑料的是衬塑；沥青黑、内壁水泥砂浆、沉手的是球铁；有焊缝和外防腐层的是钢管。像排队认人，先看衣服颜色、再看脸、最后才量体重。\n**磁铁能吸住的是球铁、钢管、衬塑（内有钢基体），吸不住的是 PE、PPR 纯塑料。** 但磁铁只是辅助一招，颜色、端面、重量三样先摆出来，吸或不吸只用来印证。\n**再用性质印证不会错：PE 怕晒，晒几个月发脆一敲就碎；衬塑严禁电焊气割，高温烧穿内衬；钢管防腐层磕破，破口先锈穿。** 落回卡上：把「PE给水管」「PPR给水管」「衬塑复合管」「球墨铸铁管」「直缝焊接钢管」五张卡按颜色、端面、内衬三项并排比一遍。\n\n【外观总览：先按颜色和端面分大类】\n**先看颜色和端面，一眼把五大类分开。** 黑色带蓝线、掂着轻的是 PE，绿白带红蓝线的是 PPR；掂着压手、有焊缝或内衬的是金属类。像先按颜色排队，再逐类认牌子。\n**再看端面和内壁，这比盯着颜色可靠。** 落回卡上：翻「PE给水管」「球墨铸铁管」那两张实物图，先记住管身颜色和标线、端面有没有内衬这两组轮廓，别凭一眼猜型号。\n\n【PE识别：黑管带一道蓝线】\n**黑管身上一道蓝色标线、6m 定尺直管，就是 PE 给水管。** 蓝线是给水专用的身份线，黑色是炭黑在挡紫外线，像给管子穿了件防晒衣。\n**PE 最怕晒，露天暴晒几个月会发脆开裂，一敲就碎。** 所以库房要遮阳堆放。落回卡上：看「PE给水管」卡的蓝线和6m直管形态，别和黑色排污管混成一堆。\n\n【PPR识别：绿白直管带红蓝线】\n**绿白或灰白的硬直管、印着红蓝线的，是 PPR 给水管。** 红线走热水、蓝线走冷水，像给冷热水各标了一条车道，它硬挺、管身带红蓝标识线。\n**PPR 靠热熔连接，耐热但同样怕晒、低温怕磕。** 把它当 PE 拿去电熔，接口根本熔不上。落回卡上：看「PPR给水管」卡的红蓝线，先认颜色再认口径。\n\n【衬塑识别：外钢内塑看切口】\n**外面像镀锌钢管、切开端面有一圈白或浅绿塑料的，是衬塑复合管。** 它是钢外壳加塑料内衬的两层夹心，像钢管里衬了层塑料胆，钢扛压、塑防锈。\n**【红线】衬塑严禁电焊气割，高温会烧穿内衬，通水后从接口往里锈烂。** 落回卡上：看「衬塑复合管」卡的端面剖面，这一圈内衬就是它不能焊的证据。\n\n【球铁识别：沥青黑、内壁水泥】\n**外壁沥青黑、又粗又重、内壁灰白水泥砂浆的，是球墨铸铁管。** 端头带喇叭形承口，靠胶圈（球墨管承插密封圈）承插连接，像一节节带套筒的粗管。\n**内衬水泥是隔开铁和水、防止生锈结垢的。** 落回卡上：看「球墨铸铁管」卡的水泥内壁和承口，别和钢管的焊缝坡口当成一回事。\n\n【钢管识别：看焊缝和防腐层】\n**带直焊缝或螺旋缝、外覆 3PE 或环氧防腐层的，是焊接钢管。** 焊缝是钢板卷起来焊上的那道接缝，像给管身留了一条脊，防腐层是它的防锈衣。\n**【红线】防腐层一磕破，破口就先从那里锈穿。** 搬运要垫木、别拖拽。落回卡上：看「直缝焊接钢管」卡的焊缝和防腐层，钢管可以焊、衬塑不能焊。\n\n【材料锚点 · 落回卡上】\n**这一课的五张卡，就是你进库房的五张对照卡。** 「PE给水管」「PPR给水管」「衬塑复合管」「球墨铸铁管」「直缝焊接钢管」，一张一个大类，颜色、端头、内衬各不一样。\n**别只在文字里认，点开卡看图，把口诀和实物对上。** 平台材料库的实物图是唯一真源；本课只教初筛，型号、口径、标准一律以卡面与现行标准原文为准。\n\n【管材颜色标线与材质代号速查】\n**把散在各卡上的颜色、标线、代号收成一张速查表，初筛时按顺序核。** 表头：大类｜颜色 / 标线｜材质代号｜第一识别点。\nPE 给水管｜黑管蓝线、6m定尺直管｜PE100 / PE80、SDR11 / SDR17｜蓝线是给水专用，黑色防紫外线。\nPPR 给水管｜绿白直管、红蓝冷热水线｜S2.5 / S3.2 / S4 / S5｜红线热水、蓝线冷水，硬挺、带冷热水标线。\n衬塑复合管｜外镀锌钢、内白或浅绿塑料｜DN15–DN300、PN10/16｜看切口那圈内衬。\n球墨铸铁管｜沥青黑、内水泥砂浆衬｜QT、K / T 型接口、DN100–DN1200｜喇叭形承口。\n焊接钢管｜直缝或螺旋缝、3PE 或环氧防腐｜DN20–DN900 / DN200–DN4000｜看焊缝和防腐层。\n**【红线】颜色只是第一线索，型号、口径、标准一律以卡面与现行标准原文为准。** 落回卡上：把本课五张卡按本表逐行对照；代号含义与逐档数值由技术部门按现行标准核定，本课不代填。\n\n**自测：外钢内塑的衬塑管，能不能当纯钢管看？** 回本课【衬塑识别：外钢内塑看切口】对照。\n\n**自测：黑管带一道蓝线，一定是 PE 给水管吗？** 回本课【PE识别：黑管带一道蓝线】对照。","structure":"主链：先看颜色与标线→再看端面与内壁→再看焊缝或承插口→最后看喷码。\n要点：1 黑管蓝线先想PE；2 绿白直管先想PPR；3 外钢内塑是衬塑；4 沥青黑粗重内水泥是球铁；5 焊缝加防腐层是钢管。\n引导：本课已能断大类；现场常卡在外钢内塑被当成纯钢管；下一步看 C36 阀门大类外观。\n会查表：颜色标线 → 材质代号 → 第一识别点，三列一起看。\n记红线：颜色只是第一线索，型号口径标准以卡面与现行标准为准。","anchors":[{"name":"PE给水管","ref":"PE给水管"},{"name":"PPR给水管","ref":"PPR给水管"},{"name":"衬塑复合管","ref":"衬塑复合管"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"直缝焊接钢管","ref":"直缝焊接钢管"}],"pitfall":"【别把衬塑当纯钢管】外钢内塑，内壁有塑料层；PE黑管带蓝线不等于排污黑管。","remark":"—","seq":3,"family":"XG-02 外观大类速记","lessonNo":1},{"id":"C36","sub":"XG-02","topic":"阀门大类外观与启闭件速记：闸、蝶、球、止回与排气","level":"D1 / L1","d":"D1","l":"L1","positioning":"本课只讲阀门大类的外形与启闭件速记，不展开密封优劣和安装红线。目标是先认出手轮、蝶板、球体、阀瓣和浮球这些外形线索。","framework":"闸阀外形｜小房子阀体，升降闸板。蝶阀外形｜扁圆阀体，蝶板旋转90度。球阀外形｜短阀体，带孔球，手柄90度。止回阀外形｜无手轮，靠阀瓣单向启闭。排气阀外形｜直立胖葫芦，内部浮球。共同点｜都看启闭件，不看铭牌先看形状。","lecture":"**相邻关系：向上接 C35《管材大类外观初筛》；向下接 C37《基础管件轮廓与密封紧固辅材速》。**\n\n**现场情境：一堆阀门摆在一起，有带手轮的、有没手轮的、还有直立的胖葫芦。** 怎么快速认出类别？本课讲启闭件速记。\n\n【阀门型号藏着一张身份证：以 Z41X、D371X 为例】\n**采购单、铭牌上那串字母数字不是乱码，是阀门的型号，拆开就知道它是什么阀、怎么接、什么密封。** 行业按 JB 308 编制：第一个字母是类型（Z 闸阀、D 蝶阀、Q 球阀、H 止回阀）；中间的数字是传动和连接形式；末尾的字母是密封材质。\n**举个例子：Z41X 是闸阀（Z）、法兰连接（4）、橡胶密封（X）；D371X 是蝶阀（D）、对夹连接（7）、橡胶密封（X）。** 看懂型号，领料和核对就不会被一串代码唬住。\n\n【型号里的数字：连接形式对不对照着看】\n**型号里有一位专门说“这阀怎么接到管子上”，选错现场就装不上。** 常用代号：1 是内螺纹（丝口）、4 是法兰（带螺栓孔圆盘）、7 是对夹（阀体很薄、夹在两片法兰中间）、6 是焊接。\n**看阀体两端也能验证：两侧有圆盘孔的是法兰阀，薄片夹装的是对夹阀，带螺纹口的是丝口阀。** 型号和数字、实物外形对得上，才不会领错。\n\n【阀门类型字母：铭牌上认这几个就够】\n**阀门类型用一个拼音字母代表，认全这几个，看铭牌和清单就心里有数。** 闸阀 Z、蝶阀 D、球阀 Q、止回阀 H、截止阀 J、减压阀 Y。\n**本课认的五类阀，代号正好是 Z、D、Q、H 加上排气阀。** 以后看到 Z41X、Q41F 这类型号，第一个字母就知道是哪类阀。\n\n【开关方向和流向：装反了就白装】\n**多数手轮是“顺时针关、逆时针开”，和家里水龙头一个道理。** 但更要看阀体上的箭头——那是水流方向。止回阀、减压阀、倒流防止器这些“有方向”的阀，装反了水过不去或直接失效。\n**所以装阀先找箭头、对准水流，再拧螺栓。** 球阀、蝶阀看手柄位置也能判断开关：手柄和管子平行是开、垂直是关。\n\n【闸阀与蝶阀：看阀体高还是扁】\n**闸阀像个小房子，转手轮让里面的闸板升降；蝶阀扁圆，靠一块蝶板转 90 度开关。** 两个都常带手轮，但一个高、一个扁，站远一点就能分。\n**先认启闭件，别先去读铭牌。** 落回卡上：翻「弹性座封闸阀（暗杆式）」「中线（软密封）蝶阀」两张实物图，看阀体轮廓和手轮位置，比背名字管用。\n\n【球阀：手柄方向就是开关】\n**球阀阀体短，手柄与管子平行是开、垂直是关。** 里面是个带孔的球，转 90 度让孔对准或错开水流，像家里燃气灶的旋钮，一眼看手柄就懂。\n**它启闭快、密封好，但不宜半开节流。** 落回卡上：看「黄铜内螺纹浮动球阀」卡的手柄和短阀体，别把球阀手柄当闸阀手轮去一圈圈拧。\n\n【止回阀：没有手轮就是线索】\n**止回阀没有手轮，靠水流自己顶开阀瓣、倒流时自己关。** 两头多是法兰，阀体上常有个检修盖。看到无手轮的法兰阀，先往止回阀想。\n**它的作用是防倒流，装反了水就过不去。** 落回卡上：看「旋启式止回阀（金属瓣/橡胶瓣）」卡的阀体流向箭头，方向比外形更要紧。\n\n【排气阀：直立的胖葫芦】\n**排气阀直立像个小葫芦，里面靠浮球顶住或让开排气孔。** 管线高点的积气靠它自动排掉，顶端有个小排气嘴，这是和止回阀最明显的区别。\n**积气不排会形成气阻、让水表空转、泵抽空。** 落回卡上：看「复合式排气阀」卡的浮球腔和排气嘴，别把高点排气阀当成普通阀门关死。\n\n【共同点：都看启闭件，不看铭牌】\n**这一课用外形就能初筛，形状比铭牌更快、也更不容易被旧标签带偏。** 手轮、蝶板、球体、阀瓣、浮球，就是五类阀门各自的指纹。\n**【红线】外形只能定大类，不能替你看密封、看端头、看标准。** 减压阀、倒流防止器也有阀体，本课先不展开。落回卡上：认完大类再逐张核对卡面上的连接方式和压力等级。\n\n【材料锚点 · 落回卡上】\n**本课挂的五张卡，正好是五类阀门各一张样板。** 「弹性座封闸阀（暗杆式）」「中线（软密封）蝶阀」「黄铜内螺纹浮动球阀」「旋启式止回阀（金属瓣/橡胶瓣）」「复合式排气阀」，点开就能看到手轮、蝶板、手柄、阀瓣、浮球腔。\n**先按外形认出大类，再点卡核对连接方式和压力等级。** 认外形是入口，不是结论；减压阀、倒流防止器另有其卡，本课先不混进来。\n\n**自测：现场一只阀没有手轮，它可能是哪类阀？** 回本课【止回阀：没有手轮就是线索】对照。\n\n**自测：直立的胖葫芦外形，是哪类阀的特征？** 回本课【排气阀：直立的胖葫芦】对照。","structure":"主链：先看有无手轮→再看阀体高扁→再看启闭件→最后看端头连接。\n要点：1 小房子是闸阀；2 扁圆是蝶阀；3 短手柄带孔球是球阀；4 无手轮多为止回；5 直立浮球是排气。\n引导：本课已能断阀门大类；现场常卡在闸阀与蝶阀都带手轮；下一步看 C37 基础管件与辅材。","anchors":[{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"中线（软密封）蝶阀","ref":"中线（软密封）蝶阀"},{"name":"黄铜内螺纹浮动球阀","ref":"黄铜内螺纹浮动球阀"},{"name":"旋启式止回阀","ref":"旋启式止回阀（金属瓣/橡胶瓣）"},{"name":"复合式排气阀","ref":"复合式排气阀"}],"pitfall":"【外形只初筛】止回阀没有手轮；排气阀直立带浮球；别把减压阀当普通闸阀。","remark":"—","seq":4,"family":"XG-02 外观大类速记","lessonNo":2},{"id":"C37","sub":"XG-02","topic":"基础管件轮廓与密封紧固辅材速记：弯头、三通、大小头、胶垫、胶圈、螺栓","level":"D1 / L1","d":"D1","l":"L1","positioning":"本课只讲库房高频基础件的外形轮廓和辅材功能区分，不展开热熔、法兰紧固和受力计算。目标是拿起件先说出它负责转弯、分叉、变径、延长还是密封紧固。","framework":"基础管件｜弯头转向、三通分叉、大小头变径、直接延长。端头初辨｜平口、螺纹、法兰盘。胶垫｜平圆垫片，法兰间密封。胶圈｜环形厚圈，承插口密封。螺栓｜六角头，半丝带光杆、全丝全螺纹。压力表弯｜O/U/Ω形缓冲弯。","lecture":"**相邻关系：向上接 C36《阀门大类外观与启闭件速记》；向下接 C38《闸阀明杆与暗杆》。**\n\n**现场情境：法兰用胶垫、承口用胶圈，有人拿平圆胶垫塞承口、用普通弯头代替压力表弯。** 错在哪？本课讲辅材分工。\n\n【给水法兰垫片：以 EPDM 为主，其他材质并列认清】\n**自来水管道的法兰垫片，默认选 EPDM（三元乙丙）：耐臭氧、耐候、无毒，适合常温清水，是给水管最常用的一片。** 它是平圆片，夹在两片法兰之间。\n**其他材质并列认清，别混拿：NBR 丁腈耐油却不耐臭氧、不宜长期户外（见 C50）；PTFE 聚四氟乙烯耐强酸碱、用于特殊介质；金属缠绕垫用于高压高温工况。** 像选鞋，日常走路上班穿运动鞋（EPDM），特殊场合才换特种鞋。选错材质，垫片会老化变硬、渗漏。落回卡上：看「胶垫（法兰橡胶垫片）」卡的材质栏，给水场景对应 EPDM。\n\n【垫片内径不能缩颈：内径要略大于管内径】\n**垫片内径要略大于管内径，装上后边缘不能探进流道。** 装偏了、或内径本来就偏小，垫片会伸进管内挡水、节流，甚至被水流冲毁。\n**记住：垫片是夹在法兰缝里封水的，不是塞进管子里堵水的。** 落回卡上：看「胶垫（法兰橡胶垫片）」卡的内径标注，安装时对中放正，别让它缩颈。\n\n【基础管件：看形状就知道它管什么】\n**弯头转向、三通分叉、大小头变径、直接延长，四个件管的都是水流去哪。** 像铁路的道岔和接头，看有几个口、口朝哪，就知道它负责拐弯还是分流。\n**先认形状，再认端头是平口、螺纹还是法兰盘。** 落回卡上：翻「弯头」「三通」「PE大小头（异径管）」三张实物图，把轮廓和用途对上号。\n\n【胶垫（法兰橡胶垫片）与胶圈：一个平、一个环】\n**胶垫（法兰橡胶垫片）是平圆片，夹在两片法兰之间；胶圈（球墨管承插密封圈）是环形厚圈，塞进承口的槽里。** 一个像垫在桌脚下的圆垫片，一个像套在笔上的粗橡皮圈，形状完全不同。\n**两者多用 EPDM，怕油也怕晒，用错位置就漏水。** 落回卡上：看「胶垫（法兰橡胶垫片）」「胶圈（球墨管承插密封圈）」两张卡，平圆给法兰、环形给承插，别混拿。\n\n【螺栓：半丝带光杆，全丝全螺纹】\n**六角头螺栓（半丝/全丝）分半丝和全丝：半丝有一段光滑杆，全丝从头到尾都是螺纹。** 落回卡上：看「六角头螺栓（半丝/全丝）」卡，光杆那一段不是没做完，是专门留着受力的。\n**法兰孔内用半丝光杆抗剪对中，管卡支架用全丝任意调节长度。** 这一步只认外观，受力分工留到 C42 细讲。\n\n【压力表弯：不是普通弯头】\n**压力表弯是 O 形、U 形或 Ω 形的小弯管，专门给压力表挡冲击。** 它在表前绕一圈，形成一段缓冲容积，让水锤先在这里卸力，像给表加了根减震弹簧。\n**【红线】拿普通管道弯头代替表弯，水锤会直接打坏表里的弹簧管。** 落回卡上：看「压力表弯（缓冲弯/冷凝弯）」卡的弯形，它不是改方向的管件。\n\n【相邻关系：小件决定漏不漏】\n**管件定走向、密封件定不漏、紧固件定不松，三样凑齐才是一个接口。** 落回卡上：把本课几张卡摆一起看，你会发现它们常出现在同一处法兰或承插节点上。\n**最容易混淆的是名称混拿：胶垫（法兰橡胶垫片）当胶圈、螺栓当生料带（聚四氟乙烯密封带）、表弯当弯头。** 现场看着都是小件，装错了返工照样要停水。\n\n【材料锚点 · 落回卡上】\n**这组卡要成组看，别一张张孤立记。** 「弯头」「三通」「PE大小头（异径管）」「直接」是改走向的四件，「胶垫（法兰橡胶垫片）」「胶圈（球墨管承插密封圈）」是两处密封件，凑起来才是一个接口。\n**点开卡看端头和截面，形状一眼对上用途。** 螺栓受力留到 C42、表弯缓冲留到 C41 细讲；本课只把「谁管转弯、谁管不漏」认清楚。\n\n**自测：胶垫和胶圈分别用在哪、形状怎么分？** 回本课【胶垫（法兰橡胶垫片）与胶圈：一个平、一个环】对照。\n\n**自测：压力表弯能不能用普通弯头代替？** 回本课【压力表弯：不是普通弯头】对照。","structure":"主链：先认形状→再认端头→再认密封件→最后认紧固件。\n要点：1 弯头转向三通分叉；2 大小头变径直接延长；3 平圆是胶垫环形是胶圈；4 半丝带光杆全丝全螺纹；5 压力表弯是缓冲件。\n引导：本课已认基础轮廓；现场常把胶垫胶圈混拿；下一步看 C38 闸阀明杆暗杆。","anchors":[{"name":"PE弯头","ref":"PE弯头"},{"name":"PE三通","ref":"PE三通"},{"name":"PE大小头（异径管）","ref":"PE大小头（异径管）"},{"name":"PE直接","ref":"PE直接"},{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"}],"pitfall":"【胶垫不是胶圈】平圆夹法兰，环形塞承口；压力表弯不能用普通弯头代替。","remark":"—","seq":5,"family":"XG-02 外观大类速记","lessonNo":3},{"id":"C53","sub":"XG-03","topic":"井室与作业现场安全设施初识：井盖、围挡、PPE与消火栓","level":"D1 / L1","d":"D1","l":"L1","positioning":"本课只讲认得出：井盖、围挡、PPE、消火栓、户表箱各是什么、看哪些部件和标识。不展开有限空间机理、作业票、下井顺序和应急流程。目标是现场看到这些设施能叫对名字、认出功能。","framework":"井盖与井座｜圆形盖体、防滑花纹、功能字样、减震胶条、防盗铰链。围挡警示｜锥桶、围栏、警示带、夜间反光。PPE｜安全帽帽壳帽衬下颚带、反光衣。消火栓｜地上式栓体出水口、地下式井内栓体与井盖。户表箱｜不锈钢箱体、PE分水器、表前阀、水表、箱门锁。功能标识与相邻｜给水、消防、阀门井字样；设施与管道件区分。","lecture":"**相邻关系：承接前一板块知识；向下接 C54《有限空间为什么危险》。**\n\n**现场情境：打开阀门井前，有人没看井盖是给水还是消防、也没摆围挡就凑上去。** 风险在哪？本课讲现场安全设施。\n\n【安全帽有效期：到期强制报废】\n**按 GB 2811-2019，塑料安全帽不超过 2.5 年、玻璃钢帽不超过 3.5 年，到期强制报废；受过冲击的帽子即使外观完好也必须换。** 像头盔，摔过一次里面的结构已经受损，看着没事也不顶用了。落回卡上：看「安全帽」卡的有效期与检查项，先核对生产日期。\n\n【帽壳帽衬缓冲间隙：靠它吸收冲击】\n**头顶与帽壳内顶要留 25–50mm（不少于 32mm）的缓冲间隙，靠这段距离吸收冲击；冲击力要降到 4900N 以下才不伤颈椎。** 间距太小，一砸就顶到头。像汽车的安全带余量，得留够缓冲。落回卡上：看「安全帽」卡的帽衬调节说明，戴之前先捏一捏顶隙。\n\n【井盖与井座】\n**井盖是盖在井座上的功能盖体，不是普通铁板。** 先看圆形盖体、防滑花纹和井座配合。**盖面常铸“给水”或“消防”字样。** 字样用于运维识别，不是装饰。**球墨铸铁井盖重，复合井盖轻。\n** 本课只认材质和标识，不判断承载选型。**盖体背面常见减震胶条或防盗铰链。** 这些是井盖附件，不是管道件。**井盖覆盖井口，井座承托盖体。** 看到井盖先认功能字样和材质。\n\n【围挡警示】\n**围挡是隔离作业区域的现场设施。** 常见锥桶、围栏、警示带。**围挡的作用是挡人挡车。** 不是摆给人看，也不是拍照道具。**夜间围挡要有反光或醒目颜色。** 否则远处车辆看不清。\n**围挡与井盖是两套东西。** 井盖覆盖井口，围挡隔离井口周围。**本课只认围挡种类和功能。** 不展开设置顺序和作业许可。\n\n【PPE】\n**安全帽由帽壳、帽衬和下颚带组成。** 帽壳挡坠物，帽衬缓冲，下颚带固定。**安全帽要戴正并系好下颚带。** 不系带碰撞时容易脱落。**反光衣用于夜间和道路作业。** 它提高可见性，不是普通工作服。\n**PPE是个人防护，不是材料库管件。** 本课只认部件和用途。**安全帽不能代替围挡，反光衣不能代替警示。** 人和现场设施要配合。\n\n【消火栓】\n**地上式消火栓栓体露出地面。** 看红色栓体、出水口和阀门。**地下式消火栓设在井内。** 地面常见井盖和启闭杆，需专用扳手。**消火栓是消防取水设施。** 不是给水阀门，也不是排气阀。\n**地上与地下区别在防冻和交通。** 本课只认外观，不展开选型。**看到消火栓先认地上或地下。** 再看出水口和功能井盖。\n\n【户表箱】\n**不锈钢户表控制箱是集成设施。** 箱体内有PE分水器、表前阀和水表。**箱门带锁，箱体防潮防锈。** 它不是普通配电箱。**底部常见PE外丝直接进水，顶部常见黄铜球阀出水。** 这是箱体接口特征。\n**内部表前阀用于单户控制。** 分水器用于多路分流。**本课只认箱体和内部主要件。** 不展开安装和维护流程。\n\n【功能标识与相邻】\n**功能标识是现场识别的第一线索。** 给水、消防、阀门井字样各有含义。**井盖标识对应井室功能。** 消火栓井、阀门井、水表井不能混叫。**围挡和PPE是安全设施，不是管道材料。\n** 材料锚点只用于定位现场设施。**本课边界是认得出，不判断能否下井。** 下井条件在C54和C56讲。\n\n**自测：安全帽不系下颚带，等于戴了吗？** 回本课【PPE】对照。\n\n**自测：井室作业前为什么要先摆围挡？** 回本课【围挡警示】对照。","structure":"主链：看井盖字样→看围挡→看PPE→看消火栓或户表箱。对照：功能井盖 vs 普通盖板；地上栓 vs 地下栓；安全帽 vs 反光衣。要点：1 井盖看字样和井座；2 围挡挡人挡车；3 安全帽有下颚带；4 反光衣夜间用；5 户表箱不是配电箱。引导：本课已认现场设施；现场常卡在只认外形不认字样；下一步C54讲为什么不能直接下井。","anchors":[{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"复合井盖（给水/消防）","ref":"复合井盖（给水/消防）"},{"name":"地上式消火栓","ref":"地上式消火栓"},{"name":"地下式消火栓","ref":"地下式消火栓"},{"name":"不锈钢户表控制箱","ref":"不锈钢户表控制箱"}],"pitfall":"【井盖不是普通盖板】先看给水或消防字样；围挡不是摆设；安全帽不系下颚带等于没戴。","remark":"企业填：井盖与消火栓标准采购时核对现行版本","seq":6,"family":"XG-03 安全生产与作业底线","lessonNo":1},{"id":"C57","sub":"CL-01","topic":"材料验收五道关卡与现场可量项：总览","level":"D1 / L1","d":"D1","l":"L1","positioning":"这一课讲材料验收的完整骨架：五道关卡各管什么、现场哪些量项可看可量。它放在 CL-01 验收子类的入口位置，只建立全景，不展开分材料细节；分材料验收在 C58–C65。","framework":"单据与卡面映射｜送货单、合格证、材料卡各看哪一栏。\n外观与标识｜名称、喷码、标签、状态。\n规格与尺寸可量项｜DN、De、Φ、壁厚、端头。\n标准与状态｜标准号、版本年、公司现用。\n包装与批次｜包装破损、批次一致性、混装。\n留痕与隔离｜拍照、记录、待检区、拒收隔离。","lecture":"**相邻关系：承接前一板块知识；向下接 C58《PE给水管与PE管件验收》。**\n\n**现场情境：一批材料到货，标签模糊、状态栏还写着非现用，收货员想直接点收。** 第一步该做什么？本课立五道关卡框架。\n\n【五道关卡先立框架】\n**验收不是只看一样，而是五道关卡顺序过。** 你先看单据与卡面，再看外观标识，再量规格尺寸，再核标准状态，最后查包装批次与留痕。\n**第一关是单据与卡面映射。** 送货单写名称数量，合格证写标准与批次，材料卡写型号规格与状态，三处要能对上；对不上就先待检，不凭经验猜。\n**第二关是外观与标识。** 你看名称、喷码、标签、公司现用标识；标签模糊不凭眼看，喷码读不全就转待检。\n**第三关是现场可量项。** 管材量外径或端头，阀门看阀杆和端头，水表看铅封和读数窗口；量错位置比不量更麻烦。\n**第四关是标准与状态。** 标准号不是装饰，是验收依据；状态栏决定能不能进现用区。\n**第五关是包装批次与留痕。** 包装破损、混装、批次不一致先分开；留痕要记课程号、卡名、批次、数量、异常点。\n【规格可量项要认体系】\n**不同材料口径体系不同，你别拿一把卡尺量所有东西。** PE给水管卡上写 DN20–DN630，实物常看 De 外径；钢管看 Φ 外径；球墨铸铁管看 DN 与承插端头。\n**可量项不是背数字，是认该量哪里。** 你量 PE 管要量外径，不量内壁；量钢管要量外径和壁厚；量球铁要看承口插口配合。\n**阀门可量项看端头与阀杆。** 弹性座封闸阀（暗杆式）看法兰端、暗杆、手轮；黄铜阀看内螺纹；端头不对，装上去就是返工。\n**水表可量项看接口与铅封。** 旋翼式机械水表（湿式/干式/液封）卡上标 DN15–DN40，验收看螺纹接口、铅封、字轮；铅封断了先待检。\n【标准与状态要一起核】\n**标准号不是装饰，是验收依据。** PE给水管卡上写 GB/T 13663.2-2018；球墨铸铁管写 GB/T 13295-2019，备注 2026 版 2027-03-01 实施。\n**状态栏决定能不能进现用区。** 卡上“公司现用”才能按现用件验收；非现用先隔离，不凭名字发料。\n**标准换版要看实施日期。** 到货在切换日前后，核对依据不同；本课只认这个规则，具体版本在分课讲。\n**合格证与卡面不一致时先待检。** 不一致不是让你猜，是转待检或拒收流程；不要替供应商解释，责任由验收人承担。\n【包装批次与留痕】\n**包装破损和混装是验收信号。** 同批里混了别的规格、别的标准，先分开再核；混装发料最容易装错。\n**留痕不是拍照发群。** 留痕要记录课程号、卡名、批次、数量、异常点、处理动作；少一项，后面查不清。\n**拒收与隔离是两道动作。** 拒收是判定，隔离是现场控制；非现用、标签模糊、老化件都不能混入现用区。\n**总览课只给索引。** 五道关卡记住顺序，分材料细节到 C58–C65 看；你先把骨架立住，再往里填。\n\n**自测：标签模糊的材料能不能凭眼看直接收货？** 回本课【五道关卡先立框架】对照。\n\n**自测：非现用状态的材料到货，应该怎么处理？** 回本课【标准与状态要一起核】对照。","structure":"主链：看单据→核卡面→看外观标识→量规格端头→核标准状态→查包装批次→留痕隔离。\n对照：可量项 vs 不可量项；公司现用 vs 非现用；待检 vs 拒收。\n要点：1 五道关卡顺序过；2 单据卡面先对上；3 不同材料量不同位置；4 标准与状态一起核；5 异常先隔离再判定。\n引导：本课已认验收五关卡；现场常卡在只看名称不看状态；下一步 C58 讲 PE 管与管件验收。","anchors":[{"name":"PE给水管","ref":"PE给水管"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"旋翼式机械水表（湿式/干式/液封）","ref":"旋翼式机械水表（湿式/干式/液封）"}],"pitfall":"【总览不替代分课】先看状态栏；标签模糊不凭眼看；非现用先隔离。","remark":"总览课，不替代 C58–C65 分课；企业填：验收单据按企业现行制度","seq":7,"family":"CL-01 材料验收入库与标准核对","lessonNo":1},{"id":"C95","sub":"GW-01","topic":"管网日常巡检工作全景与缺陷大类识别","level":"D1 / L1","d":"D1","l":"L1","positioning":"这一课建立管网巡检的全局认知框架，讲清巡检职责、类型、缺陷大类、作业流程与安全底线，是GW-01板块的入门总纲，为后续专项巡检课打基础。","framework":"巡检职责与范围｜核心职责、常规覆盖范围、责任区段划分。\n四类巡检类型｜日常例行、专项重点、汛后冻融后、老旧管网加密巡检适用场景。\n五大缺陷大类｜管材类、阀门管件类、仪表类、附属设施类、安全环境类划分。\n巡检基本流程｜现场观察→记录取证→分级上报→跟进闭环四步链路。\n安全底线原则｜井盖开启规范、有限空间禁令、井下防护基本要求。","lecture":"**相邻关系：承接前一板块知识；向下接 C96《地面巡检》。**\n\n**现场情境：巡检发现井盖破损、地面沉降，还有人想下井看看，只拍了张照就准备走。** 哪里不对？本课立巡检全景。\n\n【巡检职责与范围：先清楚自己巡什么】\n你作为巡检员，核心职责是巡查责任区段内的供水管线、阀井、消火栓、计量设施及附属构筑物，及时发现隐患并上报，不是只看路面有没有水。\n常规巡检覆盖市政道路下的给水主干管、支管，以及沿线的阀门井、排气阀井、消火栓、水表井；小区红线外、施工影响段、老旧管段是重点关注区域。\n责任区段按道路、桩号划分，每一段都要有明确的责任人，出了问题可追溯。\n【四类巡检类型：不是只有日常巡一种】\n巡检分四类，场景各不同。日常例行巡检是按固定周期全线巡查，属于常规动作；专项重点巡检是针对重大活动、高峰供水期组织的针对性检查；\n汛后/冻融后巡检是降雨、融雪冻胀过后的加密排查，重点看接口沉降渗漏；老旧管网加密巡检是对服役年限长、腐蚀严重的管段提高巡检频次，提前捕捉隐患。\n【五大缺陷大类：先归类再细看】\n管网缺陷归为五大类。管材类缺陷指管道本体的渗漏、腐蚀、变形、破裂；阀门管件类缺陷指阀门、接头、管件的锈蚀、卡涩、渗漏、老化；仪表类缺陷指水表、流量计、压力表的外观损坏、显示异常、接头渗漏；\n附属设施类缺陷指井盖、井室、标识桩、防护栏的破损、沉降、缺失；安全环境类缺陷指第三方施工破坏、地面塌陷、违章占压等环境风险。\n【巡检基本流程：四步走形成闭环】\n巡检不是随便走一圈，要按标准流程来。第一步现场观察，沿管线逐点排查，看地面、看井室、看设施；第二步记录取证，发现缺陷立刻定位、拍照、填记录，要素写全；\n第三步分级上报，按缺陷严重程度报对应岗位，紧急隐患第一时间升级；第四步跟进闭环，上报后跟进整改进度，整改完现场复核销号。四步缺一步，巡检都不算完成。\n【安全底线原则：五条红线不能碰】\n巡检首先要保自身安全。开启井盖要用专用工具，不能用手直接抠，防止井盖弹起伤人；有限空间作业严格执行禁令，无检测、无监护、无作业票绝对不能下井；\n井下查看先开盖通风3分钟以上，站在上风侧探头观察，不贸然探身；夜间和道路作业必须穿反光衣、设围挡警示；发现有毒有害异味立刻撤离，不盲目靠近。\n\n**自测：巡检是不是只找明漏就行？** 回本课【五大缺陷大类：先归类再细看】对照。\n\n**自测：发现缺陷只拍照不上报，算完成巡检吗？** 回本课【巡检基本流程：四步走形成闭环】对照。","structure":"主链：明职责→分类型→归缺陷→走流程→守底线。\n要点：1 巡检覆盖管线、阀井、消火栓、仪表全要素；2 四类巡检对应不同场景；3 缺陷分五大类，先归类再定性；4 四步流程形成闭环；5 五条安全红线必须守。\n引导：本课建立巡检全局认知；现场常卡在只看漏水不看环境；下一步C96讲地面管材隐患识别。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"旋翼式机械水表（湿式/干式/液封）","ref":"旋翼式机械水表（湿式/干式/液封）"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"}],"pitfall":"【巡检不是只找明漏】井盖破损、地面沉降、违章占压都属于巡检范围；无监护无检测绝对不能下井；发现缺陷只拍照不上报等于白巡。","remark":"—","seq":8,"family":"GW-01 日常巡检与材料缺陷识别","lessonNo":1},{"id":"C74","sub":"CL-02","topic":"库房材质分区与养护管理全景骨架","level":"D1 / L1","d":"D1","l":"L1","positioning":"本课讲仓储日常材质养护的完整知识骨架，属于 CL-02 子类的入门全景课。你将先建立全库材质分类、库位规划、养护总纲、功能分区、作业流程、责任划分的整体认知，不展开单品类细节，为后续分品类课程搭建框架。","framework":"1. 全库材质六大分类｜塑料类、橡胶密封类、黑色金属类、有色与复合类、电子仪表类、综合辅材类\n2. 库位规划三大原则｜重下轻上、先进先出、异质隔离\n3. 养护总纲三维度｜温湿度管控、避光防尘、污染隔离\n4. 库区功能四分区｜合格品区、待检区、呆滞隔离区、作业通道\n5. 日常养护全流程｜入库检查→在库巡检→定期养护→异常处置\n6. 岗位责任边界｜仓管员日常职责、异常上报流程","lecture":"**相邻关系：承接前一板块知识；向下接 C75《塑料类管材管件仓储养护》。**\n\n**现场情境：新仓管把金属件和橡胶件放同一区、重货压在轻货上。** 有什么问题？本课建材质分区骨架。\n\n【全库材质六大分类】\n库房物料按材质属性分为六大类，是养护管理的基础分类。\n分别是塑料类、橡胶密封类、黑色金属类、有色与复合类、电子仪表类、综合辅材类。\n不同材质的老化机理、失效模式完全不同，不能按同一标准管理。\n落回卡上：PE 给水管代表塑料类，球墨铸铁管代表黑色金属类，胶圈代表橡胶密封类。\n【库位规划三大原则】\n库位规划必须遵循三条核心原则，兼顾安全、效率与物料保全。\n第一条重下轻上，重物放低层货架或地面、轻物放高层，降低坠物风险与货架承重压力。\n第二条先进先出，入库早的物料放在易取外侧，避免长期存放超期失效。\n第三条异质隔离，属性冲突、会互相影响的物料分区分架存放，禁止混放。\n【养护总纲三维度】\n日常养护围绕温湿度、光照、污染物三个核心维度展开。\n温湿度是影响金属锈蚀、橡胶老化、电子受潮的核心因素，需控制在合理区间。\n光照中的紫外线会加速塑料、橡胶老化，避光防护是通用要求。\n油污、粉尘、化工挥发物会造成物料腐蚀污染，必须做好隔离防护。\n【库区功能四分区】\n库区按管理功能划分为四类区域，边界清晰禁止混放。\n合格品区存放验收合格的现用物料，是主存储区。\n待检区存放新到货未验收、状态待确认的物料。\n呆滞隔离区存放超期、不合格、待报废的物料，物理隔离防错发。\n作业通道保持畅通，禁止堆放物料，保障搬运与巡检通行。\n【日常养护全流程】\n日常养护是闭环流程，覆盖物料在库全生命周期。\n入库时先做外观初检，合格再进入合格品区。\n在库期间按周期巡检，记录温湿度与物料状态。\n定期开展针对性养护，比如金属防锈、橡胶避光检查。\n发现异常及时隔离处置，按流程上报并跟进结果。\n【岗位责任边界】\n养护不是一人之事，权责清晰才能落地。\n仓管员是日常养护第一责任人，每日巡检、定期维护。\n异常问题分级上报，重大质量问题同步技术部门判定。\n养护记录留存归档，作为物料质量追溯的依据。\n\n**自测：不同材质能不能用同一套养护标准？** 回本课【全库材质六大分类】对照。\n\n**自测：重下轻上为什么是安全底线？** 回本课【库位规划三大原则】对照。","structure":"知识结构：材质分类→库位规划→养护维度→功能分区→作业流程→责任边界，形成仓储养护的完整闭环骨架。\n学习要点：\n1. 六大材质分类是养护基础，不同材质要求差异极大\n2. 库位三原则：重下轻上、先进先出、异质隔离\n3. 养护三维度：控温湿度、防光照、隔污染\n4. 四区功能明确，呆滞料必须物理隔离\n5. 养护是全流程闭环，不是一次性动作\n6. 权责清晰，日常巡检 + 分级上报 + 记录留痕","anchors":[{"name":"PE 给水管","ref":"PE给水管"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"六角头螺栓（半丝 / 全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"黄铜内螺纹浮动球阀","ref":"黄铜内螺纹浮动球阀"},{"name":"超声波水表","ref":"超声波水表"}],"pitfall":"1. 别用同一套标准管所有材质，不同物料养护要求差异极大\n2. 呆滞料不隔离，早晚会被错领误用\n3. 重下轻上不仅是效率问题，更是安全底线","remark":"—","seq":9,"family":"其他","lessonNo":1},{"id":"C84","sub":"CL-03","topic":"领退料与抢修供给管理全景骨架","level":"D1 / L1","d":"D1","l":"L1","positioning":"本课讲领退料与抢修供给的完整知识骨架，属于 CL-03 子类的入门全景课，涵盖业务场景、核心流程、权责边界、物料范围、管理原则五块内容。本课只搭整体框架，不展开单场景细节，是全子类后续各课的共同前置。","framework":"1. 业务场景分类｜常规领料、抢修领料、退库处置三大核心场景\n2. 核心流程总览｜领料→核对→发放→退库→判定的全链路逻辑\n3. 岗位权责边界｜仓管员、领料人、审批人各自的职责与红线\n4. 核心物料范围｜管材、管件、阀门、水表、辅材五大类领用物料\n5. 管理核心原则｜凭单发料、先进先出、合规替代、分级审批","lecture":"**相邻关系：承接前一板块知识；向下接 C85《常规领料作业规范》。**\n\n**现场情境：抢修急着领料，有人说先拿后补手续、先到先得随便发。** 合规边界在哪？本课讲领退料骨架。\n\n【业务场景分类】\n领退料业务分三大核心场景，规则和优先级完全不同。\n第一类常规领料，是日常维修、工程施工的计划性领料，流程最完整。\n第二类抢修领料，是管网破损、设备故障的应急领料，效率优先但合规底线不能破。\n第三类退库处置，是剩余物料、更换下旧件的退回判定，直接影响库存损耗。\n落回卡上：PE 给水管代表管材类，哈夫节（堵漏器）代表抢修类，旋翼式水表代表计量类。\n【核心流程总览】\n所有领退料都遵循固定闭环流程，跳步就会出管理漏洞。\n领料环节先审单据，再核对物料，确认无误后发放。\n退料环节先核验状态，再判定等级，最后登记归位。\n每一步都要有记录，做到来源可查、去向可追、责任可究。\n【岗位权责边界】\n每个岗位各管一段，守好自己的红线，流程才不会乱。\n仓管员负责核对物料、按单发料、登记台账、判定退料等级。\n领料人负责提交合规单据、如实说明用途、核对领取物料。\n审批人负责超定额、替代件、特殊场景的审批，承担决策责任。\n严禁无单领料、越权审批，出了问题倒查每一环的责任。\n【核心物料范围】\n领退料覆盖五大类物料，全都是公司现用的常备品类。\n1. 管材类包含 PE 管、球铁管、PPR 管、衬塑管、钢管。\n2. 管件阀门类包含各类接头、弯头、三通、闸阀、蝶阀、止回阀。\n3. 水表仪表类包含机械水表、智能水表、流量计、压力表。\n4. 辅材类包含螺栓、胶垫（法兰橡胶垫片）、生料带（聚四氟乙烯密封带）、抢修胶等零散物料。\n【管理核心原则】\n四条核心原则是领退料的底线，任何场景都不能突破。\n凭单发料：没有合规单据不得发放物料，特殊情况事后必须补单。\n先进先出：优先发放入库早的物料，避免长期存放超期老化。\n合规替代：缺料时只能用参数更优的现用件替代，禁止私自降级。\n分级审批：超出权限的必须走审批流程，不能自作主张。\n\n**自测：先进先出是不是随便拿外面的货？** 回本课【核心流程总览】对照。\n\n**自测：先导后补手续最晚什么时候补齐？** 回本课【管理核心原则】对照。","structure":"知识结构：场景分类→流程总览→权责边界→物料范围→核心原则，构成领退料管理的完整闭环骨架。\n学习要点：\n1. 三大业务场景：常规、抢修、退库，规则优先级不同\n2. 全流程闭环：领料 - 核对 - 发放 - 退库 - 判定，一步都不能少\n3. 岗位权责清晰，各守红线，禁止越权操作\n4. 覆盖五大类物料：管材、管件、阀门、水表、辅材\n5. 四条核心原则：凭单、先进先出、合规替代、分级审批\n6. 所有操作留痕，做到来源可查、去向可追、责任可究\n把这五块骨架合起来看，现场领料、抢修、退料再乱，你也能先分清属于哪类场景、走哪条流程、谁该签字；下一课 C85 就把日常领料这一场景拆成一步步的动作。","anchors":[{"name":"哈夫节","ref":"哈夫节（堵漏器）"},{"name":"六角头螺栓（半丝 / 全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"PE 给水管","ref":"PE给水管"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"旋翼式机械水表（湿式 / 干式 / 液封）","ref":"旋翼式机械水表（湿式/干式/液封）"}],"pitfall":"1. 抢修再急也不能突破合规底线，事后要按统一口径在工作日内补齐手续\n2. 先进先出不是随便拿，要按批次和入库时间发料\n3. 替代物料不能私自换，必须符合参数更优的原则","remark":"","seq":10,"family":"其他","lessonNo":1},{"id":"C90","sub":"CL-04","topic":"盘点管理与账实核对工作全景骨架","level":"D1 / L1","d":"D1","l":"L1","positioning":"这一课建立盘点工作的整体认知框架，讲清盘点的核心类型、执行主体、全流程步骤、高易错物料范围与管理原则，让新人快速明白 “盘什么、谁来盘、怎么盘”，是后续实操课的总纲。","framework":"盘点类型分类｜日常动碰盘、月度定期盘、年度全面盘、专项盘点四类适用场景。盘点主体区分｜自盘（仓管员自主盘点）、他盘（交叉盘、监盘、复盘）的定义与权责。核心流程总览｜盘点前准备→盘中作业→盘后核对→差异处置→闭环整改全链路。高易错物料范围｜管件类、阀门类、辅材类、水表仪表类四大高易错品类。管理核心原则｜实事求是、账实一致、盲盘复核、差异必究。","lecture":"**相邻关系：承接前一板块知识；向下接 C91《盘点作业规范与系统操作实务》。**\n\n**现场情境：盘点就是数数，自盘监盘分不清，小差异也懒得上报。** 这些认知错在哪？本课立盘点骨架。\n\n【盘点类型分类：四类场景各有分工】\n你在仓库日常接触的盘点分四类，不是只有年底大盘才叫盘点。日常动碰盘是每天下班前，对当天有出入库记录的物料逐一复盘，确保动过的料账实一致；\n月度定期盘是每月固定日期，对所有常用物料全面清点，是常规管控动作；年度全面盘是年末对全仓库所有物料全盘，通常由财务监盘，结果直接对接资产核算；\n专项盘点是针对抢修料、呆滞料、贵重仪表等特定品类单独组织的盘点，比如汛期前盘抢修物资。\n【盘点主体区分：自盘是本职，他盘是校验】\n盘点分两类主体：自盘就是仓管员对自己管辖的库区自主盘点，是日常工作；\n他盘包括交叉盘、监盘、复盘，交叉盘是不同库区的仓管员互查，监盘是财务、主管等第三方现场监督，复盘是对初盘有差异的物料重新清点。\n自盘要对结果负责，他盘重在校验和监督，不能因为有监盘就推卸自盘责任。\n【核心流程总览：五步走完全链路】\n盘点不是拿起东西就数，完整流程分五步：盘点前准备→盘中作业→盘后核对→差异处置→闭环整改。准备做足能少走一半弯路，盘中要按规则点数记录，盘后立刻和账面核对，有差异就排查原因，最后落实整改形成闭环，缺一步都不算完整盘点。\n【高易错物料范围：四大类是重灾区】\n自来水仓库里，盘点最容易出错的集中在四类：管件类规格多、外形像，最容易串数；阀门类结构相近、同型异规多，容易混放；辅材类体积小、数量多，点数容易偏差；水表仪表类价值高、单位易混，出错影响大。盘点时对这四类要格外留心，多花时间核验。\n【管理核心原则：四条红线不能碰】\n盘点的核心原则就四条：实事求是，不能估数凑数；账实一致，目标是实物和账面完全对应；盲盘复核，初盘尽量不看账面数，避免先入为主；差异必究，不管差异大小都要查明原因，不能放过。\n\n**自测：自盘和监盘的权责怎么分？** 回本课【盘点主体区分：自盘是本职，他盘是校验】对照。\n\n**自测：盘点发现小差异能不能不报？** 回本课【管理核心原则：四条红线不能碰】对照。","structure":"分类型：动碰盘管日常、定期盘管月度、全面盘管年度、专项盘管特定品类。\n分主体：自盘是仓管员本职，他盘含交叉、监盘、复盘，起校验作用。\n记流程：准备→盘中→核对→差异处置→整改闭环，五步缺一不可。\n划重点：管件、阀门、辅材、水表仪表是四大高易错品类。\n守原则：实事求是、账实一致、盲盘复核、差异必究。\n明边界：盘点是流程动作，不是单纯点数，最终要落地到账实相符。\n知权责：自盘人对结果负责，监盘人对过程合规负责。","anchors":[{"name":"衬塑内外丝补芯（变径补芯）","ref":"衬塑内外丝补芯（变径补芯）"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"六角头螺栓（半丝 / 全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"旋翼式机械水表（湿式 / 干式 / 液封）","ref":"旋翼式机械水表（湿式/干式/液封）"}],"pitfall":"【盘点不是单纯点数】别把自盘和监盘权责搞混；小差异不能直接忽略不上报；盘点不用走流程、数完就行是错误认知。","remark":"—","seq":11,"family":"其他","lessonNo":1},{"id":"C01","sub":"XG-01","topic":"PE给水管：外观材质、规格体系与口径判别","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课专讲PE给水管。不去对比其他管材，重点解决新员工对PE管长什么样、材质有啥不同、口径怎么读的基础认知，建立直观的第一印象。","framework":"外观特征与材质分级｜黑色管身、蓝色标线与PE100/PE80的区别。规格天坑｜DN公称直径与De实际外径的换算。承压指标｜PN公称压力与SDR壁厚的反比关系。执行标准与喷码｜管身国标代码的识别。存放禁忌｜紫外线对塑料管材的致命破坏。SDR / PN / 壁厚对照表｜三组坐标各管什么、逐档怎么核。","lecture":"**相邻关系：向上接 C33《衬塑管基础与口径换算》；向下接 C02《PE管件图谱》。**\n\n**现场情境：泵房高压段要选 PE 管，同事说 SDR17 更便宜想直接用。** 能不能用？读完承压指标这一块就明白。\n\n【PE 后面的数字是啥：原料等级 MRS】\n**PE 管名字里的 PE100、PE80，指的是原料的“最小要求强度”MRS，不是管子粗细。** PE80 的 MRS 是 8.0MPa、PE100 是 10.0MPa，数字越大长期承压越强、同样压力能用更薄的壁。PE63 强度偏低不宜埋地，新建市政给水基本都用 PE100。领料时看清原料等级，别把 PE80 当 PE100 用在高压主干上。\n\n【外观特征与材质分级】\n**你在料场看到的PE给水管绝大多数是黑色的，且管身有一条蓝色标识线。** 这是因为黑色能防紫外线，蓝线代表它是给水专用管。\nPE管按材质密度分为PE100和PE80。打个比方，PE100像硬汉，承压能力强，同等压力下管壁可以做得薄一点；PE80像软妹子，柔韧性极好，但管壁必须做厚才能承压。\n给水主干管现在强制要求用PE100，但在地形容易沉降的区域，选用柔韧的PE80能防断裂。\n\n【规格天坑：DN与De】\n**很多人栽在口径上：图纸写DN，管子印De，千万别拿卡尺量内径去对单子。** DN是公称直径（名义值），De才是实际外径毫米数。\n比如图纸要DN100的PE管，你领回来的管子上印的应该是De110。因为管壁有厚度，如果量内径大概只有90多。如果你误以为De110和DN110是一回事，领错货装不上，会直接导致整段停工返工。\n\n【承压指标：PN与SDR】\n**别只看管子粗细，承压等级决定了这根管能埋在哪里。** PN代表公称压力，如PN10就是1.0MPa。\nSDR是标准尺寸比，也就是外径与壁厚的比值。SDR数值越小，管壁越厚，承压越高。比如SDR11的承压能力就远大于SDR17。如果在高压泵房出口错用了薄壁的SDR17，通水瞬间管子就会像气球一样爆裂。\n\n【执行标准与喷码】\n**管身上的喷码，就是这根管子的合法身份证。** 材料卡上的执行标准是GB/T 13663.2。\n现场验收时，你要核对管身喷码是否完整印着“PE100、De外径、PN压力、执行标准号”。如果喷码模糊，或者根本没有写国标号，这就是非标管，必须拒收。\n\n【存放禁忌：紫外线】\n**PE管最怕晒，露天暴晒会急速老化。** 塑料在紫外线照射下分子链会断裂，晒几个月后管子会变得像石头一样脆，一敲就碎。\n在库房或工地存放，必须用遮阳布盖严。这跟球墨铸铁管能直接在露天堆放的习性完全不同，不能混为一谈。\n【SDR / PN / 壁厚 对照表：怎么查】\n**SDR、PN、壁厚是同一件事的三种说法：管外径定死后，壁越厚越扛压。** 表头顺序：指标｜卡面怎么写｜怎么读｜核对动作。\nSDR｜卡面常见 SDR11、SDR17｜标准尺寸比＝外径÷壁厚，数值越小壁越厚｜按卡面 SDR 找对应壁厚系列。\nPN｜卡面常见 PN0.6–1.6MPa（PE100 可达 PN2.0）｜公称压力，数值越大越扛压｜按设计压力核对 PN，不只看管径。\n壁厚｜随 SDR 与外径变化｜同外径下 SDR11 比 SDR17 厚｜逐档壁厚与承压对应值由技术部门按现行标准核定。\nPE100 / PE80｜卡面材质分级｜同级压力下 PE100 可比 PE80 做得更薄｜别把材质等级当成壁厚等级。\n**【红线】SDR 小不等于口径大，PN 高不等于管壁厚，三组坐标别串。**\n落回卡上：看「PE给水管」卡的 DN20–DN630、PN0.6–1.6MPa、SDR11/17 三个字段，逐档对应数值以现行标准和技术部门核定为准。\n**自测：泵房高压段为什么不能用 SDR17？** 回本课【承压指标：PN与SDR】与上表找 SDR 与承压的关系。\n\n**自测：泵房高压段为什么不宜用 SDR17？** 回本课【承压指标：PN与SDR】对照。","structure":"看外观：黑管带蓝线，防紫外线。\n认材质：PE100承压强，PE80柔韧好。\n读规格：图纸DN100，实物De110，不可混用。\n看承压：SDR越小，管壁越厚承压越高。\n认标准：看管身喷码是否有GB/T 13663.2。\n懂存放：必须避光搭棚，严禁暴晒。\n查全表：SDR 是外径÷壁厚、PN 是公称压力、壁厚随系列变；SDR11 比 SDR17 厚。\n记红线：逐档壁厚与承压对应值以现行标准与技术部门核定为准，不凭管子粗细判承压。","anchors":[{"name":"PE给水管","ref":"PE给水管"}],"pitfall":"【图纸DN不等于实物De】千万别拿卡尺量内径去核对DN口径；PE管露天暴晒必脆裂，必须遮阳。","remark":"—","seq":12,"family":"PE 管材·管件·连接","lessonNo":3},{"id":"C02","sub":"XG-01","topic":"PE管件图谱：形状辨识、接口区分与转换逻辑","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课专讲PE系统的管件。管道不可能一根通到底，遇到转弯、分叉、接金属设备时，必须依靠管件。只认库房里真实的PE管件，让你拿起一个件就知道怎么接。","framework":"基础形状件｜PE弯头、PE三通、大小头、PE直接。跨材质转换｜PE法兰头/片与内外丝。封堵收尾｜PE管帽（堵头）。防呆辨识法｜看端头是平口还是带丝/带盘。执行标准｜GB/T 13663.3。\nPE 管件逐块讲透：端头为什么决定接法｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\nPE 管件端头 × 接法 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C01《PE给水管》；向下接 C04《球墨铸铁管本体》。**\n\n**现场情境：要把一段 PE 管接到金属阀门上，手边有平口件、带螺纹嵌件和生料带。** 平口件缠生料带能不能接上？本课讲端头决定接法。\n\n【PE管件的两大系列：承插式和对接式】\n**PE管件按接法分两大系列：承插式和对接式，这是认件的第一层。** 你之前看到的平口件全是对接式；还有一类带喇叭形承口的，是承插式，管子要插进承口里熔接。两种件长相不同、用的机器也不同，先分清系列再说名字。\n\n【承口长什么样：外大内小的喇叭口】\n**承插式管件的一头是“外大内小”的喇叭形承口，另一头也是承口，管子从两头插进去。** 对接式则两头都是平口，靠端面顶在一起熔接。你在库房看到管件端口有个明显扩大的喇叭口、内壁带着一圈台阶，那就是承插件，不能拿去对接机。\n\n【承插还是对接：看口径定】\n**接法不是随便选，是由管子的外径（De）决定的。** De63 及以下的管子，多用热熔承插；De63 到 De110 之间，承插、对接都能用；De110 以上用热熔对接。记住这条分界，领件时看管子多粗就知道该配哪种管件。\n\n【基础形状件：转弯与分叉】\n**在库房看到同样黑色的塑料件，两头光秃秃的都是热熔平口。** 要转弯就领PE弯头（90度或45度），要分叉就领PE三通，要变粗细就领PE大小头（异径管），直线接长就领PE直接。\n它们没有任何螺纹，现场全靠热熔机把管子和管件的高温融化面贴在一起。如果拿这种平口件去对接铁阀门，是绝对装不上的。\n\n【跨材质转换：连金属怎么接】\n**PE管怎么和铁阀门对接？必须有翻译官，绝不能用火烤或者用胶水粘。** 一种是PE法兰头/片，它一头是PE塑料可热熔，另一头是带螺栓孔的金属圆盘。\n如果要接小口径的水表或丝口阀门，领PE内丝直接或PE外丝直接。这种管件内部注塑了铜嵌件，带螺纹。你在现场想硬把PE管套在铁管上，只会导致接口漏水。\n\n【封堵收尾：PE管帽（堵头）】\n**管路装到尽头或预留接口，要用PE管帽把管口封死。** 它也是热熔平口，套在管端加热熔接，形成封闭端头。\n临时不接的支管口、预留阀门位，先熔一个管帽封住，防止杂物进水、也避免误接。等要用时切掉管帽重新熔接即可，比用胶带缠、木塞堵可靠得多。\n\n【防呆辨识法：看端头定真身】\n**在库房认PE件，别死记名字，先看端头。**\n端头是光秃秃圆柱面的，就是纯热熔件；端头带金属圆盘（法兰）的，是法兰头；端头带铜色螺纹的，是内外丝直接。\n只要认清端头，哪怕别人给你拿错了，你也能一眼退回去。\n【PE 管件逐块讲透：端头为什么决定接法】\n**你在库房认 PE 件，先看端头再想名字，端头决定它怎么接。** 这是本课最省事的一条捷径。\n**纯热熔件两头是光平口，靠把管子和管件的塑料面一起烫软再压合。** 打个比方，像两块蜡受热粘成一块；它没有螺纹，缠生料带（聚四氟乙烯密封带）纯属白费。\n**PE法兰头/片一端是 PE 可熔端、一端是带孔金属盘，是塑料管与铁阀门之间的翻译官。** 落回卡上：看「PE法兰头/片」卡的连接方式，一端热熔、一端法兰写在同一张卡。\n**内外丝直接内部注塑了铜嵌件，靠金属螺纹去接小水表或丝口阀门。** 你把 PE 管硬套在铁管上，接口必漏；嵌件就是给塑料管装了一副能咬合的牙。\n**管帽是热熔平口封堵件，靠熔接封死管端。** 临时口、预留口先封后接，比胶带木塞可靠；要用时切掉重熔，不伤管材。\n**看端头定真身的顺序是：光平口→热熔，带圆盘→法兰，带铜牙→丝接。** 别人拿错件，你照这个顺序一眼就能退回去。\n【PE 管件端头 × 接法 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n光平口｜PE弯头/PE三通/PE直接/PE大小头（异径管）｜热熔机对接｜平口件绝不能缠生料带（聚四氟乙烯密封带）。\n带孔金属圆盘｜PE法兰头/片｜PE 端热熔 + 盘端穿螺栓加胶垫（法兰橡胶垫片）｜孔距与 PN 一起核，逐档数值以卡面与现行标准核定为准。\n带铜色内螺纹｜PE内丝直接｜顺螺纹缠生料带（聚四氟乙烯密封带）接外丝设备｜留第一扣不缠，防碎屑进表。\n带铜色外螺纹｜PE外丝直接｜缠带后拧进内丝件｜别缠太厚，防撑裂嵌件。\n平口封堵｜PE管帽（堵头）｜热熔封住管端/预留口｜临时口必须熔接封堵，别用胶带木塞。\n**【红线】端头认错就是接法认错：平口件拿去拧丝口、法兰头拿去热熔，现场都装不上。**\n落回卡上：把「PE弯头」「PE法兰头/片」「PE内丝直接」「PE管帽（堵头）」四张卡的连接方式栏并排看，端头与接法一一对应。\n\n**自测：PE 平口件缠上生料带，能不能和金属螺纹接上？** 回本课【防呆辨识法：看端头定真身】对照。\n\n**自测：PE 管要接铁件，正确的过渡件是什么？** 回本课【跨材质转换：连金属怎么接】对照。","structure":"记形状：PE弯头转弯，PE三通分叉，大小头变径。\n记转换：法兰头接大铁件，内外丝接小水表。\n记封堵：临时管口用PE管帽熔接封死。\n看端头：平口靠热熔机，带盘靠螺栓，带丝靠生料带。\n引导：本课已按端头把四类 PE 件认全；现场常卡在「平口件被拿去拧丝口」；下一步 C03 讲这些件到底怎么接。","anchors":[{"name":"PE弯头","ref":"PE弯头"},{"name":"PE三通","ref":"PE三通"},{"name":"PE大小头（异径管）","ref":"PE大小头（异径管）"},{"name":"PE直接","ref":"PE直接"},{"name":"PE法兰头/片","ref":"PE法兰头/片"},{"name":"PE内丝直接","ref":"PE内丝直接"},{"name":"PE外丝直接","ref":"PE外丝直接"},{"name":"PE管帽（堵头）","ref":"PE管帽（堵头）"}],"pitfall":"【PE平口件绝不能缠生料带】平口件只能热熔，缠了生料带也接不上；接铁件必须用带螺纹的嵌件或法兰头。","remark":"—","seq":13,"family":"PE 管材·管件·连接","lessonNo":4},{"id":"C04","sub":"XG-01","topic":"球墨铸铁管本体：外观防腐与承插口判别","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课专讲球墨铸铁直管。解决新员工对球铁管长什么样、防腐怎么做、胶圈怎么认、壁厚怎么分的基础认知，建立直观的第一印象。","framework":"外观特征｜黑色直管与水泥内衬。防腐体系｜外锌加沥青，内水泥或环氧。柔性接口｜承口、插口与T/K型胶圈的配合。壁厚等级｜K9与K8的区别。存放禁忌｜防重压与防腐层保护。\n球墨铸铁管逐块讲透：防腐、接口与壁厚的因果链｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n球铁管验收 逐项核对表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C02《PE管件图谱》；向下接 C07《钢管管材通识》。**\n\n**现场情境：一堆球墨管，有的标 K9 有的标 K8，承口还分 T 型和 K 型。** 壁厚怎么选、胶圈怎么配？本课讲清。\n\n【球墨管为什么又强又韧：球化率与离心铸造】\n**球墨铸铁管号称“铁的本质、钢的性能”，秘密就在石墨的形状。** 普通灰铁的石墨是一片片刀刃状、容易开裂；球铁在铁水里加了球化剂，石墨变成一颗颗圆球，不再割裂金属，所以又强又韧。合格品球化率要达到 80% 以上（球化等级 1-3 级），管身是用离心机高速旋转浇铸出来的，组织致密。\n\n【内壁防腐不止一种：三种内衬材料】\n**球铁管内衬不只有水泥砂浆一种，选错会影响水质和成本。** 常规给水用水泥砂浆内衬，最普遍；饮用水或对水质要求高的场合可用环氧树脂内衬，表面更光滑、不析出；高端、低 VOCs 场合用聚氨酯内衬。看到内衬颜色不一样别以为是次品，先按水质和口径核对材质。\n\n【承插接口不止 T 型 K 型：还有 N1 型、S 型】\n**别以为球铁管接口只有 T 型和 K 型，完整柔性接口系列还有 N1 型、S 型。** T 型是推入式、K 型带压兰，N1 型和 S 型在密封结构和允许的偏转角度上各有不同，用于不同地基和工况。遇到不认识的接口型式，先查标准图，不要硬套 T/K 的装法。\n\n【K 级壁厚怎么算：数字越大管越厚】\n**K9、K8 的壁厚不是随口定的，有公式：e＝K×（0.5＋0.001×DN）。** e 是壁厚毫米数，DN 是公称直径，K 是壁厚等级系数——K9 就是取 9，K 越大壁越厚、越耐压。K9 是国标主力，K8 偏薄属非标；图纸要 K9 你发 K8，埋深受压就变形。逐档壁厚与承压值由技术部门按现行标准核定。\n\n【外观特征与防腐体系】\n你在工地看到的球墨铸铁管是沉重的直管，颜色是沥青黑。\n往管子里看，内壁有一层灰白色的水泥，这是防生锈的水泥内衬（水质特殊时升级为环氧陶瓷）。外面的黑漆是锌加沥青，用来抗土壤腐蚀。防腐层就是球铁管的命根子，卸管时绝不能拿钢丝绳硬勒。\n\n【柔性接口：承口与插口】\n球铁管一头粗一头细，粗的是承口，细的是插口。\n承口里面有个凹槽，用来塞橡胶圈。把插口插进承口，靠橡胶圈挤压封水。这种柔性接口允许微小偏转，遇到地基沉降不会被扯断，这是它能称霸地下管网的原因。\n\n【胶圈（球墨管承插密封圈）分T型与K型】\n承插密封全靠胶圈，胶圈分两种。T型是推入式，像个实心唇边，直接塞进槽里，插口硬推进去就行。K型是机械式，胶圈外面还要加一个金属压兰，用螺栓把压兰拧紧，压着胶圈变形密封。\n【T型靠推，K型靠压】。高压或大口径常用K型，低压常用T型。\n\n【壁厚等级：K9与K8】\n管身喷码除了国标号，还有K9、K8等。K代表壁厚等级，数字越大管壁越厚。\n【K9是主力，K8偏薄】。如果图纸要K9，你发了K8，埋深受压时管子容易变形甚至爆裂。\n\n【执行标准与存放】\n认准管身喷码GB/T 13295。存放时地面要平，绝不能把承口压扁，否则胶圈（球墨管承插密封圈）根本塞不进去。\n【球墨铸铁管逐块讲透：防腐、接口与壁厚的因果链】\n**球铁管是沉重的沥青黑直管，内壁那层灰白水泥是水泥砂浆内衬。** 它防的是水把铁管锈穿、结垢堵水；落回卡上：看「球墨铸铁管」卡的内衬类型字段。\n**外面黑漆是锌层加沥青，抗的是土壤腐蚀；防腐层就是球铁管的命根子。** 打个比方，像给铁管穿了雨衣，钢丝绳一勒破个口，地下水就顺着烂进去。\n**承口粗、插口细，靠塞在承口凹槽里的胶圈（球墨管承插密封圈）挤压封水。** 这种柔性接口允许微小偏转，地基沉降时不会被硬扯断，这是它称霸地下管网的原因。\n**T 型胶圈（球墨管承插密封圈）靠插口硬推进去，K 型还要加金属压兰用螺栓拧紧压变形。** 高压或大口径常用 K 型，低压常用 T 型；你分不清 T/K，胶圈根本装不进槽。\n**K9、K8 是壁厚等级，数字越大管壁越厚；图纸要 K9 你发 K8，埋深受压就变形。** 别把壁厚等级当成口径等级，喷码上两码事。\n**管身喷码是这根管的身份证：标准号、壁厚等级、口径都在上面。** 喷码模糊或没有国标号，先待检，不凭「都是黑管」放行。\n【球铁管验收 逐项核对表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n内壁｜水泥砂浆内衬（水质特殊可升级环氧陶瓷）｜看连续、无脱落｜内衬破损先待检。\n外壁｜锌层 + 沥青终饰｜看有无划伤露铁｜卸管严禁钢丝绳硬勒。\n接口｜承口 / 插口 + T 型或 K 型胶圈（球墨管承插密封圈）｜承口凹槽完好、插口端面无磕碰｜承口压扁这根管就废了。\n壁厚｜喷码 K9 / K8 等｜按图纸等级核，别凭眼估｜逐档壁厚与承压值由技术部门按现行标准核定。\n标识｜管身喷码 GB/T 13295 及等级｜编号与单据对得上｜关注换版提示：2027-03-01 后切换 GB/T 13295-2026，以卡面与主管部门要求为准。\n**【红线】防腐层一破就生锈、承口一压扁就报废、K8 不能当 K9 发；三样都是不可逆损伤。**\n落回卡上：「球墨铸铁管」卡的内衬类型、外防腐锌层、执行标准与状态栏，一张卡就能把这五项对全。\n\n**自测：K9 和 K8 哪个壁更厚，能不能混着用？** 回本课【壁厚等级：K9与K8】对照。\n\n**自测：T 型和 K 型胶圈分不清，硬装会怎样？** 回本课【胶圈（球墨管承插密封圈）分T型与K型】对照。","structure":"外观：黑直管，内壁灰白水泥。\n接口：粗头承口，细头插口，靠胶圈密封。\n胶圈：T型推入，K型压兰螺栓锁紧。\n壁厚：K9比K8厚，承压更强。\n禁忌：卸管防勒防腐层，存放防压扁承口。\n引导：本课已把球铁管的防腐、接口与壁厚连成一条链；现场常卡在「K8 当 K9 发」；下一步 C05 讲球铁管件端头。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"}],"pitfall":"【K9比K8厚，T型推K型压】防腐层一破就生锈；承口一旦被压变形，这根管子就废了；分不清T/K型，胶圈装不进。","remark":"—","seq":14,"family":"球墨铸铁管及管件","lessonNo":5},{"id":"C07","sub":"XG-01","topic":"钢管管材通识：直缝管、螺旋管的外观与防腐辨别","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课专讲钢管管材。钢管在管网里多用于泵房、过河架空等高压场景。重点解决新员工对直缝管与螺旋管的区别、以及内外防腐怎么做的基础认知。","framework":"外观与分类｜直缝管与螺旋管。材质与口径｜碳钢与大口径优势。防腐体系｜内环氧/水泥，外3PE/沥青。执行标准｜管身喷码与国标。存放禁忌｜防腐层防碰撞。\n钢管管材逐块讲透：焊缝、防腐与高压场景的因果｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n钢管验收 逐项核对表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C04《球墨铸铁管本体》；向下接 C10《PPR管材通识》。**\n\n**现场情境：过河段要选钢管，现场有直缝和螺旋两种，防腐层还有磕碰。** 看什么分类型、防腐破了会怎样？本课讲透。\n\n【直缝焊还是螺旋焊：看焊缝认工艺】\n**直缝管和螺旋管的差别就在那条焊缝上。** 直缝管焊缝是一条直线、尺寸精度高、承压稳定；螺旋管焊缝绕着管子转圈，能用窄带钢卷成大口径、成本有优势。看管身焊缝走向就能分清：一条直线是直缝，一圈螺旋线是螺旋焊。\n\n【镀锌管不能当室内给水管用】\n**新建室内生活给水已不许用镀锌钢管，见到要警惕。** 镀锌管时间一长内壁锈蚀、出水发黄，锌层析出还影响水质，现在都被衬塑管、涂塑管替代。现场若发现室内给水装了镀锌管，多半是违规，先拍照上报再处理。\n\n【外观与分类：直缝与螺旋】\n在库房看到表面涂着防腐层的铁管，就是钢管。\n看焊缝。如果是笔直的一条纵缝，叫直缝焊接钢管，通常口径较小，用在泵房内。如果焊缝像弹簧一样打着圈，叫螺旋缝焊接钢管，它可以做得非常大，像马路上的大粗管。\n\n【防腐体系：钢管的保命衣】\n钢管极容易生锈，内外都要防腐。\n内防腐是贴着水那层，常涂环氧树脂或水泥砂浆。外防腐是接触土壤那层，最常用的是3PE防腐，也就是裹了几层塑料，或者涂环氧煤沥青。防腐层一旦破损，地下水就会顺着破洞把钢管烂穿。\n\n【高压与大流量的担当】\n为什么不用塑料管？因为钢管能承受极高的压力。比如水泵出口的急剧水锤，钢管能扛得住，而塑料管会爆裂。所以泵房设备连接、长距离大流量输水、或者过河架空，首选钢管。\n\n【存放与验收】\n认准管身喷码和防腐层标志。存放时底部要垫软物。\n【严禁钢丝绳直接勒吊】。防腐层碰破一点，整根管子的寿命就打折扣。这和球墨铸铁管的防腐保护一样重要。\n【钢管管材逐块讲透：焊缝、防腐与高压场景的因果】\n**认钢管先看焊缝：笔直一条纵缝是直缝焊接钢管，绕圈像弹簧的是螺旋缝焊接钢管。** 落回卡上：看「直缝焊接钢管」「螺旋缝焊接钢管」两张卡的结构描述。\n**直缝管口径偏小多用于泵房内，螺旋管能做得非常大用于长距离大口径。** 焊缝形态不是好看不好看，它决定了这根管能用到哪个场景。\n**内防腐贴着水、外防腐贴着土，两层各管一头。** 内涂环氧或水泥砂浆防结垢，外裹 3PE 或环氧煤沥青抗土壤腐蚀；破一个口，地下水就顺着把钢管烂穿。\n**泵房水锤、长距离大流量、过河架空首选钢管，是因为它能扛极高压力。** 打个比方，塑料管像气球、钢管像铁筒，同样一记水锤，结果完全不同。\n**卸管严禁钢丝绳直接勒吊，底部要垫软物。** 防腐层碰破一点，整根管的寿命就打折扣，这跟球铁管防腐保护是同一条底线。\n【钢管验收 逐项核对表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n焊缝｜直缝 / 螺旋缝｜看是纵缝还是绕圈线｜按设计口径与场景选，别混用。\n内防腐｜环氧树脂 / 水泥砂浆｜看连续、无脱层｜内壁结垢会缩径、影响水质。\n外防腐｜3PE / 环氧煤沥青｜看划伤、鼓包、露铁｜破损点埋地后先烂这一处。\n标识｜管身喷码与防腐层标志｜标准号、规格对单据｜喷码不清先待检。\n吊装｜软吊带 + 垫软物｜严禁钢丝绳硬勒｜碰破防腐层即判外观异常。\n**【红线】防腐层破了钢管烂得极快；过河高压才用钢管；严禁钢丝绳硬勒防腐层。**\n落回卡上：「直缝焊接钢管」与「螺旋缝焊接钢管」两张卡的常用规格与执行标准栏，把口径范围和防腐体系一起核。\n\n**自测：怎么一眼分辨直缝管和螺旋管？** 回本课【外观与分类：直缝与螺旋】对照。\n\n**自测：钢丝绳直接勒在防腐层上搬运，后果是什么？** 回本课【防腐体系：钢管的保命衣】对照。","structure":"外观：看焊缝分直缝和螺旋管。\n防腐：内涂环氧/水泥，外裹3PE防锈。\n用途：高压、泵房、过河架空首选。\n存放：严禁钢丝绳勒吊，防防腐层破损。\n引导：本课已把焊缝、防腐与高压场景对应起来；现场常卡在「防腐层被钢丝绳勒破」；下一步 C08 讲钢管法兰与管件。","anchors":[{"name":"直缝焊接钢管","ref":"直缝焊接钢管"},{"name":"螺旋缝焊接钢管","ref":"螺旋缝焊接钢管"}],"pitfall":"【看焊缝分直缝和螺旋】防腐层破了钢管烂得极快，严禁钢丝绳硬勒防腐层；过河高压才用钢管。","remark":"—","seq":15,"family":"钢管及法兰焊接","lessonNo":6},{"id":"C10","sub":"XG-01","topic":"PPR管材通识：外观、温度限制与承压规格","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课专讲PPR给水管。PPR是建筑室内供水的主力，重点解决新员工对它的材质特性、冷热水适用边界以及外观判别的认知。","framework":"外观特征｜绿色/白色直管与蓝红线。材质特性｜耐热不耐晒。温度边界｜长期70度，瞬间95度。承压规格｜S2.5到S5的壁厚区分。执行标准｜GB/T 18742。\nPPR 管材逐块讲透：耐热、怕晒与 S 系列的因果｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\nPPR 规格 × 用途 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C07《钢管管材通识》；向下接 C11《PPR管件图谱》。**\n\n**现场情境：装修队拿冷水管去接热水器的热水管，还说 PPR 耐热没问题。** 能不能换用？本课讲温度红线。\n\n【PPR 热熔温度 260±5℃：高了碳化、低了不牢】\n**PPR 靠热熔连接，温度和时间是关键。** 通用工艺窗口是 260±5℃，温度过高塑料会碳化发黑、过低又熔不牢；热熔后按规定时间冷却，冷却期间不能拧动。具体加热时长按现行工艺规范执行。\n\n【S 系列和 SDR 怎么换算】\n**PPR 管身上的 S5、S3.2 是管系列，和 SDR 能互相换算。** S＝公称外径÷壁厚，SDR＝2S＋1，比如 S5 对应 SDR11、S3.2 对应 SDR7.4。S 值越小壁越厚、越耐压。搞懂换算，才不会把两种标注当成两种管子。\n\n【外观特征：建筑室内的主力】\n你在楼道或户内看到的绿色或白色、摸起来硬邦邦的直管，通常就是PPR。管身一般印有蓝色的冷水线或红色的热水线。\nPE管是黑色带蓝线的6m直管，PPR多为绿白直管、带红蓝冷热水线，两者靠颜色和标线区分，PPR因为材质较硬。\n\n【材质特性：耐热但不耐晒】\nPPR的学名是无规共聚聚丙烯，最大的优点是耐热。\n它非常适合做建筑内部的冷热水管，但【PPR极度怕紫外线】，如果明装在室外暴晒，很快就会老化变脆。在库房必须避光存放。\n\n【温度边界：70度是红线】\n材料卡上明确写了，长期工作水温不能超过70度，瞬间峰值不能超过95度。\n【不能把PPR用于集中供暖的高温主干管】，温度一旦超标，管子会变软、变形、甚至爆裂。\n\n【承压规格：S系列】\n看管身上的S2.5、S3.2、S4、S5。\n这里的S和PE管的SDR类似，S的数值越小，管壁越厚，承压越高。S2.5通常是热水管，S5多为冷水管。\n热水系统如果用错薄壁的冷水管（S5），受热后承压能力骤降，极易爆管。\n【PPR 管材逐块讲透：耐热、怕晒与 S 系列的因果】\n**你在楼道或户内看到的绿/白硬直管就是 PPR，管身印蓝线走冷水、红线走热水。** 落回卡上：看「PPR给水管」卡的外观与标识栏。\n**PPR 学名无规共聚聚丙烯，最大优点是耐热，最大弱点是怕紫外线。** 打个比方，它像怕晒的塑料布，明装室外暴晒很快老化变脆，库房必须避光。\n**长期工作水温不能超过 70 度、瞬间峰值不能超过 95 度，这是红线。** 温度一超标管子会变软变形甚至爆裂，所以不能拿去当集中供暖高温主干管。\n**S2.5、S3.2、S4、S5 是壁厚系列，S 数值越小管壁越厚、承压越高。** 它和 PE 管的 SDR 是同一套思路：外径定死后，壁越厚越扛压。\n**S2.5 常做热水管、S5 多为冷水管；热水系统错用 S5，受热后承压骤降极易爆管。** 别只按口径发料，S 系列要和用途一起核。\n【PPR 规格 × 用途 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\nS2.5｜壁最厚、承压最高｜热水管常用｜热水段优先，逐档承压值由技术部门按现行标准核定。\nS3.2 / S4｜中间档｜冷热水分界按设计｜别凭颜色判断系列，看管身喷码。\nS5｜壁最薄｜冷水管常用｜禁止用在热水系统。\n温度边界｜长期 ≤70℃、瞬间 ≤95℃｜核对介质温度｜超温即变形爆管，不用作高温供暖。\n存放｜避光、室内｜严禁室外明装暴晒｜老化变脆的管一律待检。\n**【红线】S 数值越小壁越厚；冷水管不能当热水管；长期水温不能超 70 度；暴晒必老化。**\n落回卡上：「PPR给水管」卡的温度限制、S 系列与执行标准 GB/T 18742 三个字段，一张卡就能把这四项对全。\n\n**自测：长期水温超过 70 度，PPR 管会怎样？** 回本课【温度边界：70度是红线】对照。\n\n**自测：S2.5 和 S5 哪个壁更厚、分别适合什么压力？** 回本课【承压规格：S系列】对照。","structure":"看外观：绿/白直管，带冷热水线。\n材质：耐热适合室内冷热水，极怕暴晒。\n温度：长期≤70度，不能用于高温供暖。\n规格：S数值越小，壁厚越大，承压越高。\n引导：本课已把耐热、怕晒与 S 系列的因果讲透；现场常卡在「S5 冷水管上了热水系统」；下一步 C11 讲 PPR 管件。","anchors":[{"name":"PPR给水管","ref":"PPR给水管"}],"pitfall":"【S数值越小壁厚越厚】PPR耐热但不耐晒；长期水温不能超70度；冷水管不能当热水管用。","remark":"—","seq":16,"family":"PPR 管材·管件·连接","lessonNo":7},{"id":"C11","sub":"XG-01","topic":"PPR管件图谱：热熔件、铜嵌件与活接转换","level":"D2 / L2","d":"D2","l":"L2","positioning":"PPR管件长得像，但端头大有文章。这一课教新员工认清光秃秃的热熔件、带铜牙的内外丝件、带螺母的活接，以及用来接大设备的法兰。","framework":"基础热熔件｜弯头、三通、直接、管帽。铜嵌件管件｜内丝直接、外丝直接。可拆连接｜PPR活接头。设备转换｜PPR法兰。辨识方法｜看端头有没有铜牙或螺母。\nPPR 管件逐块讲透：端头上的铜牙、螺母与法兰盘｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\nPPR 管件端头 × 接法 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C10《PPR管材通识》；向下接 C13《衬塑复合管材》。**\n\n**现场情境：要装一个能拆下来检修的 PPR 接口，手边有平口件、铜嵌件和活接头。** 选哪个才对？本课看端头认件。\n\n【铜嵌件看材质和结构：防漏又防转】\n**PPR 管件里的铜嵌件用来接金属件，好坏差别很大。** 优质件用精铜（如 62# 铜）、多道电镀，还带防漏凹槽和防转燕尾结构，防止铜塑分离、丝口打滑。拿手掂一掂、看镀层和凹槽，劣质铜嵌件用不了多久就从丝口处漏水。\n\n【基础热熔件：转弯与分叉】\n两头平口的绿/白管件。包括弯头（90/45度）、三通、直接接长、大小头变径，还有封堵管口的管帽。\n和PE件一样，它们全靠热熔机烫软后插接。\n\n【铜嵌件件：连接金属的桥梁】\nPPR管怎么接水龙头或金属阀门？用内丝直接或外丝直接。\n看端头，有一圈铜色的金属螺纹，这就是嵌件件。现场缠上生料带（聚四氟乙烯密封带）就能和金属对接。如果拿平口的PPR件去接金属水龙头，根本装不上。\n\n【可拆连接：PPR活接头】\n这里有一大类叫活接头（内丝/外丝）。它中间有个塑料大螺母，拧开就断。\n它一头热熔接管子，另一头是丝扣接设备。好处是【设备坏了需要更换时，拧开活接螺母就行】，不用把管子剪断重新热熔。\n\n【设备转换：PPR法兰】\n如果要接大口径的铸铁法兰阀门或水泵，得用PPR法兰。\n一头是PPR平口可热熔，另一头是带螺栓孔的塑料法兰盘。中间夹垫片，穿螺栓压紧。\n【PPR 管件逐块讲透：端头上的铜牙、螺母与法兰盘】\n**认 PPR 件还是先盯端头：光平口是热熔、带铜牙是丝接、带大螺母是活接、带盘是法兰。** 四类端头对应四种接法。\n**弯头、三通、直接、大小头、管帽两头都是平口，全靠热熔机烫软后插接。** 和 PE 件同一套逻辑，千万别拿去拧水龙头。\n**内丝/外丝直接端头有一圈铜色金属螺纹，是塑料管接金属设备的桥梁。** 缠上生料带（聚四氟乙烯密封带）就能对接水龙头或铁阀门，这就是嵌件件的用处。\n**活接头中间那个塑料大螺母，拧开就能断开，不用剪断管子重新热熔。** 打比方，像给水管装了个可拆的插扣；设备坏了换件最省事的就是它。\n**PPR 法兰一头是平口可热熔、另一头是带螺栓孔的塑料盘。** 接大口径铸铁法兰阀门或水泵时，中间夹垫片、穿螺栓压紧。\n【PPR 管件端头 × 接法 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n光平口｜弯头、三通、直接、管帽｜热熔承插｜加热时间适中，防缩径。\n带铜色内/外螺纹｜PPR内丝直接、PPR外丝直接｜顺螺纹缠生料带（聚四氟乙烯密封带）接金属｜留第一扣，别缠太厚。\n带塑料大螺母｜PPR活接头（内丝/外丝直接）｜靠内部平垫片密封、可拆｜漏水先换垫片，别死拧丝口。\n带孔塑料盘｜PPR法兰（法兰转换）｜夹垫片穿螺栓接大设备｜孔距与 PN 一起核，逐档数值以核定为准。\n**【红线】平口件绝不能拧水龙头；活接漏水先查垫片；带盘件别当成热熔件。**\n落回卡上：把「PPR弯头」「PPR内丝直接」「PPR活接头（内丝/外丝直接）」「PPR法兰（法兰转换）」四张卡的连接方式栏并排看。\n\n**自测：带铜牙的 PPR 件是干什么用的？** 回本课【铜嵌件件：连接金属的桥梁】对照。\n\n**自测：想以后能拆开检修，该用哪种管件？** 回本课【可拆连接：PPR活接头】对照。","structure":"热熔件：弯头三通直接，两头平口。\n铜嵌件：内外丝直接，带金属牙，接水龙头。\n活接头：带大螺母，方便拆卸维修。\n法兰：一头热熔一头带盘，接大阀门。\n引导：本课已按端头把四类 PPR 件认全；现场常卡在「平口件拿去拧水龙头」；下一步 C12 讲 PPR 连接工艺。","anchors":[{"name":"PPR弯头","ref":"PPR弯头"},{"name":"PPR三通","ref":"PPR三通"},{"name":"PPR管帽","ref":"PPR管帽（堵头）"},{"name":"PPR内丝直接","ref":"PPR内丝直接"},{"name":"PPR外丝直接","ref":"PPR外丝直接"},{"name":"PPR活接头（内丝/外丝直接）","ref":"PPR活接头（内丝/外丝直接）"},{"name":"PPR法兰（法兰转换）","ref":"PPR法兰（法兰转换）"}],"pitfall":"【看端头认件】带铜牙的接金属，带螺母的能拆卸；千万别拿光秃秃的平口件去拧水龙头。","remark":"—","seq":17,"family":"PPR 管材·管件·连接","lessonNo":8},{"id":"C13","sub":"XG-01","topic":"衬塑复合管材：钢塑结构、防腐优势与连接禁忌","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课专讲衬塑复合管本体。它外表是钢铁，内里是塑料。重点解决新员工对钢塑结合原理、外观判别以及施工不可逆损伤的认知。","framework":"外观与结构｜外镀锌钢管，内衬塑料。材质优势｜钢的强度与塑的防腐。连接方式｜丝接、沟槽与法兰。施工禁忌｜高温破坏与界面离层。执行标准｜GB/T 28897。\n衬塑复合管逐块讲透：外刚内柔与不可逆损伤｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n衬塑管 施工禁忌 × 后果 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C11《PPR管件图谱》；向下接 C14《衬塑丝接管件（一）》。**\n\n**现场情境：工人图快，用电焊去切衬塑复合管。** 这一刀下去会怎样？本课讲内衬这个命门。\n\n【内衬材质 PE/PP/PO：耐温各不同】\n**钢衬管的“衬”不是一种料，PE、PP、PO 耐温耐蚀各不一样。** 钢衬 PE 用到 60℃ 以内、钢衬 PP 能到 80℃、钢衬 PO 耐酸碱更强。给水最常用 PE，热水或化工介质要按温度和腐蚀性选对材质，选错了内衬会软化或开裂。\n\n【衬塑和涂塑是两种工艺】\n**衬塑、涂塑听着像一回事，其实是两种做法。** 衬塑是塞入成型塑料管、塑层厚（2-5mm）、外壁不带塑、不能直接埋地；涂塑是粉末喷涂成薄膜、可内外双面、可埋地。看管口塑层厚度和外壁有没有塑，就能分清是哪种。\n\n【外观与结构：外刚内柔】\n你在库房看到的衬塑管，外表看起来像普通的镀锌钢管，但往管子里看，内壁有一层光滑的白色（PE）或浅绿色（PPR）塑料层。\n这就是它兼钢的强度与塑的耐腐蚀的根本。\n\n【材质优势：替代纯钢与纯塑】\n纯钢管容易生锈结垢，纯塑料管在高层高压下容易变形。\n衬塑管既有钢管的硬骨头，能承受高压，内壁的塑料层又保证水质不结垢。常用于高层建筑给水、化工介质输送。\n\n【施工禁忌：内衬是命门】\n它的致命弱点是内衬容易被破坏。\n绝对禁止用电焊或气割。高温不仅会直接烧化塑料，更会破坏钢管与塑料的粘结界面，导致钢塑离层，内衬脱落堵水。\n也绝对禁止用普通高速砂轮切割机切割。切割产生的瞬时高温会使管口内衬碳化。现场只能用专用的低速割管机或手工锯，切完后还要用专用铰刀清理毛刺。\n\n【连接方式概览】\n小口径（DN15-DN100）多用丝扣连接；大口径（DN65以上）用沟槽卡箍（刚性/柔性）；接大设备则用带塑料密封面的衬塑法兰。\n【衬塑复合管逐块讲透：外刚内柔与不可逆损伤】\n**你看衬塑管外表像镀锌钢管，往里看有一层白（PE）或浅绿（PPR）塑料，这就是「外刚内柔」。** 落回卡上：看「衬塑复合管」卡的结构组成栏。\n**纯钢管易锈结垢、纯塑管高层高压易变形，衬塑管是两边取长。** 打个比方，钢是骨头、塑是内衬衣；骨头扛压，衬衣保水质不结垢。\n**它的命门是内衬：绝对禁止电焊气割，高温会烧化塑料、破坏钢塑粘结界面导致离层脱落。** 一离层，内衬掉下来直接堵水，且不可逆。\n**也绝对禁止普通高速砂轮切割，瞬时高温会让管口内衬碳化。** 现场只能用低速割管机或手工锯，切完还要用专用铰刀清毛刺。\n**连接方式按口径分：小口径 DN15–DN100 多丝扣，大口径沟槽卡箍（刚性/柔性），接大设备用衬塑法兰。** 落回卡上：看「衬塑复合管」卡的连接方式栏，丝接/法兰都在同一张卡。\n**执行标准看 GB/T 28897-2021，衬塑管材/管件按该标准附录 B。** 标准号对不上先待检，不凭「都是衬塑管」放行。\n【衬塑管 施工禁忌 × 后果 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n电焊 / 气割｜严禁｜烧化内衬、钢塑离层｜内衬脱落堵水，整段报废。\n普通高速砂轮切割｜严禁｜管口瞬时高温碳化｜只能用低速割管机或手锯。\n切割后毛刺｜专用铰刀清理｜毛刺会挂住衬层、缩径｜清完再看管口衬层是否完整。\n小口径连接｜丝扣｜看丝扣规整、内衬翻边完整｜丝接件不能焊。\n大口径连接｜沟槽 / 衬塑法兰｜卡箍胶圈不扭曲、法兰加软垫片｜严禁普通钢法兰（平焊/对焊）焊上去代替。\n**【红线】严禁电焊气割、严禁普通砂轮切割；切管必须冷切割并清毛刺，高温损伤一律不可逆。**\n落回卡上：「衬塑复合管」卡的执行标准 GB/T 28897-2021（附录 B）、DN15–DN300、PN10/16 与连接方式栏，一张卡把这五项对全。\n\n**自测：为什么严禁用电焊和普通砂轮切衬塑管？** 回本课【施工禁忌：内衬是命门】对照。\n\n**自测：衬塑管外刚内柔，优势体现在哪？** 回本课【材质优势：替代纯钢与纯塑】对照。","structure":"看结构：外有镀锌钢，内有白/绿塑料衬层。\n知优势：承压高、不结垢、水质好。\n守禁忌：严禁电焊气割，严禁普通砂轮切割。\n认连接：小口径丝接，大口径沟槽。\n引导：本课已把外刚内柔与不可逆损伤讲透；现场常卡在「拿砂轮片切衬塑管」；下一步 C14 讲衬塑丝接基础件。","anchors":[{"name":"衬塑复合管","ref":"衬塑复合管"}],"pitfall":"【严禁电焊和普通砂轮切割】高温会导致钢塑离层、内衬碳化；切管必须用专用工具并处理毛刺。","remark":"—","seq":18,"family":"衬塑复合及丝扣/沟槽","lessonNo":9},{"id":"C14","sub":"XG-01","topic":"衬塑丝接管件（一）：基础形状与变径转换","level":"D2 / L2","d":"D2","l":"L2","positioning":"小口径衬塑管多靠丝扣连接。这一课讲最基础的丝接管件。重点教新员工认准带丝扣的端头，以及可锻铸铁（玛钢）基体的特征。","framework":"基础形状件｜弯头、三通、管帽。变径转换｜大小头、补芯。材质与标准｜可锻铸铁基体与CJ/T 137。辨识方法｜看内壁衬塑与丝扣。\n衬塑丝接基础件逐块讲透：看内壁、认方向｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n丝接基础件 × 用法 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C13《衬塑复合管材》；向下接 C18《Y型过滤器》。**\n\n**现场情境：一段小管道要变径并封堵末端，手边有补芯和管帽。** 补芯内外丝怎么分方向？本课讲看内壁认方向。\n\n【丝口代号 R/Rc/Rp：内外丝别拧错】\n**管螺纹有代号，认错了内外丝就拧不紧或漏水。** R 是圆锥外螺纹、Rc 是圆锥内螺纹、Rp 是圆柱内螺纹。锥对锥、柱对柱要按规矩配，图纸和管件上都标着代号，配之前先对一眼，别凭“看着差不多”硬拧。\n\n【基础形状：小管道的转弯与分叉】\n衬塑丝接管件大多用可锻铸铁（玛钢）制作，外表镀锌，内部衬塑。\n外观与普通镀锌玛钢件相似，但看内壁有一层塑料。用来在室内管道转弯（弯头）和分叉（三通）。\n\n【管帽与衬塑堵头：封堵末端】\n如果管路试压或者有预留口，用管帽（衬塑堵头）拧上去封死。注意看内壁，它也有防腐塑料层。\n\n【变径转换：大小头与补芯】\n管道要变细怎么办？\n用大小头（异径管）。如果空间特别小，用补芯。补芯是一端外丝，一端内丝。\n记住方向：外丝端朝大径，拧进大管件的内丝里；内丝端朝小径，接纳小管子的外丝。丝接件绝对不能强行焊接，一焊就穿。\n\n【执行标准与基体】\n除了钢塑复合管标准，玛钢件基体还要参照CJ/T 137。验收时看丝扣是否规整，内衬是否有脱落。\n【衬塑丝接基础件逐块讲透：看内壁、认方向】\n**衬塑丝接件多用可锻铸铁（玛钢）做基体，外表镀锌、内部衬塑。** 落回卡上：看「衬塑丝接弯头」「衬塑丝接三通」两张卡，外观像普通镀锌件，区别在内壁那层塑料。\n**认它别只看外形，要看内壁有没有衬塑层、丝扣规不规整。** 打个比方，像给铁件穿了件塑料内衬衣；内衬脱落或丝扣乱牙，装上就漏。\n**弯头转弯、三通分叉、管帽（衬塑堵头）封末端，管帽内壁同样有防腐塑料层。** 试压或预留口必须封死，用普通铁衬塑堵头会锈穿。\n**变细用大小头（异径管），空间特别小用补芯；补芯一端外丝、一端内丝。** 记住方向：外丝端朝大径拧进大管件内丝，内丝端朝小径接纳小管外丝。\n**丝接件绝对不能强行焊接，一焊就穿。** 玛钢件基体还要参照 CJ/T 137，标准号与内衬状态一起核。\n【丝接基础件 × 用法 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n转弯｜衬塑丝接弯头｜按角度选｜内壁衬塑完整、丝扣规整。\n分叉｜衬塑丝接三通｜数清三端丝别｜别拿成弯头。\n封堵｜衬塑堵头｜试压 / 预留口封死｜内壁有衬层，别用普通铁件。\n变径｜衬塑丝接异径管（大小头）｜大变小过渡｜看两端丝别与口径。\n省空间变径｜衬塑内外丝补芯（变径补芯）｜外丝朝大、内丝朝小｜方向反了装不上。\n禁止动作｜电焊 / 气割｜严禁｜一焊就穿，衬层必毁。\n**【红线】补芯外丝朝大、内丝朝小；丝接件坚决不能上电焊；看内衬有没有破损。**\n落回卡上：把「衬塑丝接弯头」「衬塑丝接三通」「衬塑堵头」「衬塑内外丝补芯（变径补芯）」「衬塑丝接异径管（大小头）」五张卡的端头与内衬栏并排看。\n\n**自测：补芯的外丝和内丝分别朝哪边？** 回本课【变径转换：大小头与补芯】对照。\n\n**自测：衬塑丝接件能不能上电焊？** 回本课【执行标准与基体】对照。","structure":"基础件：弯头转向，三通分叉，管帽封堵。\n变径件：大小头过渡，补芯省空间。\n方向：补芯外丝朝大，内丝朝小。\n禁忌：丝接件不能电焊。\n引导：本课已按内壁与方向把丝接基础件认清；现场常卡在「补芯方向装反」；下一步 C15 讲活接头与内外丝直接。","anchors":[{"name":"衬塑丝接弯头","ref":"衬塑丝接弯头"},{"name":"衬塑丝接三通","ref":"衬塑丝接三通"},{"name":"衬塑堵头","ref":"衬塑堵头"},{"name":"衬塑内外丝补芯（变径补芯）","ref":"衬塑内外丝补芯（变径补芯）"},{"name":"衬塑丝接异径管（大小头）","ref":"衬塑丝接异径管（大小头）"}],"pitfall":"【补芯外丝朝大内丝朝小】丝接件坚决不能上电焊；看内衬有没有破损。","remark":"—","seq":19,"family":"衬塑复合及丝扣/沟槽","lessonNo":10},{"id":"C18","sub":"XG-01","topic":"Y型过滤器：过滤原理、滤网识别与安装位置","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课讲管网里最常见的小设备：Y型过滤器。它保护着下游昂贵的阀门和水表。重点讲清安装方向和日常清理，防止阻水。","framework":"外观结构｜Y字形阀体与滤网。过滤原理｜截留杂质保护设备。安装位置｜水表、减压阀前端。安装方向｜滤网朝下防积垢。\nY 型过滤器逐块讲透：方向为什么不能装反｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\nY 型过滤器 安装 × 维护 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C14《衬塑丝接管件（一）》；向下接 C19《蝶阀通识》。**\n\n**现场情境：装水表前的 Y 型过滤器，工人把滤网朝上装了。** 这样装会怎样？本课讲方向为什么不能反。\n\n【外观结构：像字母Y】\n在库房看到阀体呈一个Y字形的，带一根斜向的管子和一个端盖，这就是Y型过滤器。\n水流从直管进，穿过斜向管里的不锈钢滤网，再流向直管出。\n\n【过滤原理：拦截垃圾】\n自来水里会有焊渣、铁锈、泥沙。如果不经过滤，直接冲进减压阀或水表，会卡死阀芯或打坏叶轮。\n滤网就像一个筛子。杂质被挡在滤网内，洁净的水流向出口。\n\n【安装方向：绝对不能装反】\n【滤网必须朝下】。水是从里向外穿过滤网，杂质被留在滤网内部，下沉到斜管底部。\n如果装反了，或者滤网朝上，杂质会堆积在上面把水流堵死，且无法通过排污堵头排走。\n\n【清理维护：开盖或排污】\n过滤器底部有个排污堵头。平时可以拧开排污。如果堵塞严重，拧开端盖，把不锈钢滤网抽出来用刷子刷洗。这属于日常巡检的重点维护件。\n【Y 型过滤器逐块讲透：方向为什么不能装反】\n**阀体呈 Y 字形、带一根斜管和一个端盖，就是 Y 型过滤器。** 落回卡上：看「法兰Y型过滤器」「螺纹Y型过滤器」两张卡，水流从直管进、穿斜管里的不锈钢滤网再流出。\n**它拦的是水里的焊渣、铁锈、泥沙，保护下游的减压阀和水表。** 打个比方，像给精密设备门口放了道筛子；不装，杂质会卡死阀芯、打坏叶轮。\n**滤网必须朝下：水从里向外穿过，杂质留在滤网内并沉到斜管底部。** 装反或朝上，杂质堆在上面把水流堵死，还没法从排污堵头排走。\n**过滤器底部有排污堵头，平时拧开就能排污；堵得严重再拧开端盖抽出滤网刷洗。** 这是日常巡检的重点维护件，不是装完就不管。\n**水表前、减压阀前、倒流防止器前都必须装它。** 装的位置比装不装更关键，装错位置等于下游设备裸奔。\n【Y 型过滤器 安装 × 维护 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n方向｜滤网朝下、水流从里向外｜看阀体箭头与介质流向｜装反必堵、排不出渣。\n位置｜水表 / 减压阀 / 倒流防止器前端｜装在需要保护的设备之前｜装后面等于没保护。\n日常排污｜拧开底部排污堵头｜按巡检周期排｜别等堵死了才处理。\n深度清理｜拆端盖抽出不锈钢滤网刷洗｜看滤网有无破损｜滤网破了必须换，不能凑合。\n型式｜法兰 / 螺纹两型｜按接口选｜孔距与口径一起核，以卡面与现行标准核定为准。\n**【红线】滤网必须朝下、装反必堵塞；水表与减压阀前必须装；滤网破了必须换。**\n落回卡上：把「法兰Y型过滤器」「螺纹Y型过滤器」两张卡的连接方式与结构组成栏并排看，型式与接口一次对全。\n\n**自测：Y 型过滤器滤网朝上装，会出现什么问题？** 回本课【安装方向：绝对不能装反】对照。\n\n**自测：为什么水表前、减压阀前都要装它？** 回本课【过滤原理：拦截垃圾】对照。","structure":"认结构：Y字形，内有金属滤网。\n明作用：拦泥沙、焊渣，保护水表和阀门。\n定方向：滤网朝下，水流从里向外。\n懂维护：拧排污堵头，或拆端盖洗刷。\n引导：本课已把方向与维护讲透；现场常卡在「滤网朝上装反」；下一步 C19 看蝶阀怎么分中线偏心。","anchors":[{"name":"法兰Y型过滤器","ref":"法兰Y型过滤器"},{"name":"螺纹Y型过滤器","ref":"螺纹Y型过滤器"}],"pitfall":"【滤网必须朝下】装反了必堵塞；水表前、阀门减压阀前必须装；滤网破了必须换。","remark":"—","seq":20,"family":"阀门与设备","lessonNo":11},{"id":"C19","sub":"XG-01","topic":"蝶阀通识：中线偏心结构、软硬密封与电动控制","level":"D2 / L2","d":"D2","l":"L2","positioning":"蝶阀是管网里最占地方小、启闭快的截断阀。这一课讲清中线和偏心怎么认，软硬密封怎么选，以及电动蝶阀的应用。","framework":"外观与原理｜圆盘转90度截断。中线与软密封｜橡胶座，常温清水用。偏心结构｜开启脱开无摩擦，耐用。电动蝶阀｜电机驱动，远控。\n蝶阀逐块讲透：中线、偏心与软硬密封的取舍｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n蝶阀 结构 × 场景 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C18《Y型过滤器》；向下接 C20《球阀通识》。**\n\n**现场情境：同样叫蝶阀，有中线的也有偏心的，还有软密封和硬密封。** 高温场合该选哪种？本课讲取舍。\n\n【外观与原理：翻板门】\n蝶阀通常比较扁平，里面有一个圆形的蝶板。转动手轮或手柄，蝶板旋转90度，就完成了开闭。\n它流阻小，开关快，在大口径主干管上大量替代了笨重的闸阀。\n\n【中线与软密封】\n中心轴在正中间的，叫中线蝶阀。它的边缘套着橡胶圈。\n关闭时，铁板硬挤进橡胶座里实现零泄漏。但橡胶怕高温，只能用于常温清水，且挤压磨损较快。\n\n【偏心结构：原理变了】\n为了不磨损，工程师把轴往旁边偏了一点（双偏心或三偏心）。\n一关阀，蝶板先退出来再转，不刮擦阀座。【偏心结构无论是软密封还是金属硬密封，都解决了开启瞬间的摩擦问题】，寿命更长。如果是硬密封，更耐高温高压。\n\n【电动蝶阀：自动化标配】\n在泵房和长输管线，手摇太慢，会用电动蝶阀。上方带个电机箱，接电后能接收电脑指令自动开关，断电还能手动应急。\n【蝶阀逐块讲透：中线、偏心与软硬密封的取舍】\n**蝶阀扁平、里面一个圆形蝶板，转 90 度就完成开闭。** 落回卡上：看「中线（软密封）蝶阀」「偏心蝶阀」「电动蝶阀」三张卡，它流阻小、开关快，大口径主干管大量替代笨重闸阀。\n**中线蝶阀轴在正中间、边缘套橡胶圈，靠铁板硬挤进橡胶座实现零泄漏。** 打个比方，像把门板压进门框的胶条；但橡胶怕高温、挤压磨损快，只适合常温清水。\n**偏心结构把轴往旁边偏一点（双偏心 / 三偏心），关阀时蝶板先退出来再转，不刮擦阀座。** 这一下解决了开启瞬间的摩擦问题，寿命更长；配金属硬密封还能耐高温高压。\n**软密封零泄漏但怕高温，硬密封耐温耐压但密封等级要看设计。** 别只按「都是蝶阀」发料，介质温度与压力要一起核。\n**电动蝶阀顶部带电机箱，接电后能接电脑指令自动开关，断电还能手动应急。** 泵房和长输管线手摇太慢，靠它做远控。\n【蝶阀 结构 × 场景 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n中线软密封｜轴居中、橡胶座挤压密封｜常温清水｜高温工况禁用，橡胶易老化。\n双 / 三偏心｜轴偏移、开启不刮擦｜寿命要求高、频繁启闭｜配硬密封可耐高温高压。\n软密封｜零泄漏｜常温清水｜怕高温、磨损较快。\n金属硬密封｜耐温耐压｜高温高压段｜密封等级按设计核定，逐档值以现行标准为准。\n电动蝶阀｜顶部电机 + 手动应急｜泵房远控、长输管线｜断电要能手动，验收时试一次。\n**【红线】偏心结构开启不摩擦；软密封怕高温；电动阀断电必须可用手动应急；别按外形混发。**\n落回卡上：把「中线（软密封）蝶阀」「偏心蝶阀」「电动蝶阀」三张卡的结构与驱动方式栏并排看，结构与场景一一对应。\n\n**自测：偏心蝶阀相比中线蝶阀，开启时有什么不同？** 回本课【偏心结构：原理变了】对照。\n\n**自测：软密封蝶阀遇到高温会怎样？** 回本课【中线与软密封】对照。","structure":"认中线：轴在中间，橡胶挤压密封，常用于清水。\n认偏心：轴偏移，开启不摩擦，寿命长耐高压。\n认软硬：软密封零泄漏怕高温，硬密封耐温高。\n认电动：顶部带电机，用于远程控制。\n引导：本课已把中线、偏心与软硬密封讲透；现场常卡在「软密封阀上了高温段」；下一步 C20 看球阀。","anchors":[{"name":"中线（软密封）蝶阀","ref":"中线（软密封）蝶阀"},{"name":"偏心蝶阀","ref":"偏心蝶阀"},{"name":"电动蝶阀","ref":"电动蝶阀"}],"pitfall":"【偏心结构开启不摩擦】软密封怕高温；电动阀断电可用手动应急。","remark":"—","seq":21,"family":"阀门与设备","lessonNo":12},{"id":"C20","sub":"XG-01","topic":"球阀通识：浮动固定结构、黄铜小管与三通换向","level":"D2 / L2","d":"D2","l":"L2","positioning":"球阀是开关最干脆的阀门。这一课教新员工通过外观分清浮动和固定，以及户内最常见的黄铜球阀和分流用的三通球阀。","framework":"外观与原理｜带孔圆球旋转90度。浮动球阀｜受压后贴紧，小口径常用。固定球阀｜带轴承，大口径高压用。黄铜与三通｜户内表前与分流。\n球阀逐块讲透：浮动与固定差在哪根轴｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n球阀 类型 × 场景 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C19《蝶阀通识》；向下接 C24《排气阀通识》。**\n\n**现场情境：大口径高压管道上，有人想用黄铜浮动球阀。** 拧不拧得动？本课讲浮动球和固定球的分界。\n\n【球阀和三通的型号：O/V 与 L/T】\n**球阀、三通光看外形不够，型号字母决定了它能干什么。** O 型球阀全通径、用来切断；V 型带缺口、能调节流量。L 型三通切换两路、T 型三通三路都能通。选型先想清楚是要“断”还是要“换向”，别把切断阀当调节阀用。\n\n【外观与原理：带孔的球】\n球阀通常比较短，里面有一个带通孔的圆球。手柄与管道平行是开，垂直是关。\n全开时，水直通过去，水阻极小，是设备进出口的首选。\n\n【浮动球阀：压力帮我密封】\n它的球体是松动的。水压一顶，球体就被死死压在出口的塑料阀座上。\n压力越大，密封越紧。但压力太大时，转动手柄会很费力。常用于DN200以下的中小口径。\n\n【固定球阀：大口径高压首选】\n球体被上下两根轴固定住了，不会动。密封靠阀座自己浮动去贴紧球体。\n所以哪怕水压极大，转动手柄依然很轻松。大口径、高压主干管必须用它。\n\n【黄铜与三通：户内常用】\nDN50以下的户内，全是黄铜内螺纹球阀。还有三通球阀，里面有L型或T型孔，转一下就能改变水流方向，用于分流或多路控制。\n【球阀逐块讲透：浮动与固定差在哪根轴】\n**球阀短、里面一个带通孔的圆球，手柄与管道平行是开、垂直是关。** 落回卡上：看「浮动球阀」「黄铜内螺纹浮动球阀」两张卡，全开水直通过去、水阻极小。\n**浮动球阀的球体是松的，水压一顶就把球压在出口阀座上，压力越大密封越紧。** 打个比方，像用水压自己把门顶严；但压力太大时手柄会转不动，所以多用于中小口径。\n**固定球阀球体被上下两根轴固定不动，靠阀座浮动去贴紧球体。** 水压再大转动依然轻松，大口径、高压主干管必须用它。\n**DN50 以下户内基本是黄铜内螺纹球阀，靠螺纹连接。** 三通球阀里有 L 型或 T 型孔，转一下改变水流方向，用于分流或多路控制。\n**浮动球高压会拧不动，固定球靠轴承支承；这是选型第一刀。** 别只看口径大小，压力等级和支承方式一起核。\n【球阀 类型 × 场景 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n浮动球阀｜球体松动、靠水压压紧阀座｜中小口径、中低压｜压力过高手柄费力，逐档压力以现行标准与技术部门核定为准。\n固定球阀｜上下轴固定、阀座浮动贴紧｜大口径、高压主干管｜转动力矩小，适合频繁操作。\n黄铜内螺纹浮动球阀｜螺纹接口｜户内表前、小口径｜丝扣顺螺纹缠生料带（聚四氟乙烯密封带）。\n三通球阀｜L 型 / T 型孔｜流向切换、多路控制｜先确认孔型再装，装错流向反。\n黄铜闸阀 / 止回阀｜同属户内小件｜别与球阀混发｜看有无手轮、有无阀瓣。\n**【红线】大口径高压别用浮动球，会拧不动；浮动靠水压密封、固定靠轴承支承；三通球阀先认 L / T 孔型。**\n落回卡上：把「浮动球阀」「黄铜内螺纹浮动球阀」「黄铜闸阀」「黄铜立式/卧式止回阀」四张卡的结构栏并排看，别把阀门族混在一起发。\n\n**自测：大口径高压为什么不适合用浮动球阀？** 回本课【固定球阀：大口径高压首选】对照。\n\n**自测：浮动球阀是靠什么压紧阀座密封的？** 回本课【浮动球阀：压力帮我密封】对照。","structure":"认结构：带孔圆球，转90度开关，水阻小。\n分固定：浮动靠水压密封，固定带轴承转着轻。\n认场景：高压大口径用固定，户内小管用黄铜。\n认三通：L型或T型，用于流向切换。\n引导：本课已把浮动与固定差在哪根轴讲透；现场常卡在「大口径高压用了浮动球」；下一步 C21 看闸阀。","anchors":[{"name":"浮动球阀","ref":"浮动球阀"},{"name":"黄铜内螺纹浮动球阀","ref":"黄铜内螺纹浮动球阀"},{"name":"黄铜闸阀","ref":"黄铜闸阀"},{"name":"黄铜立式/卧式止回阀","ref":"黄铜立式/卧式止回阀"}],"pitfall":"【大口径高压别用浮动球】会拧不动；浮动球靠水压密封，固定球靠轴承支承。","remark":"—","seq":22,"family":"阀门与设备","lessonNo":13},{"id":"C24","sub":"XG-01","topic":"排气阀通识：快速、微量与复合式排气","level":"D2 / L2","d":"D2","l":"L2","positioning":"管道里如果进了空气，水就流不动甚至爆管。排气阀就是管网的呼吸机。这一课讲清快速排气、微量排气和复合式的区别与高处安装。","framework":"外观与原理｜浮筒浮球与排气孔。快速式｜大孔，充水时大量排气。微量式｜小孔，平时排气泡。复合式｜大孔加小孔，管网主力。\n排气阀逐块讲透：浮球、孔径与高点｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n排气阀 孔径 × 位置 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C20《球阀通识》；向下接 C30《波纹管补偿器》。**\n\n**现场情境：管线高点总是集气、流量忽大忽小，检查发现排气阀装在了低点。** 问题出在哪？本课讲高点安装。\n\n【外观与原理：呼吸机】\n排气阀通常直立安装，像一个胖葫芦。\n里面有个浮球。管子里没水的时候，浮球落下，孔是开的，排气。水满了，浮球托起，把孔堵死，防漏水。\n\n【快速与微量】\n快速式排气阀孔很大，管道刚通水时，空气被迅速挤出，防止憋气。\n微量式排气阀只有针眼大的小孔，平时水里析出的微小气泡，会慢慢聚集在阀顶排出。\n\n【复合式：全能选手】\n管网最常用的是复合式排气阀。它兼顾大孔和小孔。\n充水时大孔猛排空气；水满后大孔关上，小孔继续排微量气体；如果管内产生负压，它还能把外面的空气吸进来，防止管道被吸瘪。\n\n【安装位置：高点与变坡处】\n空气比水轻，所以【排气阀必须装在管线最高点或坡度变陡的地方】。装低了，只能喷水，排不出气。\n【排气阀逐块讲透：浮球、孔径与高点】\n**排气阀直立安装像个胖葫芦，里面有个浮球：无水时球落、孔开排气；水满时球托起、堵孔防漏。** 落回卡上：看「复合式排气阀」「快速排气阀（高速排气阀）」「微量排气阀（黄铜自动排气阀）」等卡。\n**管道里进了空气，水就流不动甚至爆管，排气阀就是管网的呼吸机。** 打个比方，像给管路装了个会自己开合的鼻孔。\n**快速式孔很大，管道刚通水时把空气迅速挤出防憋气；微量式只有针眼小孔，慢慢排平时析出的小气泡。** 孔径决定它管的是「充水」还是「运行」两个阶段。\n**复合式兼顾大孔小孔，是管网主力：充水猛排、水满后小孔继续排微量气；管内负压时还能吸进空气防管道被吸瘪。** 一阀三用，别只当它是排气。\n**空气比水轻，所以排气阀必须装在管线最高点或坡度变陡处。** 装低了只能喷水、排不出气；冬天还要注意防冻裂。\n【排气阀 孔径 × 位置 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n快速式（大孔）｜充水时大量排气｜管道初充水、主干管｜孔大，别当微量用。\n微量式（小孔）｜排运行中析出气泡｜高点持续排气｜孔小易堵，定期查。\n复合式（大孔 + 小孔）｜排气 + 负压进气｜管网主力、高点｜能防管道被吸瘪。\n小口径黄铜自动排气阀｜户内 / 局部高点｜小系统自动排气｜按接口选，别串到大口径。\n安装位置｜管线最高点、变坡处｜必须高于周边管段｜装低点只吐水不排气；冬季防冻裂。\n**【红线】排气阀必须装高点、装低点只吐水不排气；大孔排空、小孔排气；冬天注意防冻裂。**\n落回卡上：把「复合式排气阀」「快速排气阀（高速排气阀）」「微量排气阀（黄铜自动排气阀）」「小口径黄铜自动排气阀」四张卡的孔径与用途栏并排看。\n\n**自测：排气阀装在低点，为什么不排气只吐水？** 回本课【安装位置：高点与变坡处】对照。\n\n**自测：快速排气和微量排气分别管什么阶段？** 回本课【快速与微量】对照。","structure":"认作用：排出空气防气阻，防止憋气爆管。\n分孔径：大孔快速排空，小孔排微量气体。\n认复合：大小孔全都有，管网最常用。\n定位置：必须装在高点或变坡点。\n引导：本课已把浮球、孔径与高点讲透；现场常卡在「排气阀装在低点只喷水」；下一步 C25 看密封连接辅材。","anchors":[{"name":"复合式排气阀","ref":"复合式排气阀"},{"name":"快速排气阀（高速排气阀）","ref":"快速排气阀（高速排气阀）"},{"name":"微量排气阀（黄铜自动排气阀）","ref":"微量排气阀（黄铜自动排气阀）"},{"name":"小口径黄铜自动排气阀","ref":"小口径黄铜自动排气阀"}],"pitfall":"【排气阀必须装高点】装低点只吐水不排气；大孔排空，小孔排气；冬天注意防冻裂。","remark":"—","seq":23,"family":"阀门与设备","lessonNo":14},{"id":"C30","sub":"XG-01","topic":"波纹管补偿器：轴向、横向与铰链的结构与选型","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课讲波纹管补偿器。管道热胀冷缩必须有补偿装置，重点解决新员工对轴向、横向、铰链三种结构的区分，以及限位拉杆的作用。","framework":"外观与原理｜不锈钢波纹管弹性变形吸收位移。轴向型｜直管段伸长，拉杆承受推力。横向型｜大拉杆，吸收垂直位移。铰链型｜角向偏转，成对使用。安装禁忌｜严禁用补偿器强行对口。\n波纹管补偿器逐块讲透：三种位移与拉杆｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n补偿器 型式 × 位移 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C24《排气阀通识》；向下接 C31《可曲挠橡胶接头》。**\n\n**现场情境：两段管道对口差了一截，工人想用补偿器硬把它拉拢。** 这能不能干？本课讲拉杆的作用。\n\n【补偿量怎么算：ΔL＝α·L·Δt】\n**波纹管补偿器要预留多少伸缩量，是算出来的。** 公式 ΔL＝α·L·Δt，α 是线膨胀系数（碳钢约 12×10⁻⁶/℃）、L 是管段长度、Δt 是温差。冷态安装按设计预留约一半行程做预拉伸或预压缩，严禁把补偿器全压缩死，热起来没处伸会拉裂。\n\n【导流筒的作用和方向】\n**补偿器里的导流筒不是可有可无，装反了会冲坏波纹管。** 流速大于 1.5m/s、蒸汽或含沙介质必须装导流筒，它的坡口端要朝向来流，把流体导过去、不直接冲刷波纹波谷。少了它或装反，波纹管会被冲刷腐蚀直至破裂。\n\n【固定支架、导向支架要配套】\n**波纹管会产生很大的盲板力，光有补偿器不够。** 必须靠固定支架承受这股力，再用导向支架约束管道只能轴向伸缩。支架没做对，补偿器会偏磨、跑偏，用不了多久就失效。\n\n【外观与原理】\n在库房看到中间是不锈钢波纹，两头带法兰或接管，旁边有几根拉杆的，就是波纹管补偿器。它靠波纹管的拉伸、压缩或弯曲，来吸收管道因为热胀冷缩产生的位移。\n\n【轴向型：最常用】\n用在直管段。它的拉杆是运输和限位用的。工作时，波纹管顺着管道方向伸缩。拉杆不能拆，必须承受管内水压产生的巨大盲板推力，否则管子会把补偿器拉飞。\n\n【大拉杆横向型与铰链型】\n横向型由两组波纹管组成，大拉杆横跨两端，用来吸收垂直于管道的横向位移。铰链型带有铰链板，只能角向偏转，绝不能单独使用，必须两个或三个成组配套，否则无法吸收直线位移。\n\n【安装禁忌：不能强行对口】\n如果管子没对齐，千万别用拉杆硬拉过来。这样波纹管一开始就受力，通水后极易开裂。\n【波纹管补偿器逐块讲透：三种位移与拉杆】\n**中间是不锈钢波纹、两头带法兰或接管、旁边几根拉杆，就是波纹管补偿器。** 落回卡上：看「轴向型波纹管补偿器」卡，靠波纹管拉伸、压缩或弯曲吸收管道热胀冷缩的位移。\n**轴向型用在直管段，波纹管顺管道方向伸缩；它的拉杆是运输和限位用的，绝不能拆。** 打个比方，拉杆像安全带，要承受管内水压产生的巨大盲板推力；拆了管子会把补偿器拉飞。\n**大拉杆横向型由两组波纹管组成、大拉杆横跨两端，吸收垂直于管道的横向位移。** 它管的是「横向」，不是「顺着管子伸长」，选型别混。\n**铰链型带铰链板，只能角向偏转，绝不能单独使用，必须两个或三个成组配套。** 单只装上去吸不了直线位移，还会把力憋在管路上。\n**管子没对齐时，千万别用拉杆硬拉过来强行对口。** 波纹管一开始就带预应力，通水后极易开裂；正确做法是先把管道固定到位再装补偿器。\n【补偿器 型式 × 位移 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n轴向型｜顺管道方向伸缩｜直管段热胀冷缩｜拉杆承受内压推力，严禁拆除。\n大拉杆横向型｜两组波纹管 + 横跨拉杆｜吸收垂直管道的横向位移｜别当轴向型用。\n铰链型｜铰链板角向偏转｜需成组配套（2–3 只）｜单只使用吸不了直线位移。\n限位拉杆｜运输 / 限位 / 承受推力｜按厂家要求调螺母｜逐档位移量以现行标准与技术部门核定为准。\n安装｜先固定管道再装｜严禁拉杆强行对口｜强行对口通水后波纹管易裂。\n**【红线】拉杆不能随便拆、轴向型拉杆承受内压推力；铰链型必须成对用；严禁用补偿器强行拉拢管道对口。**\n落回卡上：把「轴向型波纹管补偿器」「可曲挠式橡胶接头」「球墨铸铁伸缩节（限位型/传力型）」三张卡的补偿方向与结构栏并排看，三类补偿件别混发。\n\n**自测：能不能用补偿器强行拉拢管道对口？** 回本课【安装禁忌：不能强行对口】对照。\n\n**自测：铰链型补偿器为什么要成对使用？** 回本课【大拉杆横向型与铰链型】对照。","structure":"原理：靠不锈钢波纹管变形吸收位移。轴向型：直管用，拉杆承受内压推力，不能拆。横向型：吸收垂直管道的位移。铰链型：吸收角向偏转，必须成组使用。禁忌：严禁用补偿器强行对口，管子必须先固定好。\n引导：本课已把三种位移与拉杆讲透；现场常卡在「拆了限位拉杆」；下一步 C31 看可曲挠橡胶接头。","anchors":[{"name":"轴向型波纹管补偿器","ref":"轴向型波纹管补偿器"},{"name":"可曲挠式橡胶接头","ref":"可曲挠式橡胶接头"},{"name":"球墨铸铁伸缩节（限位型/传力型）","ref":"球墨铸铁伸缩节（限位型/传力型）"}],"pitfall":"【拉杆不能随便拆】轴向型拉杆承受内压推力；铰链型必须成对用；严禁用补偿器强行拉拢管道对口。","remark":"—","seq":24,"family":"补偿器与柔性接头","lessonNo":15},{"id":"C31","sub":"XG-01","topic":"可曲挠橡胶接头：单双球体、减震降噪与限位螺栓","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课讲水泵旁边最常见的橡胶接头。重点解决新员工对单双球体的区分、限位螺栓的调节，以及介质相容性认知。","framework":"外观与结构｜橡胶球体与法兰。减震原理｜橡胶隔振与降噪。限位螺栓｜防拉脱与限位。介质要求｜给水EPDM，含油NBR。安装禁忌｜严禁焊接火花破坏橡胶。\n可曲挠橡胶接头逐块讲透：减震、限位与介质｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n橡胶接头 选型 × 禁忌 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C30《波纹管补偿器》；向下接 C25《密封与连接辅材》。**\n\n**现场情境：装好可曲挠橡胶接头后，工人没调限位螺栓就通水。** 水压一大会怎样？本课讲限位的意义。\n\n【外观与结构】\n在泵房看到中间是凸起的橡胶球，两头带法兰的，就是可曲挠橡胶接头。里面夹着帘子布和钢丝圈，外面是橡胶。它主要用在泵出口和管道连接处。\n\n【减震原理与单双球】\n橡胶是极好的减震材料。单球体弹性好，双球体位移补偿量大。它能吸收水泵运行时的震动和噪音，还能补偿管道的微量偏移。\n\n【限位螺栓：保护器】\n法兰周围有几根带螺母的螺栓。这是限位螺栓。通水后，必须按厂家要求把螺母调到特定位置，既能允许一定伸缩，又能防止水压过大把橡胶球体拉脱扯断。\n\n【介质与安装禁忌】\n给水默认EPDM材质，如果是含油介质得用NBR。安装时远离焊接作业，电焊火花溅上去直接烧个洞，就废了。\n【可曲挠橡胶接头逐块讲透：减震、限位与介质】\n**泵房里中间凸起橡胶球、两头带法兰的就是可曲挠橡胶接头，里面夹帘子布和钢丝圈。** 落回卡上：看「可曲挠式橡胶接头」卡，主要用在泵出口和管道连接处。\n**橡胶是极好的减震材料，能吸收水泵运行时的震动和噪音，还能补偿管道微量偏移。** 打个比方，像在硬管之间垫了块软胶，机器抖不直接传到管上。\n**单球体弹性好，双球体位移补偿量更大。** 选单还是双，看的是需要吸收多少位移，不是看哪个贵。\n**法兰周围那几根带螺母的螺栓是限位螺栓，通水后必须按厂家要求把螺母调到特定位置。** 既允许一定伸缩，又防住水压过大把橡胶球体拉脱扯断。\n**给水默认 EPDM，含油介质得用 NBR；安装时远离焊接作业，电焊火花溅上去直接烧个洞。** 也不能把机油涂在橡胶接头上，沾油会加速老化。\n【橡胶接头 选型 × 禁忌 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n单球体｜弹性好｜一般减震、微量偏移｜按位移量选，别凭外形。\n双球体｜位移补偿量大｜位移较大处｜逐档补偿量以现行标准与技术部门核定为准。\n限位螺栓｜防拉脱、限位｜通水后按厂家要求调螺母｜不调水压一大就扯断。\n材质｜给水 EPDM / 含油 NBR｜按介质选｜严禁涂机油，怕油怕晒。\n安装｜远离电焊、遮挡火花｜球体无油污、无裂纹、无烫伤｜烫伤鼓包即判结构异常。\n**【红线】限位螺栓一定要调，不调水压一大就扯断；绝不能把机油涂在橡胶接头上；电焊要遮挡。**\n落回卡上：「可曲挠式橡胶接头」卡的结构组成、材质与执行标准栏，把球体、法兰、限位螺栓三件一次对全。\n\n**自测：限位螺栓不调，通水后会发生什么？** 回本课【限位螺栓：保护器】对照。\n\n**自测：为什么不能把机油涂在橡胶接头上？** 回本课【介质与安装禁忌】对照。","structure":"结构：橡胶球体+法兰+限位螺栓。作用：减震降噪，补偿微量位移。限位：防拉脱，必须按要求调节螺母。选型：给水EPDM，含油NBR。禁忌：严禁电焊火花烫伤橡胶球体。\n引导：本课已把减震、限位与介质讲透；现场常卡在「限位螺栓不调就通水」；下一步 C32 看伸缩器与铸铁伸缩节。","anchors":[{"name":"可曲挠式橡胶接头","ref":"可曲挠式橡胶接头"}],"pitfall":"【限位螺栓一定要调】不调的话水压一大就扯断；绝不能把机油涂在橡胶接头上；电焊要遮挡。","remark":"—","seq":25,"family":"补偿器与柔性接头","lessonNo":16},{"id":"C25","sub":"XG-01","topic":"密封与连接辅材：胶圈、胶垫、生料带与压力表弯","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课讲管网里最不起眼但决定漏不漏水的辅材：密封圈、生料带和连接附件。重点解决新员工对橡胶材质、螺纹密封方向和缓冲弯的认知。","framework":"橡胶密封件｜胶垫与胶圈的材质差异。螺纹密封｜生料带的缠绕方向。附件缓冲｜压力表弯的作用。存放禁忌｜避光防油与老化。\n密封连接辅材逐块讲透：材质、方向与缓冲｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n密封辅材 × 用法 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。\n到货验收：橡胶件与辅材状态判定｜材质｜状态｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C31《可曲挠橡胶接头》；向下接 C26《紧固与计量辅材》。**\n\n**现场情境：装法兰时，有人给橡胶垫片抹了机油，生料带也缠得乱七八糟。** 这些动作错在哪？本课讲辅材用法。\n\n【橡胶密封件：填缝与防水】\n在库房看到平圆形的是胶垫（法兰用），环形厚实的是胶圈（承插口用）。给水场景默认材质是EPDM。橡胶件极度怕油、怕晒，存放在库房必须避光阴凉。\n\n【螺纹密封：生料带（聚四氟乙烯密封带）的用法】\n生料带（聚四氟乙烯密封带）只用于螺纹连接。缠绕方向必须顺时针（顺着拧紧方向），留出第一扣螺纹，防止生料带（聚四氟乙烯密封带）碎屑被水冲进表里。绝对不能缠反或缠太厚，否则会撑裂内螺纹件。\n\n【缓冲附件：压力表弯】\n装压力表时，下方必须配一个弯管（O型或U型），叫压力表弯。它能缓冲水锤冲击，并让高温蒸汽冷凝，保护表内精密的弹簧管。\n【密封连接辅材逐块讲透：材质、方向与缓冲】\n**平圆形的是胶垫（法兰用）、厚实环形的是胶圈（承插口用），给水场景默认材质 EPDM。** 落回卡上：看「胶垫（法兰橡胶垫片）」「胶圈（球墨管承插密封圈）」两张卡的材质栏。\n**橡胶件极度怕油、怕晒：沾油会加速老化、暴晒会让分子链断掉。** 打个比方，像橡皮筋放久了发黏发脆；库房必须避光阴凉，沾了机油的胶圈一律待检。\n**生料带（聚四氟乙烯密封带）只用于螺纹连接，缠绕方向必须顺时针（顺着拧紧方向），还要留出第一扣。** 留第一扣是防碎屑被水冲进表里；缠反了一拧就松脱，缠太厚会撑裂内螺纹件。\n**装压力表时下方必须配一个 O 型或 U 型弯管，叫压力表弯。** 它缓冲水锤冲击、让高温介质冷凝，保护表内精密的弹簧管。\n**别小看这几样辅材，漏不漏水往往就差一片垫、一圈带、一个弯。** 它们单价低，出问题却是整段返工。\n【密封辅材 × 用法 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n胶垫（法兰橡胶垫片）｜法兰对接夹在两片之间｜放正、不挡内孔｜给水 EPDM，含油改 NBR。\n胶圈（球墨管承插密封圈）｜塞进承口凹槽｜看唇边完好、无老化｜怕油怕晒，沾油先待检。\n生料带（聚四氟乙烯密封带）｜外螺纹顺向缠｜留第一扣不缠｜内螺纹不缠，别缠太厚。\n压力表弯（缓冲弯/冷凝弯）｜压力表下方必配｜缓冲水锤、冷凝介质｜不装表芯易被冲击打坏。\n存放｜避光阴凉、远离油品｜分类隔开｜老化裂纹、永久变形即判异常。\n**【红线】生料带（聚四氟乙烯密封带）顺螺纹缠、留第一扣；橡胶圈绝不能沾机油；装压力表必带缓冲弯。**\n落回卡上：把「胶垫（法兰橡胶垫片）」「胶圈（球墨管承插密封圈）」「生料带（聚四氟乙烯密封带）」「压力表弯（缓冲弯/冷凝弯）」四张卡的材质与用途栏并排看。\n\n【到货验收：橡胶件与辅材状态判定】\n**辅材单价低，但漏不漏水就差这一片垫、一圈带、一个弯；你要按状态逐件判，不按数量收。**\n1 胶垫（法兰橡胶垫片）：平圆形、放正不挡内孔，看无老化裂纹、无永久变形，给水场景默认 EPDM，含油改 NBR 以卡面为准。\n2 胶圈（球墨管承插密封圈）：厚实环形、唇边完好无缺口，塞进承口凹槽要贴合；沾了机油的一律待检，别擦擦就用。\n3 生料带（聚四氟乙烯密封带）：看是聚四氟乙烯密封带、无油污污染，只配外螺纹用，内螺纹不缠。\n4 压力表弯：看 O 型或 U 型弯管通畅无堵，装表必配，缺了表芯容易被水锤打坏。\n**【红线】橡胶件沾油、暴晒发黏发脆、老化裂纹、永久变形，任一命中判异常；存放避光阴凉、远离油品。**\n**落回卡上：**把「胶垫（法兰橡胶垫片）」「胶圈（球墨管承插密封圈）」「生料带（聚四氟乙烯密封带）」「压力表弯（缓冲弯/冷凝弯）」四张卡的材质与用途栏并排看。\n\n**自测：橡胶密封圈能不能沾机油？** 回本课【橡胶密封件：填缝与防水】对照。\n\n**自测：生料带应该顺哪个方向缠、留几扣？** 回本课【螺纹密封：生料带（聚四氟乙烯密封带）的用法】对照。","structure":"橡胶材质EPDM，怕油怕暴晒。生料带顺螺纹缠，留出第一扣。压力表弯用来缓冲冲击，保护表盘。\n引导：本课已把材质、方向与缓冲讲透；现场常卡在「胶圈沾了机油擦擦就用」；下一步 C26 看紧固与计量辅材。","anchors":[{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"生料带（聚四氟乙烯密封带）","ref":"生料带（聚四氟乙烯密封带）"},{"name":"压力表弯（缓冲弯/冷凝弯）","ref":"压力表弯（缓冲弯/冷凝弯）"}],"pitfall":"【生料带顺螺纹缠，留第一扣】橡胶圈绝不能沾机油；装压力表必带缓冲弯。","remark":"—","seq":26,"family":"辅材·井室·户表集成","lessonNo":17},{"id":"C26","sub":"XG-01","topic":"紧固与计量辅材：半丝螺栓、全丝螺栓与压力表","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课讲紧固件与就地显示仪表。重点教新员工分清半丝和全丝螺栓的使用场景，以及压力表的基本读识与安装要求。","framework":"螺栓分类｜半丝抗剪与全丝调节。压力表基础｜量程与弹簧管。安装要求｜垂直安装与前置缓冲。执行标准｜看铭牌与标识。\n紧固与计量辅材逐块讲透：半丝抗剪、表要垂直｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n紧固件 × 仪表 核对表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。\n到货验收：螺栓等级与压力表标识｜等级｜量程｜附件，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C25《密封与连接辅材》；向下接 C27《井室与消防设施》。**\n\n**现场情境：法兰和支架都要用螺栓，库房有半丝和全丝两种；压力表量程也挑大了。** 怎么选才对？本课讲。\n\n【螺栓性能等级 4.8 / 8.8 是什么意思】\n**螺栓头上那串数字是性能等级，标着它的强度。** 小数点前的数字×100 是抗拉强度（MPa），小数点后的数字×10 是屈服强度与抗拉的百分比。比如 4.8 是抗拉 400MPa、屈服 320MPa，8.8 是抗拉 800MPa。法兰高压处要用高等级螺栓，别拿 4.8 顶 8.8。\n\n【压力表精度 1.6 级、2.5 级】\n**压力表表盘上的 1.6、2.5 是精度等级，数字越小越准。** 它表示最大允许误差占满量程的百分数：1.6 级就是误差不超过 1.6%。表盘小的一般精度低，选用时看工作压力需要多准。\n\n【压力表量程按 1.5-2 倍工作压力选】\n**压力表量程不是越大越好，要按工作压力的 1.5-2 倍选。** 量程太大指针几乎不动、读不出数，太小又容易超载打坏。稳定压力时，最大工作值最好不超过量程的三分之二。\n\n【紧固件：半丝与全丝的区别】\n法兰对接必须用半丝螺栓（带一段光杆），光杆卡在法兰孔里承受剪切力，防止拉断。支架或管卡固定用全丝螺栓，方便任意调节长度。\n\n【压力表：看量程与指针】\n表盘上印有MPa或bar，指针指到几就是几公斤压力。给水常用1.0MPa或1.6MPa量程。\n\n【安装防雷】\n压力表必须垂直安装，且表前必须有缓冲弯或表阀。不能歪着装，否则机芯齿轮容易卡滞不准。\n【紧固与计量辅材逐块讲透：半丝抗剪、表要垂直】\n**法兰对接必须用半丝螺栓（带一段光杆），光杆卡在法兰孔里承受剪切力。** 落回卡上：看「六角头螺栓（半丝/全丝）」卡，打比方，光杆像一根销子把两片法兰对中定位，防的是横向拉断。\n**支架或管卡固定用全丝螺栓，螺母能在任意位置停留，方便调长度。** 全丝当半丝用，法兰孔对中差、一加压容易崩开，两者别串。\n**压力表表盘印 MPa 或 bar，指针指到几就是几公斤压力；给水常用 1.0 或 1.6MPa 量程。** 量程选大了读不准，选小了会打弯指针。\n**压力表必须垂直安装，表前要有缓冲弯或表阀。** 歪着装机芯齿轮容易卡滞，读数就不准了，这是最容易被忽略的安装细节。\n**紧固件还要看头部等级标记与镀锌层。** 螺纹不完整、镀锌层大面积脱落会影响预紧力，属于异常件。\n【紧固件 × 仪表 核对表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n半丝螺栓｜光杆段抗剪、法兰对中｜法兰对接必用｜别拿全丝代替。\n全丝螺栓｜螺母任意位停留、调长度｜支架、管卡固定｜不用于法兰孔对中。\n等级标记｜螺栓头 4.8 / 8.8 等｜按设计压力核等级｜低等级上高压法兰受力不足。\n压力表｜量程 1.0 / 1.6MPa 常见｜垂直安装、前置缓冲弯｜量程选错读不准或打弯指针。\n外观｜螺纹完整、镀锌层完好｜看锈蚀与螺纹损伤｜损伤件判异常，不进现用区。\n**【红线】法兰用半丝、支架用全丝；压力表不能歪装；量程选大了读不准、选小了会打弯指针。**\n落回卡上：把「六角头螺栓（半丝/全丝）」「压力表」两张卡的规格型号与安装要求栏并排看，等级与量程一次对全。\n\n【到货验收：螺栓等级与压力表标识】\n**法兰螺栓和压力表都要「看标识再上手」，光看尺寸差不多就装，是最常见的返工原因。**\n1 螺栓：法兰对接必须是带光杆的半丝螺栓，全丝只用于支架管卡；看头部 4.8 / 8.8 等等级标记与设计压力是否一致。\n2 外观：螺纹完整、镀锌层完好，锈蚀或螺纹损伤判异常，不进现用区。\n3 压力表：看表盘 MPa 或 bar 单位、量程是否合适，量程选大了读不准、选小了会打弯指针。\n4 附件：表阀或缓冲弯必须配套，垂直安装位留好；精度等级与检定周期以卡面与现行标准核定为准，本课不代填。\n**【红线】全丝螺栓上法兰、表盘无量程单位、缓冲弯缺失，三项任一命中就判异常，不许上高压法兰。**\n**落回卡上：**把「六角头螺栓（半丝/全丝）」「压力表」两张卡的规格型号与安装要求栏并排核一遍。\n\n**自测：法兰连接该用半丝还是全丝螺栓？** 回本课【紧固件：半丝与全丝的区别】对照。\n\n**自测：压力表量程选得过大，读数会怎样？** 回本课【压力表：看量程与指针】对照。","structure":"法兰对接用半丝抗剪，支架卡箍用全丝调节。表盘看MPa压力，安装必须垂直，前置缓冲弯。\n引导：本课已把半丝抗剪与表要垂直讲透；现场常卡在「全丝螺栓上了法兰」；下一步 C27 看井室与消防设施。","anchors":[{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"压力表","ref":"压力表"}],"pitfall":"【法兰用半丝，支架用全丝】压力表不能歪装；量程选大了读不准，选小了会打弯指针。","remark":"—","seq":27,"family":"辅材·井室·户表集成","lessonNo":18},{"id":"C27","sub":"XG-01","topic":"井室与消防设施：消火栓与井盖的类型与选用","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课讲地面上看得见的设施：消火栓与井盖。重点讲地上与地下的区别、井盖的承载等级，以及防止丢失与碾压的常识。","framework":"消火栓｜地上式与地下式。井盖分类｜球墨铸铁与复合材质。承载等级｜D400重型与A15轻型。功能标识｜给水与消防字样。\n井室与消防设施逐块讲透：地上地下与承载等级｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n井盖 / 消火栓 选型对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。\n现场判定：井盖承载等级与标识核对｜路段｜标识｜外观，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C26《紧固与计量辅材》；向下接 C29《户表控制箱》。**\n\n**现场情境：车行道井盖坏了，有人想拿复合井盖去替；地下消火栓现场找不到扳手。** 这么换行不行？本课讲选用。\n\n【消火栓型号 SS/SA：地上还是地下】\n**消火栓型号开头的字母就说明它装在哪里。** SS 是地上式、SA 是地下式，后面的数字如 SS100/65 表示主口径 100mm、副口径 65mm。看型号就知道型式和接口尺寸，领料和验收不用现场量。\n\n【井盖承载等级按场所选】\n**井盖上的 A15、B125、C250、D400 是承载等级，对应不同场所。** A15 绿化带、B125 人行道非机动车道、C250 小区背街、D400 城市主路公路。承载指单轮荷载、不是整车重量，装在机动车道上却用人行道井盖会被压坏。\n\n【消火栓：地上与地下】\n地上式消火栓露出地面，红色，灭火接水带方便。地下式消火栓藏在地下井里，冬天防冻，需要专用扳手开盖接水。\n\n【井盖：材质与等级】\n车行道上的井盖必须是球墨铸铁（重型D400），能扛住重卡碾压。绿化带或人行道可用复合井盖（轻型），无回收价值防盗。井盖表面必须铸有“给水”或“消防”字样，方便精准找阀门。\n\n【存放禁忌】\n消火栓严禁碰撞变形；复合井盖严禁重摔，容易碎裂。\n【井室与消防设施逐块讲透：地上地下与承载等级】\n**地上式消火栓露出地面、红色，灭火接水带方便；地下式藏在井里，冬天防冻，需要专用扳手开盖接水。** 落回卡上：看「地上式消火栓」「地下式消火栓」两张卡。\n**防冻地区多用地下式，交通繁忙地段也常选地下，型式要跟设计一致。** 打比方，一个随取随用、一个藏起来防冻防撞，取舍在气候与路况。\n**车行道上的井盖必须是球墨铸铁重型 D400，能扛重卡碾压。** 绿化带或人行道可用复合井盖（A15/B125/C250 等），轻、无回收价值防盗。\n**复合井盖不能上重车道，消防车通道也要按 D400 核。** 这是承载等级问题，不是轻便好看的问题；压碎了就是路面塌陷事故。\n**井盖表面必须铸有「给水」或「消防」字样，方便精准找阀门。** 存放时消火栓严禁碰撞变形，复合井盖严禁重摔，容易碎裂。\n【井盖 / 消火栓 选型对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n地上式消火栓｜栓体露出地面｜接水带快、非严寒区｜冬季注意防冻，阀体别碰撞。\n地下式消火栓｜设在井内、地面只留井盖｜严寒防冻、交通繁忙处｜需专用扳手，井盖标识清楚。\n球墨铸铁井盖（给水/消防）｜D400 重型｜车行道、消防车通道｜逐档承载值以现行标准与技术部门核定为准。\n复合井盖（给水/消防）｜A15 / B125 / C250 等｜绿化带、人行道｜不上重车道，严禁重摔。\n功能标识｜盖面「给水 / 消防」字样｜运维识别｜字样不清判标识异常。\n**【红线】车行道必须用球铁重型井盖、消防通道按 D400 核；地下式消火栓需专用扳手；复合井盖不能上车道。**\n落回卡上：把「地上式消火栓」「地下式消火栓」和两种井盖卡的承载等级、状态栏并排看。GB 4452-2026 于 2027-02-01 实施的换版提示，以卡面与主管部门要求为准。\n\n【现场判定：井盖承载等级与标识核对】\n**井盖怎么选不看轻便好看，看它压在什么路上；你要先定路段等级，再回卡面核承载与字样。**\n1 路段：车行道、消防车通道按重型 D400 核，必须球墨铸铁；绿化带、人行道才可用 A15/B125/C250 等复合井盖。\n2 标识：盖面「给水」或「消防」字样必须清晰，字样不清判标识异常，抢修时找错井会误事。\n3 型式：严寒防冻或交通繁忙处选地下式消火栓，需专用扳手；非严寒区要接水带快可选地上式。\n4 外观：消火栓栓体无碰撞变形，复合井盖无裂纹缺角，重摔过的直接判异常。\n**【红线】复合井盖上重车道或消防通道、承载等级对不上路段、盖面无功能字样，任一命中就停用。**\n**落回卡上：**把「地上式消火栓」「地下式消火栓」「球墨铸铁井盖（给水/消防）」「复合井盖（给水/消防）」四张卡的承载等级与状态栏并排看。\n\n**自测：车行道为什么必须用球铁重型井盖？** 回本课【井盖：材质与等级】对照。\n\n**自测：地下式消火栓开启要用什么工具？** 回本课【消火栓：地上与地下】对照。","structure":"地上栓接水快，地下栓防冻好。车行道必须球铁重型井盖，绿化带用复合。认准表面给水或消防字样。\n引导：本课已把地上地下与承载等级讲透；现场常卡在「复合井盖上了消防车道」；下一步 C28 看防腐与抢修辅材。","anchors":[{"name":"地上式消火栓","ref":"地上式消火栓"},{"name":"地下式消火栓","ref":"地下式消火栓"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"复合井盖（给水/消防）","ref":"复合井盖（给水/消防）"}],"pitfall":"【车行道必须用球铁重型井盖】地下式消火栓需专用扳手；复合井盖不能上车道，容易压碎。","remark":"—","seq":28,"family":"辅材·井室·户表集成","lessonNo":19},{"id":"C29","sub":"XG-01","topic":"户表控制箱：不锈钢箱体与内部集成认知","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课讲户表控制箱，它是户内给水的总控制枢纽。重点讲不锈钢箱体的优势、内部PE分水器与表前阀的布局，以及日常维护禁忌。","framework":"外观结构｜不锈钢箱体防锈。内部集成｜PE分水器与表前阀。外部接口｜底部PE进水与顶部黄铜球阀。维护禁忌｜严禁砸敲与非法私拆。\n户表控制箱逐块讲透：箱体、分流与接口｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n户表箱 结构 × 维护 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。\n到货验收：箱体与内件怎么验｜材质｜分流｜方向，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C27《井室与消防设施》；向下接 C03《PE系统连接工艺与材料存放禁》。**\n\n**现场情境：检修户表箱时，有人想暴力拆开内部管路，还说不锈钢箱不会锈。** 这些判断对吗？本课讲箱体与接口。\n\n【外观结构：不锈钢防锈】\n在楼道里看到的方形金属箱就是户表箱。材质通常是不锈钢（304或201），能防潮防锈，保护内部水表不被破坏。\n\n【内部集成：一体化分流】\n打开箱门，里面有一根管子连着好几块水表。这根总管叫PE分水器，它把进水一分为多路，减少了传统三通拼接的漏水隐患。每个水表前面都有一个黄铜表前阀，用于单独控制这户的进水。\n\n【接口与维护】\n箱子底部是PE外丝直接进水口，顶部是黄铜球阀出水口，接住户的入户管。箱门带防盗锁。日常严禁暴力砸敲箱体，也不能让非专业人员私自拆装分水器。\n【户表控制箱逐块讲透：箱体、分流与接口】\n**楼道里的方形金属箱就是户表箱，材质通常是不锈钢（304 或 201），作用是防潮防锈、保护内部水表。** 落回卡上：看「不锈钢户表控制箱」卡。\n**打开箱门，一根总管连着好几块水表，这根叫 PE 分水器，一进多出。** 打个比方，像给一栋楼装了根多插孔的接线板；一体化注塑减少了传统三通拼接的漏点。\n**每个水表前面都有一个黄铜表前阀，用来单独控制这一户的进水。** 检修某一户不用停整栋楼，靠的就是它。\n**箱子底部是 PE 外丝直接进水口、顶部是黄铜球阀出水口接住户入户管，箱门带防盗锁。** 进出方向别接反，接反了表具读数和维护都不对。\n**日常严禁暴力砸敲箱体，也不能让非专业人员私自拆装分水器。** 不锈钢也不是绝对不锈，201 在潮湿环境仍会锈，验收看材质标注。\n【户表箱 结构 × 维护 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n箱体｜不锈钢 304 / 201｜看材质标注、无变形｜潮湿环境 201 也会锈，别一概当不锈。\n分流｜PE分水器｜一体化多路、少拼接点｜比多个三通拼漏点少。\n表前控制｜黄铜表前阀（每户一只）｜单独断水检修｜表前阀不能乱动，钥匙专管。\n接口｜底部 PE 外丝直接进水、顶部黄铜球阀出水｜方向别接反｜接反读数与维护都不对。\n箱门｜防盗锁｜非专业人员不得私拆｜严禁暴力砸敲箱体。\n**【红线】严禁暴力私拆内部管路；表前阀不能乱动；底部 PE 口进水、顶部球阀出水，方向别接反。**\n落回卡上：把「不锈钢户表控制箱」「PE分水器」两张卡的结构组成与接口栏并排看，箱体与内件一次对全。\n\n【到货验收：箱体与内件怎么验】\n**户表箱是一整套集成件，你要开箱核内件，不能只看外壳亮不亮就签收。**\n1 箱体：看材质标注是不锈钢 304 还是 201，潮湿环境 201 仍会锈，别一概当不锈；箱门无变形、防盗锁完好。\n2 分流：看 PE 分水器一体化多路、无拼接三通，接口数与户表配置对得上。\n3 表前控制：每户一只黄铜表前阀，钥匙专管，阀门启闭正常。\n4 方向：底部 PE 外丝直接进水、顶部黄铜球阀出水，进出方向别接反，接反了表具读数和维护都不对。\n**【红线】箱体变形、分水器拼接漏点多、表前阀缺失、进出方向接反，任一命中就判异常，不许私自拆装。**\n**落回卡上：**把「不锈钢户表控制箱」「PE分水器」两张卡的结构组成与接口栏并排核一遍。\n\n**自测：普通不锈钢箱体在户外会不会生锈？** 回本课【外观结构：不锈钢防锈】对照。\n\n**自测：户表箱的 PE 口和球阀口分别在哪个方向？** 回本课【接口与维护】对照。","structure":"外壳是不锈钢防锈。内部靠PE分水器多路分流，靠表前阀单独控制。底部进水，顶部黄铜阀出水，带防盗锁。\n引导：本课已把箱体、分流与接口讲透；现场常卡在「进出方向接反」；下一步 C30 看波纹管补偿器。","anchors":[{"name":"不锈钢户表控制箱","ref":"不锈钢户表控制箱"},{"name":"PE分水器","ref":"PE分水器"}],"pitfall":"【严禁暴力私拆内部管路】不锈钢也会生锈（除非304）；表前阀不能乱动；底部PE口进水，顶部球阀出水。","remark":"—","seq":29,"family":"辅材·井室·户表集成","lessonNo":20},{"id":"C38","sub":"XG-02","topic":"闸阀明杆与暗杆：空间、开度与阀井深度辨识","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课只讲弹性座封闸阀明杆与暗杆的辨识和选用边界，不重复C36阀门大类，也不展开启闭力矩计算。目标是看阀杆和阀井空间说清为什么选明杆或暗杆。","framework":"明杆结构｜阀杆随启闭升降，开度外露。暗杆结构｜阀杆原地旋转，不升降。空间差异｜明杆占上方空间，暗杆省空间。开度差异｜明杆直观，暗杆不可见。适用场景｜明杆地面泵房，暗杆地下受限阀井。相邻关系｜与黄铜闸阀、加密闸阀的区别。","lecture":"**相邻关系：向上接 C37《基础管件轮廓与密封紧固辅材速》；向下接 C39《机械水表结构辨识》。**\n\n**现场情境：浅井室要装闸阀，有人选了明杆阀，结果阀杆顶到井盖。** 为什么井深决定选型？本课讲明暗杆。\n\n【明杆：阀杆跟着开度往外伸】\n**明杆闸阀转手轮时，阀杆会一节节升出来，杆伸多长、阀门就开多大。** 像老式水龙头的螺杆，开度明明白白写在杆上，巡检一眼就能读。\n**代价是占上方空间。** 落回卡上：看「弹性座封闸阀（明杆式）」卡的高阀杆和支架，装在浅阀井里，杆升到顶会直接顶到井盖。\n\n【暗杆：阀杆原地转、不升降】\n**暗杆闸阀的阀杆只原地旋转，整根杆藏在阀体里，高度几乎不变。** 它把明杆伸出去的那段收进了阀体，像把天线缩回机壳，省的是头顶那点净空。\n**省了空间，也就丢了开度可视。** 落回卡上：看「弹性座封闸阀（暗杆式）」卡的低矮阀盖，操作只能靠记圈数或限位，看不到杆升到哪。\n\n【为什么这么定：井深决定选型】\n**地下阀井浅、井盖贴着阀顶，就优先暗杆；地面泵房明装、要盯开度，就用明杆。** 这不是密封好坏的差别，是空间和可视二选一。\n**【红线】浅井错发明杆，阀门开到位时阀杆顶穿井盖，检修只能砸井。** 落回卡上：把「明杆式」「暗杆式」两张卡并排看，比的是阀盖高度，不是口径。\n\n【开度与操作：看不见就要靠规程】\n**明杆的开度是给你看的，暗杆的开度得靠圈数、限位或开度指示来记。** 关闭时宁可数圈、别硬拧到底，拧过头会顶坏闸板和密封面。\n**闸阀本就不该半开当调节阀用。** 半开时闸板被水流冲得抖动，密封面很快磨坏。落回卡上：看卡面标注的启闭方式，按规程操作而不是凭手感。\n\n【相邻关系：别和防盗、口径混】\n**黄铜闸阀多是小口径户内件，加密闸阀是在闸阀上加锁控。** 明暗杆讲的是阀杆怎么动，不是防不防盗、也不是口径大小，三件事别搅在一起。\n**认课的次序是：先 C36 断大类，再这课分明暗杆，再挑口径和锁控。** 落回卡上：「黄铜闸阀」「黄铜加密闸阀」是另两张卡，别串成本课的结论。\n\n【材料锚点 · 落回卡上】\n**把「弹性座封闸阀（明杆式）」和「弹性座封闸阀（暗杆式）」两张卡并排点开，本课就讲完了一半。** 比的是阀盖高度和阀杆，不是口径、也不是材质。\n**「黄铜闸阀」「黄铜加密闸阀」是另两张卡，别串成本课结论。** 选明杆还是暗杆由井深和是否要看开度定，具体净空按设计图与卡面复核，本课不代填数值。\n\n**自测：浅井室为什么不宜发明杆闸阀？** 回本课【为什么这么定：井深决定选型】对照。\n\n**自测：暗杆闸阀看不到开度，靠什么确认？** 回本课【开度与操作：看不见就要靠规程】对照。","structure":"主链：看阀杆是否升降→判断空间占用→再判断开度可视→最后匹配阀井。\n要点：1 明杆升降开度直观；2 暗杆原地转省空间；3 浅井优先暗杆；4 泵房明装可用明杆；5 明暗杆不是防盗。\n引导：本课已分明暗杆；现场常卡在浅井错发明杆；下一步看 C39 机械水表结构。","anchors":[{"name":"弹性座封闸阀（明杆式）","ref":"弹性座封闸阀（明杆式）"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"黄铜闸阀","ref":"黄铜闸阀"},{"name":"黄铜加密闸阀","ref":"黄铜加密闸阀"}],"pitfall":"【浅井别发明杆】明杆会顶井盖；暗杆省空间但看不到开度。","remark":"—","seq":30,"family":"XG-02 结构与计量辨识","lessonNo":4},{"id":"C39","sub":"XG-02","topic":"机械水表结构辨识：旋翼式与螺翼式","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课只讲机械水表旋翼式与螺翼式的结构辨识和适用边界，不展开选型经济和检定结论。目标是看叶轮布置和口径说清小户用旋翼、大总管用螺翼。","framework":"旋翼式结构｜叶轮垂直水流，DN15–DN40户用。湿式｜计数器浸水，灵敏便宜。干式｜磁隔离传动，读数清晰。液封｜字轮液体封装，兼顾灵敏与清晰。螺翼式结构｜叶轮水平轴，DN50–DN300大流量。共同点｜都靠水流推叶轮计数。机械水表按口径分界表｜DN15–40 旋翼、DN50–300 螺翼。","lecture":"**相邻关系：向上接 C38《闸阀明杆与暗杆》；向下接 C40《计量设备外观与表体标识》。**\n\n**现场情境：小户水表和总管水表外观相似，有人只看表壳选型。** 旋翼和螺翼怎么分？本课讲叶轮方向。\n\n【水表怎么读：黑字轮整数、红字轮小数】\n**抄表读黑色字轮，它记的是整数（立方米）；红色字轮或指针记的是小数，日常抄表不读。** 指针停在两个数字之间时取小值。像看里程表，先看整数位，红色那几位是零头。落回卡上：找一张机械水表卡，先把黑字轮整数读出来，再对红字轮的位置。\n\n【始动流量与计量等级：水太小它可能不走】\n**水表要水流达到始动流量，叶轮才转得动；“滴水成线”这种细流，可能根本不计量。** 所以家里水龙头滴答漏水，水表未必走字，但水照样流掉了。\n**准确度等级常见 2 级，即常用流量范围内误差 ±2%。** 落回卡上：核卡面的精度等级字段，始动流量与误差限以 JJG 162 与企业计量制度为准。\n\n【强制检定与到期轮换：小表到期换，大口径表按周期检】\n**贸易结算用的水表属强制检定计量器具，到使用年限要轮换：DN15–25 不超过 6 年、DN25–50 不超过 4 年。** 这是小户表的规矩。\n**大口径总管表（DN50 以上）不走“到期整体轮换”这条路，但它仍是强检器具，要按周期做在线或离线检定，检定不合格照样更换——“不轮换”不等于“免检定”。** 大表拆装影响大、价值高，所以管的是“定期验准”而不是“到期一换了之”。落回卡上：看卡面口径与检定字段，具体周期按现行计量检定规程与企业制度执行，本课不代填。\n\n【铅封是计量认证标志：不能私自拆】\n**水表上的铅封（铅丝、封条）是计量认证的标志，私自破坏或拆开即视为违规，计量也可能失准。** 像电表、气表的封签，动了就说不清。落回卡上：看卡面上铅封位置的标注，验收和抄表时先看封志是否完好。\n\n【铭牌四参数 Q1/Q2/Q3/Q4：重点看 Q3 常用流量】\n**水表铭牌上的 Q1、Q2、Q3、Q4 是四个流量参数，最该记住、选表第一眼要看的是 Q3——常用流量。** Q3 是正常工作状态下能准确计量的最大流量，也就是这块表的标称流量；户表常见 Q3=2.5 m³/h。\n**其余三个围着 Q3 转：Q1 最小流量，是能准确计量的下限，低于它“滴水成线”不计量；Q2 分界流量，是高区（误差 ±2%）与低区（±5%）的分界，约为 1.6×Q1；Q4 过载流量，是短时超额运行仍合格的上限，约为 1.25×Q3。** 大小关系记住 Q1<Q2<Q3<Q4。像量程刻度：Q1 是能读准的起点，Q3 是日常主力，Q4 是偶尔能扛的上限。落回卡上：看水表卡的铭牌参数栏，先找 Q3 对上口径与选型；逐档数值以现行标准和技术部门核定为准。\n\n【旋翼式：叶轮立着、像小风车】\n**旋翼式水表的叶轮垂直于水流，水一冲就转，DN15–DN40 的户用小表多是它。** 像插在水里的一架小风车，水流再小也能推动，始动流量低。\n**户内水量小、时大时小，要的就是这份灵敏。** 落回卡上：看「旋翼式机械水表（湿式/干式/液封）」卡的字轮和表壳，先认基表结构再论通信。\n\n【螺翼式：叶轮横躺、顺着水流】\n**螺翼式水表的叶轮是水平轴，水流沿轴线直推，DN50–DN300 的总管大表多是它。** 像水轮机顺着河道装，水流阻力小、扛得住大流量。\n**总管要的是低水损，不是灵敏。** 落回卡上：看「水平螺翼机械水表」卡的大表壳和水平叶轮，别拿它跟户用小表比始动流量。\n\n【湿式、干式、液封：看计数器不在看口径】\n**湿式计数器泡在水里，灵敏便宜但久了读数发雾；干式靠磁隔离传动，读数清爽；液封把字轮封在液体里，两头兼顾。** 这是计数器形式，跟口径无关。\n**【易错】别拿口径去判湿式还是干式。** 落回卡上：同一张「旋翼式机械水表」卡上就列了三种计数器，看字面标注，不看表壳大小。\n\n【为什么这么定：错配会出事】\n**小表硬上总管，叶轮长期超负荷、磨损飞快，计量越走越偏；大表装到户内，细小水流推不动，干脆不计数。** 两头都是漏计或多计。\n**水表是计量器具，选型和检定都以企业计量制度为准。** 落回卡上：核对卡面口径范围与精度等级，本课只教结构辨识，不代为下选型结论。\n\n【相邻关系：智能表先认基表】\n**NB-IoT、光电直读这些智能表，是在旋翼或螺翼基表上加通信模组。** 你先认出基表是旋翼还是螺翼，再看它带了什么模块。\n**【红线】只看通信模组就判表型，等于没认表。** 落回卡上：「NB-IoT智能水表」「光电直读远传水表」是基表加模块，结构仍归本课的两类。\n\n【材料锚点 · 落回卡上】\n**「旋翼式机械水表（湿式/干式/液封）」和「水平螺翼机械水表」是两类基表的样板卡。** 一张看立式小风车叶轮，一张看水平轴大叶轮，点开比叶轮方向最直观。\n**「NB-IoT智能水表」「光电直读远传水表」是基表加通信模组，先认基表再看模块。** 检定、更换周期以企业计量制度为准；本课只教结构辨识，不代为下选型结论。\n\n【机械水表按口径分界表】\n**旋翼与螺翼的第一道分界就是口径，先按 DN 归位再看计数器形式。** 表头：口径档｜表型｜卡面依据｜识别要点。\nDN15–DN40｜旋翼式机械水表（湿式/干式/液封）｜卡面 DN15–DN40｜户用小表，叶轮立着像小风车。\nDN50–DN300｜水平螺翼机械水表｜卡面 DN50–DN300｜总管大表，叶轮横躺顺水流。\nDN15–DN40｜NB-IoT 智能水表（基表加模块）｜卡面 DN15–DN40｜先认基表再看通信。\nDN15–DN300｜光电直读远传水表（基表加模块）｜卡面 DN15–DN300｜同上，不做独立表型。\n**【易错】口径分界是结构辨识线索，不是选型结论；湿式干式液封看计数器，不看口径。** 落回卡上：核「旋翼式机械水表（湿式/干式/液封）」「水平螺翼机械水表」两张卡的 DN 范围；\n具体选型与检定以企业计量制度为准。\n\n**自测：小户结算该用旋翼还是螺翼水表？** 回本课【旋翼式：叶轮立着、像小风车】对照。\n\n**自测：湿式、干式、液封水表区别看哪里？** 回本课【湿式、干式、液封：看计数器不在看口径】对照。","structure":"主链：看口径→看叶轮方向→判断旋翼或螺翼→再看计数器形式。\n要点：1 户用小表多旋翼；2 总管大表多螺翼；3 湿式灵敏干式清晰液封兼顾；4 智能表先认基表；5 水表属计量器具。\n引导：本课已认机械表结构；现场常卡在智能表只看到模组；下一步看 C40 计量设备标识。\n会查表：先按 DN 定旋翼或螺翼，再看计数器形式，智能表先认基表。\n记红线：口径是辨识线索不是选型结论，检定以企业计量制度为准。","anchors":[{"name":"旋翼式机械水表（湿式/干式/液封）","ref":"旋翼式机械水表（湿式/干式/液封）"},{"name":"水平螺翼机械水表","ref":"水平螺翼机械水表"},{"name":"NB-IoT智能水表","ref":"NB-IoT智能水表"},{"name":"光电直读远传水表","ref":"光电直读远传水表"}],"pitfall":"【小户用旋翼，总管用螺翼】别只看表壳；湿式干式液封看计数器，不是看口径。","remark":"—","seq":31,"family":"XG-02 结构与计量辨识","lessonNo":5},{"id":"C40","sub":"XG-02","topic":"计量设备外观与表体标识：机械表、超声波水表、电磁与插入式流量计","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课只讲计量设备外观和表体标识的辨识，不做贸易结算选型结论。目标是分清机械表、超声波水表、电磁流量计和插入式超声波流量计的表体线索。","framework":"机械水表｜叶轮、字轮、表壳。超声波水表｜表体加换能器，无活动部件。电磁流量计｜测量管、线圈、电极、转换器。插入式超声波｜转换器加插入传感器、球阀底座。表体标识｜口径、精度、通信、检定标识。边界｜贸易结算与管网监测要求不同。计量设备口径与用途对照表｜四问归位四类表。","lecture":"**相邻关系：向上接 C39《机械水表结构辨识》；向下接 C41《压力表与压力表弯》。**\n\n**现场情境：管网监测要选流量计，有人把贸易结算表和监测表混为一谈。** 电磁表又有什么要求？本课讲标识。\n\n【电磁流量计衬里材质：按介质选，选错被腐蚀】\n**电磁流量计的衬里直接接触介质，材质按介质选：氯丁橡胶用于一般原水、污水；聚氨酯耐磨，用于含砂浆液；PTFE/PFA 耐强酸碱。** 选错衬里会被介质腐蚀，表就废了。像给管道内壁选防护衣，清水穿普通衣、含沙穿耐磨衣、强酸碱穿耐腐衣。落回卡上：看流量计卡的衬里材质栏，按现场介质逐项核对。\n\n【电极材质按介质选：选错很快点蚀】\n**电极也泡在介质里，材质要按介质定：316L 用于生活、工业用水和弱酸碱；含氯离子的海水用哈氏合金或钛；强腐蚀工况用钽。** 选错电极很快点蚀穿孔。落回卡上：看卡面电极材质栏，先判断介质腐蚀性再定电极。\n\n【电磁流量计必须接地：水、表、管道等电位】\n**电磁流量计必须接地：金属管道直接接地，塑料管道要加装接地环，让水、表、管道处在同一电位。** 不接地，静电和杂散电流会干扰读数，数字乱跳。落回卡上：看安装图的接地要求，塑料管段别忘了接地环。\n\n【超声波时差法与多普勒法：看介质洁净不洁净】\n**超声波流量计分时差法和多普勒法：时差法用于洁净流体、精度高；多普勒法要靠介质里的颗粒或气泡反射，适合浑浊水，精度略低。** 清水用时差、浑水用多普勒，选反了信号弱、读数不准。落回卡上：看卡的测量原理栏，按介质是否含颗粒气泡来区分。\n\n【机械表与超声波表：有没有叶轮】\n**机械水表里有叶轮和字轮，水流推着转；超声波水表表体上装一对换能器，没有活动部件。** 一个靠机械转动、一个靠声波测时差，原理完全不同。\n**两者都可能带远传，别因为都有线就当成一类。** 落回卡上：翻「旋翼式机械水表」「超声波水表」两张卡，先看有没有叶轮、再看显示与通信。\n\n【电磁流量计：线圈、电极、转换器】\n**电磁流量计有测量管、励磁线圈、电极和转换器，靠导电介质切割磁力线测流量。** 它要求介质导电，测量管里空空荡荡、没有任何转动件。\n**【边界】介质不导电就不能用电磁，这是原理决定的。** 落回卡上：看「电磁流量计」卡的转换器与电极位置，和机械表的字轮一眼分得开。\n\n【插入式超声波：带球阀底座】\n**插入式超声波流量计有主机、插入传感器和球阀底座，能在带压管道上开孔装传感器。** 它不截断整段管，适合大口径在线监测。\n**定位精度要看用途，不能和管段式、贸易结算表混说。** 落回卡上：看「插入式超声波流量计」卡的球阀底座，这个部件是它最醒目的外形线索。\n\n【表体标识：口径、精度、通信、检定】\n**表体上要看口径、精度等级、通信方式和检定标识。** 这些是它的身份证，比外壳形状更能说明它能用在哪。\n**【红线】贸易结算与管网监测对计量要求不同，不能凭外观互用。** 落回卡上：逐张核对卡面标识，本课只辨识，不代为下贸易结算选型结论。\n\n【相邻关系：先认原理，再看用途】\n**水表、超声波表、电磁流量计、插入式，是四种计量原理，不是四个档次。** 你先把原理认清，用途和检定要求才有得谈。\n**远传是加装功能，不是独立表型。** 落回卡上：把本组卡按「有无活动部件、是否要导电、是否插入安装」三问排一遍，比记名字牢。\n\n【材料锚点 · 落回卡上】\n**把「旋翼式机械水表」「超声波水表」「电磁流量计」「插入式超声波流量计」四张卡摆一排，用三问分。** 有没有活动部件、要不要介质导电、是不是插入安装，三问下来原理各归各位。\n**「水平螺翼机械水表」是机械表的大口径一支，别和电子式混。** 口径、精度、通信、检定标识逐项读卡面；本课只辨识原理，贸易结算选型另按计量要求。\n\n【计量设备口径与用途对照表】\n**四类计量设备按「口径范围 + 有无活动部件 + 是否要导电 + 是否插入安装」四问归位。** 表头：设备｜卡面口径｜原理线索｜用途边界。\n旋翼式 / 螺翼机械水表｜DN15–DN40 / DN50–DN300｜有叶轮字轮｜户表到总管，属机械基表。\n超声波水表｜DN15–DN300｜无活动部件、换能器测时差｜远传与低始动场景。\n电磁流量计｜DN15–DN300｜要介质导电、线圈电极｜精度 0.5 级，介质不导电不能用。\n插入式超声波流量计｜DN80–DN2400｜插入安装、带球阀底座｜管网监测级；贸易结算应选管段式并执行强制检定。\n**【红线】贸易结算与管网监测对计量要求不同，不能凭外观互用。** 落回卡上：逐张核卡面口径、精度、通信、检定标识；具体选型与检定以企业计量制度为准。\n\n**自测：机械表和超声波表外观上怎么区分？** 回本课【机械表与超声波表：有没有叶轮】对照。\n\n**自测：电磁流量计对介质有什么要求？** 回本课【电磁流量计：线圈、电极、转换器】对照。","structure":"主链：看有无叶轮→看换能器或电极→看转换器→最后看表体标识与用途。\n要点：1 机械表有叶轮字轮；2 超声波无活动部件；3 电磁有电极线圈；4 插入式带球阀底座；5 用途决定检定要求。\n引导：本课已认计量设备外观；现场常卡在远传表只看通信不看基表；下一步看 C41 压力表与表弯。\n会查表：按口径、活动部件、导电、插入安装四问分四类。\n记红线：贸易结算与管网监测不能混说，选型检定以企业计量制度为准。","anchors":[{"name":"旋翼式机械水表（湿式/干式/液封）","ref":"旋翼式机械水表（湿式/干式/液封）"},{"name":"水平螺翼机械水表","ref":"水平螺翼机械水表"},{"name":"超声波水表","ref":"超声波水表"},{"name":"电磁流量计","ref":"电磁流量计"},{"name":"插入式超声波流量计","ref":"插入式超声波流量计"}],"pitfall":"【先认基表再看通信】电磁要求导电介质；贸易结算与管网监测不能混说。","remark":"—","seq":32,"family":"XG-02 结构与计量辨识","lessonNo":6},{"id":"C41","sub":"XG-02","topic":"压力表与压力表弯：缓冲方向、直连风险与安装初辨","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课只讲压力表和压力表弯的辨识与缓冲方向，不重复C37基础辅材轮廓，也不展开压力表量程选型计算。目标是说清表弯为什么必须缓冲、直连有什么风险。","framework":"压力表结构｜表壳、弹簧管、机芯、指针、螺纹接口。表弯形式｜O型、U型、Ω型。缓冲机理｜形成缓冲容积，削减压力脉动。冷凝降温｜高温介质在弯管内降温。直连风险｜水锤直接冲击弹簧管和机芯。安装初辨｜压力表垂直，表前设表弯或表阀。","lecture":"**相邻关系：向上接 C40《计量设备外观与表体标识》；向下接 C42《紧固件受力分工》。**\n\n**现场情境：装压力表时有人图省事直接连管道，表盘还装歪了。** 会带来什么问题？本课讲表弯缓冲。\n\n【表弯存水液封：隔离高温、防蒸汽冲表】\n**压力表弯（冷凝弯）里要存一段水或冷凝液，形成液封，把高温介质隔开、防止蒸汽直接冲进表里；蒸汽管路必须装。** 像给表前放一道水屏障，热蒸汽先在这段弯管里冷凝降温，到表时已是凉的。落回卡上：看「压力表弯（缓冲弯/冷凝弯）」卡的弯形，安装后先确认存水再投用。\n\n【压力表怎么工作：弹簧管带指针】\n**压力表靠里面一根弹簧管受压变形，经机芯放大带动指针读数。** 这根弯扁管很娇气，怕瞬间冲击、也怕长期高温。像一根被反复掰的弹簧片，掰急了就回不正。\n**看表盘量程和接口螺纹，再看表前有没有表弯。** 落回卡上：翻「压力表」卡的表盘与螺纹接口，先认表、再认它的保护件。\n\n【表弯为什么缓冲：攒出一段容积】\n**表弯是 O、U 或 Ω 形的小弯管，绕出一小段缓冲容积，把水锤脉动先卸在这里。** 像给水管接了个小气囊，压力尖峰被它抹平，传到表上就温和了。\n**弯管还拉长了路径，让高温介质在里头先降降温。** 落回卡上：看「压力表弯（缓冲弯/冷凝弯）」卡的弯形，一圈不是为了好看，是为了缓冲和冷凝。\n\n【直连风险：省一件事、坏一块表】\n**压力表直接拧在管上，水锤会一记打在弹簧管和齿轮机芯上。** 短时冲击能把指针打弯、让零点漂掉，长期脉动会把机芯磨松，读数慢慢就不准了。\n**【红线】表弯不是装饰件，图省事直连就是拿表去扛水锤。** 落回卡上：把「压力表」和「压力表弯」两张卡放一起，它们本就该成对出现。\n\n【安装初辨：垂直、表前留阀】\n**压力表要垂直安装，表前设表弯或表阀，方便检修和断压。** 表盘朝上或朝操作面，读数才看得清、也便于更换。\n**表阀能在不停水时把表摘下来校验。** 落回卡上：看卡面安装示意，量程与表阀按设计选型，本课只讲辨识和缓冲方向。\n\n【相邻关系：表弯不是普通弯头】\n**普通弯头只改方向，表弯要形成缓冲容积和冷凝路径，两件事不能互替。** 你若拿一个 90 度弯头装表前，方向是改了，缓冲一点没加。\n**再分清：表弯护表，过滤器护阀芯，减压阀护管网，各管各的。** 落回卡上：C37 已认过表弯轮廓，这课讲清它为什么必须存在。\n\n【材料锚点 · 落回卡上】\n**「压力表」和「压力表弯（缓冲弯/冷凝弯）」本就该成对出现，点开两张卡一起看。** 一张看表盘与螺纹接口，一张看 O/U/Ω 弯形，缺哪张都说明这处安装少了保护。\n**表弯护表、过滤器护阀芯，各管各的，别拿普通弯头顶替。** 量程与表阀按设计选型，本课只讲缓冲方向和直连风险，不代填量程数值。\n\n**自测：压力表为什么不能直接连管道？** 回本课【直连风险：省一件事、坏一块表】对照。\n\n**自测：表弯为什么能保护压力表？** 回本课【表弯为什么缓冲：攒出一段容积】对照。","structure":"主链：看表盘→看接口→看有无表弯→判断缓冲与冷凝→最后看安装方向。\n要点：1 压力表靠弹簧管；2 表弯形成缓冲容积；3 直连水锤打表；4 高温靠弯管降温；5 表弯不是普通弯头。\n引导：本课已认表弯作用；现场常卡在直连图省事；下一步看 C42 紧固件受力分工。","anchors":[{"name":"压力表","ref":"压力表"},{"name":"压力表弯（缓冲弯/冷凝弯）","ref":"压力表弯（缓冲弯/冷凝弯）"}],"pitfall":"【压力表别直连】表弯不是普通弯头；表盘要垂直，表前留表阀。","remark":"—","seq":33,"family":"XG-02 结构与计量辨识","lessonNo":7},{"id":"C42","sub":"XG-02","topic":"紧固件受力分工：半丝抗剪与全丝调节","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课只讲六角头螺栓半丝与全丝的外观和受力分工，不重复C37轮廓，也不展开扭矩计算。目标是说清法兰为什么用半丝、管卡支架为什么可用全丝。","framework":"半丝外观｜一段光杆加一段螺纹。全丝外观｜全长螺纹。法兰受力｜横向剪切与对中。光杆作用｜在法兰孔内抗剪、定位。全丝用途｜管卡、支架、设备底座调节长度。相邻关系｜与胶垫、法兰、管卡配套。","lecture":"**相邻关系：向上接 C41《压力表与压力表弯》；向下接 C43《井盖类型与承载标识》。**\n\n**现场情境：有人觉得全丝螺栓螺纹多、等级更高，法兰上就想用全丝。** 这是一种误解吗？本课讲受力分工。\n\n【螺栓露出螺母 2-3 扣：太少不牢、太多碰伤】\n**螺栓拧紧后，端部应露出螺母 2-3 扣：太少咬合不足、容易脱扣；太多浪费，还容易碰伤人或设备。** 像拧螺丝留出的那点余量，刚好。落回卡上：看「六角头螺栓（半丝/全丝）」卡，紧固后数一下露出的扣数。\n\n【平垫加弹垫、对角分次紧：垫片受力才均匀】\n**平垫扩大受力面、防止啃伤法兰；弹垫防松动；法兰螺栓要对称、分次拧紧，才能保证垫片受压均匀、不偏漏。** 像对角拧车轮螺丝，一次紧死一边会把轮毂拧歪——螺栓同理，单边一次拧死会把垫片压偏。落回卡上：把「六角头螺栓」「胶垫（法兰橡胶垫片）」两张卡摆一起看，紧固顺序和垫片受压一起记。\n\n【半丝与全丝：看螺纹到没到头】\n**半丝螺栓有一段光滑杆、只有尾部带螺纹；全丝螺栓从头部到尾端全是螺纹。** 像一根杆子一半缠了绳、一半光着，光杆那段不是偷工，是故意留的。\n**先数螺纹有没有爬到头部，一眼定类型。** 落回卡上：看「六角头螺栓（半丝/全丝）」卡，两种并排一比就清楚。\n\n【法兰为什么用半丝：光杆抗剪对中】\n**法兰对接时，螺栓在孔里主要扛横向剪切，还要把两片法兰对正。** 光杆段贴合孔壁、截面饱满，抗剪又定位，力由整段光杆均匀承担。\n**全丝在孔内是螺纹顶着孔壁，牙底截面小、还带应力集中。** 落回卡上：看「钢法兰（平焊/对焊）」卡的螺栓孔，孔是配光杆的，不是配牙的。\n\n【全丝为什么用于支架：任意位置停螺母】\n**管卡、支架、设备底座要调的是长度，螺母得能停在任意位置。** 全丝全长有牙，拧到哪停到哪，通用性强；它不进法兰孔扛剪切，受力小得多。\n**【易错】全丝不是等级更高、也不是更结实，是用途不同。** 落回卡上：本课的「六角头螺栓（半丝/全丝）」一张卡就覆盖两种，看用在哪再选。\n\n【为什么这么定：选错是会断的】\n**法兰上错装全丝，剪切力压在螺纹牙底，振动一久可能从牙根断裂，法兰面张开就漏水。** 支架上硬用半丝，光杆段调不动长度，装起来别扭。\n**【红线】不是越贵越好，是受力位置决定用哪种。** 落回卡上：法兰配半丝、支架配全丝，按场景对号，不按价格。\n\n【相邻关系：螺栓要和胶垫（法兰橡胶垫片）法兰配套】\n**一处法兰节点，是胶垫（法兰橡胶垫片）密封、法兰承压、螺栓夹紧三件一起干活。** 落回卡上：把「胶垫（法兰橡胶垫片）」「钢法兰（平焊/对焊）」「六角头螺栓（半丝/全丝）」摆一起，缺哪件都不成。\n**生料带（聚四氟乙烯密封带）只管螺纹密封，不管螺栓抗剪，别拿它当强度措施。** 紧固要按对角分次上紧，等级与扭矩以设计文件为准，本课只讲分工。\n\n【材料锚点 · 落回卡上】\n**「六角头螺栓（半丝/全丝）」一张卡就覆盖本课的两种件，点开数螺纹有没有到头。** 再配「钢法兰（平焊/对焊）」「胶垫（法兰橡胶垫片）」，正好凑成一个法兰节点。\n**法兰配半丝、支架配全丝，按受力位置选，不按价格选。** 螺栓等级、扭矩、防腐以设计文件与卡面为准；生料带（聚四氟乙烯密封带）只管螺纹密封，别当抗剪措施。\n\n**自测：法兰连接为什么要用半丝螺栓？** 回本课【法兰为什么用半丝：光杆抗剪对中】对照。\n\n**自测：全丝螺栓适合用在哪？** 回本课【全丝为什么用于支架：任意位置停螺母】对照。","structure":"主链：看螺纹长度→判断半丝或全丝→匹配法兰或支架→最后看等级与防腐。\n要点：1 半丝带光杆；2 全丝全螺纹；3 法兰用半丝抗剪；4 支架用全丝调节；5 螺纹处受剪易断。\n引导：本课已认螺栓分工；现场常卡在法兰错拿全丝；下一步看 C43 井盖承载标识。","anchors":[{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"钢法兰（平焊/对焊）","ref":"钢法兰（平焊/对焊）"}],"pitfall":"【法兰别用全丝】半丝光杆抗剪；全丝用于支架调节，不是等级更高。","remark":"—","seq":34,"family":"XG-02 结构与计量辨识","lessonNo":8},{"id":"C43","sub":"XG-02","topic":"井盖类型与承载标识：球墨铸铁重型与复合轻型","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课只讲井盖类型、承载标识和场景边界，不展开井室结构设计。目标是看材质和标识说清车行道消防通道用球铁重型，绿化带人行道可用复合轻型。","framework":"球铁井盖｜QT450-10，D400重型。复合井盖｜SMC或树脂复合，A15/B125/C250。承载标识｜试验荷载与使用场景。功能标识｜给水、消防等永久字样。防盗差异｜复合无回收价值，球铁配锁具。场景边界｜消防车道必须重型。承载等级×使用场景对照表｜D400 到 A15 逐档对。","lecture":"**相邻关系：向上接 C42《紧固件受力分工》；向下接 C44《球铁管件端头逻辑》。**\n\n**现场情境：消防车道上井盖坏了，有人想用复合轻型盖去换，还以为 D400 是厚度。** 危险在哪？本课讲承载标识。\n\n【井盖下方装防坠网：井盖没了也能兜住人】\n**检查井盖下方要装防坠网：井盖缺失、破损或被掀开时，防坠网能兜住坠落的人或物，是自来水井室的实际安全配置。** 安装要固定在井筒内壁、网边压实，发现破损缺失要及时补装。像给井口加了道安全带，盖子在时看不见，出事时才救命。落回卡上：看「球墨铸铁井盖（给水/消防）」卡的配套件，确认防坠网在位、挂牢。\n\n【球铁与复合：材质先分】\n**球墨铸铁井盖强度高、韧性好，能做 D400 重型；复合井盖是 SMC 或树脂，质轻、无回收价值。** 一个压不碎但沉，一个搬得动但承载低。\n**先掂重量、看背面材质和加强筋。** 落回卡上：翻「球墨铸铁井盖（给水/消防）」「复合井盖（给水/消防）」两张实物图，材质是第一道分界。\n\n【承载标识：D400 与 A15/B125/C250】\n**井盖上的 D400、B125 是承载等级，数字对应试验荷载和使用场景。** D400 是车行道、消防车道级别；复合多为 A15 到 C250 的轻中等级。\n**【红线】标识看不清就别凭厚度猜等级。** 落回卡上：看卡面标注的承载等级，等级是印在盖上的，不是估出来的。\n\n【为什么这么定：压碎是要出人命的】\n**消防车、重卡碾过轻型井盖，超过承载就开裂塌陷，车轮陷进去车毁人伤。** 球铁重型还要配井座和减震胶条，把重载均匀传到井圈。\n**【红线】消防车道不能拿复合轻型凑合，省钱省在这里最危险。** 落回卡上：核对设计道路等级再选盖，本课不代为下结构结论。\n\n【功能标识与防盗：两码事】\n**盖面上的「给水」「消防」是永久功能字样，方便运维找阀门井。** 防盗是另一回事：复合没有回收价值，球铁靠锁具和铰链防撬。\n**别把防盗好当成承载高。** 落回卡上：功能字样、承载等级、防盗结构在卡上是三个字段，逐一读，别混成一个结论。\n\n【相邻关系：井盖是井的一部分】\n**井盖要连着井座、防坠网、消火栓井或阀门井一起看，不是只看圆不圆。** 落回卡上：「地上式消火栓」「地下式消火栓」也在本组，认盖顺带认清井的用途。\n**本课只讲类型、标识和场景边界，井室结构留给设计。** 装错等级是安全红线，装错字样是运维麻烦，性质不同。\n\n【材料锚点 · 落回卡上】\n**「球墨铸铁井盖（给水/消防）」「复合井盖（给水/消防）」两张卡，比的是材质和承载标识。** 点开看背面加强筋、盖面 D400 或 B125 字样，再读「给水」「消防」功能字样。\n**「地上式消火栓」「地下式消火栓」也在本组，认盖顺带认清井的用途。** 承载等级以设计道路等级复核为准，本课不代为下结构结论；装错等级是安全红线。\n\n【承载等级 × 使用场景 对照表】\n**井盖上的等级不是装饰，它对应试验荷载和能走什么车。** 表头：等级标识｜常见材质｜使用场景｜核对动作。\nD400｜球墨铸铁重型｜车行道、消防车道｜核设计道路等级与卡面 D400 字样。\nC250｜复合或球铁｜轻型机动车偶尔通行区域｜核卡面等级与场景边界。\nB125｜复合轻型｜人行道、非机动车道｜核功能字样与承载标识。\nA15｜复合轻型｜绿化带、行人区｜不得用于车行道。\n**【红线】等级是印在盖上的，标识看不清就别凭厚度猜；消防车道不能用复合轻型凑合。**\n落回卡上：看「球墨铸铁井盖（给水/消防）」「复合井盖（给水/消防）」两张卡的 D400 与 A15/B125/C250 标注；试验荷载数值与适用道路等级以现行标准及设计文件核定，本课不代填。\n\n**自测：消防车道为什么不能用复合轻型井盖？** 回本课【为什么这么定：压碎是要出人命的】对照。\n\n**自测：D400 指的是厚度还是承载等级？** 回本课【承载标识：D400 与 A15/B125/C250】对照。","structure":"主链：看材质→看承载等级→看使用场景→最后看功能字样。\n要点：1 球铁可做D400；2 复合多为轻型；3 消防车道用球铁重型；4 复合防盗但不耐重载；5 功能字样便于运维。\n引导：本课已认井盖边界；现场常卡在消防通道错用复合；下一步看 C44 球铁端头逻辑。\n会查表：等级标识 → 材质 → 场景 → 核对动作，四列一起看。\n记红线：等级以卡面标识为准，试验荷载数值以现行标准与设计核定为准。","anchors":[{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"复合井盖（给水/消防）","ref":"复合井盖（给水/消防）"},{"name":"地上式消火栓","ref":"地上式消火栓"},{"name":"地下式消火栓","ref":"地下式消火栓"}],"pitfall":"【消防车道别用复合轻型】D400球铁才扛重载；复合无回收价值但承载低。 【D400 不是厚度】等级是印在盖上的，试验荷载数值以现行标准核定为准。","remark":"—","seq":35,"family":"XG-02 结构与计量辨识","lessonNo":9},{"id":"C54","sub":"XG-03","topic":"有限空间为什么危险：缺氧、有毒气体与“先通风、再检测、后作业”机理","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课只讲说得出：阀门井、水表井为什么是有限空间，为什么不能靠闻味判断，为什么铁律是先通风、再检测、后作业。不写气体浓度限值、审批层级和通风时长。目标是能复述风险机理和铁律因果。","framework":"有限空间识别｜阀门井、水表井、消火栓井；出入口受限、通风不良。风险来源｜缺氧、有毒气体、积水、坠落、机械伤害。为什么不能闻味｜缺氧和有毒气体可能无味；打火机试更危险。通风作用｜稀释和置换井内气体，补充新鲜空气。检测作用｜确认能否进入；不合格不进入。监护作用｜监护人不得离岗，单人不下井。常见错误｜探头闻味、单人下井、快关快上、通风完直接下。","lecture":"**相邻关系：向上接 C53《井室与作业现场安全设施初识》；向下接 C55《PPE与环境风险辨识》。**\n\n**现场情境：工人下井前说“闻着没味儿就没事”，通风后也没检测就准备下去。** 这个判断错在哪？本课讲有限空间机理。\n\n【气体检测四类指标：氧气、可燃、硫化氢、一氧化碳】\n**下井前至少要测四类气体：氧气、可燃气体、硫化氢、一氧化碳；氧含量 19.5%–23.5%、可燃气体不超过爆炸下限的 10%，合格才能进。** 像登机前的安全检查，四项缺一不可。落回卡上：看气体检测仪卡的检测项目栏，按顺序逐项测、逐项记。\n\n【上中下三点分层检测：不漏死角】\n**竖直井要按规定检测上、中、下三点（距顶、底各不超过 1m），水平方向近端、远端各不少于一点，不漏检测死角。** 气体轻重不同，重的沉底、轻的浮顶，只测一处会漏。像量水温，上中下都要测才知道分层。落回卡上：看有限空间检测示意图，按点位逐层测、不留空档。\n\n【有毒气体限值：闻不到不代表没有】\n**硫化氢≤10mg/m³、一氧化碳≤30mg/m³（GBZ 2.1）；硫化氢会麻痹嗅觉，闻不到臭味不代表没有，反而更危险。** 像煤气加了臭味剂提醒人，可硫化氢偏偏把鼻子麻掉，只能靠仪器。落回卡上：看气体检测卡的限值表，以仪器读数为准，别靠鼻子判断。\n\n【有限空间识别】\n**阀门井、水表井、消火栓井是有限空间。** 出入口受限、空间狭窄、通风不良。**有限空间不等于有大坑。** 井口小、内部有管线阀门积水，也是有限空间。**识别先看入口和通风条件。\n** 不能只看井盖大小。**井盖是入口，不是安全许可。** 打开井盖只代表能看，不代表能进。**与C53关系：C53认设施，本课说清为什么不能直接下。** 设施认识是基础，风险机理是下一步。\n\n【风险来源】\n**有限空间风险是复合的。** 缺氧、有毒气体、积水、坠落、机械伤害可能同时存在。**缺氧不一定有气味。** 人可能在无味环境中头晕倒地。**有毒气体也可能无味。** 闻不到不等于安全。\n**积水会带来溺水和滑倒。** 井壁湿滑，上下困难。**本课不写具体限值。** 检测项目和合格判据按企业作业票与标准原文。\n\n【为什么不能闻味】\n**探头闻味不是检测。** 鼻子不能判断氧气含量和有毒气体浓度。**打火机试更危险。** 可能引燃可燃气体。**闻不到气味也可能危险。** 一氧化碳等气体不一定有明显气味。**正确做法是按作业票检测。\n** 用检测结果判断能否进入。**本课只讲原则，不写检测限值。** 具体按企业制度和标准原文。\n\n【通风作用】\n**通风是稀释和置换井内气体。** 它降低有害气体浓度，补充新鲜空气。**通风不等于检测合格。** 通风后仍要检测，不能通风完就下。**通风要持续到作业过程。** 作业中保持通风和监护。\n**通风设备要放在井口合适位置。** 不能把废气吹回井内。**本课不写通风时长。** 时长按作业票和现场条件确定。\n\n【检测作用】\n**检测是确认能不能进入。** 它回答“现在能否作业”，不是走过场。**检测要在通风后进行。** 先通风再检测，顺序不能倒。**检测不合格继续通风并按作业票处理。** 仍不合格不进入。**检测要记录。\n** 记录是作业票的一部分，便于追溯。**本课不写检测项目和限值。** 按企业作业票和标准原文执行。\n\n【监护作用】\n**监护人是井上最后一道防线。** 监护人不得离岗，保持联络。**单人不下井。** 没有监护的作业不能开始。**监护人发现异常先呼救报警。** 不盲目下井拉人。**监护人还要看周边交通和围挡。\n** 防止路人坠落和车辆误入。**与C56关系：C56讲完整顺序和应急。** 本课先把机理说清。\n\n【常见错误】\n**探头闻味是偷懒。** 看着快，坑在闻不到也可能危险。**单人下井是偷懒。** 看着省人，坑在无人监护。**快关快上是偷懒。** 看着省时间，坑在未检测合格。**通风完直接下是偷懒。\n** 看着通风了，坑在没检测。\n\n**自测：闻不到异味，能不能证明井内安全？** 回本课【为什么不能闻味】对照。\n\n**自测：为什么通风之后还必须检测？** 回本课【通风作用】对照。","structure":"主链：识别有限空间→通风→检测→合格后作业→监护全程。因果链：闻不到也可能危险→所以不能靠闻味→必须通风检测→未合格不进入。对照：正确铁律 vs 探头闻味、单人下井、通风完直接下。要点：1 阀门井水表井是有限空间；2 闻不到也可能危险；3 先通风再检测后作业；4 未检测合格不进入；5 监护人不得离岗。引导：本课已说清为什么不能直接下；现场常卡在赶时间先下；下一步C55辨PPE与环境风险。","anchors":[{"name":"地下式消火栓","ref":"地下式消火栓"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"不锈钢户表控制箱","ref":"不锈钢户表控制箱"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"复合井盖（给水/消防）","ref":"复合井盖（给水/消防）"}],"pitfall":"【闻不到不等于安全】通风后还要检测；未检测合格不进入；监护人离岗等于失守。","remark":"企业填：作业票、检测、监护按企业现行制度；不生成限值/审批层级/通风时长","seq":36,"family":"XG-03 安全生产与作业底线","lessonNo":2},{"id":"C58","sub":"CL-01","topic":"PE给水管与PE管件验收：外径、端头与热熔配套","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课讲 PE 给水管与 PE 管件验收的基础分论：能说清 PE 管外观、De 外径与 DN 的关系、平口热熔件与丝口件的端头差异，以及法兰头、管帽的配套核对。复杂到货异常留待后续课程展开。","framework":"外观与标识｜黑管蓝线、6m定尺直管、喷码。\n口径体系｜DN 与 De、SDR、PE100/PE80。\n管件端头｜平口热熔件、内丝/外丝直接。\n法兰与管帽｜PE法兰头/片、管帽配套。\n标准与状态｜GB/T 13663 系列、公司现用。\n包装存放｜避光、防暴晒、端头保护。","lecture":"**相邻关系：向上接 C57《材料验收五道关卡与现场可量项》；向下接 C61《PPR给水管及管件验收》。**\n\n**现场情境：图纸 DN100 的 PE 管到货，实物印着 De110，还混进一根端头进泥的旧件。** 怎么验？本课讲外径与端头。\n\n【先认 PE 管外观】\n**PE 给水管是黑管带蓝色标识线。** 你看到一根根6m直黑管，先找管身那条蓝线；卡上名称写 PE给水管，型号 DN20–DN630，材质 PE100/PE80。\n**黑管防紫外线，蓝线表示给水用途。** 看到全黑无标识的管，你不要直接当给水管验收；它可能是排污管或非给水用途。\n**PE 给水管多为 6m 定尺直管。** 小口径也有盘管供货；你验收时看喷码是否与卡面一致，还要看管身有没有压扁变形。\n**外观过关不等于规格过关。** 你还要读 De、SDR 和压力等级；只凭黑管蓝线就放行，等于没验收。\n【口径体系是 PE 验收重点】\n**PE 管认外径 De，不认内径。** 图纸写 DN100，PE 管实物常见 De110；钢管同标 DN100 外径常是 Φ114，两者不一样。\n**SDR 决定壁厚和承压。** SDR 数值越小壁厚越厚；卡上常见 SDR11/17，你验收时要跟设计或卡面一致，别看错一位。\n**PE100 与 PE80 不是同一强度。** PE100 的 MRS 为 10 MPa，同压力等级壁厚可小于 PE80；PE80 的 MRS 为 8 MPa，柔韧性更突出。\n**读喷码要读全。** 名称、规格、压力等级、标准号、批次，能和送货单对上再往下走；少读一段，后面就可能拿错。\n【管件端头分平口与丝口】\n**平口是热熔件，丝口是转换件。** 你拿起一个 PE 管件，先看端头：光秃秃两头平的是热熔件；带一圈铜色螺纹的是内丝或外丝直接。\n**PE大小头（异径管）、三通、弯头、PE直接、管帽多为平口热熔。** 卡上 PE 管件标准写 GB/T 13663.3-2018，原料等级要与母管 PE100/PE80 对应。\n**PE法兰头/片是一端热熔一端法兰。** 卡上 PN10/16、DN100–1200，你验收看法兰盘螺栓孔与热熔端是否完好；它和钢法兰（平焊/对焊）不是一回事。\n**PE管帽（堵头）看封口和端头。** 卡上 DN≥63，验收看端头无损伤、标识与规格一致；管帽不是两端法兰，别和法兰盖混。\n【法兰与管帽配套核对】\n**法兰头不是钢法兰（平焊/对焊）。** PE 法兰头/片一端是 PE 可熔端，一端是法兰盘；你不能拿钢法兰（平焊/对焊）标准直接套，套错了压力等级就错。\n**配套要看阀门或设备接口。** 法兰压力等级、DN、螺栓孔数要能对上；垫片另配，别把 PE 法兰当万能转换。\n**管帽用于封堵预留口。** 你验收看它和母管同规格、同原料等级，端头无变形；管帽内壁也要干净。\n**混装先分开。** 同箱里大小头、PE直接、管帽混放，你按卡名和规格逐项分；混着装回去，下次发料必错。\n【标准状态与存放】\n**标准栏要读版本。** PE 给水管和管件卡上分别写 GB/T 13663.2-2018、GB/T 13663.3-2018；卫生性能符合 GB/T 17219-2025。\n**状态栏看公司现用。** 现用件按现用验收；非现用先隔离，你不凭名字发料。\n**PE 管怕晒。** 露天暴晒会加速老化，你验收看到长期暴晒、管身发白要待检；存放要遮阳。\n**端头保护不能少。** 管口进泥、划伤会影响热熔质量，你验收看端头封盖和清洁；端头脏了先清理再判。\n\n**自测：DN100 的 PE 管该核对哪个外径？** 回本课【口径体系是 PE 验收重点】对照。\n\n**自测：端头进泥的 PE 管件能不能正常入库？** 回本课【管件端头分平口与丝口】对照。","structure":"主链：认黑管蓝线→读 De 与 SDR→分平口与丝口→核法兰头/管帽→对标准状态→查包装端头。\n对照：DN vs De；PE100 vs PE80；平口热熔件 vs 丝口转换件。\n要点：1 PE 管认外径 De；2 SDR 越小壁厚越厚；3 平口热熔、丝口转换；4 法兰头不是钢法兰；5 非现用先隔离。\n引导：本课已说清 PE 管与管件验收基础；现场常卡在拿 DN 当 De 量；下一步 C59 讲球墨铸铁管及管件验收。","anchors":[{"name":"PE给水管","ref":"PE给水管"},{"name":"PE大小头（异径管）","ref":"PE大小头（异径管）"},{"name":"PE法兰头/片","ref":"PE法兰头/片"},{"name":"PE管帽（堵头）","ref":"PE管帽（堵头）"}],"pitfall":"【PE 只认外径 De】DN100 看 De110，别和钢管 Φ114 混；非现用先隔离；端头进泥要待检。","remark":"D2 基础分论，能力达标由 C59 及后续课程承接；企业填：压力等级按设计核对","seq":37,"family":"CL-01 材料验收入库与标准核对","lessonNo":2},{"id":"C61","sub":"CL-01","topic":"PPR给水管及管件验收：S系列、端头与活接","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课讲 PPR 给水管及管件验收的基础分论：能说清 PPR 外观、温度边界、S 系列壁厚，以及热熔件、铜嵌件、活接头、法兰的端头差异。复杂热熔工艺在后续安装课，不在本课展开。","framework":"外观标识｜绿/白直管、冷热水线。\n温度边界｜长期≤70℃、瞬间≤95℃。\nS系列｜母管本体 S2.5/S3.2/S4；管件可见 S5。\n热熔件｜弯头、三通、直接、管帽。\n铜嵌件｜内丝直接、外丝直接。\n活接与法兰｜活接头、PPR法兰。\n标准状态｜GB/T 18742 系列、公司现用。S 系列 / 壁厚 / 承压对照表｜S2.5 到 S5 逐档怎么对。","lecture":"**相邻关系：向上接 C58《PE给水管与PE管件验收》；向下接 C59《球墨铸铁管及管件验收》。**\n\n**现场情境：一批 PPR 管到货，冷水管和热水管外观相近，活接件还要查垫片。** 验收重点是什么？本课讲 S 系列。\n\n【先认 PPR 外观】\n**PPR 给水管多是绿色或白色直管。** 卡上名称 PPR给水管，DN20–DN160，管身常印蓝色冷水线或红色热水线；你看到黑色带蓝线的6m直管，那是PE，不是 PPR。\n**PPR 是绿白直管。** 它材质较硬，和 PE 黑管蓝线外观明显不同；你验收先看颜色和标线，能快速分族。\n**冷热水线是用途提示。** 你验收看标识与卡面一致，不能只看颜色；颜色相近的管，用途可能不同。\n**PPR 怕晒。** 长期露天暴晒会老化变脆，你验收看到管身发白、表面粉化要待检；存放要避光。\n【温度边界要记牢】\n**PPR 耐热但不耐高温主干。** 卡上写长期工作水温≤70℃，瞬间峰值≤95℃；你拿它上集中供暖高温主干，变形爆管是迟早的事。\n**超过 70℃ 不是普通 PPR 的常规边界。** 你不能把冷水管当热水管，也不能用于高温供暖主干；温度边界先看用途。\n**温度边界与 S 值要一起看。** 热水系统选薄壁冷水管，受热后承压能力下降；你只看 S 值不看用途，也会选错。\n**验收看喷码用途。** 冷水管、热水管标识要与设计一致；喷码读不清，先待检。\n【S 系列看壁厚】\n**S 数值越小，壁厚越厚，承压越高。** 卡上 PPR 给水管本体列 S2.5/S3.2/S4；管件中可见 S5。你验收先读母管喷码的 S 值。\n**S2.5 常用于热水管，S3.2/S4 冷热水均有。** 你把 S5 薄壁管当热水管用，受热后承压下降；S5 多见于管件规格，母管本体常见 S2.5/S3.2/S4。\n**S 值和 DN 一起读。** 同 DN 不同 S，壁厚不同；你只看口径不看 S，等于没读规格。\n**喷码不清先待检。** 你读不出 S 值，不凭手感猜；手感分不出 S2.5 和 S4。\n【管件端头分三类】\n**平口是热熔件。** PPR 弯头、三通、PPR直接、管帽两端平口，靠热熔承插；你看端头光秃秃、没有铜牙，就是热熔件。\n**铜色螺纹是嵌件件。** PPR 内丝直接、外丝直接带铜嵌件，用来接金属阀门或水龙头；你看到一圈铜牙，就别往热熔件里归类。\n**带大螺母的是活接头。** PPR活接头（内丝/外丝直接）中间有活接螺母，靠内部垫片密封，可拆；你看到大螺母，就知道它是检修用的。\n**法兰是一头热熔一头法兰盘。** PPR法兰（法兰转换）用于接大口径阀门或设备；你验收看法兰盘和热熔端是否配套。\n【活接与法兰验收】\n**活接头看螺母和垫片。** 卡上 DN20–DN100，你验收看螺母完整、垫片在位、螺纹规整；垫片丢了，装上去必漏。\n**活接头不是普通直接。** 它用于设备检修拆卸，你不能拿平口直接代替；代替了，设备坏了就得剪管。\n**PPR 法兰看法兰盘和热熔端。** 卡上 PN10/16、DN20–160，你验收看螺栓孔、密封面、热熔端无损伤；密封面有划伤，垫片压不住。\n**铜嵌件不能松动。** 嵌件松动、内衬开裂要待检；你用手转一下铜牙，能转动就是隐患。\n【标准状态与存放】\n**标准栏读 GB/T 18742.2-2017 和 GB/T 18742.3-2017。** 管材和管件分别对应，卫生性能符合 GB/T 17219-2025；你验收看卡面标准号，别拿 PE 标准套 PPR。\n**状态栏看公司现用。** 非现用先隔离，你不凭名字发料；PPR 法兰采集包现用栏为空，建议企业确认后再作现用锚点。\n**PPR 管件同材质同寿命。** 你验收看标识、端头、铜嵌件，不混入 PE 或衬塑件；混一件，现场就多一个漏点。\n**避光存放。** 长期暴晒的 PPR 管发白变脆，你验收要待检；库房靠窗的位置也别长期放。\n【S 系列 ↔ 壁厚 ↔ 承压 对照表】\n**PPR 卡上的 S2.5 / S3.2 / S4 / S5 是壁厚系列，数字越小壁越厚、越扛压。** 表头顺序：S 系列｜壁厚趋势｜常见落点｜核对动作。\nS5｜最薄｜管件卡面可见 S5｜用于较低压力段，按设计核。\nS4｜较薄｜管壁与管件均常见｜核对冷热水用途与温度边界。\nS3.2｜较厚｜常用承压档｜核对设计压力与卡面标注。\nS2.5｜最厚｜高承压档｜核对是否满足泵房或高层压力。\n**【红线】S 系列是 PPR 的壁厚系列，别和 PE 的 SDR 混算；逐档壁厚与承压对应值由技术部门按现行标准核定。**\n落回卡上：看「PPR给水管」卡的 DN20–DN160、S2.5/S3.2/S4，以及「PPR直接」卡的 S5，管件与母管的 S 系列不一定相同，验收要分别对。\n**自测：读上面的对照表，S2.5、S3.2、S4、S5 四档壁厚从厚到薄怎么排？** 回本表按「数字越小壁越厚」推，具体选型仍以设计为准。\n\n**自测：同一根 DN25 的 PPR 管，S2.5 和 S5 该分别用在哪？** 回本课【S 系列看壁厚】对照。","structure":"主链：认直管冷热水线→读温度边界→读 S 值与壁厚→分平口/铜牙/螺母→核法兰→对标准状态→避光存放。\n对照：PPR 绿白直管 vs PE 黑管蓝线直管；S2.5 vs S5；平口热熔件 vs 铜嵌件 vs 活接头。\n要点：1 长期≤70℃、瞬间≤95℃；2 S 越小壁厚越厚；3 平口热熔、铜牙转换；4 活接靠垫片可拆；5 非现用先隔离。\n引导：本课已说清 PPR 管与管件验收基础；现场常卡在冷水管当热水管；下一步 C62 讲直缝焊接钢管与钢制管件验收。\n查全表：S 数字越小壁越厚；母管与管件 S 系列要分别对。\n记红线：S 系列别和 PE 的 SDR 混算，逐档数值以现行标准核定为准。","anchors":[{"name":"PPR给水管","ref":"PPR给水管"},{"name":"PPR法兰（法兰转换）","ref":"PPR法兰（法兰转换）"},{"name":"PPR活接头（内丝/外丝直接）","ref":"PPR活接头（内丝/外丝直接）"},{"name":"PPR三通","ref":"PPR三通"},{"name":"PPR弯头","ref":"PPR弯头"}],"pitfall":"【S 越小壁厚越厚】冷水管不能当热水管；活接漏水先查垫片；PPR 怕晒。","remark":"D2 基础分论，能力达标由后续安装类课程承接；PPR法兰采集包现用栏为空，建议企业确认后作现用锚点；企业填：冷热水用途按设计核对","seq":38,"family":"CL-01 材料验收入库与标准核对","lessonNo":3},{"id":"C96","sub":"GW-01","topic":"地面巡检：管材类缺陷与环境隐患识别","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课讲地面巡检的全场景实操方法，针对四类现用管材讲解对应缺陷的地面征兆、环境异常识别与误判规避，解决“走在路上能看出什么隐患”的核心问题，是地面巡检的核心实操课。","framework":"PE管地面隐患识别｜地面沉降、管身裸露、第三方施工破坏、植被异常枯黄渗漏征兆。\n球墨铸铁管地面征兆｜路面渗水、井盖周边返潮、异味溢出、地面沉降不均接口渗漏特征。\n钢管腐蚀与损伤表现｜外露管段锈蚀、防腐层破损、穿跨越段变形识别要点。\n螺旋焊缝管巡检重点｜焊缝腐蚀、管身沉降、接口错位地面识别方法。\n井室与井盖缺陷｜井盖破损沉降缺失、井圈开裂、井室塌陷、标识不清判定标准。\n巡检记录规范｜缺陷位置描述、表观状态记录、现场拍照取证标准要求。\n常见漏判误区｜正常沉降当渗漏、冷凝水当漏点、忽略微小裂缝高频误判情形。","lecture":"**相邻关系：向上接 C95《管网日常巡检工作全景与缺陷大》；向下接 C97《井内巡检》。**\n\n**现场情境：路面一片潮湿，有人立刻判定管道漏水；旁边井盖还缺了。** 潮湿一定是漏吗？井盖缺失怎么处置？本课讲地面巡检。\n\n【PE管地面隐患识别：四类征兆要留心】\nPE管柔韧性好但怕尖锐物和沉降，地面巡检看四点。第一看地面沉降，管线正上方出现不均匀沉降、路面开裂，大概率是管身沉降拉扯接口；\n第二看管身裸露，施工开挖段露出的PE管，要看有没有划痕、砸伤、变形，防晒层有没有破损；第三看第三方施工，工地机械作业段要重点盯，挖掘机、打桩机极易挖破管身；\n第四看植被异常，管线正上方植被莫名枯黄、长势比周边差，排除干旱后要警惕暗漏，土壤长期泡水会让植物烂根。\n【球墨铸铁管地面征兆：接口渗漏是高发】\n球墨铸铁管最容易出问题的是承插接口，地面有明显信号。第一看路面渗水，晴天路面长期潮湿、清水渗出，顺着水流方向找源头，大概率是接口胶圈老化渗漏；\n第二看井盖周边返潮，阀门井、检查井周边一圈常年湿乎乎，井壁有流水痕迹，多是井内接口渗漏；第三闻异味，清水漏久了会发腥，污水倒灌会发臭，气味能辅助判断渗漏性质；\n第四看地面沉降不均，管线正上方路面凹陷、井体倾斜，多是地基沉降拉脱接口。\n【钢管腐蚀与损伤表现：外露段是窗口】\n钢管怕腐蚀，外露管段是巡检的观察窗口。第一看锈蚀程度，外露钢管表面防腐层鼓包、开裂、脱落，露出锈迹，说明防腐失效，埋地段也大概率同步腐蚀；\n第二看点蚀坑，表面出现分散的凹坑、锈包，是点蚀表现，继续发展会穿孔；第三看穿跨越段，过河、过路的架空钢管，要看支架有没有变形、管身有没有被车辆剐蹭、焊缝有没有开裂。\n【螺旋焊缝管巡检重点：焊缝是薄弱点】\n大口径螺旋焊缝管，缺陷多集中在焊缝。第一看焊缝腐蚀，焊缝位置比管身更容易锈，出现条状锈带、焊缝开裂鼓包要重点标记；\n第二看管身沉降，大口径管自重高，地基沉降不均会让接口错位，地面表现为管线走向的路面线性凹陷；第三看接口错位，法兰接口处地面有渗水、螺栓锈蚀严重，要警惕接口松脱。\n【井室与井盖缺陷：结构安全是红线】\n井盖井室不仅是标识，更是安全屏障。井盖破损、缺角、碾压碎裂要立刻上报；井盖沉降低于路面、凸起绊人，都属于隐患；井圈开裂、井壁坍塌、井内积泥严重，要记录等级；井盖表面“给水”“消防”字样模糊不清，抢修时容易找错井，也要纳入缺陷。\n【巡检记录规范：三样要素不能少】\n记录不是写“有漏水”就行，要写全三要素。位置描述要写清道路名称、桩号、参照物，比如“XX路XX号路灯北侧2米给水井”；\n状态描述要写清缺陷类型、严重程度，比如“井盖西北角碎裂，缺损面积约1/4”；拍照要拍全景、近景、参照物各一张，能看清缺陷位置和程度，方便后续复核。\n【常见漏判误区：三类情况最易误判】\n新手最容易踩三个坑。一是把正常地面沉降当管道渗漏，新建路面自然沉降也会开裂，要看是不是沿管线走向、有没有渗水配合；\n二是把井内冷凝水当管道漏水，夏季温差大井壁会结露积水，要看水是清水还是浑水、有没有持续增加；三是忽略微小裂缝，路面发丝裂缝看着小，下面可能已经是大隐患，尤其老旧管段要格外留心。\n\n**自测：路面潮湿是不是就等于管道漏水？** 回本课【PE管地面隐患识别：四类征兆要留心】对照。\n\n**自测：发现井盖缺失第一步该做什么？** 回本课【井室与井盖缺陷：结构安全是红线】对照。","structure":"主链：沿管线走→分管材看征兆→查井盖井室→做记录取证→规避误判误区。\n要点：1 PE管看沉降、裸露、施工、植被异常；2 球铁管重点盯接口渗漏的地面信号；3 钢管看外露段防腐与点蚀；4 螺旋管焊缝是薄弱点；5 井盖井室结构缺陷不能漏；6 记录要写清位置、状态、配照片；7 分清自然沉降、冷凝水与真渗漏。\n引导：本课覆盖地面巡检全场景；现场常卡在把冷凝水当漏水；下一步C97讲井内阀件缺陷识别。","anchors":[{"name":"PE给水管","ref":"PE给水管"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"直缝焊接钢管","ref":"直缝焊接钢管"},{"name":"螺旋缝焊接钢管","ref":"螺旋缝焊接钢管"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"复合井盖（给水/消防）","ref":"复合井盖（给水/消防）"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"}],"pitfall":"【路面潮湿不等于管道漏水】要区分冷凝水、地下水返潮与真渗漏；微小裂缝不能忽略；井盖缺失先围挡再上报，不能只拍照走人。","remark":"—","seq":39,"family":"GW-01 日常巡检与材料缺陷识别","lessonNo":2},{"id":"C97","sub":"GW-01","topic":"井内巡检：阀门管件与仪表缺陷识别","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课直击井内巡检核心场景，覆盖全品类现用阀件、管件、仪表的外观缺陷识别，配套井下安全防护要点，解决“开盖后能看出什么问题”的实操问题，是巡检员日常最高频的作业内容。","framework":"闸阀蝶阀常见缺陷｜阀体锈蚀、阀杆卡涩、密封面渗漏、手轮损坏识别。\n止回阀排气阀失效表现｜旋启式止回阀关闭不严异响、复合式排气阀漏水不排气、浮球卡滞特征。\n管件接口渗漏类型｜承插接口胶圈老化渗漏、法兰垫片渗漏、沟槽接口渗水区分。\n柔性接头与密封件老化｜可曲挠橡胶接头开裂、密封件变形失效判定。\n水表与流量计缺陷｜表盘模糊、表体渗漏、接头锈蚀、显示异常识别要点。\n井内环境异常判断｜井内积水积泥、异味、杂物堆积次生隐患排查。\n螺栓与紧固件检查｜螺栓锈蚀缺失松动快速识别。\n井下巡检安全要点｜开盖通风、先看后下、有毒有害气体预判、应急处置原则。","lecture":"**相邻关系：向上接 C96《地面巡检》；向下接 C100《管网核心功能节点专项巡检》。**\n\n**现场情境：井内有积水，工人判定管道漏了要下去查；橡胶件发黏也没当回事。** 判断对吗？本课讲井内巡检。\n\n【闸阀蝶阀常见缺陷：一眼能看出的问题】\n闸阀蝶阀是井内最多的设备，缺陷集中在四处。第一看阀体锈蚀，表面大面积掉漆、浮锈层增厚、出现锈坑，说明防腐失效；第二看阀杆卡涩，阀杆生锈、积满泥垢，转动不灵活甚至转不动，长期不操作会彻底咬死；\n第三看密封面渗漏，阀杆根部滴水、法兰接口沿边渗水，多是密封老化；第四看手轮损坏，手轮断裂、缺齿、手柄丢失，会影响应急启闭。暗杆闸阀还要看阀盖密封处有没有渗水，明杆闸阀要看阀杆升降是否顺畅。\n【止回阀排气阀失效表现：听声音看漏水】\n止回阀和排气阀藏在井内，失效有明显信号。旋启式止回阀（金属瓣/橡胶瓣）关闭不严，管网压力波动时会有“咚咚”的水锤撞击声，井内能听到明显异响；阀瓣卡滞全开的话，停水时会有持续回水。\n复合式排气阀失效分两种：漏水不止是浮球卡滞封不住，完全不排气是排气孔堵死，前者井内积水、后者管内积气。巡检时开盖先听声音、再看有没有积水，基本能判断状态。\n【管件接口渗漏类型：三种渗漏各有特征】\n井内接口渗漏分三类，成因完全不同。承插接口渗漏多是胶圈（球墨管承插密封圈）老化，水从承口边缘均匀渗出，水量不大但持续不停，伴随胶圈（球墨管承插密封圈）龟裂、失去弹性；\n法兰接口渗漏多是垫片失效，水从法兰缝里滴漏，螺栓孔周边有水迹，往往是垫片老化或螺栓松动；沟槽接口渗漏多是卡箍松了，水从卡箍下方渗出，紧螺栓大多能缓解。\n【柔性接头与密封件老化：橡胶件是短板】\n可曲挠橡胶接头这类柔性件，老化是通病。第一看表面裂纹，橡胶球体表面出现龟裂、发黏、变硬，都是自然老化表现；第二看变形鼓包，球体局部鼓胀、偏斜，是内部帘布层受损，继续用会撕裂；\n第三看渗漏，法兰边缘渗水、球体表面有针孔漏水，说明密封失效。橡胶件正常寿命5-8年，超期服役的要重点标记。\n【水表与流量计缺陷：计量设备要细心】\n水表流量计是精密设备，缺陷要细看。表盘模糊、玻璃起雾、字轮看不清，会影响抄读；表体接头处渗水、表壳有裂纹，属于密封失效；接头螺栓锈蚀严重、表体倾斜，是安装松动；\n智能表显示屏缺划、无显示，要排查电池和通信模块。旋翼式水表还要看铅封是否完好，铅封断了要上报计量部门。\n【井内环境异常判断：环境反映设备状态】\n井内环境本身就是隐患信号。井内积水超过井底5公分，要排查是接口渗漏、地下水倒灌还是雨水灌入；积泥、杂物堆积会淹埋阀门和接口，既看不见缺陷，又会加速腐蚀；\n有臭鸡蛋味、刺鼻味，要警惕有毒有害气体，立刻后撤不能下；井壁爬梯锈蚀断裂，属于登高风险，不能踩。\n【螺栓与紧固件检查：小件影响大安全】\n螺栓看着小，出问题就是大隐患。螺栓锈蚀严重、螺帽拧不动，说明长期没维护；螺栓缺失、少螺帽，法兰压力大了会呲开；螺栓松动、用手能晃，是渗漏的常见原因。还要区分半丝全丝，法兰对接必须用半丝螺栓，全丝替代的要记录异常。\n【井下巡检安全要点：先保安全再查隐患】\n下井前先守三条底线。开盖通风至少3分钟，站在上风侧，先闻味、再观察水面，不贸然探头；目测能看清的就不下去，必须下的严格执行有限空间作业流程，检测、监护、作业票齐全；\n发现头晕、恶心、异味立刻撤离，不硬撑；井下作业全程井上有人监护，不单人下井。\n\n**自测：井内有水一定是管道漏水吗？** 回本课【管件接口渗漏类型：三种渗漏各有特征】对照。\n\n**自测：橡胶密封件发黏龟裂说明什么？** 回本课【柔性接头与密封件老化：橡胶件是短板】对照。","structure":"主链：开盖通风→查阀门→查接口→查柔性件→查仪表→查环境→查紧固件→守安全底线。\n要点：1 闸阀蝶阀看锈蚀、卡涩、渗漏、手轮；2 止回阀听异响、排气阀看漏水；3 承插、法兰、沟槽三类渗漏各有特征；4 橡胶接头看裂纹、鼓包、渗漏；5 水表看表盘、密封、铅封、显示；6 井内积水积泥异味都是隐患；7 螺栓锈蚀缺失松动不能忽视；8 井下先通风、不盲目下井。\n引导：本课覆盖井内全品类设施巡检；现场常卡在只看漏水不查螺栓；下一步C100讲核心功能节点专项巡检。","anchors":[{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"中线（软密封）蝶阀","ref":"中线（软密封）蝶阀"},{"name":"旋启式止回阀（金属瓣/橡胶瓣）","ref":"旋启式止回阀（金属瓣/橡胶瓣）"},{"name":"复合式排气阀","ref":"复合式排气阀"},{"name":"可曲挠式橡胶接头","ref":"可曲挠式橡胶接头"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"旋翼式机械水表（湿式/干式/液封）","ref":"旋翼式机械水表（湿式/干式/液封）"},{"name":"电磁流量计","ref":"电磁流量计"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"}],"pitfall":"【井内有水不一定是管道漏】可能是雨水灌入、地下水倒灌；橡胶件发黏龟裂就是老化，不用等漏水才算缺陷；没做气体检测绝对不能下井。","remark":"—","seq":40,"family":"GW-01 日常巡检与材料缺陷识别","lessonNo":3},{"id":"C100","sub":"GW-01","topic":"管网核心功能节点专项巡检","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课针对消火栓、减压阀组、倒流防止器、排气阀、计量表组五大核心功能节点，讲解专属巡检要点与检查标准，对应巡检必查点位，细化每类设施的专项检查维度，直接匹配一线巡检作业清单。","framework":"消火栓巡检｜地上地下消火栓闷盖完整性、接口渗漏、启闭灵活性、防冻排水、标识清晰度检查。\n减压阀组巡检｜阀前阀后压力核对、导阀管路通畅性、阀体渗漏、压力表状态、过滤器堵塞排查。\n倒流防止器巡检｜阀体渗漏、前后压力差、泄水阀状态、滤网堵塞排查。\n排气阀巡检｜自动排气功能判断、阀体漏水、浮球卡滞、井室积水淹没风险检查。\n计量表组巡检｜水表表体渗漏、表盘清晰度、接头锈蚀、远传模块外观检查。\n配套辅件检查｜压力表、Y型过滤器、伸缩接头、连接螺栓同步巡检要点。\n专项节点记录规范｜四类节点缺陷描述标准、拍照取证要求。","lecture":"**相邻关系：向上接 C97《井内巡检》；向下接 C101《管道防腐层与阴极保护设施巡检》。**\n\n**现场情境：倒流防止器泄水口泡在脏水里，减压阀出口压力不稳就想直接换阀。** 问题找对了吗？本课讲功能节点巡检。\n\n【消火栓巡检：消防供水的第一道关】\n消火栓分地上地下，巡检要点各有侧重。地上式看栓体油漆有没有脱落、闷盖全不全、接口有没有渗漏、启闭杆能不能正常转动，冬天要检查排水阀有没有冻堵，确保排空防冻；\n地下式要开盖检查栓体、接口、启闭机构，看有没有积水浸泡、锈蚀卡死，井盖标识要清晰，确保抢修时能快速找到。两种消火栓都要检查铅封、标识，确保非消防使用能被及时发现。\n【减压阀组巡检：压力稳定靠它保】\n减压阀组是调压核心，巡检要查五处。第一核对阀前阀后压力，看压力表读数是否在设计范围内，压力超范围说明调压失效；第二查导阀管路，导阀毛细管有没有堵塞、弯折，导阀堵了减压阀就失灵；\n第三查阀体渗漏，阀盖、法兰接口有没有渗水；第四看压力表状态，表针卡滞、表盘模糊、接头漏水都要记录；第五查前置过滤器，Y型过滤器堵了会导致阀后压力不足，要记录排污周期。\n【倒流防止器巡检：饮水安全的边界】\n倒流防止器是防污染红线设备，巡检不能走过场。第一查阀体渗漏，各法兰接口、阀腔有没有滴水；第二查前后压差，进出口压力差明显异常，可能是阀芯卡滞或滤网堵塞；\n第三查泄水阀，正常工况下泄水阀不滴水，持续滴水说明止回阀密封失效；第四查前端过滤器，滤网堵塞会影响通流能力，要同步记录。重点看泄水口有没有被污水淹没，泡在脏水里会直接导致防污染失效。\n【排气阀巡检：管网呼吸的通道】\n排气阀看着小，作用极大。巡检看三点：第一看排气功能，管网充水或压力波动时，阀顶排气孔能正常排气、不持续喷水，说明浮球工作正常；第二查阀体漏水，阀盖、接口持续滴水，是密封垫老化或浮球卡滞；\n第三查井室积水，排气阀被积水淹没就完全失效，井内积水高过排气口的要立刻记录。复合式排气阀还要看负压进气功能是否正常，防止管道被吸瘪。\n【计量表组巡检：数据准确的基础】\n计量表组巡检要细致。水表外观看表壳有没有渗漏、表盘清不清晰、玻璃有没有破裂；接头看法兰或螺纹接口有没有渗水、螺栓锈蚀程度；远传模块看外观有没有破损、天线有没有脱落，显示屏读数是否正常。\n表组周边不能有杂物堆积，不能被积水浸泡，否则会影响计量精度和使用寿命。\n【配套辅件检查：小件决定功能】\n核心节点的辅件也要同步查。压力表看读数、看铅封、看接头渗漏；Y型过滤器看有没有堵塞、阀体有没有渗漏、排污口是否完好；伸缩接头看有没有变形、渗漏、螺栓松动；连接螺栓看锈蚀程度、有没有缺失松动。\n这些小件任何一个出问题，都会影响整个节点的功能。\n【专项节点记录规范：描述要精准】\n专项节点的缺陷记录要精准到部件。不能只写“消火栓坏了”，要写“地上式消火栓北侧闷盖缺失，接口渗漏”；不能只写“减压阀有问题”，要写“减压阀后压力超设计值0.1MPa，导阀管路弯折”。\n拍照要拍全景、铭牌、缺陷特写三张，确保能看清设备编号和缺陷程度。\n\n**自测：泄水口泡在污水里意味着什么？** 回本课【倒流防止器巡检：饮水安全的边界】对照。\n\n**自测：减压阀压力不稳，第一步该查什么？** 回本课【减压阀组巡检：压力稳定靠它保】对照。","structure":"主链：消火栓→减压阀组→倒流防止器→排气阀→计量表组→配套辅件→规范记录。\n要点：1 消火栓查启闭、渗漏、防冻、标识；2 减压阀查压力、导阀、过滤器；3 倒流防止器查压差、泄水阀、防淹没；4 排气阀查排气、漏水、积水；5 计量表组查外观、密封、远传模块；6 配套辅件同步检查；7 缺陷描述精准到部件。\n引导：本课覆盖五大核心功能节点；现场常卡在只查主阀不查辅件；下一步C101讲防腐与阴极保护巡检。","anchors":[{"name":"地上式消火栓","ref":"地上式消火栓"},{"name":"地下式消火栓","ref":"地下式消火栓"},{"name":"先导式减压阀","ref":"先导式减压阀"},{"name":"减压型倒流防止器","ref":"减压型倒流防止器"},{"name":"复合式排气阀","ref":"复合式排气阀"},{"name":"旋翼式机械水表（湿式/干式/液封）","ref":"旋翼式机械水表（湿式/干式/液封）"},{"name":"NB-IoT智能水表","ref":"NB-IoT智能水表"},{"name":"法兰Y型过滤器","ref":"法兰Y型过滤器"},{"name":"压力表","ref":"压力表"},{"name":"可曲挠式橡胶接头","ref":"可曲挠式橡胶接头"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"}],"pitfall":"【泄水口泡污水等于防污染失效】倒流防止器泄水口不能被积水淹没；消火栓冬天要查防冻排水；减压阀故障不能只换阀，先查过滤器堵没堵。","remark":"—","seq":41,"family":"GW-01 日常巡检与材料缺陷识别","lessonNo":4},{"id":"C101","sub":"GW-01","topic":"管道防腐层与阴极保护设施巡检","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课针对钢管、球铁管的防腐巡检与阴极保护设施检查，讲解各类防腐缺陷的外观识别、牺牲阳极巡检要点与成因区分，覆盖老旧管网防腐管控的实际需求，对应管线寿命管理的核心环节。","framework":"钢管防腐层缺陷识别｜外露钢管防腐层鼓包、开裂、脱落、点蚀分级判断。\n球墨铸铁管防腐检查｜锌层破损、沥青层脱落、承插口防腐失效外观识别。\n法兰与管件防腐检查｜法兰面、焊缝、弯头防腐薄弱点巡检要点。\n牺牲阳极巡检｜镁合金牺牲阳极埋设点标识、测试桩状态、接线完整性、外观检查要点。\n防腐缺陷成因区分｜土壤腐蚀、第三方施工破坏、电化学腐蚀、自然老化特征差异。\n防腐状态记录规范｜锈蚀面积、锈蚀深度、缺陷位置描述与拍照标准。\n缺陷上报边界｜一般锈蚀、较重腐蚀、穿孔风险分级上报阈值。","lecture":"**相邻关系：向上接 C100《管网核心功能节点专项巡检》；向下接 C98《缺陷分级与易混淆情形辨析》。**\n\n**现场情境：钢管表面有浮锈，有人就要判防腐失效；标识桩丢了就说阳极报废。** 对吗？本课讲防腐与阴极保护巡检。\n\n【钢管防腐层缺陷识别：四级程度要分清】\n钢管防腐层是它的保命衣，缺陷分四级。鼓包是防腐层鼓起、底层脱粘，还没露铁，属于早期缺陷；开裂是防腐层出现线性裂纹，雨水会顺着往里渗；脱落是防腐层整块掉落，露出钢管基体，必须重点标记；\n点蚀是露铁部位出现凹坑、锈包，说明已经开始基体腐蚀。巡检时按面积和深度分级，单片脱落面积超手掌大、出现深锈坑都属于较重缺陷。\n【球墨铸铁管防腐检查：外防腐是第一道防线】\n球墨铸铁管外防腐是锌层加沥青终饰，巡检看三处。第一看锌层破损，管身外露部分出现连片锈迹，没有沥青层覆盖，说明锌层消耗殆尽；\n第二看沥青层脱落，表面沥青层整块掉落、露出锌层或铁基体，防腐能力大幅下降；第三看承插口防腐，承插口端部防腐最容易磕碰脱落，是腐蚀高发位置，要重点检查接口周边的防腐完整性。\n【法兰与管件防腐检查：边角是薄弱区】\n焊缝、法兰、弯头这些异形部位，是防腐最薄弱的地方。法兰面螺栓孔周边、密封面外侧，最容易锈，因为施工时容易碰掉防腐层；环形焊缝、弯头背部，防腐施工难涂均匀，经常出现薄涂、漏涂；\n焊接三通的焊趾位置，应力集中加防腐薄弱，最容易出现腐蚀开裂。巡检时这些边角位置要多看一眼，不能只看管身平整处。\n【牺牲阳极巡检：阴极保护的晴雨表】\n镁合金牺牲阳极是埋地钢管的保护设施，地面巡检看四点。第一看埋设点标识，测试桩、标识桩有没有倾斜、破损、丢失，标识不清就找不到阳极位置；\n第二查测试桩状态，接线端子有没有锈蚀、松动，桩体有没有被碾压损坏；第三查接线完整性，外露的连接电缆有没有断裂、老化、被剪断；\n第四看周边环境，埋设点上方有没有施工开挖、堆土、积水，这些都会影响阳极工作效率。\n【防腐缺陷成因区分：四种原因各有特征】\n同样是锈蚀，成因不同处理方式不一样。自然老化是均匀锈蚀、面积大、发展慢，是服役时间长了的正常损耗；第三方施工破坏是局部大块脱落、有明显的机械磕碰痕迹，边界清晰；\n土壤腐蚀是埋地段低洼、潮湿位置先锈，地面对应位置常有沉降返潮；电化学腐蚀是杂散电流影响，局部点蚀严重、发展快，多在地铁、高压线附近。分清成因，上报时才能给处置提供准确依据。\n【防腐状态记录规范：量化描述不模糊】\n防腐缺陷记录要量化。不能只写“管子锈了”，要写“外露钢管北侧防腐层脱落，面积约30×20cm，基体出现点蚀，最大锈坑深度约1mm”；\n不能只写“阳极坏了”，要写“XX号测试桩倾斜，接线端子锈蚀，标识牌丢失”。拍照要拍全景、缺陷特写、带标尺参照，能直观看出锈蚀面积和深度。\n【缺陷上报边界：三级阈值要记清】\n防腐缺陷分三级上报。一般锈蚀是防腐层轻微变色、局部浮锈，面积小，可观察跟踪；较重腐蚀是防腐层成片脱落、基体明显锈蚀，出现分散点蚀，需要登记上报安排修复；\n重大腐蚀是出现连片深坑、接近穿孔，或者焊缝位置腐蚀开裂，有爆管风险，要立刻升级上报。分级按企业腐蚀管控标准执行，不凭感觉判定。\n\n**自测：表面浮锈能不能直接判定防腐完全失效？** 回本课【钢管防腐层缺陷识别：四级程度要分清】对照。\n\n**自测：牺牲阳极标识桩丢失说明阳极失效吗？** 回本课【牺牲阳极巡检：阴极保护的晴雨表】对照。","structure":"主链：钢管防腐→球铁管防腐→管件法兰防腐→牺牲阳极→成因区分→规范记录→分级上报。\n要点：1 钢管防腐分鼓包、开裂、脱落、点蚀四级；2 球铁管查锌层、沥青层、承插口；3 焊缝法兰弯头是防腐薄弱区；4 牺牲阳极查标识、测试桩、接线、环境；5 自然老化、施工破坏、土壤腐蚀、电化学腐蚀特征不同；6 记录要量化面积和深度；7 按三级阈值分级上报。\n引导：本课覆盖防腐与阴极保护巡检；现场常卡在只看管身不看边角；下一步C98讲缺陷分级与易混情形辨析。","anchors":[{"name":"直缝焊接钢管","ref":"直缝焊接钢管"},{"name":"螺旋缝焊接钢管","ref":"螺旋缝焊接钢管"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"钢焊接弯头","ref":"钢焊接弯头"},{"name":"钢法兰（平焊/对焊）","ref":"钢法兰（平焊/对焊）"},{"name":"镁合金牺牲阳极","ref":"镁合金牺牲阳极"}],"pitfall":"【浮锈不代表防腐完全失效】要区分表面浮锈与基体点蚀；焊缝法兰是防腐薄弱区，不能漏查；牺牲阳极标识桩丢失不代表阳极失效，要先核实。","remark":"—","seq":42,"family":"GW-01 日常巡检与材料缺陷识别","lessonNo":5},{"id":"C75","sub":"CL-02","topic":"塑料类管材管件仓储养护：PE/PPR 的避光与防压管控","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课讲塑料类管材管件（PE、PPR）在库养护的知识，属于 CL-02 子类的分品类课；承接 C74 的六大分类全景，与 C76 橡胶、C77 金属等分品类课并列，并为 C81 跨材质混放辨析提供判据。内容集中在紫外老化、堆码防压、划伤隐患、热膨胀、存放周期与失效识别。","framework":"1. 材质特性分级｜PE100/PE80 与 PPR 的分子结构差异与老化敏感点\n2. 紫外线老化机理｜分子链断裂过程、失效表现与环境影响因素\n3. 堆码防护规范｜直管堆放高度、防弯要求、底层衬垫标准\n4. 物理损伤防控｜尖锐物隔离、拖拽划伤规避、沟槽清石要求\n5. 热膨胀与变形防控｜温度变化对管材的影响、存放防弯措施\n6. 存放周期管理｜在库质保期、超期复检要点、临时露天堆放时限\n7. 失效形态识别｜脆化开裂、永久变形、表面老化的判定方法","lecture":"**相邻关系：向上接 C74《库房材质分区与养护管理全景骨架》；向下接 C76《橡胶密封件仓储养护》。**\n\n**现场情境：PE 管露天堆放不遮阳，堆得老高，表面还有浅划伤。** 这些隐患看得见吗？本课讲避光防压。\n\n【材质特性分级】\nPE 与 PPR 同属聚烯烃塑料，但分子结构不同，养护侧重点有差异。\nPE 管柔韧性好，分为 PE100 与 PE80 两个等级，PE100 强度更高，PE80 柔韧性更优。\nPPR 管耐热性更好，材质偏硬，热膨胀系数大，多用于室内冷热水系统。\n二者共同的老化天敌是紫外线，阳光直射会加速分子链断裂。\n落回卡上：对照 PE 给水管、PPR 给水管的材质与温度限制字段。\n【紫外线老化机理】\n紫外线是塑料管材的头号杀手，会造成不可逆的性能衰减。\n阳光中的紫外线会打断塑料的高分子链，使管材表面先发脆、再开裂。\n长期露天暴晒会让管材冲击强度明显下降、变脆易裂，具体衰减幅度以检测为准。\n黑色 PE 管的炭黑只能延缓老化，不能完全免疫紫外线。\nPPR 管无色或浅色，抗紫外线能力更弱，露天老化速度明显快于 PE。\n【堆码防护规范】\n塑料管材堆码不当会造成永久变形，直接影响安装使用。\nPE 直管堆放高度不得超过 3 层，避免底层管被压变形失圆。\n直管堆放需设置多点支撑，间距不大于 1.5 米，两端悬空长度不超过 0.5 米。\n底层必须垫方木或软衬垫，禁止直接放在粗糙水泥地面拖拽。\n不同口径分开堆放，大口径在下、小口径在上，遵循重下轻上原则。\n【物理损伤防控】\n表面划伤是塑料管材的隐性隐患，会成为后期爆管的突破口。\n尖锐的钢管坡口、螺栓棱角、铁丝边角会在管身划出深痕。\n划痕越深，承压能力下降越明显（“超壁厚 10%”是经验判据，具体以检测为准）。\n划痕肉眼不易察觉，但通水后在水压持续作用下会发生慢速开裂。\n管材存放区周边必须清理尖锐杂物，禁止与金属管件混堆。\n【热膨胀与变形防控】\n塑料热膨胀系数远大于金属，温度变化会产生明显形变。\nPPR 管热膨胀系数约为钢管的 10 倍，温差大时会出现明显弯曲。\n直管存放避免单侧暴晒，防止受热不均造成弯曲变形。\n管材存放保持平直状态，禁止强行弯折或挤压。\n冬季低温下塑料韧性下降，搬运禁止抛摔，防止脆裂。\n【存放周期管理】\n塑料管材有明确的存放周期，超期必须复检才能使用。\n室内避光存放条件下，PE 管质保期一般为 2 年，PPR 管为 18 个月，具体以厂家质保单为准。\n露天临时堆放不得超过 1 个月，且必须用遮阳布完全覆盖。\n超期存放的管材，需复检壁厚、拉伸强度与冲击性能，合格后方可使用。\n先进先出是最基本的管理原则，优先发放入库时间早的物料。\n【失效形态识别】\n在库巡检可通过外观特征，快速判断管材老化程度。\n表面出现粉末状脱层、颜色发灰发暗，是初期老化表现。\n表面粉化、发灰、出现细裂纹，或弯折即脆断，说明老化已较严重；拿不准取样检测。\n管材出现明显裂纹、永久变形失圆，直接判定为不合格，禁止发放。\n内壁出现划痕、凹陷深度超标的，降级或报废处理。\n\n**自测：炭黑的 PE 管是不是就不怕晒？** 回本课【紫外线老化机理】对照。\n\n**自测：表面浅划伤为什么要当隐患？** 回本课【物理损伤防控】对照。","structure":"知识结构：材质差异→老化机理→堆码规范→损伤防护→热膨胀防控→周期管理→失效识别，构成塑料管材养护的完整知识链。\n学习要点：\n1. PE 与 PPR 都怕紫外线，必须避光存放\n2. 堆码限高、多点支撑，防止永久变形\n3. 表面划伤是隐性隐患，禁止与尖锐物混放\n4. 塑料热胀冷缩明显，避免单侧受热不均\n5. 存放有周期，超期必须复检合格才能用\n6. 巡检看外观：脱层、发脆、裂纹都是失效信号\n7. 严格执行先进先出，减少库存老化损耗","anchors":[{"name":"PE 给水管","ref":"PE给水管"},{"name":"PE 分水器","ref":"PE分水器"},{"name":"PPR 给水管","ref":"PPR给水管"},{"name":"PPR 三通","ref":"PPR三通"},{"name":"PPR 弯头","ref":"PPR弯头"}],"pitfall":"1. 黑 PE 管不是不怕晒，炭黑只能延缓老化，不能完全防晒\n2. 表面浅划伤肉眼难辨，却是后期爆管的隐形隐患\n3. 堆码超高一时省事，底层管压变形全部报废","remark":"—","seq":43,"family":"其他","lessonNo":2},{"id":"C76","sub":"CL-02","topic":"橡胶密封件仓储养护：胶圈胶垫的避光防油与老化管控","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课讲橡胶密封件（EPDM、NBR）在库养护的知识，属于 CL-02 子类的高风险分品类课；承接 C74 全景、与 C75 塑料类课并列，并为 C81 混放辨析提供材质判据。内容集中在介质适配、热光氧油老化、环境管控、存放姿态、保质期与失效识别。","framework":"1. 材质分类差异｜EPDM 与 NBR 的介质适配与存放特性\n2. 老化四要素｜热、光、氧、油污对橡胶的破坏机理\n3. 环境管控标准｜温湿度区间、避光避臭氧要求\n4. 存放姿态规范｜禁止拉伸、自然松弛、堆码禁忌\n5. 生命周期管理｜保质期界定、定期抽检、批次追溯\n6. 失效形态识别｜发黏龟裂、永久变形、弹性丧失判定\n7. 不同品类差异｜胶圈 / 胶垫 / 生料带 / 橡胶接头的养护区别","lecture":"**相邻关系：向上接 C75《塑料类管材管件仓储养护》；向下接 C77《黑色金属类仓储养护》。**\n\n**现场情境：胶圈沾了油擦一擦继续用，还有一批压变形的胶圈看着完好。** 能不能用？本课讲老化管控。\n\n【材质分类差异】\n常用橡胶密封件分两大材质，避光避热、远离臭氧的存放要求一致，但适用场景与耐油性不同。\n给水场景默认使用 EPDM（三元乙丙橡胶），耐水、耐温≤120℃。\n含油介质必须使用 NBR（丁腈橡胶），耐油但耐水性弱于 EPDM。\n二者对热、光都敏感，避光、避热、避臭氧的养护要求一致；但耐油性不同：EPDM 怕矿物油，沾油会溶胀发黏、永久失去密封能力，NBR 耐油，用于含油介质。\n落回卡上：对照胶圈、胶垫（法兰橡胶垫片）的材质字段，给水默认 EPDM。\n【老化四要素】\n橡胶老化有四大核心诱因，库房中需重点防控。\n高温会加速橡胶分子交联，使材质变硬、失去弹性。\n紫外线会切断分子链，造成表面龟裂、粉化脱落。\n氧气长期接触会引发氧化反应，高温下老化速度翻倍。\n矿物油污会让 EPDM 等不耐油橡胶溶胀发黏、永久丧失密封性能；NBR 耐油，不属此类风险。\n【环境管控标准】\n橡胶密封件存放有明确的环境参数要求。\n最佳存放温度 5-25℃，相对湿度 40%-60%。\n必须存放在避光、阴凉、干燥的库房，避免阳光直射。\n远离臭氧源（电机、焊机）、化工挥发物与油品。\n整箱存放原包装不得破损，散件需用防尘袋封装。\n【存放姿态规范】\n橡胶件存放姿态直接影响使用寿命，错误姿态会造成永久变形。\n禁止悬挂拉伸存放，必须保持自然松弛状态。\n禁止重物直接压在胶圈胶垫（法兰橡胶垫片）上，长期受压会失去回弹能力。\n胶圈应平整码放，禁止拧扭、折叠堆放，避免产生折痕裂纹。\n不同口径、不同材质分开存放，贴明标识防止错发。\n【生命周期管理】\n橡胶件有明确的保质期，超期必须报废不得使用。\n原包装密封存放条件下，EPDM 密封件保质期一般为 18 个月。\n每批次入库必须记录生产日期与入库时间，严格先进先出。\n临近保质期 3 个月的物料提前抽检，检测硬度与压缩回弹率。\n超期物料直接隔离报废，严禁心存侥幸发放使用。\n【失效形态识别】\n巡检时看外观与按压回弹，可快速判定橡胶件是否失效。\n表面发黏、变软，用手按压回弹慢，是初期老化表现。\n表面出现裂纹、龟裂、掉渣，说明老化严重，密封失效。\n拉伸后不能恢复原状、出现永久变形，直接判定报废。\n沾有油污的胶圈直接隔离，不得再用于给水系统。\n【不同品类差异】\n不同形态的橡胶件，养护侧重点略有不同。\n承插胶圈（球墨管承插密封圈）体积大，重点防挤压变形、防唇边缺口。\n法兰胶垫（法兰橡胶垫片）薄，重点防划伤、防油污沾染。\n生料带（聚四氟乙烯密封带）怕高温、怕拉伸，原包装存放避免日晒。\n可曲挠橡胶接头带金属法兰，重点防橡胶球体沾油、防法兰锈蚀。\n\n**自测：胶圈沾油擦擦后能不能继续用？** 回本课【老化四要素】对照。\n\n**自测：压变形的胶圈为什么失去密封能力？** 回本课【存放姿态规范】对照。","structure":"知识结构：材质分类→老化机理→环境标准→存放姿态→周期管理→失效识别→品类差异，覆盖橡胶密封件全生命周期养护。\n学习要点：\n1. 给水默认 EPDM，含油场景用 NBR，二者不能混用\n2. EPDM 怕热、怕光、怕油、怕压；NBR 耐油，但同样怕热、怕光、怕压\n3. 最佳温湿度 5-25℃、40%-60%，避光避臭氧\n4. 自然松弛存放，禁止拉伸、重压、折叠\n5. 保质期 18 个月，超期直接报废，绝不能凑合\n6. 看外观、摸回弹，快速识别失效件\n7. 不同品类养护重点不同，唇边、密封面是关键","anchors":[{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"生料带","ref":"生料带（聚四氟乙烯密封带）"},{"name":"可曲挠式橡胶接头","ref":"可曲挠式橡胶接头"},{"name":"沟槽卡箍（刚性 / 柔性）","ref":"沟槽卡箍（刚性/柔性）"}],"pitfall":"1. 胶圈沾了油擦擦不能用，分子已经溶胀，密封必漏\n2. 压变形的胶圈看着完好，实际已经失去回弹能力\n3. 橡胶件超期凑合用，管网渗漏返工成本是物料的几十倍","remark":"—","seq":44,"family":"其他","lessonNo":3},{"id":"C77","sub":"CL-02","topic":"黑色金属类仓储养护：球铁 / 钢管 / 碳钢件的防潮防锈","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课讲黑色金属在库防锈的知识，属于 CL-02 子类的分品类课；承接 C74 六大分类，与 C75 塑料、C76 橡胶并列，其锈蚀判据被 C81 混放辨析和 C83 雨季防潮直接引用。内容集中在电化学腐蚀、球铁与钢管防腐层保护、锈蚀分级、垫高堆码与防锈措施。","framework":"1. 腐蚀基本原理｜电化学腐蚀机理，潮湿 / 盐雾 / 酸碱的加速作用\n2. 球墨铸铁管养护｜防腐层保护、卸管搬运禁忌、承口防变形要求\n3. 钢管养护要点｜内外防腐层防护、端部坡口保护、堆码标准\n4. 碳钢小件养护｜法兰螺栓焊接件的防潮措施、存放垫高要求\n5. 锈蚀等级判定｜浮锈 / 中锈 / 重锈的分级标准与处置规则\n6. 堆码通用规范｜通风垫高、避酸碱、层间衬垫防划伤\n7. 常用防锈措施｜涂油、包装、气相防锈纸的适用场景","lecture":"**相邻关系：向上接 C76《橡胶密封件仓储养护》；向下接 C78《有色与复合件仓储养护》。**\n\n**现场情境：钢管直接扔地上拖拽，螺栓丝扣锈了还想硬拧。** 后果是什么？本课讲黑色金属防锈。\n\n【腐蚀基本原理】\n金属锈蚀本质是电化学腐蚀，水和氧气是必要条件。\n潮湿环境下，金属表面形成微原电池，铁原子失去电子变成铁锈。\n空气相对湿度超过 60% 时，锈蚀速度显著加快；湿度越高、持续越久锈蚀越快（具体速率以现场检测为准）。\n盐雾、酸碱粉尘、二氧化硫会大幅加速腐蚀过程。\n库房防潮是黑色金属养护的核心，控制湿度就能控制锈蚀。\n【球墨铸铁管养护】\n球墨铸铁管的养护核心是保护内外防腐层，防腐层破了管子就废了。\n外壁锌层 + 沥青终饰是主要防腐屏障，钢丝绳硬勒会直接划破防腐层。\n卸管必须用软吊带，轻吊轻放，禁止在地面拖拽。\n内壁水泥砂浆内衬怕磕碰，管口撞击会造成内衬脱落、开裂。\n存放时地面平整，承口方向一致，禁止承口受压变形。\n落回卡上：对照球墨铸铁管的内外防腐字段。\n【钢管养护要点】\n焊接钢管的养护核心是保护内外防腐层与端部坡口。\n外 3PE 防腐层怕尖锐物磕碰、怕高温烘烤，破损处会优先锈蚀。\n内防腐层怕杂物划伤，管口需加保护帽，防止异物进入管内。\n端部坡口是焊接工作面，锈蚀、磕碰变形会直接影响焊接质量。\n堆码时管径大的在下、小的在上，层间垫木方，防止滚动磕碰。\n落回卡上：对照直缝焊接钢管、螺旋缝焊接钢管的防腐字段。\n【碳钢小件养护】\n法兰、螺栓、焊接管件等小件，是锈蚀高发的重灾区。\n小件表面积小但边角多，容易积存潮气，锈蚀速度比管材更快。\n必须垫高存放，离地面至少 15 厘米；雨季等返潮严重时按 C83 的雨季升级措施提高到 30cm 以上，防止地面返潮锈蚀。\n原包装完好的保留原包装，散件涂抹防锈油或用防锈纸包裹。\n螺栓螺母成套存放，防止丝扣锈蚀后无法旋合。\n落回卡上：对照钢法兰（平焊/对焊）、六角头螺栓（半丝/全丝）、钢焊接弯头。\n【锈蚀等级判定】\n锈蚀分不同等级，不是所有锈都要报废，需按深度判定。\nA 级浮锈：表面浮锈、手擦可除，轻度锈蚀，处理后可正常使用。\nB 级中锈：出现明显锈坑、深度不超过壁厚 10%，降级使用。\nC 级重锈：防腐层大面积破损、基体锈蚀穿透，直接判定报废。\n螺纹件丝扣锈蚀、无法正常旋合，直接报废不得使用。\n【堆码通用规范】\n黑色金属堆码必须遵循防潮、防损、通风三原则。\n所有物料垫高存放，禁止直接接触地面，隔绝地面潮气。\n远离酸碱、化工物料，防止腐蚀气体加速锈蚀。\n层间用木方、橡胶垫隔开，防止金属间互相磕碰划伤。\n保持库区通风，阴雨天气关闭门窗，晴朗天气开窗排潮。\n【常用防锈措施】\n根据物料价值与存放周期，选择不同防锈手段。\n短期存放：保持干燥通风，垫高离地即可。\n中期存放：涂抹防锈油、包裹防锈纸，隔绝潮气。\n长期存放：气相防锈纸包装，配合干燥剂，可显著延长防锈周期，具体以包装与检测结果为准。\n已出现浮锈的物料，除锈后补涂防锈油，再存放。\n\n**自测：防腐层磨破对钢管意味着什么？** 回本课【钢管养护要点】对照。\n\n**自测：螺栓丝扣锈了能不能强行拧？** 回本课【锈蚀等级判定】对照。","structure":"知识结构：腐蚀原理→球铁养护→钢管养护→小件养护→锈蚀分级→堆码规范→防锈措施，覆盖全品类黑色金属仓储养护。\n学习要点：\n1. 锈蚀核心是电化学腐蚀，防潮是第一要务\n2. 球铁管、钢管的核心都是保护防腐层，破了就从里面锈\n3. 碳钢小件更易锈，必须垫高、包装、涂防锈油\n4. 锈蚀分三级，浮锈可处理，锈坑超深必须报废\n5. 堆码垫高、通风避酸碱，是通用防锈规则\n6. 轻吊轻放防磕碰，防腐层比管材本身更金贵\n7. 按周期选防锈方式，短期 / 中期 / 长期手段不同","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"直缝焊接钢管","ref":"直缝焊接钢管"},{"name":"螺旋缝焊接钢管","ref":"螺旋缝焊接钢管"},{"name":"钢法兰（平焊 / 对焊）","ref":"钢法兰（平焊/对焊）"},{"name":"六角头螺栓（半丝 / 全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"钢焊接弯头","ref":"钢焊接弯头"}],"pitfall":"1. 表面浮锈不影响使用，但防腐层破了必须处置\n2. 螺栓丝扣锈了别硬拧，强行拧会滑丝报废\n3. 钢管直接扔地上拖拽，防腐层磨破等于白做防腐","remark":"—","seq":45,"family":"其他","lessonNo":4},{"id":"C78","sub":"CL-02","topic":"有色与复合件仓储养护：铜件 / 不锈钢 / 衬塑的存放禁忌","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课讲有色金属与钢塑复合件（铜件、不锈钢、衬塑件）在库养护的知识，属于 CL-02 子类的分品类课；承接 C74 六大分类、并列于 C77 黑色金属课，其中电偶腐蚀与接触污染的判据被 C81 混放辨析直接调用。内容集中在钝化膜、氯离子点蚀、内衬保护、专用切割工具与失效识别。","framework":"1. 铜件养护要点｜氧化变色防护、丝扣防锈、搬运防磕碰\n2. 不锈钢养护规则｜钝化膜原理、碳钢接触腐蚀、氯离子风险\n3. 衬塑复合管养护｜内衬塑料保护禁忌、禁高温禁焊接火花\n4. 衬塑管件养护｜丝扣防腐、内衬翻边保护、搬运注意事项\n5. 切割与加工禁忌｜衬塑管专用工具、高温作业隔离要求\n6. 堆码存放要求｜层间衬垫、禁重物压、远离热源\n7. 失效形态识别｜铜绿、点蚀、衬层开裂、钢塑离层判定","lecture":"**相邻关系：向上接 C77《黑色金属类仓储养护》；向下接 C79《电子仪表类仓储养护》。**\n\n**现场情境：不锈钢和碳钢挨着放，衬塑管旁边还在烧电焊。** 看着没事真的没事吗？本课讲有色复合件禁忌。\n\n【铜件养护要点】\n黄铜件在潮湿环境中会氧化生铜绿，影响外观与密封性能。\n黄铜阀体、管件表面镀镍或钝化处理，磕碰会破坏保护层。\n丝扣部位易积存潮气，是锈蚀高发区，需保持干燥。\n存放时保持干燥，避免与酸碱、硫化物接触，防止加速氧化。\n轻拿轻放，禁止抛摔，防止丝扣变形、密封面磕碰。\n落回卡上：对照黄铜内螺纹浮动球阀、黄铜闸阀。\n【不锈钢养护规则】\n不锈钢不是绝对不生锈，接触碳钢或氯离子会发生局部腐蚀。\n不锈钢防锈靠表面极薄的钝化膜，膜破了就会生锈。\n与碳钢螺栓、钢管直接接触会形成电偶腐蚀：碳钢电位低、作阳极先被腐蚀，不锈钢作阴极本来受保护；但碳钢锈迹和铁离子会迁移、附着到不锈钢接触面，破坏局部钝化膜并形成缝隙污染锈蚀，所以看起来像“不锈钢接触点连片生锈”，仍须隔离存放。\n氯离子环境（盐雾、除冰盐）会造成点蚀，穿透速度极快。\n禁止用钢丝刷、碳钢工具打磨不锈钢表面，会破坏钝化膜。\n必须与碳钢物料隔离存放，接触部位垫纸板或塑料膜。\n落回卡上：对照不锈钢户表控制箱。\n【衬塑复合管养护】\n衬塑复合管的命门是内衬塑料层，高温与硬物会直接毁掉它。\n内衬 PE 或 PPR 层，高温会熔化、变形，造成钢塑离层。\n绝对禁止在衬塑管附近进行焊接、气割作业，火花会烧穿内衬。\n禁止用高速砂轮切割机切割，瞬时高温会让管口内衬碳化。\n搬运时轻吊轻放，管口冲击会造成内衬翻边、脱落。\n落回卡上：对照衬塑复合管的结构组成字段。\n【衬塑管件养护】\n衬塑管件重点保护丝扣与内衬翻边，这两处是渗漏高发点。\n丝扣部位镀锌层破损会生锈，影响连接密封性。\n管口内衬翻边是密封关键，磕碰破损会造成接口渗漏。\n堆放时管口朝上，禁止重物压在管口上，防止翻边变形。\n不同口径分开码放，小件在上、大件在下，避免挤压变形。\n【切割与加工禁忌】\n衬塑管现场加工有严格工具要求，错误工具会直接报废管材。\n切割必须用低速齿锯或专用割管机，严禁砂轮高速切割。\n切割后必须用专用铰刀清理管口毛刺与内衬翻边。\n严禁现场电焊、气割衬塑管，高温会造成内衬大面积脱落。\n套丝作业控制温度，避免高温损坏管口内衬层。\n【堆码存放要求】\n有色与复合件堆码核心是防磕碰、防高温、防接触腐蚀。\n层间垫软质衬垫，防止金属面互相划伤、磕碰。\n远离热源、焊接作业区，防止高温损坏塑料内衬。\n不锈钢与碳钢物理隔离，禁止直接接触、混堆混放。\n铜件与不锈钢可同区存放，但需避免与酸碱物料接触。\n【失效形态识别】\n通过外观检查可快速识别三类物料的常见失效。\n铜件表面出现绿色铜锈、丝扣锈蚀卡滞，属于失效状态。\n不锈钢表面出现连片锈斑、点蚀坑，说明钝化膜已破坏。\n衬塑管口内衬碳化、开裂、脱落、钢塑分离，直接报废。\n丝扣变形、内衬翻边破损的衬塑管件，禁止发放使用。\n\n**自测：不锈钢挨着碳钢为什么会生锈？** 回本课【不锈钢养护规则】对照。\n\n**自测：衬塑管旁烧电焊对内衬有什么影响？** 回本课【衬塑复合管养护】对照。","structure":"知识结构：铜件养护→不锈钢养护→衬塑管养护→衬塑管件养护→加工禁忌→堆码要求→失效识别，覆盖有色与复合全品类。\n学习要点：\n1. 黄铜怕潮怕酸碱，会生铜绿，丝扣是防锈重点\n2. 不锈钢不是永不生锈，接触碳钢、氯离子照样锈\n3. 衬塑管禁高温、禁焊接火花，内衬坏了管子就废了\n4. 衬塑管必须用专用工具切割，严禁砂轮片\n5. 不锈钢与碳钢必须隔离存放，禁止直接接触\n6. 衬塑管件重点保护管口翻边，磕碰破损必漏\n7. 轻拿轻放防磕碰，远离热源保内衬","anchors":[{"name":"黄铜内螺纹浮动球阀","ref":"黄铜内螺纹浮动球阀"},{"name":"黄铜闸阀","ref":"黄铜闸阀"},{"name":"不锈钢户表控制箱","ref":"不锈钢户表控制箱"},{"name":"衬塑复合管","ref":"衬塑复合管"},{"name":"衬塑丝接三通","ref":"衬塑丝接三通"},{"name":"衬塑丝接弯头","ref":"衬塑丝接弯头"}],"pitfall":"1. 不锈钢和碳钢放一起，碳钢先锈，锈迹迁移污染到的接触面才会跟着生锈\n2. 衬塑管旁烧电焊，看着没事，内衬早就碳化了\n3. 管口内衬翻边磕破一点，装上去就会从这里漏水","remark":"—","seq":46,"family":"其他","lessonNo":5},{"id":"C79","sub":"CL-02","topic":"电子仪表类仓储养护：水表 / 阀门 / 压力表的防潮防静电","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课讲电子仪表与精密阀门在库养护的知识，属于 CL-02 子类的高价值分品类课；承接 C74 六大分类，与 C75–C78 各品类课并列，其“仪表怕潮怕静电”的结论被 C81 混放辨析和 C83 雨季除湿引用。内容集中在失效机理、原包装防潮、搬运禁忌、电池管理与出库核验。","framework":"1. 失效核心机理｜受潮损坏元件、静电击穿芯片、机械冲击卡滞\n2. 存放环境要求｜原包装防潮存储、温湿度管控、静电防护标准\n3. 搬运作业禁忌｜摔碰冲击、重压堆叠、倒置存放的危害\n4. 电池款仪表管理｜存放温度要求、定期激活、保质期管理\n5. 精密部件保护｜弹簧管、叶轮、执行机构的防护要点\n6. 出库检定要求｜外观检查、功能测试、计量精度核验\n7. 失效初步判定｜显示失灵、计量偏差、机芯卡滞的识别","lecture":"**相邻关系：向上接 C78《有色与复合件仓储养护》；向下接 C80《综合辅材仓储养护》。**\n\n**现场情境：搬水表时随手摸了下电路板，仪表还轻轻摔了一下。** 看不见的损伤有多大？本课讲电子仪表养护。\n\n【失效核心机理】\n电子仪表损坏三大主因：受潮、静电、机械冲击，库房中均可防控。\n潮湿空气会造成电路板短路、元件锈蚀，导致仪表失灵。\n静电会击穿计量芯片、传感器，造成永久性损坏，肉眼不可见。\n摔碰冲击会让机械机芯错位、叶轮变形，直接影响计量精度。\n落回卡上：对照超声波水表、电磁流量计、压力表的结构字段。\n【存放环境要求】\n电子仪表必须在干燥、防静电的环境中原包装存放。\n保留原厂包装，内部泡沫缓冲与防潮干燥剂不得随意丢弃。\n存放环境温度 0-30℃，相对湿度控制在 60% 以下，阴雨天气严禁开箱。\n货架做好静电防护，禁止直接放在水泥地面上。\n远离强磁场、强电场区域，防止干扰仪表计量元件。\n【搬运作业禁忌】\n仪表类物料娇贵，搬运不当是造成隐形损坏的主要原因。\n轻拿轻放，严禁抛摔、磕碰，哪怕是轻微跌落也可能损坏机芯。\n堆叠高度不得超过包装箱标识上限，防止重压变形损坏内部元件。\n禁止倒置存放，防止内部液封、润滑油移位影响性能。\n搬运时用专用周转箱，禁止散装混放互相碰撞。\n【电池款仪表管理】\n带电池的智能仪表，存放不当会造成电池提前失效。\nNB-IoT 智能水表内置锂电池，高温会加速电池自放电，缩短寿命。\n存放环境温度控制在 0-30℃，避免阳光直射与高温区域。\n出库或安装前检查电池状态，存放超质保期的按厂家要求处理。\n超过存放质保期的仪表，出库前必须复检功能与电池容量。\n【精密部件保护】\n不同仪表有各自的精密核心部件，是防护重点。\n压力表的弹簧管是核心感应元件，变形后计量就不准了，禁止挤压表头。\n水表叶轮轴非常精密，磕碰变形会造成计量偏差，必须保护好表体。\n电动阀门的执行机构齿轮组精密，摔碰会造成卡滞、开关不到位。\n所有仪表的接口、密封面必须保护好，防止磕碰划伤影响密封。\n【出库检定要求】\n仪表出库前必须做基础核验，避免不合格品流入现场。\n外观检查：表壳无变形、接口无损伤、密封面完好。\n功能测试：通电 / 通水后显示正常、按键响应、无报错。\n计量精度：贸易结算类仪表需在检定有效期内。\n附件齐全：说明书、合格证、专用配件完整。\n【失效初步判定】\n出库前通过外观与简单测试，可初步排查仪表失效。\n显示屏花屏、无显示、按键无响应，是电路或电池故障。\n表壳变形、接口磕碰、密封面损伤，大概率内部已损坏。\n指针不归零、叶轮卡滞，说明机械部分已有损伤。\n外观完好但计量超差，需专业设备检定，禁止直接发放。\n\n**自测：手摸电子仪表为什么可能造成损坏？** 回本课【失效核心机理】对照。\n\n**自测：仪表摔一下外观没事就没事吗？** 回本课【搬运作业禁忌】对照。","structure":"知识结构：失效机理→环境要求→搬运禁忌→电池管理→部件保护→出库核验→失效判定，覆盖电子仪表全仓储周期养护。\n学习要点：\n1. 仪表三大杀手：受潮、静电、摔碰，全部可防控\n2. 原包装是最好的防护，干燥剂、缓冲棉不能丢\n3. 轻拿轻放禁重压，禁止倒置，保护精密机芯\n4. 电池款仪表控温存放，定期抽检电压\n5. 接口、密封面是重点，磕碰划伤直接影响使用\n6. 出库前必查外观、测功能，异常先复检再发放\n7. 静电击穿肉眼看不见，摸一下可能就废了一块表","anchors":[{"name":"超声波水表","ref":"超声波水表"},{"name":"NB-IoT 智能水表","ref":"NB-IoT智能水表"},{"name":"电磁流量计","ref":"电磁流量计"},{"name":"压力表","ref":"压力表"},{"name":"电动蝶阀","ref":"电动蝶阀"},{"name":"光电直读远传水表","ref":"光电直读远传水表"}],"pitfall":"1. 静电击穿芯片肉眼看不见，摸一下可能就废了一块表\n2. 仪表轻轻摔一下，外面没事，里面机芯早就歪了\n3. 电池款仪表放高温区，还没装上去电池就耗完了","remark":"—","seq":47,"family":"其他","lessonNo":6},{"id":"C80","sub":"CL-02","topic":"综合辅材仓储养护：防腐 / 抢修 / 井室辅材的分类存放","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课讲综合辅材（防腐、抢修、井室、紧固件）在库养护的知识，属于 CL-02 子类的补全课；与 C75–C79 五大品类课共同补齐 C74 的六大分类版图，并为 C81 混放辨析提供化工辅材与井室件的判据。内容集中在填包料防潮、AB 胶控温、井盖防碎裂、紧固件分级与固液分开存放。","framework":"1. 防腐辅材养护｜镁阳极存放要求、填包料防潮防结块管理\n2. 抢修辅材养护｜AB 胶双组分存放、保质期管控、温度影响\n3. 井室设施养护｜井盖堆码防碎裂、消火栓接口防护要求\n4. 紧固件养护｜螺栓等级区分、镀锌层保护、丝扣防锈\n5. 分类存放原则｜固液分开、化学品隔离、轻重物料分层\n6. 零散辅材管理｜标识规范、五五堆码、易损耗材库存预警\n7. 失效形态识别｜填包料结块、胶粘剂固化、井盖缺角判定","lecture":"**相邻关系：向上接 C79《电子仪表类仓储养护》；向下接 C81《跨材质混放风险辨析》。**\n\n**现场情境：填包料受潮结块还凑合用，AB 胶也快过期了。** 这些辅材还能用吗？本课讲综合辅材养护。\n\n【防腐辅材养护】\n镁合金牺牲阳极与填包料，核心是防潮、防结块、保活性。\n镁阳极本体怕潮，表面氧化会影响放电效率，需干燥存放。\n填包料由石膏粉、膨润土、硫酸钠组成，受潮结块会失去导电活性。\n填包料必须密封保存，禁止破损漏料，开封后尽快用完。\n阳极电缆接头保护好，防止锈蚀、弯折断裂，影响连接导通。\n落回卡上：对照镁合金牺牲阳极的结构组成字段。\n【抢修辅材养护】\nAB 胶类抢修辅材，核心是控温、控期、双组分配套存放。\n双组分环氧胶分 A、B 两管，必须成对存放，禁止单组分遗失。\n存放温度控制在 5-25℃，高温会加速固化反应，缩短保质期。\n严格按保质期管理，超期胶粘结强度大幅下降，堵漏失效。\n存放于阴凉干燥处，远离热源与阳光直射，防止提前固化。\n落回卡上：对照 AB 胶（管道修补剂）。\n【井室设施养护】\n井盖、消火栓等井室设施，核心是防碎裂、防变形、保护接口。\n球墨铸铁井盖强度高，但也禁止高空抛掷、重物砸击，防止断裂。\n复合井盖脆性大，严禁重摔、重压，超过承载极限会直接碎裂。\n消火栓栓体、接口保护好，防止磕碰变形，影响水带连接密封。\n消火栓密封圈保持完好，长期存放需定期检查，防止老化失效。\n落回卡上：对照球墨铸铁井盖、复合井盖、地上式消火栓。\n【紧固件养护】\n螺栓、螺母等紧固件，核心是保镀锌层、防锈蚀、保等级。\n热镀锌层是防锈屏障，磕碰脱落会加速锈蚀。\n按等级、规格分类存放，4.8 级与 8.8 级禁止混放。\n丝扣保护好，防止磕碰变形、锈蚀，影响旋合使用。\n垫高存放，远离潮湿地面，原包装存放最佳。\n【分类存放原则】\n综合辅材品类杂、属性多，必须按性质分类分区存放。\n固体物料与液体物料分开，防止液体渗漏污染其他物料。\n化学品、胶粘剂单独设区，与食品级、饮水接触物料严格隔离。\n重物放低层、轻物放高层，大件靠里、小件靠外，方便存取。\n易燃易爆物品按消防要求单独存放，配备消防器材。\n【零散辅材管理】\n小件、零散辅材重点做好标识与定量管理，防止混乱损耗。\n所有辅材贴明标识，写清名称、规格、批次、保质期。\n易损耗材采用五五堆码，方便盘点，快速判断数量。\n设定最低库存预警线，低于阈值及时补货，保障抢修供给。\n定期盘点，做到账物相符，及时清理过期、失效物料。\n【失效形态识别】\n三类辅材的失效特征明显，巡检时可快速识别。\n填包料受潮结块、镁阳极表面严重氧化发白，判定失效。\nAB 胶超出保质期、单组分提前固化、包装破损漏液，禁止使用。\n井盖出现裂纹、缺角、承载结构损坏，直接报废。\n螺栓镀锌层大面积脱落、丝扣锈蚀变形，降级或报废。\n\n**自测：受潮结块的填包料能不能用？** 回本课【防腐辅材养护】对照。\n\n**自测：超期的 AB 胶为什么不能用？** 回本课【抢修辅材养护】对照。","structure":"知识结构：防腐辅材→抢修辅材→井室设施→紧固件→分类原则→零散管理→失效识别，覆盖全品类综合辅材养护。\n学习要点：\n1. 镁阳极填包料怕潮，结块就失去活性，必须密封存放\n2. AB 胶成对存放、控温、按期用，超期粘结力不达标\n3. 复合井盖怕摔怕砸，超重压上去直接碎裂\n4. 紧固件分等级、保镀锌、防锈蚀，禁止混放\n5. 辅材杂也要分类，固液分开、化学品隔离、轻重分层\n6. 零散物料标识清、定量放，盘点补货都方便\n7. 抢修类物料必须保障完好，关键时刻不能掉链子","anchors":[{"name":"镁合金牺牲阳极","ref":"镁合金牺牲阳极"},{"name":"AB 胶（管道修补剂）","ref":"AB胶（管道修补剂）"},{"name":"球墨铸铁井盖（给水 / 消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"复合井盖（给水 / 消防）","ref":"复合井盖（给水/消防）"},{"name":"地上式消火栓","ref":"地上式消火栓"},{"name":"六角头螺栓（半丝 / 全丝）","ref":"六角头螺栓（半丝/全丝）"}],"pitfall":"1. 填包料受潮结块了还凑合用，阳极等于白装\n2. AB 胶超期看似能固化，实际粘结强度差，带压一冲就漏\n3. 复合井盖当铁井盖踩，超重压碎了就是路面塌陷隐患","remark":"—","seq":48,"family":"其他","lessonNo":7},{"id":"C85","sub":"CL-03","topic":"常规领料作业规范：单货核对、先进先出与台账登记","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课专讲常规领料的标准化作业，属于 CL-03 子类分场景核心课，内容包括领料凭证、单货核对、先进先出、台账登记、常见错误与异常处置。本课承接 C84 的全景框架，把其中日常领料场景展开为可操作的作业规范，并为 C86 抢修场景的定额发放打基础。","framework":"1. 领料凭证要求｜领料单核心要素、无效单据识别标准\n2. 单货核对要点｜名称、规格、型号、数量四项核对法\n3. 先进先出落地｜批次识别、库位排布、发料顺序执行规则\n4. 台账登记规范｜出入库核心字段、账实对应基本要求\n5. 常见发料错误｜错发规格、混发材质、批次混乱的现场后果\n6. 异常处置流程｜单据不符、物料短缺的标准处理方式","lecture":"**相邻关系：向上接 C84《领退料与抢修供给管理全景骨架》；向下接 C86《抢修场景定额物料管理与快速发放》。**\n\n**现场情境：领料单要素不全就发料，还只拿外面的新货不管旧料积压。** 错在哪？本课讲单货核对。\n\n【领料凭证要求】\n领料单是发料的唯一依据，要素不全的单据一律无效。\n有效单据必须包含：物料名称、规格型号、申领数量、用途、领料人签字、审批人签字。\n手写涂改、字迹模糊、缺少审批的单据，都属于无效单据，不得发料。\n工程领料还要对应项目编号，抢修领料要注明故障地点和抢修事由。\n落回卡上：日常领用最多的 PE 给水管、PPR 给水管，都要凭单发料。\n【单货核对要点】\n发料前必须逐项核对，做到单货完全一致才能出库。\n核名称：确认物料名称和单据一致，防止拿错品类。\n核规格：核对口径、压力等级、材质型号，比如 DN100 不能发成 DN80。\n核型号：同名称不同型号的物料不能混发，比如暗杆闸阀不能发明杆的。\n核数量：按单据数量点发，多发少发都会造成账实不符。\n【先进先出落地】\n先进先出是减少物料老化损耗的核心规则，必须落到实处。\n批次识别：看物料的生产日期、入库批次，优先发入库早的。\n库位排布：同一物料按批次前后摆放，旧批次放在外侧易取处、新批次放在里侧，保证先入库的先拿到。\n发料顺序：每次发料先拿最早入库的，不能图方便只拿外面的。\n如果图省事总拿新的，旧物料会一直积压，最后超期报废造成浪费。\n【台账登记规范】\n台账是库存的账面记录，每一笔出入库都要及时准确登记。\n必填字段：日期、单据号、物料名称规格、出入库数量、结存数量、经办人。\n登记及时：发料后立即登账，不能攒着一起记，容易漏记错记。\n账实对应：账面结存要和实际库存一致，定期盘点核对差异。\n台账不仅是记账，更是追溯物料去向、排查差错的核心依据。\n【常见发料错误】\n三类高频发料错误，后果一个比一个严重。\n错发规格：比如把 PN10 的法兰发成 PN16，装上去压力不够会渗漏崩脱。\n混发材质：比如 PE 管件和 PPR 管件混发，材质不兼容热熔接不上。\n批次混乱：新料先发旧料积压，最后橡胶、塑料类物料老化报废。\n这些错误看似小事，到了现场就会造成停工返工，甚至质量事故。\n【异常处置流程】\n遇到单据不符、物料短缺，按标准流程处置，不能私自变通。\n单据信息有误：退回领料人修正，重新审批后再来办理，不能口头改数。\n物料库存不足：告知领料人，同时启动补货，有替代件的按替代流程走。\n物料外观有瑕疵：先隔离待检，再按三级判定——完好未用的可复用、轻微瑕疵不影响核心性能的降级使用并单独标识、破损老化的走报废。\n所有异常都要登记备注，不能不了了之，留下管理漏洞。\n\n**自测：单据要素不全能不能发料？** 回本课【领料凭证要求】对照。\n\n**自测：图方便只拿新货会带来什么问题？** 回本课【先进先出落地】对照。","structure":"知识结构：凭证要求→单货核对→先进先出→台账登记→常见错误→异常处置，构成常规领料全流程标准化作业链。\n学习要点：\n1. 有效领料单必须六要素齐全，缺一项都不能发料\n2. 发料前四项核对：名称、规格、型号、数量，逐项确认\n3. 先进先出靠库位排布和发料顺序落地，不能只喊口号\n4. 台账及时准确登记，做到账实一致、全程可追溯\n5. 错发规格、混发材质、批次混乱是三大高频错误\n6. 异常按流程处置，不私自变通，全部登记留痕\n日常领料看着简单，真正容易出问题的是规格拿错、批次拿乱、单据缺项这些现场小麻烦；下一课 C86 讲抢修时同样的核对怎么在求快的场景下守住底线。","anchors":[{"name":"PE 给水管","ref":"PE给水管"},{"name":"PPR 给水管","ref":"PPR给水管"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"六角头螺栓（半丝 / 全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"生料带","ref":"生料带（聚四氟乙烯密封带）"},{"name":"旋翼式机械水表（湿式 / 干式 / 液封）","ref":"旋翼式机械水表（湿式/干式/液封）"}],"pitfall":"1. 单据要素不全就发料，出了问题仓管员担主责\n2. 图方便只拿外面的货，旧料积压超期就是浪费\n3. 规格差一个号，现场就装不上，核对必须逐项来","remark":"","seq":49,"family":"其他","lessonNo":2},{"id":"C86","sub":"CL-03","topic":"抢修场景定额物料管理与快速发放","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课专讲抢修场景的物料管理与发放，属于 CL-03 子类特色核心课，内容包括典型抢修场景定额、库位规划、快速拣配、定额发放、动态盘点与应急发料。本课承接 C85 的常规领料规范，把标准化作业逻辑应用到效率优先的抢修场景，并与 C89 的应急特批规则相衔接。","framework":"1. 典型抢修场景定额｜PE 管破损、球铁管破损、阀门更换三类标配物料清单\n2. 抢修物料库位规划｜集中分区存放、标识清晰、易拿易放的布局要求\n3. 快速拣配方法｜按单索骥、规格匹配、数量核验三步配齐法\n4. 定额发放规则｜常规抢修标配数量、超定额申领的审批要求\n5. 动态盘点机制｜日盘点、补库触发条件、库存预警标准\n6. 应急发料流程｜紧急抢修的凭证要求、事后补单时限与责任界定","lecture":"**相邻关系：向上接 C85《常规领料作业规范》；向下接 C87《退库物料判定与分类处置标准》。**\n\n**现场情境：抢修急，工人拿了个规格差一号的件就走，还说手续回头补。** 后果是什么？本课讲快速发放。\n\n【典型抢修场景定额】\n三类最常见的抢修场景，都有标准的物料定额，按单配齐不遗漏。\nPE 管破损抢修：标配哈夫节（堵漏器） 1 个、对应规格胶垫（法兰橡胶垫片） 1 片、配套螺栓 1 套、生料带（聚四氟乙烯密封带） 1 卷。\n球铁管破损抢修：标配哈夫节（堵漏器） 1 个、胶垫（法兰橡胶垫片） 1 片、六角头螺栓（半丝/全丝）全套、AB 胶备用。\n阀门更换抢修：标配对应阀门 1 台、法兰胶垫（法兰橡胶垫片） 2 片、螺栓全套、生料带（聚四氟乙烯密封带） 1 卷。\n定额是基础配置，现场情况复杂的可以按需追加，但要走审批。\n落回卡上：哈夫节（堵漏器）、胶垫（法兰橡胶垫片）、六角头螺栓（半丝/全丝）都是抢修高频物料，全部在现用库中。\n【抢修物料库位规划】\n抢修物料集中存放、标识清晰，才能拿得快、不拿错。\n1. 专区存放：所有抢修常用物料放在同一个库区，不用跑好几个货架找。\n2. 分类标识：每个品类挂明确标识牌，写清名称、规格、定额数量，一眼就能找到。\n3. 易拿易放：常用规格放在齐腰高度，不用弯腰垫脚，拿取最快。\n4. 轻重分层：重的物料放低层，轻的放高层，兼顾效率和安全。\n库位规划好了，抢修时找料更快、更不易拿错，真正保障效率。\n【快速拣配方法】\n三步拣配法，又快又准，避免忙中出错。\n第一步按单索骥：对照抢修场景定额清单，按顺序挨个取料，不漏项。\n第二步规格匹配：核对每一样物料的口径、压力等级，确保和抢修点匹配。\n第三步数量核验：点清每样的数量，对照定额不多拿也不少拿。\n熟练之后，常规抢修的物料就能按清单快速配齐，效率远高于零散找料。\n边拣边核对，比拿完再返工核对更快，也不容易出错。\n【定额发放规则】\n按定额发放是基础，超定额必须走审批，不能想要多少给多少。\n常规抢修按标配定额发放，满足基本抢修需求，不多发造成浪费。\n现场情况复杂、需要超定额领料的，必须有对应层级的审批签字。\n抢修现场多用了的物料，事后要补说明和审批，不能不了了之。\n定额不是限制，是避免浪费、规范管理的手段，同时保障基本需求。\n【动态盘点机制】\n抢修物料必须动态盘点，保证随时能用、随时够量。\n每日盘点：每天下班前盘点一次抢修常用物料，账实核对，消耗了及时补。\n补库触发：库存低于最低预警线时，立即发起补货申请，不能等用完了再补。\n库存预警：设定最低库存标准，具体预警数量以现场定额为准。\n抢修物料就是备战物资，平时管到位，关键时刻才不会掉链子。\n【应急发料流程】\n特别紧急的抢修，可以先发料后补单，但有严格的时限和责任要求。\n适用场景：深夜突发爆管、大面积停水等紧急情况，来不及走正常审批。\n操作要求：必须有现场负责人口头或电话确认，登记清楚领用人、事由、数量。\n补单时限：工作日内补齐手续。\n逾期不补的，追责领用人和仓管员，严禁以抢修为名无单领料。\n\n**自测：抢修再急为什么也要核对规格？** 回本课【快速拣配方法】对照。\n\n**自测：先领后补逾期不补算什么性质？** 回本课【应急发料流程】对照。","structure":"知识结构：场景定额→库位规划→快速拣配→定额发放→动态盘点→应急流程，形成 “平时管得好、急时拿得快” 的抢修物料管理体系。\n学习要点：\n1. 三类典型抢修有标准定额，按单配齐不遗漏\n2. 集中专区存放、标识清晰，找料快、不拿错\n3. 三步拣配法：按单取、核规格、点数量，又快又准\n4. 定额内直接发，超定额必须审批，不滥发浪费\n5. 每日动态盘点，低于预警线及时补货\n6. 应急可先发后补，但有严格时限和责任要求\n抢修最怕平时不备料、急时找不全，备料和发放的尺度全靠定额和盘点拿捏；下一课 C87 讲领出去的料退回来以后，怎么判定还能不能用。","anchors":[{"name":"哈夫节","ref":"哈夫节（堵漏器）"},{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"六角头螺栓（半丝 / 全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"AB 胶（管道修补剂）","ref":"AB胶（管道修补剂）"},{"name":"生料带","ref":"生料带（聚四氟乙烯密封带）"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"}],"pitfall":"1. 抢修再急也要核对规格，拿错了到现场更耽误时间\n2. 先领后补要在工作日内补齐手续，逾期不补就是违规无单领料\n3. 抢修物料不能平时随便用，不然真抢修时就没货了","remark":"","seq":50,"family":"其他","lessonNo":3},{"id":"C87","sub":"CL-03","topic":"退库物料判定与分类处置标准","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课专讲退库物料的判定与处置，属于 CL-03 子类闭环管理课，内容包括可复用、降级使用、报废三级判定标准、退库作业流程与常见管理误区。本课补上 C84 全景框架中的退库处置环节，与 C85、C86 的领料发放前后衔接，共同构成领—发—退的完整闭环。","framework":"1. 退料三级分类｜可复用、降级使用、报废三类判定维度\n2. 可复用判定标准｜包装完好、未使用、在质保期内的核验要点\n3. 降级使用判定｜外观轻微瑕疵、不影响核心性能的适用场景\n4. 报废判定标准｜破损、老化、超期、性能不达标的判定红线\n5. 退库作业流程｜核验→判定→登记→归位的全流程步骤\n6. 常见管理误区｜不合格退料直接入库、退料不登记的管理风险","lecture":"**相邻关系：向上接 C86《抢修场景定额物料管理与快速发放》；向下接 C88《物料替代规则与参数匹配辨析》。**\n\n**现场情境：退库物料不检查就直接入库，降级料还当好料发。** 隐患在哪？本课讲退料判定。\n\n【退料三级分类】\n退回来的物料分三个等级，处置方式完全不同，不能混在一起。\n第一类可复用：状态完好，和新料一样，可以重新入库正常发放。\n第二类降级使用：有轻微瑕疵，但不影响核心性能，可以用在非关键部位。\n第三类报废：已经损坏、老化、超期，不能再用，走报废流程。\n分级判定是退库管理的核心，判错了要么造成浪费要么留下隐患。\n【可复用判定标准】\n同时满足三个条件，才能判定为可复用，重新入合格品库。\n包装完好：原包装完整，物料没有拆封，或者拆封但完全没使用。\n外观完好：没有磕碰、划伤、变形、锈蚀，和新物料状态一致。\n在质保期内：橡胶、塑料、胶类等有保质期的物料，还在有效期内。\n落回卡上：黄铜内螺纹浮动球阀、钢法兰盲板这类拆了没用的，符合条件就可以复用。\n只要有一项不满足，就不能算可复用，不能放回合格品区。\n【降级使用判定】\n轻微瑕疵、不影响核心性能的，可以降级使用，但有明确边界。\n适用情况：外观有轻微划痕、小磕碰，但密封、承压等核心性能不受影响。\n使用场景：只能用在非承压、非关键、临时使用的部位，不能用在主干管。\n单独存放：降级料单独放一个区域，贴明标识，不能和合格品混放。\n发放登记：领用时要注明降级使用，领用人确认知晓状态，不能当好料发。\n降级是为了减少浪费，但绝对不能降成质量隐患。\n【报废判定标准】\n触及任何一条红线，直接判定报废，绝对不能再用。\n1. 物理破损：裂纹、断裂、变形、密封面损坏，已经无法正常工作。\n2. 老化超期：橡胶发黏龟裂、塑料脆化、胶粘剂固化，性能已经失效。\n3. 性能不达标：阀门关不严、水表计量不准、密封件封不住水。\n4. 卫生不达标：给水接触类物料被污染，不符合卫生要求。\n报废物料单独存放，定期集中处置，不能混在库存里滥竽充数。\n【退库作业流程】\n退库按四步走，每一步都做到位，才不会乱。\n第一步核验：拿到退料先看外观、查状态，核对物料信息。\n第二步判定：对照三级标准，确定属于哪一类，拿不准的找技术确认。\n第三步登记：登记退料名称、数量、状态、退料原因、退料人。\n第四步归位：可复用的放回合格品区，降级的放降级区，报废的放报废区。\n全程留痕，每一笔退料都能查到原因、查到责任人。\n【常见管理误区】\n三个高频错误，都是管理松懈造成的，必须杜绝。\n不合格退料直接入库：图省事不检查，退回来就直接放上货架，把次品当好料。\n退料不登记：退了多少、为什么退、退的什么都不记，账实永远对不上。\n好坏混放：合格品、降级品、报废品堆在一起，发料时很容易拿错。\n这些误区看似省了事，最后都会造成库存混乱、质量隐患、资产流失。\n\n**自测：退回的料为什么必须先检查再入库？** 回本课【退料三级分类】对照。\n\n**自测：降级料能不能当好料发放？** 回本课【降级使用判定】对照。","structure":"知识结构：三级分类→复用标准→降级标准→报废标准→作业流程→常见误区，构成退库物料从判定到处臵的完整管理闭环。\n学习要点：\n1. 退料分三级：可复用、降级使用、报废，处置方式不同\n2. 可复用必须同时满足完好、未用、在质保期三个条件\n3. 降级使用有边界，只能用在非关键部位，单独存放标识\n4. 触及报废红线的直接报废，绝对不能凑合使用\n5. 退库四步走：核验→判定→登记→归位，全程留痕\n6. 杜绝不检查就入库、不登记、好坏混放三个误区\n退料最容易被当成「反正退回来了」随手一放，结果把隐患又放回货架；下一课 C88 讲缺料想用别的件顶上时，哪些能替、哪些要守住红线。","anchors":[{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"黄铜内螺纹浮动球阀","ref":"黄铜内螺纹浮动球阀"},{"name":"钢法兰盲板","ref":"钢法兰盲板"},{"name":"超声波水表","ref":"超声波水表"}],"pitfall":"1. 退回来的料不检查就入库，等于把隐患藏回了仓库\n2. 降级料不能当好料发，必须单独存放、明确告知\n3. 橡胶、胶类超期了就报废，别凑合用在管网上","remark":"","seq":51,"family":"其他","lessonNo":4},{"id":"C91","sub":"CL-04","topic":"盘点作业规范与系统操作实务","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课讲盘点全流程的标准化操作与系统工具使用，覆盖从准备到复盘的全环节实操规则，解决 “怎么盘、怎么录、怎么复核” 的问题，是仓管员必备的实操基本功。","framework":"盘点类型与适用场景｜动碰盘、定期盘、全面盘、盲盘、交叉盘的定义、适用范围与执行要求。盘点前准备工作｜物料整理归位、标签补全核对、库存基准导出、盘点表印制、工具准备。盘中计量与点数规则｜按根 / 按个 / 按套 / 按重量的计量标准；整箱散件、大口径小件的不同点数方法。标准化作业流程｜逐区盘点、逐项记录、盲盘执行、双人复核的操作规范与纪律要求。系统操作实务｜导出库存基准台账、核对物料编码与实物映射、录入初盘 / 复盘数据、生成差异报表。复盘与监盘要求｜复盘比例、抽盘规则、交叉盘点执行方法、监盘人职责与校验要点。盘点纪律红线｜禁止估数凑数、禁止提前看账盘点、禁止隐瞒差异、禁止自行调账。","lecture":"**相邻关系：向上接 C90《盘点管理与账实核对工作全景骨架》；向下接 C92《易混物料实物辨识与盘点防错技巧》。**\n\n**现场情境：整箱物料只点箱数记账，盲盘时还偷偷对照账面数。** 违规在哪？本课讲盘点作业规范。\n\n【盘点类型与适用场景：五种盘点各有用处】\n你日常会用到五种盘点形式，场景不能乱套。动碰盘针对当日有收发的物料，日清日结，适合日常管控；月度定期盘每月固定 1-2 天对全库区常用物料清点，是常规管控节点；\n年度全面盘每年至少一次，覆盖所有在库物料，对接财务资产核算；盲盘是盘点时不提供账面数量，完全凭实物清点，避免被账面数误导，多用于重要物料和监盘场景；\n交叉盘是不同库区仓管员互查，能发现自己平时注意不到的混放、错标问题。\n【盘点前准备工作：准备做足效率翻倍】\n盘点前的准备直接决定盘点速度和准确率，四件事必须做透。第一物料整理归位：同规格物料集中摆放，散件归拢，过道清理干净，避免漏盘重盘；\n第二标签补全核对：掉落、模糊的物料标签补打贴好，确保一物一签、信息对应；第三库存基准导出：从系统导出盘点基准日的库存台账，按库区、物料大类分类整理；\n第四工具准备：盘点表、签字笔、计算器、卷尺、扫码枪、手电、手套都备齐，盘点中途找工具最耽误时间。\n【盘中计量与点数规则：不同物料各有算法】\n物料形态不同，点数计量规则完全不一样，不能都按 “个” 数。管材类：PE 管、球铁管按根 / 按支清点，整垛的要点清层数和每层根数，截余的短管单独标记计数；\n管件类：按个 / 按套清点，整箱包装的先点整箱数，再加零散件数量，开箱核验时注意别弄混规格；辅材类：螺栓、胶垫（法兰橡胶垫片）、生料带（聚四氟乙烯密封带）等，整包整箱的按包装规格换算，拆零的逐个清点，贵重小辅材要双人复核；\n水表阀门类：按台 / 按个逐个清点，同时核对规格型号，不能只数数量不看型号。注意：所有计量都要以实物最小单位为准，不能按 “箱”“包” 直接入账，必须拆算到最小单位。\n【标准化作业流程：四步走不重不漏】\n盘点作业要按固定流程来，避免漏盘重盘。第一步逐区盘点：按库区货架顺序依次清点，走 “S” 形路线，不跳区、不漏架；第二步逐项记录：每盘完一个物料就立刻填盘点表，字迹清晰，不事后补填、不凭记忆填；\n第三步盲盘执行：初盘阶段尽量不看账面数，完全按实物清点，避免先入为主凑数；第四步双人复核：贵重物料、高易错物料必须由第二人复点，两人结果一致再确认。\n【系统操作实务：三步完成系统对账】\n盘点不是点完实物就完事，系统操作同样关键。第一步导出库存基准：盘点前从系统导出基准日的库存台账，核对物料编码、名称、规格、单位是否和现场一致；\n第二步录入盘点数据：初盘完成后，按物料编码逐一录入实盘数量，系统自动计算差异；第三步生成差异报表：初盘数据录完后，生成盘点差异表，标记出有差异的物料，进入复盘环节。\n注意：录入时要核对编码，不能张冠李戴把 A 物料的数录到 B 物料上。\n【复盘与监盘要求：校验质量的关键】\n初盘有差异的必须复盘，不能直接认定为差异。复盘比例按企业盘点制度设定，高价值、高易错物料应重点复盘；\n抽盘规则：监盘人员随机抽取物料进行抽点，抽盘差异率超过阈值的，要扩大复盘范围甚至重新全盘；交叉盘点：由其他库区仓管员执行，重点排查混放、错标、串规格问题；\n监盘职责：监盘人监督盘点全过程合规性，抽查盘点结果，不替代仓管员自盘。\n【盘点纪律红线：四条绝对不能碰】\n盘点纪律是底线，碰了就是严重违规。第一禁止估数凑数：不能看着差不多就填个数，必须逐件清点；第二禁止提前看账盘点：初盘不能先看账面数再对着凑数，等于白盘；\n第三禁止隐瞒差异：发现差异要如实上报，不能私自藏起来或者私下调整；第四禁止自行调账：就算确认了差异，也不能自己改系统数据，必须走审批流程。\n\n**自测：整箱物料盘点为什么要换算到最小单位？** 回本课【盘中计量与点数规则：不同物料各有算法】对照。\n\n**自测：盲盘时对照账面数为什么违规？** 回本课【盘点纪律红线：四条绝对不能碰】对照。","structure":"知类型：动碰盘日清日结，定期盘月度管控，全面盘年度资产核对，盲盘防先入为主，交叉盘互查纠错。\n做准备：物料归位、标签补全、导出台账、备齐工具，四步准备做足效率翻倍。\n会计量：管材按根、管件按个、辅材拆零核算、水表阀门逐台核验，统一到最小计量单位。\n走流程：逐区盘点、即时记录、盲盘初点、双人复核，按顺序来不重不漏。\n熟系统：导出基准、录入数据、生成差异表，编码对应准确不串户。\n懂复盘：按比例复盘、随机抽盘、交叉互查，监盘只监督不替代自盘。\n守红线：不估数、不看账、不瞒差、不调账，四条纪律严格执行。","anchors":[{"name":"PE 给水管","ref":"PE给水管"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"旋翼式机械水表（湿式 / 干式 / 液封）","ref":"旋翼式机械水表（湿式/干式/液封）"},{"name":"六角头螺栓（半丝 / 全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"生料带","ref":"生料带（聚四氟乙烯密封带）"},{"name":"哈夫节","ref":"哈夫节（堵漏器）"}],"pitfall":"【整箱物料不能只点箱数】整箱物料必须换算到最小单位，不能直接按箱记账；盲盘时偷偷对照账面数属于违规；大口径管材可以估根数是错误认知。","remark":"—","seq":52,"family":"其他","lessonNo":2},{"id":"C92","sub":"CL-04","topic":"易混物料实物辨识与盘点防错技巧","level":"D2 / L2","d":"D2","l":"L2","positioning":"这一课直击盘点最高频易错点，针对自来水仓库四类易混物料讲解实物辨识方法与防错技巧，解决 “看着都一样、实际不一样” 的盘点串户问题，大幅降低规格差错率。","framework":"管件类易混组辨识｜内外丝补芯 / 内外丝直接、PE/PPR 管件、衬塑 / 玛钢丝接管件的外观区分法。阀门类易混组辨识｜明杆 / 暗杆闸阀、中线 / 偏心蝶阀、旋启式 / 对夹式止回阀的核心差异点。辅材类易混组辨识｜不同口径胶圈 / 胶垫、4.8 级 / 8.8 级螺栓、生料带 / 密封胶的快速识别。水表仪表类易混辨识｜机械 / 智能水表、不同口径水表、冷水 / 热水表的外观与铭牌核对。标识认读技巧｜管身喷码、阀体铭牌、规格钢印、压力等级标识的现场认读方法。同型异规快速比对｜看端面、量壁厚、查铭牌、对接口的四步快速核验法。系统错误修正｜物料编码串户、规格录错、单位错误的识别与修正申报流程。盘点防错方法｜分类摆放、标识朝外、逐件核验、双人复核、易错品单独标记的实操技巧。","lecture":"**相邻关系：向上接 C91《盘点作业规范与系统操作实务》；向下接 C93《账实差异排查与成因分类辨析》。**\n\n**现场情境：补芯和直接只靠内外丝分、闸阀只看手轮、胶圈胶垫混着用。** 这些易混组怎么辨？本课讲防错技巧。\n\n【管件类易混组辨识：三组最容易拿错】\n管件是盘点串户的重灾区，三组最容易混。第一组内外丝补芯 vs 内外丝直接：补芯是变径的，一头大一头小，同时转换内外丝；内外丝直接是等径的，只转换内外丝不变径。\n盘点时看管身粗细，两头一样粗是直接，一头粗一头细是补芯。第二组 PE 管件 vs PPR 管件：PE 管件是黑色、大口径多、平口热熔；PPR 管件是绿色或白色、小口径多、承插热熔，看颜色和端口形状就能分。\n第三组衬塑管件 vs 纯玛钢管件：衬塑管件内壁有白色或浅绿色塑料层，纯玛钢管件内壁是铁的，看端面一眼就能区分，别把纯铁管件当成衬塑的盘进去。\n【阀门类易混组辨识：三类阀门易混淆】\n阀门外形相近但功能价格差很多，盘点时必须分清。第一讲明杆 vs 暗杆闸阀：看阀杆，开关时阀杆伸出来的是明杆，阀杆只转不升的是暗杆，不能只看手轮判断。\n第二中线 vs 偏心蝶阀：阀杆在蝶板正中间的是中线，阀杆偏置的是偏心；中线是软密封橡胶座，偏心有软有硬，看阀座材质也能辅助区分。第三旋启式 vs 对夹式止回阀：旋启式有摇板、阀体较厚；\n对夹式很薄、双瓣结构，夹在两法兰之间，厚度差一倍以上，很好分辨。\n【辅材类易混组辨识：小件最容易串规格】\n辅材体积小、规格多，盘点最容易点混。第一胶圈（球墨管承插密封圈） vs 胶垫（法兰橡胶垫片）：胶圈（球墨管承插密封圈）是厚环形、有唇边，塞球墨管承口用；胶垫（法兰橡胶垫片）是平圆片、薄，夹法兰之间用，形状完全不同，别拿混口径。\n第二 4.8 级 vs 8.8 级螺栓：看螺栓头部的数字标记，4.8 是普通级，8.8 是高强度级，头部钢印是唯一依据，不能凭颜色判断。第三生料带（聚四氟乙烯密封带） vs 密封胶：生料带（聚四氟乙烯密封带）是白色带状，缠螺纹用；\n密封胶是膏状，涂密封面用，形态完全不同，盘点时注意别把辅材品类搞混。\n【水表仪表类易混辨识：价值高出错影响大】\n水表价值高，盘错了资产偏差大，四点要核对。第一机械表 vs 智能表：机械表有叶轮字轮、纯机械结构；智能表带电子模块、有显示屏或通信天线，看有没有电子元件就分清。\n第二不同口径水表：看表体铭牌上的 DN 标识，不能凭大小估口径，DN15 和 DN20 外观很像，必须看铭牌。\n第三冷水表 vs 热水表：铭牌上会标注适用温度，热水表耐受温度更高，外观相近但价格和用途不同，不能混盘。\n【标识认读技巧：四个地方找答案】\n不用死记硬背，看标识就能辨物料。管身喷码：管材上的喷码有材质、口径、压力等级、标准号，逐字读就能确认；阀体铭牌：阀门侧面的金属铭牌，写着型号、口径、压力、标准，是最权威的依据；\n规格钢印：小管件、螺栓上的钢印，直接标规格和等级；压力等级标识：阀体、管件上的 PN 标识，代表承压能力。盘点时拿不准就找标识，别凭感觉猜。\n【同型异规快速比对：四步核验法】\n遇到两个看着像、拿不准规格的物料，按四步走。第一步看端面：口径不同的端面大小不一样，放一起一对比就明显；第二步量壁厚：同材质同压力等级下，口径越大壁厚越厚，用卡尺量一下更准；\n第三步查铭牌：找铭牌或喷码上的规格标注，以标识为准；第四步对接口：看接口尺寸，能和对应口径管材对上的就是对的。四步走完基本不会错。\n【系统错误修正：发现串户别硬凑】\n盘点时发现系统编码和实物对不上，比如编码写的是 DN50 实际是 DN40，这是系统串户错误。\n不能硬着头皮按系统规格盘，要先记录错误信息，走主数据修正申报流程，提交物料编码、正确规格、实物照片等佐证，由数据管理员修正后再更新台账。单位错误、名称错误也按这个流程来，不能私自改账。\n【盘点防错方法：五个技巧降差错】\n日常做好五件事，盘点差错能少一大半。第一分类摆放：同品类同规格集中放，易混物料分开放，别堆在一起；第二标识朝外：所有物料标签朝向通道，不用翻找就能看到；\n第三逐件核验：高易错物料盘点时逐个看规格，不能只数数量；第四双人复核：易混、贵重物料必须第二人复点；第五易错品单独标记：特别容易混的物料贴红色警示标，提醒盘点时重点核验。\n\n**自测：内外丝补芯和直接的核心区别是什么？** 回本课【管件类易混组辨识：三组最容易拿错】对照。\n\n**自测：明杆暗杆闸阀不能只看什么？** 回本课【阀门类易混组辨识：三类阀门易混淆】对照。","structure":"辨管件：补芯变径、直接等径；PE 黑 PPR 白；衬塑有塑层、玛钢是铁内壁。\n分阀门：明杆升暗杆转；中阀芯偏置；旋启厚对夹薄。\n识辅材：胶圈环形厚、胶垫平片薄；螺栓看头部钢印分等级；生料带是带状、密封胶是膏状。\n认水表：机械无电子模块、智能有显示屏；口径看铭牌、温度看标注。\n读标识：管身喷码、阀体铭牌、规格钢印、压力标识，拿不准就找标识。\n核异规：看端面、量壁厚、查铭牌、对接口，四步核验不踩坑。\n改错误：编码串户、规格录错、单位错误走申报流程，不私自改账。\n防差错：分类摆、标识朝外、逐件验、双人核、易错品标红。","anchors":[{"name":"衬塑内外丝补芯（变径补芯）","ref":"衬塑内外丝补芯（变径补芯）"},{"name":"衬塑双内丝直接","ref":"衬塑双内丝直接"},{"name":"衬塑双外丝直接","ref":"衬塑双外丝直接"},{"name":"弹性座封闸阀（明杆式）","ref":"弹性座封闸阀（明杆式）"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"中线（软密封）蝶阀","ref":"中线（软密封）蝶阀"},{"name":"旋启式止回阀（金属瓣/橡胶瓣）","ref":"旋启式止回阀（金属瓣/橡胶瓣）"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"六角头螺栓（半丝 / 全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"旋翼式机械水表（湿式 / 干式 / 液封）","ref":"旋翼式机械水表（湿式/干式/液封）"},{"name":"超声波水表","ref":"超声波水表"}],"pitfall":"【补芯和直接不能只看丝口】内外丝补芯和内外丝直接的核心区别是有没有变径，不是只看内外丝；明杆暗杆闸阀不能只看手轮，要看阀杆是否升降；胶圈和胶垫可以通用是错误认知。","remark":"—","seq":53,"family":"其他","lessonNo":3},{"id":"C03","sub":"XG-01","topic":"PE系统连接工艺与材料存放禁忌","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲PE系统的物理连接特性。新手不仅要认识它，还要知道热熔怎么接、法兰怎么对，以及它最怕什么。这是从“认料”到“懂料”的进阶。","framework":"连接方式配置｜热熔、法兰螺栓与丝接。热熔质量判读｜铣削、加热与翻边对称。辅材搭配｜螺栓、垫片与生料带。存放环境｜防暴晒、防重压与防划伤。执行标准｜材料配件的匹配。\nPE 连接工艺逐块讲透：为什么这样接、不这样会怎样｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\nPE 连接方式 × 配套辅材 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C29《户表控制箱》；向下接 C05《球墨铸铁管件端头辨识》。**\n\n**现场情境：热熔对接后，接口翻边一边大一边小，班组长说看着还行能用。** 这算合格吗？本课讲看翻边判质量。\n\n【热熔承插怎么接：四步走】\n**热熔承插是小口径管件的接法，管子插进承口里熔成一体。** 四步：先用刮刀把管口外皮刮掉一层、端头倒个角；在管子上量好承口深度、画一条线；把管子和承口同时放进加热模具烤到时间；无旋转地一次性插到底、让承口边挤出凸缘环。\n**插到位后要扶住不动，等它自然冷却才算接牢。** 冷却期间一晃动，接口就虚了。这套活靠的是承插加热器，和前面大管子的对接机不是一台设备。\n\n【氧化层必须刮：不刮就是假焊】\n**PE 管放在空气里，表面会悄悄长出一层很薄的氧化层，肉眼根本看不见。** 熔接前不把它刮掉，看着熔上了、其实两层塑料没真正融合，这就是“假焊”——当时看不出，一打压就从这里漏。\n**所以行规是：熔接前必刮、刮完不准用手摸。** 刮掉的是薄薄一层表皮，露出新鲜面，两家才能熔成一家。这是现场最高发的漏水原因，别嫌麻烦。\n\n【看天焊接：温度和环境也管接口质量】\n**焊接不光看手艺，天气也影响成败。** 气温低于 5℃ 要给管件保温、把冷却时间放长；下雨、下雪、刮大风要搭棚子，不能让雨水淋到熔接面；大太阳暴晒要给管件遮阳。\n**一句话：熔接面怕脏、怕水、怕忽冷忽热。** 环境不对，再好的管子也焊不牢。具体保温和冷却时长按现行工艺规范执行。\n\n【三大连接方式怎么配材料】\n**同材质PE对PE，用电热熔机。** 现场把两根黑管两头刮平，放进机器里烤软，拿出来瞬间顶推对接。\n**PE接带法兰的大铁阀门，用法兰头配合六角头螺栓（半丝/全丝）和胶垫（法兰橡胶垫片）。** 必须对角交替拧紧螺栓，让橡胶垫片受力均匀，绝不能按顺时针一圈拧死。\n**PE接小水表，用内丝/外丝直接配合生料带（聚四氟乙烯密封带）。** 生料带（聚四氟乙烯密封带）必须顺着螺纹拧紧的方向缠绕，否则一拧就松脱漏水。\n\n【热熔质量判读：看翻边】\n**热熔对接后，接口处会挤出一圈凸起的塑料，行话叫翻边。翻边就是检验真理的唯一标准。**\n如果翻边圆润、左右对称，说明受热均匀、顶推平行，焊得好。如果翻边一边大一边小，或者中间有气孔，说明加热不均或顶偏了。\n这种假焊内部没有融合，一打压必定漏水。发现不对称，必须当场用锯弓切掉重焊，绝不能凑合。\n\n【存放环境：防暴晒与尖锐物】\n**管子不仅要防暴晒，还要防重物压扁。** PE管最怕紫外线，露天存放久了像石头一样脆。\n另外，管子堆得太高压在底下的会变形；沟槽底部如果有大石头没清理，管身受力后会被尖角顶穿。这和金属管材的抗压能力完全不同，PE管更娇贵。\n\n【辅材搭配的防雷】\n**小配件也能毁掉大工程。** 法兰对接时用的垫片，给水默认EPDM，不能用普通的橡胶垫代替。\n紧固用的螺栓分半丝和全丝，法兰对接必须用半丝，利用光杆部分抗剪切。如果乱拿全丝螺栓，法兰孔对不齐，一加压就容易崩开。\n【PE 连接工艺逐块讲透：为什么这样接、不这样会怎样】\n**PE 系统的三种接法不是随便选，是由对面那头是什么材质定的。** 同材质对烫、接大铁件用法兰、接小丝口用嵌件，一步错就漏。\n**热熔对接要三步：铣削把两头刮平、加热把面烤软、顶推瞬间压合。** 少一步都不行，端面不平就存气，压合不到位就是假焊。\n**翻边左右对称，说明受热均匀、顶推平行；一边大一边小就是加热偏了。** 打比方，像烙饼两面受热不匀会一边焦；这种口一打压必漏，必须锯掉重焊。\n**法兰螺栓必须对角交替拧紧，顺时针一圈拧死会把胶垫（法兰橡胶垫片）挤到一边。** 落回卡上：看「胶垫（法兰橡胶垫片）」卡的材质栏，给水默认 EPDM，压偏了再好的垫也封不住。\n**生料带（聚四氟乙烯密封带）要顺着螺纹拧紧方向缠，反着一拧就松脱。** 这是最省钱的防漏动作，方向错了等于没缠。\n**PE 管怕晒又怕压：紫外线让分子链断、堆太高让底层管变形、沟底尖石会顶穿管身。** 这和球铁管能露天堆放的习性完全相反。\n【PE 连接方式 × 配套辅材 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\nPE 对 PE｜电热熔机｜铣削、加热、顶推三步｜看翻边圆润对称，不对称必切。\nPE 接大铁阀门｜PE法兰头/片 + 六角头螺栓（半丝/全丝） + 胶垫（法兰橡胶垫片）｜对角交替拧紧｜垫片放正别挡内孔，EPDM 为准。\nPE 接小水表｜内丝/外丝直接 + 生料带（聚四氟乙烯密封带）｜顺螺纹方向缠｜留第一扣，别缠太厚。\n露天存放｜遮阳布 + 平整场地 + 沟底清石｜避光、防重压、防尖角｜热熔温度与冷却时间按企业现行工艺规范，本课不代填。\n**【红线】翻边不对称就是假焊；法兰顺时针拧死必呲水；热熔前管口沾水会直接废掉这个口。**\n落回卡上：看「PE给水管」「PE法兰头/片」「六角头螺栓（半丝/全丝）」「胶垫（法兰橡胶垫片）」「生料带（聚四氟乙烯密封带）」五张卡，接法与辅材是配套的，缺一件就补不齐。\n\n**自测：热熔接口翻边不对称，说明什么？** 回本课【热熔质量判读：看翻边】对照。\n\n**自测：法兰对接时螺栓应该怎么拧？** 回本课【三大连接方式怎么配材料】对照。","structure":"同材质对烫，接铁用法兰加螺栓，接小丝扣用生料带。\n热熔看翻边，圆润对称为佳，不对称必切。\n存放防暴晒防重压，沟底清理尖锐石块。\n辅材要配套：用EPDM垫片和半丝螺栓。\n引导：本课已把三种接法的工艺与后果讲透；现场常卡在「翻边不对称还凑合放行」；下一步 C04 讲球铁管本体怎么认。","anchors":[{"name":"PE给水管","ref":"PE给水管"},{"name":"PE法兰头/片","ref":"PE法兰头/片"},{"name":"六角头螺栓","ref":"六角头螺栓（半丝/全丝）"},{"name":"胶垫","ref":"胶垫（法兰橡胶垫片）"},{"name":"生料带","ref":"生料带（聚四氟乙烯密封带）"}],"pitfall":"【翻边不对称就是假焊】热熔前管口不能沾水；法兰对接必须对角拧螺栓；沟槽底部要清石块。","remark":"企业填：热熔温度与冷却时间按企业现行工艺规范","seq":54,"family":"PE 管材·管件·连接","lessonNo":21},{"id":"C05","sub":"XG-01","topic":"球墨铸铁管件端头辨识：承插、双盘、双承与盘插","level":"D3 / L3","d":"D3","l":"L3","positioning":"管件长得千奇百怪，但只要看懂了端头，就绝不会拿错。这一课教新员工通过看两头的形状，快速认出短管、双承/双插等抢修过渡件。","framework":"承插端｜承口（喇叭）与插口（平口）。法兰端｜带螺栓孔的圆盘。双盘与双插双承｜两头同型端头。盘承与盘插｜法兰与承插的跨界过渡。抢修应用｜断管接驳怎么选。\n球铁管件端头逐块讲透：两头形状就是安装说明书｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n端头组合 × 用途 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C03《PE系统连接工艺与材料存放禁》；向下接 C06《球墨铸铁管件分支与变径》。**\n\n**现场情境：断管抢修，旁边剩的是插口还是承口没看清，就拿了管件去装。** 怎么选端头？本课讲看两头形状。\n\n【管件也要对 K 级：与管材标准配套】\n**球铁管件和管材是同一套标准 GB/T 13295 生产的，壁厚等级也要配套。** K9 的管子就配 K9 的管件，等级不一致接口对不上、承压也不匹配。验收别只顾看管子，管件上的喷码等级同样要核。逐档壁厚与承压值由技术部门按现行标准核定。\n\n【管件的三大类端头】\n管件怎么连，全看两端。第一类承插端：一头喇叭（承），一头平口（插）。第二类法兰端：带孔圆盘。\n看懂了端头，就等于看懂了它怎么接。\n\n【双盘、双承与双插】\n两端一样的叫什么？\n两头法兰叫双盘短管，用于阀门井两头接法兰件。\n两头承口叫双承短管，两头插口叫双插短管。这俩用在抢修！比如管子中间断了，锯掉破损段，如果两边剩下的是插口，你就得用双承短管套进去；如果两边剩的是承口，就得用双插短管。\n\n【盘承与盘插短管：跨界翻译官】\n一头法兰，一头承插，叫盘承或盘插短管。\n阀门井里装法兰阀门，阀门一侧用盘承（法兰接阀门，承口接直管），另一侧用盘插（法兰接阀门，插口插直管）。这就是它们最大的用途。\n\n【盲板与堵头】\n遇到管线末端或预留口，必须封死。用盲板或堵头。\n盲板是法兰盘样子的铁板，夹在两个法兰中间拧紧。球铁堵头则是靠承口塞进去封死。\n【球铁管件端头逐块讲透：两头形状就是安装说明书】\n**管件怎么连，全看两端端头，名字反而是最后才要记的。** 带孔圆盘是法兰、喇叭口是承、平头是插，三类端头组合出全部管件。\n**双盘短管两头法兰，用在阀门井里两头接法兰件。** 打比方，像一段两头都能拧螺丝的短接头；它不接直管的承插口。\n**双承短管两头承口、双插短管两头插口，是断管抢修的过渡件。** 中间断一段锯掉后，两边剩插口就用双承套进去，剩承口就用双插插进去，方向反了装不上。\n**盘承短管一头法兰接阀门、一头承口接直管；盘插短管一头法兰接阀门、一头插口插直管。** 记住「承口接纳、插口插入」，这两个最容易拿反。\n**盲板是实心法兰盘夹在两片法兰中间封死，堵头靠承口塞进去封死。** 管线末端或预留口必须封，用错件等于没封。\n【端头组合 × 用途 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n法兰 + 法兰｜双盘短管｜阀门井内接两片法兰件｜孔数与 PN 一起核。\n承口 + 承口｜双承短管｜两边剩插口的断管抢修｜确认槽内胶圈（球墨管承插密封圈）到位。\n插口 + 插口｜双插短管｜两边剩承口的断管抢修｜插入深度按工艺留量。\n法兰 + 承口｜盘承短管｜法兰接阀、承口接直管｜别拿成盘插。\n法兰 + 插口｜盘插短管｜法兰接阀、插口插直管｜别拿成盘承。\n实心盘 / 塞头｜球墨盲板（法兰盲板）、堵头｜封管线末端与预留口｜试压时盲板正前方严禁站人。\n**【红线】盘承与盘插拿反、双承与双插用反，现场直接装不上；试压盲板对面站人是最致命的安全事故。**\n落回卡上：把「盘插短管」「盘承短管」「双盘短管」「双承短管」「球墨盲板（法兰盲板）」五张卡的结构组成栏并排看，端头组合一目了然。\n\n**自测：盘承和盘插短管怎么区分、各接什么？** 回本课【盘承与盘插短管：跨界翻译官】对照。\n\n**自测：断管后旁边剩插口该用哪种管件？** 回本课【双盘、双承与双插】对照。","structure":"认端头：带孔圆盘是法兰，喇叭口是承，平头是插。\n双盘接阀门，双承/双插断管抢修。\n盘承短管：法兰接阀，承口接直管。\n盘插短管：法兰接阀，插口插直管。\n盲板封法兰，堵头封承口。\n引导：本课已按两端端头把短管与过渡件分族；现场常卡在「盘承盘插拿反」；下一步 C06 讲分支与变径件。","anchors":[{"name":"盘插短管","ref":"盘插短管"},{"name":"盘承短管","ref":"盘承短管"},{"name":"双盘短管","ref":"双盘短管"},{"name":"双承短管","ref":"双承短管"},{"name":"球墨盲板（法兰盲板）","ref":"球墨盲板（法兰盲板）"}],"pitfall":"【盘承和盘插别拿反】盘承是承口接直管；断管抢修分清楚，旁边剩插口用双承，剩承口用双插。","remark":"—","seq":55,"family":"球墨铸铁管及管件","lessonNo":22},{"id":"C06","sub":"XG-01","topic":"球墨铸铁管件分支与变径：弯头、三通与渐缩管","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲管路的分流、转弯与变细。认清楚弯头的角度、三通的端头组合，以及偏心渐缩管防气囊的特殊原理，并了解日常巡线最容易报错的节点。","framework":"弯头分类｜承插与双盘。三通分类｜看三个端头组合。渐缩管｜同心与偏心的致命区别。分水鞍｜不停水开孔接支管。\n球铁分支与变径逐块讲透：角度、端头与平顶的后果｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n分支 / 变径件 × 选型 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C05《球墨铸铁管件端头辨识》；向下接 C08《钢管法兰与管件》。**\n\n**现场情境：水平管上做变径，工人用了同心管；还有人想用分水鞍代替三通。** 错在哪？本课讲偏心防气囊。\n\n【弯头：改变方向】\n管线转弯用弯头。两头承插的叫承插弯头，两头法兰的叫双盘弯头。\n【认准角度，45度不能当90度用】，装错角度管线直接对不上。\n\n【三通：管线分叉】\n主管引出支管用三通。看图纸必须看清三个头是什么组合。\n比如承插盘三通：主管两端承插，支管那头是法兰盘，方便直接拧阀门。\n\n【渐缩管：偏心防气囊】\n大管变小管用渐缩管。分同心和偏心。\n【水平管必须用偏心渐缩管，而且管顶要平接】。水里含有空气，偏心平顶能让气泡顺着管顶溜走。如果用同心，管顶会形成一个倒扣的碗，气全憋在里面，直接阻断水流甚至引发水锤爆管。\n\n【分水鞍：不停水开孔】\n主管埋了想加支管，用分水鞍。像半个马甲套在管子上，拧紧后带压开孔。\n注意，分水鞍只能用于接小口径支管，绝不能替代三通做主管道分叉。\n【球铁分支与变径逐块讲透：角度、端头与平顶的后果】\n**弯头改变方向、三通引出支路、渐缩管改变管径，三件各管一件事。** 你先分功能，再看角度和端头，顺序反了就容易报错节点。\n**承插弯头两头承插、双盘弯头两头法兰，45 度不能当 90 度用。** 角度装错，管线直接对不上，返工要把整段锯掉。\n**承插盘三通主管两端承插、支管那头带法兰盘，方便直接拧阀门。** 看图纸必须数清三个头各是什么组合，这决定现场要不要再加过渡件。\n**水平管变径必须用偏心渐缩管，而且管顶要平接。** 打个比方，同心管会在管顶形成一个倒扣的碗把气憋住；偏心平顶让气泡顺着管顶溜走，不憋气就不会水锤爆管。\n**分水鞍像半个马甲套在主管上，拧紧后带压开孔接小支管。** 它只能接小口径支管，绝不能替代三通做主管道分叉，这是用途边界。\n【分支 / 变径件 × 选型 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n转弯｜承插弯头、双盘弯头｜按图纸角度（90°/45°）与端头选｜角度认准，别凭眼估。\n分叉｜承插盘三通、承插三通｜数清三个端头组合｜支口带盘可直接接阀。\n水平变径｜承插异径管（渐缩管）、双盘异径管（渐缩管）｜偏心、管顶平接｜同心件必憋气，禁止用在水平段。\n主管带压开孔｜鞍型管件（分水鞍）｜只接小口径支管｜不能替代三通做主分叉。\n**【红线】水平管变径用同心件必憋气；分水鞍不能当三通；弯头角度装错整段返工。**\n落回卡上：把「承插弯头」「承插盘三通」「承插异径管（渐缩管）」「鞍型管件（分水鞍）」四张卡的结构与用途栏并排看。\n\n**自测：水平管变径为什么必须用偏心管顶平接？** 回本课【渐缩管：偏心防气囊】对照。\n\n**自测：分水鞍能不能替代三通做分支？** 回本课【分水鞍：不停水开孔】对照。","structure":"弯头转向：承插/双盘，认准角度。\n三通分叉：承插盘三通，支口带法兰。\n变径：水平管必须用偏心，管顶平接防憋气。\n分水鞍：只能在主管上带压开小支管。\n引导：本课已把角度、端头与平顶的后果讲透；现场常卡在「水平变径用了同心件」；下一步 C07 看钢管怎么认。","anchors":[{"name":"承插弯头","ref":"承插弯头"},{"name":"双盘弯头","ref":"双盘弯头"},{"name":"承插盘三通","ref":"承插盘三通"},{"name":"承插三通","ref":"承插三通"},{"name":"承插异径管（渐缩管）","ref":"承插异径管（渐缩管）"},{"name":"双盘异径管（渐缩管）","ref":"双盘异径管（渐缩管）"},{"name":"鞍型管件（分水鞍）","ref":""}],"pitfall":"【水平管变径必须用偏心管顶平接】用错同心管必憋气；分水鞍只能接小支管，不能替代三通。","remark":"—","seq":56,"family":"球墨铸铁管及管件","lessonNo":23},{"id":"C08","sub":"XG-01","topic":"钢管法兰与管件：平焊、对焊法兰与焊接管件辨识","level":"D3 / L3","d":"D3","l":"L3","positioning":"钢管没有承插口也没有螺纹，全靠法兰和焊接。这一课教新员工认清平焊与对焊法兰的区别，以及各类钢焊接三通、弯头和盲板。","framework":"法兰分类｜平焊（SO）与对焊（WN）。钢法兰盲板｜封堵管口的实心铁板。焊接管件｜三通、弯头、异径管。辨识方法｜看脖子有没有突起的坡口。法兰 PN 等级与螺栓核对表｜PN10/16/25、SO/WN/BL、DN 怎么一起核。\n怎么辨：法兰件与螺纹件不能串用｜看接口形态、分系统，逐行可查，数值以核定为准。\n到货验收：法兰与焊接件逐项怎么验｜标识｜型式｜孔系｜坡口，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C06《球墨铸铁管件分支与变径》；向下接 C09《钢管连接工艺》。**\n\n**现场情境：高压管道法兰选型，有人图便宜要用平焊法兰。** 能不能用？本课讲平焊与对焊的分界。\n\n【法兰密封面有四种：FF/RF/MFM/TG】\n**法兰光有螺栓孔还不够，密封面形式也得配，买错垫片就漏。** FF 是全平面、RF 是突面、MFM 是凹凸面、TG 是榫槽面，不同面配不同垫片、适用压力也不同。最常见的是突面 RF 配普通垫片；压力越高越要用凹凸面、榫槽面。领垫片时密封面形式要和法兰对上。\n\n【GB 与 HG 两套法兰标准：尺寸不通用】\n**法兰有国标 GB/T 9119 和化工 HG20592 两套体系，尺寸互不通用。** 两套的螺栓孔距、密封面尺寸不一样，混着配会螺栓孔对不上、垫片压不严。核对采购单上的标准号，和现场法兰对一致再装配。\n\n【法兰双雄：平焊与对焊】\n钢法兰（平焊/对焊）是带孔圆盘，但分两种，看中间的孔。\n平焊法兰：像个平盘子，管子直接插进去，在正面焊一圈。适合低压。\n对焊法兰：中间突出一截“脖子”，像个漏斗，管子要和它对碰着焊。因为脖子加固了，所以能扛高压。泵房高压处必须用对焊法兰。\n\n【钢法兰盲板：封死管口的铁板】\n没有孔的实心铁圆盘，叫钢法兰盲板。\n管道末端要留接口，或者试压时要封死，就把盲板夹在两片法兰中间，螺栓一拧，一滴水都过不去。\n\n【焊接管件】\n钢管转弯用钢焊接弯头，分叉用钢焊接三通，变径用异径管。\n它们两头都是光秃秃的铁管口，没有任何丝扣或法兰。现场全靠电焊机焊死。焊不好的话，打压一打就漏。\n【法兰 PN 等级与螺栓核对表】\n**法兰不是只看孔径大小，PN 等级决定了孔数、孔径和螺栓规格，配错就装不上。** 表头顺序：PN 等级｜常见型式｜该核什么｜以谁为准。\nPN10｜平焊 SO 常见｜孔数、孔距、孔径、螺栓规格与长度｜现行法兰标准原文与厂家铭牌。\nPN16｜平焊 SO 或对焊 WN｜同上，与 PN10 可能不同孔距｜同上，不得凭眼混配。\nPN25｜多为对焊 WN｜同上，高压段优先对焊｜同上。\n型式｜SO 平焊 / WN 对焊 / BL 盲板｜看有没有脖子、有没有孔｜卡面型式标注。\n口径｜卡面 DN15–DN1200｜同 PN 下 DN 不同孔数也不同｜材料卡 DN 与 PN 两个字段一起核。\n**【红线】不同 PN 等级、不同 DN 的法兰螺栓孔可能不一样，凑合上螺栓会渗漏甚至崩飞。** 落回卡上：看「钢法兰（平焊/对焊）」「钢法兰盲板」卡的 PN10/16/25、SO/WN/BL、DN15–1200；\n孔数、孔径、螺栓规格由技术部门按现行标准核定，本课不代填。\n**自测：泵房高压段拿到一片平焊法兰，为什么不能凭孔径差不多就装？** 回本表核 PN 与型式两行。\n【怎么辨：法兰件与螺纹件不能串用】\n**钢管这段要么靠法兰螺栓压紧、要么靠电焊熔透，绝不能拿丝扣件混进来顶。** 你到现场先看接口：法兰是带孔圆盘，焊接件是光口铁管，两者都不带丝。\n**钢法兰盲板是实心铁圆盘、没有孔，靠夹在两片法兰中间拧紧来封堵；带丝扣的管帽是另一回事。**\n**看到补芯、活接头、管帽这类带丝扣的件，说明是衬塑或丝接系统，别往钢管法兰段上装。** 串用了，压力一上来就从丝扣处渗。\n**判断顺序给你：**1 看有没有脖子分 SO/WN；2 看有没有孔分法兰/盲板；3 看有没有丝扣分钢管件/丝接件。\n**落回卡上：**把「钢法兰（平焊/对焊）」「钢法兰盲板」「钢焊接三通」「钢焊接弯头」「钢异径管（同心/偏心）」并排看，全是光口或带孔圆盘。\n【到货验收：法兰与焊接件逐项怎么验】\n**验收不是数够数就完事，你要把标识、型式、孔系、坡口逐项对全，缺一项就先隔离。**\n1 标识：看卡面 PN 等级、型式 SO/WN/BL、DN 口径是否齐全，模糊或无标的先待检。\n2 型式：平焊看平盘、对焊看脖子，盲板看实心无孔，跟图纸要求一条条对。\n3 孔系：核孔数、孔距、孔径、螺栓规格与长度；孔数孔径螺栓规格以现行标准与技术部门核定为准，本课不代填。\n4 外观：法兰密封面无划伤无锈坑，焊接管口有坡口、无裂纹、无分层，光口不能带丝。\n**【红线】PN 或 DN 混配、密封面损伤、坡口缺失，三项任一命中就判异常，不许上高压段。**\n**自测：一片盲板到货，你先看什么？**回本块第 2 条核「实心无孔」，再回 PN 等级与螺栓核对表核配套项。","structure":"法兰：平焊适合低压（管子插进去），对焊适合高压（有脖子对碰焊）。\n盲板：实心铁盘，夹在法兰中间封堵。\n焊接管件：光口无丝扣，全靠电焊机操作。\n查全表：PN 定孔数孔径螺栓规格、型式看脖子、DN 一起核。\n记红线：孔数孔径螺栓规格以现行标准与技术部门核定为准，不凭眼混配。","anchors":[{"name":"钢法兰（平焊/对焊）","ref":"钢法兰（平焊/对焊）"},{"name":"钢法兰盲板","ref":"钢法兰盲板"},{"name":"钢焊接三通","ref":"钢焊接三通"},{"name":"钢焊接弯头","ref":"钢焊接弯头"},{"name":"钢异径管（同心/偏心）","ref":"钢异径管（同心/偏心）"}],"pitfall":"【高压必须用对焊法兰】平焊只能用于低压；盲板和垫片要一起夹在两法兰中间；焊接件看有没有坡口。","remark":"—","seq":57,"family":"钢管及法兰焊接","lessonNo":24},{"id":"C09","sub":"XG-01","topic":"钢管连接工艺：法兰对接与焊接注意事项","level":"D3 / L3","d":"D3","l":"L3","positioning":"钢管连接是个硬核手艺活。这一课讲法兰对接的螺栓紧固顺序、垫片的放置，以及坡口打磨。这是保证高压管道不漏水、不崩脱的核心。","framework":"法兰对接｜垫片放置与螺栓紧固。焊接工艺｜坡口打磨与对口间隙。辅助材料｜六角头螺栓与橡胶垫片。试压防雷｜盲板防飞脱。\n钢管连接工艺逐块讲透：拧紧、坡口与试压的后果｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n钢管连接 工艺核对表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C08《钢管法兰与管件》；向下接 C12《PPR系统连接工艺》。**\n\n**现场情境：试压时有人站到了盲板正前方，螺栓也是挨个顺序拧的。** 这两处有多大风险？本课讲对接与试压。\n\n【法兰对接：三分靠铁，七分靠拧】\n两片法兰中间要垫胶垫（法兰橡胶垫片）。\n六角头螺栓（半丝/全丝）穿过去，记住【必须对角交替拧紧】。不能顺时针挨个拧死，那样法兰会受力不均，垫片被挤到一边，一打压就呲水。\n垫片一定要放正，不能挡住管子内孔。\n\n【焊接工艺：打磨坡口】\n两根钢管要对焊，管口不能直接平碰。\n必须先拿角磨机打出V型坡口，留一点缝隙。这叫“坡口打磨”。这样电焊的熔池才能扎进铁板深处，焊得透。如果直接平面对接焊表面，一加压就会从内部裂开。\n\n【辅材搭配：EPDM胶垫（法兰橡胶垫片）】\n法兰中间垫的橡胶垫片，给水默认用EPDM。含油介质得用耐油的NBR。\n生料带（聚四氟乙烯密封带）在钢管法兰里用不上，那是给螺纹用的。\n\n【试压防雷：盲板对面绝不能站人】\n末端装了盲板打压时，盲板承受的推力极其巨大。\n【严禁人员站在盲板正前方】。如果螺栓拉断，盲板会像炮弹一样飞出来，这是试压时最致命的安全事故。\n【钢管连接工艺逐块讲透：拧紧、坡口与试压的后果】\n**法兰对接是「三分靠铁、七分靠拧」，垫片放正和螺栓顺序决定漏不漏。** 两片法兰中间夹胶垫（法兰橡胶垫片），穿六角头螺栓（半丝/全丝），一步都不能省。\n**螺栓必须对角交替拧紧，顺时针挨个拧死会让法兰受力不均、垫片被挤偏。** 打个比方，像拧汽车轮胎螺母要画十字；一打压就呲水的，多半是这一下没做对。\n**垫片要放正、不能挡住管子内孔。** 垫片偏心等于给水流设了个台阶，还会被水压逐步撕开。\n**两根钢管对焊前必须用角磨机打出 V 型坡口、留一点对口间隙。** 这样电焊熔池才能扎进铁板深处焊透；直接平面对接只焊了层皮，一加压从内部裂开。\n**法兰用 EPDM 胶垫（法兰橡胶垫片），生料带（聚四氟乙烯密封带）是给螺纹用的，在法兰里用不上。** 含油介质才改 NBR，别把辅材串场景。\n**试压时盲板承受的推力极其巨大，螺栓一断盲板会像炮弹一样飞出。** 严禁人员站在盲板正前方，这是试压最致命的安全事故。\n【钢管连接 工艺核对表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n垫片｜胶垫（EPDM，含油改 NBR）｜放正、不挡内孔｜选型以介质与现行标准核定为准。\n螺栓｜六角头螺栓（半丝/全丝）｜对角交替、分步拧紧｜扭矩按企业现行规范，本课不代填。\n坡口｜V 型坡口 + 对口间隙｜角磨机打磨后对焊｜平面对接焊不透，加压必裂。\n辅材｜生料带（聚四氟乙烯密封带）只用于螺纹｜法兰处不用生料带（聚四氟乙烯密封带）｜别把螺纹辅材串到法兰。\n试压｜钢法兰盲板封堵｜盲板正前方严禁站人｜螺栓拉断会飞板，划警戒区。\n**【红线】螺栓对角交替拧、必须打 V 型坡口、试压严禁站在盲板正前方；三条都是安全底线。**\n落回卡上：看「钢法兰（平焊/对焊）」「六角头螺栓（半丝/全丝）」「胶垫（法兰橡胶垫片）」「钢法兰盲板」「钢焊接弯头」五张卡，工艺与辅材一一对应。\n\n**自测：法兰螺栓为什么要对角交替拧？** 回本课【法兰对接：三分靠铁，七分靠拧】对照。\n\n**自测：试压时为什么严禁站在盲板正前方？** 回本课【试压防雷：盲板对面绝不能站人】对照。","structure":"法兰对接：垫片放正，螺栓对角交替拧。\n焊接：必须打V型坡口，熔透才结实。\n辅材：法兰用EPDM垫片，不用生料带。\n试压：盲板飞出会要命，严禁站人正前方。\n引导：本课已把拧紧、坡口与试压三条底线讲透；现场常卡在「顺时针一圈拧死螺栓」；下一步 C10 看 PPR 管材。","anchors":[{"name":"钢法兰（平焊/对焊）","ref":"钢法兰（平焊/对焊）"},{"name":"六角头螺栓","ref":"六角头螺栓（半丝/全丝）"},{"name":"胶垫","ref":"胶垫（法兰橡胶垫片）"},{"name":"钢法兰盲板","ref":"钢法兰盲板"},{"name":"钢焊接弯头","ref":"钢焊接弯头"}],"pitfall":"【螺栓对角交替拧】平焊不能上高压；直接平焊会炸开；试压严禁站在盲板正前方。","remark":"企业填：螺栓紧固扭矩与试压压力按规范","seq":58,"family":"钢管及法兰焊接","lessonNo":25},{"id":"C12","sub":"XG-01","topic":"PPR系统连接工艺：热熔承插与活接防漏","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲PPR的安装手艺。重点教热熔承插的火候把控（防缩径），活接头的垫片密封，以及PPR的热膨胀应对。这是室内维修最容易踩坑的地方。","framework":"热熔承插工艺｜加热时间与防缩径。螺纹密封｜生料带缠绕与活接垫片。热膨胀应对｜固定管卡与伸缩弯。辅材搭配｜生料带、胶垫与螺栓。执行标准｜工艺参数匹配。\nPPR 连接工艺逐块讲透：火候、垫片与热膨胀｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\nPPR 工艺防雷 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C09《钢管连接工艺》；向下接 C15《衬塑丝接管件（二）》。**\n\n**现场情境：PPR 热熔承插时，工人边转边往里插，还嫌加热时间长。** 这样接会怎样？本课讲火候。\n\n【热熔承插：火候决定生死】\nPPR用热熔承插。加热管子和管件，然后迅速插进去。关键看两点：\n一是必须【无旋转直插到底】，如果边插边转，熔化的塑料会被刮出，形成漏水通道。\n二是【加热时间不能太长】，时间长了，管子外壁化了太多，插进去后内部会被挤出一圈塑料环，这叫“缩径”。水流会变小，甚至堵死。\n\n【活接头与螺纹密封】\n用内外丝直接或活接头连接金属设备时，螺纹处必须缠生料带（聚四氟乙烯密封带）。\n而活接头内部通常是靠自带的橡胶平垫片来密封的。如果垫片老化漏水，【只需拧开大螺母换垫片，不要死命去拧金属丝口】。\n\n【热膨胀：塑料会变长】\nPPR通热水后，热胀冷缩非常明显。\n所以室内明装热水管，必须每隔一段距离加固定管卡，或者设计伸缩弯。如果卡死了，管子受热膨胀无处释放，会弯曲变形甚至从接头处拔出。\n\n【辅材搭配防雷】\n接金属阀门或水表，除了生料带（聚四氟乙烯密封带），千万别忘了检查活接头的垫片。这跟球墨铸铁法兰对接要用橡胶垫是一个道理，丢了垫片，怎么拧都漏。\n【PPR 连接工艺逐块讲透：火候、垫片与热膨胀】\n**热熔承插的火候决定生死，关键就两条：无旋转直插到底、加热时间不能太长。** 落回卡上：看「PPR给水管」「PPR内丝直接」两张卡的工艺提示。\n**边插边转会把熔化的塑料刮出来，形成一条漏水通道。** 打个比方，像把没干的胶蹭开一道缝；所以插进去就别再动。\n**加热太久管子外壁化得太多，插进去内部挤出一圈塑料环，这叫缩径。** 水流变小甚至堵死，根源就在这一下多烤了几秒。\n**活接头靠内部橡胶平垫片密封，漏水绝大多数是垫片老化或丢了。** 只需拧开大螺母换垫片，千万别拿大管钳死命拧金属丝口，容易把丝扣拧断在阀门里。\n**螺纹处缠生料带（聚四氟乙烯密封带）要顺拧紧方向，活接内部则靠垫片，别重复密封。** 两处机理不同，串着用料反而拧不紧。\n**PPR 通热水后热胀冷缩非常明显，明装热水管必须加固定管卡或伸缩弯。** 卡死了管子膨胀无处释放，会弯曲变形甚至从接头拔出。\n【PPR 工艺防雷 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n热熔动作｜无旋转直插到底｜插到位后保持不转｜边转边插必漏水。\n加热时间｜按管径与工艺规范｜适中，别过烤｜过烤会缩径，逐档时间按企业现行工艺规范，本课不代填。\n活接密封｜内部橡胶平垫片｜漏水先查垫片、再换垫片｜别死拧金属丝口。\n螺纹密封｜生料带（聚四氟乙烯密封带）顺螺纹缠｜留第一扣不缠｜防碎屑冲进水表阀芯。\n热膨胀｜固定管卡 / 伸缩弯｜按间距设置，别卡死｜卡死会变形、拔接头。\n**【红线】热熔后千万别转着插；加热太久会缩径；活接漏水先查垫片；热水管必须有固定管卡。**\n落回卡上：看「PPR给水管」「PPR内丝直接」「PPR外丝直接」「PPR活接头（内丝/外丝直接）」「生料带（聚四氟乙烯密封带）」五张卡，工艺与辅材是配套的。\n\n**自测：热熔后边转边插，接口会怎样？** 回本课【热熔承插：火候决定生死】对照。\n\n**自测：活接头漏水，第一步该查什么？** 回本课【活接头与螺纹密封】对照。","structure":"热熔：无旋转直插，加热时间适中，防缩径。\n活接：靠内部平垫片密封，漏水先查垫片。\n螺纹：缠生料带，顺螺纹拧紧方向。\n防变形：热水管必须有固定管卡。\n引导：本课已把火候、垫片与热膨胀讲透；现场常卡在「热熔后转着插导致漏水」；下一步 C13 看衬塑复合管。","anchors":[{"name":"PPR给水管","ref":"PPR给水管"},{"name":"PPR内丝直接","ref":"PPR内丝直接"},{"name":"PPR外丝直接","ref":"PPR外丝直接"},{"name":"PPR活接头（内丝/外丝直接）","ref":"PPR活接头（内丝/外丝直接）"},{"name":"生料带","ref":"生料带（聚四氟乙烯密封带）"}],"pitfall":"【热熔后千万别转着插】边转边插必漏水；加热太久会缩径；活接头漏水先查垫片，别死拧。","remark":"企业填：热熔温度与加热时间按工艺规范","seq":59,"family":"PPR 管材·管件·连接","lessonNo":26},{"id":"C15","sub":"XG-01","topic":"衬塑丝接管件（二）：活接头与内外丝直接","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课专讲衬塑管系统中的螺纹转换与可拆卸件。这是室内维修漏水的重灾区。重点讲衬塑活接头的结构原理与安装防漏。","framework":"活接头结构｜母体、螺母与平垫片。内丝/外丝直接｜管与金属设备的转换。防漏关键｜生料带与垫片。禁忌｜过度拧紧导致翻边破裂。\n衬塑螺纹转换逐块讲透：桥梁、后悔药与生料带｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n螺纹转换 × 防漏 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。\n到货验收：转换件与密封辅材怎么验｜丝扣｜垫片｜辅材，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C12《PPR系统连接工艺》；向下接 C16《衬塑沟槽管件与法兰》。**\n\n**现场情境：衬塑活接头漏水，工人拿大扳手死拧金属丝扣，生料带也缠得很厚。** 后果是什么？本课讲防漏。\n\n【内外丝直接：跨材质的桥梁】\n把衬塑管接到水龙头或铁阀门上，用内丝直接或外丝直接。\n一头接管，另一头带丝扣接设备。缠生料带（聚四氟乙烯密封带）时顺着螺纹方向缠，不能缠太厚。太厚不仅拧不进去，还容易把内衬塑料在丝扣根部的翻边撑裂，或者导致嵌件松动。\n\n【衬塑活接头：维修的后悔药】\n衬塑活接头（内丝/外丝）中间有一个大螺母。\n拆开看，里面有一个橡胶平垫片。它的作用是不用剪断管子就能拆卸设备。比如水表坏了，拧开活接螺母就能换。\n【漏水防雷】：如果衬塑活接头漏水，绝大多数是里面的平垫片老化或丢了，只需换个垫片。千万不要拿大管钳死命拧金属那头，容易把丝扣拧断在阀门里。\n\n【生料带（聚四氟乙烯密封带）的用法】\n外螺纹缠生料带（聚四氟乙烯密封带），内螺纹不缠。缠的时候留出第一扣螺纹不缠，防止生料带（聚四氟乙烯密封带）碎屑被水冲进管道堵塞水表或阀芯。\n【衬塑螺纹转换逐块讲透：桥梁、后悔药与生料带（聚四氟乙烯密封带）】\n**衬塑管接水龙头或铁阀门，靠内丝直接 / 外丝直接做跨材质桥梁。** 落回卡上：看「衬塑双内丝直接」「衬塑双外丝直接」两张卡，一头接管、一头带丝扣接设备。\n**生料带（聚四氟乙烯密封带）顺螺纹方向缠、不能缠太厚，太厚拧不进还会把内衬丝扣根部的翻边撑裂。** 打比方，像鞋带塞太满把鞋口撑变形；嵌件松动也常是这么来的。\n**衬塑活接头（内丝/外丝）中间有个大螺母，拆开里面是橡胶平垫片。** 它的价值是不用剪断管子就能换设备，水表坏了拧开螺母即可，是本课说的「后悔药」。\n**衬塑活接头漏水，绝大多数是平垫片老化或丢了，换个垫片就行。** 千万别拿大管钳死命拧金属那头，容易把丝扣拧断在阀门里，反而变成大修。\n**外螺纹缠生料带（聚四氟乙烯密封带）、内螺纹不缠，还要留出第一扣不缠。** 这样生料带（聚四氟乙烯密封带）碎屑不会被水冲进管道堵水表或阀芯。\n【螺纹转换 × 防漏 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n接设备｜衬塑双内丝直接 / 衬塑双外丝直接｜分清内丝外丝再缠带｜顺螺纹缠、别太厚。\n可拆连接｜衬塑活接头｜靠内部橡胶平垫片密封｜漏水先换垫片，别死拧。\n生料带（聚四氟乙烯密封带）｜外螺纹缠、内螺纹不缠｜留第一扣不缠｜防碎屑堵水表阀芯。\n过度拧紧｜严禁｜会撑裂内衬翻边、拧断丝扣｜拧不动先查有没有歪牙。\n漏水排查｜先垫片、再丝扣、最后查内衬｜按顺序排除｜别一上来就加力。\n**【红线】活接漏水先查垫片；别拿大扳手死拧金属丝扣；生料带（聚四氟乙烯密封带）别缠太厚，防撑裂内衬翻边。**\n落回卡上：把「衬塑活接头」「衬塑双内丝直接」「衬塑双外丝直接」「生料带（聚四氟乙烯密封带）」四张卡并排看，转换件与密封辅材是配套的。\n\n【到货验收：转换件与密封辅材怎么验】\n**领料时你要把转换件、活接、生料带（聚四氟乙烯密封带）当一套验，少一样现场就装不上或装完就漏。**\n1 内丝外丝：分清衬塑双内丝直接与衬塑双外丝直接，看丝扣完整、无歪牙，内衬翻边无裂纹。\n2 活接：拧开大螺母看里面橡胶平垫片在不在、有无老化发黏，垫片丢了就是漏水隐患。\n3 生料带（聚四氟乙烯密封带）：看是否聚四氟乙烯密封带、宽窄合适，别拿别的带子顶；缠绕圈数规范以厂家说明与技术部门核定为准，本课不代填。\n**【红线】活接缺垫片、内衬翻边已裂、丝扣歪牙，三项任一命中就判异常，别指望缠厚生料带（聚四氟乙烯密封带）救回来。**\n**落回卡上：**把「衬塑活接头」「衬塑双内丝直接」「衬塑双外丝直接」「生料带（聚四氟乙烯密封带）」四张卡的型式与密封辅材栏并排核一遍。\n\n**自测：活接漏水为什么先查垫片而不是死拧？** 回本课【衬塑活接头：维修的后悔药】对照。\n\n**自测：生料带缠太厚会有什么风险？** 回本课【生料带（聚四氟乙烯密封带）的用法】对照。","structure":"认转换：内外丝直接接设备，分清内丝与外丝。\n认活接：带大螺母，靠内部橡胶平垫片密封。\n查漏水：活接漏水先换垫片，别死拧丝口。\n缠生料带：顺螺纹缠绕，留出第一扣，防撑裂翻边。\n引导：本课已把转换桥梁、后悔药与生料带讲透；现场常卡在「活接漏水先死拧」；下一步 C16 讲沟槽与法兰。","anchors":[{"name":"衬塑活接头","ref":"衬塑活接头"},{"name":"衬塑双内丝直接","ref":"衬塑双内丝直接"},{"name":"衬塑双外丝直接","ref":"衬塑双外丝直接"},{"name":"生料带","ref":"生料带（聚四氟乙烯密封带）"}],"pitfall":"【活接漏水先查垫片】别拿大扳手死拧金属丝扣，会拧断在里面；生料带别缠太厚，防撑裂内衬。","remark":"—","seq":60,"family":"衬塑复合及丝扣/沟槽","lessonNo":27},{"id":"C16","sub":"XG-01","topic":"衬塑沟槽管件与法兰：大口径快装与设备转换","level":"D3 / L3","d":"D3","l":"L3","positioning":"大口径衬塑管靠沟槽连接，这也是消防和主干管的标配。这一课讲沟槽卡箍的原理，以及带塑料面的沟槽法兰安装常识。","framework":"沟槽卡箍｜刚性/柔性，C型橡胶圈。沟槽管件｜沟槽三通、弯头、异径管。沟槽法兰转换｜沟槽法兰与软垫片。安装工具｜滚槽机与扳手。\n衬塑沟槽与沟槽法兰逐块讲透：快装原理与刚柔之别｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n沟槽 / 沟槽法兰 选型对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C15《衬塑丝接管件（二）》；向下接 C17《倒流防止器》。**\n\n**现场情境：大口径快装要选沟槽卡箍，现场有刚性和柔性两种，胶圈还被扭了一下。** 怎么选、怎么装？本课讲。\n\n【沟槽连接靠的是那道槽】\n**沟槽卡箍快装，靠的是管端那道环形沟槽。** 用滚槽机在管端压出沟槽，卡箍嵌进槽里、螺栓拧紧、橡胶圈密封。沟槽的深度和宽度是关键，加工不到位卡箍就咬不紧、一打压就漏水。装之前先看槽口是否规整、有没有毛刺。\n\n【沟槽卡箍（刚性/柔性）：大口径的快装神器】\n你看不到丝扣，管子端头有一圈凹槽。\n把两段管子对接，外面套上卡箍外壳，里面放C型橡胶圈，拧紧两侧螺栓。胶圈受压变形把水封死。这比焊接快，比丝接牢。\n\n【刚性卡箍与柔性卡箍的区别】\n沟槽卡箍（刚性/柔性）分刚性和柔性。\n【刚性卡箍】像焊死一样，限制管道轴向位移，用于立管。\n【柔性卡箍】里面有缝隙，允许管道稍微偏转和伸缩，用于需吸收震动或沉降的埋地或长直管。\n\n【沟槽三通与弯头】\n端头带沟槽的管件，配合卡箍使用。安装时必须保证胶圈不扭曲，且螺栓要交替均匀拧紧。\n\n【沟槽法兰：接大设备的门面】\n接水泵或大阀门，用沟槽法兰。它的沟槽法兰密封面上有一层塑料，防腐。\n【重点】：两片沟槽法兰之间必须加非金属软垫片（给水常用EPDM，厚度3-5mm）。穿入螺栓后，必须对称、分步拧紧。严禁为了图省事，把普通钢法兰（平焊/对焊）直接焊在衬塑管上代替，那会直接烧毁内衬。\n【衬塑沟槽与沟槽法兰逐块讲透：快装原理与刚柔之别】\n**沟槽连接看不到丝扣，管子端头车出一圈凹槽，靠卡箍 + C 型胶圈封水。** 落回卡上：看「沟槽卡箍（刚性/柔性）」卡，比焊接快、比丝接牢，是大口径主干管的标配。\n**把两段管对接、外套卡箍、内放 C 型胶圈、交替拧紧两侧螺栓，胶圈受压变形把水封死。** 打个比方，像给两个管口箍了条橡胶腰带。\n**刚性卡箍像焊死一样限制轴向位移，用于立管；柔性卡箍留缝，允许偏转和伸缩。** 需吸收震动或沉降的埋地、长直管用柔性，用反了接口会受力开裂。\n**沟槽三通、弯头、异径管端头都带沟槽，安装时胶圈不能扭曲、螺栓要交替均匀拧。** 胶圈一扭就留缝，打压必渗。\n**沟槽法兰密封面上有一层塑料，两片之间必须加非金属软垫片（给水常用 EPDM）。** 螺栓对称分步拧紧；严禁把普通钢法兰（平焊/对焊）直接焊在衬塑管上代替，那会烧毁内衬。\n【沟槽 / 沟槽法兰 选型对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n刚性卡箍｜限制轴向位移｜立管、需固定段｜别用在要吸收沉降的长直管。\n柔性卡箍｜允许偏转与伸缩｜埋地、抗震、长直管｜别用在需刚性固定的立管。\nC 型胶圈｜卡箍内密封｜装前看无扭曲、无老化｜胶圈扭了打压必渗。\n沟槽管件｜沟槽三通、沟槽弯头、沟槽异径管（大小头）｜端头槽深一致｜槽不合格卡箍咬不住。\n沟槽法兰｜沟槽法兰 + 非金属软垫片｜对称分步拧紧｜严禁焊普通钢法兰（平焊/对焊）代替，垫片厚度以现行标准核定为准。\n**【红线】刚性防位移、柔性抗震别用反；胶圈千万别扭曲；沟槽法兰必须加软垫片，严禁焊死代替。**\n落回卡上：把「沟槽卡箍（刚性/柔性）」「沟槽三通」「沟槽弯头」「沟槽异径管（大小头）」「沟槽法兰」五张卡的连接方式栏并排看。\n\n**自测：刚性卡箍和柔性卡箍分别适合什么场合？** 回本课【刚性卡箍与柔性卡箍的区别】对照。\n\n**自测：沟槽卡箍的胶圈扭曲了会怎样？** 回本课【沟槽卡箍（刚性/柔性）：大口径的快装神器】对照。","structure":"认沟槽：管端有凹槽，靠卡箍+C型圈密封。\n分刚柔：刚性防位移（立管），柔性抗震（横管）。\n认沟槽法兰：沟槽法兰必须配非金属软垫片。\n禁忌：严禁用普通钢法兰焊接代替。\n引导：本课已把快装原理与刚柔之别讲透；现场常卡在「胶圈扭曲还打压」；下一步 C17 看倒流防止器。","anchors":[{"name":"沟槽卡箍（刚性/柔性）","ref":"沟槽卡箍（刚性/柔性）"},{"name":"沟槽三通","ref":"沟槽三通"},{"name":"沟槽弯头","ref":"沟槽弯头"},{"name":"沟槽异径管（大小头）","ref":"沟槽异径管（大小头）"},{"name":"沟槽法兰","ref":"沟槽法兰"}],"pitfall":"【刚性防位移，柔性抗震】胶圈千万别扭曲；沟槽法兰必须加软垫片，严禁拿普通钢法兰焊死代替。","remark":"—","seq":61,"family":"衬塑复合及丝扣/沟槽","lessonNo":28},{"id":"C17","sub":"XG-01","topic":"倒流防止器：防回流原理、三大类型与安装禁忌","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课专讲防污染的核心设备：倒流防止器。它是供水管网与消防、中水等系统的安全边界，核心任务是防止脏水倒灌。","framework":"外观与作用｜双向止水门，防倒灌污染。三大类型｜低阻力、减压、双止回。安装禁忌｜必须水平，严禁浸水。执行标准｜看标准号与泄水口。\n倒流防止器逐块讲透：为什么它是饮水安全红线设备｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n倒流防止器 类型 × 场景 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C16《衬塑沟槽管件与法兰》；向下接 C21《闸阀通识》。**\n\n**现场情境：倒流防止器装在了可能被脏水淹到的位置，还没加过滤器。** 这样装行不行？本课讲饮水安全红线。\n\n【空气隔断＋差动泄水：倒流防止器的核心】\n**倒流防止器不是靠一个止回阀挡水，靠的是“空气隔断”。** 进水止回阀的压差驱动泄水阀，一旦发生回流，中间腔排空、空气进去形成物理断开，水就过不回去。这是它比普通止回阀更保险的原因——结构上的隔断，不是单纯靠阀瓣。\n\n【三大类型按风险选】\n**倒流防止器有三类，防回流能力和水头损失不一样。** 减压型既防背压又防虹吸、能力最高；低阻力型水头损失小、适合市政节能；双止回阀型只防背压不防虹吸、用于低风险场合。按管道连接介质的风险等级来选，别一律买最便宜的。\n\n【外观与作用：单向安检门】\n你在库房看到的倒流防止器，通常是一段带有多个阀腔的铸铁件，两头法兰。\n它的作用是防止下游的脏水，因为压力波动倒流回上游的生活饮用水管网。这关乎饮水安全，是绝对的红线设备。\n\n【三大类型：看性能定场景】\n卡上有三种。第一种是减压型，内部有减压装置和泄水腔，保护等级最高，但水头损失大，用于高危边界。\n第二种是低阻力型，优化了内部流道，水头损失小于3米，适合对水压要求高的主干管。\n第三种是双止回阀型，只有两道止回，无泄水功能，防护等级最低，只能用在内部支管。\n\n【安装禁忌：必须水平与防淹】\n倒流防止器的中间腔有泄水阀，一旦压力失衡就会往外排水。\n【绝对不能在积水坑或下水道里安装】。泄水口必须能顺畅排走，且不能淹没在污水里，否则脏水会从泄水口倒灌。同时必须水平安装。\n\n【辅助配套：别忘了过滤器】\n内部有精密的弹簧和止回阀瓣。施工要求在进水口前必须安装Y型过滤器，防止泥沙卡死阀芯。\n【倒流防止器逐块讲透：为什么它是饮水安全红线设备】\n**倒流防止器是一段带多个阀腔的铸铁件、两头法兰，专防下游脏水倒灌回生活饮用水管网。** 落回卡上：看「低阻力倒流防止器」「减压型倒流防止器」「双止回阀型倒流防止器」三张卡。\n**减压型内部有减压装置和泄水腔，保护等级最高，但水头损失大，用于高危边界。** 打个比方，像安检最严的那道门，过得慢但最保险。\n**低阻力型优化了内部流道，水头损失小，适合对水压要求高的主干管。** 双止回阀型只有两道止回、无泄水功能，等级最低，只能用在内部支管。\n**中间腔有泄水阀，压力失衡就会往外排水，所以绝对不能装在积水坑或下水道里。** 泄水口必须能顺畅排走且不被污水淹没，否则脏水反而从泄水口倒灌。\n**必须水平安装，否则泄水阀和止回阀瓣不能正常复位。** 内部有精密弹簧，进水口前还必须装 Y 型过滤器，防泥沙卡死阀芯。\n【倒流防止器 类型 × 场景 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n减压型｜减压装置 + 泄水腔｜高危边界、防污染等级最高｜水头损失大，按设计核定。\n低阻力型｜优化流道、水损小｜对水压要求高的主干管｜逐档水头损失值以现行标准与技术部门核定为准。\n双止回阀型｜两道止回、无泄水｜仅内部支管｜防护等级最低，不得越级用于高危边界。\n安装｜水平、泄水口可排走｜严禁浸在污水坑｜泄水口被淹等于防污染失效。\n配套｜前端 Y 型过滤器｜防泥沙卡死阀芯｜过滤器滤网朝下，定期清理。\n**【红线】泄水阀不能泡在脏水里、必须水平安装、前端必装过滤器；防污染等级不能随便降级使用。**\n落回卡上：把三张倒流防止器卡的作用与结构栏并排看，等级差异一眼就分得清；JB/T 11151 换版提示以卡面与主管部门要求为准。\n\n**自测：泄水阀泡在脏水里有什么后果？** 回本课【安装禁忌：必须水平与防淹】对照。\n\n**自测：倒流防止器前端为什么要加过滤器？** 回本课【辅助配套：别忘了过滤器】对照。","structure":"认作用：防脏水倒流，保饮水安全。\n分类型：减压最安全，低阻力水损小，双止回等级低。\n守禁忌：严禁装在污水坑，必须水平。\n配附件：前端必装过滤器。\n引导：本课已把三种类型的等级与安装红线讲透；现场常卡在「泄水口装在积水坑」；下一步 C18 讲 Y 型过滤器。","anchors":[{"name":"低阻力倒流防止器","ref":"低阻力倒流防止器"},{"name":"减压型倒流防止器","ref":"减压型倒流防止器"},{"name":"双止回阀型倒流防止器","ref":"双止回阀型倒流防止器"}],"pitfall":"【泄水阀不能泡在脏水里】一定要水平安装；前端必须加过滤器；防污染等级不能随便降级使用。","remark":"—","seq":62,"family":"阀门与设备","lessonNo":29},{"id":"C21","sub":"XG-01","topic":"闸阀通识：明杆暗杆区别、弹性座封与防盗加密","level":"D3 / L3","d":"D3","l":"L3","positioning":"闸阀是管网里最笨重但最普及的截断阀。这一课讲明杆和暗杆的现场识别，弹性座封的零泄漏原理，以及户内防盗水的黄铜与加密闸阀。","framework":"外观与原理｜像插板，升降截断。明杆与暗杆｜看杆伸不伸，定阀井深度。弹性座封｜包胶闸板，零泄漏。黄铜与加密｜户内控制与防盗水。\n闸阀逐块讲透：明暗杆、包胶与加密锁｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n闸阀 型式 × 场景 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C17《倒流防止器》；向下接 C22《减压阀通识》。**\n\n**现场情境：闸阀被长期半开当调节阀用，暗杆阀还靠阀杆高度判断开度。** 这两处错在哪？本课讲明暗杆。\n\n【闸板有楔式和平行式】\n**闸阀的闸板分楔式和平行式，结构不同、脾气也不同。** 楔式两密封面成楔角、密封好，但温差大时容易卡死；平行式两面平行、靠介质压力压紧，适合大口径。型号里的结构形式代号能查到是哪种，检修卡涩时先分清闸板形式。\n\n【外观与原理：闸门升降】\n闸阀像个小房子。转动手轮，内部的闸板像水闸一样升起降下。\n全开时水流直通，水阻小，但不能用来调节流量，半开半关会引起震动。\n\n【明杆与暗杆：怎么选】\n看阀杆。开关时阀杆往外伸的，叫明杆。好处是看杆的长度就知道开度，但占上方空间，阀井要够深。\n阀杆只原地转、不升起的，叫暗杆。省空间，适合地下受限阀井，但看不到开度。\n\n【弹性座封：供水主力】\n传统的铁闸板关不严。现在管网的主力是弹性座封（软密封）闸阀。\n闸板表面整体包了一层橡胶。一关到底，橡胶变形，实现气泡级零渗漏，且启闭非常轻巧。\n\n【黄铜与加密：户内防盗】\n小口径户内用黄铜闸阀。如果是小区总表前或入户管，为了防止偷水，会用加密闸阀。必须插入专用的磁性钥匙才能转动，没钥匙手轮只能空转。\n【闸阀逐块讲透：明暗杆、包胶与加密锁】\n**闸阀像个小房子，转手轮内部闸板像水闸一样升降截断。** 落回卡上：看「弹性座封闸阀（暗杆式）」「弹性座封闸阀（明杆式）」两张卡，全开水阻小，但绝不能半开调流量。\n**半开半关会让闸板在水流里震动、冲刷密封面，这是闸阀最常见的误用。** 打个比方，像把门半掩着让风一直拍；要调流量该用别的阀。\n**明杆开关时阀杆往外伸，看杆长就知道开度，但占上方空间、阀井要够深。** 暗杆只原地转、不升起，省空间适合地下受限阀井，代价是看不到开度。\n**弹性座封（软密封）闸板整体包胶，一关到底橡胶变形实现零渗漏，启闭轻巧，是供水主力。** 传统铁闸板关不严，别拿旧件混发。\n**小口径户内用黄铜闸阀；总表前或入户管用加密闸阀，必须插专用磁性钥匙才能转。** 没钥匙手轮只能空转，这是防偷水的底线。\n【闸阀 型式 × 场景 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n明杆｜阀杆外伸、看得到开度｜阀井空间足、需看开度｜井深不够装不下。\n暗杆｜阀杆原地转、省空间｜地下受限阀井｜看不到开度，靠记录。\n弹性座封｜闸板整体包胶、零泄漏｜供水管网主力｜别拿传统铁闸板混发。\n黄铜闸阀｜小口径户内｜表前 / 户内控制｜丝扣顺螺纹缠带。\n加密闸阀｜磁性钥匙启闭｜总表前、防偷水｜没钥匙只会空转，钥匙专管。\n**【红线】闸阀严禁半开当调节用；暗杆省空间但看不了开度；加密阀没钥匙只会空转。**\n落回卡上：把「弹性座封闸阀（暗杆式）」「弹性座封闸阀（明杆式）」「黄铜闸阀」「黄铜加密闸阀」「加密闸阀」五张卡的阀杆与锁具栏并排看。\n\n**自测：闸阀长期半开当调节用会怎样？** 回本课【明杆与暗杆：怎么选】对照。\n\n**自测：暗杆闸阀能不能靠阀杆外露判断开度？** 回本课【明杆与暗杆：怎么选】对照。","structure":"认闸阀：像插板，升降截断，不可半开调节。\n分明暗：明杆看开度占空间，暗杆省空间看不见。\n认软封：整体包胶，零泄漏，供水主力。\n认加密：带锁芯，专用于防偷水。\n引导：本课已把明暗杆、包胶与加密锁讲透；现场常卡在「闸阀半开当调节用」；下一步 C22 看减压阀。","anchors":[{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"弹性座封闸阀（明杆式）","ref":"弹性座封闸阀（明杆式）"},{"name":"黄铜闸阀","ref":"黄铜闸阀"},{"name":"黄铜加密闸阀","ref":"黄铜加密闸阀"},{"name":"加密闸阀","ref":"加密闸阀"}],"pitfall":"【闸阀严禁半开当调节用】暗杆省空间但看不了开度；加密阀没钥匙只会空转。","remark":"—","seq":63,"family":"阀门与设备","lessonNo":30},{"id":"C22","sub":"XG-01","topic":"减压阀通识：先导与直动结构、稳压原理与安装规范","level":"D3 / L3","d":"D3","l":"L3","positioning":"水管里的压力不能太大，否则会爆管。减压阀就是把高压稳定在低压的调节器。这一课讲清先导式和直动式的区别及安装红线。","framework":"外观与结构｜膜片、弹簧与导阀。直动式｜结构简单，用于小流量。先导式｜精度高，用于大流量。安装规范｜必须水平，配过滤器和直管段。\n减压阀逐块讲透：膜片怎么把高压稳成低压｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n减压阀 型式 × 安装 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C21《闸阀通识》；向下接 C23《止回阀通识》。**\n\n**现场情境：减压阀前没装过滤器，有人还想拿它来完全关断水流。** 这样用行不行？本课讲安装红线。\n\n【减压阀前要留直管段】\n**减压阀想稳压准，前面必须有一段直管稳流。** 一般阀前直管不少于 5-10 倍管径、阀后 3-5 倍；紧挨着弯头、三通装，水流不稳就稳压不准、出口压力忽高忽低。安装时先看前后有没有足够直管，别为省地方贴着弯头装。\n\n【外观与结构：调压大脑】\n减压阀通常上部带有调节螺钉或弹簧罩。\n它的内部核心是膜片。出水口的压力顶着膜片，与上方的弹簧平衡。压力高了关小阀口，压力低了开大阀口，实现稳压。\n\n【直动式与先导式】\n直动式结构简单，靠膜片直接带动阀瓣。但流量一大，压力就不稳，适合户内小流量。\n先导式多了一个细小的导阀。用导阀控制主阀，稳压精度极高。大口径和管网主干线必须用先导式。\n\n【安装红线：过滤与直管段】\n减压阀的导阀孔非常细，稍微有个沙粒就会卡死。\n【阀前必须安装Y型过滤器】。且必须水平安装。\n阀前阀后还要留有足够长的直管段，保证水流平稳，不然压力会乱跳。\n\n【失效防雷】\n如果减压阀卡死在常开位置，下游的低压管就会被高压水击穿。通常会在阀后配安全阀来泄压。\n【减压阀逐块讲透：膜片怎么把高压稳成低压】\n**减压阀上部带调节螺钉或弹簧罩，内部核心是膜片。** 落回卡上：看「先导式减压阀」「直动式减压阀」两张卡，出水压力顶着膜片与弹簧平衡，压力高关小阀口、压力低开大阀口。\n**打个比方，膜片像一杆秤：一边是出口水压、一边是弹簧，哪边重就往哪边动，阀口跟着变。** 这就是它能「稳」住压力的原因。\n**直动式靠膜片直接带动阀瓣，结构简单但流量一大压力就飘，适合户内小流量。** 先导式多了个细小导阀，用导阀控主阀，稳压精度极高，大口径主干线必须用它。\n**导阀孔非常细，一颗沙粒就能卡死，所以阀前必须装 Y 型过滤器，且必须水平安装。** 阀前阀后还要留足直管段，水流不平稳压力就乱跳。\n**减压阀卡死在常开位，下游低压管会被高压击穿，所以阀后通常配安全阀泄压。** 也别拿它当截止阀完全断水，它不是干这个的。\n【减压阀 型式 × 安装 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n直动式｜膜片直带阀瓣、结构简单｜户内小流量｜流量一大压力不稳。\n先导式｜导阀控主阀、精度高｜大口径、主干线｜导阀孔细，怕泥沙。\n前置过滤｜Y 型过滤器，阀前必装｜防导阀卡死｜滤网朝下、定期排污。\n安装姿态｜水平、前后留直管段｜保证水流平稳｜竖直装会调压失准，直管段长度按现行规范核定。\n失效保护｜阀后配安全阀｜卡常开时泄压｜别拿减压阀当截止阀用。\n**【红线】阀前必须装过滤器、必须水平安装、前后要直管段；导阀一堵全废，不能用减压阀完全截止水流。**\n落回卡上：把「先导式减压阀」「直动式减压阀」两张卡的结构组成与适用场景栏并排看，型式与流量一次对上。\n\n**自测：减压阀前不装过滤器会怎样？** 回本课【安装红线：过滤与直管段】对照。\n\n**自测：能不能用减压阀去完全截止水流？** 回本课【失效防雷】对照。","structure":"认作用：把高压稳稳降到低压，保护管网。\n分结构：小流量用直动，大口径大流量用先导。\n守红线：必须水平，前必装过滤器，前后要直管段。\n引导：本课已把膜片稳压与安装红线讲透；现场常卡在「导阀被沙粒卡死」；下一步 C23 看止回阀。","anchors":[{"name":"先导式减压阀","ref":"先导式减压阀"},{"name":"直动式减压阀","ref":"直动式减压阀"}],"pitfall":"【阀前必须装过滤器】导阀一堵全废；必须水平安装；不能用减压阀去完全截止水流。","remark":"—","seq":64,"family":"阀门与设备","lessonNo":31},{"id":"C23","sub":"XG-01","topic":"止回阀通识：旋启、升降、对夹与静音缓闭","level":"D3 / L3","d":"D3","l":"L3","positioning":"止回阀是单向门，只准水前进不准后退。这一课教新员工怎么认出旋启、升降和对夹式，以及它们在泵房里的防倒流作用。","framework":"外观与原理｜单向阀瓣。旋启式｜像门绕轴转，金属瓣水锤大，橡胶瓣快关。升降式｜垂直起落，密封好。对夹式｜薄片省空间，双瓣。静音式｜带弹簧缓闭，防破坏性水锤。\n止回阀逐块讲透：四类阀瓣与泵房水锤｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n止回阀 型式 × 特性 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。\n现场判定：装反与选错型式怎么判｜方向｜型式｜异常，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C22《减压阀通识》；向下接 C32《伸缩器与铸铁伸缩节》。**\n\n**现场情境：水泵出口要装止回阀，现场有旋启、升降、对夹和静音缓闭四种。** 怎么选？本课讲泵房水锤。\n\n【旋启、升降阀装反了就不止回】\n**止回阀有安装方位要求，装错方向等于没装。** 升降式（直通）一般只能装在水平管上，立式升降式才装竖直管；旋启式水平竖直都行，但大口径要防止倒装。装之前找到阀体箭头、对准水流方向，再定安装姿态。\n\n【外观与原理：单向关卡】\n止回阀没有手轮。水流正向冲开阀瓣，反向时阀瓣被回水压死。\n它常装在泵出口，防止突然停泵时，高压水倒流把叶轮打坏。\n\n【旋启式与升降式】\n旋启式像一个铰链门，摇板向上翻起。水流很顺畅，适合大口径。注意，如果是金属旋启式，关阀水锤大；如果是橡胶瓣旋启式，短行程快关，水锤会小很多。\n升降式是阀瓣直上直下，密封极好，但阻力大，用于小口径或立管。\n\n【对夹式与静音式】\n对夹式像一个夹心饼干，很薄，只有法兰对夹。里面是对开的双瓣，水锤力小。\n静音缓闭式内部有弹簧和阻尼。停泵时，先快速关90%再慢慢关上最后10%，能削减水锤爆炸声，防止管网震动。\n【止回阀逐块讲透：四类阀瓣与泵房水锤】\n**止回阀没有手轮，水流正向冲开阀瓣、反向被回水压死，是只准进不准退的单向门。** 落回卡上：看「旋启式止回阀（金属瓣/橡胶瓣）」「对夹碟式止回阀」「静音式（缓闭）止回阀」等卡。\n**它常装在泵出口，防突然停泵时高压水倒流把叶轮打坏。** 打个比方，像给水泵装了道只能向外推的弹簧门。\n**旋启式像铰链门、摇板向上翻，流阻小适合大口径；金属瓣关阀水锤大，橡胶瓣短行程快关、水锤小很多。** 升降式阀瓣直上直下、密封极好，但阻力大，用于小口径或立管。\n**对夹式像夹心饼干很薄，只有法兰对夹，里面是对开双瓣，水锤力小、省空间。** 静音缓闭式带弹簧和阻尼，停泵时先快关 90%、再慢关最后 10%，削减水锤爆炸声。\n**选型的本质是选关阀速度与水锤控制，不只是选外形。** 泵房必须装，装错型式轻则噪音、重则管网震动。\n【止回阀 型式 × 特性 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n旋启式（金属瓣）｜摇板绕轴翻起｜大口径、流阻小｜关阀水锤大，注意停泵冲击。\n旋启式（橡胶瓣）｜短行程快关｜需减小水锤｜比金属瓣水锤小。\n升降式｜阀瓣垂直起落｜小口径、立管｜密封好但阻力大。\n对夹碟式｜薄片双瓣、法兰对夹｜空间受限处｜方向别装反，逐档口径以卡面核定为准。\n静音缓闭式｜弹簧 + 阻尼缓闭｜泵房、防水锤｜先快关九成再慢关一成。\n**【红线】静音缓闭防破坏性水锤；升降式阻力大；对夹薄但要注意方向；水泵出口必须装止回阀。**\n落回卡上：把「旋启式止回阀（金属瓣/橡胶瓣）」「升降式止回阀」「对夹碟式止回阀」「静音式（缓闭）止回阀」「黄铜立式/卧式止回阀」五张卡的阀瓣结构栏并排看。\n\n【现场判定：装反与选错型式怎么判】\n**止回阀装完先看方向再看型式，方向装反等于把单向门倒过来，泵一停就挡不住倒流。**\n1 方向：阀体上的流向箭头必须和管内水流一致，对夹式薄片尤其容易装反，装前对着箭头核一遍。\n2 型式：泵房要防水锤优先静音缓闭式；空间受限的两法兰之间才用对夹碟式；大口径流阻小用旋启式。\n3 阀瓣：金属旋启关阀水锤大、橡胶瓣短行程快关水锤小，选型本质是选关阀速度与水锤控制。\n4 异常：阀瓣卡滞、摇板不能自由回位、密封面有划伤，判异常，不许装泵出口。\n**【红线】水泵出口必须装止回阀；流向箭头对不上、对夹装反、阀瓣卡滞，任一命中就返工。**\n**落回卡上：**把「旋启式止回阀（金属瓣/橡胶瓣）」「升降式止回阀」「对夹碟式止回阀」「静音式（缓闭）止回阀」「黄铜立式/卧式止回阀」五张卡的流向标记与阀瓣结构栏并排看。\n\n**自测：为什么水泵出口首选静音缓闭止回阀？** 回本课【对夹式与静音式】对照。\n\n**自测：升降式止回阀的阻力特点是什么？** 回本课【旋启式与升降式】对照。","structure":"认作用：只准进不准退，保护水泵，泵口必装。\n分结构：旋启像门阻力小，升降直落密封好。\n认对夹：薄薄的双瓣，省空间水锤小。\n认静音：带弹簧缓闭，消除水锤噪音。\n引导：本课已把四类阀瓣与水锤讲透；现场常卡在「对夹式方向装反」；下一步 C24 看排气阀。","anchors":[{"name":"旋启式止回阀","ref":"旋启式止回阀（金属瓣/橡胶瓣）"},{"name":"升降式止回阀","ref":"升降式止回阀"},{"name":"对夹碟式止回阀","ref":"对夹碟式止回阀"},{"name":"静音式（缓闭）止回阀","ref":"静音式（缓闭）止回阀"},{"name":"黄铜立式/卧式止回阀","ref":"黄铜立式/卧式止回阀"}],"pitfall":"【静音缓闭防破坏性水锤】升降式阻力大；对夹式薄但要注意方向；水泵出口必须装。","remark":"—","seq":65,"family":"阀门与设备","lessonNo":32},{"id":"C32","sub":"XG-01","topic":"伸缩器与铸铁伸缩节：热胀冷缩补偿与防拉脱限位","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲套管式的伸缩接头。重点讲B2F限位型和C2F传力型的区别，以及它们与铸铁管的配套应用。","framework":"外观与结构｜伸缩管+压盖+密封圈。套管伸缩器｜法兰连接，常用于泵房。铸铁伸缩节｜B2F限位与C2F传力。限位与传力｜吸位移与传推力的区别。安装要求｜预留伸缩量。\n伸缩器与铸铁伸缩节逐块讲透：吸位移与传推力｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n伸缩件 型式 × 功能 对照表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C23《止回阀通识》；向下接 C28《防腐与抢修辅材》。**\n\n**现场情境：有人把 C2F 伸缩节当 B2F 用，还把安装顶死不留余量。** 错在哪？本课讲吸位移与传推力。\n\n【外观与结构】\n它是一段大管套小管。外面有压盖，里面塞着填料或橡胶圈。松开压盖，内管就能滑动，用来补偿管道的热胀冷缩。\n\n【套管式伸缩接头】\n一般为钢制。安装在泵房或钢管的法兰连接处。它伸缩量大，能吸收管路产生的轴向位移。\n\n【铸铁伸缩节：B2F与C2F的区别】\n这是球墨铸铁管网常用的。B2F是限位型，里面有双螺母，允许管子自由伸缩，但到极限位置会死死卡住防拉脱。\nC2F是传力型，外面有几根长螺杆把两头锁死，一点位移都不吸收，专门用来把水泵的盲板推力传给管道，保护水泵。\n\n【安装预留】\n安装伸缩器不能顶到死，必须在内部预留出伸缩余量。否则夏天一热，管子伸长，直接把伸缩器顶坏。\n【伸缩器与铸铁伸缩节逐块讲透：吸位移与传推力】\n**伸缩器是一段大管套小管，外面压盖、里面填料或橡胶圈，松开压盖内管就能滑动。** 落回卡上：看「多功能法兰连接器（防脱法兰/伸缩法兰接头）」「球墨铸铁伸缩节（限位型/传力型）」两张卡。\n**钢制套管伸缩接头一般为法兰连接，装在泵房或钢管法兰处，伸缩量大、吸收轴向位移。** 打个比方，像望远镜的套筒，能拉长能缩回。\n**B2F 是限位型：里面有双螺母，允许管子自由伸缩，但到极限位置会死死卡住防拉脱。** 它既吸位移又防拉脱，用在需要留伸缩量的直管段。\n**C2F 是传力型：外面几根长螺杆把两头锁死，一点位移都不吸收。** 它专门把水泵的盲板推力传给管道、保护水泵；把 C2F 当 B2F 用，位移没人吸收，管子会顶坏。\n**安装伸缩器不能顶到死，必须在内部预留伸缩余量。** 夏天一热管子伸长，没余量就直接把伸缩器顶坏，这是季节性高发问题。\n【伸缩件 型式 × 功能 对照表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n钢制套管伸缩接头｜法兰连接、伸缩量大｜泵房、钢管直管段｜吸轴向位移。\nB2F 限位型｜双螺母、到极限锁死防拉脱｜需留伸缩量的直管段｜既吸位移又防拉脱。\nC2F 传力型｜长螺杆锁死、不吸位移｜泵阀连接节点、传盲板推力｜别当 B2F 用。\n多功能法兰连接器（防脱法兰/伸缩法兰接头）｜防脱锁紧环 + 锥形胶圈 + 伸缩套管｜承插与法兰转换｜看锁紧环齐全，缺了防脱失效。\n安装预留｜内部留伸缩余量｜按温度变化预留｜逐档预留量以现行标准与厂家要求核定为准，顶死必坏。\n**【红线】B2F 防拉脱、C2F 传推力，别把 C2F 当 B2F 用；安装必须留余量，不能顶死。**\n落回卡上：把「多功能法兰连接器（防脱法兰/伸缩法兰接头）」「球墨铸铁伸缩节（限位型/传力型）」两张卡的结构组成与状态栏并排看，B2F 为常用主力、C2F 用于泵阀连接节点。\n\n**自测：C2F 和 B2F 伸缩节的关键区别是什么？** 回本课【铸铁伸缩节：B2F与C2F的区别】对照。\n\n**自测：伸缩节安装顶死不留余量会怎样？** 回本课【安装预留】对照。","structure":"结构：大套小，压盖压紧填料或胶圈。钢制伸缩器：法兰连接，吸位移。铸铁B2F：限位型，防拉脱。铸铁C2F：传力型，传推力保水泵。安装：必须预留伸缩余量。\n引导：本课已把吸位移与传推力分开讲透；现场常卡在「C2F 当 B2F 用」；下一步 C34 回到 PE 基础，把口径换算再核一遍。","anchors":[{"name":"多功能法兰连接器（防脱法兰/伸缩法兰接头）","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"球墨铸铁伸缩节（限位型/传力型）","ref":"球墨铸铁伸缩节（限位型/传力型）"}],"pitfall":"【B2F防拉脱，C2F传推力】别把C2F当B2F用，它不吸位移；安装必须留余量，不能顶死。","remark":"—","seq":66,"family":"补偿器与柔性接头","lessonNo":33},{"id":"C28","sub":"XG-01","topic":"防腐与抢修辅材：镁合金牺牲阳极与AB胶","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲地下的防腐与突发抢修。重点讲镁阳极如何保护钢管，以及AB胶在带水带压工况下的应急堵漏原理。","framework":"牺牲阳极｜镁合金电化学保护原理。填包料｜降低电阻的活化剂。AB胶｜双组分混合固化。操作禁忌｜表面清理与混合比例。\n防腐与抢修辅材逐块讲透：牺牲阳极与 AB 胶｜讲机理、讲后果、怎么辨与相邻关系，逐块讲透。\n防腐 / 抢修辅材 核对表｜对象｜要点｜核对动作｜红线，逐行可查，数值以核定为准。\n怎么辨：应急堵漏与永久修复的分界｜按漏点与承压分界，逐行可查，数值以核定为准。\n到货验收：阳极与 AB 胶怎么验｜标识｜电缆｜组分，逐行可查，数值以核定为准。","lecture":"**相邻关系：向上接 C32《伸缩器与铸铁伸缩节》；本板块到此收束。**\n\n**现场情境：钢管埋地要防腐，AB 胶应急止漏时工人没充分混合。** 两种材料各怎么用对立？本课讲。\n\n【牺牲阳极：镁比铁活泼，先烂自己】\n**镁合金牺牲阳极保护钢管，靠的是金属活泼性不同。** 镁比铁活泼、电位更负，和管道连在一起时镁先被腐蚀、把钢管保住，这叫阴极保护。它是“替死鬼”，会越用越薄，埋地后要定期开挖检查、该换就换，换了才继续有效。\n\n【镁合金阳极：替死鬼保护法】\n埋地钢管怎么防腐？用镁合金阳极。因为镁比铁活泼，把镁块用电缆连在钢管上，土壤里的腐蚀会优先吃掉镁块，从而保护钢管。安装时外面要裹上填包料，用来导电和保持活性。\n\n【AB胶（管道修补剂）：应急止漏神器】\n库房里常备的双组分环氧修补胶。A组分是树脂，B组分是固化剂。遇到管道砂眼、法兰轻微渗水，把表面铁锈擦掉，AB胶（管道修补剂）按比例混合均匀，涂在漏点外面，几分钟就能固化变硬，临时堵住漏水。\n【防腐与抢修辅材逐块讲透：牺牲阳极与 AB 胶】\n**埋地钢管用镁合金牺牲阳极防腐，因为镁比铁活泼，连上电缆后土壤里的腐蚀优先吃掉镁块。** 落回卡上：看「镁合金牺牲阳极」卡，打个比方，镁是替钢管挡刀的「替死鬼」。\n**阳极外面要裹填包料，作用是降低接地电阻、保持阳极活性。** 石膏粉、膨润土、无水硫酸钠配的填包料缺了或受潮，阳极效率就往下掉。\n**验收看阳极标识重量与卡面是否一致、表面有无严重氧化变形，电缆长度与焊接片要配套。** 电缆短了或接头不对，现场接不上，防腐回路就断。\n**AB 胶是双组分环氧修补剂：A 组树脂、B 组固化剂，按比例混匀后固化形成封堵层。** 落回卡上：看「AB胶（管道修补剂）」卡，用于管道砂眼、法兰轻微渗水的应急堵漏。\n**涂胶前必须把表面铁锈、油污擦干净，A 和 B 要充分混匀，不然不固化或粘不牢。** 它是应急件、不承力，不能替代哈夫节（堵漏器）或管件。\n【防腐 / 抢修辅材 核对表】\n**把本课知识按「是什么｜该核什么｜防雷」逐行对全，领料前照表核一遍。** 表头顺序：对象｜要点｜核对动作｜红线。\n镁合金牺牲阳极｜电化学保护埋地钢管｜看重量标识、表面氧化｜逐档重量以卡面与现行标准核定为准。\n填包料｜降接地电阻、保活性｜看是否缺失、受潮｜受潮结块效率下降。\n阳极电缆｜连接钢管形成回路｜看长度、焊接片、接头｜短了或接头不对现场接不上。\nAB胶（管道修补剂）｜A 树脂 + B 固化剂混合固化｜清表面、按比例混匀｜只做应急堵漏，不承力。\n用途边界｜小孔砂眼、法兰微渗｜不能替代哈夫节（堵漏器） / 管件｜带压大漏点必须换件，别靠胶。\n**【红线】镁阳极是牺牲自己保护钢管；AB 胶必须 A/B 充分混合、涂前清理表面；它不是结构胶，不能替代管件。**\n落回卡上：把「镁合金牺牲阳极」「AB胶（管道修补剂）」两张卡的组成、执行标准与用途栏并排看，防腐与抢修是两条线。\n\n【怎么辨：应急堵漏与永久修复的分界】\n**AB 胶是临时止血的应急件，不是结构件；能不能用，看漏点大小和承压，不看手边有没有胶。**\n**砂眼、法兰轻微渗水、水压不大，可以清面混匀后临时封堵；带压大漏点、裂纹、接口松脱必须换件或上哈夫节（堵漏器）。**\n**打比方：**AB 胶像创可贴，擦干净、贴得牢才管用；创口大还硬贴，一加压就冲开。\n**另一条线别混：镁合金牺牲阳极管的是「地下钢管慢慢锈」，AB 胶管的是「今天突然漏」。** 一个防，一个堵。\n**落回卡上：**把「镁合金牺牲阳极」「AB胶（管道修补剂）」两张卡的用途栏并排看，防腐与抢修是两条线，别互相顶替。\n【到货验收：阳极与 AB 胶怎么验】\n**到货先分两堆：阳极看重量标识与电缆，AB 胶看双组分是否齐全、是否在期内。**\n1 阳极：核标识重量与卡面一致，表面无严重氧化变形，电缆长度、焊接片、接头配套，填包料不缺不受潮。\n2 填包料：看有无受潮结块，结块了降电阻、保活性的作用就打折，判异常。\n3 AB 胶：A 组树脂与 B 组固化剂必须成对、比例按厂家说明，混匀前别上管；逐档重量、固化时间以卡面与现行标准核定为准，本课不代填。\n4 表面处理：涂胶前铁锈、油污、浮锈要擦净，这是能不能粘住的前提。\n**【红线】阳极电缆不配套、填包料受潮结块、AB 胶单组分或过期，三项任一命中就判异常，不许下沟。**\n**自测：半夜抢修只有 AB 胶，漏点是带压大裂口，你该怎么办？**回上一块的分界，答案是换件或哈夫节（堵漏器），不靠胶。\n\n**自测：镁合金牺牲阳极为什么能保护钢管？** 回本课【镁合金阳极：替死鬼保护法】对照。","structure":"牺牲阳极靠电化学原理保护钢管，填包料降电阻。AB胶是双组分，按比例混合，用于带水带压的应急堵漏。\n引导：本课已把牺牲阳极与 AB 胶讲透；现场常卡在「AB 胶没混匀就涂」；下一步 C29 看户表控制箱。","anchors":[{"name":"镁合金牺牲阳极","ref":"镁合金牺牲阳极"},{"name":"AB胶（管道修补剂）","ref":"AB胶（管道修补剂）"}],"pitfall":"【镁阳极是牺牲自己保护钢管】AB胶必须A和B充分混合；涂胶前必须清理表面油污和浮锈。","remark":"—","seq":67,"family":"辅材·井室·户表集成","lessonNo":34},{"id":"C44","sub":"XG-02","topic":"球铁管件端头逻辑：双盘、双承、盘插与盘承","level":"D3 / L3","d":"D3","l":"L3","positioning":"本课只讲球墨铸铁管件两端端头的组合逻辑和选用边界，不重复C36阀门外观，也不展开断管抢修流程。目标是看两头是法兰、承口还是插口，判断它接阀门还是接直管。","framework":"端头三型｜法兰盘、承口、插口。双盘短管｜两端法兰，接法兰阀门或法兰管。双承短管｜两端承口，接纳两根插口。盘插短管｜一端法兰一端插口。盘承短管｜一端法兰一端承口。盲板｜封法兰口。相邻关系｜与承插弯头、三通端头组合。","lecture":"**相邻关系：向上接 C43《井盖类型与承载标识》；向下接 C45《止回阀形态族谱》。**\n\n**现场情境：断管抢修要接法兰，有人把盘承和盘插拿反了。** 两者怎么分、各接什么？本课讲端头逻辑。\n\n【盘承盘插的法兰标准要一致：不然装不上】\n**带法兰端的转换件（盘承、盘插），其法兰标准（GB/T 9119 或 HG）和螺栓孔距要与配套阀门一致，否则孔对不上、装不上。** 像插头和插座规格要配套，标准不同就是插不进去。落回卡上：看球铁管件卡的法兰端标注，先对标准系列和孔距，再对口径；逐档数值以卡面与现行标准核定为准。\n\n【端头三型：认端头比记名字可靠】\n**球铁管件的两端，无非法兰盘、承口、插口三种。** 带一圈螺栓孔的圆盘是法兰，像喇叭口张开的那个是承口，平平切齐的是插口。\n**先蹲下来看两头，比背「双盘」「盘承」这些名字稳。** 落回卡上：翻「双盘短管」「盘承短管」几张实物图，把三种端头一一指认出来。\n\n【双盘与双承：端头完全相反】\n**双盘短管两头都是法兰，专门接法兰阀门或法兰管，靠螺栓可拆；双承短管两头都是承口，用来同时接纳两根插口，靠胶圈（球墨管承插密封圈）柔性密封。** 一个全是盘、一个全是承，不能互替。\n**为什么这么定：一个是刚性可拆连接，一个是柔性承插连接。** 落回卡上：看「双盘短管」「双承短管」卡的两端特写，方向不同、用途就不同。\n\n【盘插与盘承：跨界过渡的关键】\n**盘插是一端法兰一端插口，盘承是一端法兰一端承口。** 阀门那侧永远是法兰，直管那侧要看剩下的是插口还是承口，才能定用盘承还是盘插。\n**【红线】盘承盘插拿反，现场直接对不上、装不进去，只能停工换件。** 落回卡上：把「盘插短管」「盘承短管」并排看，区别只在承口还是插口那一端。\n\n【盲板：只封法兰口】\n**盲板是一块实心法兰盘，只用来封堵法兰端，不封承口也不封插口。** 它给将来接阀门或接管留一个可拆卸的死角。\n**【易错】拿盲板去堵承口，既密封不住也固定不了。** 落回卡上：看「球墨盲板（法兰盲板）」卡的螺栓孔，孔位说明它只配法兰。\n\n【为什么这么定：可拆与柔性各管一段】\n**法兰靠螺栓、能拆能检修；承插靠胶圈（球墨管承插密封圈）、容许小角度偏转和沉降。** 一条管线往往两种都要，过渡件就是一端法兰一端承插。\n**选件顺序是：先看两端端头 → 定阀门侧法兰 → 定直管侧承插 → 再核对胶圈（球墨管承插密封圈）。** 落回卡上：「承插盘三通」是本组更复杂的组合，先吃透两端再上三端。\n\n【材料锚点 · 落回卡上】\n**「双盘短管」「双承短管」「盘插短管」「盘承短管」「球墨盲板（法兰盲板）」五张卡，端头组合一次认全。** 点开看两端是圆盘、喇叭还是平头，比背名字稳得多。\n**「承插盘三通」是三端的复杂组合，先吃透两端再上三端。** 本课只讲端头逻辑与选用边界，双插短管若平台未列现用卡，一律查替代或报备，绝不凭名发料。\n\n**自测：盘承和盘插分别接什么？** 回本课【盘插与盘承：跨界过渡的关键】对照。\n\n**自测：双承管件能不能接法兰？** 回本课【双盘与双承：端头完全相反】对照。","structure":"主链：看两端→法兰接阀门→承口纳插口→插口进承口→最后匹配相邻管段。\n要点：1 圆盘是法兰；2 喇叭是承口；3 平头是插口；4 双盘接法兰；5 盘承盘插做跨界。\n引导：本课已认端头组合；现场常卡在盘承盘插拿反；下一步看 C45 止回阀族谱。","anchors":[{"name":"双盘短管","ref":"双盘短管"},{"name":"双承短管","ref":"双承短管"},{"name":"盘插短管","ref":"盘插短管"},{"name":"盘承短管","ref":"盘承短管"},{"name":"球墨盲板（法兰盲板）","ref":"球墨盲板（法兰盲板）"},{"name":"承插盘三通","ref":"承插盘三通"}],"pitfall":"【盘承盘插别拿反】盘承是承口接直管，盘插是插口插直管；双承不接法兰。","remark":"—","seq":68,"family":"XG-02 端头密封与材质","lessonNo":10},{"id":"C45","sub":"XG-02","topic":"止回阀形态族谱：旋启、升降、对夹与静音缓闭","level":"D3 / L3","d":"D3","l":"L3","positioning":"本课只讲止回阀形态族谱和辨识边界，不重复C36无手轮初筛，也不展开水锤计算。目标是看阀瓣运动方式分清旋启、升降、对夹和静音缓闭。","framework":"旋启式｜摇板绕铰链翻转。升降式｜阀瓣沿轴线直上直下。对夹式｜薄型双瓣夹在两法兰间。静音缓闭｜弹簧辅助，末段缓闭。金属瓣与橡胶瓣｜密封与快关差异。相邻关系｜与泵出口、水表下游配套。止回阀四类形态主链｜阀瓣动作→安装位置→防水锤。","lecture":"**相邻关系：向上接 C44《球铁管件端头逻辑》；向下接 C46《同口径假象》。**\n\n**现场情境：停泵时水锤把泵打坏了，现场止回阀选型没考虑缓闭。** 四类止回阀怎么分？本课讲形态族谱。\n\n【旋启式：像一扇铰链门】\n**旋启式的摇板绕铰链翻转，水流正冲就推开、倒流就压回阀座。** 像一扇只能朝一个方向开的弹簧门，流阻小、适合大口径。\n**金属瓣耐压耐温，橡胶瓣行程短、关得快、水锤小。** 落回卡上：看「旋启式止回阀（金属瓣/橡胶瓣）」卡的摇板与铰链，先认它怎么动。\n\n【升降式：阀瓣直上直下】\n**升降式阀瓣沿阀体轴线上下走，靠导向筋定位，密封严但水阻略大。** 像电梯沿着导轨升降，路径直、密封面贴合好。\n**【易错】它阻力偏大，别图密封好就乱上大口径总管。** 落回卡上：看「升降式止回阀」卡的立式阀体与中间导向，和旋启的斜摇板一眼分得开。\n\n【对夹式与静音缓闭：省空间与防水锤】\n**对夹式很薄，双瓣夹在两片法兰中间，省空间；静音缓闭带弹簧阻尼，先快关大半、末段再慢慢合上。** 一个省的是长度，一个削的是水锤。\n**【红线】对夹式装反方向，水根本顶不开。** 落回卡上：看「对夹碟式止回阀」「静音式（缓闭）止回阀」卡的流向箭头，方向和厚度都是线索。\n\n【为什么这么定：停泵水锤会打坏泵】\n**泵出口突然停泵，水柱倒回来撞上正在关的阀瓣，就是一记水锤。** 关得太慢倒流冲击泵，关得太猛管子震响，缓闭就是在这两头找平衡。\n**【红线】选错形态不是漏不漏，是可能打坏叶轮和泵座。** 落回卡上：本课只讲辨识与水锤方向，具体防护按设计复核。\n\n【相邻关系：装在哪比长什么样更关键】\n**止回阀常守在泵出口、水表下游，挡的都是倒流。** 落回卡上：「黄铜立式/卧式止回阀」是户内小口径的一支，原理同族、场合不同。\n**再往前一步：泵出口常是「止回阀 + 闸阀 + 压力表」成组出现，各有各的活。** 止回挡倒流、闸阀做截断、压力表看压力，别把相邻件的结论串到本课这一件上。\n**认课次序是：C36 认出无手轮 → 这课分清阀瓣怎么动 → 再定装哪。** 把「动法」和「位置」两件事分开，就不会只记外形。\n\n【材料锚点 · 落回卡上】\n**「旋启式止回阀（金属瓣/橡胶瓣）」「升降式止回阀」「对夹碟式止回阀」「静音式（缓闭）止回阀」四张卡，按阀瓣怎么动排一遍。** 摇板翻转、直上直下、薄双瓣、带弹簧缓闭，动法不同、场合不同。\n**「黄铜立式/卧式止回阀」是户内小口径一支，原理同族。** 泵出口水锤防护按设计复核，本课只讲辨识与方向；对夹式装反，水根本顶不开。\n\n【结构关联：止回阀四类形态的一条主链】\n**旋启、升降、对夹、静音缓闭不是四个并列名词，是「阀瓣怎么动 → 装在哪 → 防水锤能力」一条链。** 旋启靠阀瓣绕轴翻、升降靠阀瓣上下走、对夹薄片夹在两法兰间、静音缓闭靠缓闭机构消水锤。\n**对照：泵房出口要防水锤先想静音缓闭，空间紧凑先想对夹，大口径干管常见旋启。** 错在只按外形挑，不看安装位置和水锤条件。\n落回卡上：把四类卡的阀瓣与连接方式并排对一遍。\n\n**自测：对夹式止回阀安装时要特别注意什么？** 回本课【对夹式与静音缓闭：省空间与防水锤】对照。\n\n**自测：为什么大口径不宜用升降式止回阀？** 回本课【升降式：阀瓣直上直下】对照。","structure":"主链：看阀瓣运动→旋启翻转、升降直落、对夹双瓣、静音带弹簧→再匹配泵出口。\n要点：1 旋启像门；2 升降直上直下；3 对夹薄双瓣；4 静音带缓闭；5 泵出口重点防水锤。\n引导：本课已认止回族谱；现场常卡在对夹方向装反；下一步看 C46 同口径假象。\n主链：阀瓣怎么动 → 装在哪 → 防水锤能力，一条链串四类。\n会对照：泵房防水锤想静音缓闭、紧凑空间想对夹。","anchors":[{"name":"旋启式止回阀","ref":"旋启式止回阀（金属瓣/橡胶瓣）"},{"name":"升降式止回阀","ref":"升降式止回阀"},{"name":"对夹碟式止回阀","ref":"对夹碟式止回阀"},{"name":"静音式（缓闭）止回阀","ref":"静音式（缓闭）止回阀"},{"name":"黄铜立式/卧式止回阀","ref":"黄铜立式/卧式止回阀"}],"pitfall":"【对夹式看方向】静音缓闭不是普通止回；升降式阻力大，别乱上大口径。","remark":"—","seq":69,"family":"XG-02 端头密封与材质","lessonNo":11},{"id":"C46","sub":"XG-02","topic":"同口径假象：DN与De、Φ的跨管材换算陷阱","level":"D3 / L3","d":"D3","l":"L3","positioning":"本课只讲DN公称直径与PE的De、钢管和衬塑的Φ、球铁外径之间的换算陷阱，不重复C35外观，也不展开压力等级计算。目标是看到图纸DN，能按管材说出实物该看哪个外径。","framework":"DN含义｜公称直径，名义值，不等于内径。PE标识｜De实际外径，如DN100对应De110。钢管标识｜Φ外径，DN100常见Φ114。衬塑标识｜基体钢管Φ，DN100常见Φ114。球铁标识｜DN100外径约Φ118。测量禁忌｜不能量内径去对DN。相邻关系｜与PN、SDR、S系列分开。跨材质同 DN 外径对照表｜DN25、DN50、DN100、DN150 及以上四档怎么对。","lecture":"**相邻关系：向上接 C45《止回阀形态族谱》；向下接 C47《蝶阀密封结构》。**\n\n**现场情境：同一张图纸写 DN100，现场 PE 是 De110、钢管是 Φ114。** 为什么同 DN 却不同外径？本课破这个执念。\n\n【DN 不是内径：先破这个执念】\n**DN 是公称直径，一个名义尺寸，既不等于实际内径，也不保证各管材外径一致。** 它像鞋码，只是个便于系统配套的号，不是拿卡尺量出来的长度。\n**【红线】拿卡尺量内径去对图纸 DN，是外行做法，一量一个错。** 落回卡上：本课几张管材卡各标各的外径，先接受「同名不同径」这件事。\n\n【PE 看 De：DN100 常对 De110】\n**PE 管喷码写的是 De，也就是实际外径；图纸 DN100 的 PE 管，实物常见 De110。** 壁厚一变内径就变，但外径按 De 走，配套管件也按 De 选。\n**为什么用 De：塑料管靠外径定系列，热熔承插都看外径配合。** 落回卡上：看「PE给水管」卡的 De 标注，别把 De110 当成 DN110 去领法兰。\n\n【钢管衬塑看 Φ，球铁看外径】\n**钢管、衬塑基体按 Φ 外径标，DN100 常见 Φ114；球铁 DN100 外径约 Φ118。** 同样叫 DN100，三种材质三套外径体系。\n**【红线】同 DN 不同材质，管件不能混用，承插插不进、法兰对不上。** 落回卡上：把「衬塑复合管」「球墨铸铁管」「直缝焊接钢管」三张卡的外径并排看，差别就出来了。\n\n【测量禁忌：别量内径、别跨材质套】\n**现场验收要读管身喷码和卡面外径标准，不是拿卷尺比内径，更不是拿钢管的 Φ 去套 PE 的 De。** 一步错，后面整段配套都错。\n**外径数值只作辨识示例，实物一律以喷码和现行标准为准，平台不代填。** 落回卡上：核对喷码、外径、管件三样是否同一体系。\n\n【相邻关系：和 PN、SDR、S 系列分开】\n**DN 管「名义口径」，PN 管「公称压力」，SDR、S 系列管「壁厚」，是三组不同的坐标。** 你先把口径这一组理清，别的组才不会串。\n**同 DN 还要再对压力等级，才谈得上选管。** 落回卡上：本课只破口径假象，压力与壁厚按各自标准另查，不代为下结论。\n\n【材料锚点 · 落回卡上】\n**「PE给水管」「衬塑复合管」「球墨铸铁管」「直缝焊接钢管」「螺旋缝焊接钢管」五张卡，外径标识各写各的。** 点开比喷码：PE 写 De、钢与衬塑写 Φ、球铁写外径，同叫 DN100 数值并不同。\n**外径数值只作辨识示例，实物一律以管身喷码和现行标准为准。** 平台不代填数值；管件必须和管材同一外径体系配套，跨材质混用必然插不进或对不上。\n\n【跨材质同 DN 外径对照表：常用档怎么对】\n**把「同一个 DN、不同管材各自该看哪个外径」并成一张表，领料时先按材质找列。** 表头顺序：DN｜PE 看 De｜钢管、衬塑看 Φ｜球铁看外径｜识别要点；\n逐档精确外径以管身喷码、材料卡与现行标准核定，本课不代填。\nDN25｜PE 看 De｜钢管、衬塑看 Φ｜球铁看外径｜先判材质再找列，别一上来就量。\nDN50｜PE 看 De｜钢管、衬塑看 Φ｜球铁看外径｜衬塑此档正处丝接与沟槽交界。\nDN100｜PE 常对 De110｜钢衬常对 Φ114｜球铁约 Φ118｜三套数值并排，最容易混的一档（示例值，非标准数值）。\nDN150 及以上｜按各卡标识｜按各卡标识｜按各卡标识｜主干管与设备接口，按设计选。\n**【红线】同 DN 不同材质外径不同，管件必须和管材同一外径体系配套，跨材质混用必然插不进或对不上。**\n落回卡上：把「PE给水管」「衬塑复合管」「球墨铸铁管」「直缝焊接钢管」四张卡并排，先认清各写 De 还是 Φ。\n**自测：单子写 DN100，架上 PE、钢管、球铁三种管都印 DN100，你按什么把它们分开？** 回本课【跨材质同 DN 外径对照表】找 DN100 那一行。\n\n**自测：同 DN 的 PE、钢管、球铁管，为什么外径不一样？** 回本课【PE 看 De：DN100 常对 De110】对照。","structure":"主链：图纸DN→判断管材→PE看De、钢衬看Φ、球铁看外径→最后核对喷码和管件。\n要点：1 DN是名义值；2 不能量内径；3 PE DN100常见De110；4 钢衬DN100常见Φ114；5 球铁DN100约Φ118。\n引导：本课已破同口径假象；现场常卡在PE与钢管外径混用；下一步看 C47 蝶阀密封结构。\n查全表：同 DN 先按材质找列，PE 看 De、钢衬看 Φ、球铁看外径。\n记红线：跨材质管件不混用，数值以喷码、卡面、现行标准核定为准。","anchors":[{"name":"PE给水管","ref":"PE给水管"},{"name":"衬塑复合管","ref":"衬塑复合管"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"直缝焊接钢管","ref":"直缝焊接钢管"},{"name":"螺旋缝焊接钢管","ref":"螺旋缝焊接钢管"}],"pitfall":"【DN不等于内径】PE看De，钢衬看Φ，球铁看外径；不同材质同DN不能混管件。 【同 DN 逐档外径以现行标准核定】DN100 的 De110 / Φ114 / Φ118 为辨识示例，不作标准数值使用。","remark":"—","seq":70,"family":"XG-02 端头密封与材质","lessonNo":12},{"id":"C47","sub":"XG-02","topic":"蝶阀密封结构：中线软密封与偏心硬密封","level":"D3 / L3","d":"D3","l":"L3","positioning":"本课只讲蝶阀中线软密封与偏心硬密封的结构差异和适用边界，不重复C36蝶阀外形，也不展开执行器控制。目标是看轴位置和阀座说清为什么高压高温不能用中线软密封凑合。","framework":"中线结构｜阀杆在蝶板中心，橡胶阀座过盈。软密封｜EPDM等橡胶，常温清水零泄漏。双偏心｜开启瞬间脱离阀座。三偏心｜锥形金属密封，楔紧切断。硬密封｜多层不锈钢或硬质合金，耐高温高压。相邻关系｜电动蝶阀是在阀体上加执行器。","lecture":"**相邻关系：向上接 C46《同口径假象》；向下接 C48《补偿器三类辨识》。**\n\n**现场情境：高压场合有人选了中线软密封蝶阀，说偏心只是外观噱头。** 对吗？本课讲密封结构取舍。\n\n【截止阀低进高出：装反关不严、密封面被冲】\n**截止阀阀体有流向，必须“低进高出”安装：水从阀瓣下方进、上方出。** 装反了关闭困难、密封面被冲刷，装前先看阀体上的流向箭头。像单向门，方向装反就推不动。落回卡上：看截止阀卡的流向箭头，安装前先对准进出方向。\n\n【闸阀不能当调节阀：半开很快内漏】\n**闸阀只能全开全关，不能长期半开节流：半开时闸板被高速水流冲刷出沟槽，很快内漏；要节流得用截止阀。** 像闸门只适合全开全关，半吊着会被水冲坏。落回卡上：把闸阀和截止阀两张卡并排看，一个管通断、一个管调节，别混用。\n\n【中线软密封：轴在正中、靠橡胶挤】\n**中线蝶阀的阀杆穿过蝶板正中心，靠 EPDM 橡胶阀座过盈挤压密封。** 像把一块圆饼按进略小的橡胶圈里，常温清水能做到零泄漏，启闭也轻。\n**代价是蝶板全程蹭着阀座转，橡胶怕高温、也磨得快。** 落回卡上：看「中线（软密封）蝶阀」卡的中心阀杆和橡胶衬里，先认软密封。\n\n【双偏心、三偏心：为的是脱离摩擦】\n**双偏心让蝶板一开启就先脱离阀座，减少刮擦；三偏心把密封面做成锥形，关到底靠楔紧实现金属对金属密封。** 偏心不是外形噱头，是让密封面少磨、耐得住高温高压。\n**为什么这么定：中线全程挤压，偏心只在最后一刻楔紧。** 落回卡上：看「偏心蝶阀」卡的偏置阀杆位置，轴不在正中就是线索。\n\n【软硬边界：压力温度说了算】\n**软密封适合常温低压清水，硬密封（多层不锈钢或硬质合金）耐高温高压、也能扛微量颗粒。** 橡胶在高温下会硬化失效，金属硬密封才顶得住。\n**【红线】高压泵房错用中线软密封，橡胶可能被击穿或被磨损，阀很快内漏。** 落回卡上：本课只讲结构差异，压力温度边界按设计文件与卡面核对。\n\n【电动蝶阀：驱动变了、阀体没变】\n**电动蝶阀只是在阀体上加执行器，阀体本身仍是中线或偏心、仍是软密封或硬密封。** 你先认阀体密封结构，再看它带不带电机。\n**【红线】别因为看到电机就当成另一种阀。** 落回卡上：「电动蝶阀」是驱动方式，判断耐温耐压还得回到阀座材质。\n\n【相邻关系：本课不重复外形】\n**C36 讲的是扁圆阀体认蝶阀，这课往里走一层，看轴位置和阀座软硬。** 同一只阀，先断大类、再断密封。\n**选型的次序是：压力温度 → 软硬密封 → 中线或偏心 → 最后才谈手动还是电动。** 落回卡上：把三张蝶阀卡按这条次序排，逻辑就顺了。\n\n【材料锚点 · 落回卡上】\n**「中线（软密封）蝶阀」「偏心蝶阀」「电动蝶阀」三张卡，阀杆位置和阀座软硬是分界。** 点开看阀杆是不是穿过蝶板正中、阀座是橡胶还是金属，再判断耐温耐压。\n**电动只是驱动方式，判断边界还得回到阀体密封。** 压力温度边界按设计文件与卡面核对，本课只讲结构差异，不代为下选型结论。\n\n**自测：双偏心、三偏心蝶阀到底为了什么？** 回本课【双偏心、三偏心：为的是脱离摩擦】对照。\n\n**自测：高压场合为什么不宜用中线软密封？** 回本课【软硬边界：压力温度说了算】对照。","structure":"主链：看阀杆位置→中线或偏心→看阀座软硬→最后匹配压力温度。\n要点：1 中线轴在中心；2 软密封靠橡胶挤压；3 偏心开启脱离阀座；4 三偏心金属楔紧；5 高压高温别用中线软密封。\n引导：本课已分软硬密封；现场常卡在只看手柄不看阀座；下一步看 C48 补偿器三类辨识。","anchors":[{"name":"中线（软密封）蝶阀","ref":"中线（软密封）蝶阀"},{"name":"偏心蝶阀","ref":"偏心蝶阀"},{"name":"电动蝶阀","ref":"电动蝶阀"}],"pitfall":"【高压别用中线软密封】偏心不是外形噱头；电动蝶阀先看阀体密封再看电机。","remark":"—","seq":71,"family":"XG-02 端头密封与材质","lessonNo":13},{"id":"C48","sub":"XG-02","topic":"补偿器三类辨识：橡胶接头、波纹管与铸铁伸缩节B2F/C2F","level":"D3 / L3","d":"D3","l":"L3","positioning":"本课只讲可曲挠橡胶接头、轴向波纹管补偿器和球墨铸铁伸缩节B2F/C2F的辨识与边界，不重复C37辅材，也不展开推力计算。目标是看结构和拉杆说清谁减震、谁吸位移、谁传推力。","framework":"橡胶接头｜橡胶球体加法兰，减震降噪。轴向波纹管｜不锈钢波纹加限位拉杆，吸轴向位移。横向/铰链型｜大拉杆或铰链板，吸横向或角向。B2F限位型｜伸缩管加限位双螺母，防拉脱。C2F传力型｜传力螺杆锁死，传盲板推力。相邻关系｜与固定支架、泵阀节点配套。","lecture":"**相邻关系：向上接 C47《蝶阀密封结构》；向下接 C49《倒流防止器类型与泄水口边界》。**\n\n**现场情境：有人把 C2F 伸缩节当 B2F 用，还把波纹管拉杆当装饰拆掉。** 后果是什么？本课讲三类补偿件。\n\n【橡胶接头装限位防脱：内压会把自己顶脱】\n**橡胶软接头通内压后会把自己顶脱，必须装限位杆或防脱装置，否则爆管漏水。** 像气球充气后口子会往外挣，得有绳子拉住。落回卡上：看「可曲挠橡胶接头」卡的配套限位件，安装时限位杆要装上、调好行程。\n\n【橡胶接头：吸振不吸大位移】\n**可曲挠橡胶接头中间是个橡胶球、两头法兰，靠球体变形吸收振动、噪声和微量位移。** 像给管道垫了个软关节，泵一抖它先扛。给水默认 EPDM、含油选 NBR。\n**【红线】它不承受大的轴向热伸长，硬拿它当补偿器会被拉开。** 落回卡上：看「可曲挠式橡胶接头」卡的橡胶球和限位螺栓，先认清它管的是振、不是伸长。\n\n【波纹管：拉杆不是装饰】\n**轴向波纹管中间是不锈钢波纹，旁边几根限位拉杆替它扛住内压推力。** 波纹像手风琴的风箱，专吸直管的轴向热伸长；横向型用大拉杆、铰链型成组用，吸的是横向或角向。\n**【红线】拉杆不能随便拆，拆了内压推力会把波纹拉失稳。** 落回卡上：看「轴向型波纹管补偿器」卡的波纹与拉杆，两者是一套。\n\n【B2F 限位型：防拉脱】\n**B2F 是限位伸缩节，伸缩管在行程内滑动，到极限由双螺母锁住不让它被拉脱。** 它吸位移，但给位移设了上限，像抽屉带了个挡块。\n**C2F 传力型则相反：用传力螺杆把两端锁死，一点位移不吸，专门把泵阀盲板的推力传到管道上。** 落回卡上：看「球墨铸铁伸缩节（限位型/传力型）」卡，有螺杆锁死的是 C2F。\n\n【为什么这么定：用反了会坏设备】\n**把 C2F 当 B2F 用，热伸长没处释放，管子顶坏支架；把 B2F 当 C2F 用，泵阀推力全压到设备接口上。** 一个要能伸缩、一个要能传力，方向正好相反。\n**【红线】三者按「吸振 / 吸位移 / 传推力」分工，不能凭都带法兰就混发。** 落回卡上：先看中间是橡胶球还是波纹管、再看有无拉杆和螺杆。\n\n【相邻关系：都要配固定支架】\n**补偿器不是单独装的，它和固定支架、泵阀节点一起决定推力往哪走。** 落回卡上：本课只讲三类辨识，补偿量按设计温度与安装温度复核。\n**认课次序：先分中间件材质 → 再看拉杆/螺杆 → 最后定它吸什么或传什么。** 别只记型号字母。\n\n【材料锚点 · 落回卡上】\n**「可曲挠式橡胶接头」「轴向型波纹管补偿器」「球墨铸铁伸缩节（限位型/传力型）」三张卡，按吸振／吸位移／传推力分工。** 点开看中间是橡胶球还是波纹、有没有拉杆和传力螺杆。\n**三者都带法兰，不能凭这点混发；拉杆和螺杆都不能随便拆。** 补偿量按设计温度与安装温度复核，本课只讲三类辨识，不代为下推力计算。\n\n**自测：B2F 和 C2F 的关键差别是什么？** 回本课【B2F 限位型：防拉脱】对照。\n\n**自测：波纹管补偿器的拉杆能不能随便拆？** 回本课【波纹管：拉杆不是装饰】对照。","structure":"主链：看中间是橡胶球还是波纹管→看有无拉杆→看限位或传力→最后匹配泵阀或直管。\n要点：1 橡胶球减震；2 波纹管吸轴向；3 B2F限位防拉脱；4 C2F传力锁死；5 拉杆不能乱拆。\n引导：本课已分三类补偿；现场常卡在C2F当B2F；下一步看 C49 倒流防止器。","anchors":[{"name":"可曲挠式橡胶接头","ref":"可曲挠式橡胶接头"},{"name":"轴向型波纹管补偿器","ref":"轴向型波纹管补偿器"},{"name":"球墨铸铁伸缩节（限位型/传力型）","ref":"球墨铸铁伸缩节（限位型/传力型）"}],"pitfall":"【C2F不吸位移】B2F防拉脱，C2F传推力；波纹管拉杆别乱拆。","remark":"—","seq":72,"family":"XG-02 端头密封与材质","lessonNo":14},{"id":"C49","sub":"XG-02","topic":"倒流防止器类型与泄水口边界：减压、低阻力与双止回","level":"D3 / L3","d":"D3","l":"L3","positioning":"本课只讲倒流防止器三类类型辨识和泄水口安装边界，不重复C36阀门外观，也不展开水质风险评估。目标是看阀腔和泄水口说清防护等级与不能泡污水。","framework":"减压型｜双止回加减压装置和泄水腔，防护最高。低阻力型｜优化流道，水损较低，防护次之。双止回型｜仅两道止回，无泄水，防护最低。泄水口｜中腔泄水，必须能排走。安装边界｜水平安装，前端Y型过滤器。相邻关系｜与生活水、消防、中水边界配套。","lecture":"**相邻关系：向上接 C48《补偿器三类辨识》；向下接 C50《橡胶材质相容》。**\n\n**现场情境：倒流防止器的泄水口装在可能被污水淹到的低处。** 这样行不行？本课讲防护等级与边界。\n\n【三类防护：看有没有中腔泄水】\n**减压型是双止回加减压装置再带中腔泄水，防护最高；低阻力型优化流道、水损低，防护次之；双止回型只有两道止回、没有泄水，防护最低。** 分水岭就是那个泄水腔。\n**先找中腔和泄水口，再判类型。** 落回卡上：翻「减压型倒流防止器」「低阻力倒流防止器」「双止回阀型倒流防止器」三张卡，看阀体段数。\n\n【泄水口边界：必须排得走】\n**中腔泄水阀在压力失衡时会自动排水，把可能倒灌的水放掉。** 泄水口必须通畅排走，不能泡在污水坑、也不能接进下水道。\n**【红线】泄水口泡在污水里，脏水可能顺着它倒灌进上游饮用水。** 这是防污染装置，不是排水口，装反了反而成了污染源。\n\n【为什么这么定：高危边界不能降级】\n**生活饮用水与消防水、中水交界是高危边界，一旦倒流就是水质事故。** 双止回没有泄水，只能用于低风险隔离；减压型才用于高危点。\n**【红线】把双止回型降级凑合到高危边界，省一个阀、冒一整条管的水质风险。** 落回卡上：类型与适用边界按卡面和标准原文核对，本课不代为下结论。\n\n【安装配套：过滤器与水平安装】\n**倒流防止器前端要装 Y 型过滤器，挡住泥沙别卡住止回阀芯；阀体必须水平安装，泄水口朝下能排。** 这两件是它正常工作的前提。\n**前置过滤器脏堵不清理，阀芯关不严，防护就形同虚设。** 落回卡上：看「法兰Y型过滤器」卡，它和倒流防止器是配套件。\n\n【相邻关系：不是普通止回阀】\n**倒流防止器和 C45 的止回阀都挡倒流，但前者带泄水腔、是防污染级，后者只挡水回流。** 别因为都无手轮就归成一类。\n**【红线】用有无手轮判类型，会把防污染装置当普通阀放过。** 落回卡上：本课只辨识类型与泄水边界，标准版本采购时确认、安装按设计。\n\n【材料锚点 · 落回卡上】\n**「减压型倒流防止器」「低阻力倒流防止器」「双止回阀型倒流防止器」三张卡，数阀体段数、找中腔泄水口。** 有减压装置和泄水腔的防护最高，只有两道止回、无泄水的最低。\n**「法兰Y型过滤器」是必配前置件，点开看它挡泥沙护阀芯。** 标准版本采购时确认、安装按设计；本课只辨识类型与泄水边界，不代为下水质风险结论。\n\n**自测：泄水口泡在污水里有什么后果？** 回本课【泄水口边界：必须排得走】对照。\n\n**自测：双止回型能不能用在高危污染边界？** 回本课【为什么这么定：高危边界不能降级】对照。","structure":"主链：看有无中腔泄水和减压装置→分减压、低阻力、双止回→再看泄水口去向→最后看过滤器。\n要点：1 减压防护最高；2 低阻力水损低；3 双止回无泄水；4 泄水口不能泡污水；5 前端配过滤器。\n引导：本课已分类型与泄水边界；现场常卡在双止回降级使用；下一步看 C50 橡胶材质相容。","anchors":[{"name":"减压型倒流防止器","ref":"减压型倒流防止器"},{"name":"低阻力倒流防止器","ref":"低阻力倒流防止器"},{"name":"双止回阀型倒流防止器","ref":"双止回阀型倒流防止器"},{"name":"法兰Y型过滤器","ref":"法兰Y型过滤器"}],"pitfall":"【双止回不能高危降级用】泄水口别泡污水；倒流防止器不是普通止回阀。","remark":"—","seq":73,"family":"XG-02 端头密封与材质","lessonNo":15},{"id":"C50","sub":"XG-02","topic":"橡胶材质相容：给水EPDM与耐油NBR","level":"D3 / L3","d":"D3","l":"L3","positioning":"本课只讲橡胶密封件EPDM与NBR的材质相容和辨识边界，不重复C37胶垫胶圈轮廓，也不展开橡胶配方。目标是看介质说清给水默认EPDM，含油介质选NBR。","framework":"EPDM特性｜耐水、耐温、耐老化，怕油。NBR特性｜耐油，适合含油污水。给水默认｜胶垫、胶圈、橡胶接头默认EPDM。含油场景｜油污、含油工业水选NBR。外观边界｜黑色橡胶外观难分，必须看标识和卡面。相邻关系｜与生料带、法兰垫片配套。","lecture":"**相邻关系：向上接 C49《倒流防止器类型与泄水口边界》；向下接 C51《断管接口组合辨识》。**\n\n**现场情境：含油介质管路上用了给水 EPDM 胶圈，因为都是黑色看着差不多。** 会怎样？本课讲材质相容。\n\n【EPDM 耐候怕油、NBR 耐油怕臭氧：别用反】\n**EPDM 三元乙丙耐臭氧、耐候，适合户外给水，但不耐油；NBR 丁腈耐油，却不耐臭氧和阳光，不宜长期户外使用。** 一句话记：户外清水用 EPDM，接触油用 NBR，两者别用反。像防晒衣和耐油手套，各有各的场合。落回卡上：把 EPDM、NBR 两张材质卡并排看，先分清是怕油还是怕晒。\n\n【EPDM：给水的默认，怕油】\n**EPDM 耐水、耐温、耐老化，是给水胶垫（法兰橡胶垫片）、胶圈、橡胶接头的默认材质。** 但它极怕矿物油，沾上机油会溶胀、发黏、失去弹性，像泡发的橡皮。\n**【红线】含油介质用了 EPDM，几天就可能膨胀失效、接口漏水。** 落回卡上：翻「胶垫（法兰橡胶垫片）」「胶圈（球墨管承插密封圈）」卡，材质字段默认写 EPDM。\n\n【NBR：耐油，但给水卫生另论】\n**NBR 耐油，适合含油污水和工业介质，遇油不溶胀。** 它是给含油工况准备的，不是给生活饮用水的通用升级。\n**给水场景错用 NBR，未必满足饮用水卫生要求。** 落回卡上：看「可曲挠式橡胶接头」卡的材质选项，含油工况才点 NBR。\n\n【怎么辨：黑色橡胶别凭眼睛】\n**两种橡胶都是黑的，外观几乎分不出，必须看包装标识、材料卡材质字段和厂家标记。** 像两瓶一样的黑墨水，标签才是唯一凭据。\n**【红线】不能因为「都是黑色、手头正好有」就混用。** 落回卡上：本课只教「看标识」这一条，材质以卡面和标准原文为准。\n\n【为什么这么定：密封失效不小事】\n**密封件藏在法兰和承口里，一旦老化，拆开返工要停水、要重新紧固，代价远超一块垫片。** 介质相容要排在价格和「手头有没有」前面。\n**存放也要避光、避油、避高温，橡胶最怕这三样。** 落回卡上：「生料带（聚四氟乙烯密封带）」是螺纹密封，和橡胶垫片的介质相容是两回事，别混。\n\n【相邻关系：材质是一张卡的字段】\n**胶垫（法兰橡胶垫片）、胶圈、橡胶接头是三种件，EPDM / NBR 是它们的材质选项，两个维度别叠成一件事。** 落回卡上：先认件型，再读材质字段。\n**本课讲的是「介质选材质」，C37 讲的是「形状认件」，正好接上。** 认件和选材各归各，现场才不会拿错。\n\n【材料锚点 · 落回卡上】\n**「可曲挠式橡胶接头」「胶垫（法兰橡胶垫片）」「胶圈（球墨管承插密封圈）」三张卡，材质字段默认 EPDM。** 点开读材质、卫生性能和适用介质，含油工况才切 NBR。\n**「生料带（聚四氟乙烯密封带）」是螺纹密封，和橡胶垫片的介质相容是两回事。** 黑色橡胶外观分不出，一律以包装标识、卡面字段和厂家标记为准。\n\n**自测：给水 EPDM 胶圈遇到油会怎样？** 回本课【EPDM：给水的默认，怕油】对照。\n\n**自测：黑色橡胶件怎么正确辨认材质？** 回本课【怎么辨：黑色橡胶别凭眼睛】对照。","structure":"主链：先看介质是否含油→含油选NBR→给水默认EPDM→最后看标识和卡面。\n要点：1 EPDM耐水怕油；2 NBR耐油；3 给水默认EPDM；4 黑色外观难辨；5 必须看标识。\n引导：本课已能按介质分 EPDM 与 NBR；现场常卡在黑色橡胶凭眼看混用；下一步看 C51 断管接口组合。","anchors":[{"name":"可曲挠式橡胶接头","ref":"可曲挠式橡胶接头"},{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"生料带（聚四氟乙烯密封带）","ref":"生料带（聚四氟乙烯密封带）"}],"pitfall":"【EPDM怕油】含油介质别用给水EPDM；黑色橡胶不能凭眼看，必须看标识。","remark":"—","seq":74,"family":"XG-02 端头密封与材质","lessonNo":16},{"id":"C55","sub":"XG-03","topic":"PPE与环境风险辨识：安全帽、反光衣、井盖缺失与路面塌陷","level":"D3 / L3","d":"D3","l":"L3","positioning":"本课只讲分得清：PPE穿戴对不对，井盖缺失和路面塌陷先围挡还是先拍照。不展开PPE采购标准和塌陷结构计算。目标是在夜间和道路现场先保护自己、再围挡上报。","framework":"安全帽｜帽壳、帽衬、下颚带；正确佩戴与错误佩戴。反光衣｜夜间和道路可见性；下车前穿。井盖缺失｜洞口坠落；只拍照 vs 先围挡。路面塌陷｜下方空洞、二次塌陷；不站上去试。围挡与上报｜能挡人挡车、拍照定位、上报守交。相邻与边界｜PPE保护人、围挡保护区域；不替代设计复核。","lecture":"**相邻关系：向上接 C54《有限空间为什么危险》；向下接 C56《有限空间作业顺序与盲目施救判》。**\n\n**现场情境：路上井盖缺失，有人只拍了张照就走；还有人站上塌陷路面去试。** 正确做法是什么？本课讲环境风险。\n\n【反光衣靠逆反射条：不是普通工作服】\n**反光衣的可见性来自玻璃微珠逆反射条，反射条脱落、脏污就失效，破损要及时更换；它不是普通工作服。** 夜里车灯一照，逆反射条把光原路弹回司机眼里，才看得见人。落回卡上：看「反光衣」卡的反射条位置，穿之前先检查条子是否完整、干净。\n\n【安全帽】\n**安全帽要戴正并系好下颚带。** 帽壳挡坠物，帽衬缓冲，下颚带固定。**只扣在头上不系带等于没戴牢。** 低头或碰撞时容易脱落。**安全帽不能反戴或改装。** 帽衬和帽壳要配套。\n**夜间作业安全帽还要配合反光衣。** 可见性靠反光衣，不靠帽子颜色。**本课只讲穿戴要点，不展开采购标准。** 配置按企业制度。\n\n【反光衣】\n**反光衣用于夜间和道路作业。** 它提高人员可见性。**下车前先穿反光衣。** 不能到了路中间再穿。**反光衣不是普通工作服。** 它不能代替围挡和警示。**反光衣破损或反光条脱落要更换。\n** 否则夜间效果下降。**与围挡关系：人可见，区域也要可见。** 两者配合。\n\n【井盖缺失】\n**井盖缺失首先是洞口坠落风险。** 行人、车辆、作业人员都可能掉入。**不能只拍照发群就走。** 拍照是上报，不是现场控制。**先设临时围挡和警示。** 围挡要能挡人挡车。**砖头虚盖是偷懒。\n** 看着盖住了，坑在行人一踩就翻。**上报要带位置和参照物。** 守到交接再离开。\n\n【路面塌陷】\n**路面塌陷可能下方有空洞。** 表面看着硬，下面可能空。**不要站上去踩试。** 二次塌陷会伤人。**先围挡、疏散、上报。** 夜间加反光警示。**塌陷和井盖缺失都不是材料外观问题。\n** 先控制现场，再查原因。**与井盖关系：井盖周边塌陷可能连井座一起下沉。** 不要只复位井盖。\n\n【围挡与上报】\n**围挡要能挡人挡车。** 锥桶太轻时加围栏或警示带。**正确做法是围挡→拍照定位→上报→守交。** 只拍照不围挡是偷懒。**上报说清位置、风险类型、已做措施。** 不擅自下结论。\n**夜间要加反光警示。** 否则远处看不见。**与C56关系：C56讲井盖打开后的作业顺序。** 本课先认环境风险。\n\n【相邻与边界】\n**PPE保护人，围挡保护区域。** 两者不能互相替代。**井盖、消火栓、户表箱是现场锚点。** 看到破损先围挡上报。**本课不展开PPE采购标准和塌陷结构计算。** 按企业制度和设计复核。\n**结构关联：主链、对照、动作链、边界映射。** 下面要点收口。\n\n**自测：发现井盖缺失，第一步应该做什么？** 回本课【井盖缺失】对照。\n\n**自测：路面塌陷能不能站上去试一试？** 回本课【路面塌陷】对照。","structure":"主链：穿PPE→看环境→发现洞口或塌陷→围挡警示→拍照定位→上报守交。对照：正确围挡 vs 只拍照、砖头虚盖；正确穿戴 vs 不系下颚带。动作链：夜间下车→穿反光衣→戴安全帽→设围挡→拍照定位→上报守交。边界映射：PPE保护人，围挡保护区域；都不替代设计复核。要点：1 安全帽系下颚带；2 夜间穿反光衣；3 井盖缺失先围挡；4 塌陷不站上去；5 上报要定位守交。引导：本课已分环境风险；现场常卡在只拍照不围挡；下一步C56判作业顺序与应急。","anchors":[{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"复合井盖（给水/消防）","ref":"复合井盖（给水/消防）"},{"name":"地上式消火栓","ref":"地上式消火栓"},{"name":"地下式消火栓","ref":"地下式消火栓"},{"name":"不锈钢户表控制箱","ref":"不锈钢户表控制箱"}],"pitfall":"【井盖缺失不能只拍照】先围挡再上报；塌陷不要站上去试；安全帽不系带等于没戴。","remark":"企业填：PPE配置按企业现行制度；井盖承载按道路等级复核","seq":75,"family":"XG-03 安全生产与作业底线","lessonNo":3},{"id":"C59","sub":"CL-01","topic":"球墨铸铁管及管件验收：内衬、锌层与端头组合","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲球墨铸铁管及管件验收的辨析知识：分得清内衬类型、外防腐锌层、承插端头组合与标准换版。它承接 C57 总览和 C58 管材基础，重点在“端头拿反、内衬选错、标准换版看错”三类边界。","framework":"管身与承插口｜承口、插口、管身。\n内衬类型｜水泥砂浆、环氧密封、环氧陶瓷按水质。\n外防腐锌层｜平均≥130g/m²、局部≥110g/m²、终饰≥70μm。\n胶圈｜球墨管承插密封圈、EPDM。\n端头组合｜盘插、盘承、双承、双盘短管。\n标准换版｜GB/T 13295-2019 与 2026 版切换。\n包装批次｜端头保护、内衬完好、批次一致。","lecture":"**相邻关系：向上接 C61《PPR给水管及管件验收》；向下接 C60《衬塑复合管及管件验收》。**\n\n**现场情境：球铁管件到货，盘承盘插混在一起，还有一根内衬破损。** 怎么分端头、破损件怎么处理？本课讲。\n\n【先认承口与插口】\n**球墨铸铁管靠承插口加胶圈（球墨管承插密封圈）密封。** 卡上写承口、插口、管身，DN100–DN1200，PN10/16/25；你拿到管先看两端，大头是承口，小头是插口。\n**承口是大头，插口是小头。** 你看这个像喇叭口一样的大头叫承口，平头小头叫插口；验收先看端头有没有磕碰、密封槽是否完好。\n**承插口不是法兰口。** 看到一圈螺栓孔的是法兰端，你不要和承插端混叫；混叫就会拿错短管。\n**端头组合决定怎么接。** 盘插短管一端法兰一端插口；盘承短管一端法兰一端承口；双承两端承口；双盘两端法兰；你先把端头组合认全，再谈配套。\n【内衬类型按水质选】\n**内衬不是一律水泥砂浆。** 卡上写普通水泥砂浆、带密封涂层的水泥砂浆、无溶剂液体环氧或环氧陶瓷，按水质选定；你验收要看卡面内衬类型和实物是否一致。\n**普通水泥砂浆适用于大多数原水和饮用水。** 软水、腐蚀性水或高水质要求场景才看环氧密封或环氧陶瓷；选错内衬，水质不达标。\n**内衬要看连续性。** 你用手电照内壁，看有无脱落、裂纹、露铁；端头内衬破损要待检，不能补一补就放。\n**内衬标准要跟卡走。** 卡上参照 GB/T 26081-2022，环氧陶瓷参照 GB/T 34202 / ISO 28722；标准号对不上，先查再判。\n【锌层是外防腐硬指标】\n**球铁管外防腐看锌层加终饰层。** 卡上写锌层平均≥130g/m²、局部≥110g/m²，终饰层干膜平均≥70μm；你验收看喷码和外观，不能凭颜色判断。\n**锌层不是越黑越厚。** 有的管外观发黑但锌层不一定达标；你重点看运输划伤、露铁、大面积擦伤。\n**锌层破损会先锈。** 划伤露铁、锌层大面积擦伤要记录并待检；你放过去，埋地后先烂的就是这一点。\n**外防腐与内衬要分开看。** 内衬管水质，外防腐管土壤腐蚀，两件事；你验收不能只看内壁光滑就判合格。\n【胶圈与端头组合要配套】\n**胶圈（球墨管承插密封圈）是承插密封的关键件。** 卡上胶圈（球墨管承插密封圈）写球墨管承插密封圈，材料执行 GB/T 21873-2025，给水默认 EPDM；你验收看规格、弹性、表面。\n**胶圈不能有老化裂纹、永久变形、油污。** 你用手捏一下，回弹差、表面发黏、有油味，先待检；胶圈坏了，管口再正也漏。\n**盘承与盘插最容易拿反。** 盘承短管法兰端接阀门，承口端接纳插口；盘插短管法兰端接阀门，插口端插进承口；你记不住就念一遍“承口接纳，插口插入”。\n**鞍型管件用于主管带压分水。** 卡上鞍型管件（分水鞍）DN100–DN1200，分水口径 DN50–300；你验收看鞍体、螺栓、密封面，别当普通三通。\n【标准换版是验收边界】\n**现行标准是 GB/T 13295-2019。** 卡上备注 GB/T 13295-2026 于 2027-03-01 实施，届时切换；你验收先看到货日期。\n**到货日期在切换日前后，核对依据不同。** 切换前按现行，切换后按新版；单据写旧版、卡上提示换版时，你先看实施日期再判。\n**标准换版不是让你自行降级。** 拿不准转待检，你不凭经验放行；不要替供应商解释，责任由验收人承担。\n**批次与端头保护一起查。** 同批端头保护帽缺失、内衬进泥，先隔离；你先把异常件挑出来，再谈整批收不收。\n\n**自测：盘承和盘插管件怎么区分？** 回本课【先认承口与插口】对照。\n\n**自测：内衬破损的球铁管件怎么处置？** 回本课【内衬类型按水质选】对照。","structure":"主链：看承插口→核内衬类型→核锌层终饰→配胶圈→认端头组合→对标准换版→留痕隔离。\n对照：承口 vs 插口；盘承 vs 盘插；普通砂浆 vs 环氧内衬；现行版 vs 2026 版。\n要点：1 承口大头插口小头；2 内衬按水质选；3 锌层看两个指标；4 盘承盘插别拿反；5 换版看实施日期；6 端头破损先待检。\n引导：本课已分清球铁端头与内衬；现场常卡在盘承盘插拿反；下一步 C60 讲衬塑复合管及管件验收。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"盘插短管","ref":"盘插短管"},{"name":"盘承短管","ref":"盘承短管"},{"name":"鞍型管件（分水鞍）","ref":""}],"pitfall":"【盘承盘插别拿反】承口接纳插口；内衬破损先待检；标准换版看实施日期。","remark":"企业填：内衬类型按水质设计确认；标准切换按企业采购制度","seq":76,"family":"CL-01 材料验收入库与标准核对","lessonNo":4},{"id":"C60","sub":"CL-01","topic":"衬塑复合管及管件验收：沟槽与丝接两条线","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲衬塑复合管及管件验收的辨析知识：分得清丝接件、沟槽件、沟槽法兰三条线，认得出内衬损伤、补芯方向和卡箍刚柔。它承接 C59 的端头辨析，重点在“内衬怕高温、沟槽分刚柔、补芯看内外丝”。","framework":"外钢内塑｜镀锌钢管基体、内衬 PE/PPR。\n丝接件｜弯头、三通、堵头、大小头。\n补芯方向｜外丝朝大径、内丝朝小径。\n沟槽卡箍｜刚性限制轴向、柔性允许微量转角。\n沟槽管件｜三通、弯头、异径管。\n沟槽法兰｜衬塑密封面、软垫片。\n切割禁忌｜禁电焊气割、禁普通砂轮。","lecture":"**相邻关系：向上接 C59《球墨铸铁管及管件验收》；向下接 C62《直缝焊接钢管与钢制管件验收》。**\n\n**现场情境：衬塑管验收，补芯方向拿反了，现场还有人想电焊切割。** 错在哪？本课讲丝接与沟槽两条线。\n\n【先认外钢内塑】\n**衬塑复合管外表像镀锌钢管，内壁有塑料层。** 卡上名称衬塑复合管，DN15–DN300，PN10/16，内衬 PE/PPR；你往管口里看，能看到白或浅绿色塑料层。\n**内衬是防腐层，不是可拆件。** 你验收看内壁是否光滑、连续、无气泡和脱落；内衬起皮，整根管就废了。\n**端口要能看到钢塑结合。** 内衬翻边破损、露铁、离层，先待检；你用手摸一下端口，割手或有台阶感就要记录。\n**外镀锌层也要看。** 锈蚀、划伤、锌层脱落同样记录；你只看内衬不看外表，等于只验一半。\n【丝接件看端头与内衬】\n**丝接件多是可锻铸铁基体衬塑。** 卡上丝接弯头、丝接三通、堵头、丝接异径管，标准写 GB/T 28897-2021 附录B，可锻铸铁基体可参照 CJ/T 137-2008。\n**看丝扣是否规整。** 丝扣乱、缺牙、内衬在丝口根部翻边破裂，都不能按现用收；你拿一个标准件对一下牙距，很快能分。\n**堵头看内壁衬塑。** 它不是普通镀锌堵头，内壁也要有防腐层；你只拧一下不看内壁，可能收进无衬塑件。\n**丝接件不能电焊。** 验收发现焊过、烧黑的丝接件直接判异常；你放过去，装上去就是漏点。\n【补芯方向要分清】\n**补芯是一端内丝一端外丝。** 卡上衬塑内外丝补芯（变径补芯），DN15–DN100，用于变径并转换内外丝；你拿起来先看哪端是内牙、哪端是外牙。\n**外丝端朝大径，内丝端朝小径。** 记反了装不上，硬拧会撑裂内衬；你记不住就念“外大内小”。\n**补芯不是大小头。** 大小头两端同类型接口，补芯是内外丝转换加变径；你拿补芯当大小头发，现场两头都接不上。\n**验收看螺纹与内衬。** 外丝、内丝都规整，内衬无破损；你重点看丝根部的塑料翻边有没有裂。\n【沟槽卡箍（刚性/柔性）分刚柔】\n**沟槽卡箍（刚性/柔性）靠卡箍抱紧加 C 型橡胶圈密封。** 卡上沟槽卡箍（刚性/柔性），DN65–300，PN16，标准 GB/T 36019-2018；你看管端那一圈凹槽，就是给卡箍抱的。\n**刚性卡箍限制轴向位移，常用于立管。** 柔性卡箍允许微量转角和伸缩，用于需要吸收震动或沉降的管段；你拿不准就看卡箍壳体有没有限位结构。\n**刚柔混放是验收高频错。** 同一箱里刚性和柔性混装，你按标识和结构分开，不凭外观大小发料；混发到立管，柔性卡箍可能被拉脱。\n**胶圈不能扭曲。** 你验收看 C 型圈完好、无老化裂纹；胶圈装歪，打压就漏。\n【沟槽管件与沟槽法兰】\n**沟槽三通、弯头、异径管端头有沟槽。** 你验收看沟槽深度、端头衬塑、标识与卡名一致；沟槽太浅，卡箍抱不住。\n**沟槽法兰密封面有塑料层。** 卡上沟槽法兰（衬塑管件），PN10/16，你验收看衬塑面完好、螺栓孔规整；密封面掉塑，垫片压不严。\n**沟槽法兰必须配非金属软垫片。** 给水常用 EPDM，厚度按规格；你不能拿普通钢法兰（平焊/对焊）焊在衬塑管上代替，一焊内衬就烧毁。\n**沟槽件和丝接件不能混线。** 小口径丝接、大口径沟槽，你按设计线分开验收；混线发料，现场安装队会停下来找你。\n【切割禁忌是验收红线】\n**衬塑管严禁电焊、气割。** 高温会烧化内衬、破坏钢塑结合面，导致离层脱落；你看到焊口发蓝发黑，直接待检。\n**也禁用普通高速砂轮切割。** 瞬时高温会让管口内衬碳化；现场应用低速割管机或手锯，你验收看切割口是否平整。\n**验收看到切割口发黑、内衬碳化，直接待检。** 这不是修一修就能用；你放过去，装上去就是堵水或漏水。\n**端头毛刺要清理。** 你验收看管口是否平整、内衬是否翻边破损；毛刺不清理，装胶圈时容易划伤。\n\n**自测：补芯的外丝内丝应该朝哪边？** 回本课【补芯方向要分清】对照。\n\n**自测：衬塑管能不能用电焊或普通砂轮切割？** 回本课【先认外钢内塑】对照。","structure":"主链：看内衬→分丝接与沟槽→补芯方向→卡箍刚柔→沟槽法兰软垫→查切割口→留痕。\n对照：丝接件 vs 沟槽件；刚性卡箍 vs 柔性卡箍；补芯 vs 大小头。\n要点：1 内衬连续无脱落；2 补芯外丝朝大径；3 刚性防位移、柔性抗震；4 沟槽法兰配软垫；5 禁电焊和普通砂轮；6 切割口发黑待检。\n引导：本课已分清衬塑两条线；现场常卡在刚柔卡箍混放；下一步 C61 讲 PPR 给水管及管件验收。","anchors":[{"name":"衬塑复合管","ref":"衬塑复合管"},{"name":"沟槽卡箍（刚性/柔性）","ref":"沟槽卡箍（刚性/柔性）"},{"name":"衬塑内外丝补芯（变径补芯）","ref":"衬塑内外丝补芯（变径补芯）"},{"name":"衬塑活接头","ref":"衬塑活接头"},{"name":"沟槽法兰","ref":"沟槽法兰"}],"pitfall":"【补芯外丝朝大径】刚性卡箍防位移、柔性抗震；衬塑管禁电焊和普通砂轮。","remark":"企业填：沟槽卡箍刚柔按设计线确认；衬塑法兰垫片按介质选","seq":77,"family":"CL-01 材料验收入库与标准核对","lessonNo":5},{"id":"C62","sub":"CL-01","topic":"直缝焊接钢管与钢制管件验收：焊缝、法兰与盲板","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲直缝焊接钢管与钢制管件验收的辨析知识：分得清直缝与螺旋缝、平焊与对焊法兰、钢法兰盲板与球铁盲板，核得住壁厚、防腐和管件标准。它承接 C58–C61 的管材验收，重点在“高压别拿平焊、盲板别混材质、焊缝别混类型”。","framework":"焊缝外观｜单条纵向直缝 vs 螺旋焊缝。\n材质口径｜碳钢、DN、壁厚、长度。\n防腐层｜内防腐、外防腐、破损。\n平焊与对焊｜平焊低压、对焊带颈高压。\n钢法兰盲板｜实心盘、螺栓孔、密封面。\n焊接管件｜焊接三通、弯头、异径管。\n试压安全｜盲板受力、禁止站人。法兰验收按 PN 与 DN 核配套｜五步核对动作。","lecture":"**相邻关系：向上接 C60《衬塑复合管及管件验收》；向下接 C63《防护与调节类阀门验收》。**\n\n**现场情境：高压管道验收，有人拿平焊法兰顶对焊，试压时还站到了盲板正前方。** 风险在哪？本课讲焊缝与法兰。\n\n【先看焊缝分直缝与螺旋】\n**直缝焊接钢管是一条纵向直焊缝。** 卡上名称直缝焊接钢管，DN20–DN900，壁厚 2.5–20mm，标准 GB/T 3091-2025；你蹲下看管身，焊缝是笔直一条。\n**螺旋缝焊接钢管是连续螺旋焊缝。** 卡上名称螺旋缝焊接钢管，DN200–DN4000，用于长距离大口径；你看焊缝像弹簧一样绕圈，就是螺旋管。\n**看焊缝形态就能先分族。** 直缝是笔直线，螺旋是绕圈线；你不要把螺旋管按直缝管卡验收，标准和应用场景都不同。\n**焊缝外观要看连续性。** 裂纹、咬边、气孔、明显补焊要记录待检；你只看表面光滑，不看焊缝根部，可能漏掉大问题。\n【材质口径与防腐】\n**钢管口径看 DN 与壁厚。** 同 DN 不同壁厚承压不同，你验收要读卡上壁厚范围；壁厚薄了，高压段先出事。\n**内防腐贴水，外防腐贴土。** 内防腐常见环氧或水泥砂浆，外防腐常见 3PE 或环氧煤沥青；你看管口和内壁，能分出内外防腐。\n**防腐层破损是钢管大敌。** 划伤露铁、鼓包、脱层要记录；破损点会先锈，你放过去，埋地后先烂这一点。\n**防腐层不是越厚越对。** 你按卡上防腐体系核对，不凭颜色；颜色深不代表防腐好。\n【平焊与对焊要分场景】\n**平焊法兰像平盘，管子插进去正面焊。** 卡上钢法兰（平焊/对焊），标准 GB/T 9124.1-2019，平焊多用于低压；你看法兰颈部没有突起，就是平焊。\n**对焊法兰有脖子，管子和坡口对碰焊。** 脖子加固，承压更高，泵房高压处优先对焊；你看法兰背面有一截长颈，就是对焊。\n**高压用平焊是偷懒。** 看着省事，坑在承压不足、焊缝根部受力；你验收遇到高压段拿平焊，先待检核设计。\n**验收看密封面和螺栓孔。** 突面/平面、孔数、孔径要与配套法兰一致；孔距不对，现场装不上。\n【钢法兰盲板别混材质】\n**钢法兰盲板是钢管件里的实心盘。** 卡上钢法兰盲板（钢管件），PN10/16，DN 同母管，标准按 GB/T 9124.1-2019 配套；你看它是钢制、带螺栓孔、无中心孔。\n**球铁盲板是球铁管件。** 卡名球墨盲板（法兰盲板）属于球铁管件，标准 GB/T 13295 系列；你不要和钢盲板混发，材质和标准都不同。\n**盲板看厚度、螺栓孔、密封面。** 变形、锈蚀、孔距不对要待检；你拿球铁盲板当钢盲板用，压力等级可能不够。\n**盲板不是垫片。** 它封堵介质，垫片在盲板与法兰之间密封；你把盲板当垫片，装上去也漏。\n【焊接管件与试压边界】\n**焊接三通、弯头、异径管两端是光口。** 卡上标准 GB/T 13401-2025，你验收看坡口、壁厚、椭圆度；没有坡口，现场焊不透。\n**钢焊接弯头看角度和半径。** 90°/45°、长半径/短半径要与设计一致；你拿45°当90°用，管线对不上。\n**异径管分同心与偏心。** 水平管防气囊要看偏心布置，你验收不只看口径；偏心装反，管顶积气。\n**试压盲板对面不能站人。** 盲板承受推力大，螺栓失效会飞出；这是现场后果，你验收时要提醒安装队。\n【法兰验收：按 PN 与 DN 一起核】\n**钢管法兰验收不是数一数螺栓够不够，要先按 PN 等级和 DN 口径把配套项对齐。** 核对动作：1 读卡面 PN 与 DN；2 对实物铭牌或喷码；3 核孔数、孔距、孔径、螺栓规格；\n4 看型式 SO / WN / BL 是否与设计一致；5 检查密封面与垫片。\n**【红线】焊缝、法兰、盲板要成套核，缺一项都可能试压时漏。** 落回卡上：看「钢法兰（平焊/对焊）」「钢法兰盲板」卡的 PN、DN、型式；孔数与螺栓规格由技术部门按现行标准核定，本课不代填数值。\n\n**自测：高压场合为什么不能用平焊法兰？** 回本课【平焊与对焊要分场景】对照。\n\n**自测：试压时严禁站在什么位置？** 回本课【焊接管件与试压边界】对照。","structure":"主链：看焊缝分直缝螺旋→核 DN 与壁厚→查内外防腐→分平焊对焊→认钢盲板→核焊接管件→记试压边界。\n对照：直缝 vs 螺旋；平焊 vs 对焊；钢法兰盲板 vs 球铁盲板。\n要点：1 直缝纵缝、螺旋绕圈；2 高压优先对焊；3 平焊不承高压；4 钢盲板别混球铁；5 焊接件看坡口壁厚；6 试压盲板不站人。\n引导：本课已分清钢管焊缝与法兰；现场常卡在高压拿平焊；下一步 C63 讲防护与调节类阀门验收。\n验收动作：读 PN/DN → 对铭牌 → 核孔与螺栓 → 对型式 → 查密封面。\n记红线：孔数螺栓规格以现行标准与技术部门核定为准。","anchors":[{"name":"直缝焊接钢管","ref":"直缝焊接钢管"},{"name":"钢法兰（平焊/对焊）","ref":"钢法兰（平焊/对焊）"},{"name":"钢法兰盲板","ref":"钢法兰盲板"},{"name":"钢焊接弯头","ref":"钢焊接弯头"}],"pitfall":"【高压别拿平焊】钢盲板别混球铁盲板；试压严禁站盲板正前方。","remark":"企业填：焊缝等级与试压按设计及规范；高压法兰按设计确认","seq":78,"family":"CL-01 材料验收入库与标准核对","lessonNo":6},{"id":"C63","sub":"CL-01","topic":"防护与调节类阀门验收：倒流防止器与减压阀","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲防护与调节类阀门验收的辨析知识：分得清低阻力、减压型、双止回三类倒流防止器，分得清先导式与直动式减压阀，核得住标准、过滤器、直管段和泄水口。重点在“防护等级不降级、泄水口不泡污水、导阀前必过滤”。","framework":"防回流作用｜防止下游污染水倒灌。\n三类倒流防止器｜低阻力、减压型、双止回。\n减压阀结构｜膜片、弹簧、阀瓣、导阀。\n先导与直动｜精度与流量差异。\n标准与状态｜标准号、公司现用。\n过滤器与直管段｜阀前过滤、前后直管。\n泄水口与安装｜水平、不浸污水。","lecture":"**相邻关系：向上接 C62《直缝焊接钢管与钢制管件验收》；向下接 C64《截断类阀门验收》。**\n\n**现场情境：倒流防止器到货，泄水口位置没看就收，还把低阻力型当减压型。** 错在哪？本课讲防护设备验收。\n\n【先认防回流作用】\n**倒流防止器是饮水安全边界。** 卡上低阻力倒流防止器、减压型倒流防止器、双止回阀型倒流防止器，都是防下游脏水倒灌；你把它当普通止回阀，防护等级就错了。\n**它不是普通止回阀。** 倒流防止器有双止回加泄水或减压结构，防护等级更高；你看阀体上有泄水口或中间腔，就别按止回阀验。\n**验收先看类型。** 三类外观相近，你按卡名和铭牌分，不凭大小猜；类型错就是防护等级错。\n**类型错就是防护等级错。** 高危边界不能用低等级替代；你拿低阻力当减压型用，看着省水头，坑在防护不够。\n【三类倒流防止器要分清】\n**减压型防护等级最高。** 卡上减压型倒流防止器执行 GB/T 25178-2020，有减压装置和泄水腔，用于高风险边界；你验收看铭牌和泄水腔。\n**低阻力型水头损失小。** 卡上低阻力倒流防止器执行 JB/T 11151-2026，水头损失小于 3m，适合对水损敏感的主干节点；你看铭牌别和减压型混。\n**双止回阀型防护等级最低。** 卡上双止回阀型执行 CJ/T 160-2010，只有两道止回、无泄水，用于风险较低支管；你把它装到高危边界，就是降级。\n**不能把低阻力当减压型。** 低阻力省水头，但防护能力弱于减压型；你验收先看类型，再谈水损。\n【减压阀分先导与直动】\n**减压阀把进口高压稳定到设定出口压力。** 卡上先导式减压阀、直动式减压阀，标准分别看 GB/T 12246-2025、GB/T 12244-2025；你看阀体上部有没有导阀细管，能先分个大概。\n**直动式靠膜片直接带动阀瓣。** 结构简单，适合小流量、低压差、精度要求不高的支管；你拿直动式上大口径干线，压力会波动。\n**先导式多一个导阀。** 导阀先稳压再控制主阀，大口径和工况波动大的干线优先；你看导阀孔很细，就知道它怕堵。\n**先导式导阀孔怕堵。** 阀前必须装 Y 型过滤器，你验收看过滤器接口和滤网；没有过滤器，导阀卡死只是时间问题。\n【安装边界是验收内容】\n**倒流防止器必须水平安装。** 泄水阀要能顺畅排水，不能装在积水坑或下水道里；你看安装图写积水坑，就要先待检。\n**泄水口泡污水会倒灌。** 你验收看安装位置和排水条件，不只看阀体；泄水口淹在污水里，防回流就失效。\n**减压阀前后要留直管段。** 水流不稳压力会乱跳，你验收看接口与布置；直管段不够，压力表指针会跳舞。\n**阀前过滤器不能省。** 导阀孔细，沙粒卡死就失去稳压；你验收看过滤器有没有装、滤网有没有破。\n【标准状态与铭牌】\n**标准号要跟卡面一致。** 低阻力 JB/T 11151-2026、减压型 GB/T 25178-2020、先导 GB/T 12246-2025、直动 GB/T 12244-2025；你验收对照卡面，别拿旧标准套。\n**铭牌看类型、DN、PN、流向。** 箭头装反等于白装；你看阀体箭头，别只看法兰方向。\n**状态栏看公司现用。** 非现用先隔离；直动式减压阀采集包现用栏为空，建议企业确认后再作现用锚点。\n**外观看泄水口、导阀、过滤器接口。** 缺件、堵头不对要待检；你只看阀体完整，可能漏掉泄水口堵死。\n\n**自测：低阻力型能不能当减压型倒流防止器用？** 回本课【三类倒流防止器要分清】对照。\n\n**自测：先导式减压阀前为什么要装过滤器？** 回本课【减压阀分先导与直动】对照。","structure":"主链：认防回流→分三类倒流防止器→分先导直动→核标准铭牌→查过滤器直管段→查泄水口→留痕。\n对照：减压型 vs 低阻力 vs 双止回；先导式 vs 直动式。\n要点：1 防护等级不降级；2 低阻力水损小但防护弱；3 先导式导阀前必过滤；4 倒流防止器水平不泡污水；5 铭牌流向要核；6 非现用先隔离。\n引导：本课已分清防护与调节阀门；现场常卡在倒流防止器装积水坑；下一步 C64 讲截断类阀门验收。","anchors":[{"name":"低阻力倒流防止器","ref":"低阻力倒流防止器"},{"name":"减压型倒流防止器","ref":"减压型倒流防止器"},{"name":"先导式减压阀","ref":"先导式减压阀"},{"name":"直动式减压阀","ref":"直动式减压阀"}],"pitfall":"【泄水口不能泡污水】低阻力别当减压型；先导阀前必装过滤器；铭牌流向别装反。","remark":"直动式减压阀采集包现用栏为空，建议企业确认后作现用锚点；企业填：防护等级按水质风险设计确认","seq":79,"family":"CL-01 材料验收入库与标准核对","lessonNo":7},{"id":"C64","sub":"CL-01","topic":"截断类阀门验收：闸阀、蝶阀、球阀与加密阀","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲截断类阀门验收的辨析知识：分得清明杆与暗杆、中线与偏心、浮动与固定、普通与加密，核得住标准、端头、阀杆和锁芯。重点在“闸阀不半开调节、暗杆看不了开度、加密阀没钥匙空转”。","framework":"截断原理｜闸板升降、蝶板旋转、球体旋转。\n闸阀｜明杆与暗杆、弹性座封。\n蝶阀｜中线软密封、偏心、电动。\n球阀｜浮动与固定、黄铜小口径。\n黄铜与加密｜户内控制、防盗锁芯。\n标准状态｜标准号、公司现用。\n端头与操作｜法兰、内螺纹、手轮、锁芯。阀门型号编制字典｜七段代号逐段拆。截断类阀门类型×口径×PN对照表｜闸蝶球逐类对。","lecture":"**相邻关系：向上接 C63《防护与调节类阀门验收》；向下接 C65《止回阀与排气阀验收》。**\n\n**现场情境：闸阀型号里写着 16，有人以为是口径 16；暗杆阀验收时还想靠阀杆高度判断。** 错在哪？本课讲截断阀验收。\n\n【先认截断原理】\n**截断阀只负责全开全关。** 闸阀靠闸板升降，蝶阀靠蝶板旋转，球阀靠带孔球体旋转；你看操作机构就能先分个大概。\n**截断阀不是调节阀。** 闸阀半开半关会震动；你拿闸阀当调节阀用，阀板和阀座都容易坏。\n**验收先看端头。** 法兰、对夹、内螺纹，端头决定怎么装；你端头看错，现场得配转换件。\n**再看操作机构。** 手轮、蜗轮、电动执行器、锁芯，缺件要待检；你只看阀体完整，可能漏掉锁芯缺钥匙。\n【闸阀分明杆与暗杆】\n**明杆开关时阀杆伸出。** 你看杆长知开度，但占上方空间，阀井要够深；你验收看阀杆有没有弯曲。\n**暗杆阀杆只原地转。** 省空间，适合地下受限阀井，但看不到开度；你验收看阀杆密封圈有没有老化。\n**弹性座封闸阀是供水主力。** 卡上弹性座封闸阀（暗杆式）执行 GB/T 12232-2025、CJ/T 216-2013，闸板整体包胶；你打开看闸板包胶是否完整。\n**包胶破损会关不严。** 你验收看闸板包胶、阀座、阀杆密封；包胶起皮，关到底也漏。\n【蝶阀分中线与偏心】\n**中线蝶阀阀杆在中间，橡胶座过盈密封。** 卡上中线（软密封）蝶阀执行 GB/T 12238-2008，常用于常温清水；你看阀杆位置居中，就是中线。\n**偏心蝶阀开启瞬间先脱开阀座。** 双偏心、三偏心减少摩擦，寿命更长；你看阀杆偏置，就是偏心结构。\n**软密封怕高温，硬密封耐温高压。** 你验收看卡名和铭牌，不凭颜色；颜色相近，密封副可能不同。\n**电动蝶阀看执行器。** 电机、限位、手动应急要齐；你验收看手动手柄在不在，断电时能应急。\n【球阀分浮动与固定】\n**浮动球阀靠水压把球压向出口阀座。** 小口径常用，压力越大密封越紧；你转手柄吃力，可能是口径大或压力高。\n**固定球阀带轴承，转动手柄轻。** 大口径高压优先固定球；你验收看阀体结构，别只看手柄。\n**黄铜内螺纹浮动球阀用于户内小口径。** 卡上 DN15–DN50，PN16，标准 GB/T 8464-2023；你看内螺纹和黄铜阀体就能认。\n**浮动球别硬上大口径高压。** 会拧不动，密封件也吃力；你验收遇到大口径高压拿浮动球，先待检核设计。\n【黄铜与加密阀】\n**黄铜闸阀用于小口径全开全关。** 卡上 DN15–DN50，PN16，标准 GB/T 8464-2023；你看黄铜阀体和内螺纹。\n**加密闸阀多一套锁芯。** 卡上加密闸阀，法兰型执行 GB/T 12232-2025、CJ/T 216-2013；黄铜加密闸阀执行 GB/T 8464-2023；你验收看锁芯、钥匙、离合机构。\n**没钥匙手轮空转是正常防盗。** 你验收看锁芯有没有卡死、钥匙能不能正常吸合；手轮空转不是坏，是防盗。\n**加密阀不是普通阀加锁。** 手轮与阀杆离合结构要完整；你只加挂锁，不能算加密阀。\n【阀门型号怎么读：一串字母数字的拆法】\n**铭牌上一串型号不是乱编的，按「类型→传动→连接→结构→密封面→压力→阀体材质」逐段拆。** 表头顺序：段位｜常见代号｜举例。\n第 1 位 类型｜Z 闸阀、D 蝶阀、Q 球阀、H 止回阀、Y 减压阀｜Z45X 开头就是闸阀。\n第 2 位 传动｜9 电动、6 气动、7 液动、0 电磁、手轮常省略｜D941X 的 9 是电动。\n第 3 位 连接｜4 法兰、1 内螺纹、2 外螺纹、7 对夹｜Q11F 的 1 是内螺纹。\n第 4 位 结构｜因类型而异，如闸阀 4/5 分暗杆明杆｜Z45X 的 5、Z41X 的 1。\n第 5 位 密封面｜X 橡胶、F 氟塑料、H 硬密封、T 铜｜X 多为软密封。\n横杠后 压力｜数字代表公称压力，16 即 PN16｜D371X-16、Z45X-16Q。\n末尾 阀体材质｜Q 球墨铸铁、T 黄铜、C 碳钢、Z 灰铸铁｜Q11F-16T 末尾 T 是黄铜。\n**【红线】代号含义以现行阀门型号编制标准原文和厂家铭牌为准，本课只教拆段顺序，不代为下型号适用结论。**\n落回卡上：把「弹性座封闸阀（暗杆式）Z45X-16Q」「中线（软密封）蝶阀 D371X-16」「黄铜内螺纹浮动球阀 Q11F-16T」三张卡的型号并排拆一遍。\n\n【截断类阀门类型 × 口径 × PN 对照表】\n**同一类截断功能，不同阀型的口径与压力落点不同，验收按卡面逐项对。** 表头：类型｜卡面型号示例｜卡面口径｜卡面压力。\n弹性座封闸阀｜Z45X-16Q / Z41X-16Q｜DN50–DN600｜PN10/16。\n黄铜闸阀 / 加密闸阀｜Z11W-16T / Z45X｜DN15–DN50、DN40–DN300｜PN16、PN10/16。\n中线 / 偏心 / 电动蝶阀｜D371X-16 / D941X、D943H｜DN50–DN2000｜PN10/16。\n浮动球阀｜Q41F-16｜DN15–DN300｜PN16/25。\n黄铜内螺纹球阀｜Q11F-16T｜DN15–DN50｜PN16。\n**【红线】口径、压力、连接方式、密封面四项要一起对，只核 DN 会漏掉 PN 与材质。** 落回卡上：逐张核型号、DN、PN、连接方式四个字段；选型与判定以设计文件和企业现行制度为准。\n\n**自测：闸阀型号里的 16 是口径还是公称压力？** 回本课【阀门型号怎么读：一串字母数字的拆法】对照。\n\n**自测：大口径高压为什么不宜用浮动球阀？** 回本课【球阀分浮动与固定】对照。","structure":"主链：认截断件→分闸阀明暗→分蝶阀中线偏心→分球阀浮动固定→认黄铜与加密→对标准端头→留痕。\n对照：明杆 vs 暗杆；中线 vs 偏心；浮动 vs 固定；普通 vs 加密。\n要点：1 闸阀不半开调节；2 暗杆省空间看不了开度；3 中线软密封常温；4 大口径高压用固定球；5 加密阀没钥匙空转；6 非现用先隔离。\n引导：本课已分清截断阀四类；现场常卡在闸阀半开当调节；下一步 C65 讲止回阀与排气阀验收。\n会拆型号：类型→传动→连接→结构→密封面→压力→材质；16 是 PN16、末尾 Q 是球铁。\n查选型表：闸蝶球的 DN 与 PN 落点不同，四项一起核。\n记红线：代号含义以现行标准原文和厂家铭牌为准，本课不代下型号适用结论。","anchors":[{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"弹性座封闸阀（明杆式）","ref":"弹性座封闸阀（明杆式）"},{"name":"中线（软密封）蝶阀","ref":"中线（软密封）蝶阀"},{"name":"电动蝶阀","ref":"电动蝶阀"},{"name":"浮动球阀","ref":"浮动球阀"},{"name":"黄铜内螺纹浮动球阀","ref":"黄铜内螺纹浮动球阀"},{"name":"黄铜闸阀","ref":"黄铜闸阀"}],"pitfall":"【闸阀严禁半开调节】暗杆看不了开度；大口径高压别用浮动球；加密阀没钥匙只空转。 【型号 16 不代表口径】16 是 PN16；选型以设计文件与企业现行制度为准。","remark":"浮动球阀采集包现用栏为空，建议企业确认后作现用锚点；企业填：阀门压力等级与端头按设计核对","seq":80,"family":"CL-01 材料验收入库与标准核对","lessonNo":8},{"id":"C65","sub":"CL-01","topic":"止回阀与排气阀验收：单向、缓闭与高点排气","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲止回阀与排气阀验收的辨析知识：分得清旋启、升降、对夹、静音缓闭，分得清复合式、快速、微量排气，核得住标准、流向和安装位置。重点在“止回阀保泵、排气阀高点、静音缓闭防水锤”。","framework":"止回原理｜单向阀瓣、防倒流。\n旋启与升降｜铰链门 vs 直上直下。\n对夹与静音｜薄型双瓣、弹簧缓闭。\n排气原理｜浮球浮筒、大孔小孔。\n快速微量复合｜充水排气、日常排气、负压吸气。\n标准状态｜标准号、公司现用。\n安装位置｜泵出口、管线高点。","lecture":"**相邻关系：向上接 C64《截断类阀门验收》；向下接 C66《机械水表与超声波水表验收》。**\n\n**现场情境：止回阀验收没看箭头方向，排气阀也没确认是不是装高点的规格。** 怎么验？本课讲单向与排气。\n\n【先认止回原理】\n**止回阀没有手轮，只准水前进不准后退。** 正向冲开阀瓣，反向靠回水或弹簧关闭；你看阀体没有操作手轮，先往止回类想。\n**止回阀常装泵出口。** 停泵时防止高压水倒流打坏叶轮；你验收看泵出口位置，就知道它为什么重要。\n**验收先看流向箭头。** 箭头装反等于没装；你看阀体箭头与管道流向是否一致。\n**止回阀不是截断阀。** 它不能代替闸阀或蝶阀做全开全关；你拿止回阀当截断用，停泵时关不严。\n【旋启与升降要分清】\n**旋启式像铰链门，摇板绕轴翻起。** 流阻小，适合大口径；你打开阀盖看摇板，像门一样绕轴转。\n**金属旋启关阀水锤大，橡胶瓣短行程快关。** 卡上旋启式止回阀（金属瓣/橡胶瓣），金属瓣看 GB/T 13932-2016、GB/T 12236-2025；你验收看阀瓣材质。\n**升降式阀瓣直上直下。** 密封好但阻力大，多用于小口径或立管；你看阀瓣沿轴线升降，就是升降式。\n**对夹碟式很薄，双瓣靠扭簧快关。** 卡上对夹碟式止回阀，标准 JB/T 8937-2025，适合空间受限；你看两片薄阀瓣对开，就是对夹式。\n【静音缓闭防水锤】\n**静音式（缓闭）止回阀带弹簧和缓闭结构。** 卡上静音式（缓闭）止回阀；旋启式结构参照 GB/T 13932-2016，对夹/法兰适用部分参照 JB/T 8937-2025，缓闭指标以技术规格书为准。\n**它先快速关大部分，再缓慢关末段。** 既防倒流，又削减水锤和关闭噪声；你验收看弹簧和阻尼结构是否完整。\n**泵出口和高楼供水优先静音缓闭。** 普通旋启金属瓣水锤大，噪声也大；你拿普通旋启上泵出口，夜里能听到“咚”一声。\n**缓闭结构缺件要待检。** 弹簧、阻尼、阀瓣行程异常都不能放；你只看阀体外观，可能漏掉缓闭失效。\n【排气阀三类要分清】\n**排气阀靠浮球浮筒控制排气孔。** 气多浮球落，排气；水满浮球起，封孔；你打开阀盖看浮球，就能理解原理。\n**快速排气阀大孔，充水时大量排气。** 卡上快速排气阀（高速排气阀），标准 JB/T 12386-2015；你看排气口大，就是快速式。\n**微量排气阀小孔，平时排溶解空气。** 卡上微量排气阀（黄铜自动排气阀），标准 JB/T 12386-2015，DN15–DN25；你看小孔和浮球，就是微量式。\n**复合式兼大孔和小孔。** 卡上复合式排气阀执行 GB/T 36523-2018，充水大孔排、平时小孔排、负压还能吸气；你看阀体有两个排气通道，就是复合式。\n【标准与安装位置】\n**标准号要跟卡面一致。** 复合式 GB/T 36523-2018；快速和微量 JB/T 12386-2015；静音和旋启看各自结构标准；你验收对照卡面，别拿一个标准套所有。\n**排气阀必须装高点或变坡处。** 装低点只吐水不排气；你看安装图画在低点，先待检核图。\n**止回阀看泵出口和流向。** 阀体箭头、DN、PN、端头要核；你装反方向，泵一停就倒流。\n**状态栏看公司现用。** 非现用先隔离；黄铜小阀看螺纹和弹簧，你验收看弹簧有没有锈断。\n\n**自测：排气阀为什么必须装在管网高点？** 回本课【标准与安装位置】对照。\n\n**自测：止回阀箭头方向装反会怎样？** 回本课【先认止回原理】对照。","structure":"主链：认单向→分旋启升降→分对夹静音→认排气三类→对标准→查安装位置→留痕。\n对照：旋启 vs 升降；金属瓣 vs 橡胶瓣；快速 vs 微量 vs 复合。\n要点：1 止回阀保泵防倒流；2 静音缓闭防水锤；3 对夹薄型省空间；4 复合排气大小孔兼顾；5 排气阀装高点；6 非现用先隔离。\n引导：本课已分清止回与排气；现场常卡在排气阀装低点；CL-01 前 9 门到此形成总览到分件的验收链。","anchors":[{"name":"静音式（缓闭）止回阀","ref":"静音式（缓闭）止回阀"},{"name":"旋启式止回阀（金属瓣/橡胶瓣）","ref":"旋启式止回阀（金属瓣/橡胶瓣）"},{"name":"复合式排气阀","ref":"复合式排气阀"},{"name":"微量排气阀（黄铜自动排气阀）","ref":"微量排气阀（黄铜自动排气阀）"}],"pitfall":"【排气阀必须装高点】止回阀箭头别装反；泵出口优先静音缓闭；非现用先隔离。","remark":"企业填：泵出口止回型式按设计确认；排气阀位置按管线高点复核","seq":81,"family":"CL-01 材料验收入库与标准核对","lessonNo":9},{"id":"C66","sub":"CL-01","topic":"机械水表与超声波水表验收：接口、铅封与检定","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲机械水表与超声波水表这一类计量器具的验收知识：三类水表的结构差异、接口与口径体系、铅封与强制检定、读数显示与标准依据。它在 CL-01 验收链中承接阀门验收，向下衔接远传水表与流量计。","framework":"机械水表类型｜旋翼式湿式/干式/液封、水平螺翼。\n超声波水表｜无活动部件、换能器、显示与通信。\n接口与口径｜螺纹 DN15–DN40、法兰 DN50–DN300。\n铅封与检定｜强制检定、铅封、检定标识。\n读数与显示｜字轮、指针、液晶、单位。\n标准与状态｜GB/T 778 系列、公司现用。\n包装与外观｜表壳、滤水网、接口保护。","lecture":"**相邻关系：向上接 C65《止回阀与排气阀验收》；向下接 C67《远传水表与流量计验收》。**\n\n**现场情境：一批水表到货，铅封断了，接口还对不上。** 能不能收？本课讲强制检定与接口。\n\n【三类水表的结构差异】\n**机械水表分旋翼式和水平螺翼两类。** 旋翼式卡上标 DN15–DN40，叶轮垂直水流方向旋转，湿式计数器浸水、干式磁隔离、液封字轮用液体封装；\n水平螺翼卡上标 DN50–DN300，叶轮水平布置，水流沿轴向推动螺翼，水损小、量程宽。\n**超声波水表没有活动部件。** 卡上超声波水表 DN15–DN300，靠一对换能器测顺逆流传播时差，再结合截面积算流量；表体内没有叶轮，这是与机械表最直接的外观区别。\n**三类表的分族依据是结构与口径。** 小口径螺纹多为旋翼式，大口径法兰多为水平螺翼或超声波；结构差异决定适用场景，也决定验收时该看哪些部件。\n**水表是计量器具，不是普通管件。** 它的读数直接关系贸易结算，所以铅封、检定标识、表体编号比外观更重要。\n【接口与口径体系】\n**水表口径用 DN 表示公称口径。** 旋翼式 DN15–DN40 常配螺纹和活接，水平螺翼与超声波 DN50 以上常配法兰；DN 不是内径，不能拿卡尺量内壁去对卡面。\n**接口型式决定能不能装。** 螺纹接口看规格与牙距，法兰接口看孔数、孔距、密封面；接口与卡面不一致，属于配套性异常。\n**接口保护是出厂完整性的一部分。** 新表接口常有堵盖，堵盖缺失可能意味着内腔进异物；验收时堵盖与内腔清洁度要一起看。\n**口径与接口要跟设计对上。** 同是 DN50，螺纹和法兰是两种接口；只看 DN 不看接口，仍可能拿错。\n【铅封与强制检定】\n**水表属于强制检定计量器具。** 卡上旋翼式、水平螺翼、超声波都标“强制检定”；检定标识、铅封、检定证书是计量合法性的三道凭据。\n**铅封是计量封缄。** 铅封完整表示表体未经非授权拆动；铅封断裂或缺失，计量结果就失去封缄保护，不能直接进现用区。\n**检定标识要与表体编号对应。** 合格证、检定证书、表体编号三处要能对上；对不上说明凭据与实物不匹配，属于单据异常。\n**超声波表还要看换能器。** 换能器是超声表的核心计量部件，松动、密封破损会影响信号；换能器座与线缆属于结构完整性检查项。\n【读数显示与标准依据】\n**机械表看字轮和指针。** 湿式、干式、液封的读数窗口要清晰；窗口进水、起雾、字轮卡滞会影响抄读，属于外观与功能异常。\n**超声波表看液晶和单位。** 显示完整、单位明确是基本要求；缺划、单位不清说明显示模块可能异常。\n**标准依据是 GB/T 778.1-2018 和 GB/T 778.2-2018。** 机械表与超声波表都按这两个标准；流量计标准不能套到水表上。\n**状态栏决定现用属性。** 卡上“公司现用”才能按现用件验收；非现用先隔离，不凭名称放行。\n【包装外观与附件】\n**水表是精密计量件，包装要防震防潮。** 包装挤压、受潮可能伤及表壳或机芯；表壳变形、玻璃裂纹属于外观异常。\n**滤水网是旋翼式的常见附件。** 滤网缺失或破损会让杂质进入叶轮；验收时滤网齐全、无破损是基本要求。\n**附件与说明书要随货。** 说明书、合格证、检定证书是后续使用与追溯的依据；缺件属于资料不完整。\n\n**自测：铅封断裂的水表怎么处理？** 回本课【铅封与强制检定】对照。\n\n**自测：水表接口不对会导致什么？** 回本课【接口与口径体系】对照。","structure":"主链：结构分族→接口口径→铅封检定→读数显示→标准状态→包装附件。\n对照：旋翼式 vs 水平螺翼；机械表 vs 超声波表；螺纹接口 vs 法兰接口。\n要点：1 小口径螺纹、大口径法兰；2 铅封断了先待检；3 检定标识对编号；4 超声波看换能器；5 非现用先隔离。\n引导：本课已建立水表验收的知识骨架；现场常见问题是铅封断裂仍放行；下一步 C67 讲远传水表与流量计验收。","anchors":[{"name":"旋翼式机械水表（湿式/干式/液封）","ref":"旋翼式机械水表（湿式/干式/液封）"},{"name":"水平螺翼机械水表","ref":"水平螺翼机械水表"},{"name":"超声波水表","ref":"超声波水表"}],"pitfall":"【铅封断了先待检】水表是强制检定；接口不对装不上；超声波看换能器。","remark":"—","seq":82,"family":"CL-01 材料验收入库与标准核对","lessonNo":10},{"id":"C67","sub":"CL-01","topic":"远传水表与流量计验收：通信、直管段与检定","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲远传水表与流量计这一类计量设备的知识：光电直读与 NB-IoT 的通信差异、电磁流量计的电极衬里、插入式超声波的底座与直管段、检定规程与附件。它在 C66 水表知识之上，扩展到带通信和带转换器的计量设备。","framework":"远传水表｜光电直读、NB-IoT。\n通信接口｜M-BUS、RS-485、NB-IoT。\n电磁流量计｜电极、衬里、转换器。\n插入式超声波｜传感器、球阀底座、带压开孔。\n直管段｜上游≥10D、下游≥5D。\n检定与标准｜JJG 1033、JJG 1030、GB/T 35138。\n防护与包装｜防护等级、线缆、说明书。","lecture":"**相邻关系：向上接 C66《机械水表与超声波水表验收》；向下接 C68《密封紧固与抢修辅材验收》。**\n\n**现场情境：远传水表和流量计到货，通信接口和检定证书编号没对上就准备装。** 漏了什么？本课讲验收要点。\n\n【远传水表的两类通信】\n**光电直读远传水表是机械基表加光电模块。** 卡上 DN15–DN300，通信用 M-BUS 或 RS-485；它靠字轮码道和光电采集模块读出绝对位置，读数与机械窗口一致。\n**NB-IoT 智能水表靠运营商网络上报。** 卡上 DN15–DN40，内置通信模组和电池；它不需要总线，但依赖网络覆盖和模组状态。\n**通信接口是远传表的核心差异。** M-BUS 两线制不区分极性，RS-485 要区分 A/B 线，NB-IoT 看模组与天线；接口不匹配，表体再好也抄不到数。\n**通信协议要跟采集系统匹配。** 卡面通信方式与平台要求要一致；协议不匹配属于系统配套异常。\n【电磁流量计的结构要点】\n**电磁流量计靠导电流体切割磁感线计量。** 卡上 DN15–DN300，精度 0.5 级；测量管、励磁线圈、电极、绝缘衬里、转换器是它的基本构成。\n**衬里材质按介质选。** 氯丁橡胶、PTFE、PFA、聚氨酯各有适用；衬里破损会直接影响绝缘与信号。\n**电极是信号拾取部件。** 电极表面沾油污、密封破损会影响信号；电极松动属于结构异常。\n**转换器看铭牌与接线。** 转换器负责信号处理和输出；铭牌、电源、信号端子、说明书要配套。\n【插入式超声波的结构与边界】\n**插入式超声波流量计带压开孔插入管道。** 卡上 DN80–DN2400，精度±1%；传感器、球阀底座、信号电缆是基本构成。\n**直管段是安装边界，也是验收可查项。** 卡上写上游≥10D、下游≥5D；说明书和配套清单要能体现这一要求。\n**传感器与球阀底座要配套。** 球阀开闭灵活、插入深度标识清楚，才说明底座与传感器匹配。\n**防护等级看铭牌。** 户外或井下安装要看 IP 等级；室内型不能当户外型用。\n【检定与标准依据】\n**电磁流量计检定看 JJG 1033。** 卡上注明检定规程版本采购时确认；检定证书与版本要能对上。\n**插入式超声波看 GB/T 35138-2017、JJG 1030-2007。** 标准号与检定证书是验收依据；标准号对不上属于依据异常。\n**远传水表看 GB/T 778 系列和 CJ/T 188-2018。** 通信规约与检定标识要配套；贸易结算表还要看强制检定。\n**状态栏决定现用属性。** 非现用先隔离，不凭型号相似放行。\n【附件与包装】\n**流量计附件多，缺一件都影响使用。** 传感器、转换器、电缆、说明书、合格证要齐全；缺件属于资料或配套不完整。\n**电缆长度和接头要核。** 电缆标识、接头型式要与卡面和系统匹配；短了或接头不对，现场接不上。\n**包装防潮防震。** 转换器受潮、显示屏裂纹属于外观异常；受潮件不能直接进现用区。\n**说明书和参数表要随货归档。** 后续调试、维修、复核都要用；缺说明书属于资料不完整。\n\n**自测：远传水表通信接口不匹配会怎样？** 回本课【远传水表的两类通信】对照。\n\n**自测：电磁流量计验收要看哪些结构？** 回本课【电磁流量计的结构要点】对照。","structure":"主链：远传分族→通信接口→电磁结构→插入式底座直管段→检定标准→附件包装。\n对照：光电直读 vs NB-IoT；电磁 vs 插入式超声波；M-BUS vs RS-485。\n要点：1 通信接口要匹配；2 电磁看电极衬里；3 插入式看底座直管段；4 检定规程版本要核；5 附件说明书要齐。\n引导：本课已建立远传与流量计的知识骨架；现场常见问题是通信接口不匹配；下一步 C68 讲密封紧固与抢修辅材验收。","anchors":[{"name":"光电直读远传水表","ref":"光电直读远传水表"},{"name":"水平螺翼机械水表","ref":"水平螺翼机械水表"},{"name":"电磁流量计","ref":"电磁流量计"},{"name":"插入式超声波流量计","ref":"插入式超声波流量计"}],"pitfall":"【通信接口不匹配装上也白装】电磁看衬里电极；插入式看直管段；检定证书对编号。","remark":"NB-IoT 智能水表在知识块讲，锚点用公司现用水平螺翼机械水表","seq":83,"family":"CL-01 材料验收入库与标准核对","lessonNo":11},{"id":"C68","sub":"CL-01","topic":"密封紧固与抢修辅材验收：胶垫、胶圈、螺栓与哈夫节","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲密封、紧固与抢修辅材这一类小件知识：胶垫与胶圈的结构差异、EPDM 与 NBR 的介质边界、半丝与全丝螺栓的受力差异、哈夫节与 AB 胶的用途边界、牺牲阳极的防腐原理。它承接管材阀门验收，向下衔接井室消防设施。","framework":"密封件｜胶垫（法兰用）、胶圈（承插用）。\n材质｜给水默认 EPDM，含油选 NBR。\n紧固件｜六角头螺栓半丝/全丝、等级。\n抢修件｜哈夫节（堵漏器）、AB胶。\n防腐件｜镁合金牺牲阳极、填包料。\n标准状态｜GB/T 9126.1、GB/T 21873、GB/T 5782、YB/T 4652、GB/T 17731。\n包装存放｜避光、防油、防潮。","lecture":"**相邻关系：向上接 C67《远传水表与流量计验收》；向下接 C69《井室与消防设施验收》。**\n\n**现场情境：胶圈沾了油擦一擦就想用，螺栓半丝全丝也混在一起。** 验收怎么判？本课讲密封紧固辅材。\n\n【胶垫（法兰橡胶垫片）与胶圈的结构差异】\n**胶垫（法兰橡胶垫片）是法兰之间的平垫片。** 卡上胶垫（法兰橡胶垫片）DN15–DN1200，标准 GB/T 9126.1-2023；平圆形、带螺栓孔，靠法兰压紧填隙密封。\n**胶圈（球墨管承插密封圈）是承插口的环形密封圈。** 卡上胶圈（球墨管承插密封圈）DN100–DN1200，材料执行 GB/T 21873-2025；厚实环形、无螺栓孔，靠插口插入后受压回弹密封。\n**结构不同决定用途不同。** 胶垫（法兰橡胶垫片）用于法兰对接，胶圈用于承插接口；拿胶垫（法兰橡胶垫片）去承插口，或拿胶圈去法兰，都装不上。\n**给水默认 EPDM，含油选 NBR。** EPDM 耐水、耐温≤120℃，但怕油；含油介质要 NBR。橡胶件怕油怕晒，老化裂纹、永久变形都是异常信号。\n【半丝与全丝螺栓的受力差异】\n**半丝螺栓带光杆，用于法兰对接。** 卡上六角头螺栓（半丝/全丝）M6–M36，4.8/8.8 级，标准 GB/T 5782-2016；光杆段在法兰孔内承受横向剪切力，保证对中。\n**全丝螺栓全长螺纹，用于管卡支架。** 螺母可在任意位置停留，适应不同厚度固定；全丝当半丝用，法兰孔对中差。\n**等级看螺栓头标。** 4.8、8.8 级在头部有标记；低等级上高压法兰，受力不足。\n**锈蚀和螺纹损伤是紧固件异常。** 螺纹不完整、镀锌层大面积脱落，会影响预紧力。\n【哈夫节（堵漏器）与 AB 胶的用途边界】\n**哈夫节（堵漏器）是两片式抱箍堵漏器。** 卡上哈夫节（堵漏器）DN50–DN1000，标准 YB/T 4652-2018；壳体、橡胶垫、螺栓三件配套，靠抱箍压紧橡胶垫止漏。\n**哈夫节（堵漏器）橡胶垫默认 EPDM。** 垫片老化、裂纹会让抱箍失效；垫片是哈夫节（堵漏器）的功能件，不是附件。\n**AB胶（管道修补剂）是双组分管道修补剂。** 卡上 AB胶（管道修补剂），A 组树脂、B 组固化剂；混合后固化形成封堵层，用于小孔砂眼应急堵漏。\n**AB胶（管道修补剂）不是结构胶。** 它不承力，不能替代哈夫节（堵漏器）或管件；用途说明要看清楚。\n【牺牲阳极的防腐原理】\n**镁合金牺牲阳极靠电化学保护钢管。** 卡上镁合金牺牲阳极，标准 GB/T 17731-2015；镁电位更负，与钢管连接后优先腐蚀，保护钢管。\n**填包料降低接地电阻。** 石膏粉、膨润土、无水硫酸钠配的填包料保持阳极活性；填包料缺失或受潮，阳极效率下降。\n**阳极看重量和表面。** 标识重量与卡面一致；表面严重氧化、变形属于外观异常。\n**电缆线看长度和接头。** 电缆标识、焊接片要配套；短了或接头不对，现场接不上。\n【标准状态与存放】\n**标准号要跟卡面一致。** 胶垫（法兰橡胶垫片） GB/T 9126.1-2023、胶圈 GB/T 21873-2025、螺栓 GB/T 5782-2016、哈夫节（堵漏器） YB/T 4652-2018、阳极 GB/T 17731-2015。\n**状态栏决定现用属性。** 非现用先隔离，不凭“都能用”放行。\n**橡胶件避光防油。** 和油品混放会加速老化；库位要避光。\n**螺栓防潮防锈。** 包装受潮、锈蚀螺栓不能进现用区。\n\n**自测：胶圈沾油擦擦还能不能用？** 回本课【胶垫（法兰橡胶垫片）与胶圈的结构差异】对照。\n\n**自测：法兰连接该用半丝还是全丝螺栓？** 回本课【半丝与全丝螺栓的受力差异】对照。","structure":"主链：胶垫胶圈→橡胶材质→半丝全丝→哈夫节AB胶→牺牲阳极→标准状态→存放。\n对照：胶垫 vs 胶圈；半丝 vs 全丝；哈夫节 vs AB胶；阳极 vs 普通金属。\n要点：1 胶垫法兰用、胶圈承插用；2 EPDM 怕油；3 半丝抗剪、全丝调节；4 哈夫节看橡胶垫；5 阳极看填包料电缆。\n引导：本课已建立密封紧固与抢修辅材的知识骨架；现场常见问题是胶圈沾油仍放行；下一步 C69 讲井室与消防设施验收。","anchors":[{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"镁合金牺牲阳极","ref":"镁合金牺牲阳极"}],"pitfall":"【胶圈不能沾油】EPDM 怕油怕晒；半丝抗剪、全丝调节；哈夫节橡胶垫老化先待检。","remark":"—","seq":84,"family":"CL-01 材料验收入库与标准核对","lessonNo":12},{"id":"C69","sub":"CL-01","topic":"井室与消防设施验收：井盖与消火栓","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲井室与消防设施这一类地面设施知识：球墨铸铁井盖与复合井盖的材质差异、D400 与 A15 的承载等级、给水与消防的功能标识、地上式与地下式消火栓的结构差异、标准换版边界。它承接辅材验收，向下衔接补偿器与转换接头。","framework":"井盖类型｜球墨铸铁、复合。\n承载等级｜D400 重型、A15/B125/C250。\n功能标识｜给水、消防、阀门井字样。\n井盖附件｜井座、减震胶条、防盗铰链锁具。\n消火栓类型｜地上式、地下式。\n标准换版｜GB 4452-2011 与 2026 版切换。\n包装外观｜裂纹、变形、标识清晰。","lecture":"**相邻关系：向上接 C68《密封紧固与抢修辅材验收》；向下接 C70《补偿器与转换接头验收》。**\n\n**现场情境：车行道井盖到货，有人想用复合轻型盖；消火栓地上地下也没分清。** 怎么验？本课讲井室消防设施。\n\n【球铁井盖与复合井盖的材质差异】\n**球墨铸铁井盖强度高、承载大。** 卡上球墨铸铁井盖（给水/消防）Φ700，D400 重型，标准 GB/T 23858-2009、CJ/T 511-2017；盖体厚重、带铰链锁具。\n**复合井盖轻、无回收价值。** 卡上复合井盖（给水/消防）SMC/树脂复合材料，A15/B125/C250；盖体较轻、内嵌钢筋骨架，防盗性突出。\n**材质差异决定承载等级。** 车行道和消防通道按 D400 重型；复合井盖不能上重车道，消防通道也要按 D400 核。\n**功能标识是运维识别依据。** 盖面“给水”或“消防”字样要清楚；字样不清会影响识别，属于标识异常。\n【井盖附件与防盗结构】\n**井座和盖体要配套。** 井座尺寸、承托面、减震胶条要匹配；盖座不配套会跳响。\n**防盗铰链和锁具是功能件。** 铰链、锁芯、钥匙缺失，防盗功能不完整。\n**减震胶条看老化。** 胶条脱落、硬化会让车辆碾压异响；胶条属于井盖附件。\n**盖体裂纹变形是结构异常。** 裂纹、变形、掉角会影响承载；有裂纹直接待检。\n【地上式与地下式消火栓】\n**地上式消火栓栓体露出地面。** 卡上地上式消火栓 SS100/65-1.6，标准 GB 4452-2011；红色栓体、出水口、阀门、排水口是基本构成。\n**地下式消火栓设在井内。** 卡上地下式消火栓 SA100/65-1.6；栓体、弯管、出水口、井盖是基本构成，地面只留井盖和启闭杆。\n**地上与地下按防冻和交通条件分。** 防冻地区多用地下式，交通繁忙地段也常地下；型式要与设计一致。\n**消火栓不是给水阀门。** 功能标识和出水口是区别依据；不能和闸阀、蝶阀混。\n【标准换版边界】\n**消火栓现行标准是 GB 4452-2011。** 卡上备注 GB 4452-2026 于 2027-02-01 实施，届时切换；到货日期在切换日前后，核对依据不同。\n**切换日前后判断依据。** 切换后按新版核；单据旧版与卡上换版提示冲突时先待检。\n**井盖标准看 GB/T 23858-2009、CJ/T 511-2017。** 不能拿旧版或别的材质标准套。\n**标准换版不自行降级。** 拿不准转待检，不凭经验放行。\n【包装外观与状态】\n**井盖看标识和承载等级。** 盖面字样、D400 或 A15 标识要清楚；标识不清属于标识异常。\n**消火栓看栓体和出水口。** 碰撞变形、螺纹损伤、排水口堵塞属于外观异常。\n**状态栏决定现用属性。** 非现用先隔离，不凭“都是井盖”放行。\n**包装看防撞防潮。** 井盖磕角、消火栓变形属于包装或运输异常。\n\n**自测：车行道井盖需要什么承载等级？** 回本课【球铁井盖与复合井盖的材质差异】对照。\n\n**自测：地上式和地下式消火栓怎么区分？** 回本课【地上式与地下式消火栓】对照。","structure":"主链：井盖材质→承载等级→功能标识与锁具→地上地下消火栓→标准换版→包装状态。\n对照：球铁井盖 vs 复合井盖；D400 vs A15；地上式 vs 地下式消火栓。\n要点：1 车行道 D400；2 消防井盖有标识；3 井盖锁具不能缺；4 消火栓分地上地下；5 标准换版看到货日期。\n引导：本课已建立井盖与消火栓的知识骨架；现场常见问题是复合井盖上了重车道；下一步 C70 讲补偿器与转换接头验收。","anchors":[{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"复合井盖（给水/消防）","ref":"复合井盖（给水/消防）"},{"name":"地上式消火栓","ref":"地上式消火栓"},{"name":"地下式消火栓","ref":"地下式消火栓"}],"pitfall":"【车行道必须 D400】复合井盖不上重车道；消防井盖看标识；消火栓分地上地下。","remark":"—","seq":85,"family":"CL-01 材料验收入库与标准核对","lessonNo":13},{"id":"C70","sub":"CL-01","topic":"补偿器与转换接头验收：橡胶接头、伸缩节与法兰连接器","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲补偿器与转换接头这一类管道位移补偿与转换件知识：可曲挠橡胶接头的球体与限位、球墨铸铁伸缩节 B2F/C2F 的限位与传力差异、多功能法兰连接器的防脱结构、波纹管补偿器的拉杆与波纹管。它承接井室设施，向下衔接验收留痕与异常处置。","framework":"可曲挠橡胶接头｜单/双球体、法兰、限位螺栓。\n球墨铸铁伸缩节｜B2F 限位型、C2F 传力型。\n多功能法兰连接器｜防脱锁紧环、锥形胶圈、伸缩套管。\n波纹管补偿器｜轴向型、拉杆、波纹管。\n标准状态｜GB/T 26121、GB/T 12465、GB/T 12777。\n外观附件｜橡胶球体、压盖、螺栓、法兰。","lecture":"**相邻关系：向上接 C69《井室与消防设施验收》；向下接 C71《验收留痕、拒收隔离与入库上架》。**\n\n**现场情境：补偿器到货，橡胶接头限位螺栓缺了几颗，波纹管拉杆也被拆过。** 能不能收？本课讲验收。\n\n【可曲挠橡胶接头的结构与限位】\n**可曲挠橡胶接头中间是橡胶球体。** 卡上 KXT 单/双球体，DN32–DN3000，标准 GB/T 26121-2010；橡胶球体加两端法兰，靠橡胶弹性吸收振动与位移。\n**给水默认 EPDM，含油选 NBR。** 橡胶球体有油污、裂纹、老化，会影响弹性与密封。\n**限位螺栓是防拉脱功能件。** 限位螺栓、螺母齐全，才能在水压作用下限制过度拉伸；缺限位螺栓，球体可能被拉脱。\n**电焊火花会烧穿橡胶。** 球体烫伤、鼓包属于结构异常。\n【B2F 与 C2F 的限位与传力差异】\n**B2F 是限位型。** 卡上球墨铸铁伸缩节（限位型/传力型），DN50–DN2000，标准 GB/T 12465-2017；B2F 配限位双螺母，允许伸缩但到极限会锁定防拉脱。\n**C2F 是传力型。** C2F 配传力螺杆，把盲板推力传至管道，保护泵阀；它不靠伸缩吸位移。\n**B2F 吸位移、C2F 传推力。** 铭牌和结构是区分依据；C2F 当 B2F 用，位移没人吸收。\n**压盖和橡胶圈要配套。** 压盖、密封圈、螺栓缺件属于结构不完整。\n【多功能法兰连接器（防脱法兰/伸缩法兰接头）的防脱结构】\n**多功能法兰连接器（防脱法兰/伸缩法兰接头）一端承插锁紧、一端法兰。** 卡上 DN50–DN600，PN10/16；防脱锁紧环、锥形胶圈、伸缩套管是基本构成。\n**防脱锁紧环是关键件。** 锁紧环、压盖、螺栓齐全，防脱功能才完整；缺锁紧环，防脱失效。\n**锥形胶圈看老化。** 胶圈（球墨管承插密封圈）裂纹、变形会让承插端渗漏。\n**法兰端看标准和孔距。** 对照 GB/T 9124.1 法兰接口；孔距不对装不上。\n【波纹管补偿器的拉杆与波纹管】\n**轴向型波纹管补偿器靠波纹管伸缩。** 卡上 DN32–DN4000，标准 GB/T 12777-2019；波纹管、接管、端法兰、限位拉杆是基本构成。\n**拉杆承受内压推力。** 拉杆、螺母齐全，才能限制波纹管过度位移；缺拉杆会拉飞。\n**波纹管看磕碰和裂纹。** 波纹管薄，凹陷、划伤属于结构异常。\n**轴向型不是横向型。** 铭牌和结构是区分依据；拿横向型当轴向用，补偿方向不对。\n【标准状态与附件】\n**标准号要跟卡面一致。** 橡胶接头 GB/T 26121-2010、伸缩节 GB/T 12465-2017、波纹管 GB/T 12777-2019。\n**状态栏决定现用属性。** 非现用先隔离，不凭“都是补偿器”放行。\n**法兰和螺栓要配套。** 法兰孔数、螺栓等级要与卡面一致。\n**包装看防撞。** 橡胶球体挤压、波纹管磕碰属于包装或运输异常。\n\n**自测：B2F 和 C2F 的限位传力差别是什么？** 回本课【B2F 与 C2F 的限位与传力差异】对照。\n\n**自测：波纹管补偿器的拉杆能不能拆？** 回本课【波纹管补偿器的拉杆与波纹管】对照。","structure":"主链：橡胶接头→B2F/C2F→多功能法兰防脱→波纹管拉杆→标准状态→附件包装。\n对照：B2F vs C2F；橡胶接头 vs 伸缩节；多功能法兰 vs 普通法兰。\n要点：1 橡胶接头限位螺栓要齐；2 B2F 限位、C2F 传力；3 多功能法兰看锁紧环；4 波纹管拉杆不能缺；5 非现用先隔离。\n引导：本课已建立补偿器与转换接头的知识骨架；现场常见问题是 C2F 当 B2F 用；下一步 C71 讲验收留痕、拒收隔离与入库上架。","anchors":[{"name":"可曲挠式橡胶接头","ref":"可曲挠式橡胶接头"},{"name":"球墨铸铁伸缩节（限位型/传力型）","ref":"球墨铸铁伸缩节（限位型/传力型）"},{"name":"多功能法兰连接器（防脱法兰/伸缩法兰接头）","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"}],"pitfall":"【B2F 限位、C2F 传力】橡胶接头限位螺栓要齐；波纹管拉杆不能拆；多功能法兰看锁紧环。","remark":"波纹管补偿器在知识块讲，锚点只列三张公司现用卡","seq":86,"family":"CL-01 材料验收入库与标准核对","lessonNo":14},{"id":"C71","sub":"CL-01","topic":"验收留痕、拒收隔离与入库上架：单据闭环与现场控制","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲验收流程中的记录、隔离与上架知识：验收记录应包含哪些要素、拒收与隔离的区别、待检区与现用区的物理边界、入库上架的先决条件与先进先出原则、单据闭环与系统状态一致。它承接分材料验收，向下衔接同名不同物辨析。","framework":"验收记录｜课程号、卡名、批次、数量、异常点、处理动作。\n拒收判定｜单据不符、标准不符、非现用、老化破损。\n隔离控制｜待检区、红黄标识、物理隔离。\n入库上架｜合格区、现用区、先进先出。\n单据闭环｜送货单、合格证、检定证书、验收记录。\n异常上报｜谁判、谁批、谁复核。\n系统状态｜平台状态与实物一致。","lecture":"**相邻关系：向上接 C70《补偿器与转换接头验收》；向下接 C72《同名不同物辨析》。**\n\n**现场情境：验收完只在群里发了张照片就算留痕，待检件还和现用件混放。** 这样对吗？本课讲单据闭环。\n\n【验收记录的要素】\n**验收记录要能追溯。** 课程号、卡名、批次、数量、异常点、处理动作是基本要素；只有照片没有记录，追溯就断。\n**记录要跟单据对应。** 送货单、合格证、检定证书、验收记录的编号和批次要能对上；对不上属于单据异常。\n**处理动作要明确。** 合格、待检、拒收、降级要写清；只写“已收”等于没有判定。\n**记录是复盘依据。** 少一项要素，后续追责和复盘就缺一环。\n【拒收与隔离的区别】\n**拒收是判定，隔离是现场控制。** 拒收表示这批货不符合接收条件；隔离是防止异常件被误领误用。\n**待检区要物理分开。** 围栏、标识、台账是待检区的基本配置；混在现用区，容易发错。\n**红黄标识要清楚。** 待检、不合格、退货标识要能一眼区分；标识不清等于没有隔离。\n**隔离要写原因。** 隔离原因、数量、批次要写在标识上；只挪走不写，后面没人知道为什么。\n【入库上架的先决条件】\n**合格才能进现用区。** 平台状态和实物标识要一致；非现用、待检件不能上现用架。\n**上架要先进先出。** 库位标识、批次顺序要清楚；老批次压在新批次下面，容易过期。\n**不同材料有不同防护要求。** 球墨铸铁管垫软物、胶圈避光、井盖防撞、PE 管遮阳；上架方式要跟材料特性匹配。\n**堆高和承重要控制。** 堆太高会变形或倒塌；上架不是堆上去。\n【单据闭环与系统状态】\n**单据闭环是验收完成的标志。** 送货单、合格证、验收记录、入库单齐全，闭环才完整；缺一张，闭环就断。\n**系统状态要跟实物一致。** 平台“公司现用”标识与实物标签不一致，先查再上架。\n**异常上报要写清。** 异常类型、批次、数量、已做措施要记录；只写“有问题”，别人没法处理。\n**复核不能省。** 拒收或待检要有复核人；自己判自己复核，等于没有复核。\n【现场控制与防混】\n**待检区不能和现用区混。** 物理隔断、地标线是基本要求；混放是发错料的根源。\n**退货区要单独设。** 退货标识和台账要独立；退货和待检混在一起，容易二次流入。\n**批次混装先分开。** 同箱不同规格、不同标准，先物理分开再逐项判。\n**记录要可检索。** 按课程号、卡名、批次归档；乱堆一起，查的时候找不到。\n\n**自测：验收留痕是不是拍张照片发群就行？** 回本课【验收记录的要素】对照。\n\n**自测：拒收和隔离分别是什么意思？** 回本课【拒收与隔离的区别】对照。","structure":"主链：记录要素→拒收与隔离→入库上架→单据闭环→系统状态→现场防混。\n对照：拒收 vs 隔离；待检区 vs 现用区；留痕 vs 拍照发群。\n要点：1 留痕写课程号卡名批次；2 拒收是判定、隔离是控制；3 待检区物理分开；4 合格才上现用架；5 单据闭环可追溯。\n引导：本课已建立验收留痕与隔离的知识骨架；现场常见问题是只拍照不写记录；下一步 C72 讲同名不同物辨析。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"复合井盖（给水/消防）","ref":"复合井盖（给水/消防）"},{"name":"沟槽卡箍（刚性/柔性）","ref":"沟槽卡箍（刚性/柔性）"},{"name":"PE给水管","ref":"PE给水管"}],"pitfall":"【留痕不是拍照发群】拒收是判定、隔离是控制；待检区不能混现用区；合格才上架。","remark":"—","seq":87,"family":"CL-01 材料验收入库与标准核对","lessonNo":15},{"id":"C72","sub":"CL-01","topic":"同名不同物辨析：法兰族与端头族","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课讲验收中同名不同物这一类辨析知识：法兰族里 PE 法兰头、钢法兰、PPR 法兰、衬塑法兰的材质与标准差异；端头族里盘插、盘承、双承、双盘短管的端头组合差异；以及“同名不同标准、同端不同材质”的辨认顺序。它承接分材料验收与留痕，向下衔接到货异常处置。","framework":"法兰族｜PE 法兰头/片、钢法兰、PPR 法兰、衬塑法兰。\n端头族｜盘插短管、盘承短管、双承短管、双盘短管。\n材质差异｜塑、钢、球铁、衬塑。\n标准差异｜GB/T 13663、GB/T 9124.1、GB/T 18742、GB/T 28897、GB/T 13295。\n端头识别｜法兰端、承口、插口、双承、双盘。\n验收动作｜看端头、看材质、看标准、看标识。\n常见混发｜PE 法兰头当钢法兰、盘承当盘插。","lecture":"**相邻关系：向上接 C71《验收留痕、拒收隔离与入库上架》；向下接 C73《到货异常判别与隔离处置》。**\n\n**现场情境：法兰族里有 PE 法兰头、钢法兰、PPR 法兰，看着都叫法兰就混着发。** 错在哪？本课讲同名不同物。\n\n【法兰族四类的材质与标准】\n**PE 法兰头/片是塑-金属转换件。** 卡上PE法兰头/片，一端 PE 可熔端、一端法兰盘，标准 GB/T 13663.3-2018；可熔端是它与钢法兰（平焊/对焊）的关键区别。\n**钢法兰（平焊/对焊）是钢制管件。** 卡上钢法兰（平焊/对焊），标准 GB/T 9124.1-2019；平焊平盘、对焊带颈，都是钢制。\n**PPR 法兰（法兰转换）是 PPR 管件。** 卡上一端热熔、一端法兰盘，标准 GB/T 18742.3-2017；热熔端和塑料法兰盘是辨认依据。\n**衬塑法兰是衬塑管件。** 卡上法兰，执行标准 GB/T 28897-2021（附录 B 规范性，衬塑管件）；衬塑密封面和螺栓孔是辨认依据。\n【法兰族不能混标准】\n**同名“法兰”不等于同标准。** 卡名和材质是第一步；PE 法兰头套钢法兰（平焊/对焊）标准，压力等级就错。\n**PE 法兰头不是钢法兰（平焊/对焊）。** 没有 PE 可熔端，就不是 PE 法兰头。\n**PPR 法兰不是衬塑法兰。** PPR 是塑料本体，衬塑是钢基体衬塑；热熔端与衬塑面是区别。\n**衬塑法兰要配软垫片。** 密封面衬塑层缺失或掉塑，属于结构异常。\n【端头族四类的端头组合】\n**盘插短管一端法兰一端插口。** 卡上 DN100–DN1200，标准 GB/T 13295-2019；插口是小头。\n**盘承短管一端法兰一端承口。** 承口是大头；盘承接纳插口，盘插插入承口。\n**双承短管两端承口。** 两端都是大头，用于直线延长或接驳两段插口。\n**双盘短管两端法兰。** 两端都是法兰盘，用于两端法兰设备之间转接。\n【端头拿反是高频错】\n**盘承与盘插最容易拿反。** “承口接纳、插口插入”是辨认口诀；拿反了装不上。\n**双承不是双盘。** 看端头有没有法兰盘；双承两端承口，双盘两端法兰。\n**端头族不是法兰族。** 先分“带不带法兰盘”，再分承口插口；混在一起必错。\n**端头看密封槽。** 承口密封槽、插口端面磕碰变形，属于结构异常。\n【验收辨认顺序】\n**看端头是第一步。** 法兰盘、承口、插口先分清；端头不对，后面标准都白核。\n**看材质是第二步。** 塑、钢、球铁、衬塑，材质不同标准不同。\n**看标准是第三步。** 对照卡面标准号；标准号对不上先待检。\n**看标识是第四步。** 喷码、标签、卡名；标识不清不凭经验放行。\n【常见混发与防雷】\n**PE 法兰头当钢法兰（平焊/对焊）发。** 看可熔端；没有可熔端就是混发。\n**盘承当盘插发。** 看承口插口；拿反了现场装不上。\n**PPR 法兰当衬塑法兰发。** 看热熔端和衬塑面；两者标准和材质都不同。\n**同名不同物先隔离。** 拿不准先待检；不凭名字发料，是防混发的底线。\n\n**自测：PE 法兰头能不能当钢法兰用？** 回本课【法兰族四类的材质与标准】对照。\n\n**自测：盘承和盘插哪个接纳直管？** 回本课【端头族四类的端头组合】对照。","structure":"主链：看端头→看材质→看标准→看标识→分法兰族/端头族→拿不准待检。\n对照：PE 法兰头 vs 钢法兰；PPR 法兰 vs 衬塑法兰；盘承 vs 盘插；双承 vs 双盘。\n要点：1 法兰同名不同标准；2 PE 法兰头看可熔端；3 盘承接纳、插口插入；4 双承双盘看端头；5 拿不准先待检。\n引导：本课已建立法兰族与端头族的辨析骨架；现场常见问题是盘承盘插拿反；下一步 C73 讲到货异常判别与隔离处置。","anchors":[{"name":"PE法兰头/片","ref":"PE法兰头/片"},{"name":"钢法兰（平焊/对焊）","ref":"钢法兰（平焊/对焊）"},{"name":"沟槽法兰","ref":"沟槽法兰"},{"name":"盘插短管","ref":"盘插短管"},{"name":"盘承短管","ref":"盘承短管"}],"pitfall":"【盘承接纳、插口插入】PE 法兰头别当钢法兰；PPR 法兰别当衬塑法兰；同名不同物先待检。","remark":"PPR 法兰在知识块讲，锚点用公司现用法兰","seq":88,"family":"CL-01 材料验收入库与标准核对","lessonNo":16},{"id":"C98","sub":"GW-01","topic":"缺陷分级与易混淆情形辨析","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课解决巡检一线“判不准、分不清”的核心痛点，讲解缺陷三级判定标准、四类高频易混淆缺陷的对照区分、责任边界判定与上报边界，对应D3“分得清、判得准”的认知层级，是巡检能力从“会找”到“会判”的核心进阶。","framework":"缺陷三级分级标准｜一般缺陷、较重缺陷、重大缺陷量化判定阈值与划分依据。\n渗漏类易混辨析｜接口渗漏vs井内积水渗返vs冷凝潮湿vs地下水倒灌四组对照区分。\n锈蚀类易混辨析｜正常浮锈vs均匀腐蚀vs点蚀穿孔边界与危害差异。\n老化类易混辨析｜橡胶件自然老化vs外力破损vs安装不当渗漏成因与特征对照。\n损坏类易混辨析｜自然失效vs第三方破坏vs施工遗留损伤责任边界判定。\n紧急情形识别｜需立即处置的重大隐患特征、上报升级触发条件、临时管控要求。\n上报边界辨析｜可观察跟踪、需登记上报、应立即处置三类情形划分标准与常见误区。","lecture":"**相邻关系：向上接 C101《管道防腐层与阴极保护设施巡检》；向下接 C102《暗漏征兆识别与初步听漏排查方》。**\n\n**现场情境：井内有水、阀体有浮锈、密封件渗漏，巡检员一股脑都归成自然老化。** 这样分级对吗？本课讲缺陷辨析。\n\n【缺陷三级分级标准：先定等级再上报】\n缺陷按严重程度分三级，判定要有依据。一般缺陷是程度轻、不影响正常运行、短期内无风险的问题，比如井盖轻微缺损、阀体表面浮锈、橡胶件早期龟裂，可纳入日常观察；\n较重缺陷是影响设备功能、发展后会扩大风险的问题，比如接口持续滴水、防腐层成片脱落、阀门启闭轻度卡涩，需要登记上报安排计划处理；\n重大缺陷是随时可能引发事故、影响供水安全的问题，比如管道穿孔大量漏水、井室坍塌、阀门完全卡死、重大占压，必须立刻上报、现场管控。具体量化阈值按企业管网运维标准执行。\n【渗漏类易混辨析：四种水各有来头】\n井内有水不一定是管道漏，四种情况要分清。接口渗漏是清水、持续渗出，水源位置在接口或阀体，旱天也存在，越漏越大；井内积水渗返是地下水从井壁、井底渗进来，多是浑水、雨天更严重，水位随地下水位变化；\n冷凝潮湿是夏季井壁、管壁结的水珠，量少、清亮，气温高时出现，气温降了就消失；地下水倒灌是雨水、污水从井盖缝隙倒灌，有异味、夹带泥沙，大雨过后最明显。看水质、看位置、看天气变化，基本能分清。\n【锈蚀类易混辨析：三层程度差很多】\n锈蚀不是都一样，三层边界要划清。正常浮锈是表面一层薄锈、用抹布能擦掉，基体完好没有坑，属于外观问题，不影响结构；均匀腐蚀是整个表面普遍锈蚀、厚度均匀减薄，发展慢，到一定程度才影响强度；\n点蚀穿孔是局部凹坑、深度大、发展快，表面看着小洞，里面可能已经穿了，危害性远大于均匀腐蚀。不能看见锈就说腐蚀严重，也不能觉得是浮锈就不管，要分层判断。\n【老化类易混辨析：橡胶渗漏三种成因】\n橡胶件漏水，不一定都是自然老化。自然老化是整体龟裂、变硬、失去弹性，全周均匀渗漏，使用年限久；外力破损是局部裂口、划痕、磕碰伤，渗漏位置和破损点对应，有明显外力痕迹；\n安装不当渗漏是胶圈扭曲、偏位、没装到位，渗漏不均匀，重新安装后就能解决。自然老化要换件，外力破损要追责，安装不当要重装，成因不同处置完全不同。\n【损坏类易混辨析：责任边界要分清】\n同样是管道损坏，责任归属不一样。自然失效是服役到期、正常老化损坏，没有外力痕迹，发展过程平缓；第三方破坏是有明显的机械开挖、碾压、撞击痕迹，周边有施工痕迹，属于外部责任；\n施工遗留损伤是安装时就留下的磕碰、防腐破损、接口没装到位，投用后慢慢发展成缺陷，属于施工质量问题。判定时结合周边环境、缺陷形态、投用时间综合判断，不随便下结论。\n【紧急情形识别：这些情况要立刻升级】\n遇到六种情况必须立刻上报、现场管控。一是路面大量清水涌出、管道明显破裂；二是井室大面积坍塌、井盖坠落缺失；三是违章占压、施工挖掘即将破坏主干管；四是阀门断裂、消火栓被撞断，大量跑水；\n五是有毒有害气体泄漏、有中毒风险；六是管线沉降、路面塌陷有扩大趋势。这些情形不能等常规流程，要第一时间报调度、设围挡、守现场，防止事态扩大。\n【上报边界辨析：三类情形别搞混】\n上报不是什么都立刻报，也不是什么都压着。可观察跟踪的是轻微、稳定、无扩大风险的缺陷，定期看就行，不用单独上报；需登记上报的是较重、发展中、需要计划处理的缺陷，按周期录入台账、安排整改；\n应立即处置的是重大、紧急、随时出事的缺陷，必须第一时间升级。最常见的误区是把重大缺陷当一般问题拖着不报，或者把轻微缺陷当重大事故小题大做。\n\n**自测：看到部件损坏能不能一律归为自然老化？** 回本课【损坏类易混辨析：责任边界要分清】对照。\n\n**自测：浮锈需不需要立刻更换？** 回本课【锈蚀类易混辨析：三层程度差很多】对照。","structure":"主链：先定缺陷等级→再辨析易混情形→判定责任边界→识别紧急情形→明确上报边界。\n要点：1 缺陷分一般、较重、重大三级；2 渗漏分清接口漏、渗返、冷凝、倒灌；3 锈蚀分浮锈、均匀腐蚀、点蚀穿孔；4 橡胶渗漏分老化、外力、安装不当；5 损坏分自然失效、第三方破坏、施工遗留；6 六种紧急情形立刻升级；7 三类上报边界要分清。\n引导：本课解决判不准的痛点；现场常卡在内渗水和管道漏分不清；下一步C102讲暗漏征兆与听漏排查。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"可曲挠式橡胶接头","ref":"可曲挠式橡胶接头"},{"name":"直缝焊接钢管","ref":"直缝焊接钢管"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"减压型倒流防止器","ref":"减压型倒流防止器"}],"pitfall":"【井内有水不一定是管道漏水】雨水倒灌、地下水渗返都可能导致井内积水；浮锈不用立刻换，但要跟踪观察；不能一看到损坏就归为自然老化，要先排查外力因素。","remark":"—","seq":89,"family":"GW-01 日常巡检与材料缺陷识别","lessonNo":6},{"id":"C102","sub":"GW-01","topic":"暗漏征兆识别与初步听漏排查方法","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课补充隐蔽渗漏识别能力，讲解暗漏的五类地面征兆、不同材质管道的漏声特征、基础听漏工具使用与真伪漏水鉴别，覆盖“明察+暗辨”的完整巡检技能，是巡检员的核心进阶能力。","framework":"暗漏五类地面征兆｜路面长期潮湿、植被异常茂盛、清水渗出、异味溢出、路面沉降塌陷识别与真伪判断。\n不同材质管道漏声特征｜PE管、球墨铸铁管、钢管漏水声音差异与传播特性。\n基础听漏工具使用｜听漏棒、听音杆操作方法、接触点位选择、环境干扰排除。\n明漏与暗漏辨析｜直接可见渗漏、隐蔽渗漏、管道渗水边界区分。\n漏点初步定位｜阀门井、消火栓、水表处听音排查顺序与定位逻辑。\n易混淆情形辨析｜地下水渗返、管道冷凝水、绿化浇水、污水渗漏与管网漏水区分方法。\n疑似漏点上报规范｜征兆描述、听音记录、点位标注、取证要求。","lecture":"**相邻关系：向上接 C98《缺陷分级与易混淆情形辨析》；向下接 C99《重点场景专项巡检与缺陷上报闭》。**\n\n**现场情境：地面潮湿就断定有暗漏，听漏时没声音又说肯定没漏。** 这两种判断错在哪？本课讲暗漏征兆。\n\n【暗漏五类地面征兆：看不见的漏有信号】\n暗漏埋在地下看不见，但地面会有征兆。第一路面长期潮湿，晴天也干不了，沿管线走向呈条带状，排除下雨、洒水后仍存在，大概率是暗漏；\n第二植被异常茂盛，管线正上方草长得比周边高、颜色更绿，是漏水持续浇灌的结果；第三清水渗出，低洼处、井边有清水持续冒出，水量稳定，不是雨水积水；第四异味溢出，清水带腥味、污水带臭味，沿管线扩散；\n第五路面沉降塌陷，漏水长期冲刷冲走土壤，形成空洞，路面逐步凹陷甚至坍塌。\n【不同材质管道漏声特征：听声音辨材质】\n不同材质的管道，漏水声音不一样。球墨铸铁管刚性好，漏水声清脆、频率高，“滋滋”声传得远，沿管道传播距离大；钢管漏声偏沉闷，低频为主，焊缝处漏水会带一点震颤声；\nPE管塑料管身软，漏水声衰减快、声音闷，离得稍远就听不清，漏点范围要缩小了查。记住这个特征，听到声音能先预判管道材质，缩小排查范围。\n【基础听漏工具使用：找对点位是关键】\n常用听漏工具是听漏棒和听音杆，用对方法才有效。接触点位要选在阀门、消火栓、水表、井盖等裸露的管道附属设施上，这些地方声音传导最好；\n操作时听漏棒要垂直贴紧金属面，周围保持安静，避开车辆、人流的噪音干扰；环境噪音大的时候，要等车过去、人走开再听，或者选夜间车少的时候复核；\n不能只听一个点就下结论，要沿线多找几个点位对比，声音最大的位置离漏点最近。\n【明漏与暗漏辨析：两种渗漏不一样】\n漏水分明漏和暗漏，处置优先级不同。明漏是直接能看见的漏水，比如路面冒水、接口滴水，位置明确，直接上报处置；暗漏是隐蔽在地下、看不见的漏水，只能通过征兆间接判断，需要进一步核查定位；\n管道渗水是缓慢渗出、水量很小的渗漏，短时间风险不大，但长期会冲刷土壤。不能把地面潮湿直接定性为暗漏，也不能因为看不见漏水就当没隐患。\n【漏点初步定位：三步缩小范围】\n初步定位不用精准到厘米，缩小范围就行。第一步沿管线找阀门井、消火栓、水表井，逐个听，声音大的一侧离漏点近；第二步在两个有声点之间，再找中间的检查井、接口井对比，逐步缩小范围；\n第三步结合地面征兆，潮湿最严重、植被最茂盛的位置，大概率就是漏点上方。巡检只做初步定位，精准定位由专业听漏人员负责，不用越界。\n【易混淆情形辨析：四类假漏水要排除】\n四种情况最容易被当成暗漏，要先排除。第一地下水渗返，低洼处地下水水位高，地面返潮，雨天更明显，和管线走向无关；第二管道冷凝水，夏季温度差大，管壁结露滴水，井内潮湿但没有持续水源；\n第三绿化浇水、洒水车洒水，路面湿是人为的，沿道路分布不沿管线；第四污水管道渗漏，颜色浑、有臭味，位置在污水管线上方。排除这四类，再判定为疑似暗漏。\n【疑似漏点上报规范：说清依据不武断】\n上报疑似暗漏，不能说“肯定漏了”，要说清依据。要写清楚具体位置、地面征兆、听了几个点位、听到什么声音、排除了哪些干扰因素；标注清楚管线走向、疑似漏点范围；配上地面征兆的照片、周边参照物。\n巡检只负责发现征兆、上报疑似，不做最终定论，避免误判。\n\n**自测：地面潮湿为什么不能直接定为暗漏？** 回本课【暗漏五类地面征兆：看不见的漏有信号】对照。\n\n**自测：PE 管听不到漏声就能说没漏吗？** 回本课【不同材质管道漏声特征：听声音辨材质】对照。","structure":"主链：看地面征兆→听漏声特征→用工具排查→分明暗漏→初步定位→排除假漏→规范上报。\n要点：1 暗漏有潮湿、植被、渗水、异味、沉降五类征兆；2 球铁声脆、钢管声闷、PE声小衰减快；3 听漏选阀门、消火栓、水表点位；4 明漏可见、暗漏隐蔽、渗水缓慢；5 三步法缩小漏点范围；6 先排除四类假漏水再定性；7 上报说清依据，不做绝对结论。\n引导：本课补充暗漏识别能力；现场常卡在把绿化浇水当暗漏；下一步C99讲重点场景与上报闭环。","anchors":[{"name":"PE给水管","ref":"PE给水管"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"直缝焊接钢管","ref":"直缝焊接钢管"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"地上式消火栓","ref":"地上式消火栓"},{"name":"旋翼式机械水表（湿式/干式/液封）","ref":"旋翼式机械水表（湿式/干式/液封）"}],"pitfall":"【地面潮湿不等于一定暗漏】要先排除洒水、冷凝、地下水等干扰；巡检只做初步定位，不替代专业听漏；PE管漏水声音传不远，不能听不见就说没漏。","remark":"—","seq":90,"family":"GW-01 日常巡检与材料缺陷识别","lessonNo":7},{"id":"C81","sub":"CL-02","topic":"跨材质混放风险辨析：7 类典型错误场景、物料锚点与处置规则","level":"D3 / L3","d":"D3","l":"L3","positioning":"本课讲跨材质混放的辨析知识，属于 CL-02 子类的风险辨析课；C75–C80 分品类讲“各类物料怎么放”，本课承接这些机理，只讲 7 类错误场景的识别信号与处置规则，并为 C82 呆滞管理、C83 季节性防护提供判据。","framework":"1. 碳钢与不锈钢混放｜电偶腐蚀机理、接触锈蚀后果与处置规则\n2. 橡胶件与油污混放｜溶胀老化机理、密封失效后果与处置规则\n3. 塑料与尖锐件混放｜隐性划伤机理、渗漏隐患后果与处置规则\n4. 仪表与化工辅材混放｜腐蚀受潮机理、精度失效后果与处置规则\n5. 衬塑管与焊接同区｜内衬烧损机理、钢塑离层后果与处置规则\n6. 轻重物料违规混堆｜应力变形机理、结构破坏后果与处置规则\n7. 合格与呆滞料混放｜错发误用机理、质量事故后果与处置规则","lecture":"**相邻关系：向上接 C80《综合辅材仓储养护》；向下接 C82《呆滞物料判定与隔离区标准化管理》。**\n\n**现场情境：不锈钢挨着碳钢、胶圈挨着油桶、待检料混进现用区——库房里全是这类错。** 怎么判？本课讲混放风险。\n\n【导语：不重复机理，只讲错误场景与判据】\n碳钢与不锈钢接触的腐蚀机理在 C78 讲过、橡胶沾油溶胀在 C76 讲过、塑料划伤隐患在 C75 讲过，本课不重复这些机理，只讲你会在库里遇到的混放错误场景、现场识别信号和处置顺序。\n【碳钢与不锈钢混放：接触电偶腐蚀】\n碳钢与不锈钢直接接触，会形成电偶腐蚀，先被腐蚀的是碳钢；不锈钢接触面则可能被碳钢锈迹污染而生锈。\n不锈钢的防锈能力来自表面极薄的钝化膜。\n碳钢电位更低，二者接触形成微电池时碳钢是阳极、加速腐蚀，不锈钢是阴极、本来受保护；真正让不锈钢接触面出问题的是碳钢锈迹与铁离子迁移附着，破坏局部钝化膜，形成缝隙污染锈蚀。\n短期看不出问题，时间一长接触面就会出现明显锈斑（出现快慢受湿度影响，以现场检查为准）。\n落回卡上：对照六角头螺栓（半丝/全丝）、不锈钢户表控制箱。\n正确规则：二者之间用纸板或塑料膜隔离，分区分架存放。\n【橡胶件与油污混放：溶胀老化的密封杀手】\n橡胶件接触油污会发生溶胀，永久失去弹性与密封能力。\n给水常用的 EPDM 橡胶，耐水但不耐矿物油。\n机油、黄油会渗入橡胶分子链，让胶圈变软发黏、永久变形。\n压缩回弹率大幅下降，装到管道上一打压就渗漏。\n落回卡上：对照胶圈（球墨管承插密封圈）、胶垫（法兰橡胶垫片）。\n正确规则：橡胶件单独密封存放，油品单独设柜，物理隔离。\n【塑料与尖锐件混放：看不见的划伤隐患】\n塑料管材被尖锐金属划伤，会形成隐性裂纹，通水后应力开裂。\n钢管坡口、螺栓棱角、铁丝边角会在管身划出深痕。\n划痕越深，承压能力下降越明显（“超壁厚 10%”是经验判据，以检测为准）。\n安装试压可能不漏水，运行半年到一年后会沿裂纹爆管。\n落回卡上：对照 PE 给水管、PPR 给水管、钢焊接弯头。\n正确规则：塑料区清理尖锐物，层间衬垫，禁止金属件堆其上。\n【仪表与化工辅材混放：挥发气体腐蚀的精度杀手】\n电子仪表靠近化工辅材存放，可能被挥发的酸碱性气体、溶剂蒸气腐蚀，也可能被粉尘、潮气与漏液交叉污染，导致机芯失灵。\n需要注意：镁阳极填包料的硫酸钠本身不挥发，它怕的是吸潮结块、失去导电活性；AB 胶也不是靠固化剂缓慢挥发致害，它怕的是超期提前固化、破损漏液。真正会挥发腐蚀气体的是酸碱、溶剂类化学品。\n这些挥发物或污染物侵入仪表电子元件与金属触头，会造成计量失准、显示失灵。\n出库安装后才发现问题，造成退换货与工期延误。\n落回卡上：对照超声波水表、镁合金牺牲阳极、AB 胶（管道修补剂）。\n正确规则：仪表干燥专区存放，与化工辅材分区分架存放，保持安全距离。\n【衬塑管与焊接同区：高温烧损的内衬破坏】\n衬塑管附近进行焊接作业，高温火花会烧损管口内衬，造成钢塑离层。\n电焊火花温度上千度，溅到管口直接烧穿塑料内衬。\n还会破坏管口粘结层，导致内衬脱落、往里锈蚀。\n短期看不出来，通水后很快就会结垢、缩径、漏水。\n落回卡上：对照衬塑复合管、钢焊接弯头。\n正确规则：衬塑区设为禁焊区，焊接作业必须加防火挡板完全遮挡。\n【轻重物料违规混堆：压损变形的结构破坏】\n重物直接压在轻质脆性物料上，会造成永久变形、碎裂报废。\n铸铁管件、重型井盖压在 PPR 管件、复合井盖上，会让塑料变形、井盖碎裂。\n密封件长期受压会产生永久变形，失去密封能力。\n属于完全可避免的人为损耗，直接造成物资浪费。\n落回卡上：对照复合井盖（给水 / 消防）、PE 给水管、PPR 给水管。\n正确规则：严格重下轻上，脆性物料单独放，上方禁止堆重物。\n【合格与呆滞料混放：错发误用的质量风险】\n待检、不合格、超期物料与合格品混放，极易错领误用引发质量事故。\n没有物理隔离时，你很容易把待检阀门、超期胶圈当合格品领走。\n不合格件流入施工环节，会造成试压渗漏、运行故障。\n返工成本远高于物料本身价值，还会影响工程进度。\n落回卡上：对照中线（软密封）蝶阀、弹性座封闸阀（明杆式）。\n正确规则：设立独立呆滞隔离区，物理围栏 + 红色标识，专人管理。\n【风险分级与优先级】\n混放风险分三级，高风险项必须零容忍，优先整改。\n高风险：橡胶沾油、衬塑近焊、合格与呆滞混放\n中高风险：塑料划伤、重物压损\n中风险：碳钢不锈钢接触、仪表近化工\n巡检时按优先级排查，先整改高风险项。\n\n**自测：不锈钢和碳钢混放会发生什么腐蚀？** 回本课【碳钢与不锈钢混放：接触电偶腐蚀】对照。\n\n**自测：胶圈和油污混放为什么是密封杀手？** 回本课【橡胶件与油污混放：溶胀老化的密封杀手】对照。","structure":"知识结构：按 “材质反应类→物理损伤类→管理混淆类” 三大风险分类，形成混放风险的完整辨析框架。\n风险分级对照表\n- 高风险：橡胶沾油、衬塑近焊、合格与呆滞混放\n- 中高风险：塑料划伤、重物压损\n- 中风险：碳钢不锈钢接触、仪表近化工\n学习要点：\n1. 混放风险分三类，高风险项必须零容忍\n2. 核心处置原则：物理隔离、分区分架、标识清晰\n3. 很多失效是隐性的，当时没事不代表以后没问题\n4. 管理混放比材质混放后果更严重，直接引发质量事故\n5. 巡检不仅要查物料状态，更要查存放方式是否合规\n6. 发现混放先隔离风险物料，再排查受损情况，最后优化分区\n7. 按风险优先级整改，先解决高风险项","anchors":[{"name":"六角头螺栓（半丝 / 全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"不锈钢户表控制箱","ref":"不锈钢户表控制箱"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"PE 给水管","ref":"PE给水管"},{"name":"PPR 给水管","ref":"PPR给水管"},{"name":"钢焊接弯头","ref":"钢焊接弯头"},{"name":"衬塑复合管","ref":"衬塑复合管"},{"name":"超声波水表","ref":"超声波水表"},{"name":"镁合金牺牲阳极","ref":"镁合金牺牲阳极"},{"name":"AB 胶（管道修补剂）","ref":"AB胶（管道修补剂）"},{"name":"中线（软密封）蝶阀","ref":"中线（软密封）蝶阀"},{"name":"弹性座封闸阀（明杆式）","ref":"弹性座封闸阀（明杆式）"},{"name":"复合井盖（给水 / 消防）","ref":"复合井盖（给水/消防）"}],"pitfall":"1. 不锈钢不是绝对不生锈，挨着碳钢放，接触的地方一定会锈\n2. 胶圈沾油擦擦就用，看着没事，实际弹性早就没了，装上去必漏\n3. 待检料不隔离，早晚会被当成合格品错领出去闯祸","remark":"—","seq":91,"family":"其他","lessonNo":8},{"id":"C88","sub":"CL-03","topic":"物料替代规则与参数匹配辨析","level":"D3 / L3","d":"D3","l":"L3","positioning":"本课专讲物料替代的规则与边界，属于 CL-03 子类辨析进阶课，内容包括替代基本原则、四项核心参数比对、常见可替代组合、禁止替代红线、查找路径与审批流程。本课在 C84 全景框架中「合规替代」原则的基础上展开辨析，为 C85、C86 缺料场景下的替代处置提供判定依据。","framework":"1. 替代基本原则｜性能只升不降、压力只高不低、材质兼容三大原则\n2. 核心参数比对｜口径、压力等级、材质、连接方式四项匹配法\n3. 常见可替代组合｜不同管件、阀门、辅材的替代边界对照\n4. 禁止替代红线｜承压核心件、卫生接触件、计量仪表的禁用场景\n5. 替代查找路径｜材料库检索方法、参数筛选技巧、现用件优先规则\n6. 替代审批流程｜临时替代的申请、核验、登记要求","lecture":"**相邻关系：向上接 C87《退库物料判定与分类处置标准》；向下接 C89《特殊场景处置与审批边界辨析》。**\n\n**现场情境：现场缺料，有人想拿低压件替高压、私自换件不审批。** 红线在哪？本课讲替代规则。\n\n【替代基本原则】\n所有物料替代都必须遵守三大原则，底线不能破。\n性能只升不降：替代件的性能必须等于或优于原件，不能降级。\n压力只高不低：压力等级只能选更高的，不能用低压的替高压的。\n材质兼容：替代件和连接的物料材质必须兼容，不能起反应、接不上。\n这三条是铁则，任何替代都不能突破，不然就是埋质量隐患。\n【核心参数比对】\n替代前必须比对四项核心参数，一项都不能差。\n口径一致：公称直径必须对应，DN100 不能替 DN80，连接不上。\n压力等级达标：替代件的 PN 等级必须≥原件，比如 PN16 可以替 PN10，反过来不行。\n材质兼容：和前后连接的管材材质适配，不起反应、能接上。\n连接方式一致：接口形式必须对应，比如法兰接口不能替螺纹接口，接不上。\n四项都满足，才具备替代的基础，缺一项都不能随便替。\n落回卡上：弹性座封闸阀和中线软密封蝶阀，都能截断水流，但参数要匹配才能替代。\n【常见可替代组合】\n三类常见的可替代场景，边界清晰，现场经常遇到。\n阀门类：同口径同压力下，闸阀和蝶阀在普通截断场景可替代；高压场景优先闸阀。\n管材类：同口径下 PE100 可以替代 PE80，强度更高；反过来不行。\n辅材类：8.8 级螺栓可以替代 4.8 级，强度更高；EPDM 胶垫（法兰橡胶垫片）在给水场景通用。\n替代只限于同功能、同口径、参数更优的组合，不是差不多就行。\n【禁止替代红线】\n承压核心件、卫生接触件、计量仪表三类列为原则禁止替代的红线，再急也不能碰；特殊工况件如需替代，须经技术审批并做参数校验。\n承压核心件：主干管、高压段的核心管材管件，原则上禁止替代。\n卫生接触件：直接接触饮用水的物料，必须符合卫生标准，原则上禁止更换。\n计量仪表类：水表、流量计等计量器具，原则上禁止替代。\n特殊工况件：倒流防止器、减压阀等特殊功能阀门，确需替代的须经技术审批并校验参数，不得用普通阀直接顶替。\n这些都是安全和质量红线，突破前必须走审批与参数校验，不能擅自决定。\n落回卡上：钢法兰（平焊 / 对焊）、PE 给水管都属于承压类管材管件，原则上禁止替代。\n【替代查找路径】\n找替代件按三步来，又快又准，还不容易出错。\n第一步定参数：先明确原件的口径、压力、材质、连接方式四个核心参数。\n第二步筛现用：在公司现用物料里，筛选参数等于或更优的同功能物料。\n第三步核边界：对照禁止替代红线，确认不在红线范围内。\n优先选公司现用物料，不要随便推荐非现用件，避免采购麻烦。\n【替代审批流程】\n替代不是仓管员自己说了算，必须走审批流程。\n申请：领料人提出替代申请，说明原因、替代件信息。\n核验：仓管员核对参数，确认符合替代原则和边界。\n审批：技术或工程管理人员审批确认，承担技术责任。\n登记：发放后登记替代记录，备注清楚原件、替代件、审批人。\n流程走完才能发料，不能口头同意就替代，事后说不清楚。\n\n**自测：压力等级能不能低替高？** 回本课【核心参数比对】对照。\n\n**自测：计量仪表原则上能不能替代？** 回本课【禁止替代红线】对照。","structure":"知识结构：三大原则→四项参数→可替代组合→禁止红线→查找路径→审批流程，形成 “能替不能替、怎么替、谁来批” 的完整替代管理体系。\n三组核心辨析对照\n1. 可替代 vs 不可替代：看是否突破红线、参数是否更优\n2. 同功能替代 vs 跨功能替代：只有同功能才能谈替代，功能不同绝对不行\n3. 现用件替代 vs 非现用件替代：优先现用件，非现用件严禁私自替代\n学习要点：\n1. 三大替代原则：性能升、压力升、材质兼容，缺一不可\n2. 四项核心参数：口径、压力、材质、连接方式，逐项核对\n3. 同功能、参数更优才能替，差一点都不行\n4. 承压、卫生、计量三类是原则禁止替代的红线，特殊功能件确需替代须经审批与参数校验\n5. 找替代先定参数、再筛现用、最后核边界\n6. 替代必须走审批，不能私自换，全程登记留痕\n现场缺料时最想「差不多就换一个」，而这恰恰是参数不匹配、出质量事故的起点；下一课 C89 把这类特批、换料、单据异常的边界情形放到一起辨析。","anchors":[{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"中线（软密封）蝶阀","ref":"中线（软密封）蝶阀"},{"name":"PE 给水管","ref":"PE给水管"},{"name":"PPR 给水管","ref":"PPR给水管"},{"name":"衬塑复合管","ref":"衬塑复合管"},{"name":"钢法兰（平焊 / 对焊）","ref":"钢法兰（平焊/对焊）"}],"pitfall":"1. 压力等级只能高替低，低压替高压必出问题\n2. 计量仪表原则上禁止替代，特殊功能阀确需替代须经审批与参数校验\n3. 再缺料也不能私自换件，必须走审批留记录","remark":"","seq":92,"family":"其他","lessonNo":5},{"id":"C89","sub":"CL-03","topic":"特殊场景处置与审批边界辨析","level":"D3 / L3","d":"D3","l":"L3","positioning":"本课专讲领退料中的特殊场景与审批边界，属于 CL-03 子类管理进阶课，内容包括应急抢修特批、非现用件申领、单据异常处置三类场景规则，以及违规风险辨析、合规判定与沟通协同。本课是 CL-03 的收尾课，把 C84—C88 各项规则放到边界情形中综合辨析，形成完整的审批边界判断。","framework":"1. 应急抢修特批｜深夜抢修、重大停水等紧急场景的发料规则\n2. 非现用件申领｜一线索要非现用物料的处置流程与特批权限\n3. 单据异常处置｜单据不全、信息有误、手写借条的分级处理规则\n4. 三类违规风险｜先领后补、私自换料、越权审批的后果辨析\n5. 合规判定方法｜快速判断场景是否合规的三个判断维度\n6. 沟通协同技巧｜坚守制度同时做好一线服务的沟通方法","lecture":"**相邻关系：向上接 C88《物料替代规则与参数匹配辨析》；本板块到此收束。**\n\n**现场情境：有人把应急特批当常态用，非现用件也想私自发。** 审批边界在哪？本课讲特殊场景处置。\n\n【应急抢修特批规则】\n应急抢修可以特事特办，但有明确的适用范围和补单要求。\n适用场景：突发爆管、大面积停水、重大设备故障等影响民生的紧急情况。\n操作方式：可先发放物料，登记领用人、事由、数量，后续补手续。\n审批权限：必须有抢修负责人或值班领导确认，不能仓管员自己决定。\n补单时限：工作日内补齐手续。\n特批是为了保抢修，不是无底线开口子，底线和时限必须守住。\n落回卡上：哈夫节（堵漏器）这类抢修物料，最常遇到应急特批的情况。\n【非现用件申领处置】\n一线索要公司非现用物料，不能直接答应也不能直接拒绝，按流程来。\n第一步先查替代：在现用物料里找参数更优的替代件，优先推荐现用的。\n第二步讲规则：没有替代件的，说明非现用件需要走采购流程，不能直接发。\n第三步走特批：确实紧急且必须用的，走专项特批流程，由技术和物资部门审批。\n严禁私自发放非现用物料，也不能把非现用件混在现用库里。\n落回卡上：黄铜加密闸阀、减压型倒流防止器这类专用件，要确认是否在现用范围内。\n【单据异常分级处置】\n单据有问题分三级处理，不是一竿子打死也不是全都放行。\n一级轻微异常：字迹稍模糊、信息有小遗漏，核心要素齐全的，可先登记后补正。\n二级一般异常：缺少非核心审批、信息有误的，退回补全后再来办理。\n三级严重异常：没有单据、核心要素缺失、伪造涂改的，坚决不予发料。\n分级处置既保证合规，又不至于太死板影响正常工作。\n手写借条只能应急临时用，不能长期挂账，必须及时转成正式单据。\n【三类违规风险辨析】\n三种常见的违规做法，看似省事，后果都很严重。\n先领后补常态化：把应急特批当常态，什么料都先领再补单，最后账实混乱。\n私自换料替代：缺料了私自换别的型号，不打招呼也不登记，出问题找不到原因。\n越权审批：没有审批权限的人签字同意，出了问题责任界定不清。\n这些都是管理红线，次数多了一定会出质量事故、资产流失。\n【合规判定三要素】\n快速判断一件事合不合规，看三个维度就行。\n一看有没有依据：有没有制度依据、有没有审批签字、有没有单据记录。\n二看有没有越权：是不是在自己的权限范围内，有没有超权限做决定。\n三看有没有留痕：有没有登记记录，能不能追溯到人和事。\n三个都满足基本合规，缺一个就要打问号，缺两个就是违规。\n【沟通协同技巧】\n守制度不是硬怼人，讲究方法既能守住底线，又能让一线理解。\n先讲原因：不是故意刁难，是按制度来，也是为了现场质量负责。\n再给方案：不行的话，告诉对方可行的替代方案、正确的流程怎么走。\n急事急办：真的紧急，一起走特批通道，而不是直接拒绝。\n仓管员既是制度守门员，也是一线服务员，两者不冲突。\n\n**自测：把应急特批当常态会有什么管理漏洞？** 回本课【应急抢修特批规则】对照。\n\n**自测：非现用件能不能私自发或随便答应采购？** 回本课【非现用件申领处置】对照。","structure":"知识结构：应急特批→非现用件处置→单据异常分级→违规风险辨析→合规判定→沟通技巧，形成特殊场景从处置到判定的完整管理体系。\n三组核心边界辨析\n1. 应急特批 vs 违规无单：看是否符合场景、有没有审批、有没有补单时限\n2. 合理替代 vs 私自换料：看参数是否合规、有没有审批、有没有登记\n3. 分级处置 vs 随意放行：看异常等级、有没有补正要求、有没有登记留痕\n学习要点：\n1. 应急特批有范围、有权限、有时限，不是万能借口\n2. 非现用件先找替代，真要用走专项审批，不能私自发\n3. 单据异常分级处理，轻微的补正，严重的驳回\n4. 先领后补、私自换料、越权审批都是违规红线\n5. 合规三要素：有依据、不越权、有留痕\n6. 守制度也要讲方法，先讲原因再给方案，做好协同\n把 C84 到本课连起来看，CL-03 从全景骨架、常规领料、抢修发放、退库判定、替代边界一路走到特殊场景审批，你手里已经有一套从「看清场景」到「照章处置」的完整判断链；现场再遇到拿不准的情形，回到凭单、先进先出、合规替代、分级审批这几条底层原则逐条对，基本都能找到答案。","anchors":[{"name":"哈夫节","ref":"哈夫节（堵漏器）"},{"name":"黄铜加密闸阀","ref":"黄铜加密闸阀"},{"name":"减压型倒流防止器","ref":"减压型倒流防止器"},{"name":"电磁流量计","ref":"电磁流量计"}],"pitfall":"1. 把应急特批当常态，迟早会出管理漏洞\n2. 非现用件不能私自发，也不能随便答应采购\n3. 单据再急也不能空口无凭，至少要有登记和负责人确认","remark":"","seq":93,"family":"其他","lessonNo":6},{"id":"C93","sub":"CL-04","topic":"账实差异排查与成因分类辨析","level":"D3 / L3","d":"D3","l":"L3","positioning":"这一课系统建立账实差异的完整分析框架，覆盖差异定性四型与三级分级、业务环节六类与管理成因六类双视角、自来水仓库五类高发场景、差异特征反推口诀、五步递进排查路径、四要素取证与差异表填报、合规处置口径与高频误区，解决“发现差异后怎么查、怎么定、怎么改”的核心问题，是盘点能力从“会点数”到“会排障”的核心进阶课。","framework":"差异定性四型｜盘盈、盘亏、规格串户、状态不符；金额/单价差异单列。差异分级三级｜合理损耗、一般差异、重大差异。成因双视角｜业务环节六类：单据与台账、收发作业、计量单位、物料特性、串号替代、空间管理；管理成因六类：发料差错、录入错误、自然损耗、丢失损坏、系统故障、历史遗留。行业高发五场景｜出库领用、计量特性、单据时序、内控薄弱、委托加工。品类规律｜管件易串规格、辅材易差数量、仪表易错单位、管材易偏计量。反推口诀｜看数字形态快速锁因。五步排查｜时序→计量→领用闭环→串号库位→内控专项。取证填报｜四要素取证与差异表填报。处置误区｜合规处置路径与四类红线。","lecture":"**相邻关系：向上接 C92《易混物料实物辨识与盘点防错技巧》；向下接 C94《复杂场景盘点与差异闭环管理》。**\n\n**现场情境：账实出现差异，有人想用盈的那部分去抵亏的，工地借料也没登记。** 为什么不行？本课讲差异成因。\n\n【差异定性四型】遇到差异先分清类型：盘盈是实物多于账面，常见于余料未登记、借入未登账；盘亏是实物少于账面，是最常见形态；\n规格串户是同品类不同规格一盈一亏、总数可能对得上但明细不对，如DN50补芯多、DN40补芯少，PE件与PPR件混盘、衬塑件与纯玛钢件混发；\n状态不符是数量对得上但账面标注与实物状态不一致，如完好品里混入待修、待报废、呆滞或待检品。\n金额/单价差异单列：数量对但金额或单价不一致，多由单价录入、单位换算、单据金额不一致造成，不简单按数量盘盈盘亏处理。\n关键辨析是“总量对、明细互抵”与“总量本身就是错”走两条路线，前者先查串号、编码串户、代用、一物多码，后者先查收发作业、计量误差、时点性差异和真实损耗。\n【差异分级三级】合理损耗是正常存储收发中不可避免的少量损耗，金额小、差异率极低，如小辅材拆零散失、橡胶密封件正常老化减量、管材切割计量固有偏差；\n一般差异是超出合理损耗但金额不大、影响范围小，按常规流程处理；重大差异是金额超阈值、差异率高，或涉及贵重物料、大批量管材、智能水表、电磁流量计等，需专项核查、分级审批。\n具体阈值按企业资产制度执行，本课只给分级逻辑，不代填数值。\n【成因辨析双视角】排查先用业务环节六类定位差异发生在哪里，再用管理成因六类归纳改进方向。\n单据与台账类：漏登、重登、物料编码错挂，数量、单价、小数点、单位换算录入错误，单据在途、待验未登记、已发未销，系统与台账数据不同步；\n特征是差额常为某单据量的整数倍，或台账无对应收发记录，对应录入错误、系统故障、历史遗留。\n收发作业类：收货验收点错数、送货单与实物不符、计量方式差异，发料多发少发、错发相近规格，白条领料未补单、随用随取未报账，预借未核销、工地间借料未走调拨、余料退库未登记、以旧换新未销旧账；\n自来水仓库尤其要查“预借台账—正式领用单—退料单—调拨单”闭环，对应发料差错。\n计量单位类：根/米/公斤/盘/套/个换算系数错，PE管、PPR管按盘标称米数与实际米数不符，钢管理论数量与实际计量方式差异，小件按包装折算而非逐件清点；\n特征是集中在特定品类、方向稳定、金额占比小但反复出现，对应录入错误、自然损耗中的计量固有偏差。\n物料特性类：橡胶密封圈超期发硬、生料带（聚四氟乙烯密封带）干缩、胶水/防腐材料固化或过期，球铁管件承口内衬磕碰、阀门手轮或表玻璃运输破损、法兰密封面碰伤，管材露天存放轻微损耗；\n特征是台账数量无误但实物确已减损，应走失效处置、报损或状态调整，对应自然损耗、丢失损坏中的老化破损。\n串号替代类：同外形不同规格、材质、压力等级混放混发，如不锈钢螺栓与碳钢螺栓、PE80与PE100、PN10与PN16管件、DN100与DN125闸阀，一物多码、一码多物，代用、改制、\n修旧利废后台账未同步；特征是一增一减、总额互抵，对应发料差错中的规格串户。\n空间管理类：库位错放、多库房串库，账在A库、料在B库，工地寄存、代保管、外协借用未单列，呆滞、隔离、待报废区物资仍计入良品账，未记录内部领用、样品、借出，漏盘、重盘、估盘、失窃丢失；\n对应丢失损坏、历史遗留和管理漏洞。\n【行业高发五场景】第一是出库与领用，这是自来水仓库差异最集中处：随用随取报账不及时，实物离库而账面未扣减；预借未核销，安装队先预借大型管材管件，完工后未核对实用数量、未办正式领用；\n工地间借料未走调拨，相邻工地互借应急未在系统办调拨，借出方盘亏、借入方盘盈；\n多领不退、借而不还，余料未退库或借出长期不还，逐步累积成缺口。\n第二是计量与物料特性，管材切割后余料长短不一难以精确还原账面单位，小配件拆零清点有固有偏差，橡胶件老化、防腐化学品挥发失效会让实物慢慢低于账面；\n看它是否方向稳定、金额占比小、反复出现在同一类物料上。\n第三是单据与系统时序，手工填单、定期集中录入导致出入库已发生而系统未更新，总库与营业所仓库、项目现场调拨信息未实时同步，入库单重复录、出库单漏记、品类编码挂错，\n已登记未验收入库的物资未单独标在途状态，容易被当成盘亏。\n第四是保管与内控薄弱，非正规时段取用未填领用标签也未补单，采购、验收、保管、发货岗位制衡不足，存放位置变更未记录，露天堆场或维护场地未上锁，存在丢失和擅自取用风险。\n第五是委托加工与特殊业务，特定规格防腐管件、定制配件发出材料按计划数量登记，收回时实际耗用未同步调整，造成账面原材料数量与实际耗用脱节。\n【品类差异高发规律】管件类最高发规格串户和材质串户，相邻口径弯头、直接、补芯混放，PE与PPR、衬塑与玛钢混发，常表现为A规格盘盈、相邻B规格盘亏；\n辅材类最高发数量差错和等级串户，螺栓多发少发、4.8级与8.8级混放、胶圈胶垫（法兰橡胶垫片）口径混放；仪表类最高发单位和口径错误，水表按“箱”录成“台”、DN15与DN20混盘、完好表与待修表报废表混放；\n管材类最高发计量偏差和状态不符，PE直管按米估算不准、截余短管未登记、螺旋管理论数量与实际数量差异、存放变形损坏。\n【差异特征反推口诀】差额是某单据量的整数倍，优先查漏登、重登、重复登记；差额落在个位或尾数，优先查收发点错、计量短少、拆零散失；一增一减、总额互抵，优先查规格串户、编码串户、错发代用；\n台账无错但实物已坏，优先判物料老化、破损、失效，走状态调整或报损；账在甲库、料在乙库，优先查串库、库位错放、工地寄存；长期挂账、动销为零，优先查时点性差异、历史遗留或呆滞未隔离；\n差异突然出现且金额大、有物理损坏痕迹，查丢失损坏、搬运事故、非正规取用。\n【标准化五步排查法】第一步先定时序，确认是否盘点时点与业务时点不同步造成，如在途、已出库未登记、已入库未登账，补录单据后差异消失即属时点性差异，不往下查；\n第二步再定计量，核查该品类计量方式、单位换算系数、切割与拆零记录，差异幅度与历史同类物料系统性偏差一致，倾向计量或物料特性差异；\n第三步查领用闭环，重点追踪预借单、工地调拨单、退料单的核销情况，自来水行业大多数可避免差异在这一环；\n第四步核串号库位，查相邻规格有无一盈一亏，查其他库区、其他货架有无放错物料，很多“盘亏”其实是放错地方；\n第五步内控专项核查，排除以上因素后仍存在大额、重复、方向一致的差异，再转入专项核查，查非正规取用、岗位制衡不足或资产流失可能。\n【差异取证与填报规范】四样取证材料缺一不可：盘点记录要有盘点人和复核人签字的纸质盘点表，字迹清晰、数据可追溯；实物照片拍清物料名称、规格、实际数量、状态和存放位置；\n单据佐证附出入库单、领料单、退料单、预借单、调拨单、验收单，自来水仓库尤其附预借核销记录和工地调拨记录；台账核对用系统差异表截图或打印件，标注账面数、实盘数、差异数、差异率。\n差异表填报基础信息要准，物料编码、名称、规格、单位、账面数、实盘数、差异数、差异率不能错；差异定性注明盘盈、盘亏、规格串户、状态不符或金额/单价差异；\n原因分析具体到哪笔单据、哪个环节、哪类成因，不写“收发差错”“盘点误差”空话；是否时点性差异要写明；处置口径写清登记、更正、调账、报损、盘亏、专项核查；整改措施可落地可验证；\n盘点人、复核人、库区主管签字齐全。\n【处置口径与误区辨析】时点性差异先做时点差异登记，不直接做盘盈亏；单据与台账差错追溯单据，补录、更正或调整；规格串户、状态错放调整台账，同步整改库区、标识、编码和隔离区；\n真实损耗、老化失效走报损、失效处置和状态调整；失窃丢失报盘亏，走专项核查；重大差异逐级上报、专项核查、分级审批，处理附完整佐证；\n历史遗留按跨年、交接、系统切换三类分别处理，处理后台账备注原因、时间、处理文号。四条红线不能碰：不自行调账凑数；不以盈补亏互抵，不同物料是不同资产必须分别查明分别处理；\n不隐瞒小差异，小额长期累积会变大且背后可能藏流程漏洞；不估数填平，估数等于没盘点。另防三种误判：时点性差异不直接报盘亏，规格串户不按总量错处理，串库不按丢失处理；\n物料老化破损走失效处置，不混入收发数量差错。\n\n**自测：不同物料的差异能不能以盈补亏？** 回本课【处置口径与误区辨析】对照。\n\n**自测：工地借料未调拨会造成什么差异？** 回本课【行业高发五场景】对照。","structure":"分定性：盘盈、盘亏、规格串户、状态不符四类结果型差异；金额/单价差异单列。知分级：合理损耗、一般差异、重大差异三级，阈值按企业制度。辨成因：业务环节六类——单据与台账、收发作业、计量单位、物料特性、串号替代、空间管理；管理成因六类——发料差错、录入错误、自然损耗、丢失损坏、系统故障、历史遗留。懂规律：管件易串规格、辅材易差数量、仪表易错单位、管材易偏计量；自来水仓库重点查预借未核销、工地借料未调拨、退料未登记、管材切割计量。会排查：时序→计量→领用闭环→串号库位→内控专项，五步递进。用反推：整数倍查漏登重登，尾数差查点数和计量，一增一减查串号，台账无误物已坏查失效，账甲库料乙库查串库。重取证：盘点记录、实物照片、单据佐证、台账核对四样齐全，预借调拨退料单据附齐。避误区：不自行调账、不以盈补亏、不隐瞒小差、不估数填平；时点性差异不直接报盘亏，串户不按总量错处理，串库不按丢失处理。填报表：信息准、定性清、原因实、是否时点性写明、处置口径明确、措施具体、签字齐全。走处置：时点性差异先登记，差错更正，串号状态调账整改，真实损耗报损，失窃盘亏专项核查，重大差异分级审批。","anchors":[{"name":"PE给水管","ref":"PE给水管"},{"name":"衬塑内外丝补芯（变径补芯）","ref":"衬塑内外丝补芯（变径补芯）"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"黄铜内螺纹浮动球阀","ref":"黄铜内螺纹浮动球阀"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"旋翼式机械水表（湿式/干式/液封）","ref":"旋翼式机械水表（湿式/干式/液封）"},{"name":"哈夫节","ref":"哈夫节（堵漏器）"}],"pitfall":"不能以盈补亏互抵差异，不同物料必须分别处理；时点性差异不直接报盘亏，串库不按丢失处理，物料老化破损走失效处置；预借未核销、工地借料未调拨、退料未登记是自来水仓库高频盘亏源，差异表原因不能写空话。","remark":"企业填：差异分级阈值、热熔与试压等工艺参数按企业现行制度执行。","seq":94,"family":"其他","lessonNo":4},{"id":"C51","sub":"XG-02","topic":"断管接口组合辨识：剩插口用双承，接阀门用盘承或盘插","level":"D4 / L4","d":"D4","l":"L4","positioning":"本课只讲断管后两端接口组合的辨识与选用，不展开抢修工艺全流程，也不替代GW-03。目标是在断口条件下判断用双承短管还是盘承/盘插过渡。","framework":"断口判断｜先看两端剩承口还是插口。双承短管｜两端承口，接纳两根插口。双盘短管｜两端法兰，接法兰阀门。盘承短管｜法兰接阀门，承口接直管。盘插短管｜法兰接阀门，插口插直管。盲板｜封法兰口。边界｜双插短管若平台未列现用卡，不凭名发料。断口→选件查表｜六类断口条件直接对到卡。","lecture":"**相邻关系：向上接 C50《橡胶材质相容》；向下接 C52《库房识伪与隔离》。**\n\n**现场情境：断管后没先看清剩下的是承口还是插口，就拿双承管件去装。** 正确做法是什么？本课讲组合辨识。\n\n【断口清理切平去毛刺：不干净就装不严】\n**抢修前要把承口、插口清理干净，端面切平、去毛刺，否则胶圈装不严、熔接也接不上。** 像贴胶带前先把表面擦干净，有灰有毛边就粘不牢。落回卡上：看断管接口组合卡的作业要求，清理、切平、去毛刺三步做到位再装。\n\n【量两断口间距定短管：含承口深度和插入量】\n**抢修短接要量准两个断口之间的间距，把承口深度和插入量都算进去；量错了，短管要么装不上、要么顶不住。** 像裁窗帘，尺寸量错就长短不对。落回卡上：看断管接口组合卡的量尺示意，量的是两断口净距加两端接口深度。\n\n【先判断断口：承口还是插口】\n**断管抢修第一眼，看两端剩下的是承口还是插口。** 喇叭张口的是承口，平切的是插口。像拼插积木，得先知道手里是凸头还是凹槽。\n**这一步定错，后面整串短管都选错。** 落回卡上：翻「双承短管」「盘承短管」卡的端头特写，先把承插指认清楚。\n\n【两断口都是插口：用双承】\n**两端都剩插口，就用两端都是承口的双承短管，分别套住两根插口。** 它像一根两头带套筒的接管，靠两道胶圈柔性密封。\n**理论上两端都是承口该用双插，但平台未列现用卡时绝不凭名发料，要查替代或报备。** 落回卡上：库里只有「双承短管」，没有就走流程，不臆造件。\n\n【接阀门过渡：盘承还是盘插】\n**阀门井里一侧是法兰阀门，另一侧是直管；直管剩插口用盘承（承口接纳插口），剩承口用盘插（插口插进承口）。** 阀门侧固定是法兰，变的是直管侧。\n**【红线】盘承盘插拿反，合龙时两端顶不上，只能二次断管。** 落回卡上：把「盘插短管」「盘承短管」并排看，只差承口还是插口那一头。\n\n【双盘与盲板：法兰侧的两个选项】\n**两端都是法兰阀门时用双盘短管，纯法兰可拆连接；法兰口要临时封死时用盲板。** 盲板只封法兰，不封承插。\n**【易错】别拿盲板去堵承口，也别把双盘当断管直通件。** 落回卡上：看「双盘短管」「球墨盲板（法兰盲板）」卡的螺栓孔，孔位说明它属于法兰体系。\n\n【为什么这么定：先看断口、再定过渡】\n**断管组合的判断链是：看两端断口 → 定是否要法兰过渡 → 选双承 / 盘承 / 盘插 / 双盘 → 核对胶圈和螺栓。** 一步都不能跳。\n**法兰靠螺栓可拆、承插靠胶圈（球墨管承插密封圈）柔性，两种语言要靠过渡件翻译。** 落回卡上：本课只讲接口辨识，抢修工艺按企业规程，不替代 GW-03。\n\n【材料锚点 · 落回卡上】\n**「双承短管」「双盘短管」「盘插短管」「盘承短管」「球墨盲板（法兰盲板）」「胶圈（球墨管承插密封圈）」六张卡，是断管抢修的选件清单。** 点开逐一确认端头，按断口条件挑一件。\n**库里没有双插短管的现用卡，就走替代或报备，不臆造件。** 本课只讲接口辨识，抢修工艺按企业规程执行、不替代 GW-03；胶圈润滑与就位按卡面与规程操作。\n\n【断口 → 选件 查表】\n**把断口条件直接翻译成该拿哪张卡，现场不用现推。** 表头：断口条件｜选件｜为什么。\n两端剩插口｜双承短管｜两端承口各纳一根插口。\n两端都是法兰阀门｜双盘短管｜纯法兰可拆连接。\n阀门侧法兰、直管侧剩插口｜盘承短管｜承口接纳插口。\n阀门侧法兰、直管侧剩承口｜盘插短管｜插口插进承口。\n法兰口要临时封｜球墨盲板（法兰盲板）｜只封法兰，不封承插。\n两端都是承口｜双插短管｜库内未列现用卡时走替代或报备，不凭名发料。\n**【红线】盘承盘插拿反，合龙时两端顶不上，只能二次断管。** 落回卡上：按本表点开「双承短管」「双盘短管」「盘承短管」「盘插短管」「球墨盲板（法兰盲板）」逐张确认端头。\n\n**自测：断口两端都是插口时该用什么管件？** 回本课【两断口都是插口：用双承】对照。\n\n**自测：接阀门过渡该选盘承还是盘插？** 回本课【接阀门过渡：盘承还是盘插】对照。","structure":"主链：看两端断口→剩插口用双承→接阀门选盘承或盘插→最后核对胶圈和法兰。\n要点：1 先判断承口插口；2 双承纳两插口；3 盘承接直管承口；4 盘插插直管；5 未列现用卡不凭名发料。\n引导：本课已认断口组合；现场常卡在盘承盘插拿反；下一步看 C52 库房识伪与隔离。\n会查表：先判承口插口 → 定是否要法兰过渡 → 按行拿件。\n记红线：未列现用卡不凭名发料，盘承盘插别拿反。","anchors":[{"name":"双承短管","ref":"双承短管"},{"name":"双盘短管","ref":"双盘短管"},{"name":"盘插短管","ref":"盘插短管"},{"name":"盘承短管","ref":"盘承短管"},{"name":"球墨盲板（法兰盲板）","ref":"球墨盲板（法兰盲板）"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"}],"pitfall":"【先看断口再拿件】盘承盘插别拿反；双插未列现用卡不得凭名发料。","remark":"—","seq":95,"family":"XG-02 组合与库房排查","lessonNo":17},{"id":"C52","sub":"XG-02","topic":"库房识伪与隔离：非现用、老物件与混放排查","level":"D4 / L4","d":"D4","l":"L4","positioning":"本课只讲库房辨识线索和隔离动作，不重复CL-01验收入库全流程，也不代替CL-04盘点。目标是在混放条件下按平台状态、标签、老化和规格线索把非现用件挑出隔离。","framework":"平台状态｜是否公司现用。标签与喷码｜名称、型号、标准、换版。老化线索｜橡胶龟裂、塑料脆化、防腐破损。规格混放｜同型异规、DN/De/Φ混放。隔离动作｜挂签、分区、待复核。边界｜不直接判退、不先签收后补流程。条件判断四步顺序｜标签→批次→状态→隔离。","lecture":"**相邻关系：向上接 C51《断管接口组合辨识》；本板块到此收束。**\n\n**现场情境：库房来了一批老物件，标签模糊，工人想先签收再说。** 这个流程对吗？本课讲识伪隔离。\n\n【先进先出与批次追溯：问题件找得到源头】\n**库房出库按批次先进先出，合格证与批次号一一对应，出了问题能追溯到供应商和批次。** 像超市把临期商品摆前面，先到的先用，出问题能查到哪家进的。落回卡上：看库房卡的批次字段，出库时核批次号与合格证是否对得上。\n\n【先查平台状态：是不是公司现用】\n**拿起一件先查平台状态是否为「公司现用」，非现用件不得混进现用区。** 这是唯一真源，比看外观、凭经验判断都准。\n**标签模糊、喷码缺失、标准换版没核对的，一律先隔离待复核。** 落回卡上：本课不展开某一件具体材料，重点是「查状态」这个动作。\n\n【看老化与防腐：名称对也不能放行】\n**橡胶龟裂、塑料脆化、防腐层破损、螺栓锈蚀，都是老化线索。** 像放久的胶鞋发硬开裂，看着还是那个件，性能早不行了。\n**【红线】老物件要与新到货分区，不能因为名称对就上架。** 落回卡上：老化判定按企业现行制度与卡面标准，本课只教识别线索，不代为判退。\n\n【看规格混放：同型异规最容易混】\n**DN、De、Φ、K 级、SDR、S 系列要逐项按卡面核对，补芯、短管、法兰、胶圈尤其容易混。** 同叫 DN100 的件，跨材质就不是一个外径体系（C46 已讲）。\n**【红线】别凭「看着差不多」把异规件归到一处。** 落回卡上：以卡面字段为准，规格混放是盘点差异的主要来源。\n\n【动作链：查、看、核、挂签、报复核】\n**正确顺序是查状态 → 看标签喷码 → 看老化防腐 → 核规格 → 挂签隔离 → 报复核。** 六步一步不省，件才有归属、账才对得上。\n**【红线】错误动作是先签收回头补流程、改标签把账做平，看着省事，坑在把非现用件放进施工。** 落回卡上：动作链按企业现行制度执行，不先签收、不补流程。\n\n【边界：本课只教辨识，不判退】\n**本课讲的是库房识伪线索与隔离动作，不重复 CL-01 验收入库全流程，也不代替 CL-04 盘点。** 判退、报废、盘盈盘亏另有制度。\n**它是 XG-02 的收口课：从 C35 认大类、C46 破口径、C51 定组合，到这课把「别把错件发出去」变成习惯。** 落回卡上：隔离区、复核、差异表按企业制度走。\n\n【材料锚点 · 落回卡上】\n**这一课不展开某一件材料，三张卡是用来「对照卡面字段」的样板。** 「球墨铸铁管」「衬塑内外丝补芯（变径补芯）」「复合井盖（给水/消防）」分别对应喷码、同型异规、承载标识三类识伪线索。\n**点开卡看字段，才知道标签、喷码、规格有没有对上。** 隔离、复核、差异表一律按企业现行制度执行；本课只教辨识线索与动作链，不判退、不先签收后补流程。\n\n【条件判断：混放排查的四步顺序】\n**库房识伪不是靠眼熟，是按「标签 → 批次 → 状态 → 隔离」四步条件链走。** 第一步看名称与卡面是否同名同规；第二步对批次与合格证是否一致；第三步查「公司现用」标识与外观老化；\n第四步按结果分「合格上架 / 待检 / 隔离拒收」。\n**【冲突条件】赶着发料时发现一批外观像现用件但批次对不上，先隔离不先发货。** 错在把「像」当「是」，混放件一旦进施工环节就得整段返工。\n落回卡上：按四步逐张核卡面字段，本课只讲辨识顺序，处置按企业库房制度。\n\n**自测：标签模糊、名称对得上的旧件能不能直接放行？** 回本课【看老化与防腐：名称对也不能放行】对照。\n\n**自测：发现非现用件第一步该怎么处置？** 回本课【先查平台状态：是不是公司现用】对照。","structure":"主链：查平台状态→核标签喷码→看老化防腐→核规格→挂签隔离→报复核。\n要点：1 非现用先隔离；2 标签模糊待复核；3 老化件不混放；4 同型异规逐项核；5 不先签收不补流程。\n引导：本课已认识伪动作；现场常卡在怕麻烦先签收；末课横向回看C35大类到C51断口组合。\n条件链：同名同规 → 批次一致 → 现用标识 → 隔离判定，四步不能跳。\n记冲突：批次对不上先隔离不先发货。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"衬塑内外丝补芯（变径补芯）","ref":"衬塑内外丝补芯（变径补芯）"},{"name":"复合井盖（给水/消防）","ref":"复合井盖（给水/消防）"}],"pitfall":"【别先签收后补流程】非现用先隔离；标签模糊不凭眼看；老化件不能混入现用区。","remark":"—","seq":96,"family":"XG-02 组合与库房排查","lessonNo":18},{"id":"C56","sub":"XG-03","topic":"有限空间作业顺序与盲目施救判断：开井盖后先做什么","level":"D4 / L4","d":"D4","l":"L4","positioning":"本课只讲判得准：开井盖后带时间压迫时的正确顺序，以及井内有人倒地先做什么。不展开救援技术细节和气体检测限值。目标是把“围挡→开盖警戒→通风→检测→作业票监护→进入与持续监护→结束复位→异常呼救”走成一条链。","framework":"开盖前｜确认井位、周边交通、井盖状态，设置围挡警示。开盖后｜保持井口警戒，启动作业票、监护人到位（票证监护是进入前的门槛）。作业票与监护｜按企业制度办理并到位，监护人不得离岗；无票或无监护，不通风、不检测、不进入。通风｜稀释置换井内气体，持续到作业过程。检测｜按作业票项目和顺序检测并记录；不合格不进入。进入与持续监护｜检测合格、票证监护到位后进入；作业中保持通风监护。结束复位｜清点人员工具、复位井盖、撤围挡前确认无遗留风险。异常与盲目施救｜先呼救报警、设警戒，不盲目下井。","lecture":"**相邻关系：向上接 C55《PPE与环境风险辨识》；本板块到此收束。**\n\n**现场情境：井盖刚打开，有人就要往下钻；另一个人看见井内有人倒地，想直接跳下去救。** 这两步对吗？本课讲顺序。\n\n【三脚架加安全绳：井外施救，别盲目下井】\n**井内人员遇险，优先用三脚架、安全绳、绞盘在井外施救；盲目下井救，会把一人遇险变成两人遇险。** 像落水先抛绳，不是自己跳下去。落回卡上：看应急救援卡的装置示意，先架三脚架、再放绳，非进入式优先。\n\n【严禁纯氧通风：只能送清洁空气】\n**通风只能送清洁空气，严禁用纯氧或富氧空气，否则遇火源会剧烈燃烧甚至爆炸。** 像给火炉鼓氧，越鼓越猛。落回卡上：看通风作业卡的气体要求，确认风机送的是空气不是氧气。\n\n【开盖前确认与围挡】\n**开井盖前先确认井位和周边环境。** 看交通、行人、井盖状态。**先设置围挡警示。** 挡人挡车，夜间加反光。**围挡是第一步，不是下井。** 井盖打开后风险从洞口开始。**井盖要妥善放置。\n** 不能挡车道，也不能虚盖。**本课不写围挡距离。** 按现场和企业制度。\n\n【开盖后警戒】\n**开盖后保持井口警戒。** 不探头久留，不围一堆人。**井口要有专人看护。** 防止路人靠近。**开盖后先按企业制度启动作业票。** 作业票是进入前的门槛。**监护人到位后才能继续。\n** 监护人不得离岗。**与C54关系：开盖不等于能进。** C54讲机理，本课讲顺序。\n\n【通风】\n**先通风稀释置换井内气体。** 通风设备放在井口合适位置。**通风不是走形式。** 要持续到作业过程。**通风后仍要检测。** 通风不等于检测合格。**本课不写通风时长。** 按作业票和现场条件。\n**通风和检测顺序不能倒。** 先通风再检测。\n\n【检测】\n**检测是确认能否进入。** 按作业票规定的项目和顺序检测并记录。**检测不合格继续通风并按作业票处理。** 仍不合格不进入。**检测记录随作业票保存。** 便于追溯。**本课不写检测限值。\n** 按企业制度和标准原文。**检测合格是进入的前提之一。** 还要作业票和监护到位。\n\n【作业票与监护】\n**进入前按企业现行作业票制度办理。** 本课不写审批层级。**监护人不得离岗，保持联络。** 单人不下井。**作业人员要清楚应急信号和撤离路线。** 发现异常先撤。**作业票、检测记录、监护要配套。\n** 缺一项不进入。**与C54关系：C54讲监护人作用，本课讲到位顺序。**\n\n【进入与持续监护】\n**检测合格、作业票和监护到位后进入。** 不能先下再补。**作业中保持通风和持续监护。** 监护人盯井口和周边。**作业人员不脱PPE，不摘安全帽下颚带。** 井内动作慢而稳。\n**发现头晕、异味、异常先撤离并报告。** 不硬撑。**本课不写气体限值和救援技术细节。** 按企业应急制度。\n\n【结束与复位】\n**作业结束先清点人员。** 确认无人留在井内。**工具材料清点。** 不能把工具落在井内。**复位井盖和井座。** 井盖要盖实，不能虚盖。**撤围挡前确认现场无遗留风险。** 路面恢复再撤离。\n**结束也要记录。** 作业票闭环。\n\n【异常与盲目施救】\n**井内有人倒地，第一反应不是下井拉人。** 先呼救报警、设置警戒。**无防护不进入。** 盲目施救会把一个人变成两个人。**报告说清位置、人数、井口状态和已做措施。** 等待专业救援。\n**不要多人探头围观。** 防止二次坠落。\n\n**自测：打开井盖后第一步该做什么？** 回本课【开盖后警戒】对照。\n\n**自测：井内有人倒地，能不能立即下井施救？** 回本课【检测】对照。","structure":"主链：围挡警示→开盖警戒→作业票监护→通风→检测→合格后进入→持续监护→结束复位。对照：正确顺序 vs 探头闻味、单人下井、先下再说、通风完直接下。动作链：发现倒地→呼救报警→设警戒→不盲目下→等专业救援→报告交接。边界：不写限值、审批层级、通风时长和救援技术细节。要点：1 开井盖先围挡；2 开盖后警戒并启动票证监护；3 先通风再检测后作业；4 未合格不进入；5 井内有人倒地不盲目下。引导：本课已判作业顺序；现场常卡在“救人要紧先下去”；XG-03到此横向回看C53设施、C54机理、C55环境风险。","anchors":[{"name":"地下式消火栓","ref":"地下式消火栓"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"复合井盖（给水/消防）","ref":"复合井盖（给水/消防）"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"不锈钢户表控制箱","ref":"不锈钢户表控制箱"}],"pitfall":"【开井盖先围挡，不是先下井】未检测合格不进入；井内有人倒地别先下井，呼救报警设警戒。","remark":"企业填：作业票、检测、监护、应急按企业现行制度；不生成限值/审批层级/通风时长；统一话术已内置","seq":97,"family":"XG-03 安全生产与作业底线","lessonNo":4},{"id":"C73","sub":"CL-01","topic":"到货异常判别与隔离处置：单据、标准、状态与批次","level":"D4 / L4","d":"D4","l":"L4","positioning":"这一课讲到货异常这一类条件判断知识：六类异常如何识别、先隔离还是先判依据、标准换版与批次混装如何处理、拒收与待检如何区分、处置顺序与留痕闭环。它放在 CL-01 验收链末端，综合运用前面分材料验收与辨析知识。","framework":"异常类型｜单据不符、标签模糊、非现用、标准换版、批次混装、包装破损。\n判定依据｜卡面字段、标准号、状态栏、合格证、批次。\n处置顺序｜先隔离待检→核依据→判合格/待检/拒收→留痕→上报复核。\n拒收与待检｜拒收是判定，待检是控制。\n冲突条件｜单据旧版与卡上新版、标签与实物不符、同批混规格。\n复核上报｜谁判、谁批、谁复核。\n留痕闭环｜异常记录、隔离标识、处理结果。","lecture":"**相邻关系：向上接 C72《同名不同物辨析》；本板块到此收束。**\n\n**现场情境：一批材料到货，单据和批次对不上，标准又刚换版。** 先判依据还是先隔离？本课讲到货异常。\n\n【六类到货异常的识别】\n**到货异常分六类。** 单据与卡面不符、标签模糊、非现用、标准换版、批次混装、包装破损；分类是处置的第一步。\n**单据不符最常见。** 送货单名称数量、合格证标准批次、材料卡型号状态，三处对不上就是单据异常；不先核单据，后面容易白做。\n**标签模糊和喷码不全属于标识异常。** 标签、喷码、状态标识看不清，无法确认实物身份，属于待检条件。\n**非现用和老化属于状态异常。** 平台状态与实物老化程度决定能否进现用区；非现用先隔离，老化件不混入现用区。\n【先隔离还是先判依据】\n**先控制现场，再判依据。** 异常件先移到待检区或挂待检标识，再核单据和卡面；顺序倒了，异常件可能已被领走。\n**隔离不是判拒收。** 隔离是防止误用，拒收是判定结果；先隔离，再判合格、待检还是拒收。\n**拿不准不放过。** 单据旧版与卡上新版冲突、标签与实物不符，先待检，不自行放行。\n**上报要带证据。** 课程号、卡名、批次、数量、异常点、已做措施要写清；只写“有问题”，别人没法判。\n【标准换版与批次混装】\n**标准换版看到货日期。** 到货在切换日前后，核对依据不同；单据旧版、卡上新版时，先看实施日期再判。\n**批次混装先分开。** 同箱不同规格、不同标准、不同批次，先物理分开再逐项核；混装按一个批次发料，装错就是返工。\n**包装破损看内件。** 外包装破损是否伤及内件；内件变形、受潮、划伤属于待检条件。\n**混装和破损都不是小问题。** 它们会掩盖单据异常和标识异常；先分开，才能逐项判。\n【拒收与待检的区分】\n**拒收是判定，待检是控制。** 标准不符、非现用、老化破损可判拒收；单据不清、标签模糊可先待检。\n**待检不是无限期放。** 待检原因、责任人、复核时间要写清；一直待检等于没处理。\n**拒收要留痕。** 拒收原因、数量、批次、供应商要记录；只退货不记录，复盘没依据。\n**复核不能省。** 拒收或待检要有复核人；自己判自己复核，等于没复核。\n【处置顺序与留痕闭环】\n**处置顺序是：隔离→核依据→判定→留痕→上报复核。** 先隔离待检，再核单据卡面标准状态，再判合格/待检/拒收，再写记录，最后上报复核。\n**顺序不能倒。** 先判后隔离，异常件可能已被领走；先上报后隔离，现场控制就晚了。\n**留痕要可检索。** 按课程号、卡名、批次归档；乱堆一起，查的时候找不到。\n**闭环才算完。** 异常记录、隔离标识、处理结果要闭环；只隔离不闭环，异常件还在库里。\n\n**自测：到货异常时先判依据还是先隔离？** 回本课【先隔离还是先判依据】对照。\n\n**自测：标准换版时怎么判断该按哪版验收？** 回本课【标准换版与批次混装】对照。","structure":"主链：识别异常→先隔离→核依据→判定→留痕→上报复核→闭环。\n对照：拒收 vs 待检；隔离 vs 判定；单据异常 vs 状态异常。\n要点：1 先隔离再判依据；2 拒收是判定、待检是控制；3 标准换版看到货日期；4 批次混装先分开；5 留痕闭环可追溯。\n引导：本课综合运用 CL-01 验收链知识；到此形成总览、分材料、留痕、辨析、异常处置的闭环。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"螺旋缝焊接钢管","ref":"螺旋缝焊接钢管"},{"name":"复合井盖（给水/消防）","ref":"复合井盖（给水/消防）"},{"name":"沟槽卡箍（刚性/柔性）","ref":"沟槽卡箍（刚性/柔性）"}],"pitfall":"【先隔离再判依据】拒收是判定、待检是控制；标准换版看到货日期；批次混装先分开；留痕闭环。","remark":"—","seq":98,"family":"CL-01 材料验收入库与标准核对","lessonNo":17},{"id":"C99","sub":"GW-01","topic":"重点场景专项巡检与缺陷上报闭环","level":"D4 / L4","d":"D4","l":"L4","positioning":"这一课面向汛后冻融、老旧管网、第三方施工三类复杂巡检场景，讲解重点排查方法、缺陷规范上报流程与全闭环管理要求，覆盖从识别到销号的完整管理链路，对应高阶巡检与管理岗能力要求。","framework":"汛后冻融后专项巡检｜降雨融雪冻胀过后管网重点排查部位、常见缺陷类型、加密巡检要求。\n老旧管网重点巡检｜高风险管段识别、接口与腐蚀重点检查方法、渗漏前兆捕捉技巧。\n第三方施工旁站巡检｜施工工地周边管网防护检查、机械作业旁站要点、损伤应急处置。\n缺陷规范上报流程｜对应材料卡选择、缺陷描述要素、照片拍摄标准、位置定位要求。\n常见上报错误避坑｜材料卡选错、缺陷描述模糊、照片无效、等级错报高频问题纠正。\n隐患跟进与闭环｜已上报缺陷跟进核实、整改后复查、销号确认全流程要求。\n巡检台账管理｜巡检记录填写、缺陷台账更新、趋势分析与重点区段标记管理方法。","lecture":"**相邻关系：向上接 C102《暗漏征兆识别与初步听漏排查方》；向下接 C103《季节性专项巡检》。**\n\n**现场情境：缺陷上报只写了“坏了”，第三方施工段巡了一次就不再去，报完也没跟进。** 闭环缺了什么？本课讲上报规范。\n\n【汛后冻融后专项巡检：灾后排查有重点】\n大雨、融雪、冻胀过后，管网缺陷会集中爆发，要加密巡检。汛后重点查：低洼路段的井室有没有淹水、倒灌；砂土冲刷路段的管道有没有裸露、沉降；接口位置有没有因土壤软化出现渗漏；\n井盖井室有没有被雨水冲塌、淤积。冻融后重点查：北方冬季过后，接口胶圈有没有冻硬渗漏；水表、阀门有没有冻裂；覆土浅的管段有没有冻胀位移；保温层有没有破损脱落。\n加密巡检期要提高频次，重点区段每日一巡。\n【老旧管网重点巡检：高风险段要盯紧】\n服役超过20年的老旧管段，是爆管高发区。巡检第一要识别高风险管段：管径小、腐蚀重、接口多、曾经爆过管的路段，要重点标记；\n第二重点查接口，承插接口、法兰接口是渗漏高发点，看地面有没有返潮、井内有没有积水；第三捕捉渗漏前兆：路面细小裂纹、局部沉降、植被异常，这些小征兆背后可能是大隐患。\n老旧管段要建立专属台账，跟踪缺陷发展趋势。\n【第三方施工旁站巡检：防破坏是核心】\n工地周边的管线，最怕机械挖坏。施工前要先核对管线位置，给施工方交底；施工中要旁站巡查，机械开挖到管线附近时，必须有人在现场盯守，防止挖破管道；\n重点查防护措施，施工方有没有做保护套管、有没有按规定距离作业；发现损伤风险立刻叫停，先处置再施工。一旦发生挖破事故，第一时间关阀止水、上报调度，不能让事态扩大。\n【缺陷规范上报流程：四要素缺一不可】\n上报缺陷要规范，四要素必须全。第一选对材料卡，对应到具体的物料名称，不能笼统写“阀门坏了”，要选到对应规格的弹性座封闸阀或蝶阀；第二写清缺陷描述，包含位置、部件、缺陷类型、严重程度；\n第三拍标准照片，全景、近景、特写各一张，有参照物、能看清缺陷；第四准确定位，标注道路、桩号、井号，方便维修人员快速找到。\n【常见上报错误避坑：四类问题最常见】\n新手上报常踩四个坑。第一材料卡选错，把蝶阀报成闸阀、把PE管件报成球铁管件，导致维修带错料；第二描述模糊，只写“漏水”“坏了”，不说清哪里漏、漏多大、什么程度；\n第三照片无效，只拍近景不拍全景、逆光模糊、没参照物，看不出在哪、有多大；第四等级错报，把一般缺陷报成重大、或者把重大隐患压成一般，影响处置优先级。\n【隐患跟进与闭环：报了不是就完事】\n巡检不是报完缺陷就结束，要跟进闭环。上报后要跟进核实，看有没有派单、什么时候处理；整改时可以到现场复核，确认处置到位；整改完成后要复查销号，确认缺陷彻底解决，才能从台账里移除。\n不能报上去就不管了，也不能整改完不复查，防止假整改、整改不到位。\n【巡检台账管理：用好数据提效率】\n巡检台账不只是记录，更是管理工具。每次巡检记录要按时填写，不补记、不漏项；缺陷台账要动态更新，新增、整改、销号同步更；定期做趋势分析，哪类缺陷多、哪个区段问题集中，一目了然；\n对高频缺陷、重点区段标记出来，提高后续巡检优先级。用好台账，能把被动抢修变成主动预防。\n\n**自测：缺陷上报只写“坏了”为什么不合格？** 回本课【缺陷规范上报流程：四要素缺一不可】对照。\n\n**自测：第三方施工段能不能只巡一次？** 回本课【第三方施工旁站巡检：防破坏是核心】对照。","structure":"主链：三类专项场景巡检→规范上报流程→避常见错误→跟进整改闭环→台账管理优化。\n要点：1 汛后冻融后查低洼段、接口、井室；2 老旧管网盯高风险段、接口、渗漏前兆；3 第三方施工要旁站、防破坏、快应急；4 上报要选对卡、描述清、照片准、定位明；5 避开选错卡、描述模糊、照片无效、等级错报四类坑；6 缺陷要跟进、复查、销号全闭环；7 台账要动态更新、做趋势分析。\n引导：本课覆盖复杂场景与全流程管理；现场常卡在报完缺陷就不管；下一步C103讲季节性专项巡检。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"PE给水管","ref":"PE给水管"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"减压型倒流防止器","ref":"减压型倒流防止器"},{"name":"电磁流量计","ref":"电磁流量计"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"}],"pitfall":"【上报缺陷不能只写“坏了”】要明确到具体部件和严重程度；第三方施工段不能只巡一次就完事，要全程旁站；报完缺陷要跟进闭环，不能一报了之。","remark":"—","seq":99,"family":"GW-01 日常巡检与材料缺陷识别","lessonNo":8},{"id":"C103","sub":"GW-01","topic":"季节性专项巡检：冬季防冻与汛期防汛","level":"D4 / L4","d":"D4","l":"L4","positioning":"这一课贴合自来水行业“冬防冻、夏防汛”的核心运维节奏，讲解冬夏两季的专项巡检要点、季节性缺陷识别与应急管控要求，覆盖全年季节性运维场景，对应复杂条件下的巡检处置能力。","framework":"冬季防冻巡检｜裸露管道水表阀门保温层完好性检查；井室防寒、排水孔疏通；低温下胶圈塑料管件脆裂风险排查。\n冻胀缺陷识别｜管道冻胀位移、接口冻裂渗漏、水表冻坏、阀门冻住特征与判断。\n汛期防汛巡检｜低洼地段井室防淹、井盖防坠、管道覆土沉降、排气阀通畅性检查。\n汛后缺陷排查｜雨水浸泡后的接口渗漏、井室塌陷、防腐层冲刷损坏、螺栓锈蚀加速检查重点。\n季节性隐患处置｜防冻应急处置、防汛临时加固、冻损跑水初步管控要求。\n专项台账管理｜防冻防汛专项巡检记录、隐患台账、整改跟进管理要求。\n重点区段管控｜老旧小区、低洼路段、薄弱管段季节加密巡检规则。","lecture":"**相邻关系：向上接 C99《重点场景专项巡检与缺陷上报闭》；本板块到此收束。**\n\n**现场情境：冬天阀门冻住了，有人想硬拧、拿明火烤；汛期井盖被冲飞也没设围挡。** 错在哪？本课讲季节性巡检。\n\n【冬季防冻巡检：保温是第一道防线】\n冬季巡检核心是防冻，重点查三处。第一查裸露管段、水表、阀门的保温层，看保温棉有没有脱落、破损、受潮，保温失效的管件极易冻裂；\n第二查井室防寒，井内有没有填保温材料、井盖有没有防寒层，排水孔有没有堵，井内积水结冰会顶坏接口；\n第三查低温脆裂风险，胶圈、塑料管件低温下会变硬变脆，老旧PE管、PPR管外露段要重点看有没有裂纹。气温骤降时要加密巡检。\n【冻胀缺陷识别：冻坏了有这些信号】\n管道冻损有明显特征。管道冻胀位移会导致地面凸起、井体倾斜，接口受力拉扯容易渗漏；接口冻裂渗漏，刚开始是细水，温度回升后漏水量会突然变大；\n水表冻坏表现为玻璃破裂、表芯冻住、指针不动，解冻后会大量漏水；阀门冻住是转不动手轮、阀杆结冰，不能硬拧，硬拧会拧断阀杆。发现冻住不能用明火烤，要用温水慢慢化。\n【汛期防汛巡检：防淹防塌是重点】\n雨季汛期，巡检重心转向防汛。低洼路段的井室，要检查有没有防淹措施，井盖有没有防坠网，防止雨水倒灌冲飞井盖、人员坠落；管道覆土沉降的路段，大雨后要查有没有水土流失、管道裸露；\n排气阀要确保通畅，管内进气排气顺畅，防止水锤破坏；边坡、河岸的管线，要查有没有滑坡、塌方风险，防止管道悬空断裂。大雨期间重点路段要雨中巡、雨后立刻巡。\n【汛后缺陷排查：泡水后问题集中冒】\n大雨过后，隐患会集中显现。第一查接口渗漏，雨水浸泡导致土壤软化、沉降不均，承插接口最容易漏；第二查井室塌陷，井壁被水泡软、基础下沉，会出现开裂、坍塌；\n第三查防腐层冲刷损坏，外露钢管、管件的防腐层被雨水冲刷、泥沙磨损，会加速腐蚀；第四查螺栓锈蚀加速，井内长期积水，法兰螺栓会快速生锈，影响强度。汛后一周内要完成全线排查。\n【季节性隐患处置：先控风险再整改】\n季节性隐患处置要先控风险。冬季发现冻住的阀门水表，立刻做保温，用温水解冻，不能明火烤、不能硬拧；发现冻裂跑水，先关阀止水，再上报维修。汛期发现井室积水严重，立刻抽排，防止淹没设备；\n发现井盖冲飞、路面塌陷，立刻设围挡、立警示，守现场等处置。所有临时处置都要跟进后续整改，不能临时处理完就完事。\n【专项台账管理：季节性工作留痕迹】\n防冻防汛都要建专项台账。巡检记录要单独归档，注明日期、区段、检查项、发现的问题；隐患台账要登记季节性缺陷，标注风险等级和整改时限；整改完成后同步销号，记录整改时间、处置措施、复查结果。\n每年入冬前、入汛前，都要对照上一年的台账，提前排查重点区段，提前处置隐患。\n【重点区段管控：薄弱地方加密巡】\n季节性巡检不能全线平均用力，要抓重点。老旧小区、管网服役时间长的，防冻防汛能力差，要加密巡；低洼路段、历史上淹过水的，汛期重点盯；薄弱管段、曾经冻坏过、漏过的位置，要反复查。加密巡检的区段，要在台账里标记清楚，明确巡检频次和责任人。\n\n**自测：冻住的阀门能不能硬拧或用明火烤？** 回本课【冬季防冻巡检：保温是第一道防线】对照。\n\n**自测：汛期井盖被冲飞，第一步该做什么？** 回本课【汛期防汛巡检：防淹防塌是重点】对照。","structure":"主链：冬季防冻巡检→冻胀缺陷识别→汛期防汛巡检→汛后缺陷排查→应急处置→专项台账→重点区段管控。\n要点：1 冬季查保温、井室防寒、脆裂风险；2 冻损有位移、渗漏、冻坏、冻住四类表现；3 汛期查防淹、防坠、沉降、排气通畅；4 汛后查接口、井室、防腐、螺栓；5 先控风险再整改，禁用明火烤冻管；6 建立专项台账，逐年对比优化；7 重点区段加密巡检。\n引导：本课覆盖全年季节性运维；现场常卡在冻住了硬拧阀门；GW-01板块到此形成从基础到专项的完整能力链。","anchors":[{"name":"PE给水管","ref":"PE给水管"},{"name":"PPR给水管","ref":"PPR给水管"},{"name":"旋翼式机械水表（湿式/干式/液封）","ref":"旋翼式机械水表（湿式/干式/液封）"},{"name":"黄铜闸阀","ref":"黄铜闸阀"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"可曲挠式橡胶接头","ref":"可曲挠式橡胶接头"}],"pitfall":"【冻住的阀门不能硬拧】会拧断阀杆，也不能用明火烤；汛期井盖冲飞要先设围挡，不能一走了之；季节性隐患不能只临时处置，要跟进彻底整改。","remark":"—","seq":100,"family":"GW-01 日常巡检与材料缺陷识别","lessonNo":9},{"id":"C82","sub":"CL-02","topic":"呆滞物料判定与隔离区标准化管理","level":"D4 / L4","d":"D4","l":"L4","positioning":"本课讲呆滞物料判定与隔离区管理的知识，属于 CL-02 子类的管理闭环课；承接 C74 的四区功能划分与 C81 的混放风险辨析，为 C83 季节性养护中的临期物料处置提供判据。内容集中在四类呆滞料的定义、状态判定、隔离区设置、三条处置路径与台账留痕。","framework":"1. 呆滞料定义与分级｜超期存放、待检不合格、报废待处置、工程余料四类\n2. 判定标准细则｜不同材质超期界定、外观失效判定、性能复检规则\n3. 隔离区设置要求｜物理隔离、标识规范、台账管理、分区规则\n4. 处置路径规则｜复检复用、降级使用、报废审批三类适用边界\n5. 常见管理误区｜随意堆放、超期领用、无台账追溯三类典型错误\n6. 台账登记要点｜物料信息、入库时间、呆滞原因、处置进度四项核心\n7. 复盘与优化｜呆滞库存占比等自查口径、降本措施、持续优化方向","lecture":"**相邻关系：向上接 C81《跨材质混放风险辨析》；向下接 C83《季节性仓储养护》。**\n\n**现场情境：呆滞料堆在角落没隔离、没台账，超期了也没复检就想发。** 风险在哪？本课讲呆滞管理。\n\n【呆滞料定义与分级】\n呆滞物料是指超过正常周转周期、状态待确认或待报废的物料，分四大类。\n第一类超期存放：超过质保期未使用，状态待复检确认。\n第二类待检不合格：到货验收不合格，等待退换货或处置。\n第三类报废待处置：已判定报废，等待走审批与销毁流程。\n第四类工程余料：项目剩余的零散、短尺物料，暂存待复用。\n四类物料风险等级不同，管理要求与处置路径也不同。\n【判定标准细则】\n呆滞判定有明确标准，不能凭感觉随意划分。\n超期判定：先看物料卡与厂家说明标注的质保期，到期即待复检；本子类已明确的口径是 PE 管 2 年、PPR 管 18 个月（C75）、EPDM 密封件 18 个月原包装密封存放（C76）。其他材质或厂家标注更严的，以卡和厂家说明为准。\n外观判定：出现明显老化、锈蚀、变形、破损，且无法修复。\n性能判定：超期物料必须做性能复检，不合格则判定为呆滞报废。\n工程余料：剩余长度不足标准定尺、规格零散无法正常出库。\n所有判定都要有依据，禁止口头判定、随意升级或降级。\n落回卡上：对照超期胶圈、锈蚀六角头螺栓（半丝/全丝），先看状态、再定路径。\n【隔离区设置要求】\n呆滞隔离区必须做到物理隔离、标识清晰、专人管理。\n用围栏、隔墙与合格品区完全隔开，禁止混通混放。\n区域入口悬挂明显标识牌，标注 “呆滞物料隔离区” 字样。\n内部再分四个小区：待检区、不合格区、待报废区、余料区，分区标识。\n指定专人管理，无关人员禁止随意取用，出入必须登记。\n【处置路径规则】\n呆滞物料按状态分三类处置路径，严禁随意降级使用。\n复检复用：超期但外观完好，复检性能合格，办理手续后转回合格品区。\n降级使用：性能达标但外观有瑕疵，可降级用于非关键、非承压部位。\n报废审批：复检不合格、无修复价值，走审批流程后报废处置。\n所有处置必须留书面记录，禁止私自处理、私自调换。\n落回卡上：对照待检中线（软密封）蝶阀、余料 PE 给水管，前者先复检再定复用，后者按余料登记待复用。\n【常见管理误区】\n呆滞管理有三类高频错误，必须重点规避。\n第一类：不设隔离区，呆滞料随便堆在角落，很容易被错领。\n第二类：超期物料心存侥幸，不复检就直接发放使用。\n第三类：无台账无记录，呆滞料放了多久、为什么呆滞都说不清。\n这三类错误都会造成质量风险或资产流失，是管理红线。\n【台账登记要点】\n呆滞物料必须建立专用台账，做到来源可查、去向可追。\n登记四项核心信息：物料名称规格、入库时间与数量、呆滞原因与日期。\n每次处置、复检、移动都要更新记录，保持账物相符。\n定期盘点呆滞库存，跟进处置进度，避免长期积压占用库容。\n台账是呆滞管理的核心凭证，必须完整、准确、可追溯。\n【复盘与优化】\n你可以定期复盘呆滞情况，把库存损耗降下来。\n可自查三个数：呆滞库存占比、呆滞处置及时率、复检复用率。\n优化方向：精准采购减少余料、先进先出减少超期、及时处置减少积压。\n每月复盘呆滞原因，针对性优化采购与库存管理。\n建立呆滞料预警机制，临近质保期提前预警、优先发放。\n\n**自测：呆滞料为什么不隔离就会被错领？** 回本课【隔离区设置要求】对照。\n\n**自测：超期物料使用前要不要复检？** 回本课【判定标准细则】对照。","structure":"知识结构：定义分级→判定标准→隔离设置→处置路径→常见误区→台账管理→考核优化，形成呆滞物料全流程管理闭环。\n学习要点：\n1. 呆滞料分四类：超期、不合格、待报废、工程余料\n2. 判定要有标准，不同材质超期时限不同，不能一刀切\n3. 隔离区必须物理隔离，分区清晰，专人管理\n4. 处置分三条路径：复检复用、降级使用、报废审批\n5. 三大误区不能碰：不隔离、不复检、无台账\n6. 台账是核心凭证，必须账物相符、全程可追溯\n7. 定期自查复盘，从源头减少呆滞产生","anchors":[{"name":"超期胶圈","ref":"胶圈（球墨管承插密封圈）"},{"name":"待检中线（软密封）蝶阀","ref":"中线（软密封）蝶阀"},{"name":"余料 PE 给水管","ref":"PE给水管"},{"name":"报废压力表","ref":"压力表"},{"name":"锈蚀六角头螺栓","ref":"六角头螺栓（半丝/全丝）"}],"pitfall":"1. 呆滞料不隔离，早晚被错领，出了质量事故说不清\n2. 超期物料不复检就用，省了小事，闯了大祸\n3. 呆滞料没台账，放了多久、为什么呆滞全靠记，必乱","remark":"—","seq":101,"family":"其他","lessonNo":9},{"id":"C83","sub":"CL-02","topic":"季节性仓储养护：雨季 / 高温 / 冬季的针对性防护方案","level":"D4 / L4","d":"D4","l":"L4","positioning":"本课讲季节性仓储养护的条件判断知识，属于 CL-02 子类的条件迁移进阶课；C75–C82 按品类讲常态养护，本课把它们放进雨季、高温季、冬季三种工况下重新排优先级，并给出换季巡检与极端天气的处置顺序。内容集中在三季专项防护、巡检顺序、应急处置与前置准备。","framework":"1. 雨季防潮专项｜金属防锈升级、仪表除湿、库区排水、地面返潮处置\n2. 高温季防老化｜塑料橡胶避光降温、胶类温控、保质期复核\n3. 冬季防冻专项｜水表仪表保温、橡胶低温脆化防护、积水除冰\n4. 换季巡检标准｜检查点顺序、记录规范、异常分级上报流程\n5. 极端天气应急｜暴雨倒灌、持续高温、寒潮突袭的临时处置步骤\n6. 前置准备工作｜物资储备、预案演练、隐患排查的前置动作\n7. 地区差异适配｜南方 / 北方、沿海 / 内陆的养护重点差异","lecture":"**相邻关系：向上接 C82《呆滞物料判定与隔离区标准化管理》；本板块到此收束。**\n\n**现场情境：雨季忘了关窗螺栓全锈，高温把 AB 胶晒固化，冬天水表放室外冻裂。** 各季怎么防？本课讲季节养护。\n\n【雨季防潮专项】\n雨季核心风险是潮湿，会加速金属锈蚀、电子受潮、橡胶霉变。\n金属物料升级防锈措施，增加防锈油涂抹频次，重点检查丝扣、边角。\n电子仪表区启动除湿设备，每日记录温湿度；湿度＞60% 即需处置，雨季升级为增加记录频次、超限立即处置。\n提前检查库区排水系统，清理排水沟，防止雨水倒灌库区。\n地面返潮时，垫高物料高度至 30cm 以上，铺防潮垫，禁止直接接触地面。\n阴雨天气关闭门窗，晴朗天气及时通风排潮，动态管控。\n重点巡检：低洼处物料、碳钢小件、电子仪表、纸箱包装物料。\n落回卡上：对照六角头螺栓（半丝 / 全丝）看丝扣锈蚀、对照超声波水表看受潮，按雨季升级措施处置。\n【高温季防老化】\n高温核心风险是加速老化，塑料、橡胶、胶粘剂受影响最大。\n塑料、橡胶物料增加避光措施，避开阳光直射的货架位。\n每日监测库区温度，超过 30℃时采取通风、遮阳等降温措施。\nAB 胶等抢修辅材移入阴凉区，防止高温提前固化失效。\n落回卡上：对照 AB 胶（管道修补剂），看包装是否鼓胀、胶体是否提前固化。\n集中复核临近保质期的物料，优先发放快到期的，避免批量报废。\n严禁在库区进行焊接、动火作业，高温下火灾风险也同步上升。\n重点巡检：西晒墙面物料、橡胶密封件、胶类辅材、电池款仪表。\n【冬季防冻专项】\n冬季核心风险是低温冻损与脆化，仪表、橡胶、塑料需重点防护。\n智能水表、压力表等带液封的仪表移入暖区，防止冻裂损坏。\n橡胶件低温下会变脆，禁止抛摔、弯折，搬运时轻拿轻放。\n塑料管材低温韧性下降，拖拽、磕碰更容易开裂，需加强防护。\n库区地面积水及时清理，防止结冰打滑，造成安全事故。\n门窗缝隙做好密封，防止冷风直吹物料，造成局部温度过低。\n重点巡检：液封类仪表、室外存放物料、橡胶密封件、塑料管材。\n【换季巡检标准】\n换季是养护关键节点，必须按标准流程完成全面巡检。\n巡检顺序：先查库区设施（门窗、排水、消防），再查物料状态。\n金属查锈蚀、橡塑查老化、仪表查功能、辅材查保质期。\n逐项填写巡检记录表，异常问题标注等级，一般问题限期整改。\n重大隐患立即上报，同时采取临时防护措施，防止风险扩大。\n每次换季巡检留存完整记录，作为养护工作的追溯依据。\n【极端天气应急】\n极端天气属于突发状况，按预案快速处置，优先保障人员与核心物料安全。\n暴雨倒灌：第一时间断电，转移低洼处的电子、贵重物料，筑坝挡水。\n持续高温：增加通风降温频次，热敏物料转移至低温区，增加巡检次数。\n寒潮突袭：关闭迎风面门窗，重点仪表加盖保温，暂停室外搬运作业。\n所有应急处置优先保障人员安全，再保护物资，禁止冒险作业。\n事后及时复盘，排查隐患，优化预案，提升下次应对能力。\n【前置准备工作】\n季节性养护重在前置准备，临时抱佛脚往往措手不及。\n雨季前备齐除湿机、防潮剂、排水泵等物资，提前疏通排水。\n高温前检查遮阳、通风设施，盘点热敏物料保质期，做好移库计划。\n入冬前备好保温材料、除冰工具，排查门窗密封情况。\n提前熟悉预案、做过推演，你自己也要清楚险情触发时先做什么、后做什么。\n定期开展隐患排查，把问题解决在季节到来之前。\n【地区差异适配】\n不同气候区的季节性养护重点不同，不能照搬一套标准。\n南方梅雨区：重点强化防潮防霉，延长除湿设备运行时间。\n北方严寒区：重点强化防冻保温，增加低温物料防护等级。\n沿海盐雾区：雨季叠加盐雾，金属防锈升级为更高等级。\n西北干旱区：重点防风沙，高温防护为主，防冻压力小。\n\n**自测：雨季仓储最要紧的防护是什么？** 回本课【雨季防潮专项】对照。\n\n**自测：冬天水表放室外会怎样？** 回本课【冬季防冻专项】对照。","structure":"知识结构：雨季防潮→高温防老→冬季防冻→换季巡检→极端应急→前置准备→地区适配，形成 “预防 - 巡检 - 应急 - 复盘 - 适配” 的季节性养护闭环。\n学习要点：\n1. 雨季重点防潮，高温重点防老化，冬季重点防冻损\n2. 换季必须做全面巡检，逐项排查、记录留痕、分级上报\n3. 极端天气先保人、再保物，按预案有序处置\n4. 功夫在平时，前置准备比临时补救更重要\n5. 不同材质受季节影响不同，防护重点要区分开\n6. 每次应急后要复盘优化，持续提升养护能力\n7. 结合本地气候调整标准，不能全国一刀切","anchors":[{"name":"PE 给水管","ref":"PE给水管"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"超声波水表","ref":"超声波水表"},{"name":"黄铜内螺纹浮动球阀","ref":"黄铜内螺纹浮动球阀"},{"name":"六角头螺栓（半丝 / 全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"AB 胶（管道修补剂）","ref":"AB胶（管道修补剂）"}],"pitfall":"1. 雨季只顾着发货忘了关窗，一周后螺栓管件全锈了\n2. 高温天把 AB 胶放太阳下，还没用来就已经固化了\n3. 冬天把水表放室外冻一夜，液封冻裂表就废了","remark":"可结合本地气候调整巡检周期与防护等级","seq":102,"family":"其他","lessonNo":10},{"id":"C94","sub":"CL-04","topic":"复杂场景盘点与差异闭环管理","level":"D4 / L4","d":"D4","l":"L4","positioning":"这一课面向年度大盘、重大差异、历史遗留等复杂盘点场景，讲解组织方法、处置流程与闭环管理逻辑，覆盖盘点从执行到落地的全管理链路，对应高阶仓管与仓储管理岗的能力要求。","framework":"年度全面盘点组织｜分区负责制、进度管控、质量校验、人员分工的大盘点组织方法。重大差异处置流程｜差异超阈值后的上报路径、专项核查要求、分级审批权限。历史遗留差异处理｜跨年遗留、交接遗留、系统切换遗留三类历史问题的处置流程与核销规则。特殊物料专项盘点｜呆滞报废料、账外物料、防腐 / 抢修专用料的专项盘点方法。系统数据修正｜编码错误、单位错误、状态标注错误、初始库存错误的数据治理流程。整改闭环管理｜原因分析→整改措施→责任落实→效果验证→预防优化的 PDCA 闭环。盘点结果应用｜库存结构优化、呆滞物料治理、流程制度完善、仓管能力提升的落地方向。","lecture":"**相邻关系：向上接 C93《账实差异排查与成因分类辨析》；本板块到此收束。**\n\n**现场情境：年度大盘点期间照常随意收发料不登记，历史差异长期挂账不管。** 为什么不行？本课讲差异闭环。\n\n【年度全面盘点组织：四步管好大盘点】\n年度全面盘点覆盖全库区所有物料，对接财务资产核算，是最复杂的盘点场景，组织要做到四到位。\n第一分区负责制：按库区、按物料大类划分盘点小组，每组设组长、盘点员、复核员，明确责任范围，谁管的库区谁负责，出了问题可追溯。管材区、阀门区、辅材区、仪表区分开。\n第二进度管控：提前制定盘点时间表，明确初盘、复盘、抽盘、差异处理的完成节点，每天跟进进度，避免前松后紧最后赶时间凑数。盘点前提前 3-5 天通知各部门，提前冻结库存，盘点期间原则上停止出入库，确需收发的要单独登记、单独核算。\n第三质量校验：按企业盘点制度设定抽盘比例，财务监盘人员随机抽盘，贵重物料应复盘。抽盘差异率超过阈值的库区，要扩大复盘范围，甚至重新全盘，不能为了赶进度放过差错。\n第四人员分工：盘点员负责初点，复核员负责复点，监盘员负责监督过程合规，三方各司其职。不能一人既盘点又复核，保证互相校验；财务、审计等第三方监盘要全程参与关键环节。\n【重大差异处置流程：按级上报、专项核查】\n遇到重大差异不能瞒也不能乱处理，按流程走。\n上报路径：先报库区主管，再报仓储部门负责人，同步通知财务资产岗；金额特别大的要上报公司管理层，不能压着不报。\n专项核查：由仓储牵头，财务等相关部门参与核查，逐笔核对历史单据，查明原因与责任归属；纪检介入、调阅监控按企业制度执行。\n分级审批：差异处置按金额分级审批，小额由部门负责人审批，大额由公司管理层审批，核销必须有完整佐证材料，不能口头同意就销账。处置结果要形成正式文件，作为账务调整的依据。\n【历史遗留差异处理：三类遗留分别处置】\n历史遗留差异是老大难问题，分三类针对性处理。\n第一类跨年遗留：超过一个会计年度的差异，确实无法追溯原因的，按企业资产减值、核销流程办理，附专项核查报告，审批通过后做账务调整，不能长期挂账悬而不决。\n第二类交接遗留：仓管员交接时未核实清楚的差异，由交接双方和监交人共同核查，能找到原因的按实际原因处理，找不到原因的按交接责任划分，走审批流程核销。\n第三类系统切换遗留：系统上线、升级、更换时数据迁移错误导致的差异，由信息部门出具数据错误证明，仓储部门核实实物后，走数据修正流程调整库存，同时更新数据迁移校验规则，避免下次再出同类问题。\n所有历史遗留差异处理完后，都要在台账中做备注，记录差异原因、处理时间、审批文号，方便后续追溯。\n【特殊物料专项盘点：四类物料单独盘】\n有四类物料不能按普通方式盘点，要做专项盘点。\n第一呆滞报废料：单独存放、单独建账的呆滞、报废、待处理物料，盘点时核对数量、状态、存放时间，确认有没有过期、失效、锈蚀，同时梳理可利用、可报废、可退换的分类，推动后续处置。\n第二账外物料：没有计入正式库存的余料、退旧料、工程剩余料、废料，要单独盘点登记，统计清楚数量、规格、来源，符合入账条件的及时走入账流程，纳入正规库存管理，不能一直放在账外。\n第三防腐 / 抢修专用料：镁合金牺牲阳极、防腐涂料、哈夫节（堵漏器）、抢修胶等应急专用物料，要专项盘点，确保数量充足、状态完好，遇到抢修能立刻调出。汛期、冬季冻期前要专门组织专项盘点，保障应急物资到位。\n第四贵重精密物料：智能水表、电磁流量计、减压阀等价值高、精度高的物料，盘点时要逐台核验外观、精度状态，做好防护，避免磕碰损坏。\n【系统数据修正：规范流程不碰红线】\n系统数据错误不能私自改，按流程走。\n错误类型分四种：编码错误（一物多码、一码多物）、单位错误（单位录错导致数量偏差）、状态标注错误（完好 / 报废 / 呆滞状态标错）、初始库存错误（期初数录错）。\n修正流程：仓储部门提交数据修正申请，附物料编码、错误说明、实物照片、佐证材料；主数据管理部门审核，核实错误真实性；审批通过后由系统管理员操作修改；修改后仓储和财务共同复核数据正确性，确认无误后生效。\n整个过程留痕，申请单、审批记录、修改日志都要存档，禁止任何人私自修改系统库存数据。\n【整改闭环管理：PDCA 全链路落地】\n盘点不能盘完就完，要形成整改闭环。\n第一步原因分析：每个差异都要挖到根本原因，不能只停留在 “发错料”，要找到为什么发错，是标签不清还是摆放混放。\n第二步整改措施：针对原因制定具体整改动作，比如标签不清就补打标签，摆放混放就重新整理库区。\n第三步责任落实：整改任务明确到具体人，设定完成时限，不能泛泛而谈没人负责。\n第四步效果验证：到期检查整改结果，看同类差异有没有再出现，整改有没有落地。\n第五步预防优化：把整改成果固化成制度流程，比如优化发料复核流程、增加易混物料标识，从根源上减少差异。\n\n【盘点结果应用：四个方向提管理】\n盘点结果不是只用来调账，还要用来提升仓储管理水平。\n第一库存结构优化：通过盘点分析库存周转情况，哪些物料积压、哪些物料经常缺货，优化采购计划和库存定额，减少积压和断供。\n第二呆滞物料治理：对盘出来的呆滞料分类处置，能调拨的调拨，能利用的优先利用，能报废的走报废流程，盘活库存资产，减少资金占用。\n第三流程制度完善：针对盘点暴露的流程漏洞，完善收发料流程、盘点制度、库区管理规定，从制度上减少差错。\n第四仓管能力提升：针对高频易错点组织培训，提升仓管员的物料辨识能力和操作规范性，减少人为差错。\n\n**自测：大盘点期间能不能随意出入库？** 回本课【年度全面盘点组织：四步管好大盘点】对照。\n\n**自测：历史遗留差异能不能长期挂账？** 回本课【历史遗留差异处理：三类遗留分别处置】对照。","structure":"组织大盘：分区负责、进度管控、质量校验、分工明确，年度盘点有序推进。\n处置重差：逐级上报、专项核查、分级审批，重大差异合规处理。\n清理遗留：跨年、交接、系统切换三类遗留，分类处置、合规核销、备注留痕。\n专项盘点：呆滞报废、账外物料、抢修专用料、贵重精密件，四类物料专项管理。\n数据修正：编码、单位、状态、初始库存四类错误，走申请 - 审核 - 修改 - 复核流程，全程留痕。\n闭环整改：原因分析→整改措施→责任落实→效果验证→预防优化，PDCA 全链路落地。\n结果应用：优化库存结构、治理呆滞物料、完善流程制度、提升人员能力，盘点价值最大化。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"减压型倒流防止器","ref":"减压型倒流防止器"},{"name":"电磁流量计","ref":"电磁流量计"},{"name":"哈夫节","ref":"哈夫节（堵漏器）"},{"name":"镁合金牺牲阳极","ref":"镁合金牺牲阳极"}],"pitfall":"【大盘点不能随意出入库】年度盘点期间可以随意收发物料不用登记是错误的；历史遗留差异可以长期挂账不处理；系统数据可以私自修改。","remark":"—","seq":103,"family":"其他","lessonNo":5},{"id":"C104","sub":"GW-02","topic":"阀门操作与管网调度全景认知","level":"D1 / L1","d":"D1","l":"L1","positioning":"本课建立GW-02「阀门操作与管网调度」的完整知识地图。 承接XG-02常用材料辨识与GW-01日常巡检。\n\n本课先认识阀门功能、结构、驱动和运行监测。 重点建立全景分类，不展开具体阀门的深层结构和复杂调度判断。","framework":"阀门在供水系统中的位置｜连接水源、输配水干支管、分区节点与用户端，承担控制功能。\n按功能划分阀门族｜截断、调节、止回、排气、防倒流等类型及其任务边界。\n按结构与驱动识别｜闸阀、蝶阀、球阀，以及手动、电动、加密操作方式。\n管网运行的基本变量｜压力、流量、流速、水头及分区之间的相互影响。\n监测与配套设施｜压力表、水表、过滤器、消火栓、阀门井等各自承担的任务。\n操作流程与安全底线｜指令确认、对象确认、规范操作、状态复核、记录反馈。","lecture":"【先导：相邻关系与现场片段】\n**相邻关系：向上承接 XG-02 常用材料辨识与 GW-01 日常巡检，向下接 C105 截断类阀门。** 先建立全景地图，再逐类深入。\n\n**先看一个现场片段：调度让人去“把那个阀关了”。** 到了井室，面对手轮、压力表、过滤器的混合布置，先别动手——按本课的全景分类，把对象认出来、把上下游关系看清楚，再决定动作。\n\n【按功能族认识阀门全景】\n**阀门是管网控制节点，不是孤立的零件。** 它把输水干线、分区支管、泵站和用户端连接成可调度的网络。**阀门的核心价值是控制水流路径。** 通过截断、调节、止回或排气，改变某段管道的运行状态。\n\n**看阀门要同时看上下游关系。** 同一只阀门，对不同管段可能承担分区边界、设备保护或支路控制任务。**落回卡上看实物类别。**「弹性座封闸阀（暗杆式）」和「中线（软密封）蝶阀」属于截断类代表。\n\n**截断类负责通断，调节类负责控制参数。** 闸阀、蝶阀、球阀常用于通断；减压阀用于控制出口压力。**止回类负责限制反向流动。**「旋启式止回阀（金属瓣/橡胶瓣）」利用阀瓣动作阻止倒流。\n\n**排气与防倒流设备解决不同风险。**「复合式排气阀」管理管内空气；倒流防止器降低污染水回流风险。**相邻类别不能混为一谈。** 压力表测压力、过滤器拦杂质，它们是监测或配套设备，不是阀门本体。\n\n**自测：现场一只带手轮的“阀”，怎么判断它是阀门本体还是压力表、过滤器、消火栓这类配套件？** 回本课前三段按功能族逐项对照。\n\n【结构、驱动与用途分开记录】\n**阀门结构决定水流如何被控制。** 闸板升降、蝶板旋转、球体转动，形成不同的启闭路径。**驱动方式决定操作接口。** 手轮或手柄由人操作，电动执行机构通过电机和减速机构驱动阀杆。\n\n**加密机构增加授权控制。**「加密闸阀」和「黄铜加密闸阀」通过专用锁芯与离合结构限制非授权启闭。**结构、驱动、用途要分开记录。**\n\n**不要把“电动”误当成一种阀门功能，也不要把“加密”误当成水力功能。**\n\n【压力、流量和水头是关联变量】\n**压力反映管网的能量状态，流量反映单位时间通过的水量。** 两者会随用水量、泵站工况和阀门状态变化。**阀门改变局部阻力和水流路径。**\n\n**阀门开度变化会影响流量分配，但具体变化还受管径、上下游压力和网络结构影响。**分区边界决定调度影响范围。**一处阀门动作可能影响多个支路，不能只看阀井内的单个阀体。**\n\n**压力、流量和水头是关联变量。** 不能只凭手轮转数或阀门外观推断管网已达到目标状态。\n\n【仪表与配套设施不是阀门本体】\n**压力表提供就地压力读数。**「压力表」显示测点压力，「压力表弯（缓冲弯/冷凝弯）」用于缓冲脉动、保护仪表。**机械水表记录通过水量。**\n\n**「旋翼式机械水表（湿式/干式/液封）」通过叶轮传动计数，不替代压力测量。**过滤器保护阀门和仪表。**「法兰Y型过滤器」与「螺纹Y型过滤器」截留杂质，不承担减压或截断任务。**\n\n**消火栓和井盖属于配套设施。**「地上式消火栓」「地下式消火栓」提供消防取水；井盖保护井室，不属于阀门。\n\n**自测：台账把一只设备写成“电动、加密”，这两个词描述的是水力功能吗？** 回本课【结构、驱动、用途要分开记录】处找答案。\n\n【标准操作：先确认，再受控执行】\n**标准操作必须从指令和对象确认开始。** 先核对调度要求、阀门编号、位置和管网关系，再按制度执行。**操作过程要受控并可复核。**\n\n**按企业规程平稳操作，观察阻力、异常声响和相关监测数据，不以手感代替结果确认。**严禁用蛮力换取动作。**卡涩、异常阻力、井室积水或环境风险出现时，应停止并按程序报告。**\n\n**具体权限和技术参数以企业制度为准。** 本课只建立原则，不代填操作票、审批层级或具体压力目标。\n\n【现场识别与四项记录对应】\n**现场识别要把名称、型号、连接方式和功能放在一起核对。材料卡上的「弹性座封闸阀（暗杆式）」对应埋地管网常见截断设备；「中线（软密封）蝶阀」是另一种截断结构，不能只凭外形混记。**\n\n**「先导式减压阀」承担出口压力调节；**「旋启式止回阀（金属瓣/橡胶瓣）」限制反向流动；「复合式排气阀」负责管内空气管理。**仪表和附件要单独归类。**\n\n**「压力表」提供测点压力，「法兰Y型过滤器」拦截杂质，「地上式消火栓」和「地下式消火栓」属于消防供水设施。**\n\n**现场记录至少保留四项对应关系。1. 设备名称与材料卡名称一致；2. 型号与连接形式一致；3. 安装位置与管网功能一致；**4. 运行状态与监测数据对应。","structure":"**全景映射：** 供水系统节点 → 阀门功能族 → 结构与驱动 → 水力变量 → 监测配套 → 操作闭环。\n**六项识别要点：**\n1. 截断、调节、止回、排气、防倒流对应不同任务。\n2. 闸板升降、蝶板旋转、球体旋转是三种不同运动逻辑。\n3. 手动、电动、加密描述驱动或授权方式，不是水力功能分类。\n4. 压力表、水表、Y型过滤器、消火栓分别属于监测、计量、过滤和消防供水设施。\n5. 阀门动作必须放回上下游关系与分区边界理解。\n6. 结果要结合阀位、压力、流量和供水反馈确认。\n**结构小结：** 先认功能和位置，再认结构与驱动，最后理解监测、操作和安全边界。\n**课程衔接：** 下一课进入截断类阀门，沿闸阀、蝶阀、球阀的结构差异展开。","anchors":[{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"中线（软密封）蝶阀","ref":"中线（软密封）蝶阀"},{"name":"黄铜内螺纹浮动球阀","ref":"黄铜内螺纹浮动球阀"},{"name":"先导式减压阀","ref":"先导式减压阀"},{"name":"旋启式止回阀（金属瓣/橡胶瓣）","ref":"旋启式止回阀（金属瓣/橡胶瓣）"},{"name":"复合式排气阀","ref":"复合式排气阀"},{"name":"减压型倒流防止器","ref":"减压型倒流防止器"},{"name":"压力表","ref":"压力表"}],"pitfall":"【功能类别不要混淆】压力表是监测件、Y型过滤器是过滤附件、消火栓是消防供水设施，都不是阀门本体；阀门开到某个位置不等于管网运行状态已确认。\n【驱动不是功能】“电动”说的是驱动方式，“加密”说的是授权控制，都不是水力功能类别，别把它们当阀门类型记。","remark":"材料锚点均取自最新材料采集包「公司现用」卡名。具体调度权限、阀门编号规则和操作票要求由企业按现行制度补充。","seq":104,"family":"GW-02 阀门操作与管网调度","lessonNo":1},{"id":"C105","sub":"GW-02","topic":"截断类阀门结构原理与标准化启闭操作","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课说明截断类阀门这一类知识。 集中解释闸阀、蝶阀、球阀及手动、电动、加密驱动结构。\n\n本课重点说清结构为什么这样动作。 覆盖启闭机理、用途边界、驱动差异、状态确认和操作风险，不把一种阀门的规则套给所有阀门。","framework":"截断类阀门的任务与分类｜闸阀、蝶阀、球阀在通断控制中的定位。\n闸阀结构与密封机理｜阀杆、闸板、阀座、填料及明暗杆差异。\n蝶阀结构与开度关系｜蝶板、阀杆、阀座、手柄或蜗轮驱动。\n球阀结构与旋转密封｜浮动球体、PTFE阀座、手柄90°旋转。\n加密与电动驱动｜锁芯离合、专用钥匙、执行机构、限位与力矩保护。\n标准化启闭与状态确认｜对象核对、操作过程、位置确认、异常停止与反馈。","lecture":"【先导：相邻关系与现场情境】\n**相邻关系：向上接 C104 全景认知，向下接 C106 功能类阀门。** 本课沿闸阀、蝶阀、球阀的结构差异展开。\n\n**现场情境：接到任务关闭一只暗杆闸阀。** 手轮转了很多圈、阀杆却纹丝不动，操作前先确认它是暗杆结构，别用“阀杆没升”当开度依据。\n\n【截断类三阀：结构差异决定操作】\n**截断类阀门主要承担管路通断控制。** 它们通过改变阀内通道状态，使管段处于通水或隔断状态。**闸阀、蝶阀和球阀的运动方式不同。** 闸板作升降运动，蝶板绕阀杆旋转，球体通过旋转改变通道方向。\n\n**不同结构不能只按外形选择操作方法。** 各自的行程、密封面和驱动方式不同，错误动作会损伤阀座或传动件。**落回材料卡识别三类代表。**\n\n**「弹性座封闸阀（暗杆式）」「中线（软密封）蝶阀」「黄铜内螺纹浮动球阀」。**\n\n【闸阀：闸板升降与暗杆识别】\n**闸阀靠闸板升降实现通断。** 旋转阀杆后，螺纹传动把旋转变为闸板上下移动，像螺旋千斤顶推动挡板。**弹性座封结构依靠橡胶包胶闸板贴合阀座。**\n\n**「弹性座封闸阀（暗杆式）」卡载阀杆不升降、闸板升降的结构特点。**暗杆式阀杆旋转但不随行程升降。** 井室上方净空要求较小，不能用阀杆外露长度判断开度。**闸阀通常用于全开或全关。\n\n**自测：暗杆闸阀阀杆没有升高，能不能据此判断阀门还没开？** 回本课【闸阀靠闸板升降实现通断】处，记住“阀杆不升降、闸板升降”。\n\n**不宜长期以非设计中间开度节流，否则可能造成冲刷、振动或密封面损伤。**\n\n【蝶阀：蝶板旋转与开度边界】\n**蝶阀靠蝶板旋转改变流通面积。** 蝶板像管道中一扇可转动的门，转角变化会改变水流通道。**中线软密封蝶阀以橡胶阀座形成密封。**「中线（软密封）蝶阀」卡载居中阀杆、蝶板和EPDM阀座等结构信息。\n\n**蝶阀可快速完成通断，也可在规定条件下参与调节。** 可用开度范围需按阀型、执行机构和调度要求确定。**不要把蝶板角度简单等同于流量百分比。** 管网流量还受上下游压差、管径和其他节点影响。\n\n【球阀：约90°切换与行程差异】\n**浮动球阀以球体旋转控制通道。** 球体内部有通孔，手柄转动约90°即可在全开和全关状态间切换。**介质压力帮助浮动球体压紧出口阀座。**「黄铜内螺纹浮动球阀」卡载PTFE阀座和浮动球体结构。\n\n**球阀适合小口径快速切断。** 全通径结构流阻较小，但其快速动作也要求关注启闭速度和水锤风险。**球阀与闸阀的行程逻辑不同。** 不能把闸阀多圈旋转的经验套到球阀手柄上。\n\n**自测：球阀手柄转约 90° 就到全开，能否照搬闸阀“转多少圈”的经验？** 回本课【浮动球阀以球体旋转控制通道】处对照三种行程。\n\n【加密与电动：授权与控制接口】\n**加密阀在传动链中增加授权锁定机构。** 无专用钥匙时手轮可能空转，不代表阀门内部故障。**磁性或机械锁芯的解锁逻辑不同。**「加密闸阀」「黄铜加密闸阀」卡载磁性防盗或机械密码防盗结构。\n\n**电动蝶阀由执行机构输出低速大扭矩。** 电机经减速箱驱动阀杆，限位与力矩开关用于行程和负载保护。**落回卡上核对控制接口。**「电动蝶阀」卡载软密封、硬密封系列及手动操作手柄等信息；\n\n**模式切换按设备说明和企业制度执行。**\n\n【标准化启闭：对象、动作与结果】\n**操作前先确认对象、指令和管网关系。** 核对阀门名称、编号、位置、功能及其影响的上下游范围。**操作中要受控，不以速度和圈数作为唯一依据。** 按阀门类型和现行规程平稳动作，遇到异常阻力立即停止。\n\n**操作后要确认机械位置与水力结果。** 检查指示位置、相关压力或流量变化及下游反馈，不能只凭“手轮转到底”判定成功。**【红线】禁止加长扳手强拧、带故障反复冲击或擅自切换电动/手动模式。**\n\n**异常交由授权人员按规程处理。**\n\n【四项核对：把操作写成闭环】\n**阀门操作不是只把手轮转到头，而是完成对象、指令、动作和结果四项核对。操作前核对阀门编号、现场位置、阀型、驱动方式、目标状态及上下游关系；发现编号或位置不一致，先停下核实。**\n\n**操作接口必须与阀门结构匹配。「弹性座封闸阀（暗杆式）」阀杆旋转但不升降；「中线（软密封）蝶阀」通过蝶板旋转改变通道；「黄铜内螺纹浮动球阀」通常以约90°转动切换通道。**加密和电动设备要多核一层。\n\n**「加密闸阀」先确认专用钥匙与锁芯适配；**「电动蝶阀」先确认控制模式、现场/远程状态、限位和报警信息，切换方式按设备说明及企业制度执行。**动作中要观察阻力、声音和反馈。**\n\n**按调度方案及设备要求平稳操作，不把圈数、时间或指示灯当成唯一完成依据；**出现异常阻力、异响、渗漏或报警立即停止并反馈。**动作后要同时确认机械位置和水力结果。**\n\n**核对阀位反馈，并观察相关测点压力、流量及下游供水反馈；**记录实际结果与预期是否一致。","structure":"**操作主链：** 指令核实 → 对象定位 → 阀型/驱动确认 → 现场条件核查 → 受控启闭 → 位置确认 → 水力结果复核 → 记录反馈。\n**六项操作要点：**\n1. 暗杆闸阀阀杆旋转但不升降，不能用外露高度判断开度。\n2. 蝶阀靠蝶板旋转改变流通面积，开度不等于流量百分比。\n3. 浮动球阀以球体旋转切换通道，不能套用闸阀多圈操作经验。\n4. 加密阀先核钥匙与锁芯适配，手轮空转不等于阀体损坏。\n5. 电动阀同时核控制模式、限位/力矩反馈和现场实际状态。\n6. 操作完成必须同时核对机械位置和管网运行结果。\n**结构小结：** 操作方法由结构决定，操作结果由机械反馈与水力证据共同确认。\n**课程衔接：** 下一课从通断控制转向减压、止回、排气和防倒流等功能设备。","anchors":[{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"中线（软密封）蝶阀","ref":"中线（软密封）蝶阀"},{"name":"黄铜内螺纹浮动球阀","ref":"黄铜内螺纹浮动球阀"},{"name":"黄铜闸阀","ref":"黄铜闸阀"},{"name":"黄铜加密闸阀","ref":"黄铜加密闸阀"},{"name":"加密闸阀","ref":"加密闸阀"},{"name":"电动蝶阀","ref":"电动蝶阀"}],"pitfall":"【闸阀不宜长期节流】暗杆阀杆旋转不升降；加密手轮空转可能是未解锁；电动蝶阀的指示到位不等于密封面绝对无泄漏。\n【行程不能套用】闸阀多圈升降、蝶阀转角、球阀约90°，三种行程逻辑不同，别把一种的操作经验套给另一种。","remark":"黄铜闸阀为材料卡标注的现行特定工况材料；阀门操作圈数、行程时间、扭矩和电动模式切换按设备说明及企业制度确认。","seq":105,"family":"GW-02 阀门操作与管网调度","lessonNo":2},{"id":"C106","sub":"GW-02","topic":"功能类阀门工作原理与运行控制","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课系统讲解压力控制、单向控制、排气和防倒流设备。 并把过滤器、压力表等配套件放入正确的系统位置。\n\n本课重点解释内部机理、适用边界和相互保护关系。 不把过滤器、仪表等辅助设备误归为阀门。","framework":"减压阀分类与反馈调节｜先导式、直动式及其适用流量和稳压要求。\n止回阀的单向控制｜旋启式、缓闭式、小口径弹簧式结构与关闭机理。\n排气阀的空气管理｜快速排气、微量排气、复合式排气的分工。\n倒流防止器的污染防护｜低阻力型与减压型的结构及风险边界。\n过滤器的杂质拦截｜法兰和螺纹Y型过滤器的结构、维护关注点。\n压力监测与仪表保护｜压力表、压力表弯及读数应用边界。","lecture":"【先导：从通断控制到功能设备】\n**相邻关系：向上接 C105 截断类阀门，向下接 C107 片区停水与压力管理。** 从通断控制转向减压、止回、排气与防倒流。\n\n**现场情境：某减压阀下游压力偏低。** 现场同时有过滤器和压力表——按本课的设备组合思路，先看过滤是否堵塞、测点是否可信，别一上来就调减压阀。\n\n【减压阀：先导式与直动式】\n**减压阀通过自动改变阀口开度稳定出口压力。** 它像自动调节水龙头，出口压力变化会引起内部机构动作。**先导式先由导阀感知，再控制主阀。**\n\n**「先导式减压阀」卡载导阀、反馈取压孔、膜片和主阀活塞等结构。**直动式由介质压力直接作用于膜片。**「直动式减压阀」卡载阀瓣、膜片、弹簧和调节螺钉，结构相对简单。**两者不能只按口径替换。\n\n**流量波动大、稳压精度要求高时要综合评估先导式；直动式适合较小流量、低压差等特定工况。**\n\n【止回阀：限制倒流，不替代隔离】\n**止回阀依靠正向水流开启、反向趋势关闭。** 它像单向门，限制水流倒回上游，保护泵和计量设备。**旋启式阀瓣绕铰链摆动。**「旋启式止回阀（金属瓣/橡胶瓣）」卡载摇板、摇杆和阀座等结构。\n\n**缓闭式通过弹簧和缓闭机构控制关闭过程。**「静音式（缓闭）止回阀」卡载弹簧辅助阀瓣与缓闭装置。**止回阀不是截断阀的替代品。** 它不用于日常人工隔离，选型需结合流向、安装位置和水锤风险。\n\n**自测：止回阀能挡住倒流，能否当作人工隔离阀用来停水检修？** 回本课【止回阀不是截断阀的替代品】处找边界。\n\n【排气阀：按排气量与工况分工】\n**排气阀按空气排放量和工况分工。** 快速排气处理充水初期大量空气，微量排气持续排出析出的气体。**复合式兼顾大孔和小孔排气。**\n\n**「复合式排气阀」通过大、小浮球和杠杆，完成大量排气、微量排气及负压进气保护。**快速排气阀强调充水初期排气能力。**「快速排气阀（高速排气阀）」卡载大排气口与浮筒，水满后浮筒关闭排气口。**\n\n**微量排气依靠浮球随水位变化启闭。**「微量排气阀（黄铜自动排气阀）」和「小口径黄铜自动排气阀」用于较小口径或局部持续排气。\n\n【倒流防止器：阻断污染回流】\n**倒流防止器的核心任务是阻断污染水回流。** 它保护上游生活饮用水，不能简单等同于普通止回阀。**减压型依靠两级止回和中腔泄水形成更高防护。**\n\n**自测：高风险污染回流节点，能否图省水损直接用低阻力型倒流防止器？** 回本课【低阻力型不能直接用于高风险边界】处对照风险边界。\n\n**「减压型倒流防止器」卡载减压装置、两级止回和中腔泄水阀。**低阻力型优化流道以降低水损。**「低阻力倒流防止器」适用于回流污染风险较低、对水损敏感的节点。**防护等级和适用风险要一起判断。\n\n**低阻力型不能直接用于高风险边界隔离，具体采用哪型按风险评估和企业设计要求确定。**\n\n【Y型过滤器：拦截杂质，保护下游】\n**Y型过滤器拦截颗粒，保护下游阀门和仪表。** 水流经过滤网，焊渣和杂质被截留在滤筒内。**法兰型和螺纹型主要区别在连接方式。**「法兰Y型过滤器」采用法兰连接；「螺纹Y型过滤器」采用螺纹连接。\n\n**过滤器堵塞会带来压差和流量异常。** 但它本身不调压、不截断，也不能用来解释所有压力波动。**落回卡上看滤网和排污端。** 清理方式、隔离条件和复装要求按设备说明及企业维护规程执行。\n\n【压力表：读数要结合测点与工况】\n**压力表用于读取测点压力，不是调压装置。**「压力表」通过弹簧管位移带动指针显示压力。**压力表弯可缓冲压力脉动。**「压力表弯（缓冲弯/冷凝弯）」延长介质路径，降低瞬时冲击对仪表的影响。\n\n**读数必须连同测点和工况解释。** 单点压力不能代表全网压力，比较数据要注意时间、位置和仪表状态。**仪表异常先核表、接口和测点。** 不要因单个读数异常就擅自调整减压阀设定值。\n\n【成组判断：单台设备解释不了全部现象】\n**功能设备通常成组工作，单台设备不能解释全部运行现象。减压阀前端的过滤条件、上下游压力测点、止回设备和排气设备共同影响运行判断；设备安装位置与流向必须先核实。**压力偏低时不要直接调减压阀。\n\n**先核对压力表量程、测点和读数时间，再比较阀前阀后压力，并检查过滤器是否堵塞、阀门是否处于目标状态及供水侧是否变化。**\n\n**流量受限时要区分局部阻力与管网供水变化。**\n\n**「法兰Y型过滤器」和「螺纹Y型过滤器」的连接形式不同，但都承担杂质拦截；**滤网堵塞可能增加局部压降，不能把过滤器误当成调压设备。**止回阀与倒流防止器不能互相替代。**\n\n**「旋启式止回阀（金属瓣/橡胶瓣）」限制反向流动；**「低阻力倒流防止器」与「减压型倒流防止器」的防护结构和适用风险边界不同。**排气设备的故障表现也要区分。**\n\n**高点积气、排气不畅、浮球关闭异常和接口渗漏是不同现象；**不得通过松动承压接口来试排气。**记录要把设备链条写完整。**\n\n**至少记录设备名称、流向、上下游测点、压力/流量表现、过滤器状态及异常发生时间，便于调度和专业人员复核。**","structure":"**设备关系主链：** 过滤保护 → 压力调节 → 单向控制 → 空气管理 → 倒流防护 → 仪表监测。\n**六项设备要点：**\n1. 先导式减压阀由导阀反馈控制主阀；直动式由膜片/弹簧直接平衡。\n2. 止回阀限制反向流动，不替代人工隔离阀。\n3. 快速、微量、复合式排气阀按排气量和工况分工。\n4. 低阻力与减压型倒流防止器的防护结构和适用风险边界不同。\n5. Y型过滤器拦截杂质，堵塞可能增加局部阻力，但不承担调压功能。\n6. 压力表读取测点压力，压力表弯保护仪表，二者都不执行调节。\n**结构小结：** 先分清设备职责，再看内部机理和适用边界，最后用监测数据交叉核实。\n**课程衔接：** 下一课把这些设备放回片区管网，分析停水、复水和压力管理。","anchors":[{"name":"先导式减压阀","ref":"先导式减压阀"},{"name":"直动式减压阀","ref":"直动式减压阀"},{"name":"低阻力倒流防止器","ref":"低阻力倒流防止器"},{"name":"减压型倒流防止器","ref":"减压型倒流防止器"},{"name":"静音式（缓闭）止回阀","ref":"静音式（缓闭）止回阀"},{"name":"旋启式止回阀（金属瓣/橡胶瓣）","ref":"旋启式止回阀（金属瓣/橡胶瓣）"},{"name":"黄铜立式/卧式止回阀","ref":"黄铜立式/卧式止回阀"},{"name":"复合式排气阀","ref":"复合式排气阀"},{"name":"快速排气阀（高速排气阀）","ref":"快速排气阀（高速排气阀）"},{"name":"微量排气阀（黄铜自动排气阀）","ref":"微量排气阀（黄铜自动排气阀）"},{"name":"小口径黄铜自动排气阀","ref":"小口径黄铜自动排气阀"},{"name":"法兰Y型过滤器","ref":"法兰Y型过滤器"},{"name":"螺纹Y型过滤器","ref":"螺纹Y型过滤器"},{"name":"压力表","ref":"压力表"},{"name":"压力表弯（缓冲弯/冷凝弯）","ref":"压力表弯（缓冲弯/冷凝弯）"}],"pitfall":"【功能不能串岗】过滤器拦杂质不调压；压力表只监测不控制；止回阀防倒流不替代隔离阀；低阻力倒流防止器不作为高污染风险边界的通用替代。\n【设备不能串岗】过滤器拦杂质、压力表只监测、止回阀防倒流，谁都不能顶替别人的职责，组合判断才可靠。","remark":"直动式减压阀、静音式（缓闭）止回阀的材料卡状态为现行特定工况；具体选型与维护条件以设计文件、设备说明和企业制度为准。","seq":106,"family":"GW-02 阀门操作与管网调度","lessonNo":3},{"id":"C107","sub":"GW-02","topic":"管网基础运行调控：片区停水、恢复供水与压力管理","level":"D2 / L2","d":"D2","l":"L2","positioning":"本课把阀门放回管网系统。 讲解压力、流量、分区边界、片区隔离、恢复供水和压力波动之间的关系。\n\n本课建立从调度目标到动作和监测反馈的基本运行链。 不设定企业具体压力指标或固定启闭顺序，动作以管网拓扑、调度方案和现行规程为准。","framework":"管网水力变量与相互关系｜压力、流量、流速、水头和局部阻力。\n分区与阀门边界｜干支管、联络管、分区阀及上下游影响范围。\n片区停水的控制逻辑｜确认范围、明确边界、协调相关阀门与用户影响。\n恢复供水的基本逻辑｜复核管网条件、受控恢复、观察压力与流量变化。\n压力调节与监测｜减压阀、压力表、过滤器及水表数据的不同作用。\n水锤与空气风险｜流速突变、快速启闭、管内积气和压力波动。\n调度反馈与闭环｜指令确认、过程记录、结果反馈和异常升级。","lecture":"【先导：从单阀到片区】\n**相邻关系：向上接 C106 功能类阀门，向下接 C108 故障辨析。** 把设备放回片区管网，看停水、复水与压力管理。\n\n**现场情境：某片区准备停水，图上有联络管。** 是先关最近的阀，还是先确认边界与备用路径？带着这个问题读完本课。\n\n【压力、流量与流速：三种运行信息】\n**压力、流量和流速描述的是不同运行信息。** 压力反映测点能量状态，流量是单位时间通过的水量，流速反映水体移动快慢。**阀门动作会改变局部阻力和水流分配。**\n\n**像调整道路通行宽度，车流会重新分配，但结果还受其他道路和车流量影响。**同一开度不代表同一流量。**上下游压力、管径、管网连接和其他阀门状态都会改变实际流量。**落回监测件看变量。\n\n**「压力表」看测点压力，「旋翼式机械水表（湿式/干式/液封）」记录累计水量，不能互相替代。**\n\n【分区边界：由拓扑与阀门共同形成】\n**分区由管网拓扑和阀门边界共同形成。** 先看干管、支管、联络管和分界阀，再判断某处动作影响哪些用户。**阀门位置必须与管网图相互核对。**\n\n**一只阀门可能控制单条支路，也可能同时影响跨区联络或消防供水。**阀门状态和边界功能要分开确认。**设备显示关闭，不等于目标区域已完全隔离，仍需结合现场和监测反馈判断。**\n\n**常用隔离点可关联「弹性座封闸阀（暗杆式）」。** 材料卡将其定位为全开全关截断，常用于埋地管网。\n\n【停水控制：先定范围再定动作】\n**停水控制先明确范围和目标，再确定阀门动作。** 不能先关最近的一只阀门，再倒推影响范围。**停水前要确认上下游和关联供水路径。** 需要检查联络管、备用路径、重点用户及消防供水影响。\n\n**自测：片区要停水，能不能先关离得最近的那只阀再说？** 回本课【停水控制先明确范围和目标】处，记住先看联络管与备用路径。\n\n【多阀协同与信息同步】\n**多阀协同取决于管网结构。** 动作顺序要由调度方案决定，不存在适用于所有管网的固定“先开后关”或“先关后开”。**实施过程中保持信息同步。**\n\n**阀门位置、操作反馈和压力变化及时回传，避免不同岗位按不同版本信息操作。**\n\n【恢复供水：不是把阀门打开就结束】\n**恢复供水不是把阀门重新打开就结束。** 需要确认管段条件、相关作业已完成、供水路径明确并获调度许可。**受控恢复有助于降低压力突变风险。** 按企业规程和调度要求平稳操作，避免快速改变水流状态。\n\n**自测：阀门已经打开了，能不能就算“供水已恢复”？** 回本课【恢复完成要有结果确认】处，核对多个代表性节点。\n\n**恢复过程要观察多个代表性节点。** 关注压力、流量、用户反馈和异常声响，必要时按程序调整恢复节奏。**恢复完成要有结果确认。**\n\n**记录实际阀位、供水状态和未消除异常，不用“阀门已开”代替“供水已恢复”。**\n\n【压力管理：减压阀、过滤器与测点】\n**减压阀控制出口压力，压力表呈现测点读数。**「先导式减压阀」通过导阀与反馈取压控制主阀，「直动式减压阀」由膜片与弹簧直接平衡。**压力表弯保护测量元件。**\n\n**「压力表弯（缓冲弯/冷凝弯）」可减缓脉动冲击，读数仍需检查仪表量程和状态。**过滤器堵塞可能造成局部压降。**「法兰Y型过滤器」截留杂质，需把滤网状态纳入排查，不可直接把所有低压归因于减压阀。**\n\n**橡胶接头吸收位移与振动。**「可曲挠式橡胶接头」不是调压阀，也不能替代管网水力调控。\n\n【水锤与积气：两类动态风险】\n**水锤来自水流速度快速变化引发的压力波。** 像长水管里的水柱突然被制动，压力扰动会沿管线传播。**快速启闭会放大压力冲击。** 阀门操作速度应遵守企业规程和设备要求，不能以“越快越省时”为目标。\n\n**管内积气会改变流动状态。** 高点空气聚集可能引起流量受限、压力波动或运行噪声。**排气设备按功能配合。**\n\n**「复合式排气阀」兼顾大量和微量排气，「快速排气阀（高速排气阀）」主要处理充水初期大量空气。**\n\n【调控闭环：指令、动作与结果】\n**每次调控都要把指令、动作和结果连起来。** 调度要求明确后，执行、监测、反馈和记录形成闭环。**反馈至少包含位置和运行状态。** 阀位、测点压力、流量变化、影响范围和异常情况需要有对应记录。\n\n**异常读数先核实测点与仪表。** 比较同一时段的上下游和相邻节点，避免单点异常导致错误调度。**【红线】没有授权或缺少管网边界信息时，不擅自改变分区阀状态。** 具体操作程序由企业调度制度确定。\n\n**停水前先形成同一时点的运行基线。记录目标片区、关联阀门、上下游测点、压力读数、流量或水表累计量、重点用户及消防供水影响；不同时间口径的数据不能直接比较。**分区边界要按管网拓扑确认。\n\n**联络管、环状管网、备用水源和支路可能形成绕供路径；**地图上的阀门位置还要与现场编号、实际阀位相互核实。**停水动作不存在全网通用的固定先后顺序。**\n\n**阀门组合和动作次序由管网结构、隔离目标、调度指令及企业规程决定；**不能把某一片区的经验直接复制到另一片区。**恢复供水要关注压力变化而不只是阀门开度。**\n\n**按调度方案和设备要求受控恢复，观察代表性节点压力、流量、用户反馈及异常声响；**出现偏离预期的变化要暂停并反馈。**压力、流量和水表数据要分工解释。「压力表」反映测点压力；**\n\n**「旋翼式机械水表（湿式/干式/液封）」记录累计水量；**流量变化需结合统计时段和管网路径分析。**水锤风险来自水流速度快速变化。快速启闭、泵站切换或流向变化可能形成压力波；**\n\n**「复合式排气阀」和「快速排气阀（高速排气阀）」处理空气问题，但不能代替正确的调度控制。**\n\n**闭环信息至少包括计划、动作、监测和反馈。**\n\n**记录调度目标、阀门编号、实际动作、测点数据、影响范围、用户反馈和未解决异常，避免只写“已停水”或“已复水”。**","structure":"**运行调控主链：** 建立运行基线 → 核实管网拓扑 → 明确停水边界 → 按调度方案动作 → 受控恢复 → 监测压力/流量 → 反馈闭环。\n**六项运行要点：**\n1. 压力、流量、流速和水头描述不同运行信息，不能互相替代。\n2. 阀门开度改变局部阻力，但流量还受压差、管径和网络结构影响。\n3. 停水边界必须核查联络管、备用路径、重点用户和消防供水。\n4. 不存在适用于所有管网的固定“先开后关”或“先关后开”顺序。\n5. 恢复供水要观察多个代表性节点，不能只以阀门已开作为完成依据。\n6. 水锤与积气要结合阀门动作、泵站工况和排气设备状态辨析。\n**结构小结：** 先认管网结构，再定调度边界；动作中监测，恢复后复核。\n**课程衔接：** 下一课进入阀门操作异常与故障证据辨析。","anchors":[{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"先导式减压阀","ref":"先导式减压阀"},{"name":"直动式减压阀","ref":"直动式减压阀"},{"name":"复合式排气阀","ref":"复合式排气阀"},{"name":"快速排气阀（高速排气阀）","ref":"快速排气阀（高速排气阀）"},{"name":"压力表","ref":"压力表"},{"name":"压力表弯（缓冲弯/冷凝弯）","ref":"压力表弯（缓冲弯/冷凝弯）"},{"name":"法兰Y型过滤器","ref":"法兰Y型过滤器"},{"name":"旋翼式机械水表（湿式/干式/液封）","ref":"旋翼式机械水表（湿式/干式/液封）"},{"name":"可曲挠式橡胶接头","ref":"可曲挠式橡胶接头"}],"pitfall":"【不存在通用的固定启闭顺序】必须按管网拓扑、调度指令和企业规程确定；水表不测压力，压力表不计水量；水锤风险不能只靠“阀门已关到位”判断。\n【顺序没有通用解】停复水顺序由管网结构和调度方案决定，不存在全网通用的固定先后；恢复要看多个测点。","remark":"企业填：片区分区图、调度权限、压力目标、停复水通知和恢复确认要求按公司正式制度补充；不在课程中代设数值或审批层级。","seq":107,"family":"GW-02 阀门操作与管网调度","lessonNo":4},{"id":"C108","sub":"GW-02","topic":"阀门操作误区与常见故障辨析","level":"D3 / L3","d":"D3","l":"L3","positioning":"本课围绕截断类阀门的操作反馈和常见异常。 建立“症状—结构—驱动—外部条件—处置边界”的辨析框架。\n\n本课重点区分卡涩、关不严、外漏、异常声响和驱动故障。 训练识别错误归因与不当操作，不提供强行拆修或带压处理步骤。","framework":"操作异常的分类框架｜动作异常、密封异常、外部泄漏、驱动异常和运行异常。\n阀门类型与操作反馈对照｜闸阀多圈升降、蝶阀旋转、球阀约90°切换。\n开不动与关不严的原因辨析｜机械卡阻、传动故障、异物、密封损伤及压差影响。\n加密阀与电动阀故障辨析｜锁芯未解锁、离合空转、限位与力矩信号异常。\n外漏、内漏与管网未隔离辨析｜阀杆填料、连接处、阀座泄漏及其他供水路径。\n故障处置边界与复核｜停止、报告、保护现场、确认系统状态和结果。","lecture":"【先导：相邻关系与现场情境】\n**相邻关系：向上接 C107 运行调控，向下接 C109 运行异常辨析。** 与 GW-01 巡检前后衔接，用外部证据辅助辨析。\n\n**现场情境：一只暗杆闸阀操作时阻力突然增大。** 有人提议接长钢管加力关到底——按本课红线，这正是不能做的动作。为什么？读完自测会回答。\n\n【先描述现象，再判断故障类别】\n**先描述现象，再判断故障类别。** 手轮转不动、动作过轻、阀杆渗水、阀后仍有压力，是不同信息不能混写成“阀门坏了”。**动作异常不等于阀体损坏。**\n\n**可能来自传动机构、锁定机构、执行机构、异物或管网压差等不同环节。**故障记录要包含对象和状态。**写明阀门名称、位置、操作方式、异常出现阶段及关联压力变化。**与GW-01巡检形成前后衔接。\n\n**巡检发现的锈蚀、渗漏和井室异常，是本课故障辨析的外部证据。**\n\n【把手感和行程放回结构解释】\n**闸阀以阀杆旋转带动闸板升降。**「弹性座封闸阀（暗杆式）」阀杆旋转但不升降，不能靠阀杆外露量判断行程。**蝶阀以蝶板旋转改变通道。**\n\n**「中线（软密封）蝶阀」在转动过程中蝶板一直处于流道内，开度与流动状态有关。**球阀通过球体旋转切换通道。**「黄铜内螺纹浮动球阀」的常见操作行程约90°，与多圈闸阀不同。**\n\n**把手感和行程放回结构解释。** 不能把闸阀多圈、蝶阀转角和球阀手柄位置用同一套经验判断。\n\n【开不动与关不严：分开诊断】\n**开不动可能是传动、锈蚀、异物或压差问题。** 先确认阀型、驱动方式和可见外部状态，不以加力作为诊断。**关不严可能来自密封面或阀座问题。** 异物夹入、橡胶老化、阀板行程不到位都可能造成内漏。\n\n**“阀门关了仍有水”不等于唯一原因是阀座失效。** 还要核查旁通、联络管、其他供水路径和管段残余压力。**【红线】不得用加长杆、冲击或多人强拧逼迫阀门动作。**\n\n**自测：阀后仍有压力，第一反应就是“阀座坏了”吗？** 回本课【关不严可能来自密封面或阀座问题】处，先分清旁通与残余压力。\n\n**这会把可诊断问题变成阀杆、闸板或执行机构损坏。**\n\n【加密阀手轮空转：先确认授权】\n**加密手轮空转首先要区分是否完成授权解锁。**「加密闸阀」和「黄铜加密闸阀」的离合机构在未解锁时可与阀杆脱开。**解锁失败不代表锁芯可以强拆。** 核对专用钥匙和适配关系，异常时按授权流程报告处理。\n\n**自测：加密阀手轮空转，能不能判定阀体损坏并强行拆解？** 回本课【加密手轮空转首先要区分是否完成授权解锁】处找答案。\n\n【电动阀不动作：区分电源、信号与负载】\n**电动阀不动作要区分电源、控制信号和机械负载。**「电动蝶阀」卡载执行机构、限位和力矩开关等组成。**指示位置、力矩报警和实际水力状态是不同证据。** 不能只看控制屏显示就判定阀门内腔已严密关闭。\n\n【内漏与外漏：证据不同】\n**外漏是水从阀体外部或连接处逸出。** 可能出现在阀杆填料、阀盖结合面、法兰连接和外部密封处。**内漏是阀门关闭后仍有水通过阀内密封面。** 外部看不到水，不代表隔断功能一定可靠。\n\n**阀后仍有压力要先核查测点和管网路径。** 压力可能来自残余水、反向连通或其他供水路径，不应直接拆阀验证。**相邻设施提供辅助证据。**\n\n**压力表可观察测点变化，但读数异常时需同时核表、测点和接口状态。**\n\n【异常处置：先停止，再复核】\n**出现异常阻力、明显泄漏或异常声响时先停止操作。** 保持现场安全，按公司现行报告和调度程序处理。**复核要区分机械状态与管网状态。**\n\n**查看阀位、上下游压力、相关支路和操作反馈，必要时安排专业检查。**未经许可不拆卸承压部件。**本课不讲带压拆修、强行解体或绕过联锁的技术步骤。**故障闭环需要记录现象、判断依据和后续结果。\n\n**不能把“暂时恢复动作”写成“故障已排除”。**\n\n【四类故障辨析与可复现记录】\n**故障辨析先把现象拆成机械、密封、驱动和管网四类。机械类关注阀杆、传动件和异物；密封类关注阀座、阀瓣及填料；驱动类关注锁芯、执行机构和控制信号；管网类关注旁通、联络管和残余压力。**\n\n**开不动时先辨认阻力出现在哪个环节。核对阀型和驱动接口，观察是否有外部卡阻、锈蚀、异响或电动报警；不得加长扳手、冲击或多人强拧。**关不严时不能只盯着阀座。\n\n**异物夹入、密封面损伤、行程不到位、阀门规格不适配及旁通路径，都可能造成隔离效果不符合预期。**\n\n**外漏和内漏的证据不同。阀杆、阀盖、法兰处可见渗水属于外部泄漏线索；**\n\n**关闭后仍有流量或压力变化可能涉及内漏，也可能来自其他供水路径。****电动阀要把控制反馈与实际状态分开记录。「电动蝶阀」的限位、力矩、控制信号和现场阀位是不同证据；显示到位不等于阀座绝对严密。**\n\n**异常记录要可复现。写明阀门编号、动作方向、异常出现阶段、环境条件、报警信息、上下游数据及已采取的停止/报告动作，不用“阀门坏了”代替事实。**","structure":"**故障辨析主链：** 现象记录 → 阀型/驱动识别 → 机械/密封/电气/管网分类 → 证据交叉核对 → 停止与报告 → 复核闭环。\n**六项辨析要点：**\n1. 开不动可能来自传动、锁芯、执行机构、异物或压差，不等于阀体必坏。\n2. 关不严要区分阀座、阀瓣、行程和其他供水路径。\n3. 外漏与内漏的可见证据不同，记录位置和运行状态。\n4. 加密手轮空转先核钥匙与锁芯，不得强拆。\n5. 电动阀显示到位不等于密封面绝对严密。\n6. 异常阻力、异响和明显泄漏出现时停止强行操作，按授权流程报告。\n**结构小结：** 先把症状说准，再按结构和证据辨因，最后守住停止、报告和复核边界。\n**课程衔接：** 下一课把故障辨析扩展到压力、流量、空气和水质异常。","anchors":[{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"中线（软密封）蝶阀","ref":"中线（软密封）蝶阀"},{"name":"黄铜内螺纹浮动球阀","ref":"黄铜内螺纹浮动球阀"},{"name":"黄铜闸阀","ref":"黄铜闸阀"},{"name":"黄铜加密闸阀","ref":"黄铜加密闸阀"},{"name":"加密闸阀","ref":"加密闸阀"},{"name":"电动蝶阀","ref":"电动蝶阀"},{"name":"压力表","ref":"压力表"}],"pitfall":"【不要用蛮力诊断故障】手轮空转先核加密解锁；阀后有压先核旁通和其他供水路径；电动阀信号到位不等于密封绝对可靠。\n【证据要分清】外漏看得见、内漏看不见但阀后有流量；电动阀信号到位不等于密封严密，记录要分项写。","remark":"黄铜闸阀为特定工况现用卡。涉及拆卸、承压部件处理、电气检修等工作，按公司授权范围及专项规程执行。","seq":108,"family":"GW-02 阀门操作与管网调度","lessonNo":5},{"id":"C109","sub":"GW-02","topic":"管网运行异常与阀门调控响应辨析","level":"D3 / L3","d":"D3","l":"L3","positioning":"本课把阀门知识与管网异常现象连接起来。 重点辨析压力偏高、压力偏低、压力波动、流量异常、气阻、倒流风险和水质异常。\n\n本课建立数据、设备状态、管网路径和风险边界之间的对应关系。 训练原因分类与响应判断，不把运行调控等同于抢修施工。","framework":"异常识别与数据有效性｜压力、流量、测点、仪表量程和时间对应关系。\n压力偏高与偏低辨析｜上下游压差、减压阀状态、过滤器阻塞及供水变化。\n压力波动与水锤辨析｜启闭变化、泵站工况、阀门动作和管内空气。\n流量异常与管网路径辨析｜用水变化、阀门开度、过滤器阻塞和旁通影响。\n气阻与排气设备辨析｜积气位置、排气阀功能和运行现象。\n止回与倒流风险辨析｜止回阀动作、倒流防止器保护等级与污染风险。\n水质异常与调度响应边界｜污染风险隔离、报告、监测和恢复确认。","lecture":"【先导：从单阀故障到运行异常】\n**相邻关系：向上接 C108 故障辨析，向下接 C110 应急隔离。** 从单阀故障扩展到压力、流量、空气和水质异常。\n\n**现场情境：某分区压力和流量同时下降，上游压力表暂时正常。** 原因可能有多种，别急着把锅扣给减压阀。本课教你怎么按证据逐项排查。\n\n【异常判断先确认数据可信】\n**异常判断必须先确认数据是否可信。** 核对测点位置、仪表量程、读数时间、仪表状态和数据来源。**压力表只代表对应测点。**「压力表」的读数不能直接代表全网，比较前应确认测点上下游关系。\n\n**水表数据与压力数据互补。**「旋翼式机械水表（湿式/干式/液封）」记录通过水量，可帮助观察流量变化，但不能替代压力测量。**仪表弯和过滤状态也会影响判断。**\n\n**「压力表弯（缓冲弯/冷凝弯）」保护测量件；滤网堵塞可能带来局部压降。**\n\n【压力偏高/偏低：先看供水与控制】\n**压力偏高先看供水工况与减压控制。** 上游压力变化、下游用水减少或减压阀调节异常都可能改变出口压力。**压力偏低要同时检查供水侧和局部阻力。**\n\n**自测：某点压力偏低，能不能直接判定是减压阀坏了？** 回本课【不能只调弹簧或设定螺钉】处，先核上游供水、过滤器和阀位。\n\n**上游供水不足、阀门状态、过滤器堵塞和漏损等都可能影响压力。**先导式与直动式减压阀的响应特点不同。**「先导式减压阀」经导阀控制主阀，「直动式减压阀」由膜片与弹簧直接平衡。**\n\n**不能只调弹簧或设定螺钉。** 应先核对上下游数据、阀组和过滤器状态，再按调度授权决定后续动作。\n\n【短时压力突变：考虑水锤】\n**短时压力突变要考虑水流速度变化。** 阀门快速启闭、泵站切换或流向突变都可能形成压力波。**水锤不是普通的静态高压。** 压力波会沿管道传播，可能造成振动、噪声、接口冲击和设备损伤。\n\n**缓闭止回结构用于降低关闭冲击。**「静音式（缓闭）止回阀」通过弹簧和缓闭机构控制阀瓣末段关闭。**柔性接头只能承担其设计补偿作用。**「可曲挠式橡胶接头」吸收位移和振动，不替代正确的水力控制。\n\n【流量异常：不一定是阀门关小】\n**流量降低不一定是阀门关小。** 还要考虑上游供水、用户需求、滤网堵塞、仪表故障和管线漏损等因素。**流量增大也不一定代表供水改善。**\n\n**可能来自异常用水、管网连通变化或漏损，需要结合压力与区域信息判断。**Y型过滤器会截留杂质并产生局部阻力。**「法兰Y型过滤器」和「螺纹Y型过滤器」要按连接形式和所在位置辨认。**\n\n**水表累计量要转换为同一时间口径比较。** 不同统计时段的读数不能直接相减后当作瞬时流量。\n\n【高点积气：影响过水状态】\n**高点积气会影响管道过水状态。** 气体聚集可能造成有效过水断面变小、压力波动和局部流量受限。**快速排气与微量排气承担不同任务。**\n\n**「快速排气阀（高速排气阀）」处理大量空气，「微量排气阀（黄铜自动排气阀）」排出溶解空气析出的微量气体。**复合式排气阀兼顾不同排气阶段。\n\n**「复合式排气阀」在充水、运行集气及负压等状态下通过浮球和大小孔切换。**排气阀漏水或不排气要核设备状态。**不得擅自松动承压接口排气，处置按设备说明和企业规程执行。**\n\n**自测：高点流量受限，能不能靠松开承压接口来“放气”排气？** 回本课【高点积气会影响管道过水状态】处，按排气阀状态处置。\n\n【止回与倒流防止：风险边界不同】\n**止回阀处理反向流动，倒流防止器处理污染回流风险。** 两者的功能目标相关但防护结构和等级不能混为一谈。**旋启式止回阀依靠阀瓣摆动关闭。**\n\n**「旋启式止回阀（金属瓣/橡胶瓣）」卡载阀瓣材质和结构差异。**减压型倒流防止器具有中腔泄水防护。**「减压型倒流防止器」通过两级止回和中间泄水腔提高回流污染防护。**低阻力型适用风险边界较低。\n\n**「低阻力倒流防止器」优化流道降低水损，不应被误用为高风险边界的通用替代。**\n\n【水质异常：按供水安全风险处理】\n**水质异常先视为供水安全风险信息。** 需要及时报告、保护信息、按企业预案确定隔离和监测措施。**阀门隔离范围要结合污染可能路径。** 不能只关闭距离最近的阀门而忽略联络管、回流路径和其他水源。\n\n**倒流防止设施状态是风险判断的一部分。** 同时核实设备泄水、上下游压力和相关供水边界。**恢复供水前要完成规定的确认。** 具体采样、检测和放水流程由主管部门及企业现行制度确定，本课不代设标准。\n\n【证据链：同一时间轴逐项排查】\n**先建立同一时间轴，再比较不同测点。压力、流量、水表累计量和用户反馈必须标注采集时间、位置、仪表状态；不同时间段的数据不能拼成同一工况。**压力下降与流量下降同时出现，原因仍可能不止一种。\n\n**需要比较上游供水、分区阀位、过滤器压差线索、减压阀状态、管网漏损和用户需求变化，不能单点归因。**\n\n**压力波动要区分瞬态冲击和持续偏差。短时尖峰、周期波动与长时间偏高/偏低代表不同问题；**\n\n**结合泵站切换、阀门动作、止回阀关闭和管内积气等时间线索分析。**\n\n**高点气阻与过滤器堵塞的路径不同。气阻通常与高点空气聚集及排气状态有关；过滤器堵塞表现为局部阻力增加，需结合安装位置和前后状态判断。**\n\n**水质异常优先按供水安全风险处理。核对异常报告、可能回流路径、倒流防止设备状态及影响范围，及时向调度和相关岗位反馈；检测、隔离和恢复程序按主管部门要求及企业预案执行。**\n\n**结论要写成“证据支持的可能原因”，不能越级定故障。把已确认事实、待核实信息、可能原因和建议的下一步核查分开记录，避免把推测写成设备故障结论。**","structure":"**异常辨析映射：** 数据验真 → 压力/流量分类 → 设备状态核查 → 管网路径复核 → 风险评估 → 调度反馈。\n**六项辨析要点：**\n1. 压力偏低不等于减压阀故障，先核测点、上游供水和局部阻力。\n2. 流量下降不等于阀门关小，还要核查用户需求、过滤器和供水路径。\n3. 短时压力突变与持续高/低压不是同一类现象。\n4. 高点气阻与过滤器堵塞的原因、位置和证据不同。\n5. 止回阀限制反向流动，倒流防止器侧重污染回流风险防护。\n6. 水质异常按供水安全风险及时报告，检测与恢复按主管部门和企业预案执行。\n**结构小结：** 数据先验真，现象再分类，设备和路径交叉核对，最后按风险反馈。\n**课程衔接：** 下一课进入应急工况下的隔离边界和供水影响判断。","anchors":[{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"先导式减压阀","ref":"先导式减压阀"},{"name":"直动式减压阀","ref":"直动式减压阀"},{"name":"复合式排气阀","ref":"复合式排气阀"},{"name":"低阻力倒流防止器","ref":"低阻力倒流防止器"},{"name":"减压型倒流防止器","ref":"减压型倒流防止器"},{"name":"旋启式止回阀（金属瓣/橡胶瓣）","ref":"旋启式止回阀（金属瓣/橡胶瓣）"},{"name":"静音式（缓闭）止回阀","ref":"静音式（缓闭）止回阀"},{"name":"压力表","ref":"压力表"},{"name":"压力表弯（缓冲弯/冷凝弯）","ref":"压力表弯（缓冲弯/冷凝弯）"},{"name":"旋翼式机械水表（湿式/干式/液封）","ref":"旋翼式机械水表（湿式/干式/液封）"},{"name":"法兰Y型过滤器","ref":"法兰Y型过滤器"},{"name":"可曲挠式橡胶接头","ref":"可曲挠式橡胶接头"}],"pitfall":"【不要单点归因】压力低不等于减压阀坏，流量少不等于阀门关小；倒流防止器选型看污染风险，低阻力型不等于高防护型。\n【数据先验真】压力低不等于减压阀坏、流量少不等于阀关小；不同时段的数据不能拼成同一工况。","remark":"直动式减压阀、静音式（缓闭）止回阀为材料卡标注的现行特定工况。水质检测、隔离和恢复程序按主管部门要求及企业预案执行。","seq":109,"family":"GW-02 阀门操作与管网调度","lessonNo":6},{"id":"C110","sub":"GW-02","topic":"应急工况下的阀门操作与管网隔离处置","level":"D4 / L4","d":"D4","l":"L4","positioning":"本课说明突发管网异常下的阀门隔离、供水控制和调度响应。 属于GW-02的条件迁移层。\n\n本课覆盖信息核实、影响范围、最小有效隔离、多阀协同、消防供水、安全和结果确认。 不展开管道切割、堵漏、哈夫节安装等GW-03抢修工艺。","framework":"应急信息核实与风险分级｜事件位置、影响范围、供水异常和信息可信度。\n管网拓扑与隔离边界判定｜阀门位置、联络管、分区边界和可能影响路径。\n最小有效隔离原则｜控制影响范围与维持必要供水之间的平衡。\n多阀协同与动作顺序｜依据管网结构、调度指令和现场反馈组织动作。\n消防与重点用户供水协调｜消火栓、医院等重点供水影响核查。\n操作安全与水力风险｜受控启闭、水锤、井室环境和人员防护边界。\n隔离验证、信息反馈与恢复｜现场状态、压力流量、影响范围和恢复条件。","lecture":"【先导：本课边界与现场情境】\n**相邻关系：向上接 C109 异常辨析；管道切割、堵漏与恢复施工转入 GW-03。** 本课只覆盖阀门隔离与运行控制。\n\n**现场情境：片区突发大量漏水，调度要求尽快控制影响范围。** 隔离区内还连着一处消防供水节点——时间紧，但边界要想清楚。本课只讲原则与边界。\n\n【应急核实：不凭传闻大范围关阀】\n**应急操作先核实信息，不凭单条传闻直接大范围关阀。** 确认事件位置、时间、异常类型和报告来源。**风险判断要同时看影响范围和供水后果。** 区分局部漏损、突发压力异常、倒流污染风险和消防供水影响。\n\n**核实事件点与管网图是否对应。** 需要明确道路、井位、阀门编号、支路走向和可能的备用供水路径。**信息不完整时及时回传调度。** 不自行补造未知阀位、供水关系或故障原因。\n\n【隔离边界：由管网拓扑决定】\n**隔离边界由管网拓扑决定。** 需要同时查看上游、下游、联络管、支路和其他水源，不能只按地理距离选阀门。**优先考虑最小有效隔离范围。**\n\n**自测：隔离时是不是关的阀越多越安全？** 回本课【隔离目标是阻断风险路径，不是关闭最多阀门】处，比较方案的用户影响。\n\n**在控制风险的同时，评估受影响用户、重要设施和消防供水连续性。**阀门编号和实际位置必须相互核对。**「弹性座封闸阀（暗杆式）」等常见埋地阀门应通过台账和现场标识确认身份。**\n\n**【边界】无法确认阀门身份或网络路径时，不以试关方式探路。** 应请求调度和熟悉管网人员共同确认。\n\n【最小有效隔离：阻断风险而非多关阀】\n**隔离目标是阻断风险路径，不是关闭最多阀门。** 关阀过多会扩大停水范围，影响用户和其他供水功能。**边界选择要比较不同方案。** 评估每个方案的隔离完整性、受影响范围、供水替代路径和复水难度。\n\n**必要时保留可控供水路径。** 关键用户和消防供水需纳入调度评估，不能为了局部处置忽视其他风险。**隔离方案应有明确执行和复核点。** 说明目标阀门、预期压力变化、关注节点和停止条件。\n\n【多阀动作顺序：依管网结构而定】\n**多阀动作顺序取决于具体管网结构。** 不存在适用于所有现场的固定“先开后关”或“先关后开”。**动作前把每只阀门的功能说清。**\n\n**截断阀承担隔离，减压阀控制出口压力，止回与倒流防止设备承担保护功能。**操作过程中按指令平稳执行并逐步反馈。**关注阀位、上下游压力、流量变化和相邻区域供水状态。**\n\n**出现预期外变化要暂停并回报。** 不连续追加关阀动作掩盖方案偏差。\n\n【消防供水：必须纳入影响评估】\n**消防供水设施必须纳入隔离影响评估。**「地上式消火栓」和「地下式消火栓」是消防取水设施，不是阀门本体。**地上式与地下式消火栓的布置和操作接口不同。**\n\n**自测：消火栓不是阀门，隔离方案里是不是就不用管它？** 回本课【消防供水设施必须纳入隔离影响评估】处找边界。\n\n**地上栓体露出地面，地下式栓体位于井室内，均需确认对应供水管网状态。**井盖是人员和设施的防护边界。**「球墨铸铁井盖（给水/消防）」用于覆盖阀门井或消防井，缺失、破损需先控制现场风险。**\n\n**重点用户和消防影响要及时沟通。** 具体联络对象、通知机制和保障标准按企业应急预案执行。\n\n【作业安全与操作速度】\n**应急不等于可以快速强行启闭。** 操作速度按阀型、管网状态和企业规程控制，避免压力突变和水锤。**井室作业先守住环境安全。**\n\n**涉及有限空间时遵循先通风、再检测、后作业等基本原则，禁止盲目下井和盲目施救。**异常阻力、渗漏或阀门损坏时停止强行操作。**不使用加长杆，不擅自拆卸承压部件或绕过电气联锁。**\n\n**【情境示例】本课只说明风险识别和处置原则。** 严格执行国家最新相关作业标准及公司现行作业票制度。\n\n【结果验证与受控恢复】\n**隔离是否成功要用结果验证。** 结合目标区段压力、流量、用户反馈和其他供水路径判断，不能只看阀位。**将实际动作与预期结果对照。** 若压力、流量或影响范围与方案不符，暂停下一步动作并反馈调度。\n\n**恢复供水需重新确认条件。** 根据风险解除情况、管网状态和授权指令制定受控恢复安排。**应急闭环要留下可追溯记录。** 记录事件、方案版本、动作反馈、受影响区域、异常和恢复结果。\n\n【方案要素与可追溯记录】\n**隔离方案要同时比较风险控制和供水影响。至少核对事件位置、风险类型、管网拓扑、联络管、可替代供水路径、受影响用户、消防节点和预计恢复条件。**最小有效隔离不是简单地少关几只阀门。\n\n**方案必须能切断目标风险路径，同时避免不必要地扩大停水范围；**如果无法确认边界完整性，应先补齐管网信息并反馈调度。**每只阀门都要有明确的方案角色。**\n\n**说明它是隔离边界阀、分区控制阀还是调节/保护设备，并核实编号、位置、阀型和当前状态；**不得把减压阀、止回阀当作普通截断阀随意替代。**消防供水和重点用户必须进入影响清单。**\n\n**「地上式消火栓」和「地下式消火栓」是消防供水设施，不是阀门本体；**隔离方案需评估其供水是否受影响。**动作后要按预期结果逐项验证。核对阀位、上下游压力、目标区段状态、相邻区域供水和消防节点；**\n\n**任何一项与方案不符，都要暂停后续动作并反馈。**\n\n**现场安全条件是方案成立的前提。关注井盖、交通、积水、照明和有限空间风险；【情境示例】严格执行国家最新相关作业标准及公司现行作业票制度。**\n\n**本课边界止于阀门隔离与运行控制。管道切割、堵漏、哈夫节安装和恢复施工工艺转入GW-03，不在本课展开。**","structure":"**应急动作链：** 信息核实 → 管网拓扑确认 → 风险分级 → 最小有效隔离方案 → 授权与协同 → 受控动作 → 运行验证 → 反馈恢复。\n**六项应急要点：**\n1. 未核实事件位置、阀门身份和管网路径前，不凭猜测扩大关阀范围。\n2. 隔离边界由拓扑和风险路径决定，不按地理距离简单选阀。\n3. 最小有效隔离要同时考虑风险控制、用户影响和替代供水。\n4. 消火栓是消防供水设施，必须纳入隔离影响评估，但不是阀门本体。\n5. 动作顺序由调度方案、管网结构和企业规程决定，不存在通用固定顺序。\n6. 隔离结果要用阀位、压力、流量和受影响区域反馈验证。\n**业务边界：** 本课只覆盖阀门隔离、供水控制和调度响应；管道切割、堵漏及哈夫节安装转入GW-03。\n**结构小结：** 先核信息和路径，再定最小隔离，按指令协同动作，最终用运行数据验证。","anchors":[{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"中线（软密封）蝶阀","ref":"中线（软密封）蝶阀"},{"name":"加密闸阀","ref":"加密闸阀"},{"name":"地上式消火栓","ref":"地上式消火栓"},{"name":"地下式消火栓","ref":"地下式消火栓"},{"name":"先导式减压阀","ref":"先导式减压阀"},{"name":"复合式排气阀","ref":"复合式排气阀"},{"name":"减压型倒流防止器","ref":"减压型倒流防止器"},{"name":"低阻力倒流防止器","ref":"低阻力倒流防止器"},{"name":"压力表","ref":"压力表"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"}],"pitfall":"【不要把应急等同于多关阀】按管网拓扑选择最小有效隔离范围；消火栓是消防供水设施，不是阀门本体；本课不展开管道切割、堵漏和抢修安装。\n【最小有效隔离】不是关阀越多越安全，要在控风险与保供水之间权衡；消火栓不是阀门但要评估其供水影响。","remark":"【情境示例】有限空间、带压及其他特殊作业仅讲原则和边界；严格执行国家最新相关作业标准及公司现行作业票制度。调度权限与应急联络按企业预案补充。","seq":110,"family":"GW-02 阀门操作与管网调度","lessonNo":7},{"id":"C111","sub":"GW-02","topic":"阀门操作全流程与运行管理闭环","level":"D4 / L4","d":"D4","l":"L4","positioning":"本课将阀门操作提升为可追溯的运行管理闭环。 覆盖指令接收、对象核验、操作准备、过程控制、结果确认、记录反馈和后续维护。\n\n本课明确企业制度内容的引用边界。 不自行编造审批层级、操作票模板、压力目标或维护周期。","framework":"操作对象与台账基础｜阀门编号、名称、位置、功能、型号和上下游关系。\n指令接收与授权边界｜指令来源、任务范围、授权确认和信息复核。\n操作前准备｜对象确认、现场环境、工具、通信和风险检查。\n操作过程控制｜按阀型和调度要求实施动作、观察异常并及时反馈。\n结果确认与运行验证｜阀位、压力、流量、供水范围和关联设施状态。\n记录、交接与异常闭环｜操作时间、人员、指令、结果、异常和后续跟踪。\n运行维护与制度衔接｜巡检、状态跟踪、缺陷上报、检修计划和记录追溯。","lecture":"【先导：把全流程串成闭环】\n**相邻关系：向上回溯 C104—C110 全部内容，形成 GW-02 完整知识网。** 把结构、功能设备、调控、异常与应急串成闭环。\n\n**现场情境：复水窗口临近，执行人在群里回了句“已完成”。** 没有阀门编号、没核对压力变化——这算闭环吗？读完本课就知道还缺什么。\n\n【台账：让每只阀门可识别、定位、追溯】\n**台账的首要作用是让每只阀门可识别、可定位、可追溯。** 关键字段包括编号、名称、位置、口径、型号、功能和上下游关系。**材料名称与现场设备身份必须一致。**\n\n**例如「弹性座封闸阀（暗杆式）」与「中线（软密封）蝶阀」不能只按外形或井位混记。**加密和电动属性需要单独标注。**「加密闸阀」「电动蝶阀」还涉及钥匙管理、执行机构和控制接口。**\n\n**台账要与现场变化同步。** 阀门更换、位置调整、编号变化及功能变更应按企业程序更新，不能只改纸面记录。\n\n【指令核对：先核对象、授权与版本】\n**每次操作先核对指令来源和任务范围。** 明确操作对象、目标状态、影响区域、执行要求和反馈渠道。**授权范围不能由操作者自行推定。** 调度权限、审批层级、操作票和联络机制以公司现行制度为准。\n\n**自测：群里一句“去把那个阀关了”就能直接动手吗？** 回本课【指令与现场条件不一致时先暂停核实】处，核对象、授权和版本。\n\n**指令与现场条件不一致时先暂停核实。** 阀门编号不符、拓扑不清、现场环境异常，都不能用经验补齐。**指令版本需要保持一致。** 多岗位协同应确认同一目标和同一管网边界，防止重复或相反操作。\n\n【准备工作：设备、现场与通信】\n**准备工作要覆盖设备、现场和通信三类条件。** 核对阀型、驱动方式、实际位置、工具适配性和现场安全。**机械阀要确认操作接口匹配。**\n\n**加密阀核专用钥匙，电动阀核控制模式和现场状态，不以蛮力克服异常。**现场环境检查是操作前置条件。**关注井盖、积水、交通、照明和有限空间风险，必要时按制度设置警戒。**作业边界要提前说清。\n\n**本课的阀门操作不包含带压拆装、管道切割、堵漏或下井抢修。**\n\n【操作过程：可观察、可沟通、可停止】\n**操作过程必须可观察、可沟通、可停止。** 按阀门结构和调度要求实施受控动作，异常出现立即暂停并报告。**不同阀型不能套用同一动作口令。**\n\n**闸阀多圈传动、蝶阀蝶板旋转、球阀约90°切换，电动阀还涉及执行机构状态。**减压和排气设备要关注自动动作。**「先导式减压阀」与「复合式排气阀」会随压力和水位变化自动调节，不应随意干预内部机构。**\n\n**多岗位沟通要同步动作状态。** 每一步动作、异常和临时停止都应回报，避免调度信息滞后。\n\n【结果确认：机械状态与水力结果】\n**操作完成要核机械状态和水力结果。** 检查阀位或执行机构反馈，并观察相关测点压力、流量和供水区域变化。**压力表只能证明测点状态。**\n\n**「压力表」读数需结合安装位置和仪表状态解释，不能单独证明整段管网隔离成功。**消防及其他配套设施状态要纳入确认。**「地上式消火栓」「地下式消火栓」属于供水设施，需关注相关区域供水是否受影响。**\n\n**结果与预期不一致时不能直接销项。** 重新核对阀门身份、拓扑路径和其他供水来源，按程序升级处理。\n\n【记录：还原一次操作全过程】\n**记录要能还原一次操作全过程。** 至少关联任务来源、阀门身份、操作时间、执行情况、监测结果和异常反馈。**异常记录不能只写“已处理”。**\n\n**应说明现象、影响范围、采取措施、待办事项、责任交接和复核结果。**交接要传递未完成风险。**尚未恢复、阀位不明、监测异常或消防供水受影响等信息必须明确交接。**记录是后续追溯和分析的依据。\n\n**以一致的编号、时间和对象关联巡检、调度、维修及运行数据。**\n\n【维护管理：以状态和企业计划为依据】\n**维护管理以状态和企业计划为依据。** 关注锈蚀、渗漏、操作异常、执行机构状态、井室环境和标识完整性。**不同类型设备的关注点不同。**\n\n**自测：能不能给所有阀门统一定个“每 6 个月操作一次”写进台账？** 回本课【本课不规定统一维护周期】处，按设备状态与企业制度确定。\n\n**加密阀要关注钥匙与锁芯，电动阀关注驱动和反馈，减压阀关注压力变化及过滤条件。**消火栓和井室设施应纳入关联管理。**「球墨铸铁井盖（给水/消防）」涉及井室防护，不能因其不是阀门本体而漏掉。**\n\n**【边界】本课不规定统一维护周期。** 检查频率、操作票格式、审批层级、压力目标和台账字段按企业现行制度确定。\n\n【闭环记录要素与交接】\n**记录必须能还原“谁因何指令、操作哪只阀、结果怎样”。建议关联任务/指令来源、授权依据、阀门编号与名称、现场位置、操作人员、时间、目标状态和实际动作。**操作前后数据要能比较。\n\n**记录动作前后的阀位或执行机构反馈、代表性测点压力、流量/水表数据、受影响区域及用户反馈；**测点和时间口径必须一致。**异常记录要写事实、影响和待办。**\n\n**写明异常发生阶段、可见现象、报警信息、停止动作、已报告对象、当前风险和后续复核事项，不能只写“已处理”。**\n\n**交接要把未闭环事项显式传递。**\n\n**阀位未确认、供水未恢复、监测异常、消防供水受影响或需专业检修的事项，都要标注当前状态和下一步责任接口。**\n\n**维护管理要按设备类型看状态。加密阀关注锁芯、钥匙和操作接口；电动蝶阀关注执行机构、限位和反馈；**\n\n**减压阀关注压力变化及过滤条件；**排气阀关注排气状态和外漏。**周期和权限不能由课程自行设定。维护频次、操作票格式、审批层级、压力目标和台账字段，均按公司正式制度、设备说明和实际运行条件确定。**\n\n**台账更新要与现场变更同步。更换、迁移、编号调整、功能变化和缺陷处理完成后，按企业流程更新记录，保证巡检、调度和维护使用同一设备身份。**","structure":"**管理闭环：** 台账识别 → 指令核实与授权 → 操作准备 → 受控操作 → 结果验证 → 记录反馈 → 交接维护 → 台账更新。\n**六项闭环要点：**\n1. 对象一致：编号、名称、位置、型号和上下游关系相互对应。\n2. 指令一致：来源、目标、范围、授权和版本清楚可追溯。\n3. 动作一致：阀型、驱动方式、现场反馈和实际动作有记录。\n4. 结果一致：阀位、压力、流量、供水范围和关联设施状态相互验证。\n5. 记录完整：时间、人员、异常、处置、待办和交接信息能还原过程。\n6. 维护管理按设备状态、设备说明和公司正式制度执行，不擅自设定统一周期。\n**结构小结：** 从设备身份和指令开始，以运行结果验证结束，再把变化与缺陷带回台账和维护管理。\n**横向回看：** 回顾阀门结构、功能设备、管网调控、异常辨析和应急隔离，形成GW-02完整知识网。","anchors":[{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"中线（软密封）蝶阀","ref":"中线（软密封）蝶阀"},{"name":"电动蝶阀","ref":"电动蝶阀"},{"name":"加密闸阀","ref":"加密闸阀"},{"name":"先导式减压阀","ref":"先导式减压阀"},{"name":"复合式排气阀","ref":"复合式排气阀"},{"name":"压力表","ref":"压力表"},{"name":"地上式消火栓","ref":"地上式消火栓"},{"name":"地下式消火栓","ref":"地下式消火栓"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"}],"pitfall":"【不能凭经验补制度】不虚构审批层级、操作票模板、压力目标或维护周期；阀位到位要结合压力、流量和供水反馈验证。\n【记录要可追溯】“已处理”不算闭环，要写清现象、动作、结果、待办与交接；维护周期按企业制度，不自行设定。","remark":"企业填：按公司正式制度补充阀门台账字段、指令权限、操作票、维护周期、压力目标及异常闭环要求。","seq":111,"family":"GW-02 阀门操作与管网调度","lessonNo":8},{"id":"C112","sub":"GW-03","topic":"管网抢修工作全景、响应分级与四类抢修边界","level":"D1/L1","d":"D1","l":"L1","positioning":"本课是GW-03总纲：只讲职责、四类边界、响应分级、七步链路、三岗配置、安全底线和“信息不全时的最小安全决策”；漏损看C113，器材看C114。","framework":"1 职责与范围；2 四类边界；3 响应分级；4 七步链路；5 三岗配置；6 安全底线；7 信息不全时的最小安全决策。","lecture":"【职责与覆盖范围】\n**抢修覆盖市政主次干管、小区红线外支管、阀门井、消火栓及附属设施。**接报必问六项：位置、现象、影响户数、是否道路积水、是否第三方施工、周边管线类型；缺一项回拨确认再派工。\n**六问之外追问三句：现场是否已有人、上游阀是否已关、漏水是否清澈——已有人可对接围挡，已关阀可先核实止水点，水清是清水管、水浑可能夹带泥土有塌方风险。**\n**影响户数直接决定响应等级、关阀范围和临时供水需求，不问清就出发，到场才发现影响半个小区，增援和通知都来不及。**\n\n【四类抢修边界】\n**日常小修针对砂眼滴漏，当日闭环；应急抢修针对爆管大面积断水，第一动作止水控险，不先研究修复方案；专项大修针对老旧管段连环漏点，分批整改，不一次全面开挖；停水抢修在计划窗口作业，提前调度通知用户。**\n**判错类型等于资源全错：小修按应急调人浪费，应急按小修延误止水。**现场判据：明漏大水量、水柱高、影响户数多按应急；砂眼滴漏水量小按小修；多点渗漏管壁薄按专项；计划换阀接驳按停水。\n\n【七步链路】\n**接单派工记录时间和责任人；现场止水先于任何排查；缺陷核实至少判到管材、漏点形态、接口类型三层；方案选型结合管材、漏点、工况三项，跳选型直接施工是返工首因；施工按工艺不凭手感；验收通水按C126标准；**\n**复盘归档只沉淀工法。**七步中任何一步跳过，后面都会以返工或二次停水的方式补回来。\n\n【三岗配置】\n**指挥一人统一口令，操作按工艺，监护盯安全且不兼任操作。**三岗缺监护是有限空间和带压作业的高危配置，监护人去帮忙拧螺栓，等于没人盯异常信号。\n\n【信息不全时的最小安全决策】\n**图纸缺失、阀门位置不清、管材无法确认时，判据不是等齐信息再动手，而是先做风险最低的那件事：管材不明先按不伤害管材的保守方式止水，不直接上可能压裂薄壁管的强力抱箍；阀门位置不清先听音加查井，**\n**不盲目关阀扩大停水；管径不明带可调节范围的器材和适配辅件，不赌固定规格。**信息不全时先做不错的事，比做错再改成本低。","structure":"主链：明职责→分四类→定响应→走七步→配三岗→守底线→信息不全做最小安全决策；要点：1四类边界不混；2止水先于排查；3七步不跳选型；4监护不兼操作；5信息不全先做风险最低动作；引导：C113认漏损形态与初选。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"PE给水管","ref":"PE给水管"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"}],"pitfall":"四类不混；止水先于修复；无监护不作业；信息不全不赌规格。","remark":"","seq":112,"family":"GW-03 管网抢修与快速处置","lessonNo":1},{"id":"C113","sub":"GW-03","topic":"管网漏损形式识别与抢修方案初选","level":"D2/L2","d":"D2","l":"L2","positioning":"本课只解决“看形态→初选→定工况边界”；错用辨析归C125，器材安装归C114/C122/C123。接口漏用哈夫节的边界在本课只给结论。","framework":"1 球铁四类漏损；2 PE四类漏损；3 钢管四类漏损；4 接口三类共性；5 按形态初选；6 按工况定边界；7 初筛核四项。","lecture":"【球铁管四类漏损】\n**承口渗漏是球铁最高发形态，判据是承口周圈持续渗水、水量不大但不断线，多因胶圈老化、移位或插口插入不到位；管身破裂多外力撞击或沉降拉裂，裂纹沿轴向或环向，水迹集中在裂口附近；接口错位伴管道位移，**\n**承口与插口不同心；防腐穿孔表面小孔，内部腐蚀范围通常更大，敲击听空响可辅助判断。**现场顺序：先看承口周圈水迹，再看管身裂纹走向，最后判断是否伴随位移。\n\n【PE管四类漏损】\n**划伤深度超过壁厚10%即判为需要切除更换的损伤，不按打磨一下继续用处理——壁厚10mm的管，划伤超过1mm就不在可修补范围内；接口脱焊多因热熔假焊或冷却受扰动，外观翻边可能完好，内部融合强度不足，**\n**是暗漏重灾区；硬物刺穿漏点明确，但周边可能有隐性损伤，不能只补刺穿点。**PE现场先摸划痕深度，再看接口翻边是否对称。\n\n【钢管四类漏损】\n**腐蚀优先沿焊缝发展，焊缝锈迹和法兰缝水迹是两个高发位置；点蚀穿孔表面小孔内部坑状，敲击听空响；防腐破损加速基体腐蚀；法兰渗漏先看垫片和螺栓。**钢管现场先查焊缝和法兰。\n\n【接口三类共性】\n**承插胶圈渗漏水量不大但持续沿周圈；法兰垫片沿法兰缝滴漏、螺栓周边有水迹；螺纹密封多在小口径丝接处伴锈蚀。**三类处置完全不同：胶圈换圈复位，垫片换垫紧栓，螺纹重缠生料带，不能都当胶圈老化处理。\n\n【按形态初选】\n**砂眼小孔先评估AB胶临时或小型哈夫节；纵向裂缝用哈夫节，但两端先打磨止裂孔，否则裂缝边缘可能割伤胶条；完全断裂切除更换；接口漏换密封件复位，不用哈夫节硬抱。**形态判错，方案全错。\n\n【按工况定边界：带压四项逐一核实】\n**带压不是“看着不大就能带压”，四项要逐项到现场确认。**压力看表：确认该管段运行压力在低压范围，不凭经验估。漏量看水柱：水柱细、连续、不随时间增大，才是微漏；水柱变粗或断续喷出，按大漏处理。\n**管材看喷码和端头：薄壁、腐蚀严重的管段不带压。**器材看压力等级：哈夫节、抱箍的标称压力必须高于该管段运行压力，不拿低压器材凑高压工况。四项有一项拿不准，按停水处理，不“先带压试试看”。\n\n【初筛核四项】\n**初选后核管径、压力、管材、工况；只看形态就发料等于拿错。**","structure":"主链：分管材认漏损→分形态选工法→带压四项逐一核实→初筛核四项；要点：1球铁承口漏最高发；2PE划伤超壁厚10%即切除；3钢管腐蚀沿焊缝；4接口漏不硬抱；5带压四项拿不准就停水；引导：C114器材总纲。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"PE给水管","ref":"PE给水管"},{"name":"直缝焊接钢管","ref":"直缝焊接钢管"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"AB胶（管道修补剂）","ref":"AB胶（管道修补剂）"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"}],"pitfall":"小砂眼可能是腐蚀穿孔表象；接口漏不用哈夫节硬抱；PE划伤超10%不凑合；带压四项缺一不试。","remark":"","seq":113,"family":"GW-03 管网抢修与快速处置","lessonNo":2},{"id":"C114","sub":"GW-03","topic":"常用抢修器材族谱、通用工艺与通水前核验","level":"D2/L2","d":"D2","l":"L2","positioning":"本课只讲器材族谱、通用清理/螺栓/密封规则、通水前三查；各器材专项安装归C122/C123/C137/C138。螺栓三原则在此立规。","framework":"1 器材族谱；2 通用清理；3 螺栓三原则；4 密封件规则；5 通水前三查；6 收尾；7 边界。","lecture":"【器材族谱】\n**哈夫节管身堵漏，靠两片壳体抱箍密封，不承担接口转换；多功能法兰连接器接口转换兼防脱；PE热熔件永久连接，强度高寿命长；AB胶仅小漏点临时；胶垫平圆夹法兰间，胶圈环形塞承口槽；螺栓半丝光杆抗剪对中，**\n**全丝任意调节。**先认功能再拿件，拿错装不上。\n\n【通用清理】\n**清理不是擦一擦。**金属管表面除锈要达到St2级——露出金属本色、无可见油污、无松动锈皮；PE管用刮刀沿轴向刮平划痕，刮削长度超出划痕两端各50mm；球铁管用钢丝刷除锈后擦净。\n**清理范围超出密封件边缘2–3cm。**清理完用手摸一圈，有毛刺、有凸起、有湿气，胶垫就压不实。法兰密封面如果有径向划痕，深度超过0.2mm且穿过密封面宽度一半，清理解决不了，必须换法兰或重新加工密封面。\n**清理不彻底是哈夫节和法兰漏的首要原因。**\n\n【螺栓三原则】\n**对角交替、分2–3次、外露2–3扣。**法兰紧固现场口径：头遍五成扭矩、第二遍八成、末遍到规定值，用扭矩扳手不凭手感；哈夫节和抱箍没有扭矩扳手时，判据是胶垫溢出量一致、壳体不变形、螺栓外露2–3扣。\n**一次拧死一颗螺栓，胶垫会被挤向一侧，另一侧翘起，通水必漏。**专项判据不在本课复述：哈夫节看两侧胶圈溢出量一致（C122），连接器看周圈间隙一致（C123），法兰看补紧无效才换垫（C136）。\n\n【密封件规则】\n**平圆胶垫夹法兰、环形胶圈塞承口；EPDM怕油怕晒；形状不对必漏，拿件先看形状。**胶垫当胶圈塞承口或胶圈当胶垫夹法兰，形状不对必漏。\n\n【通水前三查】\n**外观：壳体、螺栓、密封件到位无缺件；最容易漏检的是靠近管壁的下侧螺栓和胶垫边缘，需要低头或用手摸一圈。**渗漏：先低压后升压，升压过程中出现断续冒汗即视为渗漏信号，不等成滴才算漏。\n**复位：阀门、井盖、标识恢复。**三查全过才通水，缺一不通。\n\n【收尾】\n**余料回收、井盖复位、场地恢复；临时围挡最后撤。**通水发现渗漏先泄压再处理，不带压拧螺栓。","structure":"主链：认族谱→清面→螺栓三原则→核密封→三查→收尾；要点：1功能不混用；2清理达St2、超边缘2–3cm；3法兰分遍50/80/100%；4三查漏下侧和冒汗；5工完场清；引导：C115安全底线。","anchors":[{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"AB胶（管道修补剂）","ref":"AB胶（管道修补剂）"},{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"}],"pitfall":"AB胶不是永久；螺栓一次拧死必偏；清理不彻底必漏；三查漏下侧。","remark":"","seq":114,"family":"GW-03 管网抢修与快速处置","lessonNo":3},{"id":"C115","sub":"GW-03","topic":"抢修现场安全管控与有限空间/带压底线","level":"D2/L2","d":"D2","l":"L2","positioning":"本课只讲现场安全通用底线：围挡、交底、有限空间（含分层检测与记录）、带压红线、夜间照明、异常先停；带压技巧归C130，协同归C142。","framework":"1 围挡三种场景；2 交底四要素；3 有限空间三铁律+分层检测+记录；4 带压红线；5 夜间照明与警示；6 异常先停再报；7 记录。","lecture":"【围挡】\n**先围挡再作业；道路用锥桶、警示带、警示牌，夜间加反光警示灯；小区设警示标识并预留行人通道；围挡范围覆盖作业区加安全距离，不圈太大碍交通、不圈太小失防护。**围挡不设好绝不开工，围挡挡人挡车不是摆设。\n\n【交底四要素】\n**任务内容与范围、风险点与防控、人员分工与职责、应急联络与处置；全员签字；未交底不上岗，老员工不例外；交底后让每人复述自己职责，确认听懂，不是讲过了就算。**\n\n【有限空间：三铁律+分层检测+记录】\n**先通风→再检测→后作业，顺序不反。**作业前机械通风不少于30分钟，风管延伸至空间底部，严禁纯氧通风。\n**气体检测按固定顺序：先测氧气（19.5%–23.5%VOL），再测可燃气体（＜10%LEL），最后测硫化氢、一氧化碳等有毒气体——氧气读数异常时，其他气体LEL读数本身不可靠。**\n**检测实行上、中、下分层，常规作业每15分钟记录一次，动火作业缩短至每5分钟一次。**作业中断超过30分钟，复工前重新通风、重新检测。\n**全程专人监护，监护不兼操作、不离岗；无作业票、无检测、无监护，绝不下井；异常立刻撤离，不盲目施救。**\n\n【带压红线】\n**仅限指定器材、小漏点、低压；站侧面，严禁正对漏点、法兰面；严禁带压拆承压螺栓或密封件；超边界先停水卸压。**带压作业设警戒区，非作业人员退到侧面安全距离。\n\n【夜间照明与警示：现场判据】\n**夜间作业照明不是“有灯就行”。**作业面照度要能看清螺栓螺纹、胶垫边缘和压力表刻度，看不清就加灯，不凭“大概能看见”开工。\n**警示灯或反光锥距作业区边界不少于50m，道路弯道、坡道处提前到100m；反光衣前后都要有反光条，不只是背后有。**照明和警示没到位，宁可不作业，不靠“应该没人看见”赌安全。\n\n【异常先停】\n**发现异味、涌水、塌方、压力异常：先停、撤到安全区、再上报；不冒险、不盲目靠近。**\n\n【记录】\n**交底签字表、围挡照片、异常上报时间；有限空间另附分层检测数据和15分钟记录表。**","structure":"主链：围挡→交底四要素→有限空间三铁律+分层检测+15分钟记录→带压站侧面→夜间照明看清螺纹+警示50m→异常先停；要点：1围挡先于作业；2交底签字+复述；3检测顺序氧气→可燃→有毒；4夜间照度看清螺纹、警示距≥50m；5带压站侧面；引导：C116到场前准备。","anchors":[{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"压力表","ref":"压力表"}],"pitfall":"围挡不设不开工；有限空间不分层检测=漏检；夜间看不清螺纹不开工；带压不正对漏点。","remark":"","seq":115,"family":"GW-03 管网抢修与快速处置","lessonNo":4},{"id":"C116","sub":"GW-03","topic":"抢修接单派工、到场前预判与材料工具准备技巧","level":"D3/L3","d":"D3","l":"L3","positioning":"本课只讲接单到到场前：问清信息、初判管材漏点、配主辅件、试工具、回传；闭环归C143。本课补“信息不全时带什么”。","framework":"1 接单六问；2 初判管材；3 初判漏点；4 信息不全预配；5 材料预配；6 工具预配；7 路线回传。","lecture":"【接单六问】\n**位置、现象、影响户数、是否积水、是否第三方、周边管线；缺项回拨。**影响户数决定响应等级和关阀范围，不问清就出发容易白跑。\n**六问之外追问三句：现场是否已有人、上游阀是否已关、漏水是否清澈——已有人可对接围挡，已关阀可先核实止水点，水清是清水管、水浑可能夹带泥土有塌方风险。**这三句能省掉到场后重复排查的时间。\n\n【初判管材】\n**喷码最快；无喷码看颜色端头：PE黑蓝线、PPR绿白线、衬塑外钢内塑、球铁沥青黑内水泥、钢管焊缝防腐；端头平口热熔、带盘法兰、带牙丝接。**不确定让现场拍照对卡名，不凭看起来像发料。\n\n【初判漏点】\n**明漏看水柱位置和大小；暗漏看沉降、井内水迹、压力下降；接口漏多周圈水迹；管身漏多局部裂缝。**初判决定带哈夫节、密封件还是连接器。\n\n【信息不全时的材料预配策略】\n**管材无法确认时，带可覆盖PE和球铁两种常见管径的哈夫节和适配胶垫，不带只赌一种材质的单件；管径不明时，带可调节范围的临时抱箍和辅件，不硬拿固定规格。**信息不全不是不带，而是带能覆盖不确定性的最小组合。\n\n【材料预配】\n**主件不是带一个，是按初判带两个相邻规格——初判DN100哈夫节，同时带DN80和DN100各一个，到场量了外径再定；胶垫带3片（1片装、2片备）；螺栓按每个哈夫节8套带。**\n**辅件里生料带、防锈脂、堵漏楔、临时抱箍每次必带，缺一样都可能让一次可闭环的抢修变成二次出动。**主辅件分袋标记，到场不翻找。\n\n【工具预配】\n**热熔机、割管机、扳手、压力表、围挡、照明、抽水、铁锹、听音杆；到场前逐件试运转；缺关键工具先补给；夜间带头灯反光衣。**\n\n【路线与回传】\n**预判停车、围挡点位、行人通道、材料搬运路线；到场时间、初判、是否增援、是否停水同步后台。**","structure":"主链：六问+追问三句→判管材→判漏点→信息不全带最小覆盖组合→配主辅件→试工具→回传；要点：1问清再出发；2初判带相邻两规格；3辅件每次必带；4主辅分袋；5工具试运转；引导：C117定位止水。","anchors":[{"name":"PE给水管","ref":"PE给水管"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"压力表","ref":"压力表"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"}],"pitfall":"只带主件不带辅件；不问影响户数；信息不全时赌一个规格；工具不试运转。","remark":"","seq":116,"family":"GW-03 管网抢修与快速处置","lessonNo":5},{"id":"C117","sub":"GW-03","topic":"抢修漏点定位、止水点选择与管材快速识别技巧","level":"D3/L3","d":"D3","l":"L3","positioning":"本课只讲定位、管材识别、初判止水点；正式关阀多阀协同归C128，关阀失败归C129。本课补“管材不明时先做什么”。","framework":"1 明漏定位；2 暗漏定位；3 管材识别四线索；4 管材不明保守止水；5 止水点初判；6 止水范围初判；7 标记记录。","lecture":"【明漏定位】\n**水柱最高点常靠近破口；地面塌陷范围；井内翻水位置。**先围挡再探，不盲目开挖。水柱方向可判破口朝向；大面积积水先抽排再找漏。\n\n【暗漏定位】\n**听音杆怎么听：杆尖贴管壁正上方或阀门井内管壁，耳朵贴听筒，听沙沙连续声是漏水，咚咚是水流冲击，嘶嘶是小孔喷射。**夜间22点后环境噪声低，听音最准。\n**压力下降判断：同一时段压力表每小时下降超过0.05MPa且无用水高峰解释，按暗漏排查。**井内水迹看清水还是浑水，清水多来自给水管，浑水可能来自排水或土壤渗水。\n**暗漏可能沿土壤窜水，别只盯一个点；多点异常查主管。**三点互证（听音、压力、井内水迹）比单一线索可靠。\n\n【管材识别四线索】\n**喷码→颜色标线→端头形式→内衬或焊缝；四层过完仍不确定，拍照对卡名，不凭看起来像发料。**\n\n【管材不明时的保守止水】\n**管材无法确认时，不用可能压裂薄壁管的强力抱箍或大力紧固器材；优先用临时堵漏楔、可调抱箍或降压加软性封堵控险，确认管材后再上永久器材。**不因为先止住再说把一个可修漏点变成断管。\n\n【止水点初判】\n**漏点上游最近可控阀门；最近阀关不严，向上游再找一个。**止水点不是越近越好，要可控可靠；上游阀位置查管网图加现场核对井位。\n**到阀井后先看阀杆开度指示和手轮位置：明杆阀阀杆外露长度对应开度，暗杆阀看手轮转数记录；阀井积水先抽到能看清阀体，再判断阀门状态，不凭应该关着就动手。**\n\n【止水范围初判】\n**评估关哪些阀影响多少户；优先保医院学校；具备条件开旁路；最小化在C128细讲。**\n\n【标记记录】\n**拍照、喷漆、记录桩号、管径、管材、漏点形态、初判止水点；为关阀和修复提供依据。**","structure":"主链：明漏看→暗漏听（沙沙/咚咚/嘶嘶）→认管材四线索→管材不明保守止水→查阀杆开度→初判止水点→记录；要点：1先围挡再探；2暗漏三点互证；3管材不明不上强力紧固；4止水点可控优先于近；5记录可追溯；引导：C118临时补漏。","anchors":[{"name":"PE给水管","ref":"PE给水管"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"衬塑复合管","ref":"衬塑复合管"},{"name":"直缝焊接钢管","ref":"直缝焊接钢管"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"压力表","ref":"压力表"}],"pitfall":"不盲目开挖；最近阀不控就向上游；管材不明不硬上强力抱箍；不听音只凭猜。","remark":"","seq":117,"family":"GW-03 管网抢修与快速处置","lessonNo":6},{"id":"C118","sub":"GW-03","topic":"临时止水与应急补漏：AB胶、堵漏楔、临时抱箍适用技巧","level":"D3/L3","d":"D3","l":"L3","positioning":"本课只讲三类临时补漏的适用边界与操作判据；永久修复归C125及专项。堵漏楔完整操作在此，C130只引用。","framework":"1 AB胶；2 堵漏楔；3 临时抱箍；4 表面处理；5 操作顺序；6 边界；7 记录转永久。","lecture":"【AB胶】\n**仅小砂眼、细微裂缝；打磨露基体、去油污水锈；按比例混合、分层涂敷覆盖超出漏点2–3cm、压实无气泡。**\n**AB胶配比按产品说明，混合后3–5分钟内涂完，超过适用期会发硬失效；涂敷分两层，第一层薄涂压实、第二层覆盖超出漏点边缘2–3cm；常温固化30分钟以上再升压，低于15℃固化时间延长。**\n**固化前不能通水、不能扰动。**不能补大口径长裂缝，不能代替永久。\n\n【堵漏楔判据】\n**适用于孔洞涌水，利用木材遇水膨胀；选比孔洞直径大10–20mm、长度能完全进入孔洞并外露30mm以上的木楔，缠麻丝或密封胶带增加密封；先关阀，用木锤侧向嵌入直至止漏，不用铁锤，铁锤会把木楔打裂。**\n**不能正对水柱硬塞；楔入后观察5分钟，周边无渗水再加固；仍有渗水说明楔子偏小或孔洞不规则，换大一号或改抱箍。**止漏后配合抱箍或胶泥加固，只是临时控险。\n\n【临时抱箍】\n**覆盖漏点两端足够长度；胶垫对准漏点，对角紧固；不过度拧紧压裂薄壁管；通水观察后安排永久。**\n**抱箍宽度要跨过漏点两侧的完整管壁，不能只压在破损处；临时点绝不能当永久用，止水后尽快安排永久修复，在场期间留意有无再渗。**\n\n【表面处理判据】\n**有水先堵或引流，有油去油，有锈打磨；表面处理不到位粘不牢、塞不严；PE刮平划痕再补。**\n\n【顺序与边界】\n**止水→清面→选临时→补漏→观察→标记→转永久。**临时只要求快速止水短期可靠，后续必须永久修复，不能一补了之。记录临时点位置、材料、时间、计划永久修复时间，巡检重点关注。\n**临时点的位置和用的材料要当面交代给下一班，别让接手的人不知道哪里有隐患。**","structure":"主链：止水→清面→选临时→补漏→观察→转永久；要点：1AB胶3–5分钟涂完、固化30分钟；2堵漏楔大10–20mm、木锤侧向、观察5分钟；3抱箍胶垫对准；4临时必转永久；5记录跟进；引导：C119附属设施。","anchors":[{"name":"AB胶（管道修补剂）","ref":"AB胶（管道修补剂）"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"}],"pitfall":"AB胶不是永久；堵漏楔不正对水柱；临时抱箍不替代永久。","remark":"","seq":118,"family":"GW-03 管网抢修与快速处置","lessonNo":7},{"id":"C119","sub":"GW-03","topic":"阀门井、消火栓与井室附属设施抢修技巧","level":"D3/L3","d":"D3","l":"L3","positioning":"本课只讲附属设施本体抢修；井内安全归C115，关阀失败归C129。消火栓逐个出水口试水、井盖异响判断、排气阀浮球卡住区分补可观察判据。","framework":"1 阀门井；2 消火栓；3 井盖井座；4 排气阀井；5 顺序；6 材料；7 边界。","lecture":"【阀门井】\n**先围挡开井通风；查井盖井座、井壁渗水来源、井内积水先抽；填料压盖渗漏先均匀紧压盖，不解决再换填料。**\n**填料压盖紧法：对角均匀紧压盖螺母，每次1/4圈，紧到渗漏停止即停，不一次拧死；紧完仍漏说明填料老化，关上游阀后换填料。**法兰渗漏按C136判据走。\n\n【消火栓】\n**地上式看栓体出水口阀；地下式用专用扳手开井盖；漏水三因：出水口阀关不严、栓体冻裂、接口渗漏。**消火栓冻裂判断：栓体表面有纵向裂纹、出水口法兰处渗水、开关手轮转不动，三者出现任一按冻裂处理。\n**更换前关上游阀泄压。**复位后逐个出水口试水，判据是出水顺畅、关闭后出水口无持续滴漏、栓体各接口无渗水；只试一个口不能代表其他出水口和接口密封合格，不算复位合格。\n**地下式消火栓井内积水先抽排，用专用扳手开阀，不用管钳夹阀杆。**\n\n【井盖井座：异响/翘动判断】\n**井盖不是“盖上就行”。**踩上去有晃动或异响，说明井座不平、减震胶条缺失或井盖与井座不匹配；先调平井座、补胶条，再复位井盖，不直接换盖了事。井盖翘边、盖不严，车辆碾过会弹起伤人，必须调平后再开放通行。\n**换井盖要匹配井座口径和功能字样；重车道路用重型井盖；复合井盖轻，适合人行道和绿化带，不放在重车道上。**\n\n【排气阀井：浮球卡住与正常排气的区分】\n**排气阀持续流水不止、水量稳定不断线，多为浮球卡住或密封面卡杂物；间歇性排气、排完即停，是正常排气。**\n**判断方法：关上游阀后拆检浮球，浮球能自由起落、密封面无异物为正常；浮球卡在开位或密封面有泥沙，清洗或换浮球。**复位后观察排气是否恢复正常，仍持续漏水则换阀。排气阀直立安装，不倾斜。\n\n【顺序判据】\n**围挡→通风→查本体→关上游阀→换件→复位→观察；先安全后本体；附属设施小件装错照样停水返工。**","structure":"主链：围挡→通风→查本体→关上游→换件→复位；要点：1填料每次1/4圈紧到不漏；2消火栓冻裂三判据、逐个出水口试水；3井盖异响先调平补胶条；4浮球持续流水与间歇排气区分；5先安全后本体；引导：C120表前管道。","anchors":[{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"复合井盖（给水/消防）","ref":"复合井盖（给水/消防）"},{"name":"地上式消火栓","ref":"地上式消火栓"},{"name":"地下式消火栓","ref":"地下式消火栓"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"}],"pitfall":"井盖异响先调平不直接换；消火栓只试一个口不算复位；浮球持续流水≠正常排气。","remark":"","seq":119,"family":"GW-03 管网抢修与快速处置","lessonNo":8},{"id":"C120","sub":"GW-03","topic":"小口径支管、螺纹接口与表前管道漏点抢修技巧","level":"D3/L3","d":"D3","l":"L3","positioning":"本课只讲表前管道与螺纹接口：小口径支管、丝接、活接、表前管；表组归C121，多户停水归C140。活接先查垫片补手感判据。","framework":"1 小口径支管；2 螺纹接口；3 活接漏水；4 表前管漏；5 顺序试压；6 材料；7 边界。","lecture":"【小口径支管】\n**DN15–DN50，漏点多在丝接、活接、穿墙管。**先关表前阀泄压；空间小用短扳手；穿墙管先判墙内还是墙外。\n**穿墙管漏先看墙内侧还是外侧返潮，判断不了再拆装饰面，别在墙上盲目打孔碰管；丝接拆装空间小，动手前先把两端活接松开卸力。**\n\n【螺纹接口】\n**生料带顺螺纹缠，留第一扣不缠防碎屑进表；生料带缠15–20圈，顺螺纹方向、略用力拉紧缠入牙槽，缠完用手捋一圈确认无松散。**缠太厚撑裂铜嵌件或PP-R内丝；拧紧不过度；拧紧后外露2–3扣。\n**漏了先查缠绕方向和螺纹损伤，乱牙换件不硬拧。**麻丝配厚漆多用于老镀锌管，生料带用于新件，两者不要混着缠；起始留第一扣不缠，是防止生料带被切碎后冲进水表机芯。\n\n【活接漏水判据】\n**中间螺母内平垫片老化最常见；拆开看垫片是否压扁、发硬、有缺口——压扁指厚度明显小于新垫片、失去弹性，发硬指用手捏不动、无回弹，缺口指边缘有撕裂或凹坑，三者出现任一即换。**\n**活接螺母拧紧后仍有渗汗——用纸巾贴1分钟，纸巾有湿痕即渗漏，不是等滴水才算。**不死拧丝口。拆装扶住另一端防转；垫片选同规格EPDM。\n\n【表前管漏】\n**管身裂缝切段换管；接头渗漏换接头；表前阀关不严先处理阀门或上游关阀；小口径可临时抱箍控险后换管。**小口径带压抱箍只能临时控险，不能当永久，要尽快安排停水换管。\n\n【顺序与试压】\n**关表前阀→泄压→拆旧→清螺纹→缠带→装新→慢开阀试压；先低压后正常，渗漏泄压重做。**\n\n【补芯方向】\n**外丝朝大径、内丝朝小径，反了装不上。**补芯拧好后要用生料带缠住外丝根部再上紧，防止从丝口渗漏；变径处受力矩大，扳手别加套管硬拧，铜件容易拧裂。","structure":"主链：关阀→泄压→拆换→缠带→试压；要点：1生料带15–20圈留一扣；2活接垫片压扁/发硬/缺口/纸巾渗汗；3表前管漏切换；4补芯方向；5慢开试压；引导：C121表组。","anchors":[{"name":"衬塑内外丝补芯（变径补芯）","ref":"衬塑内外丝补芯（变径补芯）"},{"name":"衬塑活接头","ref":"衬塑活接头"},{"name":"PE内丝直接","ref":"PE内丝直接"},{"name":"PE外丝直接","ref":"PE外丝直接"},{"name":"生料带（聚四氟乙烯密封带）","ref":"生料带（聚四氟乙烯密封带）"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"}],"pitfall":"生料带方向反会漏；活接漏水先换垫片；补芯方向反装不上。","remark":"","seq":120,"family":"GW-03 管网抢修与快速处置","lessonNo":9},{"id":"C121","sub":"GW-03","topic":"小区入户水表组、表前阀与表箱表井抢修技巧","level":"D3/L3","d":"D3","l":"L3","positioning":"本课只讲表组组件：表前阀、水表、表接头、活接、表箱表井；立管分户支管多户停水归C140。表前阀关不严补可观察判据。","framework":"1 表组组成；2 表前阀；3 水表；4 表箱表井；5 换表顺序；6 狭窄空间；7 边界C140。","lecture":"【表组组成】\n**表前阀、水表、表后阀、活接、过滤器；表前阀控单户，表后阀控户内，过滤器保护水表。**多表并排时先认清户号再拆装，防止装错户引起水费纠纷。\n\n【表前阀关不严判据】\n**关到底后下游仍能听到持续过水声，或表后放水时水表仍走字，即关不严；辅助判断：关阀后听阀体有无嘶嘶过水声、摸阀后管壁温度是否与阀前一致（有水流过时温差小）。**\n**表前阀是闸阀时，关到底后回半圈，防止阀杆顶死；是球阀时手柄与管道垂直即关。**先多关几次，不解决找上游阀。阀杆断或手轮坏换阀或上游关阀；加密阀用专用工具；压盖渗漏可紧压盖，不解决换阀。\n\n【水表】\n**爆裂冻裂玻璃破先关表前阀泄压；换表看方向箭头、铅封、接口螺纹；表接头渗漏换垫片或接头；水表不能倒装；换前拍照读数和表号。**\n**换表读数要新旧表核对，旧表铅封不要私自破坏；拆下旧表后管口用堵头封住，防杂物掉进管内。**\n\n【表箱表井】\n**积水先抽；狭窄用短扳手，一手扶件防转；多表并排先标记目标表；门锁复位；井内防坠物。**表井积水先抽干再作业，井内按有限空间对待（见C115），别直接下井。\n\n【换表顺序】\n**关表前阀→泄压→拆接头→取表→装新表加垫→对角轻紧→慢开阀试压→查接头；拆表前先关表后阀，防止户内余水倒流；拆下的旧表接口用堵头封住，防杂物进管；新表装前检查表体箭头方向、铅封完整、接口螺纹无损伤；**\n**装表垫片用同规格EPDM，不用再生胶垫。**换完冲洗排气，铅封复位记录。\n\n【狭窄空间技巧】\n**短柄扳手加万向接头，扶正防转，先拆下游端，垫片不掉井，工具系绳。**换表前先关表后阀、打开下游龙头泄压放空，带压拆接头会喷水；拆下的旧螺栓垫片随手装袋，别掉进井里。","structure":"主链：认组件→关表前阀→泄压→拆换→试压→复位；要点：1表前阀关不严看过水声/水表走字/摸温差；2换表先关表后阀、看箭头铅封；3狭窄防转；4先拍照读数；5慢开阀；引导：C122哈夫节。","anchors":[{"name":"旋翼式机械水表（湿式/干式/液封）","ref":"旋翼式机械水表（湿式/干式/液封）"},{"name":"黄铜内螺纹浮动球阀","ref":"黄铜内螺纹浮动球阀"},{"name":"衬塑活接头","ref":"衬塑活接头"},{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"不锈钢户表控制箱","ref":"不锈钢户表控制箱"}],"pitfall":"水表不倒装；表前阀关不严看信号不看感觉；狭窄空间防转。","remark":"","seq":121,"family":"GW-03 管网抢修与快速处置","lessonNo":10},{"id":"C122","sub":"GW-03","topic":"哈夫节选型、胶垫防偏与对角紧固技巧","level":"D3/L3","d":"D3","l":"L3","positioning":"本课只讲哈夫节管身堵漏；接口转换归C123。通用螺栓三原则见C114，本课只给哈夫节特有判据，并补胶垫挤出/翻卷必须停手重装。","framework":"1 适用；2 选型判据；3 表面清理与止裂；4 胶垫定位与偏位判据；5 失败信号；6 对角分次；7 核验。","lecture":"【适用与选型判据】\n**哈夫节只用于管身砂眼、纵向裂缝、局部破损；接口漏不用它硬抱。**选型：量外径、覆盖漏点两端各5–10cm、压力匹配。\n**安装前试扣：左右晃动间隙大于2mm即规格过松，换小一档；扣上需用力才能推进即管径偏大或哈夫节内径偏小，强行紧固会把胶圈挤出密封槽。**不以差不多凑规格。\n**哈夫节按实测管外径选，DN是公称直径不等于外径，量完外径对照产品表选，别按DN直接拿件。**\n\n【表面清理与止裂】\n**金属露基体、PE刮平、球铁除锈，清理范围超出胶垫边缘至少50mm；纵向裂缝先用角磨机在裂缝两端打磨出止裂孔再装哈夫节，否则裂缝边缘可能割伤胶条。**\n**表面除锈达到St2级或以上，胶垫才能填满微观凹坑形成密封。**\n\n【胶垫定位与偏位判据】\n**胶垫对准漏点、平整无扭曲；胶垫要顺着水流冲出的方向卡紧，不是随便放上去。**螺栓先全部手动预紧到胶圈刚接触管壁，再对角逐步加力；最终目测两侧胶圈溢出量一致，不一致即为偏位，泄压重装。\n**紧固顺序可按星型对角（如1-6-2-5-3-4），第一轮预紧至约50%扭矩，第二轮至80%，末轮到位。**\n\n【失败信号：胶垫挤出或翻卷】\n**紧固过程中胶垫从壳体边缘被挤出、翻卷，或胶垫在密封槽内发生位移，立即停手——不是继续拧紧，而是泄压、重新定位胶垫，必要时用粘接剂将胶垫固定在密封槽内再装。**\n**带压安装时这一信号尤其常见，继续拧只会把胶垫彻底挤出。**\n\n【核验】\n**先低压后升压，周圈无渗水；渗漏先泄压查胶垫；完成补防锈脂记录。**紧固后看两侧胶垫溢出量是否一致、壳体有无翘曲；试压按设计和现场规定缓慢升压稳压，不凭看着不漏就签字。","structure":"主链：试扣判过松/过紧→清面+止裂→胶垫顺水流方向→溢出量判偏位→胶垫挤出/翻卷=停手重装→星型对角分次→先低压核验；要点：1晃动>2mm换规格；2纵向裂缝先打止裂孔；3溢出量不一致=偏位；4胶垫挤出/翻卷=泄压重装不是继续紧；5薄壁不过度紧；引导：C123连接器。","anchors":[{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"}],"pitfall":"间隙>2mm不强行紧；纵向裂缝不打止裂孔割胶条；胶垫挤出/翻卷不继续拧；溢出量不一致即偏位。","remark":"","seq":122,"family":"GW-03 管网抢修与快速处置","lessonNo":11},{"id":"C123","sub":"GW-03","topic":"多功能法兰连接器胶圈入槽、锁紧环均匀受力与防脱技巧","level":"D3/L3","d":"D3","l":"L3","positioning":"本课只讲连接器接口转换与防脱；管身堵漏归C122。通用螺栓三原则见C114，本课只给连接器独有判据。","framework":"1 适用｜接口转换+异材；2 选型核三项；3 承口清理；4 胶圈入槽+尺检；5 插入深度划标记；6 锁紧环周圈间隙一致；7 防脱复核+试压。","lecture":"【适用与边界】\n**多功能法兰连接器承担密封和防脱，用于承插端与法兰端转换、异材转换，不是管身堵漏件。**接口漏优先考虑连接器或换密封件，不用哈夫节硬抱。\n**连接器选型核三项：管径匹配、压力等级匹配、端头型式匹配（承插端还是法兰端）；三项缺一装不上或密封不住。**\n\n【承口清理】\n**清理承口端毛刺、锈蚀、污垢，胶圈接触面要光滑。**毛刺不清会划伤胶圈，锈蚀不清胶圈压不实；清理范围覆盖胶圈行程全长，不只清理看得见的一段。清理完用手摸一圈，有毛刺、有凸起、有湿气，胶圈就压不实。\n\n【胶圈入槽与尺检】\n**胶圈准确放入密封槽，涂专用碱性润滑剂或肥皂水，不用油脂类——油脂会使EPDM胶圈膨胀老化。**入槽后用手捋一圈确认不扭曲，再用金属直尺沿承口一周检测胶圈深度；深度不一致说明胶圈脱位，必须重装。\n**深度一致的判据是同一把直尺在同一周圈测点读数无明显差异，不是“看着差不多”。**\n\n【插入深度划标记】\n**插口按承口深度划出插入深度标记，插入至标记处，不凭“感觉到底”。**插不到位密封长度不够，插过深可能顶住承口底部；插入前涂润滑剂，插入后确认标记线刚好在连接器端面位置。\n\n【锁紧环均匀紧固】\n**锁紧环螺栓逐步均匀紧固，周圈间隙一致；禁止单边紧——单边紧会把胶圈挤偏，一侧压死一侧留缝。**紧固按对角分2–3次，外露丝扣2–3扣（通用三原则见C114）。\n**紧固过程中观察锁紧环与管壁的间隙，间隙均匀说明受力均匀，间隙一侧大一侧小说明胶圈或锁紧环偏位。**\n\n【防脱复核与试压】\n**复核轴向防脱结构是否到位：防脱卡环、限位螺栓、防脱凸台三项逐一确认，防脱没到位，通水压力波动可能脱开。**复核后按规定压力试压，观察周圈无渗漏；先低压后升压，渗漏先泄压查胶圈，不继续带压紧螺栓。","structure":"主链：清承口→胶圈入槽+尺检→划标记插到→锁紧环周圈均匀→防脱复核→试压；要点：1连接器管接口转换不堵漏；2胶圈尺检深度一致；3划标记不凭感觉；4锁紧环周圈间隙一致；5防脱必查；引导：C124冬季冻胀。","anchors":[{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"PE给水管","ref":"PE给水管"}],"pitfall":"胶圈深度不一致即脱位；单边紧会偏位；不凭“感觉到底”；防脱没到位会脱开。","remark":"","seq":123,"family":"GW-03 管网抢修与快速处置","lessonNo":12},{"id":"C124","sub":"GW-03","topic":"冬季冻胀爆管温水解冻与防二次冻裂技巧","level":"D3/L3","d":"D3","l":"L3","positioning":"本课只讲冻胀故障：温水解冻、冻裂修复、防复冻；通用复水归C141。","framework":"1 冻胀表现；2 先关阀；3 解冻判据｜水温≤60℃、从接头开始；4 严禁｜明火/硬拧/敲击；5 修复；6 防复冻；7 分步复供。","lecture":"【冻胀表现】\n**管材纵向裂缝、接口崩开、水表玻璃破表壳裂、阀门冻住手轮不动。**先关阀止水防扩大。判断冻裂位置看渗水点：裂缝多在管身纵向，接口崩开多在承插或丝接处，水表冻损看表玻璃和表壳。\n**冻住阀门手轮转不动，不要硬拧，先解冻阀杆再操作。**水结冰体积膨胀约9%，所以冻裂多是纵向撑裂而不是圆孔，看到管身纵向长裂缝基本可判是冻胀。\n\n【解冻判据】\n**用温水缓慢浇淋冻住部位，水温不高于60℃；从接头开始浇淋，不从管身中间开始。**严禁明火烤、严禁浇烫管身本体、严禁浇水加速冷却（尤其PE/PPR热熔件）。\n**解冻后用温湿布包裹；解冻后检查损伤范围：管身有无裂缝、接口有无崩开、水表有无冻损。**水温不烫手是操作手感判据，不是“越热越快”。\n\n【严禁动作】\n**冻住阀门先解冻阀杆再操作；硬拧断阀杆是冻胀抢修高频二次损坏；不敲击管件，敲击会裂管；衬塑管冻裂切段换，不焊接。**\n\n【修复】\n**冻裂管段切换；崩开接口换胶圈或密封件；冻损水表换表；修复后做好保温。**冻裂切管时要把结冰段整体切掉，不能只补裂缝——管内残余冰体化开后会在别处再撑裂；切下的碎冰别丢进井里，防止堵塞。\n\n【防复冻】\n**暴露管加保温棉或伴热带；长期不用排空；表箱填保温材料；寒潮前排查易冻点位。**保温不是“包一层就行”，保温棉要包严接口和阀门，伴热带要通电测试。\n**修复后保温没跟上，寒潮再来同一位置必冻；保温棉接头要搭接、户外外缠防水层，长期空置管段寒潮前排空。**\n\n【分步复供】\n**分步升压，先低压观察；二次渗漏立即停；同步排查周边易冻点；通知用户检查户内。**复供不能一步满压，冻胀管段刚修复，水锤可能造成二次冻裂。复供后让用户把龙头开成细线流，防止末端死水再冻。","structure":"主链：关阀→≤60℃温水解冻→查损→修复→保温→分步复供；要点：1不高于60℃；2不明火不硬拧不敲击；3从接头开始；4修后保温包严接口；5分步升压；引导：C125选型辨析。","anchors":[{"name":"PE给水管","ref":"PE给水管"},{"name":"PPR给水管","ref":"PPR给水管"},{"name":"旋翼式机械水表（湿式/干式/液封）","ref":"旋翼式机械水表（湿式/干式/液封）"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"黄铜内螺纹浮动球阀","ref":"黄铜内螺纹浮动球阀"}],"pitfall":"冻住不明火烤；硬拧断阀杆；修完不保温必复冻；复供不一步满压。","remark":"","seq":124,"family":"GW-03 管网抢修与快速处置","lessonNo":13},{"id":"C125","sub":"GW-03","topic":"抢修材料适配与选型错用辨析","level":"D3/L3","d":"D3","l":"L3","positioning":"本课只讲选型错用后果与边界；初选归C113，接口漏边界C113已给结论。PE热熔判据在此只给选型级判据，完整验收归C137。","framework":"1 管材适配；2 漏点适配；3 带压/停水边界；4 临时/永久标准；5 器材功能不替代；6 PE修复方式边界；7 三类错用。","lecture":"【管材适配】\n**球铁管适配哈夫节、承插胶圈、多功能法兰连接器；PE管适配热熔件、电熔件、PE法兰头；钢管适配焊接修复、法兰修补、哈夫节。**球铁哈夫节套PE管上装不上；钢管法兰件不用于PE；承插胶圈不能处理钢管接口。\n**选型前先认管材，不凭“都是铁件”“都是塑料件”混用。**现场先认管材再选器材，管材认错后面全错——认不出就看喷码和端头形式。\n\n【漏点适配】\n**砂眼用AB胶临时或小哈夫节；纵向裂缝用哈夫节，但两端先打止裂孔；完全断裂切除更换；接口漏换密封件复位。**接口漏当管身漏用哈夫节硬抱，封不住还伤接口；断裂用胶水补必返工。\n\n【带压/停水边界】\n**可带压仅限小砂眼、微漏、低压、指定器材四项同时满足；大裂缝、断裂、接口失效、高压、腐蚀严重必须停水。**带压是应急手段，不是常规方案；为少停水强行带压大故障，风险远高于停水本身。\n\n【临时/永久标准】\n**临时修复要求快速止水、短期可靠，后续必须永久修复；永久修复满足设计压力和寿命，按标准验收。**临时不替代永久，AB胶、临时抱箍都是临时。\n\n【器材功能不替代】\n**哈夫节管身堵漏，连接器接口转换兼防脱，功能不同不替代。**用哈夫节处理接口漏越抱越漏，用连接器处理管身漏装不上。\n\n【PE修复方式边界】\n**热熔强度高寿命长，永久首选；机械抢修快可应急；胶水仅极小砂眼临时。**胶水补大裂缝必返工，所有故障都切管重熔也不经济。\n\n【三类错用】\n**大材小用浪费成本占空间；小材大用封不住还扩故障；材质错配装不上留隐患。**选型前核管材、漏点、工况、器材功能四项，不凭经验“差不多”。\n**到场先把管材、漏点、工况、器材功能逐项核一遍再动手；宁可多带一两种规格，也别拿不匹配的件硬凑。**","structure":"主链：管材适配→漏点适配→工况边界→临时永久→器材功能→PE方式→避三类错；要点：1接口漏不硬抱；2带压不替代停水；3临时必转永久；4哈夫节不替代连接器；5核四项；引导：C126验收返工。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"PE给水管","ref":"PE给水管"},{"name":"直缝焊接钢管","ref":"直缝焊接钢管"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"AB胶（管道修补剂）","ref":"AB胶（管道修补剂）"}],"pitfall":"接口漏不硬抱；带压不替代停水；材质不混用；临时不替代永久。","remark":"","seq":125,"family":"GW-03 管网抢修与快速处置","lessonNo":14},{"id":"C126","sub":"GW-03","topic":"抢修质量验收、隐性缺陷与返工辨析","level":"D3/L3","d":"D3","l":"L3","positioning":"本课只讲验收分级、渗漏等级、隐性缺陷、短期返工成因、通水验收边界；闭环记录归C143。","framework":"1 验收三档；2 渗漏四级；3 隐性缺陷；4 短期返工四因；5 施工vs材料；6 通水验收三类；7 三误区。","lecture":"【验收三档】\n**合格：无渗漏、无变形、尺寸到位，满足长期运行；让步接收：轻微瑕疵不影响主体，经批准短期运行、后续整改；不合格：渗漏、强度不足、尺寸超标，必须返工。**三档有依据，不凭感觉定。\n\n【渗漏四级】\n**渗水表面潮湿；滴漏间断滴水；线漏持续线状；喷漏压力喷出。**渗水可观察，滴漏要评估，线漏和喷漏必须整改。升压过程中出现断续“冒汗”按滴漏前状态评估，不等成滴才算漏。\n\n【隐性缺陷】\n**热熔翻边好看内部可能假焊；哈夫节外表紧内部胶垫偏位；接口胶圈可能扭曲。**隐性缺陷当时不漏、后期暴露；验收必须结合工艺记录和压力测试，外观好不等于内部好。\n**验收把试压值和稳压时间记下来，日后复漏时能对得上。**\n\n【短期返工四因】\n**密封件未到位，压力波动偏位；粘结类受水压温度失效；应力未释放变形；隐性缺陷发展。**复漏先找根源，先泄压拆查密封件，不简单再紧螺栓。找根因再修，不重复返工。\n\n【施工vs材料】\n**施工原因局部渗漏、安装痕迹明显；材料原因均匀渗漏、多处出现、材质异常。**先查施工再查材料，分清整改才精准。\n\n【通水验收三类】\n**常压通水用于日常小修低压；保压试验用于主干管、大口径、重要节点；带负荷运行用于重点区域、大修后。**常压不替代保压；保压时长按标准，不凭“看着没漏”签字。\n**保压试验用试压泵缓慢升压，稳压时长和允许压降按现行规范执行，不凭看着不漏就签字；隐蔽工程必须在回填前验完并记录，回填后再漏要重新开挖。**\n\n【三误区】\n**只看不压、只看外观不查接口、通水即合格。**三坑是返工率高的主因，验收要量化。回填前一定要再走一遍接口、螺栓、胶垫，把该紧的紧到位——土一盖回去就看不到了，等渗水冒到路面再挖，代价翻倍。","structure":"主链：三档→四级渗漏→隐性缺陷→四因→施工/材料→验收边界→避三误区；要点：1冒汗按早期渗漏评估；2外观不等于内部；3复漏先泄压拆查不紧螺栓；4常压不替代保压；5通水不等于验收；引导：C127开挖支护。","anchors":[{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"压力表","ref":"压力表"}],"pitfall":"通水不等于验收；“冒汗”不是没事；复漏不简单紧螺栓；外观好不查接口=漏。","remark":"","seq":126,"family":"GW-03 管网抢修与快速处置","lessonNo":15},{"id":"C127","sub":"GW-03","topic":"抢修开挖、支护与降排水技巧","level":"D3/L3","d":"D3","l":"L3","positioning":"本课只讲通用开挖支护降排水：探查、探沟、支护、降排水、管周开挖、回填；汛期边坡归C135。","framework":"1 开挖前｜管线探查+围挡；2 人工探沟｜见管即停；3 放坡支护｜坑边1m不堆土；4 降排水｜集水坑+水泵；5 管周30cm人工；6 回填分层细土；7 恢复。","lecture":"【开挖前】\n**探查给水、燃气、电力、通信管线位置；设围挡交通导改；机械开挖前人工探沟，见管即停；不凭图直接挖。**管线走向不清时先物探或人工探，不用机械试着挖。\n\n【人工探沟】\n**靠近管线用人工；探沟深度超过管顶；确认管位走向再机械；探到管线做标记。**探沟不是挖个坑看看，是确认管线位置、埋深、走向。探沟要沿管线走向挖，见到管顶和两侧肩部才算探清，只挖到一个点不能确认走向。\n\n【放坡支护】\n**按土质和深度放坡；深坑或松土用支护板加撑木；坑边1m内不堆土；支护不到位会塌方；每日开工前查支护。**坑边不堆土不只是怕滑下去，堆土增加侧压，支护再好也可能塌。\n**边坡坡度按土质和深度定（砂土缓、黏土陡），深坑必须支护，不套固定值；雨后土体含水高更易塌，复工前重查边坡。**\n\n【降排水】\n**地下水或涌水设集水坑加水泵抽排；集水坑设在坑角、离管壁至少50cm，抽水时观察坑壁有无渗水带砂——带砂说明边坡在流失，先支护再继续抽。**抽水排入排水设施不漫流；边坡渗水先支护再抽；备用水泵。\n**水排不出去就开挖，坑底泡水，边坡先垮。**\n\n【管周开挖】\n**管周30cm人工清挖；不伤防腐层和内衬；暴露管段临时支撑；球铁承口不悬空；PE不硬撬。**管周清挖到管底以下至少10cm，给回填留出垫层空间；管底悬空回填不实，通水后管道下沉会拉脱接口。\n**管周用机械挖是省事，铲齿碰到管身，防腐破、管壁裂，修漏变成换管。**\n\n【回填与恢复】\n**管周细土或砂分层夯实，不用石块直接砸管；回填到设计标高；井盖标识路面恢复；余土清运。**回填不实，路面沉陷，下次还得来。回填密实度可用环刀法或灌砂法抽检（按设计要求），路面按原结构层恢复，别用素土直接盖。","structure":"主链：探查→围挡→探沟→支护→降排水（集水坑离管壁50cm、看带砂）→管周30cm人工（挖到管底以下10cm）→回填恢复；要点：1见管即停；2坑边不堆土；3管周30cm人工；4管底留10cm垫层；5细土分层回填；引导：C128关阀止水。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"PE给水管","ref":"PE给水管"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"}],"pitfall":"不凭图机械挖；坑边不堆土；管周不伤防腐；管底不悬空回填。","remark":"本轮补入集水坑位置和管底垫层判据","seq":127,"family":"GW-03 管网抢修与快速处置","lessonNo":16},{"id":"C128","sub":"GW-03","topic":"关阀止水、多阀协同与止水范围最小化技巧","level":"D4/L4","d":"D4","l":"L4","positioning":"本课只讲关阀方案与多阀协同；关阀失败归C129。两阶段关阀逻辑在此立规，C132只引用。","framework":"1 阀门定位；2 关阀顺序｜先近后远、先支后干；3 两阶段关阀｜折点+暂停+看压力；4 多阀协同｜统一指挥；5 止水范围最小化；6 压力监测；7 边界C129。","lecture":"【阀门定位】\n**按管网图定漏点上下游控制阀；现场核对阀井位置和状态；优先可控可靠阀；井内积水先抽排；阀位不清查竣工图。**阀门定位不是“找最近的井”，是找能止住水、又能少影响用户的阀。\n\n【关阀顺序】\n**先近后远、先支后干；先关最近上游阀，不够再关下游或支路；不乱关扩大停水；关前通知调度。**先关支路再关干管，能缩小影响范围；反过来先关干管，整片停水。\n**关阀后要防他人误开让抢修点突然来水，可留标记并交代现场人员别动阀。**关阀时人站阀杆侧面、不要正对阀盖，老阀井密闭要先通风（见C115）；关完记下阀号、关了几圈，复水时按原样开回，别多开也别少开。\n\n【两阶段关阀】\n**大口径采用先快后慢两阶段：先关至折点开度，暂停观察压力，剩余开度缓慢关完。**折点开度按管网条件确定，文献案例有15%和30%，不套统一值。\n**现场判据：压力表指针稳定、管道无明显振动和水锤声；不匀速快关到底。**匀速快关到底水锤风险最高，两阶段的核心价值在“折点暂停”。\n\n【多阀协同】\n**统一指挥、指令出口一致、同步动作、关键节点回报。**多阀各自为战，压力骤变，二次爆管。\n\n【止水范围最小化】\n**能止水前提下少关阀；评估影响户数；保医院学校；具备条件开旁路。**止水范围不是越大越安全，越大影响越大。确需扩大停水先通知调度和用户再关阀，关错阀扩大停水比漏点本身更容易引发投诉。\n\n【压力监测】\n**关阀全程看压力；异常暂停；通水分步升压。**压力骤降可能二次爆管，压力骤升可能水锤，两个方向都要盯。关阀后要到漏点现场确认止水（听水声消失、看水迹停、摸管壁），不能只看手轮到位就算止住。","structure":"主链：定位阀→先近后远→折点暂停→慢关剩余→多阀同步→最小化→监压；要点：1先近后远；2折点开度按管网定；3折点暂停是防水锤关键；4保重点；5多阀统一；引导：C129关阀失败。","anchors":[{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"中线（软密封）蝶阀","ref":"中线（软密封）蝶阀"},{"name":"压力表","ref":"压力表"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"}],"pitfall":"匀速快关出水锤；折点开度不套固定值；折点暂停不跳过；多阀不各自为战。","remark":"","seq":128,"family":"GW-03 管网抢修与快速处置","lessonNo":17},{"id":"C129","sub":"GW-03","topic":"阀门关不严、阀杆断与关阀失败应对技巧","level":"D4/L4","d":"D4","l":"L4","positioning":"本课只讲关阀失败应对：关不严、阀杆断、手轮坏、加密阀、逐级找上游、临时控险；表前阀场景归C121。","framework":"1 关不严｜杂物卡座/胶圈磨损；2 空转=阀杆断/脱开；3 发死=填料过紧/阀杆弯曲；4 手轮坏/加密阀；5 逐级找上游；6 临时控险；7 记录。","lecture":"【关不严】\n**先反复慢关几次；杂物卡阀座可尝试开大再关；胶圈磨损关不严需换阀。**关不严影响止水时立即向上游找可控阀，不反复折腾同一只阀。闸阀关不严多是闸板底部卡杂物或密封面磨损，球阀多是密封圈老化，处理方向不同。\n\n【两种失败信号：空转vs发死】\n**空转：手轮转动但阀杆不跟随，通常为阀杆断、阀杆与闸板连接脱开或暗杆阀阀杆断裂。**出现空转，不再反复试关，直接判该阀不可用，转上游阀。\n**发死：手轮阻力突然异常增大、转不动，常见原因为填料压盖过紧、阀杆弯曲、闸板与阀座间结垢卡涩。**\n**出现发死，不靠加力杆征服；填料过紧可逐步松开填料压盖螺栓，每次调整1/4圈，直至力矩正常且无泄漏；怀疑阀杆弯曲，用百分表检测直线度，偏差超0.1mm/m应校直或更换。**\n\n【力矩预防】\n**新阀门填料不要压太紧，以不漏为度；每周全行程操作一次防卡涩；力矩较初始状态上升20%即应检查。**定期操作比事后加力杆省事。\n**长期不动的阀最易锈死；抢修时优先选动作灵活、状态明确的阀，别跟一只发死的阀较劲，误了止水时机。**\n\n【逐级找上游】\n**最近阀不可控时逐级向上游找；核对管网图和竣工图；上游阀也可能关不严，继续找到可控止水点；记录每级阀的状态。**找上游不是“随便找个井”，按图按桩号找可控阀。\n**找上游阀时记录每级阀的位置、编号和开关状态，复水后按原状态恢复，别把原本常开的阀关了忘开。**\n\n【临时控险】\n**漏点扩大先用抱箍、堵漏楔临时控险（判据见C118）；设围挡；请求增援；不因关阀失败让漏点失控。**\n\n【记录】\n**标记关不严阀位置、现象、影响，为后续更换提供依据。**","structure":"主链：试关→判空转/发死→空转转上游、发死不硬扳→逐级找上游→临时控险→记录；要点：1空转=阀杆断/脱开，不反复试关；2发死≠空转，不硬扳不加力杆；3填料过紧松1/4圈逐步调；4逐级找上游；5临时控险后记录；引导：C130带压边界。","anchors":[{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"黄铜内螺纹浮动球阀","ref":"黄铜内螺纹浮动球阀"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"压力表","ref":"压力表"}],"pitfall":"空转和发死是两种病，处置不同；发死不硬扳；空转不反复试关。","remark":"","seq":129,"family":"GW-03 管网抢修与快速处置","lessonNo":18},{"id":"C130","sub":"GW-03","topic":"带压/停水抢修边界判别与带压堵漏适用技巧","level":"D4/L4","d":"D4","l":"L4","positioning":"本课只讲带压与停水的边界和带压适用技巧；安全底线归C115，选型错用归C125。堵漏楔操作引用C118。","framework":"1 可带压四条件；2 必须停水条件；3 带压器材选用；4 站位｜侧面不正对；5 防护｜警戒/泄压预案；6 边界判断；7 超界转停水。","lecture":"【可带压四条件】\n**同时满足：漏点为小砂眼或微渗漏、漏量不随时间快速增大、管段处于低压工况、使用指定带压器材。**四项缺一，不按带压处理。压力看表确认，漏量看水柱是否持续增大，管材看喷码和腐蚀状况，器材看压力等级。\n\n【必须停水条件】\n**大裂缝、断裂、接口失效、高压管段、腐蚀严重管段，出现任一项必须停水卸压。**带压是应急手段，不是常规方案；为少停水强行带压大故障，风险远高于停水本身。\n\n【带压器材选用】\n**哈夫节用于管身小漏点（判据见C122）；临时抱箍用于控险；堵漏楔用于孔洞涌水，操作判据见C118，带压场景仍须先确认可控或关阀后再操作。**器材压力等级必须匹配工况，不“拿大的凑”。\n**带压器材用前先核压力等级铭牌、看胶垫有没有老化开裂，超期的密封件不带到现场；堵漏楔、抱箍都要留够余量，别拿刚好卡死的规格。**\n\n【站位与防护】\n**带压作业站侧面，严禁正对漏点、法兰面；设警戒区，非作业人员退到侧面安全距离；备泄压措施；有异常立即撤离；严禁带压拆承压螺栓或密封件。**正对漏点操作，介质喷出伤人，与压力高低无关。\n**带压作业划警戒区、设专人监护、备好泄压通道，严禁两人同时在同一漏点正前方作业。**\n\n【边界拿不准】\n**压力、漏量、管材腐蚀状况任一拿不准，按停水处理。**安全优先不是口号，是“拿不准就停”。带压补漏的胶垫可能被水压冲出，一旦渗漏扩大或胶垫位移立即停手转停水，不要反复加拧。\n\n【转停水】\n**超边界立即停水卸压再处置；停水后按常规修复流程走，不在带压状态下再试一次。**夜间、雨天、空间狭窄时把带压条件判得更严——环境越差越倾向停水，不拿人员和用户安全赌时间。","structure":"主链：四项判可带压→任一项触发停水→选匹配器材→侧站→拿不准就停；要点：1四项全满足才带压；2大漏高压必停水；3站侧面不拆承压件；4拿不准按停水；引导：C131复杂工况总纲。","anchors":[{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"压力表","ref":"压力表"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"PE给水管","ref":"PE给水管"}],"pitfall":"带压不正对漏点；不拆承压件；拿不准就停水。","remark":"","seq":130,"family":"GW-03 管网抢修与快速处置","lessonNo":19},{"id":"C131","sub":"GW-03","topic":"复杂工况抢修总纲与处置顺序","level":"D4/L4","d":"D4","l":"L4","positioning":"本课只讲复杂工况分类与通用处置顺序：大口径、老旧、第三方、冻胀、汛期；专项归C132–C135。","framework":"1 五类复杂工况；2 通用顺序｜止水控险→排查核实→修复→分步复水→记录；3 资源统筹｜先报增援；4 协同｜调度/水质/交通；5 次生风险；6 分步复水；7 边界。","lecture":"【五类与通用顺序】\n**大口径爆管、老旧连环漏、第三方破坏、冻胀、汛期冲毁。**通用顺序固定：止水控险→排查核实→修复→分步复水→记录。先修后止水会扩大影响范围，顺序不能反。\n**复杂工况最忌边查边修、边修边改方案，先花几分钟把漏点数、影响户数、管材和风险扫一遍，定了方案再动手，跳过这步十有八九要返工。**\n\n【资源统筹判据】\n**复杂工况人料机需求超出单班组能力时，先报增援再动手，不边干边等。**判断标准：涉及两个以上作业面、需要同时关多个阀、需要水质或交通配合，满足任一项就先报增援。\n**材料按主件加辅件配（见C116）；关键机具试运转；现场指定一人统一指挥。**开工前把人员、主辅件、机具清点一遍，缺一样先补齐——复杂工况最怕干到一半发现少件，人留在现场干等；排不开就先报增援，别硬扛。\n\n【协同】\n**调度控阀、水质冲洗检测、交通导改同步启动；关键节点（到场、止水、修复完成、开始复水）定时回传，信息不同步会导致误操作。**\n**联络人和对讲频道开工前明确，关键节点（到场、止水、修复、复水）逐一回报，谁负责哪一环当场点名。**\n\n【次生风险】\n**复杂工况常伴塌方、积水、交通、次生爆管；先设围挡警戒、边坡先支护、不站危险区；次生风险未控不进入修复。**修复不是第一优先，控险才是。\n**到场先设围挡警戒再控险，人员站位避开边坡、冲坑、井口和带电体；次生风险没控住前不进核心作业区。**\n\n【分步复水】\n**先低压、再逐步升压，监测压力和浊度；异常暂停；不一步到位。**复杂工况修复点可能不止一处，一步满压会掩盖未发现的渗漏。\n\n【边界】\n**各专项判据见C132–C135，本课只给总纲和顺序。**","structure":"主链：分类→先报增援→止水→排查→修复→分步复水→记录；要点：1止水先于修复；2先报增援判断标准；3统一指挥；4次生风险先控；5分步复水；引导：C132大口径。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"PE给水管","ref":"PE给水管"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"压力表","ref":"压力表"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"}],"pitfall":"不先修后止水；不边干边等增援；不一步复水；次生风险未控不修复。","remark":"","seq":131,"family":"GW-03 管网抢修与快速处置","lessonNo":20},{"id":"C132","sub":"GW-03","topic":"大口径主干管爆管止水、分段复水与水锤防控技巧","level":"D4/L4","d":"D4","l":"L4","positioning":"本课只讲大口径爆管：止水范围、多阀协同、分段排查、分步复水、水锤防控；通用复水归C141，两阶段关阀逻辑引用C128。","framework":"1 定位与围挡；2 上下游阀控制；3 两阶段关阀（引用C128）；4 止水范围最小化；5 分段排查；6 修复与支护；7 分步复水+排气。","lecture":"【定位与围挡】\n**大口径爆管水柱大、冲坑深；先围挡警戒，人不站冲坑边；按管网图定位，不凭水柱方向猜。**冲坑边土壤被掏空，站人可能塌陷。\n**冲坑持续扩大说明水在掏空路基、随时可能塌陷，围挡随冲坑扩大而扩大，机械和人员退到安全距离外。**\n\n【两阶段关阀】\n**与C128同一逻辑：先关至折点开度，暂停看压力，剩余开度缓慢关完；折点开度按管网条件定，文献案例有15%和30%，不作为统一值；现场判据是压力表指针稳定、管道无明显振动和水锤声；**\n**折点暂停是防水锤的关键，不跳过。**多阀协同统一指挥，不各自为战。\n\n【止水范围最小化】\n**能止水前提下少关阀；评估影响户数；保医院学校；具备条件开旁路。**大口径关一个阀影响面大，能少关一个就少关一个。\n\n【分段排查】\n**止水后分段查故障程度和波及范围，查周边管段是否受损；不只看爆管点本身。**爆管冲击波可能造成邻近接口松动，排查范围超出爆管点。\n**爆管冲击波会震松邻近接口，排查要往上下游各多查一两个接口和井，别只修看得见的破口；地面沉降、路面冒水都要记下来一并处理。**\n\n【修复与支护】\n**按管材漏点选哈夫节、连接器或切换；大口径连接器锁紧环周圈均匀（判据见C123）；开挖段按C127支护，回填分层。**大口径修复后支撑防脱，不支撑直接回填，通水压力波动可能拉开。\n**大口径抢修机具提前调齐（吊装、支撑、抽排、照明），停水时间长要给用户和重点单位发通知。**\n\n【分步复水+排气】\n**先低压充水，打开高点排气阀，再逐步升压；慢开阀；监测压力；异常暂停。**大口径不排气就升压，气阻加水锤双重风险。大口径复水分级升压，每级稳压看压力表和接口，确认无渗漏再升下一级。","structure":"主链：围挡定位→两阶段关阀→控范围→分段排查→修复支护→排气分步复水；要点：1冲坑边不站人；2折点暂停不跳过；3多阀统一；4分段查周边；5先排气再升压；引导：C133老旧管网。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"PE给水管","ref":"PE给水管"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"复合式排气阀","ref":"复合式排气阀"},{"name":"压力表","ref":"压力表"}],"pitfall":"冲坑边不站人；折点暂停不跳过；不复水前不排气；不一步满压。","remark":"","seq":132,"family":"GW-03 管网抢修与快速处置","lessonNo":21},{"id":"C133","sub":"GW-03","topic":"老旧管网连环漏与薄弱管段分步处置技巧","level":"D4/L4","d":"D4","l":"L4","positioning":"本课只讲老旧管网多点渗漏、薄壁管、分步处置；不重复大口径和第三方专项。","framework":"1 连环漏特征；2 先控最重漏点；3 管壁评估；4 手感发虚即停；5 机械抢修优先；6 分批整改；7 复水观察新漏。","lecture":"【连环漏特征】\n**多点渗漏、管壁腐蚀变薄、接口老化；一处修完别处可能再漏。**先评估整体管段状况，不把这一处当全部。连环漏不是“修完这个就完事”，要有后续整改计划。\n**连环漏修完一处别处又漏，常见原因是水压转移到薄弱段，所以不能哪漏补哪，要评估整段并列入分批更换。**\n\n【先控最重】\n**先止最严重漏点，止水降压；影响户数大的先保重点；设围挡；不平均用力。**最重的漏点不一定是最大的，可能是位置最关键、影响户数最多的。\n\n【管壁评估】\n**看腐蚀程度、管壁减薄、接口状态；腐蚀严重或薄壁管段，抱箍紧固手感发虚即停。**手感发虚的具体含义：抱箍扳手继续拧紧时，阻力不随转角增大，反而变轻、发软，或扳手出现空行程——这是管壁已被压屈服的信号。\n**出现这个信号，立即停手，不继续加力；换更大接触面积的抱箍，或改为停水切换。**薄壁管大力紧固会把漏点变成断裂。薄壁管别硬装抱箍，扳手越拧越发虚就停手，改用停水切换或整段更换。\n\n【不强行带压】\n**老旧管尽量停水或降压处理；必须带压时仅限小漏低压指定器材（边界见C130）；不拿老旧管试带压。**\n**老旧管网带压抢修时，抱箍螺栓用力要轻、分级紧，手感发虚立即停手；旁边还有漏点时压力会反复波动，带压更难控，能停水就停水。**\n\n【机械抢修优先】\n**哈夫节、连接器、临时抱箍优先；不轻易动火、不强行焊接薄壁腐蚀管；焊穿比漏更麻烦。**\n\n【分批整改与复水】\n**制定分批更换高危管段计划，先急后缓，不一次大面积开挖；分步升压复水，观察周边有无新漏；记录高频漏点，供C145工法迭代。**\n**给每个漏点建档（位置、日期、形态、处理），高频漏段优先纳入改造。**","structure":"主链：控最重→评管壁→手感发虚即停→机械抢修→分批整改→复水观察；要点：1薄壁阻力变轻/发软/空行程=压屈服，立即停；2老旧管不强行带压；3机械优先不动火；4分批不全面开挖；引导：C134第三方。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"压力表","ref":"压力表"}],"pitfall":"手感发虚不是再使点劲，是停手信号；老旧管不强行带压；不一次全换。","remark":"","seq":133,"family":"GW-03 管网抢修与快速处置","lessonNo":22},{"id":"C134","sub":"GW-03","topic":"第三方施工破坏损伤识别与快速止水修复技巧","level":"D4/L4","d":"D4","l":"L4","positioning":"本课只讲损伤识别与快速止水修复：挖破、机械损伤、多管同损、防二次。","framework":"1 损伤识别；2 先关上游阀止水；3 核实范围；4 按形态选件修复；5 防二次破坏；6 复水观察；7 记录用于工法。","lecture":"【损伤识别】\n**挖破多不规则破口；机械损伤可能压扁或划伤；看漏水量和水柱高度判断破口大小，水柱突然增大提示破口扩大；多管同损要查周边燃电通信管线，不只盯给水管。**\n**第三方破坏往往不是单根管，挖掘机一铲下去可能同时伤给水、燃气、通信。**第三方破坏现场先止水控险，再拍照取证、通知产权和施工方；挖掘机一铲常同时伤多条管线，务必查清燃气、电力、通信有没有被伤。\n\n【先关上游阀】\n**第一时间关上游阀止水，控制漏点扩大；设围挡警戒；积水先抽排；不先拍照后止水。**止水优先于记录，漏点扩大损失更大。若怀疑伤及燃气管，立即疏散人员、禁火禁电、通知燃气抢修，给水管抢修让位于燃气险情。\n\n【核实范围】\n**确认单点还是多点损伤；查周边管线连带；评估影响户数；确定修复方案再动手。**核实不是“看一眼”，是沿破口走向查相邻管段和接口。\n**机械挖破的破口边缘常有应力集中和隐性裂纹，核实范围要比肉眼看到的破口放大一圈；同一开挖面多根管并排时逐根查，别只盯漏水的那一根。**\n\n【按形态修复】\n**管身破口用哈夫节（判据见C122）；断管用连接器或切换；PE按C137热熔；修复前清表面；按工艺紧固，不差不多拧上。**\n\n【防二次破坏】\n**对施工区域设围挡警示、向现场人员做安全交底、标记管线走向；不交底就撤围挡，等着再被挖一次。**交底要讲清管线位置、埋深、走向，不只在围挡上贴张纸。\n**修复后在地面标出管线走向和埋深、向施工方交底并留联系方式，围挡和标识保留到回填夯实完成。**\n\n【记录】\n**记录损伤位置、形态、管材、修复材料，只用于工法沉淀和管线保护改进。**","structure":"主链：识别→关上游→核范围→按形态修→防二次→记录；要点：1先止水再拍照；2查多管同损；3按形态选件；4交底防二次；引导：C135汛期。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"PE给水管","ref":"PE给水管"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"}],"pitfall":"不先拍照后止水；不只修主漏不管周边；不交底就撤围挡。","remark":"","seq":134,"family":"GW-03 管网抢修与快速处置","lessonNo":23},{"id":"C135","sub":"GW-03","topic":"汛期悬空管道临时支撑与边坡防护抢修技巧","level":"D4/L4","d":"D4","l":"L4","positioning":"本课只讲汛期悬空管道和边坡：临时支撑、边坡防护、修复、覆土恢复；通用开挖归C127。","framework":"1 汛期风险；2 先排查边坡路基；3 临时支撑｜垫软、不顶防腐；4 边坡防护｜坡顶1m内不堆载；5 接口管身修复｜防脱；6 覆土恢复；7 汛期加密巡检。","lecture":"【汛期风险】\n**雨水冲刷导致覆土流失、管道悬空、移位、接口拉脱；先排查边坡裂缝、路基空洞，人员不站边坡下；设围挡警戒，防次生塌方。**汛期抢修第一风险不是管道本身，是边坡和路基的次生灾害，人站错位置比管漏更危险。\n**雨中水位上涨、边坡出现新裂缝或渗出浑水时立即撤人，别为抢进度留在坑内；雨后对悬空点复测，确认无新冲刷再收工。**\n\n【临时支撑判据】\n**悬空管段用支墩、吊架、木方临时支撑；支撑点垫软物，不直接顶防腐层或管身薄弱处；支撑要稳，不临时靠一下；球铁承口不悬空受力；长距离悬空应采用悬吊、支撑等措施将管道恢复至正常位置。**\n**支撑不是垫一下就走，要能承受管道自重和满水重量，支撑点间距按管径和壁厚定，大口径间距更密。**\n\n【边坡防护】\n**沙袋压坡脚、排水沟导流、彩条布覆盖；坡顶线1m范围内不应堆载、停放设备；先稳边坡再修复管道；边坡未稳就开挖修复等于边修边塌。**坡顶堆载是常见错误，挖出来的土堆在坡顶，增加下滑力，支护再好也可能塌。\n\n【修复】\n**查接口是否拉脱、管身是否变形；接口换胶圈复位（判据见C138）；管身破损哈夫节或切换；连接器注意防脱（C123）。**修复前先确认边坡稳定，修复中随时观察边坡变化，有裂缝扩大立即撤人。\n\n【覆土恢复】\n**修复后分层回填夯实，恢复护坡，设标识；不恢复覆土等于下次汛期同一位置再冲毁。**覆土不是随便堆回去，分层夯实、恢复原坡度，护坡按原设计恢复。\n\n【加密巡检】\n**汛期重点区域雨前雨后加密，记录悬空点和边坡变化；不把汛期巡检当日常巡检走。**雨前查排水、雨后查冲刷，两个时间点都不能省。\n**汛期把易冲刷、已悬空的管段列入重点清单，加密查看；夜间也要设警示，别等白天才发现管道又被冲空。**","structure":"主链：排查围挡→临时支撑垫软→边坡先稳（坡顶1m不堆载）→修复防脱→覆土恢复→汛期加密；要点：1不站边坡下；2支撑垫软不伤防腐；3坡顶1m不堆载；4边坡先稳再修管；5覆土分层恢复；引导：C136钢管。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"PE给水管","ref":"PE给水管"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"}],"pitfall":"支撑不垫软伤防腐；边坡不稳就修管；坡顶堆载等于加下滑力；不恢复覆土。","remark":"","seq":135,"family":"GW-03 管网抢修与快速处置","lessonNo":24},{"id":"C136","sub":"GW-03","topic":"钢管焊缝、法兰渗漏与动火/免动火抢修技巧","level":"D4/L4","d":"D4","l":"L4","positioning":"本课只讲钢管焊缝和法兰渗漏：焊缝、点蚀、法兰、动火条件、免动火；连接器归C123。动火标准按GB 30871-2022体积分数口径，法兰补紧无效才换垫补判据。","framework":"1 焊缝渗漏；2 点蚀穿孔；3 法兰渗漏｜先紧后换垫；4 动火条件｜隔离+置换+检测；5 动火合格标准｜体积分数口径；6 免动火；7 试压+防腐。","lecture":"【焊缝渗漏】\n**焊缝是薄弱点，腐蚀优先沿焊缝发展；小渗漏可打磨补焊，大缺陷切换；动火前必须停水、泄压、清管，不带压动火。**焊缝渗漏先看锈迹走向，腐蚀沿焊缝一条线发展，不是散点。\n\n【点蚀穿孔】\n**表面小孔内部坑状，敲击听空响；小孔用哈夫节或补板；大范围腐蚀切换；清表面再补，不点一下焊了事。**点蚀小孔背后可能是一大片坑，补焊前先打磨到露出金属本色，看坑的范围再决定补板还是切换。\n\n【法兰渗漏】\n**先对角分遍补紧螺栓；补紧仍漏或持续滴漏，才拆换垫片；换垫时旧垫不得重复使用，密封面残渣除净、法兰对中再装垫；法兰密封面划痕深度超过0.2mm且覆盖面超过垫片密封面宽度一半时，密封面须重新加工或换法兰，**\n**不靠多紧几扣凑合。**顺序不是上来就换垫。\n\n【动火条件】\n**执行先隔离、后置换、再检测、后动火；办动火票、专人监护、配灭火器材；带水带压不碰动火。**隔离不是关阀就行，要加盲板或断开管线，防止阀门内漏串气。\n\n【动火合格标准：体积分数口径，非%LEL】\n**按GB 30871-2022第5.3.2条，动火分析合格判定为：被测气体爆炸下限≥4%时，浓度≤0.5%（体积分数）；爆炸下限<4%时，浓度≤0.2%（体积分数）。**\n**便携式检测仪读数以%LEL显示时，须按该气体爆炸下限换算，不把0.2%LEL当作合格标准。**具体检测手段和企业限值以现行制度为准，课程不代填统一限值。\n\n【免动火】\n**哈夫节、法兰修补器、连接器用于免动火抢修；按管径压力选；胶垫对准（判据见C122/C123）。**能免动火就不动火，动火审批和风险都比机械抢修高。\n\n【试压与防腐】\n**按标准保压，查焊缝法兰；补防腐；不试压就回填等于把隐患埋下去。**","structure":"主链：判渗漏→停水泄压→法兰先紧后换垫→动火四步→合格标准（体积分数两档）→免动火→试压防腐；要点：1法兰不先换垫；2动火必须隔离置换检测；3≥4%时≤0.5%、<4%时≤0.2%（体积分数）；4不把0.2%LEL当标准；5试压防腐；引导：C137 PE热熔。","anchors":[{"name":"直缝焊接钢管","ref":"直缝焊接钢管"},{"name":"螺旋缝焊接钢管","ref":"螺旋缝焊接钢管"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"胶垫（法兰橡胶垫片）","ref":"胶垫（法兰橡胶垫片）"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"}],"pitfall":"动火标准是体积分数不是%LEL；法兰密封面划痕超0.2mm不凑合；旧垫不重用；隔离不是关阀就行。","remark":"动火口径按GB 30871-2022","seq":136,"family":"GW-03 管网抢修与快速处置","lessonNo":25},{"id":"C137","sub":"GW-03","topic":"PE管热熔/电熔修复翻边判断与冷却防扰动技巧","level":"D4/L4","d":"D4","l":"L4","positioning":"本课只讲PE热熔/电熔：端面、对齐、加热、翻边判据、冷却、电熔；断管连接归C139。翻边切除比例不写死，验收以根部凹槽不低于管外壁等外观判据加切除检验为准。","framework":"1 热熔适用；2 铣端面；3 对齐｜错边≤壁厚10%；4 加热对接｜参数按设备；5 翻边判据｜实心圆滑+根部凹槽不低于管外壁；6 冷却不扰动；7 电熔。","lecture":"【热熔适用】\n**PE管段更换永久修复首选；强度高、寿命长；不能带水热熔；小漏点应急用机械（C118）。**热熔是永久修复，不是应急手段，带水、带压都不能热熔。\n\n【端面与对齐】\n**铣平端面去氧化层，端面平整无油污；错边量不超过壁厚的10%；夹具固定，不强行对中；管端面与轴线垂直。**错边超10%不重做，后面翻边再好看内部也融不匀。\n\n【加热与切换】\n**按设备说明和企业工艺参数加热；达到熔融后迅速切换对接；切换时间越短越好，管端凉了再对接就是假焊。**切换时间通常控制在几秒内，具体按设备要求，手忙脚乱拖到十几秒，熔融面已经降温。\n\n【翻边验收判据】\n**翻边应实心圆滑、根部较宽；沿圆周平滑对称；翻边下侧无杂质、小孔、扭曲。**最关键的一条快速判据：翻边根部凹槽底部应高于管材外表面；根部V型凹槽过深、低于管外壁，即判不合格，割除重焊，不看着还连着放行。\n**翻边表面无气孔、无鼓泡、无过烧碳化；翻边不对称提示管端未对正或加热不均。**\n**翻边宽度约0.5–0.8倍壁厚（e）、翻边高度约0.2–0.25e，可作为过程参考，但验收以实心圆滑、根部宽、根部凹槽不低于管外壁、下侧无缺陷为准，不以单一宽度数值判合格。**\n**翻边切除检验按适用规范和企业工艺文件执行，不把某一比例写死。**\n\n【冷却判据】\n**冷却期间不移动、不撬动、不踩踏、不浇水、不施加任何外力；完全冷却再移夹具；冷却时间按设备/管材厂家规定，不凭摸着不烫判断，专人计时。**\n**DN110以下冷却不少于20分钟，DN110以上不少于30分钟是常见现场口径，具体按厂家规定。**\n\n【电熔】\n**刮氧化层、插到位、按参数通电；观察熔接指示；冷却不扰动。**\n\n【假焊信号】\n**翻边不对称、根部凹槽低于管外壁、有气孔、冷却期间被扰动——任一出现按不合格处理，切除重做，不再用用看。**","structure":"主链：铣端面→错边≤10%→加热对接→翻边判据（根部凹槽不低于管外壁）→冷却不扰动→电熔；要点：1错边≤10%；2根部凹槽低于管外壁=不合格；3冷却不移动不浇水；4翻边好看≠内部融合；5假焊信号=重做；引导：C138球铁接口。","anchors":[{"name":"PE给水管","ref":"PE给水管"},{"name":"PE弯头","ref":"PE弯头"},{"name":"PE三通","ref":"PE三通"},{"name":"PE直接","ref":"PE直接"}],"pitfall":"根部凹槽低于管外壁不看着还连着；冷却扰动=假焊；错边超10%不重做；翻边宽度不单一判合格。","remark":"翻边判据以根部凹槽+切除检验为准","seq":137,"family":"GW-03 管网抢修与快速处置","lessonNo":26},{"id":"C138","sub":"GW-03","topic":"球墨铸铁管承插接口渗漏胶圈复位与插入深度控制技巧","level":"D4/L4","d":"D4","l":"L4","positioning":"本课只讲球铁承插接口：胶圈复位、插入深度（标记环）、尺检、相邻接口复查、T/K型；连接器归C123。轴向间隙按不小于3mm、上限按产品技术文件/设计执行。","framework":"1 承插接口；2 T型推入/K型压兰；3 胶圈入槽｜不扭曲；4 插入深度｜标记环+相邻复查；5 尺检判据｜周圈深度一致；6 轴向间隙≥3mm；7 渗漏处置+试压。","lecture":"【承插接口】\n**球铁承口粗、插口细，靠胶圈挤压密封；柔性接口允许微小偏转；渗漏多因胶圈老化、移位或插入不到位。**承口槽内如果有泥沙、旧胶圈碎片，胶圈压不实，先清槽再装。\n\n【T/K型】\n**T型推入式，胶圈塞槽后插口硬推进；K型机械式，胶圈外加金属压兰用螺栓压紧；T型靠推、K型靠压，分清再装。**T型硬推时涂润滑剂，K型压兰螺栓对角均匀紧，不单边压。\n\n【胶圈入槽】\n**清承口槽，胶圈不扭曲入槽；润滑剂用无毒碱性润滑剂或肥皂水，不用油脂类；胶圈粗细不均、有气泡/重皮不用。**胶圈入槽后用手捋一圈，感觉有扭曲立即重装，不靠推进去硬纠。\n**润滑剂只能用中性肥皂水或厂家指定产品，油脂类会泡胀橡胶导致密封失效；冬季胶圈发硬先用温水（不烫手）回软再装，不用火烤。**\n\n【插入深度与相邻复查】\n**插口按承口深度做好安装标记，推入深度应达到标记环；达到标记环后，必须复查与其相邻已安好的第一至第二个接口推入深度，防止已安好接口被拔出或错位。**\n**沿直线安装时，承插口间纵向间隙不应小于3mm；上限按产品技术文件或设计要求执行，不同厂家/接口型式可能有不同规定，课程不代填统一上限。**检查方法：观察加塞尺或钢尺检查。\n**插口推进时如果阻力突然变大，别硬推——多半是胶圈被挤歪或承口有异物，退出来清干净重插，硬推会把胶圈切坏，当时不漏、通水就漏。**\n\n【尺检判据】\n**安装后用金属直尺插入承插口之间检查橡胶圈各部的环向位置，确认橡胶圈在同一深度——深度一致等于到位；不一致等于胶圈脱位，重装。**不凭推进去了判断到位。\n\n【渗漏处置】\n**接口渗漏先泄压拆查；胶圈老化换圈；接口错位复位；承口损伤用连接器或换管；不用哈夫节硬抱接口（边界见C125）。**\n\n【试压】\n**复位后按规定试压，观察周圈；分步升压。**","structure":"主链：清槽→胶圈入槽不扭曲→插到标记环→复查相邻第一至第二个接口→尺检周圈一致→轴向间隙≥3mm（上限按产品文件/设计）→换圈复位→试压；要点：1插到标记环只是第一步；2复查相邻接口；3尺检深度一致；4轴向间隙≥3mm；5接口不硬抱；引导：C139断管连接。","anchors":[{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"}],"pitfall":"推进去≠到位；不复查相邻接口=已安好的可能被拔出；尺检不一致=脱位重装；轴向间隙不小于3mm。","remark":"轴向间隙口径修正为≥3mm，上限按产品技术文件/设计","seq":138,"family":"GW-03 管网抢修与快速处置","lessonNo":27},{"id":"C139","sub":"GW-03","topic":"管段切除、断管连接与异材转换通用技巧","level":"D4/L4","d":"D4","l":"L4","positioning":"本课只讲断管切除与异材转换通用：切除长度、工具、连接方式、转换件、支撑、试压；各管材工艺归C136–C138。","framework":"1 切除长度与切口质量；2 工具按管材选；3 连接方式；4 异材转换；5 支撑防脱；6 试压；7 回填。","lecture":"【切除长度】\n**切除破损段并留连接余量；量准两端；切口平齐。**切除前量好两端尺寸，切口留出连接件长度加余量，切短了接不上，切长了浪费管件。切除长度不是“看着切”，要按连接件实际长度加两端各留10–15mm余量。\n\n【切口质量判据】\n**PE管切口端面与轴线垂直度偏差不超过5°，切口无毛刺、无椭圆变形；球铁管切割后用手摸切口无尖锐凸起，凸起会割伤胶圈；钢管切口打磨坡口，坡口角度按焊接工艺，不直接对焊。**\n**切口不合格，连接件密封面贴不实，装上去也是漏。**切完用手摸一圈，有毛刺、有斜面、有椭圆，重切不凑合。\n\n【工具与连接】\n**PE热熔/电熔；球铁承插或连接器；钢管焊接或法兰；衬塑冷切割（见C13/C120）；按管材选连接方式，不混用。**PE不能套丝，钢管不能热熔，衬塑不能电焊，工具拿错切口就废。\n\n【异材转换】\n**PE接金属用PE法兰头或内丝/外丝直接；球铁接钢管用连接器；转换件压力等级和口径匹配；胶圈不扭曲（C123）。**异材转换件不是万能件，压力等级不够、口径不匹配，装上就漏。\n**转换件选型核三项：压力等级不低于原管、口径匹配、端头型式对得上。**\n\n【支撑防脱】\n**断管连接后设支墩或支撑；大口径重点防脱；回填前固定。**支墩尺寸按管径和试验压力确定，不是“随便垫块砖”。\n**DN300以上断管连接，支墩要能承受满水管道轴向推力，回填前用木楔临时固定，回填后支墩与管身之间加软垫防硬性挤压。**不支撑直接回填等于通水压力波动可能拉开。通水后第一天复查支墩有无位移。\n\n【试压与回填】\n**按规定试压，查连接口；分步升压；管周细土分层夯实；恢复标识。**试压先低压后升压，连接口渗漏泄压重做，不带压紧螺栓。回填管周细土或砂分层夯实，不用石块直接砸管；回填到设计标高。","structure":"主链：定切除（留10–15mm余量）→切口质量（垂直度≤5°、无毛刺椭圆）→选连接→异材转换（压力/口径/端头三项核）→支撑（支墩承受轴向推力）→试压→回填；要点：1切口平齐、垂直度≤5°；2按管材选工具；3转换件三项匹配；4支墩不是随便垫砖；5试压后复查支墩；引导：C140多户停水。","anchors":[{"name":"PE给水管","ref":"PE给水管"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"直缝焊接钢管","ref":"直缝焊接钢管"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"PE法兰头/片","ref":"PE法兰头/片"},{"name":"胶圈（球墨管承插密封圈）","ref":"胶圈（球墨管承插密封圈）"}],"pitfall":"切口不平会漏；转换件不匹配装不上；大口径不支撑会脱；支墩不是随便垫砖。","remark":"本轮补入切口垂直度、支墩尺寸判据","seq":139,"family":"GW-03 管网抢修与快速处置","lessonNo":28},{"id":"C140","sub":"GW-03","topic":"小区立管、分户支管与多户停水快速处置技巧","level":"D4/L4","d":"D4","l":"L4","positioning":"本课只讲小区立管、分户支管、多户停水：关阀、通知、临时供水、排气、分户复水；表组归C121。","framework":"1 立管漏｜关立管阀影响多户；2 分户支管漏｜关单户；3 多户停水｜通知+影响户数；4 临时供水｜取水点；5 复水排气｜高点；6 分户查压；7 边界｜表组C121。","lecture":"【立管与分户支管】\n**立管漏关立管阀，影响多户；分户支管漏关单户表前阀；表前支管归C120。**先判漏点在哪一级，再定关阀范围，不一关一大片。立管漏和分户支管漏的关阀范围差一个数量级，判错影响户数翻倍。\n\n【多户停水】\n**关立管阀前评估影响户数，提前贴通知或群通知；设临时取水点；优先保障老人等特殊用户；不关阀后才通知。**通知不是走过场，要写清停水时间、影响范围、临时取水点位置。\n**停水通知提前发，写清起止时间、影响楼栋和临时取水点，医院等重点用户单独告知。**\n\n【临时供水】\n**临时供水车或取水点；告知用户水质合格；不把临时取水点设在污染源附近。**临时取水点要有围挡和标识，不让人误以为是污水。\n**停水时间较长要设临时取水点，保证水质、明确谁负责，通知里写清取水点位置。**\n\n【复水排气判据】\n**修复后先开最高处水龙头或立管高点排气阀排气，再分户慢开阀；以高点排气、慢开阀、见稳定水流再开下一户为操作原则，不一步全开；气排不净会出现气阻、水表空转、水锤。**\n**复水顺序现场有先高后低和从低到高两种做法，抢修场景以高点排气、慢开阀、见稳定水流再开下一户为操作原则。**\n**复水后按单元逐户确认来水，顶层和高点最后确认、气阻排净再让用户正常用水；用户反映无水不要让用户自己反复开关阀。**\n\n【分户查压】\n**逐户开阀后查水压和出水；异常（无水/浑水/漏水）单独处理，不全开完就走。**浑水先放至清，不把浑水留给用户。楼道立管作业空间窄，工具系绳、材料随身带，防高空坠物；作业完恢复楼道通行和消防设施。\n\n【边界】\n**表组组件归C121；本课只讲多户组织与复水。**","structure":"主链：判漏点级别→关阀→通知→临时供水→高点排气→分户慢开查压；要点：1先判级别再关阀；2关阀前通知；3高点排气；4分户慢开查压；5浑水放清；引导：C141复水。","anchors":[{"name":"PPR给水管","ref":"PPR给水管"},{"name":"衬塑复合管","ref":"衬塑复合管"},{"name":"黄铜内螺纹浮动球阀","ref":"黄铜内螺纹浮动球阀"},{"name":"旋翼式机械水表（湿式/干式/液封）","ref":"旋翼式机械水表（湿式/干式/液封）"}],"pitfall":"不关一大片；不关阀后才通知；不一步全开；不复水前排气；浑水不留给用户。","remark":"","seq":140,"family":"GW-03 管网抢修与快速处置","lessonNo":29},{"id":"C141","sub":"GW-03","topic":"抢修临时供水、分段复水、排气与水锤防控技巧","level":"D4/L4","d":"D4","l":"L4","positioning":"本课只讲通用复水：临时供水、复水前检查、分段复水、排气、水锤防控、异常暂停；大口径专项归C132。","framework":"1 临时供水；2 复水前检查；3 分段复水｜低压→升压；4 排气｜高点；5 水锤防控｜慢开慢关；6 水质观察；7 异常暂停。","lecture":"【临时供水】\n**设临时取水点或减压供水；保障基本用水；告知用户；水质合格。**临时供水不是把水接出来就行，要保证水质和取水安全，取水点设围挡和标识。\n\n【复水前检查】\n**确认修复完成、阀门状态正确、井盖复位、人员撤离、工具材料清出；未检查就开阀等于把修复成果交给运气。**检查不是走一圈，要逐项确认：修复点无渗漏、阀门开到位、井盖盖好、人员撤到安全区。\n\n【分段复水：升压速率判据】\n**先低压充水，再逐步升压；分区域开阀；不一步全开；监测压力。**升压速率不是“慢点就行”：低压充水阶段压力控制在工作压力的1/3以内，观察10分钟无渗漏再升到2/3，再观察10分钟，最后升到工作压力。\n**每次升压后检查修复点和沿线阀门井，异常立即停泵泄压。**分区域开阀能让问题暴露在小范围内，一步全开，一处漏全线停。\n\n【排气：位置和声音判据】\n**打开高点排气阀；管道充水排气；气排不净会导致气阻、水表空转、水锤。**排气阀位置不对，排了也白排：排气阀必须装在管线最高点或坡度变陡处，装低点只能喷水排不出气。\n**排气时听声音：连续嘶嘶是气在排，变成哗哗是水出来了，见稳定水流再关阀。**见稳定水流再关排气阀。\n\n【水锤防控：分次开阀判据】\n**慢开慢关；大口径分多次；压力异常暂停；不快速满开。**大口径阀门开阀分三次：先开1/4观察压力，再开1/2观察，最后全开；每次间隔不少于2分钟，压力表指针稳定再开下一档。\n**快速满开一次，水锤压力可能达到正常工作压力的2–3倍，能把刚修好的接口震开。**\n\n【水质观察】\n**冲洗至出水清澈；浊度明显下降再继续；异常排放；必要时按C142做冲洗消毒。**复水初期水浑是正常的，放到清再供。\n\n【异常暂停】\n**渗漏、压力骤降、水质异常：立即停，查原因再复水；不再开大点冲冲看。**冲冲看只会把小漏冲成大漏。","structure":"主链：临时供水→复水前检查→低压1/3观察10分钟→2/3再观察→工作压力→高点排气（听声音）→分次开阀（1/4→1/2→全开，间隔≥2分钟）→观察；要点：1升压1/3→2/3→满压，每步10分钟；2排气阀装高点，听嘶嘶变哗哗；3开阀分三次，间隔2分钟；4异常暂停；5水浑放清；引导：C142协同水质。","anchors":[{"name":"压力表","ref":"压力表"},{"name":"复合式排气阀","ref":"复合式排气阀"},{"name":"弹性座封闸阀（暗杆式）","ref":"弹性座封闸阀（暗杆式）"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"}],"pitfall":"不一步全开；不排气就升压；快速满开出水锤；异常不硬复；水锤能震开刚修好的接口。","remark":"本轮补入升压1/3→2/3→满压、开阀1/4→1/2→全开判据","seq":141,"family":"GW-03 管网抢修与快速处置","lessonNo":30},{"id":"C142","sub":"GW-03","topic":"抢修现场多工种协同、信息同步与水质防控技巧","level":"D4/L4","d":"D4","l":"L4","positioning":"本课只讲协同、信息同步、水质冲洗消毒；复水操作归C141，资源统筹归C144。冲洗消毒显性标注GB 50268-2008依据，20mg/L为最低值。","framework":"1 协同岗位；2 统一指挥；3 信息同步；4 交通导改；5 水质冲洗｜GB 50268依据；6 用户通知；7 记录。","lecture":"【协同岗位】\n**抢修负责修复；调度负责关阀复水；水质负责冲洗检测；交通负责导改；各司其职，不互相替代。**抢修人员兼做水质检测，检测结果没人信；调度兼做交通导改，两头顾不上。\n**冲洗时盯住排水口浊度和用户端出水，确认水质合格再复水，别只冲不判。**\n\n【统一指挥与信息同步】\n**现场设指挥人，指令出口一致；到场、止水、修复完成、开始复水四个节点定时回传；信息不同步会导致这边已复水、那边还在拆阀。**统一指挥不是设个指挥人就行，指令要一个出口，不能多个人同时下指令。\n\n【水质冲洗判据：依据GB 50268-2008第9.5.3条】\n**第一次冲洗：用清洁水冲洗至出水口浊度小于3NTU，冲洗流速大于1.0m/s。**\n**第二次冲洗：第一次冲洗后，用有效氯离子含量不低于20mg/L的清洁水浸泡24h，再用清洁水冲洗至水质检测、管理部门取样化验合格。**\n**注意：20mg/L是规定的最低值，北京等地实践常用25–50mg/L，地方或企业制度可能高于此值，具体以现行制度为准。**余氯按现行标准执行，不代填统一限值；水质不合格不复水。\n**冲洗流速大于1.0m/s不是大概开大一点，需要用流量或流速计确认。**冲洗排水引到指定排放点，不漫流冲刷边坡和路面；取样化验由管理部门取样，现场只做浊度初判。\n\n【用户通知】\n**停水通知、复水通知、临时取水点；重点用户单独告知。**通知要提前发，不是停了水再发。复水后提醒用户先放水至清澈再用，有净水器、热水器的用户尤其要放，避免初期浑水进设备。\n\n【记录】\n**协同节点、水质检测结果、复水时间，用于闭环（C143）。**","structure":"主链：定岗位→统一指挥→节点同步→冲洗消毒达标（GB 50268：浊度<3NTU、流速>1.0m/s、含氯≥20mg/L浸泡24h，20mg/L为最低值）→通知→记录；要点：1统一指挥；2四节点同步；3冲洗消毒按GB 50268；4含氯20mg/L是最低值；5水质不合格不复水；引导：C143闭环。","anchors":[{"name":"压力表","ref":"压力表"},{"name":"复合式排气阀","ref":"复合式排气阀"},{"name":"球墨铸铁井盖（给水/消防）","ref":"球墨铸铁井盖（给水/消防）"},{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"}],"pitfall":"各自为战；水质不合格复水；把20mg/L当标准值而非最低值；冲洗流速不够；停了水再通知。","remark":"显性标注GB 50268-2008及20mg/L最低值","seq":142,"family":"GW-03 管网抢修与快速处置","lessonNo":31},{"id":"C143","sub":"GW-03","topic":"抢修全流程闭环、记录沉淀与工法改进","level":"D4/L4","d":"D4","l":"L4","positioning":"本课只讲单次抢修闭环：接单到复盘、记录七要素、材料台账、复盘、档案、改进；体系迭代归C145。","framework":"1 接单派工记录；2 现场记录；3 验收记录；4 材料台账；5 复盘；6 一漏一档；7 高频漏点改进。","lecture":"【记录七要素】\n**接报时间、到场时间、故障位置、漏点类型与程度、使用材料明细、处置过程、恢复通水时间；及时准确可追溯，不事后补记、不模糊写。**七要素不是“写满就行”：接报时间和到场时间用于算响应时长；\n**故障位置写到桩号或门牌号，下次同一位置再漏能查历史；漏点类型写清管材、接口形式、破损形态；材料明细写到规格和数量；处置过程写清止水方式、修复工法、试压结果；通水时间精确到分钟。**\n**模糊写“某处漏水、已修好”，复盘时什么都查不到。**\n\n【材料台账】\n**领用有记录、消耗有统计、余料退库；账实相符；不领多少用多少、余料私自处理。**\n**台账不是月底补：领料时当场登记，消耗按工单核销，余料当天退库；退库材料要标注“可复用/降级/报废”，可复用的下次优先发，报废的走报废流程不混入库存。**月底盘一次，账实不符查原因，不“调账做平”。\n**台账不是给上面看的，是下次备料时知道什么用得快、什么老剩。**\n\n【复盘判据】\n**复盘只问三件事：漏点成因是什么、选型是否合适、工法哪里可优化；返工案例找根因。**复盘三问要有具体答案，\n**不是“成因是老化”就完了：成因写到“胶圈老化是因为该段阀门井长期积水、胶圈长期浸泡”；选型写到“哈夫节压力等级够不够、胶垫材质适不适配”；工法写到“紧固顺序是否对角、清理是否到位”。**\n**每个答案对应一条改进措施，措施要能在下次抢修中验证。**\n\n【一漏一档与高频统计】\n**一漏一档记录位置、原因、处置、材料、时间；按管段统计故障次数，形成高频漏点清单，供C145专项治理。**高频清单不是列出来就完事，要标出哪一段一年漏三次以上。\n**一漏一档不是填张表，是下次同一位置再漏时，能查到上次怎么修的、用了什么材料、为什么漏。**\n\n【改进】\n**针对高频漏点做专项治理；工法按效率、质量、返工率对比优化；材料选型迭代；形成记录→复盘→改进→再记录的闭环。**闭环不是画个圈，是每次改进都能在下一次抢修中验证。","structure":"主链：七要素记录（到桩号/门牌号）→台账（当场登记、余料当天退）→复盘三问（具体到原因/选型/工法）→一漏一档（标年漏三次以上）→改进（能验证）；要点：1七要素写到能复盘；2台账不月底补；3复盘三问要有具体答案；4高频清单标年漏三次；5改进要能验证；引导：C144资源统筹。","anchors":[{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"PE给水管","ref":"PE给水管"},{"name":"六角头螺栓（半丝/全丝）","ref":"六角头螺栓（半丝/全丝）"}],"pitfall":"记录不事后补；余料不退库；复盘不追责只改进；高频清单不列完就完事；台账不月底补。","remark":"本轮补入七要素具体写法、台账当场登记、复盘三问具体化","seq":143,"family":"GW-03 管网抢修与快速处置","lessonNo":32},{"id":"C144","sub":"GW-03","topic":"多故障并发抢修资源统筹与跨区域支援","level":"D5/L5","d":"D5","l":"L5","positioning":"本课只讲多故障并发资源统筹：优先级、人料机调配、跨区支援、信息汇总；单次流程归C143。","framework":"1 并发场景与统一台账；2 优先级｜保重点/控大风险；3 人员调配｜技能/位置/负载；4 材料机具调配｜抢修包/关键机具；5 跨区支援｜联络/交接；6 信息汇总｜定时更新；7 防重复调派。","lecture":"【并发与台账】\n**多故障并发（爆管、多漏点、极端天气）先建统一故障-资源台账；无台账就调资源等于重复调派和漏派并存。**台账不是记一下，要实时更新：哪个点已派人、哪个点还缺人、哪个点已修复。\n**台账记清故障位置、类型、影响户数和当前状态，随进展更新，防止重复派工和漏派。**\n\n【优先级判据】\n**先保重点区域（医院、学校）、影响户数大、风险高的故障；先控大漏再修小漏；不平均用力。**优先级不是谁先打电话谁先修，是按影响和风险排。\n\n【人员调配】\n**按技能、位置、负载安排；设组长；关键岗位有备份；不把全部熟手压在一个点。**熟手全压一个点，其他点全是新手，出了问题没人兜底。夜间加派照明和监护，熟手分散到关键点、别全压一个点。\n\n【材料机具】\n**按抢修包配主辅件（C116）；热熔机、割管机、抽水泵、照明优先给关键故障；用完归还登记。**关键机具不是谁先抢到谁用，是按故障优先级调。\n**跨点调用机具要先问清对面点还需不需要用，别从一个正在抢修的点把设备抽走；关键机具用前先试运转，确认能正常启动再出发。**\n\n【跨区支援】\n**明确联络人、集合点、交接内容；支援队伍带自用工具；到场后统一指挥，不来了就各干各的。**跨区支援不是人到就行，要交接清楚现场情况、已做到哪一步、下一步做什么。\n**支援队伍到场先到指挥点报到、领任务、明确交接人和撤离集合点，未交接清楚不擅自开工。**\n\n【信息汇总】\n**故障清单、资源清单、进度定时更新；统一出口，避免多头指挥。**多头指挥比没人指挥更乱。各点进度统一报给指挥人，由指挥人对外发布，避免用户从不同人嘴里听到不同复水时间；台账和口头汇报要一致。","structure":"主链：建台账→排优先级→调人料机→跨区交接→定时汇总→防重复；要点：1保重点控大风险；2不平均用力；3关键机具优先关键故障；4跨区统一指挥；5台账实时更新；引导：C145工法迭代。","anchors":[{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"PE给水管","ref":"PE给水管"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"压力表","ref":"压力表"}],"pitfall":"不平均用力；不重复调派；跨区不交接不统一指挥；台账不更新等于没台账。","remark":"","seq":144,"family":"GW-03 管网抢修与快速处置","lessonNo":33},{"id":"C145","sub":"GW-03","topic":"抢修工法优化、预案迭代与知识沉淀","level":"D5/L5","d":"D5","l":"L5","positioning":"本课只讲体系级工法优化与预案迭代：高频分析、工法对比、材料迭代、预案演练、知识沉淀；单次记录归C143。","framework":"1 高频漏点分析；2 工法对比｜效率/质量/返工；3 材料选型迭代；4 预案迭代｜场景/资源/流程；5 培训演练；6 知识沉淀｜案例/口诀；7 改进闭环。","lecture":"【高频分析】\n**按管段、管材、接口统计高频漏点；用C143的档案数据找规律；确定专项治理优先序；不凭印象觉得哪里老漏。**数据说话，不是感觉说话。\n**统计要落到管段、管材、接口形式、漏态四个维度，只按位置统计看不出是管材问题还是施工问题。**\n\n【工法对比】\n**对比效率、质量、返工率、成本；小漏点机械快、永久修复热熔稳；不凭感觉改工法，用返工率和复漏率说话。**工法好不好，看三个数：一次合格率、返工率、平均耗时。\n**对比工法要记一次修复成功率、平均耗时、返工率和材料成本，数据来自C143的抢修档案，不靠印象。**\n\n【材料迭代】\n**根据现场反馈优化抢修包配置；淘汰不好用件；引入适配新件时核压力、口径、材质；不新件拿来就上。**新材料先小范围试用，验证后再推广。\n**常用规格的抢修件和密封垫在车上定置存放，出车前顺手查一遍，别等抢修时才发现缺件或胶垫老化。**\n\n【预案迭代】\n**按场景更新预案：大口径、老旧、冻胀、汛期；明确资源、流程、联络；预案必须演练验证，不演练的预案等于没更新。**预案不是写完放柜子里，每年至少演练一次。\n\n【知识沉淀】\n**案例库、工法卡、防雷小抄；一漏一档提炼；口诀化便于自学，沉淀只用于改进。**口诀不是顺口溜，是把关键判据压缩成能记住的一句话。\n**一漏一档要有现场照片、处置前后对比、用的什么件和为什么这么选；防雷小抄和口诀贴在抢修车上、写进班组交接本，新人才能用上。**\n\n【改进闭环】\n**问题→分析→措施→验证→固化；每一次迭代都回到下一次抢修能不能少返工、少停水这个标准上。**改进不是写报告，是下次抢修时用得上。","structure":"主链：高频分析→工法对比→材料迭代→预案演练→知识沉淀→闭环；要点：1用数据找高频；2用返工率评工法；3预案必演练；4沉淀口诀化；5闭环回到少返工少停水；引导：GW-03形成从入门到体系迭代的完整能力链。","anchors":[{"name":"哈夫节（堵漏器）","ref":"哈夫节（堵漏器）"},{"name":"多功能法兰连接器","ref":"多功能法兰连接器（防脱法兰/伸缩法兰接头）"},{"name":"球墨铸铁管","ref":"球墨铸铁管"},{"name":"PE给水管","ref":"PE给水管"},{"name":"压力表","ref":"压力表"}],"pitfall":"凭感觉改工法；预案不演练；沉淀不追责只改进；改进要能验证。","remark":"","seq":145,"family":"GW-03 管网抢修与快速处置","lessonNo":34}],"quizzes":[{"id":"C34-Q01","courseId":"C34","type":"单选","stem":"料场一根6m直管，管身喷码印着「PE100 De110 SDR11」，单子却写 DN100。按本课【口径天坑：DN与De】，下面判断正确的是？","options":{"A":"喷码 De110 与单子 DN100 矛盾，应直接拒收","B":"SDR11 说的是内径 11 毫米","C":"应该去找管身印着 DN100 的 PE 管","D":"De110 是 PE 管实际外径，对应图纸 DN100，属正常，别去量内径对 DN"},"answer":["D"],"explain":"对应课程【口径天坑：DN与De】。DN 是公称直径名义值，PE 管按 De 标实际外径，DN100 常见 De110；SDR 是外径÷壁厚，不是内径。别拿卡尺量内径去对单子。","multi":false},{"id":"C34-Q02","courseId":"C34","type":"单选","stem":"【冲突条件】现场要接入一段DN100的管线，库房里放着两根管子：一根是PE管（量得外径为110mm），一根是衬塑管（量得外径为114mm）。新员工量完后抱怨：“两根都不对，DN100的管子外径应该刚好是100啊，怎么一个110一个114？”你作为材料员该如何向他解释？","options":{"A":"两根都没错。图纸的DN100是名义尺寸。PE管看外径De，De110对应DN100；衬塑管看钢管外径Φ，Φ114也对应DN100","B":"确实都拿错了，应该找一根内径刚好是100的管子","C":"拿大号砂纸把外面的磨掉一点就能用了","D":"只能留下110的，114的太粗了装不上"},"answer":["A"],"explain":"对应课程【口径天坑：DN与De】。不同材质管子的外径标准不同。同为DN100，PE管外径是De110，而衬塑管（钢管基体）外径是Φ114，它们在各自的标准下都是正确的，只是不能混用管件。","multi":false},{"id":"C34-Q03","courseId":"C34","type":"多选","stem":"【冲突条件】新来的库管员在盘点PE管时，拿游标卡尺量了一根De110的PE管内径，发现只有90mm。他翻看单子要求“DN100”，觉得管子壁厚太厚导致内径缩水，打算拒收。关于这个判定，下列分析正确的是？","options":{"A":"PE管及钢管类管道，公称直径（DN）绝不等于实际内径","B":"De110的PE管，壁厚越厚，内径就越小，用内径去卡DN100是完全错误的","C":"管类材料的验收应以管身喷码的外径（De）为准","D":"他拒收是正确的，因为内径变小会导致水流量不足"},"answer":["A","B","C"],"explain":"对应课程【口径天坑】。管材口径标准中，DN是名义尺寸，不代表内径。PE管用De表示外径，不同壁厚（如SDR11或SDR17）内径完全不同。量内径拒收是极其外行的做法。","multi":true},{"id":"C33-Q01","courseId":"C33","type":"单选","stem":"图纸写 DN50 的衬塑管要领料，师傅顺口说「拿 2 寸的丝接件」。按本课【衬塑常用口径逐档完整对应表】，下面哪项判断正确？","options":{"A":"DN50 是 2 寸、正处丝接与沟槽交界档，按设计定接法，两种件不能混发","B":"DN50 就是 4 分，该领 4 分的丝接件","C":"DN50 一律沟槽连接，丝接件到此为止","D":"2 寸是实测 50 毫米，量内径对得上就行"},"answer":["A"],"explain":"对应课程【衬塑常用口径逐档完整对应表】【DN 与分管、寸、管螺纹：现场俗称对照】。DN50 俗称 2 寸，恰在丝接与沟槽交界档，按设计定接法；DN65 才是沟槽卡箍下限档，2 寸是俗称不是实测值。逐档外径数值以现行标准与技术部门核定为准。","multi":false},{"id":"C33-Q02","courseId":"C33","type":"单选","stem":"【冲突条件】图纸要求领一批“DN50”的衬塑管。新员工拿卡尺量了一根管子的内径，发现是53mm，他抱怨说“尺寸不对，图纸要50的”。他错在哪里？","options":{"A":"确实拿错了，内径不够","B":"他应该去量管子的长度","C":"没拿错，DN是公称直径（名义尺寸），且钢管类口径应量外径，DN50对应的外径通常约为Φ60mm","D":"他用的是厘米尺"},"answer":["C"],"explain":"对应【口径换算】。钢管与衬塑管的DN是名义尺寸，绝不等于内径。DN50的管子，外径（Φ）通常是60mm。拿卡尺量内径去对DN，是新手最容易犯的低级错误。","multi":false},{"id":"C33-Q03","courseId":"C33","type":"多选","stem":"【冲突条件】现场施工，工人为了图快，想用普通电焊直接给衬塑管点焊固定，并拿来了高速砂轮切割机准备切管。你作为材料员，必须制止他的哪些违规行为？","options":{"A":"电焊高温会烧毁内衬塑料，导致钢塑离层","B":"高速砂轮切割机摩擦生热，会导致管口内衬碳化","C":"必须改用低速割管机或手工锯进行冷切割","D":"管子太长了，必须电焊截断"},"answer":["A","B","C"],"explain":"对应【施工底线】。衬塑管严禁动火（电焊、气割）和高温切割，高温是破坏塑料衬层的头号杀手。","multi":true},{"id":"C35-Q01","courseId":"C35","type":"单选","stem":"料场有一根6m直的黑色管子，管身有一条蓝色标识线，材质为塑料。按本课外观初筛，应先判断为哪类管材？","options":{"A":"PE给水管","B":"球墨铸铁管","C":"衬塑复合管","D":"直缝焊接钢管"},"answer":["A"],"explain":"调用【PE与PPR】。黑管蓝线、6m定尺直管是PE给水管典型外观；球铁粗重内水泥，衬塑外钢内塑，钢管有焊缝防腐层。 另见本课【管材颜色标线与材质代号速查】逐档 / 逐类核对，标准数值以现行标准与技术部门核定为准。","multi":false},{"id":"C35-Q02","courseId":"C35","type":"单选","stem":"新员工看到一根外表像镀锌钢管、内壁却有白色塑料层的管子，把它当纯钢管准备电焊。按本课应怎样解释？","options":{"A":"这是衬塑复合管，外钢内塑，严禁电焊气割","B":"外表像钢管就是纯钢管","C":"这是PE管","D":"这是球铁管"},"answer":["A"],"explain":"调用【衬塑与钢管】。外钢内塑是衬塑复合管；高温会烧毁内衬，不能按纯钢管电焊。","multi":false},{"id":"C35-Q03","courseId":"C35","type":"单选","stem":"库房来了一根外表沥青黑、掂着很压手的粗管，敲开内壁看到一层水泥砂浆衬。按本课外观初筛，它应归为哪类？","options":{"A":"PPR给水管","B":"衬塑复合管","C":"直缝焊接钢管","D":"球墨铸铁管"},"answer":["D"],"explain":"调用【球铁识别】。沥青黑、粗重、内壁水泥衬、刚性直管、掂着压手、内壁水泥衬是球墨铸铁管的典型外观；PE黑管蓝线、PPR绿白直管、衬塑外钢内塑、钢管带焊缝防腐，均不符。","multi":false},{"id":"C36-Q01","courseId":"C36","type":"单选","stem":"库房里一只阀门没有手轮，两端法兰，内部靠水流推阀瓣启闭。按本课外观速记，应先归为哪类？","options":{"A":"闸阀","B":"蝶阀","C":"止回阀","D":"排气阀"},"answer":["C"],"explain":"调用【球阀与止回阀】。止回阀无手轮，靠阀瓣单向启闭；闸阀蝶阀球阀通常有手轮或手柄。","multi":false},{"id":"C36-Q02","courseId":"C36","type":"单选","stem":"一只阀门阀体扁圆，内部蝶板旋转90度启闭。它最符合本课哪类外形？","options":{"A":"闸阀","B":"止回阀","C":"球阀","D":"蝶阀"},"answer":["D"],"explain":"调用【闸阀与蝶阀】。蝶阀扁圆、蝶板旋转90度；闸阀像小房子升降闸板。","multi":false},{"id":"C36-Q03","courseId":"C36","type":"单选","stem":"一只阀门阀体很短，侧面一个手柄与管子平行时水流通、拧成垂直就关断，里面是个带孔的球。它最符合本课哪类外形？","options":{"A":"闸阀","B":"止回阀","C":"球阀","D":"蝶阀"},"answer":["C"],"explain":"调用【球阀外形】。短阀体、手柄方向即开关、内部带孔球转90度是球阀；闸阀像小房子、蝶阀扁圆蝶板、止回阀无手轮。","multi":false},{"id":"C37-Q01","courseId":"C37","type":"单选","stem":"库房料架上有一片平圆形橡胶件，准备夹在两片法兰之间。它应归为本课哪类辅材？","options":{"A":"胶垫","B":"胶圈","C":"生料带","D":"压力表弯"},"answer":["A"],"explain":"调用【胶垫与胶圈】。平圆片夹法兰是胶垫；环形厚圈塞承口是胶圈。","multi":false},{"id":"C37-Q02","courseId":"C37","type":"单选","stem":"工人拿了一根O形弯管准备装在压力表前，说这是普通管道弯头。按本课应怎样纠正？","options":{"A":"普通弯头也能缓冲","B":"这是螺栓","C":"这是胶圈","D":"这是压力表弯，用来缓冲压力脉动和保护压力表"},"answer":["D"],"explain":"调用【螺栓与压力表弯】。压力表弯是缓冲冷凝件，不是普通改向弯头。","multi":false},{"id":"C37-Q03","courseId":"C37","type":"单选","stem":"库房一筐环形厚圈，准备塞进球墨管承口的凹槽里做密封。它应归为本课哪类辅材？","options":{"A":"胶垫","B":"压力表弯","C":"生料带","D":"胶圈"},"answer":["D"],"explain":"调用【胶垫与胶圈】。环形厚圈塞承口槽是胶圈；平圆片夹法兰才是胶垫，两者位置不同不能混拿。","multi":false},{"id":"C53-Q01","courseId":"C53","type":"单选","stem":"现场看到一只圆形井盖，表面铸有“给水”字样，下面有井座。按本课应首先识别为什么设施？","options":{"A":"普通盖板","B":"给水功能井盖","C":"地上式消火栓","D":"不锈钢户表控制箱"},"answer":["B"],"explain":"调用【井盖与井座】【功能标识】。有“给水”字样和井座的是功能井盖，不是普通盖板；消火栓和户表箱是另外设施。","multi":false},{"id":"C53-Q02","courseId":"C53","type":"多选","stem":"下列哪些属于本课讲的作业现场安全设施或标识？","options":{"A":"带“给水/消防”字样的井盖","B":"锥桶、围栏、警示带","C":"安全帽和反光衣","D":"管道压力表读数"},"answer":["A","B","C"],"explain":"调用【井盖与井座】【围挡警示】【PPE】。压力表读数是运行参数，不是本课安全设施；A、B、C分别对应井盖、围挡和PPE。","multi":true},{"id":"C53-Q03","courseId":"C53","type":"单选","stem":"安全帽的正确佩戴方式是？","options":{"A":"扣在头上不系下颚带","B":"戴正并系好下颚带","C":"挂在工具袋上","D":"用反光衣代替"},"answer":["B"],"explain":"调用【PPE】。不系下颚带碰撞时易脱落；反光衣不能代替安全帽，安全帽也不能挂起来。","multi":false},{"id":"C57-Q01","courseId":"C57","type":"单选","stem":"材料验收五道关卡中，哪一关专门核对标准号与公司现用状态？","options":{"A":"单据与卡面映射","B":"外观与标识","C":"标准与状态","D":"包装与批次"},"answer":["C"],"explain":"调用【标准与状态要一起核】。标准号是验收依据，状态栏决定能否进现用区；单据、外观、包装各管一段。","multi":false},{"id":"C57-Q02","courseId":"C57","type":"多选","stem":"下列哪些属于本课讲的现场可量项？","options":{"A":"PE 管外径 De","B":"球墨铸铁管承插端头","C":"阀门阀杆与端头","D":"材料卡上的公司现用状态"},"answer":["A","B","C"],"explain":"调用【规格可量项要认体系】。De、承插端头、阀杆端头可看可量；公司现用状态是卡面栏，不是量项。","multi":true},{"id":"C57-Q03","courseId":"C57","type":"排序题","stem":"材料验收五道关卡的判断顺序，下列哪一项正确？","options":{"A":"单据与卡面→外观标识→规格尺寸→标准状态→包装批次","B":"外观标识→单据与卡面→标准状态→规格尺寸→包装批次","C":"标准状态→单据与卡面→外观标识→规格尺寸→包装批次","D":"包装批次→外观标识→单据与卡面→规格尺寸→标准状态"},"answer":["A"],"explain":"调用【五道关卡先立框架】。先对单据与卡面，再看外观标识，再量规格尺寸，再核标准状态，最后查包装批次与留痕；顺序倒置会先量后核。","multi":false},{"id":"C95-Q01","courseId":"C95","type":"单选","stem":"下列哪项不属于管网日常巡检的五大缺陷大类？","options":{"A":"管材类缺陷","B":"阀门管件类缺陷","C":"人员考勤类","D":"附属设施类缺陷"},"answer":["C"],"explain":"调用【五大缺陷大类】。巡检缺陷分为管材类、阀门管件类、仪表类、附属设施类、安全环境类，人员考勤不属于巡检缺陷范畴。","multi":false},{"id":"C95-Q02","courseId":"C95","type":"辨析题","stem":"“巡检发现缺陷拍个照发群里就行，不用正式上报。”这种说法是否正确？","options":{"A":"正确，大家看到就行","B":"错误，必须按流程记录上报并跟进闭环","C":"正确，小事不用走流程","D":"错误，应该直接自己处理"},"answer":["B"],"explain":"调用【巡检基本流程】。巡检必须按“观察-取证-上报-闭环”四步执行，仅拍照发群不形成正式记录和跟进闭环，属于不规范操作。","multi":false},{"id":"C95-Q03","courseId":"C95","type":"排序题","stem":"管网日常巡检的标准作业流程，排序正确的是？","options":{"A":"记录取证→现场观察→分级上报→跟进闭环","B":"现场观察→记录取证→分级上报→跟进闭环","C":"分级上报→现场观察→记录取证→跟进闭环","D":"现场观察→分级上报→记录取证→跟进闭环"},"answer":["B"],"explain":"调用【巡检基本流程】。正确流程为：先现场观察发现问题，再记录取证固定信息，随后按等级上报，最后跟进整改形成闭环，顺序颠倒会导致信息缺失、追溯困难。","multi":false},{"id":"C74-Q01","courseId":"C74","type":"单选","stem":"库房规划库位时，以下哪项不属于三大核心原则","options":{"A":"重下轻上","B":"先进先出","C":"就近存放","D":""},"answer":["C"],"explain":"调用【库位规划三大原则】知识块。库位三原则为重下轻上、先进先出、异质隔离；“就近存放” 是效率习惯，并非核心原则，反而可能造成异质混放的风险。A、B 均为核心原则，C 不符合。","multi":false},{"id":"C74-Q02","courseId":"C74","type":"单选","stem":"以下哪类物料必须存放于物理隔离的呆滞隔离区","options":{"A":"刚到货未验收的新料","B":"超期待复检的胶圈","C":"常用现用 PE 管件","D":""},"answer":["B"],"explain":"调用【库区功能四分区】知识块。超期待检物料属于呆滞料范畴，必须放入隔离区；新料对应待检区，常用料对应合格品区。A 属于待检区物料，C 属于合格品区物料，B 属于呆滞物料。","multi":false},{"id":"C74-Q03","courseId":"C74","type":"辨析题","stem":"日常养护只需要管好物料本身，库区环境和通道不需要重点关注。","options":{"A":"正确，物料完好才是核心","B":"错误，温湿度、通道畅通都是养护的一部分","C":"错误，通道应该堆满物料提高利用率","D":""},"answer":["B"],"explain":"调用【养护总纲三维度】知识块。养护不仅管物料，还要管控温湿度、光照、污染物等环境因素，作业通道必须畅通，既是效率要求也是安全要求。A 忽略了环境管控，C 属于违规堆码，B 表述正确。","multi":false},{"id":"C84-Q01","courseId":"C84","type":"单选","stem":"以下哪项不属于领退料管理的四大核心原则","options":{"A":"凭单发料","B":"先进先出","C":"就近快拿","D":"合规替代"},"answer":["C"],"explain":"领退料有四条核心原则，你记住凭单发料、先进先出、合规替代、分级审批这四条，就有了判断的尺子。“就近快拿”图的是省事，却会打乱先进先出、绕过合规管理，算不上原则。A、B、D 都在四条原则里，只有 C 不属于，所以选 C。这正对应本课讲的核心原则，照这四条去对照就不会选错。","multi":false},{"id":"C84-Q02","courseId":"C84","type":"多选","stem":"领退料业务覆盖的核心物料类别包括","options":{"A":"管材管件类","B":"阀门水表类","C":"辅材类","D":"办公文具类"},"answer":["A","B","C"],"explain":"领退料覆盖的是生产物料，你按管材、管件、阀门、水表、辅材五大类去认，A 管材管件、B 阀门水表、C 辅材都落在其中。办公文具属于办公用品，不在生产物料领退范围里，所以 D 不属于。记住这五大类，就是本课讲的核心物料范围，照着数一遍就不会多选。","multi":true},{"id":"C84-Q03","courseId":"C84","type":"辨析题","stem":"抢修领料比较紧急，可以不用单据，先把料拿走再说。","options":{"A":"正确，抢修优先，效率最重要","B":"错误，抢修也要走合规流程，应急情况事后必须补单","C":"错误，抢修必须等审批完才能发料","D":"—"},"answer":["B"],"explain":"抢修领料确实效率优先，但再急也不能突破合规底线。你可以先发料，前提是登记清楚领用人、事由、数量，并在工作日内补齐手续，责任也要落到人。A 把“先把料拿走再说”当成理由，等于突破底线；C 非要等审批完才发料，在真正的应急场景里过于僵化。B 既保效率又守规矩，表述最准确。这对应本课讲的三大场景规则：场景不同、优先级不同，但底线不能变。","multi":false},{"id":"C90-Q01","courseId":"C90","type":"单选","stem":"下列关于盘点主体权责的说法，正确的是？","options":{"A":"监盘人员负责替代仓管员完成自盘","B":"自盘由仓管员对管辖库区自主盘点，对结果负责","C":"交叉盘属于自盘的一种形式","D":"复盘只由财务人员独立完成"},"answer":["B"],"explain":"自盘是仓管员本职工作，对盘点结果负直接责任；他盘含交叉盘、监盘、复盘，核心作用是校验监督，不能替代自盘责任。","multi":false},{"id":"C90-Q02","courseId":"C90","type":"辨析题","stem":"“日常动碰盘只需要盘点当天入库的物料，出库物料无需复盘。” 这种说法是否正确？","options":{"A":"正确，入库才会影响库存","B":"错误，当日所有发生出入库变动的物料都需复盘","C":"正确，出库有单据不会错","D":"错误，动碰盘需要全盘所有物料"},"answer":["B"],"explain":"日常动碰盘针对当日所有发生出入库记录的物料逐一复盘，确保动过的物料账实一致，并非只盘点入库项。","multi":false},{"id":"C90-Q03","courseId":"C90","type":"排序题","stem":"盘点工作的完整执行流程，下列排序正确的是？","options":{"A":"盘中作业→盘点前准备→盘后核对→差异处置→闭环整改","B":"盘点前准备→盘中作业→盘后核对→差异处置→闭环整改","C":"盘点前准备→差异处置→盘中作业→盘后核对→闭环整改","D":"盘后核对→盘点前准备→盘中作业→闭环整改→差异处置"},"answer":["B"],"explain":"完整盘点链路为：准备→盘中作业→盘后核对→差异处置→整改闭环，顺序倒置会导致漏项、效率低下、结果失真。","multi":false},{"id":"C01-Q01","courseId":"C01","type":"单选","stem":"新员工在料场看到一根6m直的黑色管子，管身上有一条蓝色的线，材质是硬塑料。他应该判断这是什么管材？","options":{"A":"球墨铸铁管","B":"衬塑复合管","C":"钢管","D":"PE给水管"},"answer":["D"],"explain":"对应课程【外观特征】。PE给水管最典型的外观就是黑色管身加蓝色标识线的6m直管；球墨铸铁管是直管且内壁有灰白水泥。","multi":false},{"id":"C01-Q02","courseId":"C01","type":"多选","stem":"到货一批 PE100 给水管，单子写「DN100 SDR11 PN1.6MPa」。按本课【SDR / PN / 壁厚 对照表】，下列判断正确的是？","options":{"A":"SDR11 是外径÷壁厚的比值，数值小意味着管壁较厚","B":"PN1.6MPa 是公称压力，和 DN、SDR 分属不同坐标，不能混算","C":"同外径下 SDR11 比 SDR17 更扛压，可用于更高压力段","D":"只要印着 PE100，壁厚和承压都不用再核"},"answer":["A","B","C"],"explain":"对应课程【SDR / PN / 壁厚 对照表：怎么查】【承压指标：PN与SDR】。SDR 是外径÷壁厚、数值越小壁越厚越扛压；PN 是公称压力，与口径、壁厚是三组坐标。D 错在只看材质不看 SDR 与 PN，高压段错用薄壁管必爆。逐档对应值以现行标准与技术部门核定为准。","multi":true},{"id":"C01-Q03","courseId":"C01","type":"单选","stem":"【冲突条件】夏天工地，工人把一根6m直PE管拆了包装直接暴晒在太阳下，说“晒软了正好方便热熔”。你作为巡检员应该怎么做？","options":{"A":"觉得有道理，晒软了确实好干活","B":"向领导打小报告","C":"不理他，这不归你管","D":"立即制止并要求盖遮阳布，紫外线会加速PE管老化变脆，日后必爆管"},"answer":["D"],"explain":"对应课程【存放禁忌：紫外线】。PE管极度怕暴晒，紫外线会让塑料分子链断裂变脆。工人的借口是偷懒，坑在毁坏材料寿命。","multi":false},{"id":"C02-Q01","courseId":"C02","type":"单选","stem":"【冲突条件】现场需要把一根PE管接到一个铸铁法兰阀门上。施工员让你领个三通，说“拿铁丝缠紧塞进去就行”。你应该领什么？","options":{"A":"领法兰头/片（一端热熔一端法兰盘）","B":"听施工员的，领三通","C":"领大号生料带","D":"领电焊机"},"answer":["A"],"explain":"对应课程【跨材质转换】。PE管不能直接硬塞或焊接在铁阀门上，必须用法兰头/片进行跨材质连接。","multi":false},{"id":"C02-Q02","courseId":"C02","type":"单选","stem":"【冲突条件】工人拿了一个黑色的PE平口弯头，想让你拿点生料带去给他缠上。你该怎么做？","options":{"A":"给他生料带","B":"用铁丝绑","C":"用胶水粘","D":"拒绝，纯PE平口件没有螺纹，必须用热熔机烫软对接，生料带没用"},"answer":["D"],"explain":"对应课程【基础形状件与防呆辨识法】。平口件全靠热熔，生料带只适用于有螺纹（如内外丝直接）的管件。","multi":false},{"id":"C02-Q03","courseId":"C02","type":"单选","stem":"【冲突条件】一段PE支管暂时不用，预留着以后接阀门。工人说“拿胶带缠住管口就行”。你该怎么做？","options":{"A":"熔接一个PE管帽（堵头）封住管口","B":"听工人的，用胶带缠","C":"塞个木塞","D":"不用管，敞着就行"},"answer":["A"],"explain":"对应课程【封堵收尾：PE管帽】。临时口、预留口必须熔接管帽封死，防杂物进水、避免误接；胶带木塞都不可靠。","multi":false},{"id":"C04-Q01","courseId":"C04","type":"单选","stem":"【冲突条件】施工员看管身上印着“K9”，库房却给他发了印着“K8”的管子，他说“K8数字小，肯定更轻、承压更高，你发错了”。他说的对吗？","options":{"A":"不对，K代表壁厚等级，K9比K8壁厚更大、承压能力更强，用K8替代K9存在爆管风险","B":"对，K8比K9高级","C":"只要口径对，K几无所谓","D":"K是厂家随便印的"},"answer":["A"],"explain":"对应课程【壁厚等级：K9与K8】。K代表管壁厚度，数字越大壁越厚承压越高。压力管道错用薄壁管极易爆裂。","multi":false},{"id":"C04-Q02","courseId":"C04","type":"多选","stem":"【冲突条件】货车卸下一批球墨铸铁直管，作为库管员进行入库验收，下列检查项正确的是？","options":{"A":"检查内壁的水泥内衬，不能有大面积空鼓或脱落","B":"检查外壁的锌加沥青，不能有钢丝绳勒痕或破损","C":"检查承口内部的胶圈槽，不能磕碰变形","D":"看管身喷码印着K8，图纸要求K9，直接签收装车"},"answer":["A","B","C"],"explain":"对应课程【防腐体系/承插接口/壁厚等级】。D选项错误，K8壁厚薄于K9，不能擅自降级替代，必须拒收或换货。","multi":true},{"id":"C04-Q03","courseId":"C04","type":"单选","stem":"【冲突条件】管沟里准备插管，工人拿了T型橡胶圈，却发现承口外面配了一堆法兰压兰和螺栓。为什么装不上？","options":{"A":"T型胶圈比K型厚，塞不进","B":"工人拿错管件了","C":"T型是推入式，靠插口硬顶进去；带压兰和螺栓的是K型机械式胶圈","D":"用锤子硬砸进去"},"answer":["C"],"explain":"对应课程【胶圈分T型与K型】。T型推入即可；K型必须依靠压兰和螺栓挤压。看到压兰，就应该找K型胶圈。","multi":false},{"id":"C07-Q01","courseId":"C07","type":"单选","stem":"新员工看到一根钢管，发现焊缝像弹簧一样绕着管子转圈。根据课程，这属于什么管？它在管网中常用于什么场景？","options":{"A":"直缝管，用于室内水龙头","B":"无缝管，用于高压化肥","C":"螺旋缝管，常用于大口径长距离输水或主干管","D":"铸铁管，用于下水道"},"answer":["C"],"explain":"对应课程【外观与分类】。焊缝呈螺旋状的是螺旋缝焊接钢管，可以做得很大，用于大流量主干线；直缝管焊缝是一条直线。","multi":false},{"id":"C07-Q02","courseId":"C07","type":"多选","stem":"【冲突条件】库房到货一批外防腐为3PE的螺旋钢管，吊车司机正准备用细钢丝绳直接起吊，被你拦下。关于钢管防腐，下列说法正确的是？","options":{"A":"内防腐有环氧或水泥，外防腐有3PE","B":"3PE防腐层能防土壤腐蚀，但不能被破坏","C":"钢丝绳硬勒破了防腐层，时间长了钢管会烂穿","D":"钢管比铁硬，防腐层破了没影响"},"answer":["A","B","C"],"explain":"对应课程【防腐体系】。D错误，钢管极怕腐蚀，防腐层就是它的保命衣，一旦勒破，在潮湿土壤中会迅速生锈烂穿。","multi":true},{"id":"C07-Q03","courseId":"C07","type":"单选","stem":"【冲突条件】图纸要求一段过河架空管线，且压力极高。施工员嫌钢管重，想申请换成PE管，说“PE管也抗压”。你应该怎么说服他？","options":{"A":"听施工员的，换PE","B":"换成球墨铸铁管","C":"可以，能省力","D":"制止，过河架空或高压水锤工况必须用钢管，因为钢管能扛住极高的压力，塑料管会爆"},"answer":["D"],"explain":"对应课程【高压与大流量的担当】。钢管抗拉抗压强度远高于塑料管，在水泵出口的高压或过河架空等复杂工况下，钢管是唯一选择。","multi":false},{"id":"C10-Q01","courseId":"C10","type":"单选","stem":"新员工在楼道看到一根绿色的直管，管身印着红线，标识为S2.5。根据课程，这通常是什么管，适合干嘛？","options":{"A":"PPR给水管，S2.5壁厚较厚，适合室内热水管","B":"PE给水管，适合室外埋地","C":"球墨铸铁管，适合高压主干","D":"钢管，适合泵房"},"answer":["A"],"explain":"对应课程【外观特征/承压规格】。PPR是绿/白直管，S系列数值越小壁越厚，S2.5常用于热水。","multi":false},{"id":"C10-Q02","courseId":"C10","type":"多选","stem":"【冲突条件】施工员要把一根白色的PPR管用在室外露天接临时水管，且夏季阳光暴晒，水温很高。作为材料员，下列判断正确的是？","options":{"A":"PPR管耐热，夏天这点温度没问题","B":"PPR极度怕紫外线，露天暴晒会迅速老化变脆","C":"长期水温若超过70度，PPR管会变软变形，不能用于高温主干","D":"必须确认管材的S系列，如果用薄壁管风险极大"},"answer":["B","C","D"],"explain":"对应课程【材质特性/温度边界/承压规格】。A错误。PPR怕晒且不耐超高温，不能当室外露天高温管长期用。","multi":true},{"id":"C10-Q03","courseId":"C10","type":"单选","stem":"【冲突条件】图纸要求做室内热水支管，工人图便宜想领S5的管子，说“反正都是PPR，能通水就行”。这有什么隐患？","options":{"A":"S5管壁薄，承压等级低，通热水后承压能力骤降，极易爆管","B":"没隐患，都是PPR","C":"S5壁厚太厚，水流量小","D":"S5容易结垢"},"answer":["A"],"explain":"对应课程【承压规格】。S5数值大，管壁薄，通常用于冷水。热水受热后管子更软，用薄壁管极易在压力下爆裂。","multi":false},{"id":"C11-Q01","courseId":"C11","type":"单选","stem":"【冲突条件】工人在安装淋浴混水阀，拿了一个光秃秃的PPR平口弯头，准备缠点生料带拧进混水阀。这能装上吗？","options":{"A":"能，生料带万能","B":"能，拿锤子硬砸进去","C":"装不上，平口件是热熔的，必须用带金属螺纹的PPR内丝或外丝直接才能拧进金属设备","D":"装不上，得用电焊"},"answer":["C"],"explain":"对应课程【铜嵌件件】。PPR连金属设备必须通过带铜嵌件的丝扣件，平口件无法拧入。","multi":false},{"id":"C11-Q02","courseId":"C11","type":"单选","stem":"【冲突条件】户内某处水龙头坏了需要更换，但龙头前面的PPR管子是直接热熔死在上面的。如果当初施工时用哪种管件，现在换龙头就不用重新热熔管子了？","options":{"A":"PPR三通","B":"PPR管帽","C":"PPR活接头","D":"PPR法兰"},"answer":["C"],"explain":"对应课程【可拆连接：PPR活接头】。活接头带大螺母，拧开就能断开管路更换设备，无需剪管。","multi":false},{"id":"C11-Q03","courseId":"C11","type":"多选","stem":"【冲突条件】库房到货一批带铜牙的PPR管件，作为验收员，下列检查点正确的是？","options":{"A":"检查铜嵌件与塑料的结合处是否有裂缝","B":"检查铜螺纹是否顺滑，有无毛刺","C":"确认是否配套了活接头的平垫片","D":"铜件必须全是不锈钢材质"},"answer":["A","B","C"],"explain":"对应课程【铜嵌件件/活接头】。D错误，铜件就是黄铜，不需要是不锈钢。结合处裂缝和毛刺是漏水隐患，垫片是活接必备。","multi":true},{"id":"C13-Q01","courseId":"C13","type":"单选","stem":"库房到货一批衬塑复合管，工人拿起来准备用普通高速砂轮切割机切断，被库管员制止。为什么不能用普通砂轮切割？","options":{"A":"砂轮切不动钢管","B":"砂轮切割灰尘太大","C":"高速砂轮切割产生的瞬时高温会使内衬碳化，破坏钢塑界面造成离层","D":"必须要用气割"},"answer":["C"],"explain":"对应课程【施工禁忌：内衬是命门】。高温不仅烫坏内衬，更会导致钢塑离层。必须用低速割管机或手工锯。","multi":false},{"id":"C13-Q02","courseId":"C13","type":"多选","stem":"【冲突条件】现场需要将两段衬塑复合管连接起来。施工员问你需要准备什么工具和工艺。下列说法正确的是？","options":{"A":"如果是小口径，可以使用丝扣连接，记得缠生料带","B":"如果是大口径，可以现场用电焊直接焊死","C":"大口径可以用沟槽卡箍连接，无需焊接","D":"严禁使用气割，因为气割会直接烧毁内衬塑料"},"answer":["A","C","D"],"explain":"对应课程【连接方式概览/施工禁忌】。B错误，衬塑管严禁电焊，高温会烧毁内衬。","multi":true},{"id":"C13-Q03","courseId":"C13","type":"单选","stem":"一段衬塑管需要接到水泵上，施工员为了省事，把普通碳钢法兰直接焊在了衬塑管端头，试水时法兰面漏水，且管内流出黑色杂质。原因最可能是？","options":{"A":"水泵压力太大","B":"螺栓没拧紧","C":"普通法兰不匹配","D":"焊接高温破坏了管口内衬，导致钢塑离层脱落，且未加橡胶垫片"},"answer":["D"],"explain":"对应课程【衬塑法兰/施工禁忌】。不能用普通钢法兰焊死代替衬塑法兰，焊接高温会毁坏防腐层并导致漏水。","multi":false},{"id":"C14-Q01","courseId":"C14","type":"单选","stem":"【冲突条件】工人拿了一个补芯准备变径，看外观一头是外丝，一头是内丝。他问你外丝应该朝哪边拧？","options":{"A":"补芯的外丝侧朝大径端，拧进大管件的内丝里；内丝侧朝小径端","B":"外丝朝阀门，内丝朝管子","C":"随便拧哪头","D":"外丝朝上，内丝朝下"},"answer":["A"],"explain":"对应课程【变径转换：大小头与补芯】。补芯外丝旋入大管件内丝，内丝接纳小管外丝，这样才能实现正确的变径过渡。","multi":false},{"id":"C14-Q02","courseId":"C14","type":"多选","stem":"【冲突条件】库房到货一批丝接弯头，库管员核对型号无误后准备入库。下列哪些是必须要检查的项？","options":{"A":"检查内壁的塑料衬层有没有脱落、鼓包","B":"检查丝扣（螺纹）是否规整，有无断丝","C":"检查外表面镀锌层是否大面积剥落生锈","D":"用锤子敲击，看能不能砸出坑"},"answer":["A","B","C"],"explain":"对应课程【基础形状/执行标准】。D错误，丝接件多为玛钢或铸件，用锤砸容易碎裂。","multi":true},{"id":"C18-Q01","courseId":"C18","type":"单选","stem":"【冲突条件】新员工在装Y型过滤器时，看到滤网在一边，为了好看，把滤网那一侧朝上装了。通水后，流量越来越小。为什么？","options":{"A":"滤网破了","B":"水压不够","C":"滤网必须朝下。装反或朝上会导致杂质堆积在滤网上方，无法沉底，直接把通道堵死","D":"生料带缠多了"},"answer":["C"],"explain":"对应课程【安装方向】。滤网朝下，利用水流重力和向下的空间，让杂质沉底；朝上会很快堵死。","multi":false},{"id":"C18-Q02","courseId":"C18","type":"多选","stem":"【冲突条件】巡检时发现某段管路水压变小，怀疑是Y型过滤器堵了。下列处理方式正确的是？","options":{"A":"拧开底部的排污堵头，冲排杂质","B":"如果排不干净，关阀后拆开端盖，取出滤网刷洗","C":"直接把整个过滤器锯掉，说这东西没用","D":"检查滤网有没有破洞，破了就换"},"answer":["A","B","D"],"explain":"对应课程【清理维护】。C错误，过滤器是保护水表和阀门的必备件，绝对不能拆除。","multi":true},{"id":"C19-Q01","courseId":"C19","type":"单选","stem":"【冲突条件】泵房的高压出口管线需要使用蝶阀。工人领来了一批中线软密封蝶阀，班长要求必须换成偏心金属硬密封蝶阀。为什么？","options":{"A":"软密封太贵了","B":"软密封太大了","C":"硬密封便宜","D":"中线软密封靠橡胶挤压密封，在高压大口径工况下，橡胶极易磨损，且偏心硬密封开启不摩擦"},"answer":["D"],"explain":"对应课程【偏心结构】。高压下必须用硬密封；且偏心结构解决的是启闭摩擦问题，寿命更长。","multi":false},{"id":"C19-Q02","courseId":"C19","type":"多选","stem":"【冲突条件】自动化改造要求对管网进行远程监控和启闭，你领来了一批电动蝶阀。关于这种阀，下列说法正确的是？","options":{"A":"带电机和执行器，能接收电脑信号自动开闭","B":"断电时可切换为手动摇柄操作","C":"必须水平安装，不能倾斜","D":"安装时需要看水流方向"},"answer":["A","B","D"],"explain":"对应课程【电动蝶阀】。C错误，电动蝶阀可多角度安装（除倒装），但安装必须看箭头方向。","multi":true},{"id":"C20-Q01","courseId":"C20","type":"单选","stem":"【冲突条件】DN300的高压供水主干线上要装一个截断阀。工人去库房搬了一个浮动球阀，结果转手轮时根本拧不动。应该换什么？","options":{"A":"应该换成固定球阀。大口径高压下，浮动球阀的球体会被死死压住，扭矩极大，固定球阀带轴承才转得动","B":"换个大号管钳硬拧","C":"换蝶阀","D":"加润滑油"},"answer":["A"],"explain":"对应课程【固定球阀】。浮动球阀只适合DN200以下中低压，大口径高压必须用固定球阀。","multi":false},{"id":"C20-Q02","courseId":"C20","type":"单选","stem":"【冲突条件】小区户内水表前的小管子需要换阀门。工人领了一个带法兰的铸铁阀门，发现根本装不上。应该换什么？","options":{"A":"黄铜内螺纹浮动球阀。户内小口径通常没有法兰空间，必须用螺纹连接","B":"听施工员的，拿三通","C":"用胶水粘","D":"用电焊焊死"},"answer":["A"],"explain":"对应课程【黄铜与三通】。DN50以下户内首选黄铜内螺纹球阀，小巧且螺纹连接。","multi":false},{"id":"C24-Q01","courseId":"C24","type":"单选","stem":"【冲突条件】一段长距离输水管线，刚通水时，空气被压缩在管子里，导致水流走不动。巡检员在管线最高点应该安装什么阀？","options":{"A":"复合式排气阀，大孔能快速排出大量空气，解决气阻","B":"减压阀","C":"闸阀","D":"水表"},"answer":["A"],"explain":"对应课程【排气阀】。排气阀必须装高点，复合式排气阀大孔排气最快。","multi":false},{"id":"C24-Q02","courseId":"C24","type":"多选","stem":"【冲突条件】管线上某处的复合式排气阀小孔一直往外滴水，工人说“这点水无所谓”。这样做会有什么影响？","options":{"A":"小孔漏水可能是内部浮球密封面被泥沙卡住","B":"如果浮球卡死关不严，大孔打开时会导致大量漏水甚至淹井","C":"应该及时拆开清洗或更换","D":"滴水是正常的，不用管"},"answer":["A","B","C"],"explain":"对应课程【排气阀】。排气阀漏水通常是内部浮球或密封面失效，必须维修，绝不能放任不管。","multi":true},{"id":"C30-Q01","courseId":"C30","type":"单选","stem":"【冲突条件】在直管段安装轴向型波纹管补偿器，工人为了好看，把两端的限位拉杆全拆了，说“这样伸缩更自由”。这会带来什么后果？","options":{"A":"拉杆用于承受管内水压产生的盲板推力，拆掉后补偿器会被水压直接拉断或拉飞","B":"没后果，确实更好","C":"补偿器会生锈","D":"水阻变大"},"answer":["A"],"explain":"对应课程【轴向型】。轴向型的拉杆绝不能拆，它是用来平衡盲板推力的限位保护件。","multi":false},{"id":"C30-Q02","courseId":"C30","type":"多选","stem":"【冲突条件】工地挖开一条沟，管子热胀冷缩严重，需要补偿器。关于波纹管补偿器的类型，下列判断正确的是？","options":{"A":"轴向型用于直管段，吸收轴向伸缩","B":"横向型通常用大拉杆，吸收横向位移","C":"铰链型可以单独安装，吸收角向位移","D":"如果管道没对齐，可以用拉杆强行拉过来对口"},"answer":["A","B"],"explain":"对应课程【横向型与铰链型/安装禁忌】。C错误，铰链型必须成组用；D错误，严禁用补偿器强行拉拢对口。","multi":true},{"id":"C30-Q03","courseId":"C30","type":"单选","stem":"安装波纹管补偿器时，发现管道两端错位很大，工人想用拉杆强行把管子拉过来焊上。这会导致什么隐患？","options":{"A":"拉杆会断","B":"法兰会漏水","C":"波纹管在安装前就承受了巨大的初始应力，通水受热后极易在波纹处开裂","D":"没隐患"},"answer":["C"],"explain":"对应课程【安装禁忌】。强行对口会导致补偿器提前疲劳损坏，安装必须保证自然对齐。","multi":false},{"id":"C31-Q01","courseId":"C31","type":"单选","stem":"【冲突条件】泵房里的橡胶接头刚装好，工人嫌那几根带螺母的限位螺栓碍事，把它拧松退到了最外面。水泵一启动，橡胶球被高压水拉得很长。这说明什么？","options":{"A":"水泵压力太大","B":"水泵转太快","C":"橡胶质量不好","D":"限位螺栓的作用就是防拉脱，退到最外面会导致球体过度拉伸"},"answer":["D"],"explain":"对应课程【限位螺栓】。限位螺栓用来平衡水压拉力，必须按厂家要求调好位置，不能随便拧松。","multi":false},{"id":"C31-Q02","courseId":"C31","type":"多选","stem":"【冲突条件】在含有废油的工业污水管上，工人领了一个黑色的橡胶接头准备装上。关于橡胶接头，下列说法正确的是？","options":{"A":"给水橡胶接头默认是EPDM材质","B":"EPDM极怕油，含油污水必须改用NBR材质","C":"安装时应远离电焊作业，防止火花烫坏橡胶","D":"橡胶接头可以替代止回阀使用"},"answer":["A","B","C"],"explain":"对应课程【介质与安装禁忌】。D错误，橡胶接头没有防倒流功能。","multi":true},{"id":"C31-Q03","courseId":"C31","type":"排序题","stem":"【排序题】班组在水泵出口安装可曲挠橡胶接头，请按正确的安装顺序排序：①将橡胶球体法兰与管道法兰对齐 ②对角交替拧紧法兰螺栓 ③穿上限位螺栓 ④按要求调节限位螺栓的螺母位置","options":{"A":"① → ② → ③ → ④","B":"① → ② → ④ → ③","C":"③ → ① → ② → ④","D":"① → ③ → ② → ④"},"answer":["D"],"explain":"对应课程【限位螺栓】。先对准法兰穿上螺栓，拧紧后，再调节限位螺栓防拉脱。","multi":false},{"id":"C25-Q01","courseId":"C25","type":"单选","stem":"【冲突条件】新员工接手了一批黑色的橡胶法兰垫片，看旁边有废机油，顺手就把机油抹在垫片上，说“这样好装还防锈”。这种做法对吗？","options":{"A":"对，机油能润滑","B":"对，可以防止垫片生锈","C":"不对，给水橡胶垫（EPDM）极怕油，抹机油会导致橡胶溶胀、老化，日后必漏水","D":"无所谓"},"answer":["C"],"explain":"对应课程【橡胶密封件】。EPDM材质耐水不耐油。接触机油会破坏其分子结构导致膨胀失效，必须保持干净。","multi":false},{"id":"C25-Q02","courseId":"C25","type":"多选","stem":"【冲突条件】工人在缠生料带准备拧阀门，你觉得他的操作可能有问题。下列关于生料带的正确用法是？","options":{"A":"必须顺螺纹拧紧的方向（顺时针）缠绕","B":"缠的时候可以厚一点，越厚越密封","C":"要留出第一扣螺纹不缠，防碎屑掉进管里","D":"生料带用于法兰对接密封"},"answer":["A","C"],"explain":"对应课程【螺纹密封】。B错误，太厚容易撑裂内丝；D错误，法兰靠橡胶垫，不用生料带。","multi":true},{"id":"C25-Q03","courseId":"C25","type":"单选","stem":"装压力表时，工人嫌麻烦，直接把表拧在管子上，没装压力表弯。这会导致什么后果？","options":{"A":"压力表读数更准","B":"没有影响","C":"节省空间","D":"管网里的水锤冲击或高温会直接损坏表内精密的弹簧管和齿轮"},"answer":["D"],"explain":"对应课程【缓冲附件】。压力表弯起到缓冲脉冲压力和降温的作用，直连容易打坏表盘指针。","multi":false},{"id":"C26-Q01","courseId":"C26","type":"单选","stem":"【冲突条件】泵房安装高压法兰阀门，工人去库房领料，拿了一堆全是螺纹的全丝螺栓（全牙）。班长让他去换半丝螺栓。为什么？","options":{"A":"半丝螺栓有一段光杆，卡在法兰孔里能抗剪切力，全丝螺栓在剪切力下容易断","B":"半丝螺栓比较好看","C":"半丝螺栓便宜","D":"全丝螺栓拧不紧"},"answer":["A"],"explain":"对应课程【紧固件】。法兰对接必须用半丝，利用光杆承受管道横向剪切力，全螺纹螺栓不适合法兰定位。","multi":false},{"id":"C26-Q02","courseId":"C26","type":"多选","stem":"关于压力表的安装与使用，下列做法正确的是？","options":{"A":"压力表必须垂直安装","B":"表前应设置缓冲弯或三通旋塞阀","C":"表盘量程越大越好，方便看","D":"给水管道常用MPa作为压力单位"},"answer":["A","B","D"],"explain":"对应课程【压力表基础】。C错误，量程过大指针偏转角度小，读数不准。","multi":true},{"id":"C26-Q03","courseId":"C26","type":"排序题","stem":"【排序题】班组要进行法兰对接，师傅让你去拿螺栓。请按正确的紧固顺序排序：①将半丝螺栓穿入法兰孔 ②对角交替、分次拧紧螺母 ③检查垫片是否偏心 ④用手带上所有螺母","options":{"A":"② → ① → ③ → ④","B":"① → ③ → ④ → ②","C":"① → ④ → ③ → ②","D":"① → ② → ③ → ④"},"answer":["C"],"explain":"对应课程【紧固件】。步骤：先穿螺栓，手工带上螺母，检查垫片没歪，最后用扳手对角交替拧紧。","multi":false},{"id":"C27-Q01","courseId":"C27","type":"单选","stem":"【冲突条件】某新建小区的消防通道上需要更换一个井盖。库房有复合井盖和球墨铸铁井盖。施工队想用轻便的复合井盖，你应该怎么制止？","options":{"A":"听施工队的，复合的轻","B":"都可以","C":"制止。消防车道有重型车辆碾压，必须使用D400级别的球墨铸铁井盖，复合井盖承压不够会碎裂","D":"拿铁链子锁上就行"},"answer":["C"],"explain":"对应课程【井盖分类】。复合井盖只适合人行道或绿化带。车行道和消防通道必须用球墨铸铁重型井盖。","multi":false},{"id":"C27-Q02","courseId":"C27","type":"多选","stem":"【冲突条件】冬天北方某地，巡检员发现一个室外消火栓被冻裂了。关于消火栓的选用，下列说法正确的是？","options":{"A":"地上式消火栓容易发现，但易冻","B":"严寒地区宜采用地下式消火栓防冻","C":"地下式消火栓需要用专用扳手开盖接水","D":"消火栓接水口不需要管尺寸"},"answer":["A","B","C"],"explain":"对应课程【消火栓】。D错误，消火栓出水口有100mm和65mm等严格标准，必须匹配消防水带。","multi":true},{"id":"C27-Q03","courseId":"C27","type":"单选","stem":"井盖表面铸有“给水”或“消防”字样，主要作用是什么？","options":{"A":"为了美观","B":"为了防滑","C":"防盗","D":"便于巡检人员快速精准地找到对应的阀门井或消火栓井，防止误操作"},"answer":["D"],"explain":"对应课程【功能标识】。不同系统的井盖标识不同，遇到紧急抢修或火警时，能救命。","multi":false},{"id":"C29-Q01","courseId":"C29","type":"单选","stem":"【冲突条件】小区物业新换了一批户表箱，工人抱怨说“这箱子看起来像铁的，怎么这么贵？”你解释说这通常是不锈钢材质，主要有什么好处？","options":{"A":"比较美观","B":"可以当暖气罩","C":"比较轻","D":"强度高、耐腐蚀防潮，使用寿命长，能有效保护内部水表不被破坏"},"answer":["D"],"explain":"对应课程【外观结构】。户表箱多位于楼道或室外，环境潮湿，通常采用不锈钢制作以防锈蚀，保护内部水表和管路。","multi":false},{"id":"C29-Q02","courseId":"C29","type":"多选","stem":"【冲突条件】户表箱内部漏水，你打开箱门检查，发现水是从表前的位置漏出来的。根据课程，户表箱内部包含了哪些主要管件？","options":{"A":"PE分水器，负责将总进水一分为多路","B":"表前阀，用于单独控制每户的进水","C":"黄铜球阀，通常位于箱外顶部作为出水控制","D":"水表以及连接用的活接头"},"answer":["A","B","C","D"],"explain":"对应课程【内部集成】。户表箱是一个高度集成的系统，包含分水器、各户表前阀、水表，顶部接出黄铜球阀。","multi":true},{"id":"C29-Q03","courseId":"C29","type":"单选","stem":"关于户表控制箱的进水口和出水口位置，下列说法正确的是？","options":{"A":"底部通常是PE外丝直接进水，顶部通常是黄铜球阀出水","B":"顶部进水，底部出水","C":"左右两侧进出水","D":"没有固定的进出水口"},"answer":["A"],"explain":"对应课程【外部接口】。从下往上供水的设计有利于排空管内空气，且顶部装黄铜阀方便用户操作。","multi":false},{"id":"C38-Q01","courseId":"C38","type":"单选","stem":"地下阀井很浅，井盖离阀门顶部很近。按本课明暗杆边界，应优先选哪种闸阀？","options":{"A":"暗杆闸阀","B":"明杆闸阀","C":"双盘弯头","D":"止回阀"},"answer":["A"],"explain":"调用【暗杆结构】。暗杆阀杆不升降，省上方空间；明杆开启会伸出，浅井易顶盖。","multi":false},{"id":"C38-Q02","courseId":"C38","type":"单选","stem":"泵房地面明装，巡检要求一眼看出闸阀开度。按本课应优先选哪种？","options":{"A":"暗杆闸阀","B":"中线蝶阀","C":"明杆闸阀","D":"排气阀"},"answer":["C"],"explain":"调用【明杆结构】。明杆阀杆随启闭升降，开度直观；暗杆看不到开度。","multi":false},{"id":"C38-Q03","courseId":"C38","type":"单选","stem":"师傅说『明杆闸阀比暗杆密封更好，所以浅井也该发明杆』。按本课，明暗杆的本质差别是什么？","options":{"A":"明杆密封等级更高","B":"暗杆更防盗","C":"明杆阀杆升降开度直观、暗杆阀杆原地转省空间但看不到开度","D":"暗杆只能用于高压"},"answer":["C"],"explain":"调用【明暗杆不是密封】。明暗杆差别在阀杆是否升降：明杆开度直观但占上方空间，暗杆省空间但看不见开度；二者密封等级、防盗无关，浅井应优先暗杆防顶盖。","multi":false},{"id":"C39-Q01","courseId":"C39","type":"单选","stem":"DN20户内水表，叶轮垂直水流、始动流量小。按本课应归为哪类机械水表？","options":{"A":"水平螺翼机械水表","B":"电磁流量计","C":"旋翼式机械水表","D":"插入式超声波流量计"},"answer":["C"],"explain":"调用【旋翼式】。小口径户用、叶轮垂直水流多为旋翼式；螺翼式多用于DN50以上总管。 另见本课【机械水表按口径分界表】逐档 / 逐类核对，标准数值以现行标准与技术部门核定为准。","multi":false},{"id":"C39-Q02","courseId":"C39","type":"单选","stem":"DN200总管要求大流量低水损，表内叶轮水平轴布置。按本课应归为哪类？","options":{"A":"旋翼式机械水表","B":"水平螺翼机械水表","C":"压力表","D":"复合式排气阀"},"answer":["B"],"explain":"调用【螺翼式】。大口径总管、叶轮水平轴、低水损是螺翼式特征。","multi":false},{"id":"C39-Q03","courseId":"C39","type":"单选","stem":"同一张旋翼式机械水表卡上列了湿式、干式、液封三种。判断一只水表是湿式还是干式、液封，要看什么？","options":{"A":"看表壳大小","B":"看口径 DN","C":"看计数器形式（浸水/磁隔离/液封）","D":"看安装方向"},"answer":["C"],"explain":"调用【湿式干式液封】。湿式、干式、液封是计数器形式，与口径无关；别拿表壳大小或口径去判计数器类型。","multi":false},{"id":"C40-Q01","courseId":"C40","type":"单选","stem":"一只计量设备表体内无叶轮，带一对换能器和显示通信模块。按本课应先归为哪类？","options":{"A":"超声波水表","B":"机械水表","C":"电磁流量计","D":"压力表"},"answer":["A"],"explain":"调用【机械表与超声波水表】。无活动叶轮、带换能器是超声波水表；机械表看叶轮字轮。 另见本课【计量设备口径与用途对照表】逐档 / 逐类核对，标准数值以现行标准与技术部门核定为准。","multi":false},{"id":"C40-Q02","courseId":"C40","type":"单选","stem":"一台流量计有测量管、励磁线圈、电极和转换器，要求介质导电。它属于哪类？","options":{"A":"电磁流量计","B":"超声波水表","C":"旋翼式水表","D":"插入式超声波流量计"},"answer":["A"],"explain":"调用【电磁流量计】。测量管、线圈、电极、转换器是电磁流量计特征，且要求导电流体。","multi":false},{"id":"C40-Q03","courseId":"C40","type":"单选","stem":"一台流量计有主机、一根插入传感器和球阀底座，能在管道带压时开孔装探头做在线监测。它属于哪类？","options":{"A":"电磁流量计","B":"插入式超声波流量计","C":"旋翼式机械水表","D":"超声波水表"},"answer":["B"],"explain":"调用【插入式超声波】。主机+插入传感器+球阀底座、可带压在线监测是插入式超声波流量计；电磁靠电极线圈、机械表有叶轮字轮，均不符。","multi":false},{"id":"C41-Q01","courseId":"C41","type":"单选","stem":"压力表直接拧在管道上，没有表弯。按本课缓冲方向，主要风险是什么？","options":{"A":"读数更准","B":"没有风险","C":"更省空间","D":"水锤和脉动直接冲击弹簧管与机芯"},"answer":["D"],"explain":"调用【直连风险】。表弯形成缓冲容积，直连会让水锤直接打表。","multi":false},{"id":"C41-Q02","courseId":"C41","type":"单选","stem":"压力表弯装在表前，主要起什么作用？","options":{"A":"替代法兰垫片","B":"防倒流","C":"过滤泥沙","D":"形成缓冲容积并让高温介质降温"},"answer":["D"],"explain":"调用【表弯缓冲】。表弯不是过滤器也不是止回阀，作用是缓冲脉动和冷凝降温。","multi":false},{"id":"C41-Q03","courseId":"C41","type":"单选","stem":"巡检发现一只压力表直接拧在管道上，表前没有表弯。按本课【安装初辨】，下列做法正确的是？","options":{"A":"表前不设表弯更省事","B":"表盘随意方向能看见就行","C":"垂直安装、表前设表弯或表阀便于检修断压","D":"表弯可用普通管道弯头代替"},"answer":["C"],"explain":"调用【安装初辨】。压力表应垂直安装，表前设表弯缓冲、设表阀以便不停水摘表校验；表弯不可被普通弯头替代，表盘应朝向操作面。","multi":false},{"id":"C42-Q01","courseId":"C42","type":"单选","stem":"法兰对接时，工人拿全丝螺栓去装法兰，说全丝螺纹更多更结实。按本课应怎样纠正？","options":{"A":"全丝确实更适合法兰","B":"法兰应用半丝，光杆段在法兰孔内抗剪和对中，全丝螺纹处受剪易断","C":"随便哪种都行","D":"应该用生料带"},"answer":["B"],"explain":"调用【法兰为什么用半丝】。半丝光杆参与抗剪；全丝用于管卡支架调节。","multi":false},{"id":"C42-Q02","courseId":"C42","type":"单选","stem":"管卡支架需要任意调节紧固长度，应优先选哪种螺栓？","options":{"A":"全丝螺栓","B":"半丝螺栓","C":"法兰盲板","D":"胶圈"},"answer":["A"],"explain":"调用【全丝为什么用于支架】。全丝全长螺纹，可在任意位置停螺母；法兰才优先半丝。","multi":false},{"id":"C42-Q03","courseId":"C42","type":"单选","stem":"拿起一根螺栓，尾部带螺纹、但头部到螺纹之间有一段光滑杆。它属于哪类？","options":{"A":"全丝螺栓","B":"半丝螺栓","C":"法兰盲板","D":"胶圈"},"answer":["B"],"explain":"调用【半丝全丝外观】。半丝螺栓有一段光杆、仅尾部带螺纹；全丝从头到尾全螺纹。光杆那一段是留着在法兰孔内抗剪对中的，不是没做完。","multi":false},{"id":"C43-Q01","courseId":"C43","type":"单选","stem":"消防车道上的给水阀门井盖，应优先选哪类？","options":{"A":"复合轻型井盖","B":"球墨铸铁D400重型井盖","C":"塑料井盖","D":"木质盖板"},"answer":["B"],"explain":"调用【承载标识】。消防车道有重型车辆，必须用球铁D400重型；复合轻型承载不足。 另见本课【承载等级 × 使用场景 对照表】逐档 / 逐类核对，标准数值以现行标准与技术部门核定为准。","multi":false},{"id":"C43-Q02","courseId":"C43","type":"单选","stem":"绿化带内非车行区域的给水井盖，可优先考虑哪类？","options":{"A":"球铁D400重型","B":"钢法兰","C":"复合轻型井盖","D":"盲板"},"answer":["C"],"explain":"调用【球铁与复合】。绿化带低荷载可用复合轻型；它无回收价值、防盗，但不耐重载。","multi":false},{"id":"C43-Q03","courseId":"C43","type":"单选","stem":"一只井盖上永久印着『给水』字样，但材质轻、承载等级是 A15。按本课应怎样理解？","options":{"A":"印给水就代表能扛消防车","B":"『给水』只是功能字样便于运维找井，不代表承载高","C":"功能字样等于承载等级","D":"印给水就一定比球铁好"},"answer":["B"],"explain":"调用【功能标识与防盗】。『给水』『消防』是永久功能字样，便于运维识别；承载等级另看 D400/A15 等标识，二者是不同字段，不能混为一谈。","multi":false},{"id":"C54-Q01","courseId":"C54","type":"单选","stem":"为什么不能靠探头闻味判断阀门井内是否安全？","options":{"A":"闻不到气味就一定安全","B":"缺氧和有毒气体可能无味，不能靠闻味判断","C":"通风后一定不用检测","D":"检测是多余的"},"answer":["B"],"explain":"调用【为什么不能闻味】【检测作用】。闻不到不等于安全；通风后仍要按作业票检测，检测不是多余。","multi":false},{"id":"C54-Q02","courseId":"C54","type":"多选","stem":"有限空间作业铁律，下列做法正确的是？","options":{"A":"先通风、再检测、后作业","B":"未检测合格不进入","C":"监护人可临时离岗拿工具","D":"单人可以先下井看看"},"answer":["A","B"],"explain":"调用【通风作用】【检测作用】【监护作用】。C错在监护人离岗；D错在单人无监护下井；A、B是铁律。","multi":true},{"id":"C54-Q03","courseId":"C54","type":"辨析题","stem":"有人说“通风完就可以下井，不用检测”。这种说法对不对？","options":{"A":"错，通风不等于检测合格，未检测合格不进入","B":"对，通风已经把气体换掉了","C":"对，只要闻不到味道就行","D":"错，但可以先探头看看"},"answer":["A"],"explain":"调用【通风作用】【检测作用】。通风是稀释置换，不是检测；A、C、D仍把通风或闻味当许可。","multi":false},{"id":"C58-Q01","courseId":"C58","type":"单选","stem":"图纸写 DN100，PE 给水管实物验收应重点读哪个外径标识？","options":{"A":"Φ114","B":"De110","C":"DN50","D":"De63"},"answer":["B"],"explain":"调用【口径体系是 PE 验收重点】。PE 管认外径 De，DN100 常见 De110；Φ114 是钢管外径，别混。","multi":false},{"id":"C58-Q02","courseId":"C58","type":"多选","stem":"PE 管件到货，端头有平口热熔件、带铜色螺纹的内丝直接、一端热熔一端法兰的法兰头。下列关于这三类端头归类的判断，正确的是？","options":{"A":"平口多为热熔件","B":"内丝直接带铜色螺纹","C":"法兰头/片一端热熔一端法兰","D":"管帽两端都是法兰"},"answer":["A","B","C"],"explain":"调用【管件端头分平口与丝口】【法兰与管帽配套核对】。管帽是封堵端，不是两端法兰。","multi":true},{"id":"C58-Q03","courseId":"C58","type":"辨析题","stem":"“PE 法兰头/片可以直接套用钢法兰标准验收。”这种说法对不对？","options":{"A":"对，两者都是法兰","B":"对，只要螺栓孔对上就行","C":"错，PE 法兰头一端是可熔端、一端是法兰盘，不能直接套钢法兰标准","D":"错，但可以按钢法兰压力等级放行"},"answer":["C"],"explain":"调用【法兰与管帽配套核对】。PE 法兰头是塑-金属转换件，标准和端头都不同；套钢法兰标准会错判压力等级。","multi":false},{"id":"C61-Q01","courseId":"C61","type":"单选","stem":"PPR 到货，母管印 S2.5、管件印 S5。按本课【S 系列 ↔ 壁厚 ↔ 承压 对照表】，下面哪项判断正确？","options":{"A":"S5 数字大所以壁更厚，管件比母管扛压","B":"S 系列数字越小壁越厚、越扛压；母管与管件的 S 系列不必相同，要分别对","C":"S2.5 和 S5 是 PE 的 SDR，不能用在 PPR 上","D":"只要 DN 一样，S 系列不同也能混用"},"answer":["B"],"explain":"对应课程【S 系列 ↔ 壁厚 ↔ 承压 对照表】【S 系列看壁厚】。S 系列是 PPR 壁厚系列，数字越小壁越厚；母管本体常见 S2.5/S3.2/S4，S5 多见于管件，验收要分别对。别和 PE 的 SDR 混算；逐档承压对应值以现行标准与技术部门核定为准。","multi":false},{"id":"C61-Q02","courseId":"C61","type":"多选","stem":"PPR 管件到货，端头有两端平口的热熔件、带铜色螺纹的内丝直接、带大螺母的活接头、带法兰盘的法兰转换件。下列端头判断正确的是？","options":{"A":"两端平口多为热熔件","B":"带铜色螺纹是内丝/外丝直接","C":"带大螺母是活接头","D":"带法兰盘是 PPR 法兰（法兰转换）"},"answer":["A","B","C","D"],"explain":"调用【管件端头分三类】【活接与法兰验收】。四类端头分别对应热熔、铜嵌件、活接、法兰。","multi":true},{"id":"C61-Q03","courseId":"C61","type":"辨析题","stem":"“PPR 母管本体常见 S2.5/S3.2/S4，所以现场看到 S5 母管一定是假货。”这种说法对不对？","options":{"A":"错，S5 多见于管件规格，但不能直接判假，要按标识和设计核","B":"对，S5 不是 PPR 规格","C":"对，母管只能有 S2.5/S3.2/S4","D":"错，S5 壁厚一定比 S2.5 厚"},"answer":["A"],"explain":"调用【S 系列看壁厚】。母管本体常见 S2.5/S3.2/S4；S5 见于管件规格，验收不能凭一个 S 值直接判假，要看喷码、标识与设计用途。","multi":false},{"id":"C96-Q01","courseId":"C96","type":"单选","stem":"球墨铸铁管接口渗漏最典型的地面征兆是？","options":{"A":"路面大面积积水","B":"井盖周边持续返潮、井壁有水迹","C":"植被全部枯死","D":"路面出现大量裂纹"},"answer":["B"],"explain":"调用【球墨铸铁管地面征兆】。球墨铸铁管承插接口渗漏会沿井壁渗出，表现为井盖周边持续返潮、井壁流水痕迹；大面积积水多是明漏爆裂，植被枯死不符合渗漏特征。","multi":false},{"id":"C96-Q02","courseId":"C96","type":"多选","stem":"下列属于PE管地面巡检重点关注的隐患有？","options":{"A":"管线正上方地面不均匀沉降","B":"第三方施工机械开挖作业","C":"管身裸露有明显划痕","D":"管线周边植被异常枯黄"},"answer":["A","B","C","D"],"explain":"调用【PE管地面隐患识别】。地面沉降、施工破坏、管身划痕、植被异常枯黄都是PE管渗漏或损伤的地面征兆，均属于巡检重点关注项。","multi":true},{"id":"C96-Q03","courseId":"C96","type":"辨析题","stem":"“路面潮湿就说明地下管道一定漏水了。”这种说法是否正确？","options":{"A":"正确，有水就是漏了","B":"错误，可能是冷凝水、地下水返潮或洒水导致","C":"正确，沿管线走的水肯定是管道漏的","D":"错误，只有下雨天才会路面潮湿"},"answer":["B"],"explain":"调用【常见漏判误区】。路面潮湿的成因很多，冷凝水、地下水渗返、绿化洒水、雨水积水都可能导致，不能直接判定为管道漏水，需逐一排除干扰。","multi":false},{"id":"C97-Q01","courseId":"C97","type":"单选","stem":"下列可曲挠橡胶接头老化的典型表现，不包括哪项？","options":{"A":"表面龟裂、发黏变硬","B":"局部鼓包、偏斜","C":"阀体锈蚀转动困难","D":"法兰边缘渗水"},"answer":["C"],"explain":"调用【柔性接头与密封件老化】。橡胶接头老化表现为裂纹、鼓包、渗漏；阀体锈蚀是金属阀门的缺陷，不属于橡胶接头老化表现。","multi":false},{"id":"C97-Q02","courseId":"C97","type":"辨析题","stem":"“井内有积水，就说明井内管道或阀门一定漏水了。”这种说法是否正确？","options":{"A":"正确，水只能从管道里漏出来","B":"错误，可能是雨水倒灌、地下水渗返","C":"正确，只要有水就是渗漏","D":"错误，井内积水都是人为倒的"},"answer":["B"],"explain":"调用【井内环境异常判断】。井内积水成因多样，雨水倒灌、地下水渗返、管道渗漏都有可能，需要结合水质、天气、渗漏位置综合判断，不能直接归为管道漏水。","multi":false},{"id":"C97-Q03","courseId":"C97","type":"多选","stem":"井内闸阀巡检时，需要重点检查的缺陷有？","options":{"A":"阀体锈蚀程度","B":"阀杆是否卡涩","C":"密封面是否渗漏","D":"手轮是否完好"},"answer":["A","B","C","D"],"explain":"调用【闸阀蝶阀常见缺陷】。阀体锈蚀、阀杆卡涩、密封渗漏、手轮损坏都是闸阀巡检的核心检查项，四项均需重点关注。","multi":true},{"id":"C100-Q01","courseId":"C100","type":"单选","stem":"倒流防止器最核心的巡检红线是？","options":{"A":"阀体有没有灰尘","B":"泄水口是否被污水淹没","C":"外观油漆是否脱落","D":"铭牌清不清晰"},"answer":["B"],"explain":"调用【倒流防止器巡检】。泄水口被污水淹没会导致脏水倒灌进饮用水管网，直接破坏防污染功能，是倒流防止器最核心的安全红线。","multi":false},{"id":"C100-Q02","courseId":"C100","type":"辨析题","stem":"“消火栓巡检只要看有没有水就行，闷盖缺不缺无所谓。”这种说法是否正确？","options":{"A":"正确，有水就能用","B":"错误，闷盖缺失会导致杂物进入、接口锈蚀，影响应急使用","C":"正确，闷盖只是装饰","D":"错误，缺闷盖会直接导致消火栓爆裂"},"answer":["B"],"explain":"调用【消火栓巡检】。闷盖缺失会让杂物进入接口、造成锈蚀，紧急使用时接不上水带，属于必须整改的缺陷，并非无关紧要。","multi":false},{"id":"C100-Q03","courseId":"C100","type":"单选","stem":"减压阀后压力持续偏高，首先应排查什么？","options":{"A":"是不是阀门坏了","B":"前置Y型过滤器是否堵塞","C":"是不是水压太高","D":"导阀管路是否堵塞或弯折"},"answer":["D"],"explain":"调用【减压阀组巡检】。减压阀调压失效最常见的原因是导阀管路堵塞、弯折，导致调压失灵；应先排查导阀和过滤器，再判断阀体本身故障。","multi":false},{"id":"C101-Q01","courseId":"C101","type":"单选","stem":"管道防腐缺陷中，危害最大、最容易导致穿孔的是？","options":{"A":"表面浮锈","B":"均匀腐蚀","C":"点蚀","D":"防腐层鼓包"},"answer":["C"],"explain":"调用【钢管防腐层缺陷识别】。点蚀是局部深度腐蚀，发展速度快、容易直接穿孔，危害性远大于均匀腐蚀和表面浮锈。","multi":false},{"id":"C101-Q02","courseId":"C101","type":"辨析题","stem":"“镁合金牺牲阳极的标识桩倒了，不影响管道防腐，不用管。”这种说法是否正确？","options":{"A":"正确，阳极在地下，标识桩没用","B":"错误，标识桩丢失倾斜会导致后续找不到阳极位置，影响检测维护","C":"正确，只要阳极在地下就行","D":"错误，标识桩倒了阳极就失效了"},"answer":["B"],"explain":"调用【牺牲阳极巡检】。标识桩用于定位阳极位置、方便检测维护，倾倒丢失不影响阳极即时工作，但会给后续运维检测造成困难，需及时修复。","multi":false},{"id":"C101-Q03","courseId":"C101","type":"多选","stem":"下列属于管道防腐薄弱区域的有？","options":{"A":"法兰密封面周边","B":"环形焊缝位置","C":"弯头背部","D":"管身平整段"},"answer":["A","B","C"],"explain":"调用【法兰与管件防腐检查】。法兰周边、焊缝、弯头都是防腐施工的薄弱区，容易出现薄涂、漏涂，是腐蚀高发位置；管身平整段防腐相对均匀。","multi":true},{"id":"C75-Q01","courseId":"C75","type":"单选","stem":"PE 给水管露天临时堆放，最长不能超过多久","options":{"A":"1 个月","B":"3 个月","C":"6 个月","D":""},"answer":["A"],"explain":"调用【存放周期管理】知识块。PE 管露天临时堆放不得超过 1 个月，且必须全覆盖遮阳布；3 个月暴晒会使冲击强度下降 30% 以上，6 个月老化严重无法使用。","multi":false},{"id":"C75-Q02","courseId":"C75","type":"辨析题","stem":"黑色的 PE 给水管添加了炭黑，因此可以长期露天存放。","options":{"A":"正确，炭黑能完全防紫外线老化","B":"错误，炭黑只能延缓老化，不能完全免疫","C":"错误，黑色 PE 管反而老化更快","D":""},"answer":["B"],"explain":"调用【紫外线老化机理】知识块。黑色 PE 管的炭黑只能延缓紫外线老化，不能完全免疫，长期露天存放依然会出现脆化、开裂。A 夸大了炭黑的作用，C 表述不符合事实。","multi":false},{"id":"C75-Q03","courseId":"C75","type":"单选","stem":"塑料管材存放时，以下哪种做法是错误的","options":{"A":"直管多点支撑，避免弯曲变形","B":"直接堆放在粗糙水泥地上拖拽","C":"与尖锐金属件分区分开","D":""},"answer":["B"],"explain":"调用【物理损伤防控】知识块。直接在粗糙地面拖拽会划伤管材外壁，形成隐性裂纹，埋下爆管隐患；A、C 均为正确的防护做法。","multi":false},{"id":"C76-Q01","courseId":"C76","type":"单选","stem":"给水场景常用的橡胶密封件默认材质是","options":{"A":"NBR 丁腈橡胶","B":"EPDM 三元乙丙橡胶","C":"天然橡胶","D":""},"answer":["B"],"explain":"调用【材质分类差异】知识块。给水场景默认使用 EPDM 材质，耐水且耐温性能适配；NBR 用于含油介质，天然橡胶极少用于给水系统。","multi":false},{"id":"C76-Q02","courseId":"C76","type":"单选","stem":"原包装密封存放条件下，EPDM 橡胶密封件的常规保质期是","options":{"A":"6 个月","B":"18 个月","C":"3 年","D":""},"answer":["B"],"explain":"调用【生命周期管理】知识块。EPDM 密封件原包装密封存放的保质期为 18 个月，超期需报废处理；6 个月过短，3 年远超安全周期。","multi":false},{"id":"C76-Q03","courseId":"C76","type":"辨析题","stem":"胶圈表面沾了机油，擦干净就可以继续用在给水管道上。","options":{"A":"正确，表面没油了不影响密封","B":"错误，机油已经渗入分子链，弹性永久下降","C":"错误，沾油的胶圈硬度会变高","D":""},"answer":["B"],"explain":"调用【老化四要素】知识块。矿物油会渗入橡胶分子链造成溶胀，使橡胶永久失去弹性和密封能力，仅擦拭表面无法恢复性能。A 忽略了内部损伤，C 表述不是核心问题。","multi":false},{"id":"C77-Q01","courseId":"C77","type":"单选","stem":"黑色金属发生锈蚀的核心机理是","options":{"A":"物理磨损","B":"电化学腐蚀","C":"高温熔化","D":""},"answer":["B"],"explain":"调用【腐蚀基本原理】知识块。金属锈蚀的本质是水和氧气共同作用下的电化学腐蚀，并非物理磨损或高温作用。","multi":false},{"id":"C77-Q02","courseId":"C77","type":"辨析题","stem":"表面只有浮锈的钢管，除锈后可以正常使用，不影响结构性能。","options":{"A":"正确，浮锈属于轻度锈蚀，未损伤基体","B":"错误，只要有锈就必须报废","C":"错误，浮锈会持续向内腐蚀，必须降级","D":""},"answer":["A"],"explain":"调用【锈蚀等级判定】知识块。A 级浮锈仅停留在表面，未损伤金属基体，除锈后可正常使用；只有锈坑深度超标才需要降级或报废。B、C 表述过于绝对。","multi":false},{"id":"C77-Q03","courseId":"C77","type":"单选","stem":"以下关于黑色金属堆码的做法，错误的是","options":{"A":"直接放在地面上，不用垫高","B":"远离酸碱类化工物料","C":"层间用木方隔开防磕碰","D":""},"answer":["A"],"explain":"调用【堆码通用规范】知识块。黑色金属必须垫高存放，隔绝地面潮气，直接放地面会加速底部锈蚀；B、C 均为正确做法。","multi":false},{"id":"C78-Q01","courseId":"C78","type":"单选","stem":"不锈钢箱体与碳钢螺栓直接接触存放，会出现什么问题","options":{"A":"不锈钢接触位置发生局部腐蚀","B":"碳钢螺栓会变软失效","C":"二者会焊接粘在一起","D":""},"answer":["A"],"explain":"调用【不锈钢养护规则】知识块。二者接触会形成电偶腐蚀，不锈钢接触点的钝化膜被破坏，出现连片锈斑；B、C 均为错误表述。","multi":false},{"id":"C78-Q02","courseId":"C78","type":"单选","stem":"衬塑复合管现场切割，必须使用哪种工具","options":{"A":"高速砂轮切割机","B":"低速齿锯 / 专用割管机","C":"气割","D":""},"answer":["B"],"explain":"调用【切割与加工禁忌】知识块。衬塑管必须用低速齿锯或专用工具切割，高速砂轮和气割的高温会烧穿塑料内衬，造成钢塑离层。","multi":false},{"id":"C78-Q03","courseId":"C78","type":"辨析题","stem":"黄铜阀门不容易生锈，随便放哪里都可以。","options":{"A":"正确，黄铜完全不会锈蚀","B":"错误，潮湿环境下黄铜也会生铜绿","C":"错误，黄铜生锈比碳钢还快","D":""},"answer":["B"],"explain":"调用【铜件养护要点】知识块。黄铜在潮湿、含硫化物的环境中同样会氧化生成铜绿，影响外观和密封性能，也需要干燥存放。A、C 表述均不符合事实。","multi":false},{"id":"C79-Q01","courseId":"C79","type":"单选","stem":"以下哪项不是电子仪表仓储常见的三大失效原因","options":{"A":"受潮短路","B":"静电击穿芯片","C":"自然老化耗尽寿命","D":""},"answer":["C"],"explain":"调用【失效核心机理】知识块。电子仪表仓储期内三大失效主因为受潮、静电、机械冲击；正常仓储周期内自然老化并非主要失效原因。","multi":false},{"id":"C79-Q02","courseId":"C79","type":"辨析题","stem":"仪表原厂包装里的干燥剂占地方，入库时可以直接扔掉。","options":{"A":"正确，库房干燥不需要干燥剂","B":"错误，干燥剂是防潮关键，不能随意丢弃","C":"错误，干燥剂越多越好，还要额外多加","D":""},"answer":["B"],"explain":"调用【存放环境要求】知识块。原厂干燥剂是仪表防潮防护的重要组成，随意丢弃会增加受潮失效风险。A 认知错误，C 表述过于绝对，过量干燥剂也可能带来问题。","multi":false},{"id":"C79-Q03","courseId":"C79","type":"单选","stem":"搬运电子仪表时，以下哪种做法是正确的","options":{"A":"轻拿轻放，避免抛摔磕碰","B":"多层堆叠重压节省空间","C":"倒置存放节省仓位","D":""},"answer":["A"],"explain":"调用【搬运作业禁忌】知识块。仪表内部有机芯、叶轮等精密部件，抛摔磕碰会造成错位失准；B、C 均为错误做法，会损坏仪表。","multi":false},{"id":"C80-Q01","courseId":"C80","type":"单选","stem":"镁合金牺牲阳极的填包料，最核心的存放禁忌是","options":{"A":"受潮结块","B":"低温凝固","C":"阳光褪色","D":""},"answer":["A"],"explain":"调用【防腐辅材养护】知识块。填包料受潮结块后会失去导电活性，导致阳极无法正常发挥保护作用；B、C 均非核心风险。","multi":false},{"id":"C80-Q02","courseId":"C80","type":"单选","stem":"以下关于井盖存放的说法，正确的是","options":{"A":"复合井盖可以多层重压","B":"球墨铸铁井盖不怕摔，随便扔","C":"都要保护承载结构，防止磕碰碎裂","D":""},"answer":["C"],"explain":"调用【井室设施养护】知识块。无论是复合井盖还是球墨铸铁井盖，承载结构受损都会影响强度和安全性，都需要防止磕碰、重压。A、B 均为错误做法。","multi":false},{"id":"C80-Q03","courseId":"C80","type":"辨析题","stem":"螺栓规格看起来差不多，4.8 级和 8.8 级混放也没关系，用时再挑。","options":{"A":"正确，都是螺栓，能用就行","B":"错误，等级不同强度不同，混放会引发安全事故","C":"错误，8.8 级会生锈更快","D":""},"answer":["B"],"explain":"调用【紧固件养护】知识块。不同强度等级的螺栓力学性能差异极大，混用会导致法兰崩脱、管道泄漏等严重事故，必须分类存放、标识清晰。A 忽视了安全风险，C 表述错误。","multi":false},{"id":"C85-Q01","courseId":"C85","type":"单选","stem":"常规发料前的四项核对，不包括以下哪一项","options":{"A":"核对名称规格","B":"核对型号","C":"核对领料人工号","D":"核对数量"},"answer":["C"],"explain":"发料前的核对盯的是物料本身，你按顺序核对名称、规格、型号、数量这四项就够了。领料人工号属于单据上的信息，单据上有签字即可，不必放到物料核对这一步来查。A、B、D 都是四项核对里的内容，只有 C 不是。把这四项逐项过一遍，就是本课讲的单货核对要点。","multi":false},{"id":"C85-Q02","courseId":"C85","type":"多选","stem":"以下属于无效领料单、不得发料的情况有","options":{"A":"缺少审批人签字","B":"规格型号字迹模糊无法辨认","C":"单据有涂改痕迹且未签章确认","D":"填写了具体工程用途"},"answer":["A","B","C"],"explain":"判断领料单有没有效，你可以对照一张有效单据的六要素：物料名称、规格型号、申领数量、用途、领料人签字、审批人签字，缺一项都不能发。A 缺审批人签字，B 规格型号字迹模糊没法辨认，C 有涂改却没有签章确认，这三种都属于无效单据。而 D 填写具体工程用途恰恰是必填项，属于有效要求，不是无效情形。照这六要素逐一核，就能分清有效还是无效，这对应本课讲的领料凭证要求。","multi":true},{"id":"C85-Q03","courseId":"C85","type":"排序题","stem":"常规领料的正确作业顺序是：①台账登记 ②单据审核 ③物料核对 ④发放物料","options":{"A":"②③④①","B":"①②③④","C":"③②④①","D":"④②③①"},"answer":["A"],"explain":"常规领料的顺序你可以这样走：先审单据是否有效，再核对物料信息，确认单货一致后发放物料，最后登记台账，也就是②单据审核→③物料核对→④发放物料→①台账登记。必须先审单再发料，登账放在最后一步，顺序乱了就容易出账实不符的漏洞。按这个顺序做，正是本课讲的全流程闭环。","multi":false},{"id":"C86-Q01","courseId":"C86","type":"单选","stem":"抢修物料管理的核心目标是","options":{"A":"平时管得规范，急时拿得又快又准","B":"全部打包好，拿起来就走","C":"堆在一起，不用盘点","D":"只备常用件，不用管库存预警"},"answer":["A"],"explain":"抢修物料管理追求的是“平时管得好、急时拿得快”：平时把库存管规范、把库位规划好，紧急时才能快速准确地发料，所以 A 说得最到位。B 全部预打包看着快，其实不利于堆放和盘点；C 堆在一起不盘点，用时找不到也说不清；D 只备常用件、不管库存预警，真抢修时可能没货。后三项都不是规范管理。这正对应本课的核心目标，照“规范＋效率”这两头去想就不会偏。","multi":false},{"id":"C86-Q02","courseId":"C86","type":"多选","stem":"球墨铸铁管破损抢修的标配物料包括","options":{"A":"对应规格哈夫节","B":"法兰橡胶垫片","C":"配套六角头螺栓","D":"超声波水表"},"answer":["A","B","C"],"explain":"球墨铸铁管破损抢修，标配的是哈夫节、法兰橡胶垫片和配套六角头螺栓，这些都是把破口密封、紧固起来的物料，A、B、C 都对得上。超声波水表是计量仪表，管的是流量计量，跟管道破损抢修不沾边，所以 D 不选。抢修定额是围绕“堵漏、密封、紧固”配的，照这个思路核对就不会漏项，这也对应本课讲的典型抢修场景定额。","multi":true},{"id":"C86-Q03","courseId":"C86","type":"辨析题","stem":"深夜突发爆管抢修，可以先发放物料，工作日内补齐手续即可。","options":{"A":"正确，符合应急发料流程要求","B":"错误，必须等审批完才能发","C":"错误，任何时候都不能先领后补","D":"—"},"answer":["A"],"explain":"深夜突发爆管属于特别紧急的抢修，可以按应急发料流程处理：先发料，但要有现场负责人确认，登记好领用人、事由、数量，再在工作日内补齐手续。A 符合这个要求。B 要求必须等审批完才能发，C 认为任何时候都不能先领后补，都没有考虑应急场景的特殊性，过于僵化。这里要记住，先发后补有严格时限，逾期不补就是违规无单领料——这对应本课讲的应急发料流程，效率和底线要一起守住。","multi":false},{"id":"C87-Q01","courseId":"C87","type":"单选","stem":"以下哪种退料可以判定为可复用，重新入合格品库","options":{"A":"拆封未使用、外观完好且在质保期内的 PE 管件","B":"表面有明显裂纹的法兰盲板","C":"已经超期半年的橡胶密封圈","D":"密封面有划痕的黄铜球阀"},"answer":["A"],"explain":"判断能不能复用，你要同时满足三个条件：包装完好、没有使用过、还在质保期内。A 的 PE 管件拆封后没用、外观完好、又在质保期内，三条都满足，可以重新入合格品库。B 的法兰盲板有明显裂纹，C 的橡胶密封圈已经超期，D 的黄铜球阀密封面有划痕，都属于失效或触及报废红线，哪怕只占一条也不能复用。三项缺一不可，这是本课讲的可复用判定标准。","multi":false},{"id":"C87-Q02","courseId":"C87","type":"多选","stem":"退库物料的三级分类包括","options":{"A":"可复用","B":"降级使用","C":"报废","D":"暂存"},"answer":["A","B","C"],"explain":"退库物料只有三个正式等级：可复用、降级使用、报废，处置方式各不相同，A、B、C 就是这三级。“暂存”不在分类里，退回来的料如果随手一暂存、不判定不登记，反而会留下管理漏洞，所以 D 不属于。记住这三级，再对照物料状态去归类，就是本课讲的退料三级分类。","multi":true},{"id":"C87-Q03","courseId":"C87","type":"辨析题","stem":"退回来的物料看着差不多，直接放回货架就行，不用检查登记。","options":{"A":"正确，省时间提高效率","B":"错误，必须核验判定、登记留痕、分区存放","C":"错误，退回来的料全部报废处理","D":"—"},"answer":["B"],"explain":"退回来的料不能看着差不多就直接上架。你要先核验状态，再对照三级标准判定等级，然后登记名称、数量、状态和退料原因，最后按等级分区归位；不检查就入库，等于把次品混进合格品，埋下质量隐患。A 图省事直接上架，是典型的错误做法；C 主张一律报废又过于绝对，把还能复用的料也浪费了。B 的表述最准确。照“核验→判定→登记→归位”四步走，就是本课讲的退库作业流程。","multi":false},{"id":"C91-Q01","courseId":"C91","type":"单选","stem":"仓管员盘点整箱包装的六角头螺栓，每箱标称 100 套，共 8 整箱，零散剩余 23 套，以下记录方式正确的是？","options":{"A":"8 箱 + 23 套","B":"823 套","C":"约 800 套","D":"8 箱"},"answer":["B"],"explain":"盘点必须以物料最小单位为准，整箱需换算为单个数量，8×100+23=823 套，不得按 “箱” 为单位直接记账。","multi":false},{"id":"C91-Q02","courseId":"C91","type":"多选","stem":"下列属于盘点前必须完成的准备工作有哪些？","options":{"A":"物料整理归位，散件集中摆放","B":"补全掉落、模糊的物料标签","C":"导出盘点基准日的库存台账","D":"提前对照账面数预估实盘数量"},"answer":["A","B","C"],"explain":"盘点前需完成物料整理、标签补全、台账导出、工具准备四项核心动作；提前对照账面数预估属于违规行为，违背盲盘原则。","multi":true},{"id":"C91-Q03","courseId":"C91","type":"辨析题","stem":"“初盘时为了提高效率，可以先看账面数量再对照实物清点，只要最终数对得上就行。” 这种说法是否正确？","options":{"A":"正确，能提升盘点效率","B":"错误，盲盘要求初盘不参考账面数，避免先入为主凑数","C":"正确，只要结果一致过程不重要","D":"错误，应该复盘的时候再看账面数"},"answer":["B"],"explain":"初盘执行盲盘规则，不得提前查看账面数量，避免被账面数误导凑数，失去盘点的真实性与校验意义。","multi":false},{"id":"C92-Q01","courseId":"C92","type":"单选","stem":"区分内外丝补芯与双内丝直接的核心依据是？","options":{"A":"是否带有内螺纹","B":"两端口径是否一致","C":"材质是否为衬塑","D":"是否带有外螺纹"},"answer":["B"],"explain":"内外丝补芯是变径件，两端口径不同；双内丝直接是等径件，两端口径一致，这是两者的核心区别，与丝口类型、材质无关。","multi":false},{"id":"C92-Q02","courseId":"C92","type":"辨析题","stem":"“区分明杆和暗杆闸阀，只需要看手轮的大小就能判断。” 这种说法是否正确？","options":{"A":"正确，明杆手轮更大","B":"错误，核心判断依据是阀杆是否随启闭升降","C":"正确，暗杆手轮更厚重","D":"错误，核心判断依据是阀体颜色"},"answer":["B"],"explain":"明杆闸阀阀杆随启闭升降，暗杆闸阀阀杆只旋转不升降，这是核心判断依据，与手轮大小、阀体颜色无必然关联。","multi":false},{"id":"C92-Q03","courseId":"C92","type":"多选","stem":"下列哪些做法能有效降低盘点时的物料串户差错？","options":{"A":"易混物料分类摆放、分开存放","B":"所有物料标签朝向通道，标识朝外","C":"高易错物料盘点时逐件核验规格","D":"外形相近的物料堆放在一起方便清点"},"answer":["A","B","C"],"explain":"分类摆放、标识朝外、逐件核验都是经过验证的有效防错措施；外形相近物料堆放在一起会大幅增加串户混放风险。","multi":true},{"id":"C03-Q01","courseId":"C03","type":"排序题","stem":"【排序题】班组在做PE管热熔对接，由于没带师傅，新员工不知道先干嘛。请按照标准热熔流程，把正确步骤排序：①管口放进加热板加热 ②用铣刀刮平管口 ③拿出来迅速顶推对接 ④清理管口污渍并画线","options":{"A":"② → ④ → ③ → ①","B":"④ → ② → ① → ③","C":"④ → ① → ② → ③","D":"① → ② → ③ → ④"},"answer":["B"],"explain":"对应课程【热熔原理】。热熔标准四步曲：清理画线（防顶过深）——铣削刮平（去氧化层）——加热融化——迅速顶推。","multi":false},{"id":"C03-Q02","courseId":"C03","type":"单选","stem":"【冲突条件】工人做完PE管热熔，检查发现翻边一边大一边小，他说“外面看着没漏，今天太冷了，凑合用吧”。你该怎么处置？","options":{"A":"同意凑合用，赶进度","B":"拿AB胶把缝隙糊上","C":"坚决要求切掉重焊，因为翻边不对称说明加热不均或顶偏了，内部是假焊，打压必漏","D":"外面缠一圈胶带"},"answer":["C"],"explain":"对应课程【热熔质量判读：看翻边】。翻边对称圆润是融合合格的唯一直观标准。不对称为假焊，通水加压直接爆脱。","multi":false},{"id":"C03-Q03","courseId":"C03","type":"单选","stem":"【冲突条件】PE管沟槽挖好了，沟底有几块尖锐的大石头没清理，工人说“PE管是塑料的，有弹性不怕石头”。这有什么隐患？","options":{"A":"没隐患，塑料确实有弹性","B":"石头会自己腐烂","C":"有隐患，但问题不大","D":"管身受压后极易被尖锐石块顶穿或划伤，导致爆管"},"answer":["D"],"explain":"对应课程【存放环境：防暴晒与尖锐物】。PE管虽柔韧，但不耐尖锐物划伤。沟底石块会导致应力集中刺穿管壁。","multi":false},{"id":"C05-Q01","courseId":"C05","type":"单选","stem":"【冲突条件】阀门井里安装一个法兰闸阀，阀门两边要接承插的球墨直管。施工员让你去领“双盘短管”。你应该领吗？","options":{"A":"应该，双盘两头都是法兰，好接","B":"把直管一头锯平当法兰","C":"随便，能拧上就行","D":"不应该，应该领盘承或盘插短管，因为双盘两头都是法兰，没法接承插直管"},"answer":["D"],"explain":"对应课程【盘承与盘插短管】。要一头接法兰阀门，另一头接承插直管，必须用盘承（法兰+承口）或盘插（法兰+插口）过渡。","multi":false},{"id":"C05-Q02","courseId":"C05","type":"排序题","stem":"【排序题】老管子爆裂被切掉一段，两边断口只剩“插口”了。班长让你去领一根短管，并给了你四个抢修步骤。请排序：①清理并涂抹润滑剂 ②套入双承短管 ③塞入橡胶圈 ④双向顶推到位","options":{"A":"② → ① → ③ → ④","B":"① → ③ → ② → ④","C":"① → ② → ③ → ④","D":"④ → ③ → ② → ①"},"answer":["C"],"explain":"对应课程【双盘、双承与双插】。两边是插口，必须用双承短管。步骤：清理润滑——套入一边——塞胶圈——双向顶推。","multi":false},{"id":"C05-Q03","courseId":"C05","type":"单选","stem":"管线末端有个预留口，是个带螺栓孔的法兰，为了防止漏水，你需要领一个什么样的配件封死它？","options":{"A":"球墨盲板（法兰盲板），夹在法兰中间拧紧","B":"球铁堵头（塞承口的）","C":"双插短管","D":"生料带"},"answer":["A"],"explain":"对应课程【盲板与堵头】。法兰口必须用法兰盲板封堵；承口才用球铁堵头塞。","multi":false},{"id":"C06-Q01","courseId":"C06","type":"单选","stem":"【冲突条件】图纸显示一段水平管线要从DN400变成DN200。库房只有“同心渐缩管”，工人说“拿角磨机切一下当偏心的用，凑合焊上”。这做法为什么被绝对禁止？","options":{"A":"同心管太贵，切了可惜","B":"偏心管不好买","C":"水平变径必须用偏心渐缩管且管顶平接。同心管顶部会形成倒扣气囊，阻断水流甚至引发水锤爆管","D":"切了会破坏防腐层"},"answer":["C"],"explain":"对应课程【渐缩管：偏心防气囊】。气体轻会聚集在管顶，同心变径顶部不平，必然憋气。","multi":false},{"id":"C06-Q02","courseId":"C06","type":"单选","stem":"【冲突条件】主管道已经通水，现在要在主管上接一根DN50的小支管。施工队嫌停水麻烦，想让你找一个“像马甲一样、带开孔和螺栓的两半圆件”。这是什么？它能替代三通吗？","options":{"A":"这是分水鞍，可以替代三通做主分叉","B":"这是盲板","C":"这是双盘短管","D":"这是分水鞍，只能在不影响主管的情况下接小支管，绝不可替代主管三通"},"answer":["D"],"explain":"对应课程【分水鞍：不停水开孔】。分水鞍依靠抱箍密封，只能带压开小支管，没有纵向抗拉强度，不能替代主管三通。","multi":false},{"id":"C06-Q03","courseId":"C06","type":"单选","stem":"图纸要求一个管线从水平转90度向上。工人领来了两个承插弯头，说“两个45度的拼起来就是90度，一样用”。这有什么问题？","options":{"A":"承插弯头拼装会占用两倍空间，导致管线几何位置错位；且多出一个接口，增加了漏水隐患。应直接领90度弯头","B":"一样用，省得去买90度的","C":"45度拼装不结实","D":"拼起来太丑"},"answer":["A"],"explain":"对应课程【弯头：改变方向】。弯头角度是图纸设计的，拼装弯头会导致管线坐标偏移，法兰对接不上。","multi":false},{"id":"C08-Q01","courseId":"C08","type":"单选","stem":"泵房高压段法兰对接，库房送来两批法兰，一批标 PN10、一批标 PN16，孔径看着差不多。按本课【法兰 PN 等级与螺栓核对表】，应该怎么做？","options":{"A":"PN 等级定孔数、孔距、孔径和螺栓规格，必须按 PN 与 DN 一起核配套项，不能凭眼混配","B":"孔径差不多就能混装，螺栓通用","C":"只数螺栓够不够就行","D":"高压段优先用平焊 SO，PN 不影响选型"},"answer":["A"],"explain":"对应课程【法兰 PN 等级与螺栓核对表】【法兰双雄：平焊与对焊】。PN10/16/25 对应的孔数、孔距、螺栓规格可能不同，凑合上螺栓会渗漏甚至崩飞；高压段还应优先对焊 WN。孔数与螺栓规格由技术部门按现行标准核定，本课不代填。","multi":false},{"id":"C08-Q02","courseId":"C08","type":"单选","stem":"【冲突条件】一根钢管末端暂时不接设备，但已经安装了法兰，为了防止管内进水，你需要领一个什么件？","options":{"A":"法兰盲板","B":"生料带","C":"焊接弯头","D":"双盘短管"},"answer":["A"],"explain":"对应课程【法兰盲板】。盲板是实心铁板，夹在两片法兰中间拧紧，用来封堵管口。生料带和弯头都不对。","multi":false},{"id":"C08-Q03","courseId":"C08","type":"多选","stem":"【冲突条件】图纸要求在高压泵房内用焊接三通分出一路支管。关于这些焊接管件的验收，下列哪项是正确的？","options":{"A":"两端应该是光秃秃的铁口，靠电焊机焊死","B":"如果有螺纹丝扣，说明买错件了","C":"管口应该有一定的坡口或厚度，方便焊接","D":"焊接件只能靠生料带连接"},"answer":["A","B","C"],"explain":"对应课程【焊接管件】。D错误，生料带只用于螺纹，焊接管件是光口无丝扣的，必须靠电焊熔透。","multi":true},{"id":"C09-Q01","courseId":"C09","type":"排序题","stem":"【排序题】班组在安装法兰闸阀，师傅让你去拧紧六角头螺栓。请按照正确的紧固原则排序：①放入橡胶垫片 ②对角交替、分阶段拧紧螺栓 ③清理法兰密封面 ④用手拧上所有螺栓","options":{"A":"③ → ④ → ① → ②","B":"① → ③ → ② → ④","C":"② → ① → ④ → ③","D":"③ → ① → ④ → ②"},"answer":["D"],"explain":"对应课程【法兰对接】。步骤：先清理密封面，再放垫片，然后手动带上所有螺栓，最后用扳手对角交替、分阶段拧紧。","multi":false},{"id":"C09-Q02","courseId":"C09","type":"单选","stem":"【冲突条件】新员工用两块平焊法兰对接钢管，为了赶进度，直接把管子切平，对着缝隙用焊条堆了一层。试压时压力一升高，焊缝就裂开了。原因是什么？","options":{"A":"焊条质量不好","B":"可以，但不够美观","C":"管口没打磨V型坡口，表面堆焊内部没有熔透，一受压就裂","D":"法兰选错了"},"answer":["C"],"explain":"对应课程【焊接工艺：打磨坡口】。壁厚>4mm需打70°V型坡口，让焊条深入内部熔透，表面浮焊是假焊，扛不住水压。","multi":false},{"id":"C09-Q03","courseId":"C09","type":"单选","stem":"【冲突条件】管段装了法兰盲板做水压试验。压力表打到1.0MPa时，班长发现盲板有点渗水，要求所有人退到侧面，严禁站在盲板正前方。为什么？","options":{"A":"盲板会生锈","B":"前面有电","C":"站在前面看不清漏点","D":"盲板承受巨大水压，一旦螺栓断裂，盲板会像炮弹一样飞出，造成致命伤亡"},"answer":["D"],"explain":"对应课程【试压防雷】。试压时盲板承受极大的推力，站在正前方极其危险，这是绝对的安全红线。","multi":false},{"id":"C12-Q01","courseId":"C12","type":"排序题","stem":"【排序题】班组在热熔PPR管，师傅让你去操作。请按照正确的热熔承插动作排序：①迅速无旋转插入到底 ②设定热熔机温度 ③保持稳定，等待冷却 ④同时加热管材和管件","options":{"A":"② → ① → ④ → ③","B":"② → ④ → ① → ③","C":"④ → ② → ① → ③","D":"① → ② → ③ → ④"},"answer":["B"],"explain":"对应课程【热熔承插】。步骤：设温——同时加热——无旋转直插到底——保持等待冷却。","multi":false},{"id":"C12-Q02","courseId":"C12","type":"单选","stem":"【冲突条件】新员工热熔PPR管时，为了赶进度，加热了很长时间才拔出来插，结果插进去后，管口内部溢出一大圈塑料，水流通道变得很细。这叫什么现象？","options":{"A":"假焊","B":"氧化","C":"热膨胀","D":"缩径"},"answer":["D"],"explain":"对应课程【热熔承插：火候决定生死】。加热时间过长，塑料熔化太多，插入时内壁融化部分被挤出形成缩径，会导致水流变小或堵塞。","multi":false},{"id":"C12-Q03","courseId":"C12","type":"单选","stem":"【冲突条件】工人发现活接头根部漏水，拿出大管钳死命拧金属丝扣那头，结果把丝口拧裂了。正确的维修做法应该是什么？","options":{"A":"拧开活接头的大螺母，检查并更换内部的橡胶平垫片","B":"继续用力拧，直到不漏","C":"用胶水把裂缝粘上","D":"用铁丝缠死"},"answer":["A"],"explain":"对应课程【活接头与螺纹密封】。活接头靠内部的平垫片密封，漏水通常是垫片老化。死命拧丝口会拧裂管件。","multi":false},{"id":"C15-Q01","courseId":"C15","type":"单选","stem":"【冲突条件】家用水表坏了需要更换。工人看到表前有一个带大螺母的管件，拧开螺母就能把表拆下。这个管件叫什么？","options":{"A":"丝接三通","B":"衬塑法兰","C":"活接头","D":"沟槽卡箍"},"answer":["C"],"explain":"对应课程【活接头】。活接头带大螺母，里面靠平垫片密封，专用于需要拆卸维修的地方。","multi":false},{"id":"C15-Q02","courseId":"C15","type":"单选","stem":"【冲突条件】工人发现水表活接头处滴水，便拿了一把大管钳，死命去拧活接头连在铁管上的那头，想把它拧得更紧。结果管件裂了。正确的处理方法是什么？","options":{"A":"用更大的管钳继续拧","B":"用强力胶布缠起来","C":"用电焊把活接头焊死","D":"拧开活接头的大螺母，换掉里面老化的橡胶平垫片"},"answer":["D"],"explain":"对应课程【活接头】。活接头漏水通常是内部平垫片损坏，死拧金属丝口会撑裂管件，正确做法是换垫片。","multi":false},{"id":"C15-Q03","courseId":"C15","type":"单选","stem":"工人接内丝直接时，为了防止漏水，在生料带上缠了厚厚的一圈，结果拧的时候把内衬塑料根部的翻边挤裂了。正确的生料带缠法应该是？","options":{"A":"顺螺纹方向缠，留出第一扣，厚度适中","B":"越厚越好","C":"逆螺纹方向缠","D":"不需要缠"},"answer":["A"],"explain":"对应课程【生料带用法/禁忌】。生料带应顺螺纹方向缠绕，过厚会导致拧入时阻力过大，撑裂内衬翻边或嵌件松动。","multi":false},{"id":"C16-Q01","courseId":"C16","type":"单选","stem":"【冲突条件】高层建筑的供水立管，要求管道必须垂直且不能有任何位移。现场使用的是沟槽连接。应该选用哪种沟槽卡箍？","options":{"A":"柔性卡箍，因为能抗震","B":"普通铁丝绑死","C":"刚性卡箍，因为它能限制管道轴向位移，保证立管稳固","D":"焊接"},"answer":["C"],"explain":"对应课程【刚性卡箍与柔性卡箍的区别】。立管需要防位移，选刚性卡箍；长直管或需吸收震动选柔性卡箍。","multi":false},{"id":"C16-Q02","courseId":"C16","type":"多选","stem":"【冲突条件】在消防喷淋管道上（大口径），工人正用扳手紧固沟槽卡箍的螺栓。关于沟槽连接，下列哪些做法是正确的？","options":{"A":"安装前检查C型橡胶圈有没有老化","B":"涂抹洗洁精或专用润滑剂，方便套入","C":"将两片卡箍外壳扣好，交替均匀拧紧螺栓","D":"为了省事，一边拧到死，另一边再拧"},"answer":["A","B","C"],"explain":"对应课程【沟槽卡箍】。D错误，沟槽卡箍螺栓必须交替均匀拧紧，防止胶圈挤压不均漏水。","multi":true},{"id":"C16-Q03","courseId":"C16","type":"辨析题","stem":"【冲突条件】法兰对接时，工人嫌麻烦，说“这衬塑法兰面上本来就有一层塑料，直接两片拧紧就行，不用加垫片了”。这种说法对不对？","options":{"A":"对，塑料面可以自己密封","B":"不对，应该用电焊焊死","C":"不对，衬塑法兰必须加非金属软垫片（如EPDM），并对称分步拧紧螺栓","D":"对，只要螺栓拧得够紧"},"answer":["C"],"explain":"对应课程【衬塑法兰】。衬塑法兰表面是防腐层，不是密封层。必须依靠非金属软垫片填补微观不平，才能保证高压不漏水。","multi":false},{"id":"C17-Q01","courseId":"C17","type":"单选","stem":"【冲突条件】某高档小区的生活水管网接入了消防水系统，设计院要求安装防倒灌设备。施工队为了省钱，领了双止回阀型倒流防止器装在主进水口。这有什么隐患？","options":{"A":"没隐患，能防倒流就行","B":"双止回阀容易漏水","C":"双止回阀太大了","D":"双止回阀防护等级最低且无泄水，不能用于生活水与消防交界等高危场景，应改用减压型或低阻力型"},"answer":["D"],"explain":"对应课程【三大类型】。双止回阀无泄水功能，防护等级最低。高危边界必须用带泄水功能的减压型或低阻力型。","multi":false},{"id":"C17-Q02","courseId":"C17","type":"单选","stem":"【冲突条件】工人把减压型倒流防止器安装在了常年积水的仪表井里。结果水质被污染了。为什么？","options":{"A":"倒流防止器中间腔的泄水阀必须排水，泡在脏水里会导致脏水倒灌","B":"倒流防止器生锈了","C":"管子裂了","D":"工人没关紧阀门"},"answer":["A"],"explain":"对应课程【安装禁忌】。泄水口排出的水不能积存，更不能泡在污水里，否则脏水会通过泄水口倒吸。","multi":false},{"id":"C21-Q01","courseId":"C21","type":"单选","stem":"【冲突条件】老小区地下阀门井空间非常狭窄，井盖离阀门顶部很近。如果要换一个DN200的闸阀，应该选哪种？","options":{"A":"明杆闸阀，开度直观","B":"电动闸阀","C":"暗杆闸阀，阀杆不升降，对上部空间要求低，适合受限阀井","D":"大口径球阀"},"answer":["C"],"explain":"对应课程【明杆与暗杆】。明杆开启时阀杆会伸出很高，井深不够会顶到井盖。受限空间首选暗杆。","multi":false},{"id":"C21-Q02","courseId":"C21","type":"单选","stem":"【冲突条件】小区物业反映，总水表前的闸阀总是被人偷偷打开偷水。你建议换成什么阀门？","options":{"A":"普通的弹性座封闸阀","B":"换成球阀","C":"加个铁链子锁死","D":"黄铜加密闸阀或加密闸阀。不插专用钥匙手轮空转，能有效防盗水"},"answer":["D"],"explain":"对应课程【黄铜与加密】。普通的锁容易被破坏，加密闸阀依靠磁性或机械密码锁芯，是防偷水的标准配置。","multi":false},{"id":"C22-Q01","courseId":"C22","type":"单选","stem":"【冲突条件】某高层建筑的低压支管压力忽大忽小，洗澡水忽冷忽热。你检查发现，阀前没有装Y型过滤器，导致减压阀的导阀堵塞了。这说明减压阀的什么特性？","options":{"A":"先导式减压阀的导阀孔径极小，泥沙极易堵塞，导致稳压失效。阀前必装过滤器","B":"减压阀不需要过滤器","C":"装不装无所谓","D":"导阀坏了不影响"},"answer":["A"],"explain":"对应课程【安装红线/先导式】。先导式精密但娇气，前端无过滤器必堵。","multi":false},{"id":"C22-Q02","courseId":"C22","type":"多选","stem":"【冲突条件】工人在安装减压阀时，为了省空间，把它垂直立着装在了一段拐弯的管子上。这种安装方式会导致什么后果？","options":{"A":"膜片受力不均，导致出口压力波动","B":"阀芯重力影响，稳压精度下降","C":"容易积水垢","D":"没影响"},"answer":["A","B"],"explain":"对应课程【安装红线】。减压阀必须水平安装，且前后要有直管段，否则内部弹簧和膜片无法正常平衡受力。","multi":true},{"id":"C23-Q01","courseId":"C23","type":"单选","stem":"【冲突条件】泵房里的水泵一停机，管道里就发出巨大的“咣当”声，感觉整个管子都在震。工人换了一个静音式缓闭止回阀后问题解决了。为什么？","options":{"A":"静音阀比较重","B":"可以自己发声","C":"静音缓闭止回阀能在关闭的最后阶段减速，有效吸收和削减破坏性水锤","D":"声音被挡住了"},"answer":["C"],"explain":"对应课程【静音式】。普通止回阀关闭太快，水锤巨大。静音缓闭能分两段关闭，保护管网。","multi":false},{"id":"C23-Q02","courseId":"C23","type":"单选","stem":"【冲突条件】空间极小的地下井里，要在两片法兰之间装一个止回阀。手里有一个很厚的旋启式和一个很薄的对夹式，应该用哪个？","options":{"A":"旋启式，因为结实","B":"都不用","C":"两个一起用","D":"对夹碟式止回阀。它薄如纸片，专门用于空间受限的两法兰之间"},"answer":["D"],"explain":"对应课程【对夹式】。对夹式止回阀就是为节省安装空间设计的。","multi":false},{"id":"C32-Q01","courseId":"C32","type":"单选","stem":"【冲突条件】泵房里的铸铁法兰阀门，为了防止推力震裂水泵，施工员领了一个C2F（传力型）球墨铸铁伸缩节。另一个工头说“拿B2F（限位型）一样，还能吸热胀冷缩”。工头说的对吗？","options":{"A":"对，B2F更好","B":"不对，B2F允许伸缩但不传递盲板推力，保护水泵必须用C2F，将两端刚性锁死传力","C":"对，都是一样的","D":"都不对"},"answer":["B"],"explain":"对应课程【铸铁伸缩节：B2F与C2F】。C2F是传力接头，用长螺杆锁死，不吸位移，专职传推力保设备；B2F是限位接头，吸位移防拉脱。","multi":false},{"id":"C32-Q02","courseId":"C32","type":"多选","stem":"【冲突条件】安装套管式伸缩接头时，工人为了不漏水，把压盖螺栓拧到最紧，并且把内部的伸缩管完全顶到了最里面。这种做法会导致什么后果？","options":{"A":"没有预留伸缩余量，夏天管道受热伸长，会把伸缩器顶坏","B":"压盖拧太死会导致填料或橡胶圈失去弹性","C":"不会漏水就行","D":"只要不漏水，顶死也无所谓"},"answer":["A","B"],"explain":"对应课程【安装预留】。伸缩器必须预留余量，且压盖要有微调的空间，不能顶死。","multi":true},{"id":"C32-Q03","courseId":"C32","type":"排序题","stem":"【排序题】在进行钢制套管伸缩器的安装，请按正确顺序排序：①固定管道 ②调节伸缩管，预留出所需的伸缩余量 ③对角拧紧压盖螺栓 ④检查压盖处是否渗漏","options":{"A":"② → ① → ③ → ④","B":"① → ② → ③ → ④","C":"① → ③ → ② → ④","D":"④ → ② → ③ → ①"},"answer":["B"],"explain":"对应课程【安装预留】。必须先固定管道，再根据温度环境预留余量，然后压紧压盖，最后通水检查。","multi":false},{"id":"C28-Q01","courseId":"C28","type":"单选","stem":"【冲突条件】钢管埋在地下容易生锈烂穿，工人领来了一包“镁合金牺牲阳极”埋在管子旁边。这东西是怎么保护钢管的？","options":{"A":"镁比铁活泼，腐蚀会优先把镁块吃掉，从而让钢管免受电化学腐蚀","B":"它像油漆一样把管子包住","C":"它能释放防腐气体","D":"它能在土里发热"},"answer":["A"],"explain":"对应课程【牺牲阳极】。牺牲阳极的阴极保护法。镁作为阳极牺牲自己，释放电子让钢管变成阴极，从而免遭腐蚀。","multi":false},{"id":"C28-Q02","courseId":"C28","type":"多选","stem":"【冲突条件】半夜抢修，一条铸铁管出现了几个砂眼正往外渗水，但水压不大。抢修队拿出AB胶准备应急处理。下列关于AB胶的说法正确的是？","options":{"A":"它是双组分，A和B必须按比例充分混合","B":"涂抹前必须把砂眼周围的铁锈、油污和水分擦拭干净","C":"AB胶固化后能达到较高硬度，能临时带压止漏","D":"只要涂上去，不管有没有水都能自动粘合"},"answer":["A","B","C"],"explain":"对应课程【AB胶】。D错误，表面有水或有油污会严重影响AB胶的粘结力，必须清理干净且按比例混合。","multi":true},{"id":"C28-Q03","courseId":"C28","type":"单选","stem":"下列关于镁合金牺牲阳极的存放和安装，做法正确的是？","options":{"A":"随便扔在露天泥地里","B":"直接和铁管焊死，不需要电缆连接","C":"安装时外面必须包裹专用的填包料（石膏、膨润土等），以降低接地电阻并保持活性","D":"安装前把镁块用水泡烂"},"answer":["C"],"explain":"对应课程【牺牲阳极】。镁阳极必须通过电缆与管道连接，且周围包裹填包料，才能形成有效的导电回路，否则无法发挥作用。","multi":false},{"id":"C44-Q01","courseId":"C44","type":"单选","stem":"【冲突条件】抢修只剩十分钟、库房只发得出一根短管，井里一侧是法兰阀门、另一侧直管现场量到是承口，班长催着让先拿件——阀门井里一侧是法兰阀门，另一侧直管只剩承口。按本课端头逻辑，应选哪种过渡短管？","options":{"A":"双承短管","B":"盘插短管","C":"盲板","D":"盘承短管"},"answer":["D"],"explain":"调用【盘插与盘承】。法兰接阀门、承口接纳直管插口的是盘承短管；盘插是插口插直管。","multi":false},{"id":"C44-Q02","courseId":"C44","type":"单选","stem":"两段球铁直管断后，两端都只剩插口，需要一根两端承口的短管套入。应选哪种？","options":{"A":"双盘短管","B":"盲板","C":"盘插短管","D":"双承短管"},"answer":["D"],"explain":"调用【双承与双盘】。双承短管两端承口，接纳两根插口；双盘两端法兰。","multi":false},{"id":"C44-Q03","courseId":"C44","type":"单选","stem":"一段需要两端都用螺栓与法兰阀门或法兰管对接、可拆的短管，应选哪种？","options":{"A":"双承短管","B":"盘承短管","C":"盘插短管","D":"双盘短管"},"answer":["D"],"explain":"调用【双盘与双承】。双盘短管两头都是法兰，靠螺栓刚性可拆连接，专接法兰阀门或法兰管；双承/盘承/盘插都含承口或插口，不接纯法兰。","multi":false},{"id":"C45-Q01","courseId":"C45","type":"单选","stem":"【冲突条件】泵房深夜停泵后水锤噪声被投诉，天亮前必须换好一只止回阀，货架上四种形态都有、又不能停水太久——泵出口需要削减停泵水锤噪声，止回阀应优先考虑哪种形态？","options":{"A":"静音式缓闭止回阀","B":"普通旋启金属瓣","C":"升降式止回阀","D":"对夹双瓣"},"answer":["A"],"explain":"调用【对夹与静音】。静音缓闭先快关再缓闭，削减水锤噪声；普通旋启关得快水锤大。","multi":false},{"id":"C45-Q02","courseId":"C45","type":"单选","stem":"两片法兰之间空间很小，需要薄型止回阀。按本课应优先选哪种？","options":{"A":"旋启式","B":"升降式","C":"对夹碟式止回阀","D":"排气阀"},"answer":["C"],"explain":"调用【对夹与静音】。对夹式薄，夹在两法兰间省空间；旋启和升降占空间更大。","multi":false},{"id":"C45-Q03","courseId":"C45","type":"单选","stem":"一只止回阀的阀瓣像一扇铰链门，水流正冲就推开、倒流就压回阀座，流阻小、适合大口径。它最符合哪类？","options":{"A":"升降式","B":"旋启式","C":"对夹碟式","D":"静音缓闭式"},"answer":["B"],"explain":"调用【旋启式】。摇板绕铰链翻转、像单向弹簧门、流阻小适合大口径是旋启式；升降阀瓣直上直下阻力偏大，对夹薄双瓣，静音带缓闭弹簧。","multi":false},{"id":"C46-Q01","courseId":"C46","type":"单选","stem":"【冲突条件】领料单只写 DN100、料车马上发车，架上 PE、钢管、球铁三种管都印着 DN100，老师傅说「都是一百的管随便装」——图纸写DN100的PE给水管，实物喷码应重点核对哪个外径标识？","options":{"A":"Φ114","B":"DN118","C":"De110","D":"Φ60"},"answer":["C"],"explain":"调用【PE看De】。PE管DN100常见De110；Φ114是钢管/衬塑基体常见外径。","multi":false},{"id":"C46-Q02","courseId":"C46","type":"辨析题","stem":"【辨析题】关于 DN100 在不同管材上的口径与外径，下列说法正确的是？","options":{"A":"只要都标 DN100，外径必然一样，管件可以通用","B":"De110 就是 DN110，PE 管可以直接按 Φ114 领","C":"拿卡尺量内径最准，比看喷码可靠","D":"DN 是公称直径（名义值），PE 看 De、钢管/衬塑看 Φ、球铁另有外径，不能量内径去对"},"answer":["D"],"explain":"调用【DN 不是内径】。DN 只是名义尺寸，各材质外径体系不同：PE 常见 De110、钢/衬塑常见 Φ114、球铁约 Φ118。量内径、跨材质套管件，都会导致插不进或法兰对不上。","multi":false},{"id":"C46-Q03","courseId":"C46","type":"单选","stem":"领料单只写 DN100，架上 PE、衬塑钢管、球铁三种管都印着 DN100。按本课【跨材质同 DN 外径对照表】，正确的核对顺序是？","options":{"A":"三种管外径一样，随便装","B":"先按材质找列：PE 看 De、钢管衬塑看 Φ、球铁看外径，再核喷码与管件是否同一体系","C":"只量内径，对得上 100 就合格","D":"按量出来的最大外径统一配套管件"},"answer":["B"],"explain":"对应课程【跨材质同 DN 外径对照表：常用档怎么对】。同 DN 不同材质外径体系不同，管件必须和管材同一体系配套；逐档精确外径以管身喷码、材料卡与现行标准核定，本课示例值不作标准数值。","multi":false},{"id":"C47-Q01","courseId":"C47","type":"单选","stem":"【冲突条件】泵房今晚要投运，库房只剩两只蝶阀、工期紧又不许返工，班长催着马上定型号——高压泵房出口要选一只蝶阀，介质温度偏高、压力也不低。按本课软硬密封边界，应优先考虑哪类？","options":{"A":"三偏心金属硬密封蝶阀，锥形楔紧、耐高温高压","B":"中线软密封蝶阀，常温清水零泄漏又便宜","C":"电动蝶阀，带了执行器密封自然更好","D":"随便一只中线蝶阀，加个电机就行"},"answer":["A"],"explain":"调用【软硬边界】。软密封靠 EPDM 橡胶过盈挤压，怕高温高压；三偏心是金属对金属楔紧切断，耐高温高压。电动只是驱动方式，不改变阀体密封等级，别拿它当耐温措施。","multi":false},{"id":"C47-Q02","courseId":"C47","type":"单选","stem":"一只蝶阀的阀杆穿过蝶板正中心、阀座是橡胶过盈挤压。按本课它属于哪类结构？","options":{"A":"三偏心硬密封蝶阀","B":"双偏心金属密封蝶阀","C":"中线（软密封）蝶阀","D":"静音缓闭止回阀"},"answer":["C"],"explain":"调用【中线软密封】。阀杆居中 + 橡胶阀座过盈＝中线软密封，常温清水密封好、启闭轻；偏心是阀杆偏置、开启瞬间脱离阀座，靠位置就能分辨。","multi":false},{"id":"C47-Q03","courseId":"C47","type":"单选","stem":"一台蝶阀带电机执行器，介质是高温高压热水。判断它能不能耐温耐压，关键看什么？","options":{"A":"看有没有电机","B":"看阀体本身的密封结构（中线软密封还是偏心硬密封）","C":"电机功率越大越耐温","D":"手柄颜色"},"answer":["B"],"explain":"调用【电动蝶阀】。电动只是在阀体上加执行器，阀体密封结构没变；耐温耐压由中线软密封或偏心硬密封决定，不是电机，别因有电机就当耐温阀。","multi":false},{"id":"C48-Q01","courseId":"C48","type":"单选","stem":"【冲突条件】试压前发现盲板推力没处传，库房只剩 B2F 和 C2F 各一只，班长说「都是伸缩节随便上」——泵出口要把阀门盲板推力传到管道、且不允许吸收位移。按本课分工，应选哪种补偿件？","options":{"A":"可曲挠橡胶接头，球体吸振","B":"轴向波纹管补偿器，吸轴向热伸长","C":"C2F 传力型伸缩节，螺杆锁死、传推力、不吸位移","D":"B2F 限位型伸缩节，行程内可伸缩"},"answer":["C"],"explain":"调用【B2F与C2F】。C2F 用传力螺杆把两端锁死，不吸位移、专传盲板推力；B2F 是限位伸缩、吸位移防拉脱。二者用反了，要么热伸长没处放，要么推力压坏设备。","multi":false},{"id":"C48-Q02","courseId":"C48","type":"单选","stem":"直管段要吸收热胀冷缩的轴向伸长，中间是不锈钢波纹、旁边带几根限位拉杆。按本课它是哪类？","options":{"A":"可曲挠式橡胶接头","B":"轴向型波纹管补偿器","C":"C2F 传力型伸缩节","D":"横向铰链型补偿器"},"answer":["B"],"explain":"调用【波纹管】。不锈钢波纹 + 限位拉杆＝轴向波纹管补偿器，吸轴向位移；拉杆替波纹扛内压推力，绝不能随便拆。橡胶接头吸的是振动，不是热伸长。","multi":false},{"id":"C48-Q03","courseId":"C48","type":"单选","stem":"一段管道需要吸收角向偏转，库房里有铰链型波纹管补偿器。按本课【补偿器三类辨识】，下面哪项做法正确？","options":{"A":"铰链型单独装一只就能吸收直线位移","B":"铰链型只能角向偏转，必须两个或三个成组配套使用","C":"把限位拉杆拆掉就能当轴向型用","D":"用补偿器硬拉管道对口找正"},"answer":["B"],"explain":"对应课程【补偿器三类辨识】【大拉杆横向型与铰链型】。铰链型只能角向偏转，必须成组配套，单独用无法吸收直线位移；拉杆承受内压推力不能拆，也不能用补偿器强行对口。","multi":false},{"id":"C49-Q01","courseId":"C49","type":"单选","stem":"【冲突条件】生活水与消防水交界今天要验收，井里已有积水、泄水口没法抬高，有人提议把泄水口先封死省事——倒流防止器中腔泄水口必须满足什么边界？","options":{"A":"可以泡在污水坑里","B":"必须能顺畅排走，不能泡在污水或下水道里","C":"可以封死不用","D":"必须朝上"},"answer":["B"],"explain":"调用【泄水口边界】。中腔泄水要能排走，泡污水会倒灌。","multi":false},{"id":"C49-Q02","courseId":"C49","type":"辨析题","stem":"【辨析题】关于倒流防止器的防护等级与泄水口，下列说法正确的是？","options":{"A":"减压型带双止回、减压装置和中腔泄水，防护最高；泄水口必须顺畅排走、不能泡污水","B":"泄水口泡在污水里不影响，反正水往外排","C":"双止回型防护最高，可用于生活水与消防水高危边界","D":"低阻力型没有止回阀，水损最低"},"answer":["A"],"explain":"调用【三类类型 / 泄水口边界】。减压型双止回 + 减压 + 中腔泄水，防护最高；双止回无泄水、防护最低，不能用于高危降级。泄水口泡污水，脏水可能倒灌污染上游饮用水。","multi":false},{"id":"C49-Q03","courseId":"C49","type":"单选","stem":"倒流防止器前端为什么要配 Y 型过滤器？","options":{"A":"为了好看统一","B":"挡住泥沙避免卡住止回阀芯，保证防护有效","C":"代替泄水口排水","D":"提高水压"},"answer":["B"],"explain":"调用【安装配套】。前置 Y 型过滤器挡泥沙，防止阀芯卡住关不严；阀芯失效防护就形同虚设。它不代替泄水口，也不提高水压。","multi":false},{"id":"C50-Q01","courseId":"C50","type":"单选","stem":"【冲突条件】含油污水管抢修赶工期，库里只剩一批黑色橡胶圈、包装标识磨没了，有人说「黑色都一样先装上」——给水管道胶圈包装标识不清，库房只剩黑色橡胶圈。按本课应怎样处理？","options":{"A":"凭黑色直接发料","B":"看包装标识、材料卡材质字段和厂家标记，不能凭眼看","C":"抹机油试用","D":"用生料带代替"},"answer":["B"],"explain":"调用【怎么辨】。黑色橡胶外观难分，必须看标识和卡面；给水默认EPDM。","multi":false},{"id":"C50-Q02","courseId":"C50","type":"单选","stem":"含油工业污水管道的橡胶接头，应优先选哪种材质？","options":{"A":"EPDM","B":"球墨铸铁","C":"PTFE","D":"NBR"},"answer":["D"],"explain":"调用【NBR】。NBR耐油；EPDM怕油会溶胀。","multi":false},{"id":"C50-Q03","courseId":"C50","type":"单选","stem":"给水管道的 EPDM 胶圈被错用到含矿物油的污水里，几天后最可能出什么问题？","options":{"A":"更耐用了","B":"橡胶溶胀发黏失去弹性、接口漏水","C":"颜色变浅","D":"没有任何影响"},"answer":["B"],"explain":"调用【EPDM怕油】。EPDM 耐水怕油，遇矿物油会溶胀发黏、失去弹性，几天就可能接口失效漏水；含油介质应选 NBR。","multi":false},{"id":"C55-Q01","courseId":"C55","type":"单选","stem":"夜间道路抢修，工人说“反光衣太显眼，先下车再说”。按本课正确做法是什么？","options":{"A":"听他的，先下车","B":"先穿反光衣再下车，安全帽按现场要求戴好","C":"只戴安全帽不穿反光衣","D":"跑快一点就行"},"answer":["B"],"explain":"调用【反光衣】【安全帽】。夜间道路作业先提高可见性；只戴帽不穿反光衣可见性不足，跑快不能代替PPE。","multi":false},{"id":"C55-Q02","courseId":"C55","type":"单选","stem":"巡检发现井盖缺失，赶时间只拍照发工作群就走。正确做法是什么？","options":{"A":"只拍照发群","B":"立即设置临时围挡警示并上报，守到交接","C":"用砖头虚盖一下","D":"继续巡检不管"},"answer":["B"],"explain":"调用【井盖缺失】【围挡与上报】。只拍照是上报不是现场控制；砖头虚盖是偷懒，坑在行人一踩就翻。","multi":false},{"id":"C55-Q03","courseId":"C55","type":"多选","stem":"路面塌陷，下列处理方式正确的是？","options":{"A":"不要站上去踩试","B":"先围挡、疏散并上报","C":"夜间加反光警示","D":"开车压过去试试深度"},"answer":["A","B","C"],"explain":"调用【路面塌陷】【围挡与上报】。D是二次塌陷风险；A、B、C是先控制现场再上报。","multi":true},{"id":"C59-Q01","courseId":"C59","type":"单选","stem":"【冲突条件】到货单写 GB/T 13295-2019，材料卡备注 2026 版 2027-03-01 实施，到货日期是 2027 年 4 月。验收第一步怎么判？","options":{"A":"直接按单据旧版放行","B":"先看实施日期，切换后按新版核对，拿不准转待检","C":"把卡上备注撕掉","D":"只要外观好就放行"},"answer":["B"],"explain":"调用【标准换版是验收边界】。切换日后按新版；单据旧版与卡上换版提示冲突，先看实施日期，不自行放行。","multi":false},{"id":"C59-Q02","courseId":"C59","type":"多选","stem":"球墨铸铁管及管件到货验收，下列哪些要重点看？","options":{"A":"内衬类型与连续性","B":"外防腐锌层与终饰层","C":"胶圈规格与老化","D":"端头保护与批次一致性"},"answer":["A","B","C","D"],"explain":"调用【内衬类型按水质选】【锌层是外防腐硬指标】【胶圈与端头组合要配套】。四项都是本课验收范围。","multi":true},{"id":"C59-Q03","courseId":"C59","type":"排序题","stem":"球墨铸铁管到货遇标准换版提示，验收判断顺序哪一项正确？","options":{"A":"看到货日期→看卡上实施日期→判断切换前后→单据与卡面冲突拿不准转待检","B":"看卡上实施日期→看到货日期→直接按旧版放行→转待检","C":"直接按单据放行→看到货日期→看卡上实施日期→转待检","D":"看到货日期→直接按新版放行→看卡上实施日期→转待检"},"answer":["A"],"explain":"调用【标准换版是验收边界】。先看到货日期，再看卡上实施日期，判断切换前后；单据与卡面冲突且拿不准时转待检，不自行放行。","multi":false},{"id":"C60-Q01","courseId":"C60","type":"单选","stem":"【冲突条件】同一箱沟槽卡箍，标签写“刚性/柔性混装”，到货验收怎么分？","options":{"A":"随便拿，反正都能密封","B":"按标识和结构分，分别挂签待检","C":"全部当柔性卡箍收","D":"全部当刚性卡箍收"},"answer":["B"],"explain":"调用【沟槽卡箍分刚柔】。刚性限制轴向位移，柔性允许微量转角；混装不能凭外观发料，先分开挂签。","multi":false},{"id":"C60-Q02","courseId":"C60","type":"辨析题","stem":"“内外丝补芯（变径补芯）两端都是内丝，所以验收不用分方向。”这种说法对不对？","options":{"A":"对，补芯两端都是内丝","B":"错，但两端都是外丝","C":"对，只要口径对就行","D":"错，补芯一端内丝一端外丝，外丝朝大径、内丝朝小径"},"answer":["D"],"explain":"调用【补芯方向要分清】。补芯是一端内丝一端外丝，用于变径并转换内外丝；记反硬拧会撑裂内衬。","multi":false},{"id":"C60-Q03","courseId":"C60","type":"多选","stem":"衬塑复合管及管件验收，下列哪些是红线？","options":{"A":"严禁电焊气割","B":"严禁普通高速砂轮切割","C":"切割口发黑、内衬碳化要待检","D":"可以用焊补修内衬"},"answer":["A","B","C"],"explain":"调用【切割禁忌是验收红线】。电焊气割和普通砂轮都会高温损伤内衬；焊补修内衬不成立。","multi":true},{"id":"C62-Q01","courseId":"C62","type":"单选","stem":"钢管法兰到货验收，单据写「PN16 DN200 WN」。按本课【法兰验收：按 PN 与 DN 一起核】，正确的核对顺序是？","options":{"A":"数螺栓数量够了就放行","B":"读卡面 PN/DN → 对实物铭牌 → 核孔数孔距螺栓规格 → 对型式 SO/WN/BL → 查密封面与垫片","C":"只看有没有焊缝","D":"按上次同口径法兰的经验放行"},"answer":["B"],"explain":"对应课程【法兰验收：按 PN 与 DN 一起核】。五步核对动作要成套走，焊缝、法兰、盲板缺一项都可能试压时漏。孔数、孔径、螺栓规格由技术部门按现行标准核定，本课不代填数值。","multi":false},{"id":"C62-Q02","courseId":"C62","type":"排序题","stem":"直缝焊接钢管与钢制管件到货验收，判断顺序哪一项正确？","options":{"A":"看焊缝分直缝/螺旋→核DN与壁厚→查内外防腐→分平焊/对焊→认钢盲板/球铁盲板","B":"核DN与壁厚→看焊缝→认盲板→查防腐→分平焊/对焊","C":"分平焊/对焊→看焊缝→核DN与壁厚→查防腐→认盲板","D":"认盲板→查防腐→看焊缝→核DN与壁厚→分平焊/对焊"},"answer":["A"],"explain":"调用【先看焊缝分直缝与螺旋】【材质口径与防腐】【平焊与对焊要分场景】【法兰盲板别混材质】。先分族，再核规格防腐，再分法兰类型，最后认盲板材质。","multi":false},{"id":"C62-Q03","courseId":"C62","type":"多选","stem":"直缝焊接钢管与钢制管件到货验收，下列哪些要核？","options":{"A":"焊缝是纵向直缝还是螺旋缝","B":"DN 与壁厚","C":"内外防腐层破损","D":"平焊还是对焊法兰"},"answer":["A","B","C","D"],"explain":"调用【先看焊缝分直缝与螺旋】【材质口径与防腐】【平焊与对焊要分场景】。四项都是钢管验收关键。","multi":true},{"id":"C63-Q01","courseId":"C63","type":"单选","stem":"【冲突条件】倒流防止器到货，铭牌写“低阻力型”，卡上要求高风险边界用“减压型”。验收怎么判？","options":{"A":"低阻力也能用，直接放行","B":"类型与设计防护等级不符，先待检核设计","C":"把铭牌改成减压型","D":"只要阀体好就放行"},"answer":["B"],"explain":"调用【三类倒流防止器要分清】。低阻力水头损失小但防护等级低于减压型；类型不符先待检。","multi":false},{"id":"C63-Q02","courseId":"C63","type":"辨析题","stem":"“低阻力倒流防止器水头损失小，所以在高风险边界可以替代减压型倒流防止器。”这种说法对不对？","options":{"A":"对，水损小更节能","B":"错，低阻力防护等级低于减压型，不能降级替代","C":"对，两者防护等级一样","D":"错，但可以按低阻力标准放行"},"answer":["B"],"explain":"调用【三类倒流防止器要分清】。低阻力省水头，减压型防护等级更高；高风险边界不能降级替代。","multi":false},{"id":"C63-Q03","courseId":"C63","type":"多选","stem":"减压阀到货验收，下列哪些要核？","options":{"A":"阀前 Y 型过滤器接口或配套过滤器","B":"铭牌类型、DN、PN、流向","C":"导阀、膜片外观完整","D":"出厂合格证与标准号"},"answer":["A","B","C","D"],"explain":"调用【安装边界是验收内容】【标准状态与铭牌】。过滤器配套、铭牌、导阀膜片、合格证标准都是到货可查项。","multi":true},{"id":"C64-Q01","courseId":"C64","type":"单选","stem":"到货闸阀铭牌写「Z45X-16Q」。按本课【阀门型号怎么读】，下面哪项拆读正确？","options":{"A":"Z 是蝶阀、16 是口径 DN16","B":"Z 是闸阀、4 是法兰连接、X 是橡胶软密封、16 是 PN16、Q 是球墨铸铁","C":"Q 表示球墨铸铁，所以 16 是壁厚","D":"型号末尾字母代表传动方式"},"answer":["B"],"explain":"对应课程【阀门型号怎么读：一串字母数字的拆法】【截断类阀门类型 × 口径 × PN 对照表】。按类型→传动→连接→结构→密封面→压力→材质逐段拆；横杠后 16 是公称压力 PN16，不是口径；末尾 Q 是阀体材质球铁。代号含义以现行型号编制标准原文和厂家铭牌为准。","multi":false},{"id":"C64-Q02","courseId":"C64","type":"多选","stem":"截断类阀门到货，中线蝶阀、固定球阀、加密闸阀同批。下列关于阀杆、轴承与锁具的核对判断，正确的是？","options":{"A":"中线蝶阀看阀杆居中、软密封标识","B":"固定球阀看轴承结构、转动手柄轻","C":"加密闸阀看锁芯、钥匙、离合机构","D":"浮动球阀适合所有大口径高压"},"answer":["A","B","C"],"explain":"调用【蝶阀分中线与偏心】【球阀分浮动与固定】【黄铜与加密阀】。浮动球大口径高压会拧不动，D 是选型错误。","multi":true},{"id":"C64-Q03","courseId":"C64","type":"辨析题","stem":"“加密闸阀没钥匙时手轮空转，说明阀门坏了。”这种说法对不对？","options":{"A":"对，空转就是损坏","B":"错，没钥匙手轮空转是正常防盗，手轮与阀杆离合","C":"对，必须换手轮","D":"错，但可以强行拧开"},"answer":["B"],"explain":"调用【黄铜与加密阀】。加密阀靠离合锁定，没钥匙手轮空转是正常防盗；验收看锁芯、钥匙、离合机构，不能当损坏。","multi":false},{"id":"C65-Q01","courseId":"C65","type":"单选","stem":"【冲突条件】止回阀到货，阀体箭头与包装标识流向不一致，验收怎么判？","options":{"A":"按箭头装就行","B":"流向标识不一致先待检，核对铭牌与卡面","C":"把箭头磨掉","D":"只要阀体好就放行"},"answer":["B"],"explain":"调用【先认止回原理】。止回阀箭头装反等于没装；标识不一致先待检。","multi":false},{"id":"C65-Q02","courseId":"C65","type":"排序题","stem":"排气阀到货验收，判断顺序哪一项正确？","options":{"A":"看阀体类型（快速/微量/复合）→看浮球浮筒结构→核标准号→看标识与包装","B":"核标准号→看阀体类型→看标识→看浮球结构","C":"看标识与包装→核标准号→看浮球结构→看阀体类型","D":"看浮球结构→看标识→看阀体类型→核标准号"},"answer":["A"],"explain":"调用【排气阀三类要分清】【标准与安装位置】。先分类型，再看浮球浮筒结构，再核标准号，最后看标识与包装；顺序有助于先分族再核依据。","multi":false},{"id":"C65-Q03","courseId":"C65","type":"多选","stem":"排气阀到货，快速式大孔、微量式小孔、复合式大小孔都有。关于这三类排气阀结构的判断，下列哪些正确？","options":{"A":"快速排气阀大孔用于充水大量排气","B":"微量排气阀小孔排溶解空气","C":"复合式排气阀兼大孔和小孔","D":"复合式排气阀没有浮球"},"answer":["A","B","C"],"explain":"调用【排气阀三类要分清】。复合式靠浮球浮筒控制，D 错；快速、微量、复合按结构分。","multi":true},{"id":"C66-Q01","courseId":"C66","type":"单选","stem":"旋翼式机械水表与水平螺翼机械水表，结构分族的主要依据是什么？","options":{"A":"叶轮布置方向与常用口径","B":"表壳颜色","C":"铅封颜色","D":"包装大小"},"answer":["A"],"explain":"调用【三类水表的结构差异】。旋翼式叶轮垂直水流、DN15–DN40；水平螺翼叶轮水平、DN50–DN300；结构分族看叶轮与口径。","multi":false},{"id":"C66-Q02","courseId":"C66","type":"多选","stem":"水表到货验收，下列哪些属于本课讲的计量凭据或功能项？","options":{"A":"铅封是否完整","B":"读数窗口是否清晰","C":"检定标识与表体编号是否对应","D":"表壳颜色是否统一"},"answer":["A","B","C"],"explain":"调用【铅封与强制检定】【读数显示与标准依据】。铅封、检定标识、读数窗口是计量凭据与功能项；颜色不是判定依据。","multi":true},{"id":"C66-Q03","courseId":"C66","type":"辨析题","stem":"“水表铅封断了，只要表体没坏就可以直接进现用区。”这种说法对不对？","options":{"A":"错，铅封是计量封缄，断了先待检","B":"对，表体没坏就行","C":"对，铅封只是装饰","D":"错，但可以自己重新铅封"},"answer":["A"],"explain":"调用【铅封与强制检定】。铅封是计量封缄，断裂不能直接进现用区；重新铅封不是验收人员自行处理的事。","multi":false},{"id":"C67-Q01","courseId":"C67","type":"单选","stem":"光电直读远传水表与 NB-IoT 智能水表，通信侧的主要差异是什么？","options":{"A":"表壳大小","B":"通信方式：M-BUS/RS-485 与 NB-IoT 模组","C":"铅封颜色","D":"包装箱颜色"},"answer":["B"],"explain":"调用【远传水表的两类通信】。光电直读常配 M-BUS/RS-485，NB-IoT 靠模组与网络；通信方式先分。","multi":false},{"id":"C67-Q02","courseId":"C67","type":"多选","stem":"电磁流量计到货验收，下列哪些属于本课讲的结构或凭据项？","options":{"A":"检定证书与标准号","B":"转换器铭牌与电源信号端子","C":"电极与衬里是否完好","D":"表壳颜色是否统一"},"answer":["A","B","C"],"explain":"调用【电磁流量计的结构要点】【检定与标准依据】。电极衬里、转换器、检定证书是结构或凭据项；颜色不是判定依据。","multi":true},{"id":"C67-Q03","courseId":"C67","type":"排序题","stem":"插入式超声波流量计到货验收，判断顺序哪一项正确？","options":{"A":"看传感器与球阀底座配套→看直管段要求与说明书→核标准号与检定证书→查电缆与附件","B":"核标准号→看传感器→查电缆→看直管段","C":"查电缆→看传感器→核标准号→看直管段","D":"看直管段→查电缆→看传感器→核标准号"},"answer":["A"],"explain":"调用【插入式超声波的结构与边界】【检定与标准依据】【附件与包装】。先看底座配套，再看直管段说明，再核标准检定，最后查电缆附件。","multi":false},{"id":"C68-Q01","courseId":"C68","type":"单选","stem":"胶垫（法兰橡胶垫片）与胶圈（球墨管承插密封圈），结构分族的主要依据是什么？","options":{"A":"颜色","B":"包装大小","C":"形状与用途：平圆带孔 vs 厚实环形","D":"价格"},"answer":["C"],"explain":"调用【胶垫与胶圈的结构差异】。胶垫平圆形带螺栓孔、用于法兰；胶圈厚实环形、用于承插；形状和用途先分。","multi":false},{"id":"C68-Q02","courseId":"C68","type":"多选","stem":"密封紧固与抢修辅材到货验收，下列哪些判断正确？","options":{"A":"给水胶垫胶圈默认 EPDM","B":"半丝螺栓用于法兰对接，光杆抗剪","C":"哈夫节要看橡胶垫是否老化","D":"螺栓等级不用看头标"},"answer":["A","B","C"],"explain":"调用【胶垫与胶圈的结构差异】【半丝与全丝螺栓的受力差异】【哈夫节与 AB 胶的用途边界】。螺栓等级要看头标，D 错。","multi":true},{"id":"C68-Q03","courseId":"C68","type":"辨析题","stem":"“胶圈沾了点机油没关系，擦一擦还能用。”这种说法对不对？","options":{"A":"对，擦干净就行","B":"错，EPDM 怕油，沾油会加速老化，先待检","C":"对，机油能润滑","D":"错，但可以泡水继续用"},"answer":["B"],"explain":"调用【胶垫与胶圈的结构差异】。给水默认 EPDM，怕油怕晒；沾油先待检，不能擦一擦就放行。","multi":false},{"id":"C69-Q01","courseId":"C69","type":"单选","stem":"车行道和消防通道的井盖，承载等级应重点看哪一档？","options":{"A":"D400 重型","B":"A15 轻型","C":"B125 普型","D":"C250 中型"},"answer":["A"],"explain":"调用【球铁井盖与复合井盖的材质差异】。车行道和消防通道按 D400 重型；复合井盖不能上重车道。","multi":false},{"id":"C69-Q02","courseId":"C69","type":"多选","stem":"井盖与消火栓到货验收，下列哪些属于本课讲的功能或结构项？","options":{"A":"井盖功能标识（给水/消防）","B":"井盖防盗铰链与锁具","C":"地上式与地下式消火栓的型式区别","D":"井盖颜色是否统一"},"answer":["A","B","C"],"explain":"调用【井盖附件与防盗结构】【地上式与地下式消火栓】。功能标识、锁具、消火栓型式是功能或结构项；颜色不是判定依据。","multi":true},{"id":"C69-Q03","courseId":"C69","type":"辨析题","stem":"“复合井盖轻便又防盗，所以消防车通道也能用。”这种说法对不对？","options":{"A":"对，轻便就好","B":"对，复合井盖不怕压","C":"错，消防车通道要按 D400 重型核，复合井盖承载等级不够不能上","D":"错，但加个铁框就能用"},"answer":["C"],"explain":"调用【球铁井盖与复合井盖的材质差异】。复合井盖常用 A15/B125/C250，消防通道要 D400；承载等级不够不能上。","multi":false},{"id":"C70-Q01","courseId":"C70","type":"单选","stem":"球墨铸铁伸缩节 B2F 与 C2F，结构分族的主要依据是什么？","options":{"A":"颜色","B":"价格","C":"包装大小","D":"B2F 配限位双螺母、C2F 配传力螺杆"},"answer":["D"],"explain":"调用【B2F 与 C2F 的限位与传力差异】。B2F 限位、C2F 传力；看限位双螺母和传力螺杆先分。","multi":false},{"id":"C70-Q02","courseId":"C70","type":"多选","stem":"可曲挠橡胶接头到货验收，下列哪些属于本课讲的结构或材质项？","options":{"A":"橡胶球体有无裂纹、油污、烫伤","B":"材质标识 EPDM/NBR","C":"限位螺栓与螺母是否齐全","D":"法兰颜色是否统一"},"answer":["A","B","C"],"explain":"调用【可曲挠橡胶接头的结构与限位】。球体、限位螺栓、材质标识是结构或材质项；颜色不是判定依据。","multi":true},{"id":"C70-Q03","courseId":"C70","type":"排序题","stem":"补偿器与转换接头到货验收，判断顺序哪一项正确？","options":{"A":"核标准号→看类型→查包装→看关键件","B":"看类型与结构（橡胶接头/B2F/C2F/多功能法兰/波纹管）→看关键件（限位螺栓、传力螺杆、锁紧环、拉杆）→核标准号→查包装附件","C":"查包装→看关键件→核标准号→看类型","D":"看关键件→看类型→查包装→核标准号"},"answer":["B"],"explain":"调用【可曲挠橡胶接头的结构与限位】【B2F 与 C2F 的限位与传力差异】【多功能法兰连接器的防脱结构】【波纹管补偿器的拉杆与波纹管】【标准状态与附件】。先分类型结构，再看关键件，再核标准，最后查包装附件。","multi":false},{"id":"C71-Q01","courseId":"C71","type":"单选","stem":"验收记录要能追溯，下列哪一项不是“拍照发群”能替代的？","options":{"A":"拍一张外包装照片","B":"课程号、卡名、批次、数量、异常点、处理动作","C":"发一句“到货了”","D":"拍一张叉车照片"},"answer":["B"],"explain":"调用【验收记录的要素】。记录要能追溯，必须包含课程号、卡名、批次、数量、异常点、处理动作；拍照发群不能替代。","multi":false},{"id":"C71-Q02","courseId":"C71","type":"多选","stem":"拒收与隔离处置，下列哪些判断正确？","options":{"A":"拒收是判定，隔离是现场控制","B":"待检区要物理分开并挂标识","C":"合格才能上现用架","D":"隔离就是把货藏起来不用记录"},"answer":["A","B","C"],"explain":"调用【拒收与隔离的区别】【入库上架的先决条件】。隔离要记录原因数量批次，D 错。","multi":true},{"id":"C71-Q03","courseId":"C71","type":"辨析题","stem":"“待检件先放在现用区角落，等有空再处理。”这种说法对不对？","options":{"A":"对，角落也是隔离","B":"错，但贴张纸就行","C":"对，反正没发料","D":"错，待检区要物理分开并挂标识，不能混在现用区"},"answer":["D"],"explain":"调用【拒收与隔离的区别】。待检区要物理分开、挂标识、有台账；混在现用区角落，下次就发错。","multi":false},{"id":"C72-Q01","courseId":"C72","type":"单选","stem":"PE 法兰头/片与钢法兰，结构分族的主要依据是什么？","options":{"A":"颜色","B":"包装大小","C":"有没有 PE 可熔端","D":"价格"},"answer":["C"],"explain":"调用【法兰族四类的材质与标准】。PE 法兰头一端可熔端、一端法兰盘；钢法兰没有 PE 可熔端；端头先分。","multi":false},{"id":"C72-Q02","courseId":"C72","type":"多选","stem":"端头族辨析，下列哪些判断正确？","options":{"A":"盘插短管一端法兰一端插口","B":"盘承短管一端法兰一端承口","C":"双承短管两端承口","D":"双盘短管两端承口"},"answer":["A","B","C"],"explain":"调用【端头族四类的端头组合】。双盘短管两端法兰，D 错。","multi":true},{"id":"C72-Q03","courseId":"C72","type":"辨析题","stem":"“盘承短管和盘插短管都是法兰短管，拿哪个都一样。”这种说法对不对？","options":{"A":"错，盘承带承口、盘插带插口，拿反了装不上","B":"对，都是法兰短管","C":"对，只要口径对就行","D":"错，但可以现场改"},"answer":["A"],"explain":"调用【端头拿反是高频错】。盘承接纳插口，盘插插入承口；拿反了装不上，不能现场改。","multi":false},{"id":"C98-Q01","courseId":"C98","type":"单选","stem":"井内出现浑黄色积水，雨后水位明显上涨，最可能的成因是？","options":{"A":"管道接口渗漏","B":"地下水/雨水倒灌","C":"冷凝水结露","D":"排气阀排水"},"answer":["B"],"explain":"调用【渗漏类易混辨析】。浑水、雨后上涨是地下水/雨水倒灌的典型特征；管道接口渗漏多为清水，与降雨关联度低。","multi":false},{"id":"C98-Q02","courseId":"C98","type":"辨析题","stem":"“橡胶件漏水就一定是自然老化了，直接更换就行。”这种说法是否正确？","options":{"A":"正确，橡胶件用久了都会漏","B":"错误，外力破损、安装不当也会导致渗漏，要先区分成因","C":"正确，反正都要换不用查原因","D":"错误，橡胶件漏水都是安装问题"},"answer":["B"],"explain":"调用【老化类易混辨析】。橡胶渗漏分为自然老化、外力破损、安装不当三类，成因不同处置方式和责任不同，不能一概归为自然老化。","multi":false},{"id":"C98-Q03","courseId":"C98","type":"单选","stem":"下列哪种情形属于必须立即升级上报的重大缺陷？","options":{"A":"井盖表面轻微掉漆","B":"阀体表面有浮锈","C":"路面大量清水涌出、管道疑似破裂","D":"橡胶件表面有细微裂纹"},"answer":["C"],"explain":"调用【紧急情形识别】。管道大量漏水、路面涌水属于重大紧急隐患，必须立刻上报并现场管控；其余三项均为一般或较重缺陷。","multi":false},{"id":"C102-Q01","courseId":"C102","type":"单选","stem":"哪种材质的管道漏水声音衰减最快、听漏距离最短？","options":{"A":"球墨铸铁管","B":"钢管","C":"PE管","D":"不锈钢管"},"answer":["C"],"explain":"调用【不同材质管道漏声特征】。PE管是塑料管，管壁软、声音衰减快，漏声传播距离短，听漏排查需要缩小点位间距。","multi":false},{"id":"C102-Q02","courseId":"C102","type":"辨析题","stem":"“沿管线地面潮湿，就可以确定是管道暗漏。”这种说法是否正确？","options":{"A":"正确，沿管线走的水肯定是管道漏的","B":"错误，需要排除洒水、冷凝、地下水渗返等干扰因素","C":"正确，植被长得旺也能确定漏水","D":"错误，只有冒清水才是暗漏"},"answer":["B"],"explain":"调用【易混淆情形辨析】。地面潮湿只是疑似暗漏的征兆之一，必须先排除绿化洒水、冷凝水、地下水渗返、污水渗漏等干扰，才能判定为疑似暗漏。","multi":false},{"id":"C102-Q03","courseId":"C102","type":"排序题","stem":"疑似暗漏初步排查的正确顺序是？","options":{"A":"定位漏点→看地面征兆→排除假漏→上报","B":"排除假漏→看地面征兆→听漏排查→定位→上报","C":"看地面征兆→听漏排查→排除假漏→初步定位→上报","D":"听漏排查→看地面征兆→定位→排除假漏→上报"},"answer":["C"],"explain":"调用【暗漏排查全流程】。正确顺序是先观察地面征兆，再用工具听漏排查，接着排除各类假漏水情形，随后初步定位漏点范围，最后规范上报疑似缺陷。","multi":false},{"id":"C81-Q01","courseId":"C81","type":"单选","stem":"橡胶胶圈和机油桶放在同一货架，最直接的风险是","options":{"A":"橡胶溶胀失去弹性，密封失效","B":"机油会变浑浊失效","C":"橡胶会变硬变脆","D":""},"answer":["A"],"explain":"调用【橡胶件与油污混放】知识块。矿物油会使 EPDM 橡胶发生溶胀，永久丧失弹性和密封能力；B、C 表述均不符合实际后果。","multi":false},{"id":"C81-Q02","courseId":"C81","type":"单选","stem":"以下混放场景中，风险等级最高、必须优先整改的是","options":{"A":"碳钢螺栓挨着不锈钢箱体","B":"待检阀门和合格品阀门同货架混放","C":"塑料管上面堆着焊接弯头","D":""},"answer":["B"],"explain":"调用【风险分级与优先级】知识块。合格品与待检 / 呆滞料混放属于高风险，极易造成不合格件错发误用，引发质量事故；A、C 属于中 / 中高风险，后果严重程度更低。","multi":false},{"id":"C81-Q03","courseId":"C81","type":"排序题","stem":"发现混放问题后，正确的处置顺序是：①排查受损情况 ②隔离风险物料 ③优化分区规则 ④跟进整改验证","options":{"A":"①②③④","B":"②①④③","C":"②①③④","D":""},"answer":["C"],"explain":"发现混放后，先把风险物料隔离出来，避免继续相互污染或被错领；再排查受损情况，判断哪些物料已经受影响、影响多大；接着优化分区规则，把存放边界和标识补上，防止同类混放再次发生；最后跟进整改验证，确认隔离、分区和处置都做到位并留下记录。也就是“先控风险→再查损失→再建机制→最后闭环验证”。这对应本课学习要点第6条“权责清晰，日常巡检 + 分级上报 + 记录留痕”：不只处理当下异常，还要跟进结果、留痕闭环。","multi":false},{"id":"C88-Q01","courseId":"C88","type":"单选","stem":"以下哪项不符合物料替代的三大基本原则","options":{"A":"性能只升不降","B":"压力只高不低","C":"价格只低不高","D":"材质兼容"},"answer":["C"],"explain":"物料替代有三条铁则：性能只升不降、压力只高不低、材质兼容，A、B、D 都在这三条里。价格从来不是判断能不能替代的标准，更不能为了便宜就降低性能，那等于给工程埋质量隐患，所以 C 不符合。记住“性能、压力、材质”这三条底线，就是本课讲的替代基本原则。","multi":false},{"id":"C88-Q02","courseId":"C88","type":"多选","stem":"以下场景中，绝对禁止替代的有","options":{"A":"主干管高压段的核心承压管件","B":"直接接触饮用水的卫生级物料","C":"普通支管的截断阀门","D":"贸易结算用的计量水表"},"answer":["A","B","D"],"explain":"有四类场景是替代红线，再急也不能碰：承压核心件、卫生接触件、计量仪表，还有特殊功能阀门。A 是主干管高压段的核心承压管件，B 是直接接触饮用水的卫生级物料，D 是贸易结算用的计量水表，都落在红线上，绝对不能替。C 是普通支管的截断阀门，只要同功能、参数匹配，是可以合理替代的，不属于禁止范围。对照这几类红线逐一排除，就能分清“能替不能替”，这是本课的核心要点。","multi":true},{"id":"C88-Q03","courseId":"C88","type":"排序题","stem":"物料替代的正确操作顺序是：①审批登记 ②核对替代边界 ③查找现用替代件 ④确认原件参数","options":{"A":"④③②①","B":"①②③④","C":"②①③④","D":"③②④①"},"answer":["A"],"explain":"找替代件、办审批，你可以按这条线走：先确认原件的需求参数，再在公司现用物料里查找参数相等或更优的替代件，然后核对这个替代件是否符合替代原则、有没有触碰禁止红线，最后走审批、登记后发放，也就是④确认原件参数→③查找现用替代件→②核对替代边界→①审批登记。必须先查到件、核过参数，再去审批，顺序反了就说不清依据。这对应本课讲的“定参数→筛现用→核边界”查找路径和后续审批要求，照这个顺序做就不会乱。","multi":false},{"id":"C89-Q01","courseId":"C89","type":"单选","stem":"判断一个特殊场景是否合规，不需要看以下哪一项","options":{"A":"有没有制度依据","B":"有没有领导口头打招呼","C":"有没有越权操作","D":"有没有登记留痕"},"answer":["B"],"explain":"判断一个场景合不合规，你只要看三条：有没有制度依据（制度、审批签字、单据记录），有没有越权，有没有登记留痕能追溯到人和事。这三条就是合规三要素，A、C、D 分别对上了它们。B 的领导口头打招呼不算正式依据，也不能当放行理由，所以不需要看。记住“有依据、不越权、有留痕”，就是本课讲的合规判定方法。","multi":false},{"id":"C89-Q02","courseId":"C89","type":"多选","stem":"以下属于违规操作的有","options":{"A":"把应急特批当常态，经常先领后补单","B":"缺料时私自更换其他规格物料，事后再说","C":"没有权限的人签字审批同意发料","D":"按流程走特批后发放抢修物料"},"answer":["A","B","C"],"explain":"三种做法都是典型违规，你对照着记：把应急特批当常态、经常先领后补，最后账实混乱；缺料时私自换规格、不打招呼不登记，出了问题查不到原因；没有权限的人签字审批，责任界定不清。A、B、C 正对应这三种。D 按流程走特批后再发放，是合规操作，不属于违规。分清这条线，就是本课讲的违规风险辨析。","multi":true},{"id":"C89-Q03","courseId":"C89","type":"辨析题","stem":"一线工人要非现用物料，仓管员可以直接发给他，大不了事后补采购。","options":{"A":"正确，服务一线最重要","B":"错误，应优先推荐现用替代件，确需的走专项审批","C":"错误，直接拒绝，什么都不用解释","D":"—"},"answer":["B"],"explain":"一线要非现用物料，你既不能私自发放，也不能一句“不行”硬顶回去。先在现用物料里找参数更优的替代件推荐给对方；没有替代件的，就说明非现用件要走采购流程、不能直接发；确实紧急又必须用的，走专项特批，由技术和物资部门审批后再发。A 直接发突破了合规底线，C 什么都不解释，服务意识不足，都不对。B 的做法最稳妥。照“先查替代、再讲规则、必要时走特批”这三步处置，就是本课讲的非现用件申领处置。","multi":false},{"id":"C93-Q01","courseId":"C93","type":"单选","stem":"盘点时发现甲工地 DN100 PE 给水管盘亏 20 米，相邻乙工地同规格 PE 管盘盈 20 米，两边总数无偏差，该差异最可能的成因是？","options":{"A":"录入错误","B":"工地间借料未走系统调拨","C":"自然损耗","D":"计量偏差"},"answer":["B"],"explain":"同规格一盈一亏、总额互抵，且发生在相邻工地，是典型的工地间直接借料未走系统调拨手续，导致借出方盘亏、借入方盘盈，两边账面均失真。","multi":false},{"id":"C93-Q02","courseId":"C93","type":"排序题","stem":"面对一笔账实差异，正确的排查顺序是？","options":{"A":"时序排查→计量核查→领用闭环核查→串号库位核查→内控专项核查","B":"计量核查→时序排查→领用闭环核查→内控专项核查→串号库位核查","C":"领用闭环核查→时序排查→计量核查→串号库位核查→内控专项核查","D":"内控专项核查→时序排查→计量核查→领用闭环核查→串号库位核查"},"answer":["A"],"explain":"排查遵循从易到难、从常规到特殊的递进逻辑：先排除时点性差异，再核计量偏差，再查领用闭环，再核串号串库，最后开展内控专项核查。","multi":false},{"id":"C93-Q03","courseId":"C93","type":"多选","stem":"下列关于账实差异的处理方式，属于违规错误做法的有？","options":{"A":"自行修改系统库存数，把账凑平","B":"A 物料盘盈、B 物料盘亏，直接互相抵消找平","C":"小额差异金额太小，隐瞒不报自行消化","D":"差异核实后走审批流程进行账务调整"},"answer":["A","B","C"],"explain":"自行调账凑数、以盈补亏互抵、隐瞒小差异都属于盘点纪律红线；差异核实后按分级审批流程调整账务是合规做法。","multi":true},{"id":"C51-Q01","courseId":"C51","type":"单选","stem":"【冲突条件】夜间断管抢修、两端都只剩插口，天亮前要通水，只能发一根短管，有人提议拿双盘短管顶一下——断管后两端都只剩插口，应选哪种短管套入？","options":{"A":"双盘短管","B":"盲板","C":"盘插短管","D":"双承短管"},"answer":["D"],"explain":"调用【双承短管】。双承两端承口，分别接纳两根插口；双盘接法兰。 另见本课【断口 → 选件 查表】逐档 / 逐类核对，标准数值以现行标准与技术部门核定为准。","multi":false},{"id":"C51-Q02","courseId":"C51","type":"排序题","stem":"断管后两端均为插口，准备用双承短管抢修。请按接口辨识与安装顺序排序：①确认两端均为插口 ②选双承短管 ③清理并润滑承口和胶圈 ④两侧顶推到位","options":{"A":"③→①→②→④","B":"②→①→③→④","C":"①→②→③→④","D":"①→③→②→④"},"answer":["C"],"explain":"调用【先判断断口】。先确认断口，再选双承，清润滑，最后顶推；不能先拿件再猜断口。","multi":false},{"id":"C51-Q03","courseId":"C51","type":"单选","stem":"断管后阀门井一侧是法兰阀门、另一侧直管只剩承口，需要一根一端法兰接阀门、另一端插进承口的过渡短管。应选哪种？","options":{"A":"盘承短管","B":"盘插短管","C":"双承短管","D":"双盘短管"},"answer":["B"],"explain":"调用【盘插与盘承】。阀门侧固定法兰、直管侧剩承口时，用盘插短管（插口插进直管承口）；盘承是承口接纳插口，用于直管侧剩插口，别拿反。","multi":false},{"id":"C52-Q01","courseId":"C52","type":"单选","stem":"【冲突条件】月底盘点赶进度，一只短管外观很新但标签模糊、平台状态又不是现用，组长说「先签收、回头补流程」——库房盘点发现一只短管标签模糊、平台状态不是公司现用，但外观很新。按本课动作链，第一步应做什么？","options":{"A":"先签收再说","B":"直接发到工地","C":"查平台状态并挂签隔离待复核","D":"把标签改成现用"},"answer":["C"],"explain":"调用【先查平台状态】。非现用或标签模糊先隔离待复核，不先签收、不改标签。","multi":false},{"id":"C52-Q02","courseId":"C52","type":"多选","stem":"库房混放排查中，下列哪些属于本课讲的识伪线索？","options":{"A":"平台是否「公司现用」","B":"标签喷码与标准换版","C":"橡胶龟裂、塑料脆化、防腐破损","D":"外观很新就判定合格，无需查状态"},"answer":["A","B","C"],"explain":"调用【动作链】。状态、标签喷码、老化、规格混放才是识伪线索；「外观新就放行」恰是本课要防的偷懒做法，先签收后补流程会把非现用件放进施工。","multi":true},{"id":"C52-Q03","courseId":"C52","type":"单选","stem":"库房一只老管件名称与现用件一致，但橡胶龟裂、防腐层破损。按本课正确做法是？","options":{"A":"名称对就直接上架","B":"与新到货分区存放，按制度判定是否可用，不凭名称放行","C":"抹机油后复用","D":"改标签当新品"},"answer":["B"],"explain":"调用【看老化与防腐】。老化件（橡胶龟裂、防腐破损）要与新到货分区，按企业现行制度与卡面标准判定，不凭名称对就上架；本课不代为判退。","multi":false},{"id":"C56-Q01","courseId":"C56","type":"单选","stem":"【教学示例】夜间抢修急等关阀，井盖已打开，井内情况不明。你一个人先到场，第一步做什么？","options":{"A":"先探头闻一下，没异味就下井","B":"先设置围挡警示，再按企业制度启动票证监护、通风检测，合格后再下井","C":"让最瘦的人先下去试","D":"先下井快关快上"},"answer":["B"],"explain":"调用【开盖前确认与围挡】。第一步是设置围挡警示；呼救、作业票、监护、通风、检测是后续，不是先下井。A、D把有限空间当普通坑，C仍是无防护进入。严格执行国家最新相关作业标准及公司现行作业票制度。","multi":false},{"id":"C56-Q02","courseId":"C56","type":"单选","stem":"【教学示例】井内有人倒地，你一个人在场。第一步做什么？","options":{"A":"立即下井拉人","B":"先呼救报警并设置警戒，不盲目下井","C":"先探头下去看看","D":"等他自己爬出来"},"answer":["B"],"explain":"调用【异常与盲目施救】。A是盲目施救；C无防护进入；D延误。无防护不进入，呼救报警和警戒同步。严格执行国家最新相关作业标准及公司现行作业票制度。","multi":false},{"id":"C56-Q03","courseId":"C56","type":"排序题","stem":"井盖打开后、进入作业前，请按正确顺序排序：①设置围挡警示 ②按企业制度办理作业票并监护到位 ③通风 ④检测 ⑤检测合格后进入","options":{"A":"①→③→④→⑤→②","B":"②→①→③→④→⑤","C":"③→④→①→②→⑤","D":"①→②→③→④→⑤"},"answer":["D"],"explain":"调用【开盖前确认与围挡】【开盖后警戒】【通风】【检测】【作业票与监护】。D漏了作业票与监护；铁律是通风、检测、后作业，且进入前票证监护要到位。","multi":false},{"id":"C73-Q01","courseId":"C73","type":"单选","stem":"【冲突条件】一箱到货混装了 DN100 与 DN150 两种规格，外箱破损、喷码模糊，送货单只写了一个批次号，现场还催着发料。你第一步怎么做？","options":{"A":"先按送货单数量发料，规格回头再分","B":"先拍照发群等回复，暂不处置","C":"只把外箱破损的挑出来，其余照发","D":"先整箱隔离待检并挂标识，再物理分开逐项核"},"answer":["D"],"explain":"调用【先隔离还是先判依据】【标准换版与批次混装】【六类到货异常的识别】。批次混装、标签模糊、包装破损叠加，先控制现场：整箱隔离待检、挂标识，再物理分开逐项核；先发料或只挑破损件，异常件可能已流出。","multi":false},{"id":"C73-Q02","courseId":"C73","type":"排序题","stem":"到货异常处置顺序，下列哪一项正确？","options":{"A":"先上报→再隔离→再判→再核依据","B":"先判拒收→再隔离→再核依据→再留痕","C":"先隔离待检→核单据卡面标准状态→判合格/待检/拒收→留痕→上报复核","D":"先发料→再隔离→再补记录→再上报"},"answer":["C"],"explain":"调用【处置顺序与留痕闭环】。先隔离控制现场，再核依据，再判定，再留痕，最后上报复核；顺序不能倒。","multi":false},{"id":"C73-Q03","courseId":"C73","type":"辨析题","stem":"“到货异常先判拒收，再慢慢隔离也不迟。”这种说法对不对？","options":{"A":"对，先判后隔离一样","B":"对，拒收就是隔离","C":"错，先隔离控制现场再判依据，避免异常件被领走","D":"错，但可以先发料再补"},"answer":["C"],"explain":"调用【先隔离还是先判依据】【拒收与待检的区分】。隔离是现场控制，拒收是判定；先判后隔离，异常件可能已被领走。","multi":false},{"id":"C99-Q01","courseId":"C99","type":"单选","stem":"第三方施工工地周边管线巡检，最核心的任务是？","options":{"A":"检查路面卫生","B":"防止机械挖坏管道，旁站监督作业","C":"统计施工人数","D":"核对施工工期"},"answer":["B"],"explain":"调用【第三方施工旁站巡检】。第三方施工段巡检的核心是防管道破坏，必须对机械开挖作业旁站监督，及时制止危险操作，避免挖爆管。","multi":false},{"id":"C99-Q02","courseId":"C99","type":"多选","stem":"缺陷上报时常见的错误有哪些？","options":{"A":"选错对应材料卡","B":"缺陷描述模糊笼统","C":"照片只有特写无全景","D":"缺陷等级错报"},"answer":["A","B","C","D"],"explain":"调用【常见上报错误避坑】。材料卡选错、描述模糊、照片无效、等级错报都是上报时的高频错误，四项均会影响后续处置效率和准确性。","multi":true},{"id":"C99-Q03","courseId":"C99","type":"辨析题","stem":"“缺陷上报给调度之后，巡检员就不用管了。”这种说法是否正确？","options":{"A":"正确，上报就是完成任务","B":"错误，还要跟进整改进度、整改后复查销号","C":"正确，维修是别人的事","D":"错误，要亲自去维修"},"answer":["B"],"explain":"调用【隐患跟进与闭环】。巡检员需对上报的缺陷跟进闭环，核实整改进度、整改后复查销号，不能一报了之。","multi":false},{"id":"C103-Q01","courseId":"C103","type":"单选","stem":"冬季发现阀门冻住转不动，正确的做法是？","options":{"A":"用扳手强行拧开","B":"用明火烤化冰块","C":"用温水缓慢解冻","D":"直接砸开阀门"},"answer":["C"],"explain":"调用【冻胀缺陷识别】。阀门冻住严禁硬拧、明火烤，正确做法是用温水缓慢解冻，硬拧会拧断阀杆，明火易引发火灾和管道损伤。","multi":false},{"id":"C103-Q02","courseId":"C103","type":"多选","stem":"汛期雨后需要重点排查的缺陷有？","options":{"A":"接口渗漏","B":"井室塌陷","C":"防腐层冲刷损坏","D":"螺栓加速锈蚀"},"answer":["A","B","C","D"],"explain":"调用【汛后缺陷排查】。汛后雨水浸泡会导致接口渗漏、井室塌陷、防腐冲刷、螺栓锈蚀加速，四项都是雨后排查重点。","multi":true},{"id":"C103-Q03","courseId":"C103","type":"辨析题","stem":"“汛期低洼路段的井盖被冲走了，在旁边放个树枝警示就行，不用守现场。”这种说法是否正确？","options":{"A":"正确，路人能看见就行","B":"错误，必须设置围挡警示并留人值守，防止坠落事故","C":"正确，雨停了再换井盖","D":"错误，直接把井口填上"},"answer":["B"],"explain":"调用【汛期防汛巡检】。井盖缺失属于重大安全隐患，必须设置规范围挡警示并安排人员值守，仅放树枝起不到有效警示作用，极易发生坠落事故。","multi":false},{"id":"C82-Q01","courseId":"C82","type":"单选","stem":"超期存放的橡胶密封件，正确的处置方式是","options":{"A":"看着完好就直接发放使用","B":"直接扔掉，不用走流程","C":"复检性能，合格则复用，不合格则报废","D":""},"answer":["C"],"explain":"调用【处置路径规则】知识块。超期物料必须经过性能复检，合格的办理手续后可复用，不合格的走报废流程；A 属于违规操作，B 不符合管理流程。","multi":false},{"id":"C82-Q02","courseId":"C82","type":"辨析题","stem":"工程剩余的短尺 PE 管属于边角余料，随便堆在角落就行，不用入账。","options":{"A":"正确，反正都是剩下的零碎料","B":"错误，余料也要纳入呆滞管理，登记台账","C":"错误，余料必须直接报废处理","D":""},"answer":["B"],"explain":"调用【呆滞料定义与分级】知识块。工程余料属于呆滞物料四大类之一，必须统一管理、登记台账、规范处置；A 属于管理疏漏，C 表述过于绝对。","multi":false},{"id":"C82-Q03","courseId":"C82","type":"单选","stem":"呆滞隔离区的核心要求是","options":{"A":"随便找个角落堆着就行","B":"物理隔离、标识清晰、专人管理","C":"和合格品放一起，贴个标签就行","D":""},"answer":["B"],"explain":"调用【隔离区设置要求】知识块。呆滞隔离区必须做到物理隔离、明确标识、专人管理，防止错领误用；A、C 均不符合管理要求，存在质量风险。","multi":false},{"id":"C83-Q01","courseId":"C83","type":"单选","stem":"雨季库房防潮，以下做法错误的是","options":{"A":"阴雨天气开窗通风","B":"启动除湿设备控湿","C":"物料垫高离地","D":""},"answer":["A"],"explain":"调用【雨季防潮专项】知识块。雨季室外空气湿度更高，开窗会让潮气大量进入库区，加剧物料锈蚀；B、C 均为正确的防潮措施。","multi":false},{"id":"C83-Q02","courseId":"C83","type":"单选","stem":"冬季低温环境下搬运橡胶密封件，需要注意什么","options":{"A":"可以随意抛摔，低温下橡胶更结实","B":"轻拿轻放，低温下橡胶变脆易裂","C":"用火烤一下，增加柔韧性","D":""},"answer":["B"],"explain":"调用【冬季防冻专项】知识块。低温下橡胶分子链变硬、韧性下降，抛摔容易造成开裂，必须轻拿轻放；A、C 均为错误操作，用火烤会直接损坏橡胶性能。","multi":false},{"id":"C83-Q03","courseId":"C83","type":"排序题","stem":"极端暴雨即将来临，库房正确的应对顺序是：①转移低洼处贵重物料 ②检查排水系统 ③人员撤离到安全区域 ④关闭门窗做好挡水","options":{"A":"②①④③","B":"①②③④","C":"④②①③","D":""},"answer":["A"],"explain":"题干说的是极端暴雨“即将来临、尚未成灾”的预警阶段，在确保人员安全的前提下，先做防护性准备：②检查排水系统，排除堵塞和倒灌隐患；①转移低洼处贵重物料，减少可能被淹损失；④关闭门窗做好挡水，阻止雨水进入库区；当险情触发或水位逼近、继续防护有危险时，立即执行③人员撤离到安全区域。若险情已至，人员撤离为第一优先，本排序针对预警阶段的准备顺序。","multi":false},{"id":"C94-Q01","courseId":"C94","type":"单选","stem":"年度全面盘点期间，因管网抢修急需领用一批哈夫节，正确的处理方式是？","options":{"A":"直接领用，不用登记，盘点完再说","B":"单独登记领用信息，单独核算，不纳入盘点基准库存","C":"禁止任何领用，抢修也不能动","D":"领用完直接修改盘点表数量"},"answer":["B"],"explain":"年度盘点原则上冻结库存停止出入库；确有紧急抢修等收发需求的，需单独登记、单独核算，不纳入盘点基准库存，避免干扰盘点结果。","multi":false},{"id":"C94-Q02","courseId":"C94","type":"辨析题","stem":"“历史遗留差异因为时间太久找不到原因，可以一直挂在账上不用处理。” 这种说法是否正确？","options":{"A":"正确，找不到原因就不用管","B":"错误，需定期清理，无法追溯的按流程审批后核销","C":"正确，处理了会影响当期利润","D":"错误，必须由仓管员全额赔偿"},"answer":["B"],"explain":"历史遗留差异需定期清理，确实无法追溯原因的，需附专项核查报告，按企业资产核销流程审批后规范处理，不得长期挂账悬而不决。","multi":false},{"id":"C94-Q03","courseId":"C94","type":"多选","stem":"盘点后的整改闭环管理，包含以下哪些核心环节？","options":{"A":"深挖差异根本原因","B":"制定可落地的整改措施并落实到人","C":"验证整改效果，固化为制度流程","D":"调完账就结束，不需要后续跟进"},"answer":["A","B","C"],"explain":"完整的 PDCA 闭环包含原因分析、整改措施、责任落实、效果验证、预防优化五个环节；仅调账不跟进无法从根源改善管理，盘点价值会大打折扣。","multi":true},{"id":"C104-Q01","courseId":"C104","type":"单选","stem":"库管员把现场设备按功能归类。下列哪一项最准确地描述了「先导式减压阀」的主要任务？","options":{"A":"限制管内反向流动","B":"控制阀后出口压力","C":"排出管内积聚空气","D":"拦截水中颗粒杂质"},"answer":["B"],"explain":"对应课程【按功能建立阀门族谱】。先导式减压阀属于调节类设备，核心任务是控制出口压力；A是止回/防倒流设备的相关任务，C属于排气设备，D属于过滤器。","multi":false},{"id":"C104-Q02","courseId":"C104","type":"多选","stem":"巡检与库房核对时，下列哪些应归入阀门本体或阀门功能设备，而不是普通仪表、过滤附件或消防供水设施？","options":{"A":"弹性座封闸阀（暗杆式）","B":"压力表","C":"先导式减压阀","D":"复合式排气阀"},"answer":["A","C","D"],"explain":"对应课程【阀门功能族】及【监测与配套设施】。A为截断阀，C为调节阀，D为排气阀；B压力表只监测压力，不是阀门本体。","multi":true},{"id":"C104-Q03","courseId":"C104","type":"单选","stem":"现场台账把一只阀门标注为“电动、加密”。按本课分类，这两个词主要描述什么？","options":{"A":"两个不同的水力功能","B":"阀门的公称压力等级","C":"阀门的连接方式与口径","D":"驱动方式或授权控制属性"},"answer":["D"],"explain":"对应课程【按结构与驱动识别】。电动描述执行机构驱动，加密描述启闭授权控制；二者不能替代截断、调节、止回等功能分类。","multi":false},{"id":"C105-Q01","courseId":"C105","type":"多选","stem":"对照闸阀、蝶阀、球阀及加密驱动结构，下列哪些说法正确？","options":{"A":"弹性座封闸阀（暗杆式）的阀杆旋转但不随行程升降","B":"中线（软密封）蝶阀通过蝶板旋转改变流通状态","C":"黄铜内螺纹浮动球阀应按闸阀多圈行程判断全开位置","D":"加密闸阀手轮空转时，应先核对钥匙与锁芯适配关系"},"answer":["A","B","D"],"explain":"对应课程【闸阀结构】【蝶阀结构】【球阀结构】【加密驱动】。A、B、D分别符合暗杆传动、蝶板旋转和加密解锁特点；C错误，浮动球阀通常以约90°旋转切换通道，不能套用闸阀多圈经验。","multi":true},{"id":"C105-Q02","courseId":"C105","type":"单选","stem":"接到片区阀门操作任务后，现场编号与调度指令中的编号不一致。按标准化启闭逻辑，第一步应当怎样处理？","options":{"A":"先操作现场最近的一只阀门，再补核编号","B":"按手轮圈数估算目标阀门并继续操作","C":"暂停动作，核实设备身份、位置和指令对应关系","D":"请旁边人员确认外观相似后直接操作"},"answer":["C"],"explain":"对应课程【操作前核对】。对象身份不一致会导致误关阀和扩大停水，必须先核实编号、位置、阀型及管网关系，不能凭距离、圈数或外观替代确认。","multi":false},{"id":"C105-Q03","courseId":"C105","type":"单选","stem":"一只电动蝶阀完成动作后，控制界面显示“关到位”。要确认本次操作结果，哪种做法最完整？","options":{"A":"只保存控制界面的到位截图","B":"核对现场阀位反馈，并观察相关测点压力、流量及下游供水反馈","C":"以执行机构运行时间达到历史平均值作为完成依据","D":"听到电机停止声即可确认管段完全隔离"},"answer":["B"],"explain":"对应课程【操作后结果确认】。机械位置反馈与管网水力结果是两类证据，需结合压力、流量和下游反馈；运行时间、声音或单张截图都不能单独证明隔离成功。","multi":false},{"id":"C106-Q01","courseId":"C106","type":"多选","stem":"关于减压、止回、排气和监测设备的职责，下列哪些说法正确？","options":{"A":"压力表可根据指针变化自动调节阀后压力","B":"旋启式止回阀通过阀瓣摆动限制反向流动","C":"复合式排气阀兼顾大量排气与微量排气等不同阶段","D":"法兰Y型过滤器通过滤网拦截杂质，堵塞可能增加局部阻力"},"answer":["B","C","D"],"explain":"对应课程【止回阀】【排气阀】【过滤器】【压力监测】。B、C、D分别符合单向控制、复合排气和杂质拦截原理；A错误，压力表只提供测点读数，不执行调压。","multi":true},{"id":"C106-Q02","courseId":"C106","type":"单选","stem":"某减压阀下游压力偏低，现场同时发现过滤器前后运行状态异常。哪一种判断更符合本课的设备组合思路？","options":{"A":"直接调高减压阀设定值，不必检查过滤器","B":"先确认测点和仪表有效性，再核查过滤器阻塞及阀前阀后压力","C":"把压力表拆下后即可判断减压阀是否失灵","D":"将止回阀替换为闸阀即可恢复出口压力"},"answer":["B"],"explain":"对应课程【设备组合与异常初筛】。过滤器堵塞可能增加局部压降，压力异常还需核对测点、仪表和阀前阀后状态；直接调设定值或替换设备缺乏证据。","multi":false},{"id":"C106-Q03","courseId":"C106","type":"单选","stem":"一个节点存在较高的污染水回流风险，同时需要评估防护结构。按材料卡的设备边界，哪一项更适合优先纳入高风险防护评估？","options":{"A":"低阻力倒流防止器","B":"普通旋启式止回阀","C":"减压型倒流防止器","D":"法兰Y型过滤器"},"answer":["C"],"explain":"对应课程【倒流防止器的污染防护】。减压型倒流防止器具有两级止回和中腔泄水等防护结构；低阻力型强调降低水损，不能作为高风险边界的通用替代。","multi":false},{"id":"C107-Q01","courseId":"C107","type":"多选","stem":"进行片区运行状态分析时，下列哪些数据与设备用途对应正确？","options":{"A":"压力表读数用于描述对应测点压力","B":"旋翼式机械水表记录累计通过水量","C":"阀门开度变化可能改变局部阻力，但不等于流量按同一比例变化","D":"过滤器滤网堵塞可能增加局部阻力并影响下游运行状态"},"answer":["A","B","C","D"],"explain":"对应课程【管网水力变量】【压力调节与监测】【水锤与空气风险】。四项均成立：压力、累计水量、阀门局部阻力和过滤器阻力分别提供不同运行信息，分析时需结合时间、位置和管网结构。","multi":true},{"id":"C107-Q02","courseId":"C107","type":"单选","stem":"同一片区准备停水，管网图显示存在联络管和备用供水路径。哪种做法最符合停水边界确认原则？","options":{"A":"按离事件点最近的两只阀门直接关断","B":"套用上一个片区的固定启闭顺序","C":"先关所有分区阀，再逐步恢复","D":"核对联络管、备用路径、重点用户和消防供水后，按调度方案确定阀门组合"},"answer":["D"],"explain":"对应课程【分区与阀门边界】【片区停水控制逻辑】。隔离边界由拓扑和调度目标决定，必须核查绕供路径和供水影响，不存在通用固定启闭顺序。","multi":false},{"id":"C107-Q03","courseId":"C107","type":"单选","stem":"阀门快速启闭后，管道出现短时压力冲击和振动。最符合本课的机理解释是哪一项？","options":{"A":"水温短时间升高导致管材膨胀","B":"水流速度快速变化形成压力波，并沿管线传播","C":"压力表弯改变了管道的公称直径","D":"水表累计读数增加直接造成压力升高"},"answer":["B"],"explain":"对应课程【水锤与空气风险】。水锤与水流速度快速变化有关，压力扰动会沿管道传播，可能引起振动、噪声和接口冲击；其他选项不能解释该类瞬态压力波。","multi":false},{"id":"C108-Q01","courseId":"C108","type":"多选","stem":"【冲突条件】一只暗杆式闸阀操作时阻力突然增大，现场有人提出接长钢管加力关到底。为避免把异常扩大成设备损坏，下列哪些做法合理？","options":{"A":"停止强行操作，记录阻力出现的阶段和伴随现象","B":"继续加长力臂，利用多人同时施力克服阻力","C":"核对阀型、驱动接口及外部可见卡阻情况","D":"结合上下游压力、阀门状态和管网关系向调度反馈"},"answer":["A","C","D"],"explain":"对应课程【开不动与关不严的原因辨析】。A、C、D分别完成停止、结构核对和运行证据收集；B会放大阀杆、闸板或传动件损伤风险，不能作为诊断方法。","multi":true},{"id":"C108-Q02","courseId":"C108","type":"单选","stem":"某阀门显示已关闭，但阀后压力仍持续存在。尚未确认旁通和联络管状态时，最合理的首轮辨析方向是什么？","options":{"A":"直接认定阀座损坏并安排拆阀","B":"连续反复启闭，直到压力表归零","C":"先核对测点、残余压力、旁通及其他供水路径，再判断阀门隔离效果","D":"用加长扳手再多关几圈"},"answer":["C"],"explain":"对应课程【关不严与管网未隔离辨析】。阀后有压可能来自残余水、旁通、联络管或其他供水路径，不能直接归因于阀座失效，更不能用强行操作代替证据核查。","multi":false},{"id":"C108-Q03","courseId":"C108","type":"辨析题","stem":"【冲突条件】电动蝶阀控制界面显示“全关到位”，现场人员据此认定阀门密封严密、下游已经完全隔离。以下判断哪项最准确？","options":{"A":"判断成立，控制界面到位即可证明阀座密封","B":"判断不成立，还需核对现场阀位、执行机构反馈及相关压力/流量结果","C":"判断成立，只要电机停止就说明阀板已经压紧阀座","D":"判断不成立，但只需再看一次控制界面即可"},"answer":["B"],"explain":"对应课程【加密与电动阀故障辨析】【外漏、内漏与管网未隔离辨析】。到位信号只能说明控制/行程反馈达到某状态，不能单独证明密封严密或管段隔离成功，必须结合现场和水力证据。","multi":false},{"id":"C109-Q01","courseId":"C109","type":"多选","stem":"【冲突条件】某分区压力和流量同时下降，上游压力表读数暂时正常。为避免把原因简单归结为“减压阀设定过低”，哪些核查方向合理？","options":{"A":"核对压力表测点、量程、采集时间及读数有效性","B":"比较上游、下游和相邻节点的压力/流量变化","C":"未经授权先调整减压阀设定值，观察是否恢复","D":"检查分区阀位、过滤器状态、供水路径及用户需求变化"},"answer":["A","B","D"],"explain":"对应课程【异常识别与数据有效性】【压力偏高与偏低辨析】【流量异常与管网路径辨析】。A、B、D能形成数据、空间和设备交叉验证；C在证据不足且未获授权时先调设定值，可能掩盖原因并造成新的压力异常。","multi":true},{"id":"C109-Q02","courseId":"C109","type":"单选","stem":"某高点管段出现流量受限和间歇性压力波动，现场尚未核查排气设施。哪一项是更完整的首轮辨析方向？","options":{"A":"直接把减压阀出口设定调高","B":"核查高点积气可能、排气设备状态，并同步比较相邻测点压力和流量","C":"只检查下游用户水龙头是否堵塞","D":"把旋启式止回阀拆开观察阀瓣"},"answer":["B"],"explain":"对应课程【气阻与排气设备辨析】。高点积气可能影响有效过水断面并引起波动，应结合排气设备状态和相邻测点数据判断；不应在证据不足时擅调或拆卸承压设备。","multi":false},{"id":"C109-Q03","courseId":"C109","type":"单选","stem":"巡检发现某节点水质异常，同时该节点与其他供水区域存在联络管。按本课风险响应边界，首先应重视什么？","options":{"A":"先把异常水排放一段时间，再决定是否报告","B":"只关闭最近的一只阀门，不必核查回流路径","C":"先更换普通止回阀，随后直接恢复供水","D":"及时报告并核实可能污染路径、倒流防护状态和影响范围，按预案处理"},"answer":["D"],"explain":"对应课程【水质异常与调度响应边界】。水质异常涉及供水安全，需及时报告、核查污染路径和防护设施，并按主管部门要求及企业预案确定隔离、检测和恢复程序。","multi":false},{"id":"C110-Q01","courseId":"C110","type":"多选","stem":"【情境示例｜时间压迫】某片区突发大量漏水，调度要求尽快控制影响范围；管网图显示隔离区内还连有一处消防供水节点。制定阀门隔离响应时，哪些动作应纳入方案？","options":{"A":"为抢时间，先关闭所有能找到的分区阀，再评估停水范围","B":"核实事件位置、管网拓扑、联络管和可能的替代供水路径","C":"评估最小有效隔离边界及对消防、重点用户的影响","D":"按授权方案实施受控动作，并用阀位、压力、流量和区域反馈验证"},"answer":["B","C","D"],"explain":"对应课程【管网拓扑与隔离边界】【最小有效隔离原则】【消防与重点用户供水协调】【隔离验证】。B、C、D构成核实、评估、执行验证链；A会在未评估前扩大停水范围，可能影响消防和重点用户。","multi":true},{"id":"C110-Q02","courseId":"C110","type":"排序题","stem":"【情境示例｜时间压迫】一次管网异常需要实施阀门隔离。请按“先核实、再评估、后授权动作、最后验证反馈”的逻辑排列：①核实事件位置与信息来源；②核对管网拓扑、联络管和替代供水路径；③评估风险、停水范围及消防/重点用户影响；④形成最小有效隔离方案并确认授权；⑤按方案受控操作并监测；⑥验证结果、反馈并记录。","options":{"A":"①→②→③→④→⑤→⑥","B":"①→④→②→⑤→③→⑥","C":"②→①→④→③→⑥→⑤","D":"①→②→⑤→④→③→⑥"},"answer":["A"],"explain":"对应课程【应急信息核实】【隔离边界判定】【多阀协同】【隔离验证】。正确链条先核实事实与拓扑，再评估风险和影响，随后形成方案并确认授权，最后实施、验证和反馈；不能先动作后补方案。","multi":false},{"id":"C110-Q03","courseId":"C110","type":"辨析题","stem":"【情境示例｜时间压迫】隔离方案可能影响一处地下式消火栓。现场人员说：“消火栓不是阀门，所以不用纳入阀门隔离方案评估。”以下判断哪项正确？","options":{"A":"判断成立，只有阀门本体才需要纳入隔离影响分析","B":"判断不成立，消火栓属于消防供水设施，必须评估供水影响，但不能把它归类为阀门本体","C":"判断成立，地下式消火栓不属于供水管网","D":"判断不成立，因此应把消火栓直接当作截断阀操作"},"answer":["B"],"explain":"对应课程【消防与重点用户供水协调】。地下式消火栓是消防供水设施，不是阀门本体，但其供水状态可能受隔离方案影响，必须纳入影响评估；不能因此把它当作截断阀操作。","multi":false},{"id":"C111-Q01","courseId":"C111","type":"多选","stem":"【冲突条件｜时间压迫】复水窗口临近，执行人员只在群里回复“已完成”，未记录阀门编号，也未核对压力变化。要形成可追溯闭环，哪些信息应补齐？","options":{"A":"操作指令来源、目标、授权及对应版本","B":"阀门编号、名称、位置、实际动作和完成时间","C":"只保留“已完成”三个字，避免记录过多影响效率","D":"阀位反馈、相关压力/流量变化、异常情况及后续待办"},"answer":["A","B","D"],"explain":"对应课程【记录、交接与异常闭环】【结果确认与运行验证】。A、B、D分别补齐指令、对象动作和结果证据；C无法还原操作对象、过程和结果，不具备追溯性。","multi":true},{"id":"C111-Q02","courseId":"C111","type":"排序题","stem":"【情境示例｜时间压迫】复水窗口临近，有人建议先操作阀门、之后再补核对象和授权。为避免顺序倒置，请排列管理闭环：①接收并核实指令及授权；②核对阀门对象、位置和管网关系；③检查现场条件、工具和通信；④按阀型与调度方案受控操作；⑤核对阀位、压力/流量和供水结果；⑥记录、反馈并交接未完成事项。","options":{"A":"①→②→③→④→⑤→⑥","B":"②→④→①→③→⑤→⑥","C":"①→③→④→②→⑥→⑤","D":"③→①→②→⑤→④→⑥"},"answer":["A"],"explain":"对应课程【指令接收与授权】【操作前准备】【操作过程控制】【结果确认】【记录交接】。先确认指令与对象，再完成准备，随后受控操作、验证结果并形成记录；不能先操作后补授权。","multi":false},{"id":"C111-Q03","courseId":"C111","type":"辨析题","stem":"【冲突条件｜时间压迫】临近班组交接，有人建议把所有阀门统一设定为“每6个月必须操作一次”，直接写入台账。以下判断哪项最符合本课管理边界？","options":{"A":"判断正确，所有阀门都应使用统一操作周期","B":"判断正确，只要写入台账就可以代替设备说明","C":"判断不成立，维护频次应结合设备说明、运行状态和公司正式制度确定，课程不代设统一周期","D":"判断不成立，因此阀门无需维护或状态跟踪"},"answer":["C"],"explain":"对应课程【运行维护与制度衔接】。维护频次不能由课程统一设定，应依据设备说明、运行条件和公司正式制度；不设统一周期不等于不维护，而是按适用依据执行。","multi":false},{"id":"C112-Q01","courseId":"C112","type":"单选","stem":"接报“某小区门口地面冒水，水柱约30cm，影响约200户”，按四类抢修边界，第一动作应是什么？","options":{"A":"先研究修复方案再派工","B":"按日常小修派单人过去看","C":"等上班后再安排","D":"按应急抢修止水控险，不先研究修复方案"},"answer":["D"],"explain":"调用四类抢修边界：明漏大水量、影响户数多=应急抢修，第一动作止水控险。A把修复前置到止水之前，B把应急当小修延误，C完全违背响应分级。","multi":false},{"id":"C112-Q02","courseId":"C112","type":"多选","stem":"关于抢修七步链路和“信息不全时的决策”，下列说法正确的有？","options":{"A":"现场止水优先于缺陷核实","B":"缺陷核实至少要判到管材、漏点形态、接口类型三层","C":"方案选型可以凭经验跳过，直接施工","D":"管材不明时，先按“不伤害管材”的保守方式止水"},"answer":["A","B","D"],"explain":"C错误：跳选型直接施工是返工首因；A、B、D均符合链路判据和信息不全最小安全决策。","multi":true},{"id":"C112-Q03","courseId":"C112","type":"排序题","stem":"接报DN300球铁管爆管，影响约200户，按四类边界和七步链路，以下动作的正确顺序是？①接单派工 ②围挡+关上游阀止水 ③核实管材和漏点 ④选哈夫节方案 ⑤施工 ⑥通水前三查 ⑦复盘","options":{"A":"①→③→②→④→⑤→⑥→⑦","B":"②→①→③→④→⑤→⑥→⑦","C":"①→②→③→④→⑤→⑥→⑦","D":"①→②→④→③→⑤→⑥→⑦"},"answer":["C"],"explain":"正确：派工→止水→核实→选型→施工→三查→复盘。A错在核实先于止水；B错在未派工先到场；D错在选型先于核实。","multi":false},{"id":"C113-Q01","courseId":"C113","type":"单选","stem":"球墨铸铁管承口周圈持续渗水、水量不大，最可能的漏损形态是？","options":{"A":"管身纵向裂缝","B":"承插接口胶圈渗漏","C":"防腐穿孔","D":"管身环向断裂"},"answer":["B"],"explain":"承口周圈持续渗水=胶圈渗漏最高发。管身裂缝/穿孔/断裂的水迹不在承口周圈。","multi":false},{"id":"C113-Q02","courseId":"C113","type":"多选","stem":"关于PE管热熔假焊的识别与后果，说法正确的有？","options":{"A":"热熔假焊外观可能完好，但内部融合强度不足","B":"假焊只影响外观，不影响承压","C":"冷却期间受扰动是假焊成因之一","D":"假焊是PE管暗漏的重灾区"},"answer":["A","C","D"],"explain":"B错误，假焊直接削弱承压；A、C、D为假焊判据和后果。","multi":true},{"id":"C113-Q03","courseId":"C113","type":"辨析题","stem":"“带压抢修时，只要漏量不大就可以带压，不用逐项核实压力和器材。”这种说法是否正确？","options":{"A":"正确，漏量不大就能带压","B":"错误，带压四项（压力、漏量、管材、器材压力等级）要逐项到现场确认，有一项拿不准就按停水处理","C":"正确，经验判断就够了","D":"错误，带压只需要看漏量"},"answer":["B"],"explain":"调用带压四项逐一核实：压力看表、漏量看水柱、管材看喷码、器材看压力等级，四项缺一不试。A、C、D把带压简化为“看漏量”一个条件。","multi":false},{"id":"C114-Q01","courseId":"C114","type":"单选","stem":"抢修器材通用工艺中，关于螺栓紧固，正确的做法是？","options":{"A":"对角交替、分2–3次逐步加力，外露丝扣2–3扣","B":"按顺时针顺序一次拧死一颗","C":"先拧紧一侧再拧另一侧","D":"力矩越大越好"},"answer":["A"],"explain":"通用螺栓三原则：对角交替、分2–3次、外露2–3扣。B/C导致胶垫偏位，D过度紧固损伤管件。","multi":false},{"id":"C114-Q02","courseId":"C114","type":"多选","stem":"通水前三查包括哪些内容？","options":{"A":"直接满压通水可以快速检验密封性","B":"外观：壳体、螺栓、密封件到位无缺件","C":"渗漏：先低压后升压，各密封面无滴漏","D":"设施复位：阀门、井盖、标识恢复"},"answer":["B","C","D"],"explain":"A错误：直接满压通水会掩盖隐性渗漏；B、C、D为三查内容。","multi":true},{"id":"C114-Q03","courseId":"C114","type":"排序题","stem":"器材通用工艺的合理顺序是：①清理密封面 ②对角分次紧固 ③通水前三查 ④收尾场清","options":{"A":"②→①→③→④","B":"③→①→②→④","C":"④→②→①→③","D":"①→②→③→④"},"answer":["D"],"explain":"正确顺序：清面→紧固→三查→收尾。顺序颠倒会导致密封失效或漏检。","multi":false},{"id":"C115-Q01","courseId":"C115","type":"单选","stem":"有限空间作业必须遵守的顺序是？","options":{"A":"先作业→再通风→后检测","B":"先检测→再通风→后作业","C":"先通风→再检测→后作业","D":"直接下井→有事再撤"},"answer":["C"],"explain":"有限空间三铁律：先通风、再检测、后作业，顺序不可反。A、B顺序错误，D严重违章。","multi":false},{"id":"C115-Q02","courseId":"C115","type":"多选","stem":"关于有限空间作业的检测、记录和复工，正确的有？","options":{"A":"作业前机械通风不少于30分钟","B":"气体检测实行上、中、下分层检测","C":"作业过程中气体数据每15分钟记录一次","D":"作业中断超过30分钟，复工前重新通风、重新检测"},"answer":["A","B","C","D"],"explain":"四项均为有限空间作业实操判据：通风不少于30分钟、分层检测、15分钟记录、30分钟中断重测。全选。","multi":true},{"id":"C115-Q03","courseId":"C115","type":"辨析题","stem":"“夜间抢修只要有灯、能看见就行，警示距离不用管。”这种说法是否正确？","options":{"A":"正确，有灯就够了","B":"正确，警示灯随便摆","C":"错误，作业面照度要能看清螺栓螺纹和压力表刻度，警示灯距作业区不少于50m，弯道坡道提前到100m","D":"错误，夜间不用反光衣"},"answer":["C"],"explain":"调用夜间照明与警示判据：照度看清螺纹、警示距≥50m、弯道坡道100m、反光衣前后都有条。A、B、D均把夜间安全简化为“有灯就行”。","multi":false},{"id":"C116-Q01","courseId":"C116","type":"单选","stem":"接单时影响户数信息缺失，最应该做的是？","options":{"A":"直接出发，到了再看","B":"按最小规模派一个人","C":"等用户再打一次","D":"回拨确认影响户数再派工"},"answer":["D"],"explain":"影响户数决定响应等级和关阀范围，缺项回拨确认。A导致资源错配，B可能延误应急，C被动等待。","multi":false},{"id":"C116-Q02","courseId":"C116","type":"多选","stem":"到场前材料预配的正确做法有？","options":{"A":"按管材和漏点形态配主件+辅件","B":"主辅件分袋标记，到场不翻找","C":"只带主件，辅件到了再找","D":"关键工具到场前逐件试运转"},"answer":["A","B","D"],"explain":"C错误：只带主件到场常因缺胶垫/螺栓返工；A、B、D为正确预配。","multi":true},{"id":"C116-Q03","courseId":"C116","type":"排序题","stem":"到场前准备的合理顺序是：①接单六问 ②初判管材漏点 ③配主辅件和工具 ④信息回传","options":{"A":"①→②→③→④","B":"②→①→③→④","C":"③→①→②→④","D":"④→②→①→③"},"answer":["A"],"explain":"正确：问清→初判→配材料工具→回传。先配后判会带错主件。","multi":false},{"id":"C117-Q01","courseId":"C117","type":"单选","stem":"暗漏定位最实用的组合判据是？","options":{"A":"只看地面有没有水","B":"直接大面积开挖","C":"听音+压力下降+附近阀门井水迹","D":"只问用户"},"answer":["C"],"explain":"暗漏定位：听音、压力下降、井内水迹三点互证。A/B/D信息不足或成本过高。","multi":false},{"id":"C117-Q02","courseId":"C117","type":"多选","stem":"管材快速识别的线索包括？","options":{"A":"管身喷码","B":"颜色和标线","C":"端头连接形式","D":"只听用户描述就够了"},"answer":["A","B","C"],"explain":"D不够，还要看内衬或焊缝，且不能只凭描述。","multi":true},{"id":"C117-Q03","courseId":"C117","type":"排序题","stem":"漏点定位与初判止水点的顺序是：①围挡 ②明漏看/暗漏听 ③认管材 ④初判上游可控阀","options":{"A":"②→①→③→④","B":"①→②→③→④","C":"③→②→①→④","D":"④→③→②→①"},"answer":["B"],"explain":"正确：先围挡再探漏，再认管材，最后初判止水点。","multi":false},{"id":"C118-Q01","courseId":"C118","type":"单选","stem":"堵漏楔止水的正确操作是？","options":{"A":"正对水柱直接硬塞","B":"只用手推入","C":"用铁锤猛砸","D":"先关阀，用木锤将略大的木楔侧向嵌入孔洞"},"answer":["D"],"explain":"堵漏楔判据：先关阀、木楔侧向嵌入、利用遇水膨胀。A危险，B塞不紧，C易碎楔。","multi":false},{"id":"C118-Q02","courseId":"C118","type":"多选","stem":"关于临时补漏的边界，正确的有？","options":{"A":"AB胶只用于小砂眼、细微裂缝","B":"临时补漏可以管一个季度不用管","C":"临时抱箍控险后必须安排永久修复","D":"临时补漏后标记并跟进永久修复"},"answer":["A","C","D"],"explain":"B错误：临时补漏只控险，不能管一个季度；A、C、D为正确边界。","multi":true},{"id":"C118-Q03","courseId":"C118","type":"辨析题","stem":"“临时补漏当时不漏，就可以不再管了。”这种说法是否正确？","options":{"A":"错误，临时补漏只控险，必须标记并安排永久修复","B":"正确，不漏就是修好","C":"正确，AB胶是永久修复","D":"错误，只有钢管需要永久修复"},"answer":["A"],"explain":"临时只要求短期可靠，后续必须永久修复。B、C、D均把临时当永久。","multi":false},{"id":"C119-Q01","courseId":"C119","type":"单选","stem":"消火栓更换后复位，只打开一个出水口试水、出水顺畅就收工，是否正确？","options":{"A":"正确，一个口出水正常就够","B":"错误，应逐个出水口试水，看“出水顺、关后不漏、接口无渗”","C":"正确，地下式消火栓不用试水","D":"错误，消火栓不需要试水"},"answer":["B"],"explain":"只试一个口不能代表其他出水口和接口密封合格；逐个试水才是复位合格判据。","multi":false},{"id":"C119-Q02","courseId":"C119","type":"多选","stem":"关于消火栓抢修和井盖复位，正确的有？","options":{"A":"消火栓复位后只试一个出水口即可","B":"消火栓更换前关上游阀泄压","C":"地下式消火栓用专用扳手开井盖","D":"井盖踩上去有晃动或异响，先调平井座、补减震胶条，再复位"},"answer":["B","C","D"],"explain":"A错误：应逐个出水口试水；B、C、D为正确判据。","multi":true},{"id":"C119-Q03","courseId":"C119","type":"排序题","stem":"附属设施抢修顺序是：①围挡通风 ②关上游阀 ③查本体 ④换件复位观察","options":{"A":"②→①→③→④","B":"①→②→③→④","C":"③→①→②→④","D":"①→③→②→④"},"answer":["B"],"explain":"正确：先围挡通风，再关上游阀，查本体，换件复位观察。","multi":false},{"id":"C120-Q01","courseId":"C120","type":"单选","stem":"螺纹接口缠生料带，正确的做法是？","options":{"A":"逆螺纹随便缠","B":"缠越厚越好","C":"顺螺纹方向缠，留第一扣不缠","D":"不用缠直接拧"},"answer":["C"],"explain":"顺螺纹缠、留第一扣防碎屑进表。A方向反会漏，B撑裂嵌件，D密封不足。","multi":false},{"id":"C120-Q02","courseId":"C120","type":"多选","stem":"活接漏水处置，正确的判据有？","options":{"A":"生料带方向反了也能密封","B":"拆开看垫片是否压扁、发硬、有缺口","C":"活接螺母拧紧后仍有“渗汗”，应换垫片","D":"不死拧丝口，垫片选同规格EPDM"},"answer":["B","C","D"],"explain":"A错误：生料带方向反会漏；B、C、D为活接判据。","multi":true},{"id":"C120-Q03","courseId":"C120","type":"辨析题","stem":"“补芯安装时外丝朝小径、内丝朝大径。”这种说法是否正确？","options":{"A":"正确，这样装得进去","B":"正确，方向无所谓","C":"错误，补芯只有外丝","D":"错误，补芯外丝朝大径、内丝朝小径"},"answer":["D"],"explain":"补芯外丝朝大径拧进大管件，内丝朝小径接纳小管。A、B、C方向描述均错误。","multi":false},{"id":"C121-Q01","courseId":"C121","type":"单选","stem":"表前阀关到底后，判断“关不严”最直接的现场信号是？","options":{"A":"用手摸阀体温度","B":"看阀门颜色","C":"下游仍能听到持续过水声，或表后放水时水表仍走字","D":"凭感觉"},"answer":["C"],"explain":"表前阀关不严看下游过水声和水表走字。A、B、D均不是有效判据。","multi":false},{"id":"C121-Q02","courseId":"C121","type":"多选","stem":"小区表组抢修正确的有？","options":{"A":"表前阀关不严可先多关几次，不解决找上游","B":"换表前不用看表号","C":"水表不能倒装，按箭头方向安装","D":"水表玻璃破可带压直接拆"},"answer":["A","C"],"explain":"B错误：换表前要拍照读数和表号；D必须先关阀泄压；A、C为正确判据。","multi":true},{"id":"C121-Q03","courseId":"C121","type":"排序题","stem":"换表顺序是：①关表前阀 ②泄压拍照 ③拆装水表 ④慢开阀试压","options":{"A":"①→②→③→④","B":"②→①→③→④","C":"③→①→②→④","D":"①→③→②→④"},"answer":["A"],"explain":"正确：关阀→泄压拍照→拆装→慢开试压。③在②之前会丢读数信息。","multi":false},{"id":"C122-Q01","courseId":"C122","type":"单选","stem":"哈夫节安装前试扣，左右晃动间隙大于2mm，说明什么？","options":{"A":"规格过松，应换小一档","B":"正常，直接紧固","C":"管径偏小","D":"胶垫太厚"},"answer":["A"],"explain":"晃动间隙>2mm=规格过松，强行紧固会把胶圈挤出密封槽。B、C、D均误判。","multi":false},{"id":"C122-Q02","courseId":"C122","type":"多选","stem":"哈夫节安装中，胶垫偏位和失败信号的正确判据有？","options":{"A":"螺栓先手动预紧到胶圈刚接触管壁","B":"最终目测两侧胶圈溢出量一致","C":"一次拧死一颗螺栓","D":"胶垫从壳体边缘被挤出、翻卷，立即停手泄压重装"},"answer":["A","B","D"],"explain":"C错误：一次拧死会导致胶垫偏位；A、B、D为正确判据。","multi":true},{"id":"C122-Q03","courseId":"C122","type":"排序题","stem":"哈夫节安装的合理顺序是：①试扣判间隙 ②清面+纵向裂缝打止裂孔 ③胶垫定位 ④对角分次紧固 ⑤先低压核验","options":{"A":"②→①→③→④→⑤","B":"③→①→②→④→⑤","C":"①→②→③→④→⑤","D":"①→③→②→④→⑤"},"answer":["C"],"explain":"正确：试扣→清面/止裂→胶垫定位→对角紧固→低压核验。跳试扣会拿错规格。","multi":false},{"id":"C123-Q01","courseId":"C123","type":"单选","stem":"连接器胶圈入槽后，判断是否脱位最直接的判据是？","options":{"A":"用手摸一下","B":"目测颜色","C":"不用检查","D":"用金属直尺沿承口一周检测胶圈深度是否一致"},"answer":["D"],"explain":"胶圈入槽判据：金属直尺周圈深度一致=到位；不一致=脱位重装。A、B、C均不可靠。","multi":false},{"id":"C123-Q02","courseId":"C123","type":"多选","stem":"多功能法兰连接器安装正确的有？","options":{"A":"承口毛刺、锈蚀清干净","B":"单边一次拧死","C":"胶圈不扭曲入槽，涂专用润滑剂","D":"锁紧环周圈间隙一致"},"answer":["A","C","D"],"explain":"B单边紧会挤偏胶圈；A、C、D为连接器判据。","multi":true},{"id":"C123-Q03","courseId":"C123","type":"辨析题","stem":"“连接器安装时，插口插到感觉到底就行，不用划标记。”这种说法是否正确？","options":{"A":"正确，手感最准","B":"正确，连接器有自动到位提示","C":"错误，连接器不需要插到位","D":"错误，应划插入深度标记，插到标记处，不凭感觉"},"answer":["D"],"explain":"插入深度判据：划标记插到标记处。A手感不可靠，B无此提示，C完全错误。","multi":false},{"id":"C124-Q01","courseId":"C124","type":"单选","stem":"冬季冻管解冻，正确的介质温度是？","options":{"A":"沸水直接浇","B":"明火烘烤","C":"不高于60℃的温水，从接头开始","D":"蒸汽直冲"},"answer":["C"],"explain":"解冻判据：温水≤60℃、从接头开始。A沸水损伤管材，B明火烤变形，D蒸汽温度过高。","multi":false},{"id":"C124-Q02","courseId":"C124","type":"多选","stem":"冻胀故障处置正确的有？","options":{"A":"先关阀止水","B":"严禁硬拧冻住的阀门","C":"明火烤化最快","D":"修复后做保温防复冻"},"answer":["A","B","D"],"explain":"C明火烤变形塑料/衬塑，严禁；A、B、D为冻胀判据。","multi":true},{"id":"C124-Q03","courseId":"C124","type":"排序题","stem":"冻胀抢修顺序是：①关阀 ②≤60℃温水解冻 ③查损修复 ④保温+分步复供","options":{"A":"①→②→③→④","B":"②→①→③→④","C":"③→①→②→④","D":"④→②→①→③"},"answer":["A"],"explain":"正确：关阀→解冻→修复→保温复供。②在①前会边解冻边漏水。","multi":false},{"id":"C125-Q01","courseId":"C125","type":"单选","stem":"PE管热熔对接的错边量上限是？","options":{"A":"壁厚的50%","B":"外径的10%","C":"没有要求","D":"壁厚的10%"},"answer":["D"],"explain":"PE热熔判据：错边≤壁厚10%。A过松，B混用外径，C无依据。","multi":false},{"id":"C125-Q02","courseId":"C125","type":"多选","stem":"下列属于典型选型错用的有？","options":{"A":"接口漏用哈夫节硬抱","B":"按管材、漏点、工况核四项后选型","C":"带压强行替代停水修大裂缝","D":"球铁哈夫节套PE管"},"answer":["A","C","D"],"explain":"B是正确流程；A、C、D为典型错用：接口漏硬抱、带压替代停水、材质错配。","multi":true},{"id":"C125-Q03","courseId":"C125","type":"辨析题","stem":"“PE热熔翻边好看，内部就一定融合好了。”这种说法是否正确？","options":{"A":"正确，翻边好就是焊得好","B":"正确，外观是唯一标准","C":"错误，翻边越窄越好","D":"错误，翻边好看不等于内部融合，需看错边、根部宽、无缺陷，必要时做翻边切除检验"},"answer":["D"],"explain":"翻边好看不代表内部融合，要结合错边≤10%、根部宽、无气孔，必要时切除检验。A、B、C均与判据相悖。","multi":false},{"id":"C126-Q01","courseId":"C126","type":"单选","stem":"管道接口持续线状流水，属于哪级渗漏？","options":{"A":"渗水","B":"滴漏","C":"线漏","D":"喷漏"},"answer":["C"],"explain":"渗漏四级：渗水潮湿、滴漏间断、线漏持续线状、喷漏压力喷出。线漏必须整改。","multi":false},{"id":"C126-Q02","courseId":"C126","type":"多选","stem":"关于抢修验收，正确的有？","options":{"A":"外观合格不代表内部无隐性缺陷","B":"通水即合格","C":"常压通水可以替代保压试验","D":"短期复漏应先找根因，不简单紧螺栓"},"answer":["A","D"],"explain":"B、C是典型误区；A、D为验收判据：外观不等于内部、复漏找根因。","multi":true},{"id":"C126-Q03","courseId":"C126","type":"辨析题","stem":"“法兰补紧一次还漏，就应该立刻拆换垫片。”这种说法是否正确？","options":{"A":"正确，一次补紧无效就换","B":"正确，换垫最快","C":"错误，应先确认泄压、对角分遍补紧，持续滴漏且补紧无效才拆换垫片，旧垫残渣必须除净","D":"错误，法兰漏不能换垫片"},"answer":["C"],"explain":"法兰渗漏顺序：先泄压+对角分遍补紧，持续滴漏且补紧无效才换垫；换垫时清残渣、对中。A、B跳过“持续滴漏且无效”条件，D完全错误。","multi":false},{"id":"C127-Q01","courseId":"C127","type":"单选","stem":"机械开挖接近已知管线时，正确的做法是？","options":{"A":"继续快速挖","B":"人工探沟，见管即停","C":"凭图直接挖","D":"先挖开再看"},"answer":["B"],"explain":"开挖前判据：机械开挖前人工探沟，见管即停。A、C、D均易挖破管线。","multi":false},{"id":"C127-Q02","courseId":"C127","type":"多选","stem":"开挖支护降排水的正确做法有？","options":{"A":"坑边堆土不影响支护","B":"深坑按土质支护","C":"用石块直接回填管周","D":"管周30cm人工清挖"},"answer":["B","D"],"explain":"A错误：坑边堆土增加侧压，可能导致支护失效；C错误：石块回填损伤防腐和内衬；B、D为正确判据。","multi":true},{"id":"C127-Q03","courseId":"C127","type":"排序题","stem":"开挖支护的合理顺序是：①探查围挡 ②人工探沟 ③支护降排水 ④管周开挖回填","options":{"A":"①→②→③→④","B":"②→①→③→④","C":"③→①→②→④","D":"④→②→①→③"},"answer":["A"],"explain":"正确：探查围挡→探沟→支护降排水→管周开挖回填。跳探沟直接机械挖风险极高。","multi":false},{"id":"C128-Q01","courseId":"C128","type":"单选","stem":"大口径管道关阀，两阶段操作的现场判据是？","options":{"A":"先关至折点开度，暂停观察压力，剩余缓慢关完，以压力稳定、无明显振动为准","B":"匀速快关到底","C":"直接全关","D":"关一半停住"},"answer":["A"],"explain":"两阶段关阀：折点暂停看压力，折点开度按管网条件定，不套统一值。B匀速快关出水锤，C/D无控压逻辑。","multi":false},{"id":"C128-Q02","courseId":"C128","type":"多选","stem":"关阀止水正确的原则有？","options":{"A":"先近后远、先支后干","B":"多阀协同统一指挥","C":"慢开慢关","D":"各自为战抢速度"},"answer":["A","B","C"],"explain":"D各自为战导致压力骤变和二次爆管；A、B、C为正确原则。","multi":true},{"id":"C128-Q03","courseId":"C128","type":"排序题","stem":"关阀止水合理顺序是：①定位上下游阀 ②先近后远慢关 ③折点暂停监压 ④确认止水","options":{"A":"②→①→③→④","B":"③→①→②→④","C":"①→②→③→④","D":"④→②→①→③"},"answer":["C"],"explain":"正确：定位→先近后远慢关→折点暂停监压→确认止水。不定位直接关会关错阀。","multi":false},{"id":"C129-Q01","courseId":"C129","type":"单选","stem":"关阀时手轮转动但阀杆不跟随（空转），和手轮阻力突然异常增大（发死），正确处置分别是？","options":{"A":"两者都用加力杆硬扳","B":"空转=直接判该阀不可用、转上游阀；发死=不硬扳，填料过紧可逐步松填料压盖螺栓，每次1/4圈","C":"两者都继续反复试关","D":"空转=松填料；发死=转上游阀"},"answer":["B"],"explain":"空转多为阀杆断/脱开，不再反复试关，转上游；发死多为填料过紧/阀杆弯曲/结垢，不硬扳，填料过紧可逐步松1/4圈调整。A、C、D把两种病混为一谈。","multi":false},{"id":"C129-Q02","courseId":"C129","type":"多选","stem":"关阀失败应对正确的有？","options":{"A":"关不严可反复慢关几次","B":"最近阀不可控时逐级找上游","C":"加密阀用专用钥匙","D":"阀杆断用加长杆硬拧"},"answer":["A","B","C"],"explain":"D硬拧会脆断阀杆；A、B、C为正确应对。","multi":true},{"id":"C129-Q03","courseId":"C129","type":"辨析题","stem":"“闸阀手轮阻力突然变大，用加力杆就能拧动。”这种说法是否正确？","options":{"A":"正确，加力杆增加力矩","B":"正确，闸阀不怕大力","C":"错误，闸阀没有手轮","D":"错误，阻力突然增大或“发死”应立即停手，加力杆会使阀杆在应力集中处脆断"},"answer":["D"],"explain":"力矩判断：手轮阻力“发死”立即停手，不靠加力杆征服。A、B把可修变必须换，C描述错误。","multi":false},{"id":"C130-Q01","courseId":"C130","type":"单选","stem":"带压抢修的可带压条件，以下哪项不是必要条件？","options":{"A":"小砂眼或微渗漏","B":"低压工况","C":"使用指定带压器材","D":"大口径断裂"},"answer":["D"],"explain":"可带压四条件：小漏、微漏/低压、指定器材。大口径断裂属于必须停水项。","multi":false},{"id":"C130-Q02","courseId":"C130","type":"多选","stem":"必须停水的条件包括？","options":{"A":"小砂眼微漏低压","B":"大裂缝","C":"断裂","D":"接口失效且高压"},"answer":["B","C","D"],"explain":"A是可评估带压的小漏场景；B、C、D均为必须停水项。","multi":true},{"id":"C130-Q03","courseId":"C130","type":"辨析题","stem":"“带压抢修时，只要动作快，可以拆承压螺栓。”这种说法是否正确？","options":{"A":"正确，快就行","B":"错误，严禁带压拆承压螺栓或密封件，超边界必须停水卸压","C":"正确，小螺栓没关系","D":"错误，带压只能修接口"},"answer":["B"],"explain":"带压红线：严禁带压拆承压螺栓/密封件。A、C严重违章，D曲解边界。","multi":false},{"id":"C131-Q01","courseId":"C131","type":"单选","stem":"复杂工况抢修的通用第一原则是？","options":{"A":"先修复再止水","B":"先止水控险，再排查、修复、分步复水","C":"先复水","D":"先记录"},"answer":["B"],"explain":"复杂工况通用顺序：止水控险→排查核实→修复→分步复水→记录。A先修后止水扩大影响。","multi":false},{"id":"C131-Q02","courseId":"C131","type":"多选","stem":"复杂工况抢修正确的有？","options":{"A":"超出单班组能力先报增援再动手","B":"边干边等增援","C":"现场指定一人统一指挥","D":"次生风险未控不进入修复"},"answer":["A","C","D"],"explain":"B边干边等会延误和混乱；A、C、D为正确判据。","multi":true},{"id":"C131-Q03","courseId":"C131","type":"排序题","stem":"复杂工况抢修顺序是：①止水控险 ②排查核实 ③修复 ④分步复水记录","options":{"A":"②→①→③→④","B":"①→②→③→④","C":"③→①→②→④","D":"④→③→②→①"},"answer":["B"],"explain":"正确：止水→排查→修复→复水记录。②在①前会边漏边查。","multi":false},{"id":"C132-Q01","courseId":"C132","type":"单选","stem":"大口径爆管关阀时，折点开度应如何确定？","options":{"A":"统一用15%","B":"统一用83%","C":"按管网条件确定，文献案例有15%、30%等，不套统一值，以压力稳定、无振动为准","D":"随便关"},"answer":["C"],"explain":"折点开度按管网条件定，文献有15%、30%、83%等不同案例，不能统一套用。A、B把个案当通例。","multi":false},{"id":"C132-Q02","courseId":"C132","type":"多选","stem":"大口径爆管处置正确的有？","options":{"A":"人不站冲坑边","B":"多阀协同统一指挥","C":"不排气直接满压复水","D":"只查爆管点本身"},"answer":["A","B"],"explain":"C不排气直接满压=气阻+水锤；D只查爆管点遗漏周边管段损伤；A、B为正确判据。","multi":true},{"id":"C132-Q03","courseId":"C132","type":"辨析题","stem":"“大口径修复后可以直接满压复水。”这种说法是否正确？","options":{"A":"错误，应先低压充水、高点排气，再逐步升压，不一步满压","B":"正确，越快越好","C":"正确，大口径不怕水锤","D":"错误，只能常压复水"},"answer":["A"],"explain":"分步复水+排气：先低压充水、排气、逐步升压。B、C忽略水锤和气阻风险，D描述错误。","multi":false},{"id":"C133-Q01","courseId":"C133","type":"单选","stem":"老旧薄壁管抱箍紧固时，“手感发虚”的具体含义和正确处置是？","options":{"A":"手感发虚=阻力不随转角增大、反而变轻发软或出现空行程，立即停手，换更大接触面积抱箍或停水切换","B":"手感发虚=阻力变大，继续加力","C":"手感发虚=正常现象，不用管","D":"手感发虚=抱箍太小，换小一档"},"answer":["A"],"explain":"“手感发虚”不是再使点劲，是管壁已被压屈服的信号：阻力变轻/发软/空行程，立即停手。B、C、D均误判。","multi":false},{"id":"C133-Q02","courseId":"C133","type":"多选","stem":"老旧管网连环漏处置正确的有？","options":{"A":"一次全面开挖更换","B":"先修最容易修的","C":"腐蚀严重段不强行带压","D":"优先机械抢修，不轻易动火"},"answer":["C","D"],"explain":"A一次全面开挖影响过大；B应先控最严重漏点，不是最容易修的；C、D为正确判据。","multi":true},{"id":"C133-Q03","courseId":"C133","type":"排序题","stem":"老旧管网分步处置顺序是：①控最重漏点 ②评估管壁 ③机械抢修 ④分批整改观察","options":{"A":"②→①→③→④","B":"③→②→①→④","C":"④→①→②→③","D":"①→②→③→④"},"answer":["D"],"explain":"正确：控最重→评管壁→机械抢修→分批整改观察。②在①前会先研究未控漏。","multi":false},{"id":"C134-Q01","courseId":"C134","type":"单选","stem":"第三方挖破给水管，第一动作应是？","options":{"A":"先拍照留证","B":"先回填","C":"关上游阀止水控险","D":"先找施工方"},"answer":["C"],"explain":"第三方破坏：先关上游阀止水，再核实修复、防二次。A、D把非抢修动作前置，B掩盖漏点。","multi":false},{"id":"C134-Q02","courseId":"C134","type":"多选","stem":"第三方破坏抢修正确的有？","options":{"A":"只修给水管不管周边","B":"查单点还是多点损伤","C":"查周边燃电通信管线连带","D":"按形态选哈夫节/连接器/切换"},"answer":["B","C","D"],"explain":"A遗漏连带损伤；B、C、D为正确判据。","multi":true},{"id":"C134-Q03","courseId":"C134","type":"辨析题","stem":"“第三方挖破管道，应先追责再止水。”这种说法是否正确？","options":{"A":"正确，追责第一","B":"错误，应先关阀止水控险，再修复和防二次破坏","C":"正确，止水不急","D":"错误，不用止水"},"answer":["B"],"explain":"第三方抢修优先级：先止水控险。A、C颠倒优先级，D完全错误。","multi":false},{"id":"C135-Q01","courseId":"C135","type":"单选","stem":"汛期悬空管道临时支撑，正确做法是？","options":{"A":"直接顶在防腐层上","B":"支撑点垫软物，不直接顶防腐层或管身薄弱处","C":"用铁丝吊住","D":"不支撑直接修"},"answer":["B"],"explain":"临时支撑判据：垫软物、不顶防腐层/薄弱处。A伤防腐，C不稳，D悬空受力危险。","multi":false},{"id":"C135-Q02","courseId":"C135","type":"多选","stem":"汛期冲毁抢修正确的有？","options":{"A":"先排查边坡路基风险","B":"人员不站边坡下","C":"先修管再管边坡","D":"边坡先稳再修复管道"},"answer":["A","B","D"],"explain":"C边修边塌；A、B、D为正确判据。","multi":true},{"id":"C135-Q03","courseId":"C135","type":"排序题","stem":"汛期悬空管道处置顺序是：①排查围挡 ②临时支撑 ③边坡防护 ④修复覆土","options":{"A":"①→②→③→④","B":"②→①→③→④","C":"③→①→②→④","D":"④→②→①→③"},"answer":["A"],"explain":"正确：排查围挡→临时支撑→边坡防护→修复覆土。B在③前可能边撑边冲，C在①前缺少安全前提，D在①前缺少排查。","multi":false},{"id":"C136-Q01","courseId":"C136","type":"单选","stem":"钢管法兰渗漏，正确的处置顺序是？","options":{"A":"上来就拆换垫片","B":"带压直接换垫","C":"用胶水糊住","D":"先泄压，对角分遍补紧；持续滴漏且补紧无效，才拆换垫片"},"answer":["D"],"explain":"法兰渗漏顺序：先补紧，无效再换垫。A过度，B违章，C无效。","multi":false},{"id":"C136-Q02","courseId":"C136","type":"多选","stem":"钢管动火补焊前，必须满足的条件和合格标准包括？","options":{"A":"停水、泄压、清管","B":"办动火票、专人监护、配灭火器材","C":"带压直接焊","D":"动火分析合格标准：爆炸下限≥4%时浓度≤0.5%（体积分数），爆炸下限<4%时浓度≤0.2%（体积分数）"},"answer":["A","B","D"],"explain":"C严禁带压动火；A、B、D为动火条件和体积分数口径合格标准。","multi":true},{"id":"C136-Q03","courseId":"C136","type":"辨析题","stem":"“钢管法兰渗漏，只要补紧一次螺栓还漏，就应马上换垫片。”这种说法是否正确？","options":{"A":"错误，应先确认泄压、对角分遍补紧，持续滴漏且补紧无效才换垫，换垫时清残渣、法兰对中","B":"正确，一次补紧无效就换","C":"正确，换垫最快","D":"错误，法兰不漏"},"answer":["A"],"explain":"法兰顺序：补紧→持续滴漏且无效→换垫；换垫清残渣、对中。B跳过持续滴漏且无效条件，C换垫最快不是判据，D完全错误。","multi":false},{"id":"C137-Q01","courseId":"C137","type":"单选","stem":"PE热熔翻边验收，以下哪项是快速判不合格的判据？","options":{"A":"翻边实心圆滑、根部较宽","B":"翻边根部凹槽底部低于管材外表面","C":"翻边下侧无杂质、小孔、扭曲","D":"错边≤壁厚10%"},"answer":["B"],"explain":"翻边判据：根部凹槽低于管外壁即判不合格，割除重焊，不看着还连着放行。A、C、D是合格判据，不是不合格判据。","multi":false},{"id":"C137-Q02","courseId":"C137","type":"多选","stem":"PE热熔冷却期间正确的做法有？","options":{"A":"可以踩踏","B":"不移动、不撬动","C":"不浇水","D":"冷却时间凭摸着不烫判断"},"answer":["B","C"],"explain":"A踩踏等于扰动等于假焊风险；D冷却时间按设备/管材厂家规定，不凭手感；B、C为正确做法。","multi":true},{"id":"C137-Q03","courseId":"C137","type":"排序题","stem":"PE热熔对接顺序是：①铣端面 ②对齐（错边≤10%） ③加热对接 ④冷却检查翻边","options":{"A":"②→①→③→④","B":"①→②→③→④","C":"③→①→②→④","D":"④→③→②→①"},"answer":["B"],"explain":"正确：铣端面→对齐→加热对接→冷却检查。A在①前无法保证端面平行，C在②前未对齐，D顺序完全颠倒。","multi":false},{"id":"C138-Q01","courseId":"C138","type":"单选","stem":"球铁承插接口插到标记环后，还必须做哪一步才算插入到位？","options":{"A":"直接回填","B":"用手推一下感觉","C":"复查与其相邻已安好的第一至第二个接口推入深度，并用金属直尺检查橡胶圈周圈深度一致","D":"目测胶圈颜色"},"answer":["C"],"explain":"插到标记环只是第一步；规范要求复查相邻第一至第二个接口推入深度，并用金属直尺检查橡胶圈周圈深度一致。A、B、D均缺验证步骤。","multi":false},{"id":"C138-Q02","courseId":"C138","type":"多选","stem":"球铁承插接口正确的有？","options":{"A":"T型推入、K型压兰，分清再装","B":"接口漏用哈夫节硬抱","C":"胶圈不扭曲入槽","D":"插口划插入深度标记，插到标记处"},"answer":["A","C","D"],"explain":"B错误：接口漏不硬抱，应换胶圈复位；A、C、D为正确判据。","multi":true},{"id":"C138-Q03","courseId":"C138","type":"辨析题","stem":"“球铁承插接口推进去了，就算安装到位了。”这种说法是否正确？","options":{"A":"正确，推进去就行","B":"正确，胶圈会自己找正","C":"错误，插到标记环只是第一步，还须复查相邻接口并用金属直尺周圈检测深度一致才算到位","D":"错误，球铁接口不用胶圈"},"answer":["C"],"explain":"插入深度加复查：推进去不等于到位，复查相邻接口加尺检周圈一致才算到位。A、B、D忽略验证步骤。","multi":false},{"id":"C139-Q01","courseId":"C139","type":"单选","stem":"断管连接切口的基本要求是？","options":{"A":"越斜越好","B":"切口平齐，并留连接余量","C":"随便切","D":"用手掰"},"answer":["B"],"explain":"切除判据：切口平齐、留连接余量。A、C、D导致密封面贴合不良。","multi":false},{"id":"C139-Q02","courseId":"C139","type":"多选","stem":"断管连接与异材转换正确的有？","options":{"A":"PE用割管机","B":"大口径断管不设支撑","C":"球铁切割后清毛刺","D":"异材转换件压力等级和口径匹配"},"answer":["A","C","D"],"explain":"B错误：大口径不支撑易脱开；A、C、D为正确判据。","multi":true},{"id":"C139-Q03","courseId":"C139","type":"排序题","stem":"断管连接顺序是：①定切除长度 ②断管 ③选连接/转换 ④支撑试压回填","options":{"A":"②→①→③→④","B":"③→①→②→④","C":"④→②→①→③","D":"①→②→③→④"},"answer":["D"],"explain":"正确：定切除→断管→选连接→支撑试压回填。A在①前无法确定切口，B在②前未断管，C在①前未定长度。","multi":false},{"id":"C140-Q01","courseId":"C140","type":"单选","stem":"小区立管漏水影响多户，关阀前首先应？","options":{"A":"直接关立管阀","B":"先开挖","C":"先复水","D":"评估影响户数并提前通知用户"},"answer":["D"],"explain":"多户停水判据：关阀前评估影响户数、提前通知。A未通知易引发投诉，B/C顺序错误。","multi":false},{"id":"C140-Q02","courseId":"C140","type":"多选","stem":"多户停水复水正确的有？","options":{"A":"高点排气","B":"分户慢开阀","C":"一步全开","D":"逐户查水压和出水"},"answer":["A","B","D"],"explain":"C一步全开等于气阻加水锤加跑水；A、B、D为正确判据。","multi":true},{"id":"C140-Q03","courseId":"C140","type":"辨析题","stem":"“多户停水修完，把立管阀全开就行，不用逐户看。”这种说法是否正确？","options":{"A":"正确，全开最快","B":"正确，用户自己会放气","C":"错误，应先高点排气、分户慢开阀，逐户查水压和出水，异常单独处理","D":"错误，立管阀不能开"},"answer":["C"],"explain":"复水排气加分户查压：高点排气、慢开、逐户查。A、B把风险转给用户，D描述错误。","multi":false},{"id":"C141-Q01","courseId":"C141","type":"单选","stem":"分段复水时，正确的升压方式是？","options":{"A":"先低压充水，再逐步升压","B":"直接满压","C":"只开一个阀不管压力","D":"先复水再修"},"answer":["A"],"explain":"分段复水：先低压充水、逐步升压。B满压易水锤，C无监控，D顺序反。","multi":false},{"id":"C141-Q02","courseId":"C141","type":"多选","stem":"通用复水正确的有？","options":{"A":"打开高点排气阀","B":"异常继续开大冲冲","C":"快速满开","D":"异常（渗漏/压力骤降/水质异常）立即暂停"},"answer":["A","D"],"explain":"B/C会扩大故障和出水锤；A、D为正确判据。","multi":true},{"id":"C141-Q03","courseId":"C141","type":"排序题","stem":"通用复水顺序是：①复水前检查 ②低压充水 ③高点排气 ④分步升压观察","options":{"A":"②→①→③→④","B":"③→①→②→④","C":"①→②→③→④","D":"④→②→①→③"},"answer":["C"],"explain":"正确：复水前检查→低压充水→高点排气→分步升压观察。A在①前可能带病复水，B在②前未充水，D顺序完全颠倒。","multi":false},{"id":"C142-Q01","courseId":"C142","type":"单选","stem":"管道第一次冲洗的合格判据是？","options":{"A":"出水清澈就行","B":"只测余氯","C":"浊度小于3NTU，冲洗流速不小于1.0m/s","D":"不用冲洗"},"answer":["C"],"explain":"水质冲洗判据：浊度<3NTU、流速≥1.0m/s。A无量化，B不全面，D违规。","multi":false},{"id":"C142-Q02","courseId":"C142","type":"多选","stem":"关于管道冲洗消毒，正确的有？","options":{"A":"第一次冲洗浊度小于3NTU、流速大于1.0m/s","B":"水质不合格可以先复水再检测","C":"第二次用有效氯不低于20mg/L的清洁水浸泡24h","D":"20mg/L是规定的最低值，地方或企业制度可能更高"},"answer":["A","C","D"],"explain":"B错误：水质不合格不复水；A、C、D为GB 50268-2008冲洗消毒判据，20mg/L是最低值。","multi":true},{"id":"C142-Q03","courseId":"C142","type":"排序题","stem":"水质冲洗消毒顺序是：①第一次冲洗（浊度<3NTU） ②含氯≥20mg/L浸泡24h ③第二次冲洗 ④取样化验合格","options":{"A":"②→①→③→④","B":"③→①→②→④","C":"①→②→③→④","D":"④→③→②→①"},"answer":["C"],"explain":"正确：先冲洗达标→含氯浸泡→再冲洗→化验合格。A在①前杂质未除影响消毒，B在①前未冲洗，D顺序完全颠倒。","multi":false},{"id":"C143-Q01","courseId":"C143","type":"单选","stem":"抢修记录七要素中，不包括以下哪项？","options":{"A":"接报时间","B":"到场时间","C":"使用材料明细","D":"施工人员考勤"},"answer":["D"],"explain":"记录七要素：接报、到场、故障位置、漏点类型程度、材料、处置过程、通水时间。D不属于抢修业务闭环。","multi":false},{"id":"C143-Q02","courseId":"C143","type":"多选","stem":"复盘与工法改进正确的有？","options":{"A":"只问漏点成因、选型是否合适、工法哪里可优化","B":"返工案例找根因","C":"形成高频漏点清单支撑专项治理","D":"复盘写责任判定"},"answer":["A","B","C"],"explain":"D错误：复盘不追责、不写责任判定；A、B、C为正确判据。","multi":true},{"id":"C143-Q03","courseId":"C143","type":"辨析题","stem":"“余料可以自行处理，不用退库。”这种说法是否正确？","options":{"A":"正确，余料不值钱","B":"错误，领用有记录、消耗有统计、余料退库，账实相符","C":"正确，下次还能用","D":"错误，必须直接扔掉"},"answer":["B"],"explain":"材料台账：余料必须退库，账实相符。A、C、D均违反台账管理。","multi":false},{"id":"C144-Q01","courseId":"C144","type":"单选","stem":"多故障并发时，优先级判据是？","options":{"A":"谁先打电话谁先修","B":"平均用力","C":"保重点区域（医院/学校）、影响户数大、风险高的先修","D":"只修大漏不管小漏"},"answer":["C"],"explain":"优先级判据：保重点、户数大、风险高，不平均用力。A、B、D均导致资源错配。","multi":false},{"id":"C144-Q02","courseId":"C144","type":"多选","stem":"多故障并发统筹正确的有？","options":{"A":"重复调派","B":"建统一故障-资源台账","C":"按技能/位置/负载调人","D":"关键机具优先关键故障"},"answer":["B","C","D"],"explain":"A重复调派浪费资源；B、C、D为正确判据。","multi":true},{"id":"C144-Q03","courseId":"C144","type":"辨析题","stem":"“多故障并发时每个点平均派人最公平。”这种说法是否正确？","options":{"A":"正确，公平第一","B":"正确，不用统筹","C":"错误，只修一个","D":"错误，应按风险、影响、重点区域排优先级，资源优先关键故障"},"answer":["D"],"explain":"优先级判据：排优先级，不平均用力。A、B违背统筹原则，C描述错误。","multi":false},{"id":"C145-Q01","courseId":"C145","type":"单选","stem":"工法优化的正确起点是？","options":{"A":"用C143档案数据统计高频漏点，找规律","B":"凭感觉改","C":"只看成本","D":"不演练"},"answer":["A"],"explain":"高频分析：用数据找规律，不凭印象。B、C、D均缺乏数据支撑。","multi":false},{"id":"C145-Q02","courseId":"C145","type":"多选","stem":"预案迭代与知识沉淀正确的有？","options":{"A":"按场景更新预案","B":"预案必须演练验证","C":"案例库、工法卡、口诀化沉淀","D":"预案写完不演练"},"answer":["A","B","C"],"explain":"D不演练的预案等于没更新；A、B、C为正确判据。","multi":true},{"id":"C145-Q03","courseId":"C145","type":"排序题","stem":"工法迭代闭环顺序是：①高频分析 ②工法对比 ③预案更新演练 ④知识沉淀固化","options":{"A":"②→①→③→④","B":"③→①→②→④","C":"④→②→①→③","D":"①→②→③→④"},"answer":["D"],"explain":"正确：先高频分析→工法对比→预案更新演练→知识沉淀固化。A在①前缺数据，B在①前缺分析，C顺序完全颠倒。","multi":false}]};
